  Event_117279_ChoiceDesc1 = {
    Text = "【かつての無邪気な姿を探す】「(Skill.Arg1)」を3枚デッキに加える。"
  },
  Event_117279_Desc = {
    Text = "\n海面から淡い白霧が立ちのぼり、すべてがぼんやりとした霧に包まれる。\n生と死の境界を越え、扉の内と外の隔たりを越え、色あせてしまった遥かな記憶を越えて、あなたは日傘を差した淑女が逆光の中に浮かぶ姿を見る。\n彼女と過ごした時間は、すでに遠く過ぎ去っていた。それは、彼女の繊細でありながら鮮烈に輝く青春そのもののようだった。\n偽りの太陽が昇り、薄い霧が跡形もなく消え去る頃には、彼女の横顔もまた夢の中で揺らめき、儚く虚ろな泡へと変わっていく。そして、あなたに無言の別れを告げる。"
  },
