  Event_118415_Desc = {
    Text = "あなたの応えが「空」をさらに優しくさせた。\nそれはあなたの額にそっと口づけを落とす。\nそして、あなたの額に一輪の波の花が咲いた。"
  },
  Event_118415_Name = {
    Text = "海の抱擁"
  },
  Event_118416_ChoiceDesc1 = {
    Text = "【幻想に溺れる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_118416_ChoiceDesc2 = {
    Text = "【理性を保つ】狂気値が50以上の覚醒体が1人いるごとに、15ブラックスタンプを獲得"
  },
  Event_118416_ChoiceDesc3 = {
    Text = "【強制離脱】3つの刻印の中から1つを獲得"
  },
  Event_118416_Desc = {
    Text = "おそらく長期の戦闘があなたに恍惚を生じさせたのか、あるいは単にあなたの脳が身体を裏切ったのか。\nある種の無重力感があなたの脳裏に現れる。\n一瞬にして、あなたの脳裏は突然万華鏡と化し、絢爛で、色彩豊かで、五色の光彩がきらめく。\n数え切れないインスピレーション、迷想、狂想が脳に押し寄せ、あなたの脳の溝の隅々を占拠する。\nこのままでは、あなたの頭はすぐにこれらの雑多なもので破裂してしまうだろう。"
  },
  Event_118416_Name = {
    Text = "思考の万華鏡"
  },
  Event_118417_ChoiceDesc1 = {
    Text = "【賭けに参加】「(Skill.Arg1)」に感染し、賭けの場に入ります"
  },
  Event_118417_ChoiceDesc2 = {
    Text = "【やはりやめる】25黒章を獲得する"
  },
  Event_118417_Desc = {
    Text = "恍惚の中、あなたの意識は幾重もの霧を突き抜け、未知の空間へと漂い出た。\n二つのサイコロがあなたの前に投げ出されたが、あなたを強制的にここへ連れてきた未知の存在はまだ姿を現さない。\nあなたにはただ、四方八方から響くその存在の混沌とした声だけが聞こえる。\n「帰りたいか？なら一局やろう。」\n「お前の命を賭け金に、運命と駆け引きをしよう。」"
  },
  Event_118417_Name = {
    Text = "運命の賭け"
  },
  Event_118418_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118418_Desc = {
    Text = "超越的な体験は常に短い。それらは音もなく訪れ、突然消え去る。\nだが少なくともあなたの頭はまだここにあり、本当に爆発はしなかった。"
  },
  Event_118418_Name = {
    Text = "思考の万華鏡"
  },
  Event_118419_ChoiceDesc1 = {
    Text = "【離れる】獲得しろがねのつくりもの「(RelicConfig.Arg1)」"
  },
  Event_118419_Desc = {
    Text = "あなたは負けなかった。だが勝ちもしなかった。結果は良くも悪くもない。\n「引き分けか…………」\n未知の存在はため息をついたが、その声に惜しむ気配はなかった。\n「なかなか面白い余興だった」"
  },
  Event_118419_Name = {
    Text = "運命の賭け"
  },
  Event_118420_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118420_Desc = {
    Text = "次第に、あの狂乱の楽音があなたの耳の中で調和し、聖なるものへと変わっていく。\nあなたはついに悟り、なぜそれが「完美聖歌」と呼ばれるのかを理解した。\nなぜなら、それは確かに「完璧無欠」だからだ。"
  },
  Event_118420_Name = {
    Text = "「完美」聖歌"
  },
  Event_118421_ChoiceDesc1 = {
    Text = "【脳を感知】3枚のコマンドカードから1枚を選択して刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_118421_ChoiceDesc2 = {
    Text = "【魂を感知】「(Skill.Arg1)」に感染し、再刻印する。最大2回まで実行可能"
  },
  Event_118421_Desc = {
    Text = "人の最初の牢獄は、自分自身の肉体である。\nこの肉体という牢獄の中で、脳は最後にして最も重要な檻である。\n「ハニー、自分が生きていて、まだ呼吸しているから安全だと思っているの？」\nあなたの脳が魂を裏切る時、あなたはこの世で最も苦しい拷問を味わうことになる。\nそしてその拷問は、一生あなたに付きまとう。"
  },
  Event_118421_Name = {
    Text = "脳内の牢獄"
  },
  Event_118422_ChoiceDesc1 = {
    Text = "【蝶に触れる】2枚のカードを除去"
  },
  Event_118422_ChoiceDesc2 = {
    Text = "【蝶を追い払う】呪いの造物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_118422_ChoiceDesc3 = {
    Text = "【離れる】Arg1黒章を獲得する"
  },
  Event_118422_Desc = {
    Text = "深海には蝶はいない。部屋に囚われた少女が、これらの命を想像したのだ。\nそれらはとても美しく、空中を自由にひらひらと舞っている。\n「もし…………もし私もあの子たちのように、ここから飛び立てたなら…………」\n一匹の蝶がすすり泣きを漏らしたが、その声は無数の羽ばたきの音に、パチパチというタイプの音にかき消され、ほとんど聞こえなかった。"
  },
  Event_118422_Name = {
    Text = "魂は蝶のように舞う"
  },
  Event_118423_ChoiceDesc1 = {
    Text = "【縄を断ち切る】感染「(Skill.Arg1)」、呪われた造物「(RelicConfig.Arg2)」を獲得"
  },
  Event_118423_ChoiceDesc2 = {
    Text = "【彼の縄を解く】感染「(Skill.Arg1)」を2回行い、白銀造物「(RelicConfig.Arg2)」および「(RelicConfig.Arg3)」を獲得"
  },
  Event_118423_ChoiceDesc3 = {
    Text = "【彼に解放を与える】白銀造物「(RelicConfig.Arg1)」を獲得"
  },
  Event_118423_Desc = {
    Text = "「果てしない欲望こそが人を前に進ませる原動力だと言う者がいる。」\n「だが、その欲望が無視できないほど、断ち切れないほど強大になった時、私にはこの自身から生まれた欲望が、私を閉じ込める牢獄と化したとしか感じられない。」\n闇の中から力のない声が聞こえてくる。相手の顔は見えず、縛られた両手だけが見える。\n「これらの欲望は私の恐怖、臆病、希望、苦痛を糧とし、さらに私の欲望を増幅させる。」\nその力のない声が、最後の哀願を発した。\n「すべてを捧げよう！善き人よ、私を救ってくれ…………あるいは解放を与えてくれ…………」"
  },
  Event_118423_Name = {
    Text = "纏縛の欲"
  },
  Event_118424_ChoiceDesc1 = {
    Text = "【脳を感知】3枚のコマンドカードから1枚を選択して刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_118424_Desc = {
    Text = "あなたは自分の脳髄がぴくりと動いたのを感じた。\n「これには何か特別な意味があるのか？」\nあなたは自分に問いかけるが、脳は静寂のままだ。\n自分自身への問いかけが、毎回答えを得られるわけではない。"
  },
  Event_118424_Name = {
    Text = "脳内の牢獄"
  },
  Event_118425_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118425_Desc = {
    Text = "あなたは必死に上へと泳ぎ、ついに水面から飛び出した。\n潮の匂いが混じった空気が肺に流れ込み、まだ本当の危険から逃れていないことを思い知らせる。\nだが分かっている、本当の空はすぐ頭上にあると。\n真実のように、優しい嘘に覆い隠されることは決してない。"
  },
  Event_118425_Name = {
    Text = "海の抱擁"
  },
  Event_118426_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118426_Desc = {
    Text = "あなたがその欲望の縄に触れた刹那、魂の奥底から刺すような痛みが湧き上がった。\nあなたの恐怖、臆病、希望、苦痛がすべて体内から溢れ出し、血にまみれた縄へと変わり、あなたの両手を縛り上げた。\nその時、あの声が悪意に満ちた歓声を上げるのが聞こえた。\n「善き人よ、報酬を受け取るがいい…………もちろん、呪いもな。」"
  },
  Event_118426_Name = {
    Text = "纏縛の欲"
  },
  Event_118427_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118427_Desc = {
    Text = "あなたの触れた手に蝶たちは震えた。\n生まれてから、こんなに優しく扱われたことは一度もなかった。\n蝶たちは戸惑いの感情に支配され、飛ぶことさえ忘れてしまった。\nそして、数え切れない蝶が落下し、無数の翼に隠されていたタイプライターが姿を現した。\nすでに命を失ったその哀れなものは、最後の力を振り絞り、「自由」という二文字を打ち出した。"
  },
  Event_118427_Name = {
    Text = "魂は蝶のように舞う"
  },
  Event_118428_ChoiceDesc1 = {
    Text = "【戦闘準備】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_118428_ChoiceDesc2 = {
    Text = "【声を出して問う】25黒章を獲得する"
  },
  Event_118428_Desc = {
    Text = "星の光が降り注ぐ深海の中で、蹈海者たちは千百年の歳月を潜伏してきた。\n無限の海水は彼らの狂気を見届け、彼らの忍耐を見届け、そして神への最も敬虔な信仰をも見届けた。\n誰も神の偉大なる降臨を阻むことはできない。\n邪魔する者は全て、蹈海者の怒りの中で灰燼と化す。"
  },
  Event_118428_Name = {
    Text = "群星の下の待機"
  },
  Event_118429_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118429_Desc = {
    Text = "あなたは無意識に耳を覆った。\n不思議なことに、魂の奥底からの楽音が消えた。\nもちろん、一時的なものに過ぎないが。"
  },
  Event_118429_Name = {
    Text = "冒涜の琴音"
  },
  Event_118430_ChoiceDesc1 = {
    Text = "【過去を振り返る】3つのうち1つの高等級の刻印を獲得"
  },
  Event_118430_ChoiceDesc2 = {
    Text = "【未来を覗く】ゴールドクリエイション「(RelicConfig.Arg1)」を獲得し、感染「(Skill.Arg2)」"
  },
  Event_118430_ChoiceDesc3 = {
    Text = "【離れる】50のブラックスタンプを獲得"
  },
  Event_118430_Desc = {
    Text = "この世に不変なものなど何もない。\n神母が創り上げた楽園でさえも。\n束の間の刹那、あなたは時空の裂け目から何かを垣間見た。\n過去、現在、未来がひび割れた隙間の中で交錯し、絶えず変化している。\nあなたの好奇の眼差しを待っている。"
  },
  Event_118430_Name = {
    Text = "時空の裂け目"
  },
  Event_118431_ChoiceDesc1 = {
    Text = "【100黒章を獲得】"
  },
  Event_118431_ChoiceDesc2 = {
    Text = "【ランダムな2枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」】"
  },
  Event_118431_Desc = {
    Text = "無形の意志はあなたの選択を受け入れない。もう一度だけ機会を与え、考えを改めさせようとしている――\n気をつけろ、たとえ音楽が無形であっても、命を刈り取ることができる。"
  },
  Event_118431_Name = {
    Text = "「完美」聖歌"
  },
  Event_118432_ChoiceDesc1 = {
    Text = "【ネズミに餌をやる】しろがねのつくりもの「(RelicConfig.Arg1)」を獲得し、1回の症状に感染することを選択する"
  },
  Event_118432_ChoiceDesc2 = {
    Text = "【ネズミを追い払う】3枚のコマンドカードから1枚を選択して刻印を獲得：「(EnchantConfig.Arg1)」、感染「(Skill.Arg2)」"
  },
  Event_118432_ChoiceDesc3 = {
    Text = "【ネズミを無視】25黒章を獲得する"
  },
  Event_118432_Desc = {
    Text = "この船の上のすべてが、輪廻を繰り返している。\n船の上で生きる、忌まわしく汚い毛に覆われた小さな生き物たちも、当然この運命から逃れることはできない。\n何度も何度も繰り返す輪廻の中で、目に映るすべてを食べても、なお満たされない。\n「お腹が…………すく…………」\n群がるネズミたちが病的で耳障りな金切り声を上げる。\n幾度もの輪廻が彼らを飢えに苦しめ、何かを食べなければならない。\n今すぐに！"
  },
  Event_118432_Name = {
    Text = "飢えたネズミの群れ"
  },
  Event_118433_ChoiceDesc1 = {
    Text = "【視線を回避する】ゴールドクリエイション「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_118433_ChoiceDesc2 = {
    Text = "【眼を直視する】ランダムで2体の覚醒体を覚醒させ、2回「(Skill.Arg1)」に感染"
  },
  Event_118433_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_118433_Desc = {
    Text = "空の群星と同じく、深海にも当然多くの眼がある。\nそれらの眼は海底に棲む魚から、冒涜的な鰓類から、そして海洋そのものから来ている。\nしっ、彼らを驚かせてはならない。\n深海の狂気を、驚かせてはならない。"
  },
  Event_118433_Name = {
    Text = "深海の眼"
  },
  Event_118434_ChoiceDesc1 = {
    Text = "【囁きを無視する】"
  },
  Event_118434_ChoiceDesc2 = {
    Text = "【囁きに耳を傾ける】"
  },
  Event_118434_ChoiceDesc3 = {
    Text = "【逆宣伝する】"
  },
  Event_118434_Desc = {
    Text = "「神の寵愛を得たいか？己の存在の意味を知りたいか？」\n耳元にため息が響く。まるで精神病患者の独り言のようでもあり、無形の存在の親密な囁きのようでもある。\n理性と警戒心から、あなたは拒絶の声を上げたが、その声はなおも独り言を続けた。\n「どうか耐心をもって聞いてくれ。あなたが知ることになるのは、世界の運命に関わる真実だ…………」"
  },
  Event_118434_Name = {
    Text = "無形者の布教"
  },
  Event_118435_ChoiceDesc1 = {
    Text = "【脳を感知】3枚のコマンドカードから1枚を選択して刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_118435_ChoiceDesc2 = {
    Text = "【魂を感知】「(Skill.Arg1)」に感染し、再度ランダムに刻印"
  },
  Event_118435_Desc = {
    Text = "頭蓋の中で安全に守られている脳が、あなたにある情報を伝えた。\nこれらの情報が神経伝達物質の変換や生体電流の伝達の中で摩耗を受けたかどうかはわからない。\n唯一確かな事実は、あなたがこの情報を受け取り、肉体の客観的存在の中で、自分の生存を感知したということだ。"
  },
  Event_118435_Name = {
    Text = "脳内の牢獄"
  },
  Event_118436_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_118436_Desc = {
    Text = "「悪くない答えだ。だが残念ながら、正解ではない」\n「では正解は何だ？」\n未知の存在はあなたの問いに答えず、ただ嘲笑を漏らした。\n「誰が運命に正解があると言った？」"
  },
  Event_118436_Name = {
    Text = "運命の賭け"
  },
  Event_118437_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118437_Desc = {
    Text = "「私がそれを断ち切ろうとしなかったとでも思うのか？いいや、欲望に抗えば抗うほど、それはさらに強くなるだけだ！」\n欲望が化した縄がますます締め付けられ、血肉に食い込むのを感じながら、その声は絶望の叫びを上げた。\n「私は永遠にそれらから逃れられない…………永遠に！」"
  },
  Event_118437_Name = {
    Text = "纏縛の欲"
  },
  Event_118438_ChoiceDesc1 = {
    Text = "【歌を聴く】25黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_118438_ChoiceDesc2 = {
    Text = "【放任不管】離れる"
  },
  Event_118438_Desc = {
    Text = "漆黒のカラスが泣いている。\n漆黒のカラスが叫んでいる。\n漆黒のカラスが狂ったように啼いている。\nしかし人々の耳には、ただ歌っているようにしか聞こえない。\n「ああ、なんて気楽な歌声だろう。私もカラスになれたら、人の世の煩わしさから離れられるのに。」"
  },
  Event_118438_Name = {
    Text = "感知されない怨嗟"
  },
  Event_118439_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118439_Desc = {
    Text = "蝶が散り、あなたはようやく下にあるタイプライターをはっきりと見ることができた。\nすでに命を失ったその哀れなものは、最後の力を振り絞り、「離脱」という二文字を打ち出した。"
  },
  Event_118439_Name = {
    Text = "魂は蝶のように舞う"
  },
  Event_118440_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118440_Desc = {
    Text = "過去の映像の中で、毛皮のコートを纏った少女があなたに手を振っている。\n彼女が何を言っているのか聞き取れないが、あなたは少女の笑顔を見た。"
  },
  Event_118440_Name = {
    Text = "時空の裂け目"
  },
  Event_118441_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118441_Desc = {
    Text = "深海は再び漆黒と静寂に包まれた。\nその漆黒と静寂の中で、あなたは再び心臓の鼓動を聞いた。\nその音はあなたの体内から聞こえてくる。\n他者の目には、あなたもまた漆黒の深海を漂う一つの脈打つ心臓に過ぎないのだ。"
  },
  Event_118441_Name = {
    Text = "弱肉強食"
  },
  Event_118442_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118442_Desc = {
    Text = "今回、灰燼と化したのは邪魔者ではなく、蹈海者たちだった。\n群星は無言でこの光景を見下ろしている。過去千百年と同じように、沈黙を保ったまま。"
  },
  Event_118442_Name = {
    Text = "群星の下の待機"
  },
  Event_118443_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118443_Desc = {
    Text = "数の上では優位に立っているにもかかわらず、あの汚いネズミどもの度胸はその体よりも小さかった。\nあなたの強気な態度に怯え、蜘蛛の子を散らすように逃げ去った。"
  },
  Event_118443_Name = {
    Text = "飢えたネズミの群れ"
  },
  Event_118444_ChoiceDesc1 = {
    Text = "【手を差し伸べる】1体の覚醒体をランダムで覚醒させ、「(Skill.Arg1)」に感染させる"
  },
  Event_118444_ChoiceDesc2 = {
    Text = "【黙って傍観する】3選1の刻印を獲得"
  },
  Event_118444_Desc = {
    Text = "一つの脈打つ心臓が漆黒の深海を漂っている。\nそれはおそらく一匹の魚のものか、あるいは鰓を持つ何かの生物のものかもしれない。\nあなたには見えない。唯一見えるのは、絶え間なく脈打つ心臓と、その心臓の後方で徐々に開かれていく血に染まった大きな口だけだ。\n狩るか、狩られるか――それは大自然の法則。\n陸であろうと、海であろうと。"
  },
  Event_118444_Name = {
    Text = "弱肉強食"
  },
  Event_118445_ChoiceDesc1 = {
    Text = "【手を振って追い払う】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_118445_ChoiceDesc2 = {
    Text = "【任由停留】獲得しろがねのつくりもの「(RelicConfig.Arg1)」、感染「(Skill.Arg2)」"
  },
  Event_118445_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_118445_Desc = {
    Text = "暗闇の中からかすかな音が聞こえた。\nそれは一匹の蝶が礼儀正しく尋ねる声だった。\n「あなたの手のひらに止まってもいいですか？」\n「ただ疲れてしまって、少し休みたいだけなの…………」\nそう尋ねながら、蝶は暗闇を越え、あなたの目の前を旋回している。\n漆黒の粘液がその翅から滴り落ちる――それは蝶が暗闇を越えた時、暗闇からの贈り物だった。"
  },
  Event_118445_Name = {
    Text = "蝶の頼み"
  },
  Event_118446_ChoiceDesc1 = {
    Text = "【離れる】「(RelicConfig.Arg1)」ゴールドクリエイションを獲得"
  },
  Event_118446_Desc = {
    Text = "しばしの沈黙の後、何かがあなたの懐に投げ込まれた。\n「それを持って去れ」\n「運命は幸運な者に、常に気前がいい」"
  },
  Event_118446_Name = {
    Text = "運命の賭け"
  },
  Event_118447_ChoiceDesc1 = {
    Text = "【導きに従う】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_118447_ChoiceDesc2 = {
    Text = "【導きを無視する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_118447_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_118447_Desc = {
    Text = "祭典はすでに始まった。\n霊の焔火と血の祝祷の下、数え切れない信徒の魂が航標と化した――\n漂う霊があなたの周りに散らばり、導きの精霊のように光を放ち、あなたの選択を待っている。"
  },
  Event_118447_Name = {
    Text = "魂の航標"
  },
  Event_118448_ChoiceDesc1 = {
    Text = "【離れる】感染「(Skill.Arg1)」、獲得50ブラックスタンプ"
  },
  Event_118448_Desc = {
    Text = "「無知な人間め！」\nその声は苛立ちの不満を漏らしたが、怒りには至らなかった。\nなぜなら、無知な者にもいつか悟りの時が訪れることを知っているからだ。\nただその日の到来を待てばよい。\nそしてその日が来る前に、あなたの身に神の烙印を刻み、あなたの魂の帰属を確かなものとする。"
  },
  Event_118448_Name = {
    Text = "無形者の布教"
  },
  Event_118449_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118449_Desc = {
    Text = "「@2の@3…………」\n膨大な知識が冒涜的な楽音と共に、あなたの脳に流れ込む。\nしかし人間の身体があなたを制限し、宇宙からの学識を理解することができない。\n実に悲しい遺憾である。"
  },
  Event_118449_Name = {
    Text = "冒涜の琴音"
  },
  Event_118450_ChoiceDesc1 = {
    Text = "【離れる】感染「(Skill.Arg1)」、獲得50ブラックスタンプ"
  },
  Event_118450_Desc = {
    Text = "「実は、私も一つ世界の真実を教えたいことがあるんだ…………」\n「世界は二つの知恵あるミートボールの目と、無限の力を象徴するパスタで構成された空飛ぶスパゲッティ・モンスターによって創造された…………」\nあなたは真面目な顔でどこかで聞いた面白い話をでっち上げ、相手の反応を待った。\nしかし長い時間が経っても、向こうは何の反応も示さなかった。\n「はぁ、狂信者にはユーモアが通じないようだ。」\nあなたはため息をつき、立ち去るしかなかった。"
  },
  Event_118450_Name = {
    Text = "無形者の布教"
  },
  Event_118451_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118451_Desc = {
    Text = "あなたの調律は、この乱れた音節を調和させることはできなかった。\nしかし少なくとも、無形の意志はあなたの試みを見届けた。\nこれは良い始まりだ。"
  },
  Event_118451_Name = {
    Text = "「完美」聖歌"
  },
  Event_118452_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118452_Desc = {
    Text = "三つの人影が震えながら、声もなく啜り泣いている。\nそれらの信仰があなたに疑われた。そしてこれは、狂信者が最も容認できない冒涜である。"
  },
  Event_118452_Name = {
    Text = "最良の供物"
  },
  Event_118453_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118453_Desc = {
    Text = "未来の映像の中で、腕足を生やした少女が傲慢にあなたを一瞥し、叱責の声を上げた。\n「神母の真の姿を冒涜することは許されない。」\nそして、映像は消え、時空の裂け目も瞬時に閉じた。あなたはただ先ほどの光景を思い返すのみ。"
  },
  Event_118453_Name = {
    Text = "時空の裂け目"
  },
  Event_118454_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118454_Desc = {
    Text = "あなたは蹈海者を振り切り、前方へと駆け続けた。\nあなたの頭上で、群星は静かに輝いている。過去千百年と同じように。"
  },
  Event_118454_Name = {
    Text = "群星の下の待機"
  },
  Event_118455_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118455_Desc = {
    Text = "未知の存在はあなたを引き止めなかった。\n「いつか、お前はまた戻ってくる」\n「誰も、運命を拒むことはできない」"
  },
  Event_118455_Name = {
    Text = "運命の賭け"
  },
  Event_118456_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118456_Desc = {
    Text = "手際の良い動作の下、その両手は力なく垂れ下がった。\nだがあなたは、相手の最後の溜息を聞き逃さなかった。\n彼はついに、自身の果てしない欲望から、真に解放されたのだ。"
  },
  Event_118456_Name = {
    Text = "纏縛の欲"
  },
  Event_118457_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118457_Desc = {
    Text = "感知されないことは、この世の必然の宿命。\n誰も他の生命に完全に共感することはできない。"
  },
  Event_118457_Name = {
    Text = "感知されない怨嗟"
  },
  Event_118458_ChoiceDesc1 = {
    Text = "【歌を聴く】35黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_118458_ChoiceDesc2 = {
    Text = "【放任不管】離れる"
  },
  Event_118458_Desc = {
    Text = "漆黒のカラスが泣いている。\n漆黒のカラスが叫んでいる。\n漆黒のカラスが狂ったように啼いている。\nしかし人々の耳には、ただ歌っているようにしか聞こえない。\n「ああ、なんて気楽な歌声だろう。私もカラスになれたら、人の世の煩わしさから離れられるのに。」"
  },
  Event_118458_Name = {
    Text = "感知されない怨嗟"
  },
  Event_118459_ChoiceDesc1 = {
    Text = "【耳を傾けて】獲得: しろがねのつくりもの「(RelicConfig.Arg1)」、感染「(Skill.Arg2)」"
  },
  Event_118459_ChoiceDesc2 = {
    Text = "【耳を塞ぐ】3選1の刻印を獲得"
  },
  Event_118459_Desc = {
    Text = "無形の狂乱の中で、あなたはピアノを見たような気がした。\n形の見えない一対の手が、この無形の鍵盤の上で跳ね、冒涜的な楽音を奏でている。\n不気味な音楽があなたの魂の奥底から響き、血管という回路を通じて、震える脳に直接届く。"
  },
  Event_118459_Name = {
    Text = "冒涜の琴音"
  },
  Event_118460_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118460_Desc = {
    Text = "それらのインスピレーション、迷想、狂想が混ざり合い、この世で最も絢爛な色彩に調和される。\nあなたは空間が自分の体内で折り畳まれ、時間が自分の意志に従って旋回するのを見る。\nこの瞬間、あなたは時空を洞察し、全能であり、全知である。\nもちろん、あなたは代償も払った。"
  },
  Event_118460_Name = {
    Text = "思考の万華鏡"
  },
  Event_118461_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118461_Desc = {
    Text = "混沌の魂が鋭い嚎哭であなたに前路を示す。\nそれは安全な道なのか？あなたにはわからない。\nあなたに唯一残された選択は、ただ前に進み続けることだけだ。"
  },
  Event_118461_Name = {
    Text = "魂の航標"
  },
  Event_118462_ChoiceDesc1 = {
    Text = "【歌を聴く】４０黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_118462_ChoiceDesc2 = {
    Text = "【無視】25黒章を獲得し、離れる"
  },
  Event_118462_Desc = {
    Text = "漆黒のカラスが泣いている。\n漆黒のカラスが叫んでいる。\n漆黒のカラスが狂ったように啼いている。\nしかし人々の耳には、ただ歌っているようにしか聞こえない。\n「ああ、なんて気楽な歌声だろう。私もカラスになれたら、人の世の煩わしさから離れられるのに。」"
  },
  Event_118462_Name = {
    Text = "感知されない怨嗟"
  },
  Event_118463_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118463_Desc = {
    Text = "混沌の魂が哀怨のため息を漏らした。\nそれは次第に消散していったが、その哀怨のため息は実体を持つかのように、あなたの心臓に落ちた。\nドクン、ドクン、あなたの心拍が祭典の楽音と同じリズムで鳴り響く。"
  },
  Event_118463_Name = {
    Text = "魂の航標"
  },
  Event_118464_ChoiceDesc1 = {
    Text = "【離れる】獲得しろがねのつくりもの「(RelicConfig.Arg1)」"
  },
  Event_118464_Desc = {
    Text = "「ああ、ああ、なんと敬虔な子羊だろう！」\nその声は感嘆し、賞賛の歓喜に満ちていた。\n「我が主が目覚めし時、お前のような子羊はきっとあの崇高にして偉大なる神国に居場所を見つけることができるだろう…………」"
  },
  Event_118464_Name = {
    Text = "無形者の布教"
  },
  Event_118465_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118465_Desc = {
    Text = "「空」はあなたのわがままを包み込む。\nいつの日か、迷子の子供は母の腕に帰るだろう。\nなぜなら、あなたには逃げ場がないのだから。"
  },
  Event_118465_Name = {
    Text = "海の抱擁"
  },
  Event_118466_ChoiceDesc1 = {
    Text = "【抱擁を受け入れる】しろがねのつくりもの「(RelicConfig.Arg1)」を手に入れ、「(Skill.Arg2)」に感染する"
  },
  Event_118466_ChoiceDesc2 = {
    Text = "【抱擁を拒む】しろがねのつくりもの「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_118466_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_118466_Desc = {
    Text = "世界があなたの目の前で傾く。\nこの瞬間、あなたを取り囲む深海こそが「空」である。\n溺死寸前の苦痛の中、この深い青の「空」が優しく近づき、あなたを抱きしめようとする。\nそれは裁かず、ただ与えるのみ。"
  },
  Event_118466_Name = {
    Text = "海の抱擁"
  },
  Event_118467_ChoiceDesc1 = {
    Text = "【叱りつける】呪いの造物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_118467_ChoiceDesc2 = {
    Text = "【それらに応える】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_118467_ChoiceDesc3 = {
    Text = "【無視】50黒章を獲得るる"
  },
  Event_118467_Desc = {
    Text = "三つの形のぼやけた魂があなたの行く手を遮った。\n一つの人影が敬虔にあなたに礼をし、血を賜るよう懇願する。あなたの流れる血液は、神に捧げる最良の供物だと。\n一つの人影が冷淡にあなたに刃を向け、あなたの血肉を切り取ろうとする。変異していない人肉は、きっと神の寵愛を得られるだろうと。\n最後の一つは無言であなたを見つめ、自らの命を奪ってほしいと願う。それこそが最も敬虔な信仰の証だと。"
  },
  Event_118467_Name = {
    Text = "最良の供物"
  },
  Event_118468_ChoiceDesc1 = {
    Text = "【歌を聴く】30黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_118468_ChoiceDesc2 = {
    Text = "【放任不管】離れる"
  },
  Event_118468_Desc = {
    Text = "漆黒のカラスが泣いている。\n漆黒のカラスが叫んでいる。\n漆黒のカラスが狂ったように啼いている。\nしかし人々の耳には、ただ歌っているようにしか聞こえない。\n「ああ、なんて気楽な歌声だろう。私もカラスになれたら、人の世の煩わしさから離れられるのに。」"
  },
  Event_118468_Name = {
    Text = "感知されない怨嗟"
  },
  Event_118469_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_118469_ChoiceDesc2 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_118469_ChoiceDesc3 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_118469_Desc = {
    Text = "「いいや！こんなものはいらない！もっと…………美味しいものが欲しい。」\n「それは…………お前の血肉だ！」\n群がるネズミたちが金切り声を上げ、あなたに押し寄せてくる。\nどうやら溢れる善意が、時にかえって災いを招くこともあるようだ。"
  },
  Event_118469_Name = {
    Text = "飢えたネズミの群れ"
  },
  Event_118470_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118470_Desc = {
    Text = "あなたの敬意がそれらの眼の好感を勝ち取った。\n消える前に、それらは湧き上がる海水を通して、あなたに贈り物を送った。\nそれは深海があなたを馴らした証である。"
  },
  Event_118470_Name = {
    Text = "深海の眼"
  },
  Event_118471_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118471_Desc = {
    Text = "あなたの隠すことのない視線の下で、深海がゆっくりと目覚める。\n海水が狂乱のようにあなたの周囲で湧き上がり、名状しがたい譫言をもたらす。\n深海の怒りを感じるがいい、これは祝福であり、呪いでもある。"
  },
  Event_118471_Name = {
    Text = "深海の眼"
  },
  Event_118472_ChoiceDesc1 = {
    Text = "【歌を聴く】20黒章を獲得、「(Skill.Arg2)」に感染する"
  },
  Event_118472_ChoiceDesc2 = {
    Text = "【放任不管】離れる"
  },
  Event_118472_Desc = {
    Text = "漆黒のカラスが泣いている。\n漆黒のカラスが叫んでいる。\n漆黒のカラスが狂ったように啼いている。\nしかし人々の耳には、ただ歌っているようにしか聞こえない。\n「ああ、なんて気楽な歌声だろう。私もカラスになれたら、人の世の煩わしさから離れられるのに。」"
  },
  Event_118472_Name = {
    Text = "感知されない怨嗟"
  },
  Event_118473_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118473_Desc = {
    Text = "血、肉片、生命。\n供物はすでに整えられた。あとは静かに神の饗宴を待つだけだ。"
  },
  Event_118473_Name = {
    Text = "最良の供物"
  },
  Event_118474_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118474_Desc = {
    Text = "蝶はあなたの拒絶を理解した。\n漆黒の粘液にまみれた翅が再び震え、暗闇の中をふらふらと飛んでいく。\nやがて、暗闇が再び蝶を飲み込んだ。今度は、もう抗う力は残っていなかった。"
  },
  Event_118474_Name = {
    Text = "蝶の頼み"
  },
  Event_118475_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118475_Desc = {
    Text = "蝶はあなたの手のひらに降り立った。共に落ちてきたのは、あの色鮮やかな翅の上の漆黒の粘液。\nあなたのため息の中で、色鮮やかな翅は次第に溶け、漆黒の粘液と混ざり合い、未知の混沌とした形になった。\nこの蝶はもう二度と暗闇を経験しなくていい。\nあなたの手のひらの中で安らかに眠っている。"
  },
  Event_118475_Name = {
    Text = "蝶の頼み"
  },
  Event_118477_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118477_Desc = {
    Text = "声を枯らしたカラスはついに目を閉じた。\n誰にも知られず、感知されない怨恨の中で、最後の息を飲み込み、黒い濃厚な液体の水たまりと化した。"
  },
  Event_118477_Name = {
    Text = "感知されない怨嗟"
  },
  Event_118478_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118478_Desc = {
    Text = "「ありがとう…………」\n脈打つ心臓は嬉しそうに遠くへ駆けていった。\nほどなくして、漆黒の深海から血肉を咀嚼する音が聞こえてきた。"
  },
  Event_118478_Name = {
    Text = "弱肉強食"
  },
  Event_118479_ChoiceDesc1 = {
    Text = "【招待を受ける】「(Skill.Arg1)」に感染し、呪いの造物–「(RelicConfig.Arg2)」を獲得"
  },
  Event_118479_ChoiceDesc2 = {
    Text = "【招待を断る】1つの造物を破壊し、1つの報酬を得る"
  },
  Event_118479_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_118479_Desc = {
    Text = "「この船の上のすべては、この絶えず崩壊し再起動する循環の楽園の一部とならねばならない。」\n狂乱の楽音があなたの脳裏に響く。それは無形の意志からあなたへの啓示だった。\n「ここには嘆きも、悲しみもない。あるのは純潔な聖楽と永遠の笑い声だけ。」\n「楽園に加わり、この完美なる楽音の一部となる気はあるか？」"
  },
  Event_118479_Name = {
    Text = "「完美」聖歌"
  },
  Event_118480_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_118480_Desc = {
    Text = "あなたの沈黙の中で、魂たちは音もなく消散した。\n信仰を理解しない者には、時間を費やす価値がない。"
  },
  Event_118480_Name = {
    Text = "最良の供物"
  },
  Event_123616_ChoiceDesc1 = {
    Text = "【標準遺物を受け取る】"
  },
  Event_123616_Desc = {
    Text = "すべての覚醒体の狂気を100に設定し、キーチャージを1000に設定し、ライフを80％に設定します。\n 2枚のカードを除去し、3枚の症状カードを置きます。\n 猩紅炉を12.5％に設定し、4枚のカードを超次元空間に置きます。\n 標準遺物パックを獲得します。"
  },
  Event_123616_Name = {
    Text = "ワンクリックで道中スキップ"
  },
  Event_125696_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125696_Desc = {
    Text = "理由なき怒りに駆り立てられ、あなたは手を上げて力いっぱい追い払う。謎の中に長く留まりすぎた。おそらくあなたが渇望していたのは痛快な戦いであり、あるいはただ終焉を望んでいただけかもしれない…………\nしかし鴉群は何もしなかった。あなたの視線の下、深淵は消え去った。\n鴉群は舞台の果てに消えていった――あなたがこれから向かう場所へ。"
  },
  Event_125696_Name = {
    Text = "群鴉の深淵"
  },
  Event_125697_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125697_Desc = {
    Text = "「臆病者。」女の声は笑いに含まれる嘲りを少しも隠さなかった。\n「行きなさい、できるだけ遠くへ。」"
  },
  Event_125697_Name = {
    Text = "運命の錠"
  },
  Event_125698_ChoiceDesc1 = {
    Text = "【追い払う】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_125698_ChoiceDesc2 = {
    Text = "【耳を傾ける】白銀の造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」に感染"
  },
  Event_125698_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_125698_Desc = {
    Text = "暗闇の中からかすかな音が聞こえた。一匹の蝶があなたの掌に舞い降りる。あなたはこの蝶を覚えている。\n「アラクネさん…………あなたは一度も私たちを見捨てたことはありませんよね？」\n蝶の美しい模様が、あなたの傍らにいる人を見つめている。"
  },
  Event_125698_Name = {
    Text = "蝶の余生"
  },
  Event_125699_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125699_Desc = {
    Text = "その音と文字が蜂の群れのように頭の中に入り込んでくる。あなたは息を潜め、無用な雑念を頭から追い払った。\n無視することは読むことよりもはるかに難しい。だが、あなたはやり遂げた。"
  },
  Event_125699_Name = {
    Text = "次元電報"
  },
  Event_125700_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125700_Desc = {
    Text = "あれは敵が作り出した幻覚だ！\nあなたは首を振って意識を取り戻し、再び手の中の銀の鍵を握り締めた。"
  },
  Event_125700_Name = {
    Text = "酒に映る影"
  },
  Event_125701_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125701_Desc = {
    Text = "あなたはあの瞳を真剣に見つめ、懸命に注視し、耳を傾けた。あなたは役者の内面に入り込み、彼が経験している苦痛を感じ取ろうとした。\n近づく、近づく。あなたは彼の身体を通り抜け、彼の魂に触れた…………\nあなたはハッと目を開け、自分が舞台の中央に立っていることに気づいた。涙が指先を伝って流れ落ちていた。\nそれはあなたが観客に捧げた告白だった。"
  },
  Event_125701_Name = {
    Text = "役者の告白"
  },
  Event_125702_ChoiceDesc1 = {
    Text = "【彼女と語り合う】指令カードを1枚削除し、Arg1の黒印を獲得"
  },
  Event_125702_ChoiceDesc2 = {
    Text = "【沈黙を守る】"
  },
  Event_125702_Desc = {
    Text = "「楽しい結末は確かに美しい。でもその偽りの歓びは、決して観客の心には届かない…………」\n劇作者は目を閉じて沈思した。この結末には満足していないようだ。"
  },
  Event_125702_Name = {
    Text = "劇作の結末"
  },
  Event_125703_ChoiceDesc1 = {
    Text = "【歌を聴く】35黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_125703_ChoiceDesc2 = {
    Text = "【無視】離れる"
  },
  Event_125703_Desc = {
    Text = "「きしり――きしり――運命の女神が紡ぎ車を回す。\nきしり――きしり――運命の糸が彼女の手に集まる。」"
  },
  Event_125703_Name = {
    Text = "最後の予言"
  },
  Event_125704_ChoiceDesc1 = {
    Text = "【自分自身】デッキからランダムに3枚の指令カードを引き、1枚を選んで複製する"
  },
  Event_125704_ChoiceDesc2 = {
    Text = "【ウィリアム】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_125704_ChoiceDesc3 = {
    Text = "【誰でもない】黒印を25獲得する"
  },
  Event_125704_Desc = {
    Text = "酔ってなどいないと確信していたが、酒を覗き込んだ瞬間、静寂な湖に落ちていった。\n優雅なグラスに一つの影が映る――あれは誰だ？"
  },
  Event_125704_Name = {
    Text = "酒に映る影"
  },
  Event_125705_ChoiceDesc1 = {
    Text = "【聴く】白銀の造物【(RelicConfig.Arg1)】を獲得"
  },
  Event_125705_ChoiceDesc2 = {
    Text = "【追い払う】黒印を75獲得、【(Skill.Arg2)】に感染"
  },
  Event_125705_Desc = {
    Text = "体内のプラズミドの力に近づこうとしたとき、一群のカラスが脳裏に現れ、乱れた精神空間の中を旋回した。\n\nカラスの群れが周囲を取り囲み、深淵が頭上で逆さまに渦を巻いた。\n十万羽のカラスが一斉に鳴き叫び、嘲笑うような予言のごとく響き渡った。"
  },
  Event_125705_Name = {
    Text = "群鴉の深淵"
  },
  Event_125706_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125706_Desc = {
    Text = "あなたとアラクネは傍らで崩壊する運命を安定させようと試みた。努力の成果はわずかだったが、それで十分だった。稼いだ時間を利用して、あなたたちはネフレアにさらに近づいた。\nあなたがここに来たのは、彼女に解放をもたらすため。"
  },
  Event_125706_Name = {
    Text = "運命の網の幕引き"
  },
  Event_125707_ChoiceDesc1 = {
    Text = "【歌を聴く】20黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_125707_ChoiceDesc2 = {
    Text = "【無視】離れる"
  },
  Event_125707_Desc = {
    Text = "「それらは巨大な網と共に死んだ。音もなく。」"
  },
  Event_125707_Name = {
    Text = "最後の予言"
  },
  Event_125708_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125708_Desc = {
    Text = "それは淵獄に宛てた電報だった。\n「焦らないで、我が子たちよ。牢獄の門はまもなく開かれる。お前たちの自由はもうすぐだ。」"
  },
  Event_125708_Name = {
    Text = "次元電報"
  },
  Event_125709_ChoiceDesc1 = {
    Text = "【追い払う】ランダムな1枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_125709_ChoiceDesc2 = {
    Text = "【傾聴】3枚の指令カードから1枚を選んで刻印を付与：【(EnchantConfig.Arg1)】"
  },
  Event_125709_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_125709_Desc = {
    Text = "一匹の蝶があなたの手にそっと止まった。美しい模様はまるで瞳のように、静かにあなたを見つめている。\nもしかすると、何かを伝えたいのだろうか？"
  },
  Event_125709_Name = {
    Text = "蝶のひと休み"
  },
  Event_125710_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125710_Desc = {
    Text = "二十対の悲しげな瞳があなたを見つめる。カラスは歌を止め、最後の予言を携えて、今にも崩れ落ちそうな網を去っていった。"
  },
  Event_125710_Name = {
    Text = "最後の予言"
  },
  Event_125711_ChoiceDesc1 = {
    Text = "【腰をかがめて身を乗り出す】「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_125711_ChoiceDesc2 = {
    Text = "【確認を諦める】50黒章を獲得する"
  },
  Event_125711_Desc = {
    Text = "街角を曲がった時、質素な映写館が目に入った。ロンディニウムにこんな店があった記憶はない。"
  },
  Event_125711_Name = {
    Text = "記憶映写館"
  },
  Event_125712_ChoiceDesc1 = {
    Text = "【運命を受け入れる】3枚の指令カードから1枚を選んで刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125712_ChoiceDesc2 = {
    Text = "【運命に抗う】【(Skill.Arg1)】に感染、刻印をやり直す、最大2回まで"
  },
  Event_125712_Desc = {
    Text = "「ああ、また会えたわね、あなた。」\nあなたは脳内に響く若い女の声を楽しみ始めている。それは優しく、誘惑的で、まるで虫を捕らえる網のよう。\n「さあ、教えて。あなたは自分の運命を受け入れる？」"
  },
  Event_125712_Name = {
    Text = "宿命の檻"
  },
  Event_125713_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125713_Desc = {
    Text = "「愚かな人間め、お前と親しいとでも思っているのか？」\n黒猫は嫌そうにあなたを一瞥し、背を向けた。\n「ここから去れ。次はこんな愚かなことをするな。」"
  },
  Event_125713_Name = {
    Text = "幻化変形"
  },
  Event_125714_ChoiceDesc1 = {
    Text = "【写真を撮る】3枚の指令カードから1枚を選び、刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125714_ChoiceDesc2 = {
    Text = "【ポーズを変える】【(Skill.Arg1)】に感染し、選択肢1で獲得する刻印を変更する。2回使用可能"
  },
  Event_125714_Desc = {
    Text = "一台のカメラがステージにぽつんと立っている。漆黒のレンズがこちらを見つめ、まるで機械の神が創り出した神秘的な複眼のようだ。\n「この劇場にはもう長いこと観客が来ていなかった…………ようこそ！ようこそ！写真を撮りましょう！完全無料ですよ！」\nカメラは興奮して叫んでいる。誰にも顧みられないこのステージで、それだけが唯一の主役だった。"
  },
  Event_125714_Name = {
    Text = "観客席の残影"
  },
  Event_125715_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125715_Desc = {
    Text = "「運命に疑問を持たない者が、どうして運命の答えを期待できるのかしら？」"
  },
  Event_125715_Name = {
    Text = "運命の錠"
  },
  Event_125716_ChoiceDesc1 = {
    Text = "【打開策を思考】白銀造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」に感染"
  },
  Event_125716_ChoiceDesc2 = {
    Text = "【流れに任せる】黄金造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」、「(Skill.Arg3)」に感染"
  },
  Event_125716_ChoiceDesc3 = {
    Text = "【水面に浮かび上がる】25黒章を獲得する"
  },
  Event_125716_Desc = {
    Text = "新たな舞台、重なり合う二つの人生…………警官から逃れる道中、あなたはアラクネが教えてくれたことを整理していた。\n複雑な思考の中、あなたは静寂の深海へと沈んでいく。"
  },
  Event_125716_Name = {Text = "静寂"},
  Event_125717_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125717_Desc = {
    Text = "蝶はあなたの肩に止まり、耳元に寄ってきた。あなたは真剣に耳を傾けたが、聞こえたのは翅の微かな動きだけ――無音の嘆息のようだった。\nあなたが聴き入る中、あの色鮮やかな翅は次第に溶けていき、蝶はあなたの肩の上で安らかに眠りについた。\nあなたはもう二度と、蝶があなたに伝えようとした言葉を知ることはできない。"
  },
  Event_125717_Name = {
    Text = "蝶の余生"
  },
  Event_125718_ChoiceDesc1 = {
    Text = "【咀嚼】ランダムに1体の覚醒体を目覚めさせ、【(Skill.Arg1)】に感染する"
  },
  Event_125718_ChoiceDesc2 = {
    Text = "【拒否する】3つの中から1つの刻印を獲得"
  },
  Event_125718_Desc = {
    Text = "「お腹が空いたでしょう、親愛なるお客様？」\nねっとりとした声がカウンターの奥から響く。振り返っても、何も見えない。\n「真夜中の仮面バーの軽食も有名ですよ。試してみませんか？」"
  },
  Event_125718_Name = {
    Text = "運命の味"
  },
  Event_125719_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125719_Desc = {
    Text = "書かれた文字を軽々しく読む気にはなれず、精巧な封筒をじっくりと眺めるだけにした。\n封筒の封蝋にはぼんやりとした家紋が刻まれ、美しい飾り文字でこう記されていた：\n「新たに生まれしアラクネお嬢様へ。」\n「忠実なる執事、エドガーより。」"
  },
  Event_125719_Name = {
    Text = "おやすみなさい、エドガーさん"
  },
  Event_125720_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125720_Desc = {
    Text = "「そうですか、わかりました、お姉さま…………」\n「劇作者は決して登場人物の結末を書き換えることはできない。あの悲惨な運命はとうに定められていて、たとえあなたでも、決して変えることはできなかったのですね…………」\n悲しい嗚咽が消えた。劇作者のタイプライターは一匹一匹の蝶となり、がらんとした運命の劇場に散っていき、もう二度とその姿は見えなくなった。"
  },
  Event_125720_Name = {
    Text = "劇作の結末"
  },
  Event_125721_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125721_Desc = {
    Text = "名も知れぬ役者、危険なステップ…………それがどうしたというのか？運命そのものより悪いことなどありはしない。\nあなたは手を伸ばし、舞台に上がった。人形があなたの手を取り、軽快な踊りを踊り始めた。\nあなたは拍手の音を聞いた。"
  },
  Event_125721_Name = {
    Text = "三人の舞"
  },
  Event_125722_ChoiceDesc1 = {
    Text = "【歌を聴く】25黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_125722_ChoiceDesc2 = {
    Text = "【無視】離れる"
  },
  Event_125722_Desc = {
    Text = "「それらは踊る。それらは歌う。ギィ――ギィ――」"
  },
  Event_125722_Name = {
    Text = "最後の予言"
  },
  Event_125723_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125723_Desc = {
    Text = "導き手、戦友、孤独な次元における唯一の仲間。\nあなたたちは共にここの全てを片付け、カダスへ帰還する。あなたはそれを一度も疑ったことがない。"
  },
  Event_125723_Name = {
    Text = "酒に映る影"
  },
  Event_125724_ChoiceDesc1 = {
    Text = "【賭ける】「(Skill.Arg1)」に感染し、賭けに入る"
  },
  Event_125724_ChoiceDesc2 = {
    Text = "【やはりやめる】25黒章を獲得する"
  },
  Event_125724_Desc = {
    Text = "路地の角で、汚れた両手があなたを遮った。\nぼろぼろの服を着た乞食がそっと近づいてきた。その目は、腐肉を見つけたハイエナのように貪欲だった。\n「さあ！一勝負だ！お前が知りたいこと、全部教えてやる！勝ちさえすればな…………」"
  },
  Event_125724_Name = {
    Text = "街角の賭け"
  },
  Event_125725_ChoiceDesc1 = {
    Text = "【無視】指令カードを1枚削除し、黒印を25獲得する"
  },
  Event_125725_ChoiceDesc2 = {
    Text = "【閲読】山札のカードを1枚複製し、【(Skill.Arg1)】に感染する"
  },
  Event_125725_Desc = {
    Text = "カタカタカタ、カタカタカタ…………\nバーの片隅には誰もいない。電信機が軽やかに鳴り響き、まるで美しいピアノ曲のようだ。"
  },
  Event_125725_Name = {
    Text = "次元電報"
  },
  Event_125726_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125726_Desc = {
    Text = "「黙れ、俺は猫だ。お前たちの愚かな話など聞きたくない。」\n黒猫はため息をつき、背を向けた。\n「ここから去れ。次はこんな愚かなことをするな。」"
  },
  Event_125726_Name = {
    Text = "幻化変形"
  },
  Event_125727_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125727_Desc = {
    Text = "彼女の言葉は間違っていないのかもしれない。それがあなただ。あなたの心の奥底に潜む、最も隠された最も汚い考え。\n誰もが利己的であり、あなたは他人が思うほど高潔ではなかった。\nあなたはその卑しい苦痛を味わう。過去はもう過ぎ去ったと知っている。そしてあなたの救済は前方にある。"
  },
  Event_125727_Name = {
    Text = "苦痛の蔓延"
  },
  Event_125728_ChoiceDesc1 = {
    Text = "【彼女と語り合う】指令カードを1枚削除し、Arg1の黒印を獲得"
  },
  Event_125728_ChoiceDesc2 = {
    Text = "【沈黙を守る】"
  },
  Event_125728_Desc = {
    Text = "「壮烈な結末はなんと真実味があることでしょう。でも私たちの現実はすでにこんなにも悲惨なのに、物語の中でさえ、彼女に美しい帰る場所を与えてあげられないのでしょうか…………」\n劇作者は目を閉じて沈思した。この結末には満足していないようだ。"
  },
  Event_125728_Name = {
    Text = "劇作の結末"
  },
  Event_125729_ChoiceDesc1 = {
    Text = "【離れる】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_125729_Desc = {
    Text = "コロコロコロ、サイコロはダイスカップの中で興奮して踊り、力尽きるまで踊り続けた。\n\n「なぜ…………なぜ誰も勝てないんだ！…………」"
  },
  Event_125729_Name = {
    Text = "街角の賭け"
  },
  Event_125730_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125730_Desc = {
    Text = "あなたは精一杯近づき、真剣に耳を傾けた。\n蝶は翅を羽ばたかせ、あなたの掌から飛び立った。\n何も聞こえなかった。"
  },
  Event_125730_Name = {
    Text = "蝶のひと休み"
  },
  Event_125731_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125731_Desc = {
    Text = "あなたが追い払おうとしても、蝶は動じなかった。\nひたむきにあなたの掌を追い続け、最後に腕を振った時、ようやく去ることを選んだ。\n少し後悔した。もしかすると、その言葉に耳を傾けるべきだったのかもしれない。"
  },
  Event_125731_Name = {
    Text = "蝶のひと休み"
  },
  Event_125732_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125732_Desc = {
    Text = "黒い煙が失意に震え、乞食の苦痛の叫びは声が枯れ果てた。\nサイコロと乞食はあなたが一度瞬きした後に消え去った。ボロボロのシルクハットの中に、ゲームの報酬が残されていた。"
  },
  Event_125732_Name = {
    Text = "街角の賭け"
  },
  Event_125733_ChoiceDesc1 = {
    Text = "【狂宴に加わる】「(Skill.Arg1)」に感染、呪いの造物–「(RelicConfig.Arg2)」を獲得"
  },
  Event_125733_ChoiceDesc2 = {
    Text = "【演奏を止める】造物1つを選んで破壊し、報酬1つを獲得"
  },
  Event_125733_ChoiceDesc3 = {
    Text = "【耳を塞ぐ】黒印50を獲得"
  },
  Event_125733_Desc = {
    Text = "「ああ！音楽！偉大な演目に音楽がないなんてありえない！！」\n不協和な交響曲が崩れた劇場に響き渡り、まるで混沌の狂宴のようだ。淵獄から来た役者たちがこの無秩序な頌歌の中で踊り、歓声を上げる――それは彼らの命を繋ぐ音符。"
  },
  Event_125733_Name = {
    Text = "運命の頌歌"
  },
  Event_125734_ChoiceDesc1 = {
    Text = "【100黒章を獲得】"
  },
  Event_125734_ChoiceDesc2 = {
    Text = "【ランダムな2枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」】"
  },
  Event_125734_Desc = {
    Text = "見えざる運命の糸が音符の中で舞い踊り、その雑多な音の中から、君は次第にあの魅惑的な旋律を掴み取った――そう、それこそが運命あるべき音。\n淵獄の棄てられし者たちが君に歓声を上げ、群がり、無秩序な狂宴へと引き込む。\nおめでとう、幸運な観客よ！さあ、役者たちと共に運命にカーテンコールを。"
  },
  Event_125734_Name = {
    Text = "運命の頌歌"
  },
  Event_125735_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125735_Desc = {
    Text = "この音の意味は分からない。だが、止めなければならないことは分かる。\n銀光が狂った刃のように振るわれ、そのリズムは不思議と音符に合致していた。\n気がついた時には、音符はいつの間にか止んでいた。もう何の音も聞こえない。見えるのはただ闇、聞こえるのはただ静寂。\n無秩序な喧騒と絶対の静寂、どちらがより恐ろしいのだろう…………秘密の守り人よ？"
  },
  Event_125735_Name = {
    Text = "運命の頌歌"
  },
  Event_125736_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125736_Desc = {
    Text = "手を伸ばすと、一匹の蝶がそっとあなたの手に止まった。\nそうだ。死、消散、流転…………蝶は繭の中から生まれ、苦痛は芸術の永遠の土壌。\n優れた観客として、これはあなたが理解しなければならない真理だ。"
  },
  Event_125736_Name = {
    Text = "消散の中に咲く"
  },
  Event_125737_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125737_Desc = {
    Text = "これもまたネフレアの何かの企みかもしれない。\n蝶はあなたの言葉を理解し、闇の中にその無音の嘆息が響いた。漆黒の粘液が流れる翅が震え、やがて蝶の重い影は果てしない闇の中に沈んでいった。\nあなたはもう二度と、蝶があなたに伝えようとした言葉を知ることはできない。"
  },
  Event_125737_Name = {
    Text = "蝶の余生"
  },
  Event_125738_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_125738_Desc = {
    Text = "コロコロコロ、サイコロはダイスカップの中で興奮して踊り、力尽きるまで踊り続けた。\n\n「なぜ…………なぜ誰も勝てないんだ！…………」"
  },
  Event_125738_Name = {
    Text = "街角の賭け"
  },
  Event_125739_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125739_Desc = {
    Text = "今、思考を無秩序に巡らせるのは危険だ。あなたは首を振り、急いで水面へと浮上した…………"
  },
  Event_125739_Name = {Text = "静寂"},
  Event_125740_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125740_Desc = {
    Text = "すべての音符に聴衆が必要なわけではない。すべての運命に答えが必要なわけではない。\n君はしっかりと耳を塞ぎ、この喧しい舞台を後にした。\nあの不協和な音の意味は今も気になる。だが、唯一正しい選択をしたと、君は分かっている。"
  },
  Event_125740_Name = {
    Text = "運命の頌歌"
  },
  Event_125741_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125741_Desc = {
    Text = "銀光が幻影を貫き、黒猫たちは黒い粘液の水たまりと化した。\n黒猫に化けて逃れようとしても、あなたの目は欺けない。"
  },
  Event_125741_Name = {
    Text = "幻化変形"
  },
  Event_125742_ChoiceDesc1 = {
    Text = "【運命を受け入れる】3枚の指令カードから1枚を選んで刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125742_Desc = {
    Text = "「誰も本当に運命には逆らえないの、あなた。私たちには最初から選ぶ権利なんてなかった。」\n女の声は寂しげに、遠くなっていく。あなたには分からない――彼女が語りかけたかったのはあなたなのか、それとも別の何かなのか。"
  },
  Event_125742_Name = {
    Text = "宿命の檻"
  },
  Event_125743_ChoiceDesc1 = {
    Text = "【歌を聴く】30黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_125743_ChoiceDesc2 = {
    Text = "【無視】離れる"
  },
  Event_125743_Desc = {
    Text = "「人形たちが列をなして入場し、運命の巨大な網に足を踏み入れる。」"
  },
  Event_125743_Name = {
    Text = "最後の予言"
  },
  Event_125744_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125744_Desc = {
    Text = "あなたは頭を上げ、渦流のような深淵を仰ぎ見て、鴉群の神託に耳を傾けようとした。\nしかし鴉群は何も語らなかった。あなたの視線の下、深淵は消え去った。\n鴉群は舞台の果てに消えていった――あなたがこれから向かう場所へ。"
  },
  Event_125744_Name = {
    Text = "群鴉の深淵"
  },
  Event_125745_ChoiceDesc1 = {
    Text = "【蝶に賛同する】カードを2枚削除する"
  },
  Event_125745_ChoiceDesc2 = {
    Text = "【蝶に反対する】呪いの造物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_125745_ChoiceDesc3 = {
    Text = "【離れる】Arg1黒章を獲得する"
  },
  Event_125745_Desc = {
    Text = "舞台の幕が風に揺れ、屍から滴り落ちる黒い粘液の中に、蝶の群れが見えた。\n「真の芸術は、常に消散の中に咲くもの…………そうでしょう、秘密の守り人？」\n舞い手の屍があなたに微笑みかけている。蝶が羽ばたく音が聞こえる。"
  },
  Event_125745_Name = {
    Text = "消散の中に咲く"
  },
  Event_125746_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125746_Desc = {
    Text = "詭弁があなたを惑わすことは決してない。自分がどんな道を歩んでいるのか、終着点がどこにあるのか、あなたは明確に知っている。\n荊棘が体内で消散する。あなたはいつものように道を歩み始める。"
  },
  Event_125746_Name = {
    Text = "苦痛の蔓延"
  },
  Event_125747_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125747_Desc = {
    Text = "あなたは振り返り、背後のあの目を忘れようとした。しかし、体がいつものように思い通りに動かないことに気づいた。\nあなたは知っている。あの凝視する眼差しから、決して逃れることはできないと。"
  },
  Event_125747_Name = {Text = "観客"},
  Event_125748_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125748_Desc = {
    Text = "敬意からか畏れからか、軽々しく触れる気にはなれず、封筒を元の場所に戻した。立ち去ろうとしたその時、封筒の奥の闇から、濁りながらも穏やかな声が響いた。\n「覚えていてくださり、ありがとうございます、アラクネお嬢様…………」"
  },
  Event_125748_Name = {
    Text = "おやすみなさい、エドガーさん"
  },
  Event_125749_ChoiceDesc1 = {
    Text = "【守護の力】白銀造物【(RelicConfig.Arg1)】を獲得"
  },
  Event_125749_ChoiceDesc2 = {
    Text = "【逃避の自由】ランダムなカード1枚が刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125749_ChoiceDesc3 = {
    Text = "【回答を拒否】黒印を50獲得"
  },
  Event_125749_Desc = {
    Text = "真夜中の仮面舞踏会の酒精があなたの頭に忍び込み、鎖のようにあなたを縛りつける。冷たい鎖を辿るように、若い女性の声が脳裏に響き渡る。\n「教えて、あなた。あなたが望む運命とは、一体何なの？」"
  },
  Event_125749_Name = {
    Text = "運命の錠"
  },
  Event_125750_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125750_Desc = {
    Text = "どんなに複雑な事柄であっても、あなたたちが解決しなければならない。\nますます重くなる負担を感じると同時に、新たな力も感じ取った。"
  },
  Event_125750_Name = {Text = "静寂"},
  Event_125751_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125751_Desc = {
    Text = "名も知れぬ役者、危険なステップ。そう、逃げることが一番安全だ。\nあなたは振り返って走り出し、劇場の幕を開けた。すると、あなたは舞台の上に立っていた。人形があなたの手を取り、軽快な踊りを踊り始めた。\n運命の舞台に、選択肢などない。"
  },
  Event_125751_Name = {
    Text = "三人の舞"
  },
  Event_125752_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125752_Desc = {
    Text = "今は映画を観に行っている場合ではない。"
  },
  Event_125752_Name = {
    Text = "記憶映写館"
  },
  Event_125753_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125753_Desc = {
    Text = "道中の危険はあなたの頭に少しも入ってこなかった。あなたは傍らで崩壊する運命を通り過ぎ、ネフレアにさらに近づいた。\nあなたがここに来たのは、彼女に解放をもたらすため。"
  },
  Event_125753_Name = {
    Text = "運命の網の幕引き"
  },
  Event_125754_ChoiceDesc1 = {
    Text = "【封筒を読む】黄金の造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」に感染"
  },
  Event_125754_ChoiceDesc2 = {
    Text = "【手紙を読む】指令カード3枚から1枚を選んで刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125754_ChoiceDesc3 = {
    Text = "【元の場所に戻す】50黒章を獲得する"
  },
  Event_125754_Desc = {
    Text = "君たちの動きが密集した蜘蛛の巣を引き裂き、古びた手紙が一通、蜘蛛の巣から落ちてきた。\nその重みは、薄い紙切れとは比べものにならない。"
  },
  Event_125754_Name = {
    Text = "おやすみなさい、エドガーさん"
  },
  Event_125755_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125755_Desc = {
    Text = "カラスの目から涙がこぼれ落ちる。カラスの口元から鮮血が流れる。カラスは全ての命を尽くし、あなたに最後の予言を歌い上げた。"
  },
  Event_125755_Name = {
    Text = "最後の予言"
  },
  Event_125756_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125756_Desc = {
    Text = "「ふふ…………あはははは！」\n「いかがですか、お客様？運命の味、きっと狂おしいほど恋しくなりますよ…………」"
  },
  Event_125756_Name = {
    Text = "運命の味"
  },
  Event_125757_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125757_Desc = {
    Text = "「つまらない。」女の声が気だるげにあくびをした。\n「その力を持って、クラブで格闘でもしてきなさい。」"
  },
  Event_125757_Name = {
    Text = "運命の錠"
  },
  Event_125758_ChoiceDesc1 = {
    Text = "【運命の網を安定させる】3択から上級刻印を獲得"
  },
  Event_125758_ChoiceDesc2 = {
    Text = "【危険を無視する】黄金の造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」に感染"
  },
  Event_125758_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_125758_Desc = {
    Text = "彼女は美の寵児。彼女は運命の棄て子。彼女は微かな光を辿り、深淵から這い上がった復讐者。彼女はここに来た、すべてに解放をもたらすために。\n運命の網があなたたちの周囲で崩れ落ちていく。あなたは劇場の舞台に立ち、ネフレアとそう遠くない距離で向かい合っている。"
  },
  Event_125758_Name = {
    Text = "運命の網の幕引き"
  },
  Event_125759_ChoiceDesc1 = {
    Text = "【理解できない】白銀の造物【(RelicConfig.Arg1)】を獲得"
  },
  Event_125759_ChoiceDesc2 = {
    Text = "【共感する】黄金の造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」に感染"
  },
  Event_125759_Desc = {
    Text = "舞台から身を引き裂くような慟哭が聞こえ、唯一の照明が孤独な影を照らしている。\n彼はあなたに最も誠実な演技を捧げている――己の臓腑を切り開き、すべての観客に見せるように。\n何がこの役をこれほどまでに苦しめているのか？"
  },
  Event_125759_Name = {
    Text = "役者の告白"
  },
  Event_125760_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125760_Desc = {
    Text = "あなたの手は右へ伸びた。\nそれはあなたの未来、最も強く渇望するもの、あなたの帰着点、いつか辿り着く場所。\nあなたの存在は、前方の太陽を追いかけるためにある。"
  },
  Event_125760_Name = {
    Text = "過去、未来"
  },
  Event_125761_ChoiceDesc1 = {Text = "【3点】"},
  Event_125761_ChoiceDesc2 = {Text = "【6点】"},
  Event_125761_ChoiceDesc3 = {Text = "【1点】"},
  Event_125761_Desc = {
    Text = "もちろんそのまま立ち去ることもできたが、あの精巧なサイコロがすっかりあなたの心を奪った。\n背後の追手のことも忘れ、敬虔にそれを手に取り、シルクハットの中に投げ入れた――"
  },
  Event_125761_Name = {
    Text = "街角の賭け"
  },
  Event_125762_ChoiceDesc1 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_125762_Desc = {
    Text = "コロコロコロ、サイコロはダイスカップの中で興奮して踊り、力尽きるまで踊り続けた。\n\n「なぜ…………なぜ誰も勝てないんだ！…………」"
  },
  Event_125762_Name = {
    Text = "街角の賭け"
  },
  Event_125763_ChoiceDesc1 = {
    Text = "【運命を受け入れる】3枚の指令カードから1枚を選んで刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125763_ChoiceDesc2 = {
    Text = "【運命に抗う】【(Skill.Arg1)】に感染、再びランダムに刻印"
  },
  Event_125763_Desc = {
    Text = "「ああ、いたずらっ子ね。運命はいつも慈悲深いけれど…………すべての抵抗には代償がある。さあ、今度は受け入れてくれる？」"
  },
  Event_125763_Name = {
    Text = "宿命の檻"
  },
  Event_125764_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125764_Desc = {
    Text = "あなたはその視線を見回し、手を振って挨拶する。\nまもなく、物語のクライマックスを彼らに届けることになるだろう。"
  },
  Event_125764_Name = {Text = "観客"},
  Event_125765_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125765_Desc = {
    Text = "「親愛なるアラクネ様、今日はあなたの誕生日です。私はご主人様と奥様、そしてあなたのために喜びを感じています。この美しい世界へようこそ。この優しい子守唄をあなたに捧げます。あなたが生まれたこの日から、心配のない人生を過ごせますように…………」"
  },
  Event_125765_Name = {
    Text = "おやすみなさい、エドガーさん"
  },
  Event_125766_ChoiceDesc1 = {
    Text = "【写真を撮る】3枚の指令カードから1枚を選び、刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125766_ChoiceDesc2 = {
    Text = "【再びポーズを変える】【(Skill.Arg1)】に感染し、選択肢1で獲得する刻印を変更する。あと1回使用可能"
  },
  Event_125766_Desc = {
    Text = "レンズを前にして少し不安になる。このポーズの方がいい写りになるだろうか？それともあのポーズ？"
  },
  Event_125766_Name = {
    Text = "観客席の残影"
  },
  Event_125767_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125767_Desc = {
    Text = "映し出された内容を見ようとしたが、スクリーンには何も映っておらず、映写館にはフィルムが回る音だけが響いていた。\nフィルムに記された内容を知る機会は、ずっと先のことになるのかもしれない。"
  },
  Event_125767_Name = {
    Text = "記憶映写館"
  },
  Event_125768_ChoiceDesc1 = {
    Text = "【視線を避ける】ランダムに覚醒体を1体覚醒させる"
  },
  Event_125768_ChoiceDesc2 = {
    Text = "【視線を直視する】覚醒体を1体選択して覚醒させ、その霊知覚醒カードの行動力消費を2点減少させる。「(Skill.Arg1)」に感染する"
  },
  Event_125768_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_125768_Desc = {
    Text = "舞台に上がった時、ひそひそと囁く声が聞こえた。振り返ると、一万の観客の目が舞台の四方に浮かび、あなたを凝視していた。\nさあ！と彼らは言う。素晴らしい劇が、まさかここで終わるのか？\n踊れ！と彼らは言う。この舞曲のクライマックスを見せてくれ！"
  },
  Event_125768_Name = {Text = "観客"},
  Event_125769_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125769_Desc = {
    Text = "あなたは彼の苦しみを理解しない。理解する必要もない。\n劇場にはこれほど多くの舞台があり、舞台にはこれほど多くの人形がいる。あなたもその一つに過ぎない。\nあなたにはもっと重要なことがある。"
  },
  Event_125769_Name = {
    Text = "役者の告白"
  },
  Event_125770_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125770_Desc = {
    Text = "死、消散、流転…………芸術は苦痛をもたらすために存在するのではない。もし美が苦痛の中にしか存在しないなら、そんな美など要らない。\nあなたは懸命に追い払った。蝶は散り、悲しげな屍だけが残された。"
  },
  Event_125770_Name = {
    Text = "消散の中に咲く"
  },
  Event_125771_ChoiceDesc1 = {
    Text = "【歌を聴く】40黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_125771_ChoiceDesc2 = {
    Text = "【無視】25黒章を獲得し、離れる"
  },
  Event_125771_Desc = {
    Text = "かつてあなたと出会った鴉の群れが一羽に集まった。それはあなたの前に立ち、歌を歌う。その歌声は凄涼で、まるで最後の予言のようだった。"
  },
  Event_125771_Name = {
    Text = "最後の予言"
  },
  Event_125772_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125772_Desc = {
    Text = "あなたの手は左へ伸びた。\nそれはあなたの過去、最も大切な記憶、歩んできた道、いつか帰る場所。\n過去のすべてが、あなたのすべてを形作っている。"
  },
  Event_125772_Name = {
    Text = "過去、未来"
  },
  Event_125773_ChoiceDesc1 = {
    Text = "【写真を撮る】3枚の指令カードから1枚を選び、刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125773_Desc = {
    Text = "レンズを前にして少し不安になる。このポーズの方がいい写りになるだろうか？それともあのポーズ？\nまだ迷っているが、カメラがすでにかなり苛立っているのが見て取れた。"
  },
  Event_125773_Name = {
    Text = "観客席の残影"
  },
  Event_125774_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125774_Desc = {
    Text = "あなたはポーズを決め、カメラの前に立った。端正に、好奇心を持って、真剣に――まるで本物の観客のように。\nゴポッ――\nカメラがシャッターを切ると、黒い粘液が機体から弾け飛び、ステージ全体に飛び散った。\nカメラの残骸の中央、フィルムには何も写っていなかった。"
  },
  Event_125774_Name = {
    Text = "観客席の残影"
  },
  Event_125775_ChoiceDesc1 = {
    Text = "【受け入れる】3択から白銀の造物を獲得"
  },
  Event_125775_ChoiceDesc2 = {
    Text = "【逃げる】白銀の造物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」を獲得、「(Skill.Arg3)」に2回感染"
  },
  Event_125775_Desc = {
    Text = "タッタッ、タッタッ…………ヒールと板が触れ合い、心地よい軽やかな音を立てる。\n学生服を着た二体の人形が舞台の上で踊っている。突然、二体は踊りを止め、振り返ってあなたに手を差し伸べた。"
  },
  Event_125775_Name = {
    Text = "三人の舞"
  },
  Event_125776_ChoiceDesc1 = {
    Text = "【苦痛に耐える】最大HPをArg1ポイント増加する"
  },
  Event_125776_ChoiceDesc2 = {
    Text = "【苦しみに反論する】ランダムな1枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、1枚の「(Skill.Arg2)」に感染"
  },
  Event_125776_Desc = {
    Text = "「あなたはリズの死を気にかけたことなどない。誰のことも気にかけたことなどない。」\n「あなたが気にかけるのは自分だけ…………あなたの周りのすべての人は、自由と安寧へ至るための道具に過ぎない。」\n「違うかしら…………秘密の守り人？」\n案内人の囁きが耳元に響く。心臓が締め付けられ、収縮し、激しい苦痛が彼女の言葉とともに体中に蔓延していく…………"
  },
  Event_125776_Name = {
    Text = "苦痛の蔓延"
  },
  Event_125777_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125777_Desc = {
    Text = "意識の沈降に身を委ねなさい。海水には浮力がある。運命があなたたちにすべての道を示してくれるだろう。"
  },
  Event_125777_Name = {Text = "静寂"},
  Event_125778_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125778_Desc = {
    Text = "それは自分自身だった。力の源、責務の担い手、唯一忠誠を誓う対象。\nあなたは自分だけの道を歩んでいる。"
  },
  Event_125778_Name = {
    Text = "酒に映る影"
  },
  Event_125779_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125779_Desc = {
    Text = "「残念ですね、お客様。運命の味、もう二度と味わう機会はありませんよ…………」"
  },
  Event_125779_Name = {
    Text = "運命の味"
  },
  Event_125780_ChoiceDesc1 = {
    Text = "【彼女と語り合う】指令カードを1枚削除し、Arg1の黒印を獲得"
  },
  Event_125780_ChoiceDesc2 = {
    Text = "【沈黙を守る】"
  },
  Event_125780_Desc = {
    Text = "「これは本当に悲しいお芝居ですね…………あの可哀想な少女は、自分が慕う人に捨てられたのでしょうか、お姉さま？」\nその聞き覚えのある声には、狂気も憎悪も一切感じられなかった。その声は澄んでいて、哀しげで、まるで林の中を流れる穏やかな小川のようだった。\n「あの歌い手は、力なく漂う枯れ葉のように、ただ運命に弄ばれるしかない…………なんて可哀想な人なのでしょう…………」\n「ねえ、もし私があの筆を執る者だったら…………彼女にどんな結末を書いてあげるべきでしょうか？」"
  },
  Event_125780_Name = {
    Text = "劇作の結末"
  },
  Event_125781_ChoiceDesc1 = {
    Text = "【撫でる】50％の確率で黒印を125獲得、50％の確率で【(Skill.Arg2)】に感染"
  },
  Event_125781_ChoiceDesc2 = {
    Text = "【説明する】75％の確率で黒印を100獲得、25％の確率で【(Skill.Arg2)】に感染"
  },
  Event_125781_ChoiceDesc3 = {
    Text = "【看破する】黒印を50獲得"
  },
  Event_125781_Desc = {
    Text = "バーの裏通りを追いかけると、怪物の姿は消え去り、一群の黒猫があなたの前に立ちはだかった。\n「おい、お前。」一匹の黒猫が自分の爪を舐め、あなたを見つめた。\n「俺たちの縄張りに何の用だ？」"
  },
  Event_125781_Name = {
    Text = "幻化変形"
  },
  Event_125782_ChoiceDesc1 = {
    Text = "【過去を抱きしめる】黄金造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」に感染"
  },
  Event_125782_ChoiceDesc2 = {
    Text = "【未来を迎える】3択から黄金造物を1つ獲得、【(Skill.Arg1)】に感染"
  },
  Event_125782_ChoiceDesc3 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_125782_Desc = {
    Text = "ネフレアの出現が糸を乱した。紊乱した運命の中、あなたは二つのぼんやりとした幻影を見た。\nそれはあなたの過去、そしてあなたの未来。あなたはそれらに歩み寄り、手を伸ばした…………"
  },
  Event_125782_Name = {
    Text = "過去、未来"
  },
  Event_125855_ChoiceDesc1 = {
    Text = "【感知】造物を1つ選び、黄金造物【(RelicConfig.Arg1)】に変化させる"
  },
  Event_125855_ChoiceDesc2 = {
    Text = "【凝視する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_125855_ChoiceDesc3 = {
    Text = "【無視】25黒章を獲得する"
  },
  Event_125855_Desc = {
    Text = "カサリムの街角で、ある水晶店の眩い輝きがあなたの目を引いた。あなたは店の前に来て、銀芯の形をした水晶を一つ拾い上げた。"
  },
  Event_125855_Name = {
    Text = "水晶の秘密"
  },
  Event_125856_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125856_Desc = {
    Text = "あなたは目を閉じ、それを注意深く感じ取った。\n微かな光があなたの意識の中で瞬き、何かを伝えようとしている…………"
  },
  Event_125856_Name = {
    Text = "水晶の秘密"
  },
  Event_125857_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125857_Desc = {
    Text = "運命への抵抗も覗き見も、すべては徒労に過ぎない。君は静かに目を閉じ、運命の赴くままに身を委ねた。"
  },
  Event_125857_Name = {
    Text = "縛命の網"
  },
  Event_125858_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125858_Desc = {
    Text = "「感情は存続の意義である。自らの選択を後悔しないことを願おう。」"
  },
  Event_125858_Name = {
    Text = "選択の代償"
  },
  Event_125859_ChoiceDesc1 = {
    Text = "【感情】ライフを Arg1 ポイント回復する"
  },
  Event_125859_ChoiceDesc2 = {
    Text = "【理性】ランダムな指令カード1枚に刻印を獲得：【(EnchantConfig.Arg1)】"
  },
  Event_125859_ChoiceDesc3 = {
    Text = "【選択を拒否する】25ブラックシールを獲得"
  },
  Event_125859_Desc = {
    Text = "天秤が舞台に現れた。\n「脳と心臓、理性と感情、灰と赤…………我々は選択から逃れられない、それが我々の運命だ。」\n「舞台の終着点はすでに定められた。さあ、この舞台が辿る道を選ぶがいい。」"
  },
  Event_125859_Name = {
    Text = "選択の代償"
  },
  Event_125860_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125860_Desc = {
    Text = "「顔を上げるな。ここから離れろ。」\nあなたは運命の声を聞いた。空を見上げたいという渇望が込み上げるが、あなたは知っている——彼女の言葉は正しいと。"
  },
  Event_125861_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125861_Desc = {
    Text = "君は決して運命を受け入れない。決して囚われを受け入れない。\n必死にもがき、蛾の肢体の一部を犠牲にして、ようやく逃れることができた…………"
  },
  Event_125861_Name = {
    Text = "縛命の網"
  },
  Event_125862_ChoiceDesc1 = {
    Text = "【友情】黒印を50獲得する"
  },
  Event_125862_ChoiceDesc2 = {
    Text = "【助力】黒印を75獲得し、【(Skill.Arg2)】に感染する"
  },
  Event_125862_Desc = {
    Text = "バーの裏通りで、あなたは再びあの黒猫たちに出会った。\n「聞いたよ。あの黒い粘液が私たちの姿に化けて、随分と迷惑をかけたみたいだね。」\n「お詫びとして、教えてよ。何が欲しい？」\n黒猫があなたの足元を二周回り、見上げてきた。"
  },
  Event_125862_Name = {
    Text = "初対面の贈り物"
  },
  Event_125863_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125863_Desc = {
    Text = "蛮力では運命を打ち破れない。だが知恵ならば？\n君はこの網を注意深く観察し、運命の軌跡を読み取ろうと試みる…………"
  },
  Event_125863_Name = {
    Text = "縛命の網"
  },
