  },
  Event_125865_ChoiceDesc1 = {
    Text = "【もがく】デッキからランダムに指令カード3枚を取得し、1枚を選んで削除、黒印75を獲得"
  },
  Event_125865_ChoiceDesc2 = {
    Text = "【思考する】デッキからランダムに指令カード3枚を取得し、1枚のオリジナルコピーをデッキに追加、黒印25を獲得"
  },
  Event_125865_ChoiceDesc3 = {
    Text = "【休息する】黒印50を獲得"
  },
  Event_125865_Desc = {
    Text = "見覚えのある感覚が襲いかかる。だが前回とは違い、あのねばつく感触、抗えないという直感が、より強烈に、より致命的になっていた。\n蛾は蜘蛛の巣に落ち、君もまた舞台に足を踏み入れた。"
  },
  Event_125865_Name = {
    Text = "縛命の網"
  },
  Event_125866_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125866_Desc = {
    Text = "「理性は存続の手段である。自らの選択を後悔しないことを願おう。」"
  },
  Event_125866_Name = {
    Text = "選択の代償"
  },
  Event_125867_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125867_Desc = {
    Text = "好奇心に火がついた。あなたは人々の中に入り、彼らと同じように頭を上げた。\nそこには何もなかった。だが、なぜかわからないが、あなたはどうしても目を下ろしたくなかった。このまま見つめていたい、ずっと見つめていたい…………"
  },
  Event_125868_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125868_Desc = {
    Text = "「選択を放棄することもまた一つの選択、それは運命の呪いだ。自らの選択を後悔しないことを願おう。」"
  },
  Event_125868_Name = {
    Text = "選択の代償"
  },
  Event_125869_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_125869_Desc = {
    Text = "「さあ、もう手に入れたよ。」\n黒猫があなたのすねに擦り寄り、すぐに姿を消した。\n彼らが消えた場所に、贈り物が待っていた。"
  },
  Event_125869_Name = {
