  Event_125871_ChoiceDesc2 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_125871_Desc = {
    Text = "喧騒が一瞬消えた。街の人々は沈黙に陥り、頭を上げて空を見上げた。"
  },
  Event_129176_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129177_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129178_ChoiceDesc1 = {
    Text = "【方向を指示する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129178_ChoiceDesc2 = {
    Text = "【共に祈る】3択刻印を2回獲得"
  },
  Event_129178_Desc = {
    Text = "ピアノとオルガンの音が灰色の風の中で交錯している。\n魔法のような旋律が人のいない街並みに漂っている。\n\n名前のない修道女が音楽に合わせて祈りを捧げる。\n\n「簡単な祈りには華やかな儀式は不要で、偉大な父なる神は私たちに希望を撒き与えてくださる。\nまさしく、彼が私たちに信仰心を授けてくれたように」"
  },
  Event_129178_Name = {
    Text = "パイプオルガンの祈り"
  },
  Event_129179_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129180_ChoiceDesc1 = {
    Text = "【積極的に迎え撃つ】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129180_ChoiceDesc2 = {
    Text = "【抵抗を諦める】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129180_ChoiceDesc3 = {
    Text = "【急いで離脱する】50黒章を獲得する"
  },
  Event_129180_Desc = {
    Text = "いくつかの蝋人形の原型が道を塞いでいる。\n\nそれらは歪んでいて、粗い顔立ちで、ロジャーズの技術とは思えない。\n\n「命令……主の命令……」"
  },
  Event_129180_Name = {Text = "習作"},
  Event_129181_ChoiceDesc1 = {
    Text = "【思考を放棄する】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129181_ChoiceDesc2 = {
    Text = "【啓示を追いかける】ランダムな指令カード1枚に刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129181_Desc = {
    Text = "襲撃された港、帰らぬ謎の貨物船、そしてヒレを生やした“新たな仲間”…これは周到に用意された罠なのか？それともまた事故が多発する予兆なのでしょうか？\n現実と理性が絡み合い、数え切れないほどの直感や提案が湧き出てきます。"
  },
  Event_129181_Name = {
    Text = "インスピレーション"
  },
  Event_129182_ChoiceDesc1 = {
    Text = "【加わる】「(Skill.Arg1)」に2回感染、ランダムなカード1枚が刻印を獲得：「(EnchantConfig.Arg2)」を2回"
  },
  Event_129182_ChoiceDesc2 = {
    Text = "【追い払う】「(Skill.Arg1)」に2回感染、ランダムなカード1枚が刻印を獲得：「(EnchantConfig.Arg2)」を2回"
  },
  Event_129182_ChoiceDesc3 = {
    Text = "【無関心】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129182_Desc = {
    Text = "あなたは遠くからかすかに響く骨のホラ貝の音を聞いた。\n鼠の群れがその音に導かれ、黒い泥の中から湧き出て、干からびた河床に横たわる無名の死体を貪り食っている。\n彼らは円を作り、その中心にはすでに空洞となった遺体があり、円周は忘却を法とする新王国である。\nそしてあなたは、その王国の入口に立っている。"
  },
  Event_129182_Name = {
    Text = "追放された王国"
  },
  Event_129183_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129184_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129185_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129186_ChoiceDesc1 = {
    Text = "【肖像を救う】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129186_ChoiceDesc2 = {
    Text = "【空白を受け入れる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129186_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129186_Desc = {
    Text = "あなたはピックマンの贈り物の前に立っています。\nそれは血で描かれた肖像画で、真っ黒な炎が静かに燃えています。\n絵の中の人の空洞の目を通して、あなたは見ることができます——\nあなたの記憶がうねり燃え上がり、引き延ばされ、ねじれ、光り輝いており、まるで何か無形の火があなたの脳の回廊を舐めているかのようです。ぼんやりとした中で、あなたは一つの声を聞きます。\n「鍋に入れる時間だ、ちょうどいい火加減だ。」\nそれはあなた自身が描いた記憶の景色で、あなたは炎の中でもがき変形しています。"
  },
  Event_129186_Name = {
    Text = "燃える肖像"
  },
  Event_129187_ChoiceDesc1 = {
    Text = "【どのような代償を払いますか？】ランダムな1枚のカードの刻印品質を2回向上"
  },
  Event_129187_ChoiceDesc2 = {
    Text = "【期限切れのブラッディ・マリーを一杯ご馳走しよう】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129187_Desc = {
    Text = "「いらっしゃいませ、私の大切なお客様。\nどうぞご自由に選んでください、ここにあるものはすべてあなたを待っていました」\n\n「えっと、失礼ですが、あなたは……ダフォダイルさんの双子の姉妹ですか？」\n\n「私はダフォダイル本人です。\nお客様、今日はどのようなご用件で……？」\n\n「申し訳ありません、以前よりも魅力的になられていて、気づきませんでした。\n覚えていますか？\n二十年前、あなたが私のバーから奇妙な奴を追い出してくれたことを……昨日、その悪夢が再び現れました。\n奴は仲間を引き連れてバーを占領して……」"
  },
  Event_129187_Name = {
    Text = "記憶の断片・昔の夢が甦る"
  },
  Event_129188_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129189_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129190_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129191_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129192_ChoiceDesc1 = {
    Text = "【火種を信じる】最大ライフをArg1増加させる"
  },
  Event_129192_ChoiceDesc2 = {
    Text = "【内心と向き合う】ランダムな指令カード2枚に刻印を獲得：「(EnchantConfig.Arg1)」を2回、2枚の「(Skill.Arg2)」を2回感染"
  },
  Event_129192_Desc = {
    Text = "この壮大な狩りで、ゴリアテの追跡は夜の獣のように希望の光を飲み込もうとする。\nしかし、この無情な追跡にあなたは怖気づくことはなく、むしろ心の火種を燃やして胸の中に広がり、熱くなった。"
  },
  Event_129192_Name = {
    Text = "光を追う"
  },
  Event_129193_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129194_ChoiceDesc1 = {
    Text = "【先人の道を読む】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_129194_ChoiceDesc2 = {
    Text = "【自分の道を書き記す】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129194_ChoiceDesc3 = {
    Text = "【闇を見つめる】25黒章を獲得する"
  },
  Event_129194_Desc = {
    Text = "もしあなたが一人で密境を進んでいたら、今のように自分の道を確信することはできなかっただろう。\n\n密境の足跡は三つに分かれ、刻まれた足跡は見えない未来を描いている。"
  },
  Event_129194_Name = {Text = "出口"},
  Event_129195_ChoiceDesc1 = {
    Text = "【誤りを指摘する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129195_ChoiceDesc2 = {
    Text = "【演奏を聴き終える】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_129195_ChoiceDesc3 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_129195_Desc = {
    Text = "少年の蝋人形がピアノの前で練習曲を弾いている。\n\n彼の先生もまた蝋人形で、そばで指導している。\n\n133，355，244……\n間違っている、すべての音が間違っている。"
  },
  Event_129195_Name = {
