  },
  Event_129197_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129198_ChoiceDesc1 = {
    Text = "【悲しみに耳を傾ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129198_ChoiceDesc2 = {
    Text = "【喜びを聴く】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_129198_ChoiceDesc3 = {
    Text = "【離れる】3択刻印を2回獲得"
  },
  Event_129198_Desc = {
    Text = "悠然、叙情、歓喜、哀愁……メロディーが密境に響き渡り、出所が分からない。\n\n幽霊船の音響から流れるソナタか、それとも密境に囚われた夜の狂想曲か？"
  },
  Event_129198_Name = {
