  },
  Event_129200_ChoiceDesc1 = {
    Text = "【封筒を開ける】黄金造物「(RelicConfig.Arg1)」を獲得し、感染「(Skill.Arg2)」"
  },
  Event_129200_ChoiceDesc2 = {
    Text = "【読む】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129200_ChoiceDesc3 = {
    Text = "【元の場所に戻す】50黒章を獲得する"
  },
  Event_129200_Desc = {
    Text = "誰も気に留めない隅に、手紙が残されていた。\n手紙の多くの文字は判読できなくなっているが、ただ一つの言葉だけは透き通っている。\nその言葉は「母」だ。"
  },
  Event_129200_Name = {
    Text = "消えゆく思い"
  },
  Event_129201_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129202_ChoiceDesc1 = {
    Text = "【じっくり聴く】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129202_ChoiceDesc2 = {
    Text = "【耳を塞ぐ】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_129202_ChoiceDesc3 = {
    Text = "【確認する】3択刻印を2回獲得"
  },
  Event_129202_Desc = {
    Text = "遺骸がある階に入ると、廃工場の中で突然、心地よいピアノの音が響き渡る。\n錆びついた鉄の廃墟には不釣り合いな清らかな音色だ。"
  },
  Event_129202_Name = {
    Text = "不気味な音階"
  },
  Event_129203_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129204_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129205_ChoiceDesc1 = {
    Text = "【彼女を許す】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129205_ChoiceDesc2 = {
    Text = "【彼女を助ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129205_ChoiceDesc3 = {
    Text = "【自分の道を行く】50黒章を獲得する"
  },
  Event_129205_Desc = {
    Text = "三人の影があなたの行く手を阻む。\n\n「彼女を見逃してあげて」\n融蝕液塗れのクマのぬいぐるみを抱く影が言う。\n「彼女は臆病なだけで、邪悪ではない。誰も傷つけたくないんだ」\n\n「彼女を助けてあげて」\nきれいに包装されたキャンディを持つ影が言う。\n「あなたには彼女ができないことができる。すべてを終わらせることができる」\n\n「私たちの言うことを聞く必要はない」\n手ぶらの影が言う。\n「あなたにはあなたの道がある」"
  },
  Event_129205_Name = {
    Text = "分かれ道"
  },
  Event_129206_ChoiceDesc1 = {
    Text = "【ネズミに餌をやる】しろがねのつくりもの「(RelicConfig.Arg1)」を獲得し、1回の症状に感染することを選択する"
  },
  Event_129206_ChoiceDesc2 = {
    Text = "【ネズミを追い払う】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129206_ChoiceDesc3 = {
    Text = "【ネズミを無視】25黒章を獲得する"
  },
  Event_129206_Desc = {
    Text = "この船の上のすべてが、輪廻を繰り返している。\n船の上で生きる、忌まわしく汚い毛に覆われた小さな生き物たちも、当然この運命から逃れることはできない。\n何度も何度も繰り返す輪廻の中で、目に映るすべてを食べても、なお満たされない。\n「お腹が…………すく…………」\n群がるネズミたちが病的で耳障りな金切り声を上げる。\n幾度もの輪廻が彼らを飢えに苦しめ、何かを食べなければならない。\n今すぐに！"
  },
  Event_129206_Name = {
    Text = "飢えたネズミの群れ"
  },
  Event_129207_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129208_ChoiceDesc1 = {
    Text = "【脳に触れる】ランダムな指令カード1枚が刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129208_ChoiceDesc2 = {
    Text = "【心臓に触れる】Arg1の最大体力をポイント上昇させ、「(Skill.Arg2)」に感染します"
  },
  Event_129208_Desc = {
    Text = "あなたは誰もささやかない灰色のホールに足を踏み入れ、黒霧の中で天秤がぼんやりと浮かび上がっているのを見た。\n左側には、湖のように静かな大脳があり、銀色の溝が微かに光を放っている；右側には、赤熱した蒸気を放つ心臓がある。\n突然、あなたは香りを感じ、渇望が膨れ上がり、理性がその無限の暗闇に押しつぶされていく。\nあなたは手を伸ばした。"
  },
  Event_129208_Name = {
    Text = "ハンガー・ゲーム"
  },
  Event_129209_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129210_ChoiceDesc1 = {
    Text = "【人影を斬る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129210_ChoiceDesc2 = {
    Text = "【胚胎を砕く】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129210_ChoiceDesc3 = {
    Text = "【目を閉じる】25黒章を獲得する"
  },
  Event_129210_Desc = {
    Text = "ぼんやりと、アランで見たことのある人々があなたに近づいてくる。\n\n彼らは笑いながら、酒を飲み、踊り、美食を楽しむように誘う。\n\nそして彼らの血肉が次々と剥がれ落ち、地面に落ちたものが蠢いて新たな胚胎を生み出す。\n\n彼らは手を差し伸べ、血肉と新生の狂宴にあなたを誘う。"
  },
  Event_129210_Name = {
    Text = "過去の影"
  },
  Event_129211_ChoiceDesc1 = {
    Text = "【彼らに餌を与える】白銀造物「(RelicConfig.Arg1)」を獲得し、1回症状を感染することを選択"
  },
  Event_129211_ChoiceDesc2 = {
    Text = "【無視する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129211_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129211_Desc = {
    Text = "住民が出入りする中、鼠の群れは長く続いている。\n人間と比べて、彼らこそがこの古城の「先住民」だ。\nしかし、彼らは人間の進入に異議を唱えない。\nなぜなら、その香ばしく柔らかく、白くて醜いものたちが、同じように香ばしく柔らかく、白くて醜いものを与えてくれるからだ。\n「そしてお前は、醜いもの、どちらの種類に属するのか？」"
  },
  Event_129211_Name = {
    Text = "古城の秘密"
  },
  Event_129212_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129213_ChoiceDesc1 = {
    Text = "【男の声を判別する】山札からランダムに指令カードを3枚引き、1枚選択して複製する"
  },
  Event_129213_ChoiceDesc2 = {
    Text = "【女性の声を聞き分ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129213_ChoiceDesc3 = {
    Text = "【老人の声を判別する】25黒章を獲得する"
  },
  Event_129213_Desc = {
    Text = "暗闇の中の沼地に一人立つ。\n\nぼんやりと混沌とした呪文が押し寄せ、耄碌した老人から来たものや、言葉を学び始めたばかりの子供、切迫した女性、なんとも言えない恐怖に包まれた男性から来たものもある…"
  },
  Event_129213_Name = {
    Text = "遺言のうわ言"
  },
  Event_129214_ChoiceDesc1 = {
    Text = "【よく見る】3択刻印を2回獲得"
  },
  Event_129214_ChoiceDesc2 = {
    Text = "【ポスターを剥がす】ランダムな1枚の指令カードに刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129214_Desc = {
    Text = "蝋人形館内の随所に見られる燭台。\n\n病的な橙色の光で、壁に手描きのポスターが貼られているのを発見する。"
  },
  Event_129214_Name = {
    Text = "暗闇の中の笑い声"
  },
  Event_129215_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129216_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129217_ChoiceDesc1 = {
    Text = "【凝視する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129217_ChoiceDesc2 = {
    Text = "【無視する】3択刻印を2回獲得"
  },
  Event_129217_Desc = {
    Text = "アラン族は砂嵐の中でひざまずく。\n\n嵐が彼らの体を叩き、砂が彼らの信仰心を巻き込む。\n\n砂塵の渦の中、無数の巨大な目が歪んだ大地を見下ろしているようだ。"
  },
  Event_129217_Name = {
    Text = "砂塵の巨物"
  },
  Event_129218_ChoiceDesc1 = {
    Text = "【蝶を追い払う】ランダムな指令カード1枚が刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129218_ChoiceDesc2 = {
    Text = "【願いを聞く】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129218_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129218_Desc = {
    Text = "小さな蝶は、たくさんの夢を抱えています。\nこれらの夢は花畑や病室、そして多くの血肉で満たされた@2の祭壇に散らばっています。\n今、ようやく絆のある人を待ち望んでいますが、あなたはその小さな、小さな願いを聞いてくれるのでしょうか。"
  },
  Event_129218_Name = {Text = "蝶の夢"},
  Event_129219_ChoiceDesc1 = {
    Text = "【導きに従う】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129219_ChoiceDesc2 = {
    Text = "【導きを無視する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129219_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129219_Desc = {
    Text = "祭典はすでに始まった。\n霊の焔火と血の祝祷の下、数え切れない信徒の魂が航標と化した――\n漂う霊があなたの周りに散らばり、導きの精霊のように光を放ち、あなたの選択を待っている。"
  },
  Event_129219_Name = {
    Text = "魂の航標"
  },
  Event_129220_ChoiceDesc1 = {
    Text = "【鈴の音を無視する】3択上位刻印を2回獲得"
  },
  Event_129220_ChoiceDesc2 = {
    Text = "【受話器を取る】ゴールドクリエイション「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染します"
  },
  Event_129220_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_129220_Desc = {
    Text = "それは鳴るべきではなかった——その電話は、キャンバスの裏に縮こまっている。\n受話器のコードは大きな本体に絡まりつき、錆びたへその緒のように、あなたの脳から伸びているかのようだ。\nあなたは震動の周波数を注意深く識別し、奇妙な音はピックマンの超現実的なアートのようだ。"
  },
  Event_129221_ChoiceDesc1 = {
    Text = "【私たちは皆無事です】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129221_ChoiceDesc2 = {
    Text = "【あなたは誰ですか？】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129221_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129221_Desc = {
    Text = "タイプライターが突然インクを噴き出し、驚くほど多くの感嘆符が目に刺さる。\n\n「ドール、大丈夫か？？？\nなぜ守秘者が消えたら君も消えたんだ！！！\n無事ならメッセージを返してくれ！！！\n\n待ち続けてたら、ウィリアムの髪が全部抜けちゃうぞ！！！」"
  },
  Event_129221_Name = {
    Text = "緊急通信"
  },
  Event_129222_ChoiceDesc1 = {
    Text = "【赤い絹を切断する】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_129222_ChoiceDesc2 = {
    Text = "【対抗する】指令カードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_129222_ChoiceDesc3 = {
    Text = "【ラモンナを呼びかける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129222_Desc = {
    Text = "カーシアが赤い絹を投げ、瞬時にあなたの手提げを絡め取った。"
  },
  Event_129222_Name = {
    Text = "絡みつく絹"
