  },
  Event_129227_ChoiceDesc1 = {
    Text = "【手を振って追い払う】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129227_ChoiceDesc2 = {
    Text = "【留まるに任せる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129227_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129227_Desc = {
    Text = "暗闇の中からかすかな音が聞こえた。\nそれは一匹の蝶が礼儀正しく尋ねる声だった。\n「あなたの手のひらに止まってもいいですか？」\n「ただ疲れてしまって、少し休みたいだけなの…………」\nそう尋ねながら、蝶は暗闇を越え、あなたの目の前を旋回している。\n漆黒の粘液がその翅から滴り落ちる――それは蝶が暗闇を越えた時、暗闇からの贈り物だった。"
  },
  Event_129227_Name = {
    Text = "蝶の頼み"
  },
  Event_129228_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129229_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129230_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129231_ChoiceDesc1 = {
    Text = "【歌詞を聞き分ける】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129231_ChoiceDesc2 = {
    Text = "【そっと鼻歌を歌う】3択刻印を2回獲得"
  },
  Event_129231_Desc = {
    Text = "古い船歌が密境に響く。\n\n密境に閉じ込められた記憶が、聞いたことのない言葉で、波、空、酒を歌う。"
  },
  Event_129231_Name = {Text = "海の歌"},
  Event_129232_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129233_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129234_ChoiceDesc1 = {
    Text = "【手のひらを切る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129234_ChoiceDesc2 = {
    Text = "【成長を受け入れる】シルバークリエイション「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染します"
  },
  Event_129234_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129234_Desc = {
    Text = "そのちょうちょうは飛んできたのではなく、あなたの掌の中でゆっくりと成長していった。\n最初は汗だと思っていたが、指の隙間から黒い液体が血管のように静かに逆流し、冷たく脈動する羽へと凝固していくのを見た。\nそのたびに、あなたの血液の中で波紋が広がる。"
  },
  Event_129235_ChoiceDesc1 = {
    Text = "【読み続ける】ランダムな1枚の指令カードに刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129235_ChoiceDesc2 = {
    Text = "【離れる】最大ライフをArg1増加させ、さらに「(Skill.Arg2)」に感染する"
  },
  Event_129235_Desc = {
    Text = "重さを測るための天秤。\nその背後には、無数の臓器が赤いホルマリン液に浸かり、それらは整然と棚に置かれていた。\n\n近くのノートを拾い読みする。\n「心臓：8オンス、脳：50オンス……」"
  },
  Event_129235_Name = {
    Text = "臓器登録"
  },
  Event_129236_ChoiceDesc1 = {
    Text = "【迂回する】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_129236_ChoiceDesc2 = {
    Text = "【なぜ沈んだのか尋ねる】指令カードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_129236_ChoiceDesc3 = {
    Text = "【クルーに挨拶する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129236_Desc = {
    Text = "動力室に向かう途中で、再び密境に固定された「記憶」に出会う。\n\n彼らは幽霊ではなく、エルトン船長が亡くなった船員を想う心だ。"
  },
  Event_129236_Name = {
    Text = "ソナニール号の主人"
  },
