  },
  Event_129238_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129239_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129240_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129241_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129242_ChoiceDesc1 = {
    Text = "【彼のために演奏する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129242_ChoiceDesc2 = {
    Text = "【ピアノを聴く】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_129242_ChoiceDesc3 = {
    Text = "【離れる】3択刻印を2回獲得"
  },
  Event_129242_Desc = {
    Text = "「親愛なるジョン：\n最近、唐突に思い至りました……\nあなたが僕たちのために最後にピアノを演奏してくれた時から、もう数年も経っていることに。\n\n僕は今年81歳になり、年々若い頃の思い出の大切さを感じています。\n\nもしあなたがこの手紙を受け取ったら、次にロンディニウムに寄った時は、僕のアパートの前で立ち止まり、一曲演奏してくれませんか」"
  },
  Event_129242_Name = {
    Text = "遺憾のソナタ"
  },
  Event_129243_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129244_ChoiceDesc1 = {
    Text = "【財布がないと言う】3択の刻印を2回獲得"
  },
  Event_129244_ChoiceDesc2 = {
    Text = "【網を破る】ランダムな1枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129244_Desc = {
    Text = "オレンジがかった黄色の糸が静かに空中に浮かんでいる。\n思わず手を伸ばすと、脆い糸は瞬時に溶け、子供たちの笑い声が耳元で響いた。\n「金も銀も黄も赤も、すべての財布は私たちのもの！」"
  },
  Event_129244_Name = {
    Text = "迷走ネットワーク"
  },
  Event_129245_ChoiceDesc1 = {
    Text = "【感情を選択する】Arg1ポイントの生命を回復"
  },
  Event_129245_ChoiceDesc2 = {
    Text = "【理性を保つ】ランダムな指令カード1枚に刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129245_ChoiceDesc3 = {
    Text = "【選択を拒否する】25ブラックシールを獲得"
  },
  Event_129245_Desc = {
    Text = "「選択せよ、選択せよ。」\n狂奔するダークの中から、無数の呟きが聞こえてきた。\nこの声は優しく催眠的で、無限の魔力を帯びているようで、あなたに何らかの狂気の幻覚を引き起こさせる。\nあなたの脳は狂悖に陥り、身体から脱け出そうと蠕動し、心臓は何らかの意識を持ち始め、あなたに叫びかけて呼びかけている。\n「選択せよ、選択せよ。」\n「理性を維持するか、感性を選ぶか、あなたは選択しなければならない。」"
  },
  Event_129245_Name = {
    Text = "人間性の代償"
  },
  Event_129246_ChoiceDesc1 = {
    Text = "【供物を消滅させる】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129246_ChoiceDesc2 = {
    Text = "【縄を解く】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129246_ChoiceDesc3 = {
    Text = "【前進し続ける】50黒章を獲得する"
  },
  Event_129246_Desc = {
    Text = "3人のアラン族が高台に縛られている。\n\n彼らの体には、見たことのある樹皮状の暗い模様が浮かび、呪文を唱えている。"
  },
  Event_129246_Name = {
    Text = "3つの供物"
  },
  Event_129247_ChoiceDesc1 = {
