  },
  Event_129248_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129249_ChoiceDesc1 = {
    Text = "【前に進む】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_129249_ChoiceDesc2 = {
    Text = "【糸を断ち切る】指令カードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_129249_ChoiceDesc3 = {
    Text = "【じっと堪える】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129249_Desc = {
    Text = "道中、あなたは進むように押され、すべての選択が見えない糸で操られている。\n\n必死に両手を動かし、大切なものを掴もうとする。\n\n世界の運命はあなたの指先にかかっている。\n\n無数の糸が絡みつき、全身を縛りつける。"
  },
  Event_129249_Name = {
