  },
  Event_129250_ChoiceDesc2 = {
    Text = "【その場を離れる】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_129250_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129250_Desc = {
    Text = "影は痩せこけた街灯の下に立っていた。\n「ちょっと火を貸してもらえませんか、先生」\nあなたは@2の習慣はないが、小さな「魔法」を使うのは厭わない。\nあなたの助けで、影は火のついた@2を、底の見えない黒い渦の中へと深く差し入れた。\nほどなくして、白い煙が立ち上るのが見えた。\n「ああ――」\n影は愉悦に満ちたため息をついた。"
  },
  Event_129250_Name = {
    Text = "街灯の下の影"
  },
  Event_129251_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129252_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129253_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129254_ChoiceDesc1 = {
    Text = "【幻覚を受け入れる】ランダムな1枚の指令カードに刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129254_ChoiceDesc2 = {
    Text = "【幻覚を否定する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129254_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129254_Desc = {
    Text = "重厚な暗い鉄橋の下、葦が生い茂る静かな河岸に、突然光る蝶が飛び出す。\n\n蝶が軽やかに手のひらに舞い降りると、悪夢のような叫び声が止み、代わりに列車が錆びた鉄橋を轢く轟音の響き、石炭が燃えるパチパチ音、車輪が回る金属の摩擦音が響く……"
  },
  Event_129254_Name = {
    Text = "鉄道の幻覚"
  },
  Event_129255_ChoiceDesc1 = {
    Text = "【拒否を選択する】1枚の指令カードを削除し、Arg1ブラックシールを獲得"
  },
  Event_129255_ChoiceDesc2 = {
    Text = "【従うを選択する】1枚の指令カードをコピーし、感染「(Skill.Arg1)」"
  },
  Event_129255_ChoiceDesc3 = {
    Text = "【抱擁を選ぶ】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129255_Desc = {
    Text = "「私は檻の中の鳥で、たくさんの部屋がある庭に閉じ込められています。」\n暗闇の中を彷徨うぼんやりとした人影、それは過去の者たちが残した執念です。\n「彼らはそれを精神病院だと言いますが、私は知っています。それは人間の特別な囚籠で、社会のルールに従うことを望まない自由な鳥を閉じ込めています。」\n「しかし、鳥が飛べないなら、鳥と呼べるのでしょうか？」\n執念たちがあなたに寄り添い、救済を求めています。\n「私の翼を折ってください、私は飛ぶことに疲れました。」"
  },
  Event_129256_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129257_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129258_ChoiceDesc1 = {
    Text = "【蝶を放す】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129258_ChoiceDesc2 = {
    Text = "【蝶になる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129258_ChoiceDesc3 = {
    Text = "【腹に収める】25黒章を獲得する"
  },
  Event_129258_Desc = {
    Text = "今夜は多くのことが起こった。\n\n埠頭での襲撃、幽霊船、海踊教団、トゥルー、マーフィー、ラモンナ……すべてが渦の中で回転し、ミサゴレストランの朝7時のオートミールのようにかき混ぜられた。\n\n覚醒体に質問したいが、どう切り出せばいいかわからず、喉に詰まった。"
  },
  Event_129258_Name = {
    Text = "バタフライ効果"
  },
  Event_129259_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129260_ChoiceDesc1 = {
    Text = "【そのままにしておく】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129260_ChoiceDesc2 = {
    Text = "【手を振って追い払う】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129260_ChoiceDesc3 = {
    Text = "【蝶を迎える】25黒章を獲得する"
  },
  Event_129260_Desc = {
    Text = "あなたたちは冷たい風が吹きすさぶ療養所を歩いていると、季節外れの黒い蝶が舞い降りてきた。\n\n蝶の羽ばたきには黒い粘液がまとわりつき、上下に揺れながら飛び、羽から溢れた黒い液体は固まって風化し剥がれ落ちる。\n\n疲れた蝶は、あなたの指先に止まった。"
  },
  Event_129260_Name = {
    Text = "存在しないはずのもの"
  },
  Event_129261_ChoiceDesc1 = {
    Text = "【過去を振り返る】3択の上位刻印を2回獲得する"
  },
  Event_129261_ChoiceDesc2 = {
    Text = "【未来を覗く】ゴールドクリエイション「(RelicConfig.Arg1)」を獲得し、感染「(Skill.Arg2)」"
  },
  Event_129261_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_129261_Desc = {
    Text = "この世に不変なものなど何もない。\n神母が創り上げた楽園でさえも。\n束の間の刹那、あなたは時空の裂け目から何かを垣間見た。\n過去、現在、未来がひび割れた隙間の中で交錯し、絶えず変化している。\nあなたの好奇の眼差しを待っている。"
  },
  Event_129261_Name = {
    Text = "時空の裂け目"
  },
  Event_129262_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129263_ChoiceDesc1 = {
    Text = "【無視する】3択刻印を2回獲得"
  },
  Event_129263_ChoiceDesc2 = {
    Text = "【触れる】ランダムな指令カード1枚が刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129263_Desc = {
    Text = "胞子のような奇妙な物があなたの注意を引いた。\nそれは血肉でできた細いクラゲのようであり、また脳の奥深くに信号を保存している神経繊維のようでもある。\n「私に触れてみて。」それは無言であなたを誘惑し、「私はあなたに残酷な記憶を見せるだろう。」"
  },
  Event_129263_Name = {
    Text = "ディープメモリ"
  },
  Event_129264_ChoiceDesc1 = {
    Text = "【幻想に溺れる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129264_ChoiceDesc2 = {
    Text = "【理性を保つ】狂気値が50以上の覚醒体が1人いるごとに、15ブラックスタンプを獲得"
  },
  Event_129264_ChoiceDesc3 = {
    Text = "【強引に立ち去る】3択刻印を2回獲得"
  },
  Event_129264_Desc = {
    Text = "おそらく長期の戦闘があなたに恍惚を生じさせたのか、あるいは単にあなたの脳が身体を裏切ったのか。\nある種の無重力感があなたの脳裏に現れる。\n一瞬にして、あなたの脳裏は突然万華鏡と化し、絢爛で、色彩豊かで、五色の光彩がきらめく。\n数え切れないインスピレーション、迷想、狂想が脳に押し寄せ、あなたの脳の溝の隅々を占拠する。\nこのままでは、あなたの頭はすぐにこれらの雑多なもので破裂してしまうだろう。"
  },
  Event_129264_Name = {
    Text = "思考の万華鏡"
  },
  Event_129265_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129266_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129267_ChoiceDesc1 = {
    Text = "【聴く】3択上位刻印を2回獲得"
  },
  Event_129267_ChoiceDesc2 = {
    Text = "【叫ぶ】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129267_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_129267_Desc = {
    Text = "事故以来、パートナーからの連絡は途絶えた。\n\n無数の連絡を試みたが、まるで石を投げたように何の反応もない。\n\n希望失いかけた時、通信機が突然音を立てた。\n\n手提げ箱を開け、受話器を耳に近づける。\n\n「守秘者……」\nぼんやりと、ずっと思い続けていた声が、遠く虚空を隔てて響いてくる。"
  },
  Event_129267_Name = {
    Text = "思い出のこだま"
  },
  Event_129268_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129269_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129270_ChoiceDesc1 = {
