  },
  Event_129270_ChoiceDesc2 = {
    Text = "【戦闘に集中する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129270_Desc = {
    Text = "地獄の番犬の輪郭が変化している。\n\nその体は壁の隙間と繋がり、怪しい幻影を見せる。"
  },
  Event_129270_Name = {
