  },
  Event_129271_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129272_ChoiceDesc1 = {
    Text = "【紙をつなぎ合わせる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129272_ChoiceDesc2 = {
    Text = "【読む】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回"
  },
  Event_129272_ChoiceDesc3 = {
    Text = "【それを捨てる】50黒章を獲得する"
  },
  Event_129272_Desc = {
    Text = "提灯教会のローブから黄ばんだ紙が落ちた。\n\n紙には奇妙な文字がびっしりと書かれており、象形文字のようなものや、奇妙に上向きのもの、重なり合った文字もあり、わずかに判読可能な文字もある。\n\nタイトルは《@2神子の誕生》"
  },
  Event_129272_Name = {
    Text = "密命・下"
  },
  Event_129273_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129274_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129275_ChoiceDesc1 = {
    Text = "【戦闘準備】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」に2回感染"
  },
  Event_129275_ChoiceDesc2 = {
    Text = "【声を出して問う】25黒章を獲得する"
  },
  Event_129275_Desc = {
    Text = "星の光が降り注ぐ深海の中で、蹈海者たちは千百年の歳月を潜伏してきた。\n無限の海水は彼らの狂気を見届け、彼らの忍耐を見届け、そして神への最も敬虔な信仰をも見届けた。\n誰も神の偉大なる降臨を阻むことはできない。\n邪魔する者は全て、蹈海者の怒りの中で灰燼と化す。"
  },
  Event_129275_Name = {
    Text = "群星の下の待機"
  },
  Event_129276_ChoiceDesc1 = {
    Text = "【数音弾く】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129276_ChoiceDesc2 = {
    Text = "【蓋を閉める】3択の刻印を2回獲得"
  },
  Event_129276_Desc = {
    Text = "壁際のピアノは蓋が開いたままになっている。\n鍵盤は黄ばんでおり、端には木の色が見えるひび割れがあったが、どの鍵盤もきれいに拭き取られていた。"
  },
  Event_129276_Name = {
    Text = "幼少期のメロディ"
  },
  Event_129277_ChoiceDesc1 = {
    Text = "【幻覚を受け入れる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129277_ChoiceDesc2 = {
    Text = "【幻覚を否定する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129277_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_129277_Desc = {
    Text = "重厚で暗い鉄橋の下、葦が生い茂る静かな河原に、突然光る蝶が飛び出した。\n\n蝶は軽やかにあなたの手のひらに舞い降り、騒がしい叫び声が止み、代わりに鉄筋を運ぶ作業員の掛け声、ハンマーの攻撃音、リベットの金属音が響く……"
  },
  Event_129277_Name = {
    Text = "鋼橋の幻覚"
  },
  Event_129278_ChoiceDesc1 = {
    Text = "【呪いを見せる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」を2回、「(Skill.Arg2)」を2回感染"
  },
  Event_129278_ChoiceDesc2 = {
    Text = "【カラスを拒む】3択刻印を2回獲得"
  },
  Event_129278_ChoiceDesc3 = {
    Text = "【無視する】"
  },
  Event_129278_Desc = {
    Text = "漆黒で病的な多頭のカラスが提灯教会の黒いローブから飛び出し、あなたの肩に止まった。\n\n「私の頭を見たか？呪いを味わえば、新しい頭が生えてくる。\n見せてくれ、君の呪いを！」"
  },
  Event_129278_Name = {
    Text = "呪われた怪鳥"
  },
