  Event_129283_ChoiceDesc1 = {
    Text = "【占位】一時的なテキスト。"
  },
  Event_129900_ChoiceDesc1 = {
    Text = "【埋葬】Arg2ライフを回復する[ExDesc1]、指令カードを1枚選択して削除する"
  },
  Event_129900_ChoiceDesc2 = {
    Text = "【祈祷】黄金造物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_129900_Desc = {
    Text = "蒼白の骸骨の一片が、漆黒の融蝕液に半ば沈んでいた。"
  },
  Event_129900_Name = {
    Text = "色褪せた遺骨"
  },
  Event_130337_ChoiceDesc1 = {
    Text = "【着席する】「操り人形」をデッキに加える。"
  },
  Event_130337_Desc = {
    Text = "劇場への階段を踏みしめた瞬間、あなたはこの舞台から視線をそらせなくなった。\n運命の糸が無数の物語を紡ぐ――過去の塵、今この瞬間の光と影、そして未来の霧。それらすべてが、舞台の上で絶え間なく渦巻いている。\nあなたは、自分がどこから来て、どこへ向かおうとしていたのか忘れてしまった。幕の陰で、わずかに残った「自我」がすべて溶け去っていく。今、あなたは客席で静かに見つめる観客であり、舞台上で燃え上がる役者でもある。\nあなたの存在は、二つの痕跡だけを残して崩れ落ちていく。見つめること、そして演じること。"
  },
  Event_130337_Name = {
    Text = "運命の舞台"
  },
  Event_131264_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_131264_Desc = {
    Text = "あなたたちは力を選んだ。揺るぎない信念と、ひたすら前へ進む勇気を選んだ。\nだが、代償…………代償が存在する意味は、受け入れるためにあるのではないだろうか？"
  },
  Event_131264_Name = {
    Text = "過去の凝望"
  },
  Event_131265_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_131265_Desc = {
    Text = "あなたは脳裏の痛みに耐えながら、散りゆく砕けた記憶を力いっぱい握りしめた。あなたの懸命な忍耐の下、亀裂は少しずつ縫い合わされていった。\nあなたは銘記するために旅立ち、銘記するために戦う。いかなる記憶も自分から離れることを許さない。"
  },
  Event_131265_Name = {
    Text = "砕けた記憶"
  },
  Event_131266_ChoiceDesc1 = {
    Text = "【記憶を守る】3択から1つ刻印を獲得"
  },
  Event_131266_ChoiceDesc2 = {
    Text = "【裂け目を阻止する】3枚の指令カードから1枚を選び刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_131266_Desc = {
    Text = "あなたは自分の記憶を疑ったことがなかった。それらは温かく、堅固で、最も頼れる港であり、最も大切な宝物だった。\nだが今、淵獄の干渉の下、それらの記憶に乱れた亀裂が現れ始めた。"
  },
  Event_131266_Name = {
    Text = "砕けた記憶"
  },
  Event_131267_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_131267_Desc = {
    Text = "精神の力が脳裏に流れ込み、恐ろしい裂け目を修復していく。あなたは全力を尽くし、ついにそれらの亀裂を元通りにした。\nあなたは銘記するために旅立ち、銘記するために戦う。いかなる記憶も自分から離れることを許さない。"
  },
  Event_131267_Name = {
    Text = "砕けた記憶"
  },
  Event_131268_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_131268_Desc = {
    Text = "「うぅぅぅぅ…………あはははは！！」\n誰もあなたの問いかけを理解せず、泣き叫びと甲高い笑いで応えた。"
  },
  Event_131268_Name = {
    Text = "見捨てられし者"
  },
  Event_131269_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_131269_Desc = {
    Text = "あなたたちはそれらを見つめ返した。糸が弾かれ、優しい眼差しが記憶を抱きしめた。\nあなたは黙ってその運命の操り手を見つめた。もしもう一度やり直せるなら、彼女はどんな選択をするのだろうか？"
  },
  Event_131269_Name = {
    Text = "過去の凝望"
  },
  Event_131270_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_131270_Desc = {
    Text = "「うぅぅぅぅ…………あはははは！！」\n泣き叫びと甲高い笑いがあなたの前で次第に消えていった。魂魄は誰も傷つけに来なかった――彼らはとうに無視されることに慣れていたのだ。"
  },
  Event_131270_Name = {
    Text = "見捨てられし者"
  },
  Event_131271_ChoiceDesc1 = {
    Text = "【記憶を見つめる】黄金造物「(RelicConfig.Arg1)」を獲得、「(Skill.Arg2)」に感染"
  },
  Event_131271_ChoiceDesc2 = {
    Text = "【記憶を忘れる】ランダムに覚醒体2名を覚醒、【(Skill.Arg1)】に2回感染"
  },
  Event_131271_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_131271_Desc = {
    Text = "少女の体の中で、壺が砕ける音が聞こえた。記憶がその器を離れ、あなたたちのもとへやってきた。\n幼い頃の遊び仲間、両親からの贈り物、白い雲と飛ぶ鳥への最も純粋な想像、空のように白く清らかな理想…………すべての記憶が目を開き、静かにあなたたちを見つめている。\nそれらは問いかける。それらは泣く。それらは待っている。"
  },
  Event_131271_Name = {
    Text = "過去の凝望"
  },
  Event_131272_ChoiceDesc1 = {
    Text = "【尋ねる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_131272_ChoiceDesc2 = {
    Text = "【無視する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_131272_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_131272_Desc = {
    Text = "鋭い泣き叫びが耳元に響き、苦悶する魂魄が目の前で自らの顔と体を引き裂いている…………\n彼らは誰なのか？淵獄の囚人？見捨てられた運命？埋もれた記憶？"
  },
  Event_131272_Name = {
    Text = "見捨てられし者"
  },
  Event_133380_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_133380_Desc = {
    Text = "あなたはベルベットの座席に腰を下ろした。深紅の幕が静かに開く。\n親愛なる観客の皆様、どうぞご期待ください。\nこの演目の主役は、すでに舞台へ上がっております。"
  },
  Event_133380_Name = {
    Text = "運命の舞台"
  },
  Event_141995_ChoiceDesc1 = {
    Text = "【簡単な試み】任意のカードを最大 5 枚削除"
  },
  Event_141995_ChoiceDesc2 = {
    Text = "【彼に研究させる】ランダムに指令カードを 5 枚削除し、祝福された遺物「(RelicConfig.Arg1)」を獲得する。"
  },
  Event_141995_ChoiceDesc3 = {
    Text = "【逆転の発想？】覚醒体を最大 2 体選択し、彼らの基本カード一式を生成してデッキに加える"
  },
  Event_141995_Desc = {
    Text = "あなたは広場へとやって来た。多くの人が足早に行き交っており、ここで何か面白いものが見つかるかもしれない。\nあなたが薄暗い灯りの灯る部屋のドアをノックすると、研究員風の人物が顔を覗かせた。見知らぬ科学器械が数多く並んでいるのが見え、彼はあなたを引っ張って座らせ、自分は「進化学者」だと名乗った。彼は狂熱的な表情で、自らの「科学的手法」を熱心に勧めてきた。\n「人間に備わる無趣味な冗長を削ぎ落とすことこそ、真の進化への道だ！」"
  },
  Event_141995_Name = {
    Text = "進化学者"
  },
  Event_141996_ChoiceDesc1 = {
    Text = "【攻撃に特化した特訓】刻印を持たないすべての基礎打撃にランダムな刻印を付与する"
  },
  Event_141996_ChoiceDesc2 = {
    Text = "【防御に特化した特訓】刻印を持たないすべての基礎防御にランダムな刻印を付与する"
  },
  Event_141996_ChoiceDesc3 = {
    Text = "【がむしゃらな特訓】ランダムな指令カード15枚にランダムな刻印を付与し、ランダムな症状カードを5枚獲得する"
  },
  Event_141996_Desc = {
    Text = "あなたは広場にやって来た。多くの人が足早に行き交っており、ここで何か面白いものが見つかるかもしれない。\n金属がぶつかり合う澄んだ音が空き地に反響し、数人がここで互いに腕を競い合い、武芸を磨いている。古い鎧を身にまとった若者があなたに気づき、剣を一本投げてよこし、一緒に鍛錬するよう招待した。"
  },
  Event_141996_Name = {
    Text = "特訓の時間"
  },
  Event_141997_ChoiceDesc1 = {
    Text = "【大を押す】50%の確率でランダムな刻印を獲得して再ベット、50%の確率で 75 ブラックスタンプを獲得"
  },
  Event_141997_ChoiceDesc2 = {
    Text = "【小を押す】50%の確率でランダムな刻印を獲得して再ベット、50%の確率で 75 ブラックスタンプを獲得"
  },
  Event_141997_Desc = {
    Text = "給仕は変わらぬ笑みを保ちながら、サイコロカップを持ち上げた。澄んだ音が反響し、他のプレイヤーたちはそれぞれの選択をした。「ベットは締め切りました。」と彼は言った、「さあ、賭けてください——」"
  },
  Event_141997_Name = {
    Text = "喧騒のカジノ"
  },
  Event_141998_ChoiceDesc1 = {
    Text = "【素直に賭ける】指令カードを1枚削除する"
  },
  Event_141998_ChoiceDesc2 = {
    Text = "【イカサマを試みる】症状カードを1枚削除する"
  },
  Event_141998_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_141998_Desc = {
    Text = "あなたは非常に賑やかな場所にやって来た。人々の顔には幸福が溢れ、縦横無尽に閃く色とりどりの灯りが夜の闇を追い払っている。そして至る所に掲げられた看板にはこう書かれていた：「カーニバルへようこそ！ここでは夢が永遠に続き、歓喜は決してフィナーレを迎えない！」\n押し合いへし合いする人の波に揉まれながら、あなたはある豪華な建物へと押し込まれた。ホール内は金色に輝き、人々の声が飛び交い、空気には甘ったるい酒の香りが漂っている。一つのサイコロがころころとあなたの足元まで転がってきた。給仕は媚びた笑みを浮かべ、これは幸運の象徴だと告げた。好奇心を胸に、あなたは一歩前へ踏み出す——もしかしたら、このゲームで腕前を存分に発揮できるかもしれない。"
  },
  Event_141998_Name = {
    Text = "喧騒のカジノ"
  },
  Event_141999_ChoiceDesc1 = {
    Text = "【物々交換】遺物を1個取り除き、50%の確率で3択の高級遺物を獲得、50%の確率で25ブラックスタンプを獲得"
  },
  Event_141999_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_141999_Desc = {
    Text = "あなたはとても賑やかな場所にやって来た。人々の顔には幸福が溢れ、縦横無尽に閃く色とりどりの灯りが夜の闇を追い払っていた。そして至る所に見える看板にはこう書かれていた：「カーニバルへようこそ！ここでは夢に終わりなく、歓喜にフィナーレなし！」\n群衆の中で、ぼろをまとっているが驚くほど大きな荷物を背負った商人があなたに手を振った。彼は傍らの荷物を叩き、近づいて声を潜め、物々交換の招待をあなたに持ちかけた。その古びた布の袋は彼の話し声に合わせてゆらゆらと揺れ、時折カタカタと音を立てていた。"
  },
  Event_141999_Name = {
    Text = "ぼろをまとった行商人"
  },
  Event_142000_ChoiceDesc1 = {
    Text = "【願いを込めてみる】現在のライフの50%を消費し、ランダムな高級遺物を2個獲得"
  },
  Event_142000_ChoiceDesc2 = {
    Text = "【全身全霊で願う】現在のライフの99%を消費し、時の振り子「(RelicConfig.Arg2)」を獲得する"
  },
  Event_142000_ChoiceDesc3 = {
    Text = "【手を伸ばして池の底を探る】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_142000_Desc = {
    Text = "風が野原を吹き抜け、あたりは静まり返り、木々のざわめきだけが響いていた。\n突然、あなたは何かがゆったりと流れる音を耳にし、音を辿って進むと、濃厚な血の甘い香りが先に漂ってきた。ようやくあなたはその水音の源を見極めた——それは願い事の池で、赤い色に満ち溢れ、無数の人々の血液が池の中でサージし、まるで水面の下から何かが飛び出そうとしているかのようだった。\n声があなたの心の奥底に響いた：「あなたの血を捧げよ、恵みを授けよう。」"
  },
  Event_142000_Name = {Text = "血の泉"},
  Event_142001_ChoiceDesc1 = {
    Text = "【簡単に供養する】遺物を2個削除することを選び、罪の遺物「(RelicConfig.Arg1)」を獲得"
  },
  Event_142001_ChoiceDesc2 = {
    Text = "【信仰を込めて供養する】遺物を4個削除することを選び、祝福された遺物「(RelicConfig.Arg1)」を獲得"
  },
  Event_142001_ChoiceDesc3 = {
    Text = "【供物をちょっと拝借、誰も知らない】高級遺物「(RelicConfig.Arg1)」を獲得"
  },
  Event_142001_Desc = {
    Text = "風が野原を吹き抜け、あたりは静まり返り、木々のざわめきだけが響いていた。\nいつの間にか、あなたは古い祭壇の前に立っていた。巨大な彫像が高みからあなたを凝視し、あなたの手から何かを奪い取ろうとしているかのようだった。祭壇の真下にはかすれた文字が刻まれていた——「得失相称」。"
  },
  Event_142001_Name = {
    Text = "得失の祭壇"
  },
  Event_142002_ChoiceDesc1 = {
    Text = "【無料体験】ランダムに Arg2 個の低級遺物をアップグレード"
  },
  Event_142002_ChoiceDesc2 = {
    Text = "【通常サービス】Arg1 ブラックスタンプを消費：ランダムに Arg2 個の低級遺物をアップグレード"
  },
  Event_142002_ChoiceDesc3 = {
    Text = "【豪華サービス】Arg1 ブラックスタンプを消費：ランダムに Arg2 個の低級遺物をアップグレード"
  },
  Event_142002_Desc = {
    Text = "あなたは広場へとやって来た。多くの人が足早に行き交っており、ここで何か面白いものが見つかるかもしれない。\n温かな灯りの灯る小さな建物が広場の一角に静かに佇んでいる。高級会館のようだが、壁に掲げられた濃い色の看板には「本店は生物以外の存在のみにサービスを提供する。」と書かれていた。"
  },
  Event_142002_Name = {
    Text = "特別会館"
  },
  Event_142003_ChoiceDesc1 = {
    Text = "【一回引く】症状カードを1枚獲得する"
  },
  Event_142003_ChoiceDesc2 = {
    Text = "【立ち去る】75 ブラックスタンプを獲得する"
  },
  Event_142003_Desc = {
    Text = "あなたは非常に賑やかな場所にやって来た。人々の顔には幸福が溢れ、縦横無尽に閃く色とりどりの灯りが夜の闇を追い払っている。そして至る所に掲げられた看板にはこう書かれていた：「カーニバルへようこそ！ここでは夢が永遠に続き、歓喜は決してフィナーレを迎えない！」\nあなたは道端にくじ引きの屋台があることに気づいた。人だかりができており、すべての人の眼差しが厳重に覆われた大賞に注がれていた——屋台の主人はその希少さを声高に宣伝し、人々は競って参加しようとしていた。"
  },
  Event_142003_Name = {
    Text = "くじ引きチャレンジ"
  },
  Event_142004_ChoiceDesc1 = {
    Text = "【少し借りる】"
  },
  Event_142004_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_142004_Desc = {
    Text = "風が郊外を吹き抜け、あたりは静まり返り、木々のざわめきだけが響いている。\nふと、あなたは古びた草葺きの小屋を見つけた。中央には鉄床が置かれ、傍らには錆びついた金属製の武器が数多く並んでいる。ここはずいぶん前に廃れた鍛冶屋のようだ。鉄床の横には詳しい使用説明書が置かれており、ここに遺物を置いて改造できると書かれている。"
  },
  Event_142004_Name = {Text = "鍛冶屋"},
  Event_142005_ChoiceDesc1 = {
    Text = "【素直に賭ける】指令カードを1枚削除する"
  },
  Event_142005_ChoiceDesc2 = {
    Text = "【イカサマを試みる】症状カードを1枚削除する"
  },
  Event_142005_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_142005_Desc = {
    Text = "周囲の喝采があなたの勝利を告げた。喧騒の中で、あなたもついに彼らと同じように、すべてを賭けたこの奇妙奇天烈な夢に溺れていった。手の中のチップに目を向けると、まるでそれらがあなたに栄光をもたらす最も忠実な友のように思えた。ささやきが賭けテーブルの奥から漂ってきて、ある曖昧な願いを帯びていた：「もう一度やろう、もう一度勝とう。」"
  },
  Event_142005_Name = {
    Text = "喧騒のカジノ"
  },
  Event_142013_ChoiceDesc1 = {
    Text = "【大を押す】50%の確率でランダムな低級遺物を獲得して再ベット、50%の確率で 75 ブラックスタンプを獲得してエリート戦闘に突入"
  },
  Event_142013_ChoiceDesc2 = {
    Text = "【小を押す】50%の確率でランダムな低級遺物を獲得して再ベット、50%の確率で 75 ブラックスタンプを獲得してエリート戦闘に突入"
  },
  Event_142013_Desc = {
    Text = "給仕は変わらぬ笑みを保ちながら、サイコロカップを持ち上げた。澄んだ音が反響し、他のプレイヤーたちはそれぞれの選択をした。「ベットは締め切りました。」と彼は言った、「さあ、賭けてください——」"
  },
  Event_142013_Name = {
    Text = "喧騒のカジノ"
  },
  Event_142073_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142073_Desc = {
    Text = "給仕がサイコロカップを持ち上げた。ほんの数秒、空気がまるで停滞したかのようだった。答えが明かされた瞬間、歓声と嘆きが入り混じった声が聞こえた。幸運はあなたに庇護を与えなかった。テーブルの上に静かに横たわるいくつかのサイコロは、あなたの予想とは逆の答えを示していた。あなたは最後にぐるりと見渡し、あの発狂した賭博師たちを眺めた。もう行く時だ。"
  },
  Event_142073_Name = {
    Text = "喧騒のカジノ"
  },
  Event_142074_ChoiceDesc1 = {
    Text = "【戦闘に入る】"
  },
  Event_142074_Desc = {
    Text = "あなたが期待に胸を膨らませて賭けテーブルを凝視していると、突然あなたの手がしっかりと掴まれた。顔を上げると、カジノのボスが見下ろしており、ルールを守らない客をすべて追い出そうとしていた。瞬く間に、すべての視線があなた一人に集中した——驚愕の、敵意に満ちた、嘲笑うような視線が......あなたは気づいた。人はイカサマを何度も繰り返せるかもしれないが、一度でも発見されさえすれば、完全な失墜を迎えることになるのだと。"
  },
  Event_142074_Name = {
    Text = "喧騒のカジノ"
  },
  Event_142103_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142103_Desc = {
    Text = "あなたは物理的な手段でカジノから無事に脱出した。群衆の喧騒をあなたは背後に置き去りにして、足早にその場を離れた——この惨状については、誰かが後始末をするだろう。"
  },
  Event_142103_Name = {
    Text = "喧騒のカジノ"
  },
  Event_142105_ChoiceDesc1 = {
