  },
  Event_142118_ChoiceDesc1 = {
    Text = "【物々交換】遺物を1個取り除き、25%の確率で3択の時の振り子を獲得、50%の確率でランダムな高級遺物を2個獲得、25%の確率で25ブラックスタンプを獲得"
  },
  Event_142118_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_142118_Desc = {
    Text = "商人はあなたが差し出した品を受け取り、月明かりに照らしながら何度もひっくり返して眺め、目が飛び出しそうなほど見入っていた。あなたがしばらく待つと、ようやく彼は口角を緩め、袋の中から錆びた鉄の箱を取り出した。「開けてみてください、これは今一番流行りのブラインドボックスですよ。」\nあなたはそれを開けたが、中には些かの不満足なブラックインプリントしか入っていなかった。商人は手をすり合わせ、申し訳なさそうな目でもう一度試せると告げた。"
  },
  Event_142118_Name = {
    Text = "ぼろをまとった行商人"
  },
  Event_142119_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142119_Desc = {
    Text = "商人はあなたが差し出した品を受け取り、月明かりに照らしながら何度もひっくり返して眺め、目が飛び出しそうなほど見入っていた。あなたがしばらく待つと、ようやく彼は口角を緩め、袋の中から錆びた鉄の箱を取り出した。「開けてみてください、これは今一番流行りのブラインドボックスですよ。」\nあなたはそれを開けると、中に何かが入っていた。"
  },
  Event_142119_Name = {
    Text = "ぼろをまとった行商人"
  },
  Event_142120_ChoiceDesc1 = {
    Text = "【物々交換】高級遺物を1個取り除き、50%の確率で3択の時の振り子を獲得、50%の確率で3択の祝福された遺物を獲得"
  },
  Event_142120_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_142120_Desc = {
    Text = "あなたは再びブラインドボックスを開けたが、やはり欲しいものは入っていなかった。商人は慌てて愛想笑いを浮かべ、また鉄の箱を取り出し、両手で捧げてあなたの前に差し出した。\n「怒らないでください、お客様！誓って、今度こそ最高のものが入っているはず……」そう言いながら、彼はこっそり片手を引き、あなたに向かって手のひらを広げた。「もちろん、宝物には宝物を。」"
  },
  Event_142120_Name = {
