  },
  Event_142167_Name = {Text = "鍛冶屋"},
  Event_142235_ChoiceDesc1 = {
    Text = "【堅定に前へ進む】「純粋」を獲得：すべての指令カードが20層の永久強化を獲得する"
  },
  Event_142235_ChoiceDesc2 = {
    Text = "【逃げない】「昇華」を獲得：銀の鍵の上限・狂気上限が永久に20％低下する"
  },
  Event_142235_Desc = {
    Text = "あなたの眼前に突然霧がかかり、世界がぼんやりと霞み始めた。ふと、一つの声があなたの心の奥底に響いた：\n「それでも前へ進むのか？」"
  },
  Event_142235_Name = {
    Text = "終着駅が近づく"
  },
  Event_142925_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142925_Desc = {
    Text = "会館のスタッフは報酬を受け取り、あなたに基本サービスを行った。彼らはあなたが預けた品物を真っ暗な個室へと持ち込んだ。待ち時間はさほど長くなく、彼が再び現れた時、品物はトレーの上に戻されており、以前とは少し違う様子だった。"
  },
  Event_142925_Name = {
    Text = "特別会館"
  },
  Event_142926_ChoiceDesc1 = {
    Text = "【高級遺物を一つ削除】（高級遺物が必要）"
  },
  Event_142926_ChoiceDesc2 = {
    Text = "【強化（Forged）遺物を選択可能】"
  },
  Event_142926_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_142926_Desc = {
    Text = "「遺物数量」「遺物リストを選択」のテスト"
  },
  Event_142927_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142927_Desc = {
    Text = "会館のスタッフは報酬を受け取り、あなたに豪華サービスを行った。彼らは丁重にあなたの品物を箱に収め、真っ暗な個室へと持ち込んだ。あなたはしばらく待ち続け、やがて彼が再び現れ、品物を両手で捧げるように差し出した。その表情は相変わらず穏やかだった。"
  },
  Event_142927_Name = {
    Text = "特別会館"
  },
  Event_142928_ChoiceDesc1 = {
    Text = "【最大2体の覚醒体を選び狂気を満たす】"
  },
  Event_142928_ChoiceDesc2 = {
    Text = "【覚醒体を2体選択して狂気を満たす必要がある】"
  },
  Event_142928_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_142928_Desc = {
    Text = "「条件で覚醒体を選択」のテスト"
  },
  Event_142929_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142929_Desc = {
    Text = "研究員はあなたの周りを何度も何度も回り、じっくりと観察してからようやく作業を始めた――あなたの意見を聞くことはなかった。しばらく経って、この奇妙な研究所を去ろうとした時、自分が確かに多くのものを失ったとわかった。しかし彼は手を叩いてあなたを祝福した。「これこそが進化の真髄だ！」"
  },
  Event_142929_Name = {
    Text = "進化学者"
  },
  Event_142930_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142930_Desc = {
    Text = "あなたは手を伸ばし、一面猩紅に染まった池の水の中を探り、何か役に立つものを見つけた。"
  },
  Event_142930_Name = {Text = "血の泉"},
  Event_142931_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142931_Desc = {
    Text = "声が遠ざかり、あなたの心は決意に満ち、力が湧出するのを感じる。"
  },
  Event_142931_Name = {
    Text = "終着駅が近づく"
  },
  Event_142932_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142932_Desc = {
    Text = "声が遠ざかり、あなたの心は決意に満ち、頭がより冴えわたる。"
  },
  Event_142932_Name = {
    Text = "終着駅が近づく"
  },
  Event_142933_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142933_Desc = {
    Text = "あなたは山積みの供物の中から少しだけ拝借し、すぐに立ち去った。去り際に、彫像の両眼がわずかに動いたように見えた。"
  },
  Event_142933_Name = {
    Text = "得失の祭壇"
  },
  Event_142934_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142934_Desc = {
    Text = "あなたは防御方向に焦点を当てた訓練を行い、相手の奇襲に対して武器で絶えず防ぎ続けた。防御能力と反応速度がともに向上した。"
  },
  Event_142934_Name = {
    Text = "特訓の時間"
  },
  Event_142935_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142935_Desc = {
    Text = "研究員は手袋をはめ、棚から奇妙な形の器械をいくつか取り出し、あなたの前で一通り動かしてみせた。彼が一体何をしたのかはわからないが、確かに少し楽になった気がした。"
  },
  Event_142935_Name = {
    Text = "進化学者"
  },
  Event_142936_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142936_Desc = {
    Text = "あなたは特定の方向を定めず、自分の身体の限界を顧みることなく他者と打ち合い、すべての人が疲弊し果てるまで続けた。自分がかなり上達したことはわかっているが、同様に、代償も払った。"
  },
  Event_142936_Name = {
    Text = "特訓の時間"
  },
  Event_142937_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142937_Desc = {
    Text = "あなたは袋から適当に何かを取り出して供養し、相応の褒美を得た。"
  },
  Event_142937_Name = {
    Text = "得失の祭壇"
  },
  Event_142938_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142938_Desc = {
    Text = "あなたは貴重な供物を捧げ、相応の褒美を得た。"
  },
  Event_142938_Name = {
    Text = "得失の祭壇"
  },
  Event_142939_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142939_Desc = {
    Text = "あなたは彼の研究手法に疑問を抱き、一番議論した末、彼はあなた自身がこれらの器械を使い、別の方法で「進化」を追求することに同意した。\n同じ道具を使いながら、あなたは偶然にも「削除」されるはずだったものを大量に「増殖」させてしまい、立ち去る間際、研究員の嘆き声が聞こえた。"
  },
  Event_142939_Name = {
    Text = "進化学者"
  },
  Event_142940_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142940_Desc = {
    Text = "会館のスタッフがあなたに無料サービスを行った。彼らはあなたが預けた品物を真っ暗な個室へと持ち込み、しばらくして戻ってくると、何も言わずに品物をあなたの手に返した。"
  },
  Event_142940_Name = {
    Text = "特別会館"
  },
  Event_142941_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142941_Desc = {
    Text = "あなたは願い事の池に大量の血液を捧げ、貴重な贈り物が池の中から浮かび上がった。"
  },
  Event_142941_Name = {Text = "血の泉"},
  Event_142942_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142942_Desc = {
    Text = "あなたは攻撃方向に向けた訓練を行い、鋼鉄のぶつかり合いの中で、打撃の技術と速度が向上した。"
  },
  Event_142942_Name = {
    Text = "特訓の時間"
  },
  Event_142943_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_142943_Desc = {
    Text = "あなたは願い事の池に少量の血液を捧げ、池の中から贈り物が浮かび上がった。"
  },
  Event_142943_Name = {Text = "血の泉"},
  Event_142944_ChoiceDesc1 = {
    Text = "【アップグレードする遺物を選択】"
  },
  Event_142944_ChoiceDesc2 = {
    Text = "【ランダムに遺物をアップグレード】"
  },
  Event_142944_ChoiceDesc3 = {
    Text = "【離れる（テスト）】"
  },
  Event_142944_Desc = {
    Text = "「遺物アップグレード機能」のテスト、遺物自身が追加"
  },
  Event_146258_ChoiceDesc1 = {
    Text = "【彼を呼びかける】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146258_ChoiceDesc2 = {
    Text = "【それらに応える】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_146258_ChoiceDesc3 = {
    Text = "【無視】50黒章を獲得るる"
  },
  Event_146258_Desc = {
    Text = "祭壇の上で、ジュリエットの白衣が濃い煙の中に沈み、香の灰に甘く生臭い匂いが混じっていた。\n「光の持ち主は世の罪人を憐れみたもう、」その声は高くはなかったが、堂内に満ちるざわめくような祈りの声を明確に圧し、「慈しみ深き母が、産着に包まれた赤子を憐れむように。」\n祭台の供物は燭火の中で脂ぎった光を帯び、幾筋もの青い煙がその輪郭に沿ってゆらゆらとのぼり、台下の人々の顔を霞ませた。\nカストルは揺れる煙越しにポリュクスを見つめた。彼は信者たちの中に立ち、目を伏せ、訓練によって作り上げられた、ほどよい敬虔さを顔に貼りつけていた。"
  },
  Event_146258_Name = {
    Text = "古き夢 Ⅲ"
  },
  Event_146259_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146259_Desc = {
    Text = "気にするな、ただの雪風の咆哮、氷湖の嘆息、あるいは峰々の哀悼に過ぎない。\n枯れ果てた枯れ枝が、互いに擦れ合うさざめきだ。\nそれらは永遠に哀切に呟き続ける、かつて氷の裂け目に葬られたすべての先駆者たちのために。"
  },
  Event_146259_Name = {
    Text = "氷湖のアリア"
  },
  Event_146260_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146260_Desc = {
    Text = "絶対的な平等が公平なら、血鎖・ヘロットはあなたたちと平等に願いを叶える機会を持つのか？\nそして、彼女に先を越され競争相手まで追い払われたことに、あなたは淡々と受け入れるべきなのか？\n「それより余計なことを考えるのをやめて、さっさと登り続けなさい！」耳元にカラブの呼びかけが響いた。"
  },
  Event_146260_Name = {
    Text = "荒唐な公平"
  },
  Event_146261_ChoiceDesc1 = {
    Text = "【山は飢餓を恐れる】"
  },
  Event_146261_ChoiceDesc2 = {
    Text = "【山は喪失を恐れる】"
  },
  Event_146261_ChoiceDesc3 = {
    Text = "【山は死を恐れる】"
  },
  Event_146261_Desc = {
    Text = "あなたは山の体の上を歩く。\n山の震えが、その秘密を暴いた。\n山の貪欲さが、山の恐怖を決めた。"
  },
  Event_146261_Name = {
    Text = "山の秘密"
  },
  Event_146262_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146262_Desc = {
    Text = "あなたは滑らかで柔らかな毛並みを楽しみながら、自らの欲望に囚われていた。\nその手触りに満足していた。\n表象の下に何があるかなど、本当に重要なのだろうか？"
  },
  Event_146262_Name = {
    Text = "忍び歩く黒猫"
  },
  Event_146263_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146263_Desc = {
    Text = "あなたは静かに赤い紐の端を受け取り、自分の手首に結んだ。\nポリュクスも同じようにして、二人の子供の手はすぐに細い赤い紐で繋がれた。\n同じ時間で探せる範囲は狭くなったが、あなたたちは運命を共にするのだから、そうじゃないか？\n残りは、運命に委ねよう。"
  },
  Event_146263_Name = {
    Text = "古き夢 Ⅰ"
  },
  Event_146264_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146264_Desc = {
    Text = "「これがどれほど辛いことか、もちろん分かっているよ、愛しい子よ。」\n「でも、世界は誰にとっても決して易しくはなかった。」\n「いつかあの蝶はあなたの掌から飛び立ち、そして二度と戻らないだろう。」"
  },
  Event_146264_Name = {
    Text = "幻にして真ならず"
  },
  Event_146265_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146265_Desc = {
    Text = "ウィリアムは目を上げ、視線があなたをさっと掠めてから、遠くの雪に覆われた山稜へと落ちた。\n「君は謝るようなことは何もしていない、」と彼は真剣な口調で言った。「いくつかの問いは私自身のものであり、私自身が答えるしかない。」\n「だが、君の鋭さと洞察に感謝する。」"
  },
  Event_146265_Name = {
    Text = "優しき沈没"
  },
  Event_146266_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146266_Desc = {
    Text = "ウィリアムの眼差しが揺れた。\nあなたは口を開きかけたが、何も言わなかった。沈黙が今この瞬間の最善の選択だ。\n二人の間にはまだ大切な無言の了解がある。それを壊してはいけない。"
  },
  Event_146266_Name = {
    Text = "優しき沈没"
  },
  Event_146267_ChoiceDesc1 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_146267_Desc = {
    Text = "「返せ、返せ、それは私の力だ！」\n山は泣き叫び、山は嘆き悲しむ。\n山は耐えられない、かつて持っていたすべてが奪い尽くされた。"
  },
  Event_146267_Name = {
    Text = "山の秘密"
  },
  Event_146268_ChoiceDesc1 = {
    Text = "【逃げ続ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染する"
  },
  Event_146268_ChoiceDesc2 = {
    Text = "【機会を待つ】3択の刻印を獲得する"
  },
  Event_146268_ChoiceDesc3 = {
    Text = "【ゆっくりと立ち去る】"
  },
  Event_146268_Desc = {
    Text = "「お兄ちゃん、気をつけて、カラスが見ている。」\n少年のカストルはポリュクスを背負って急ぎ足で進み、怯えた目で怪しい場所を一つ一つ確かめたが、何も見つからなかった。\n「上だ。」\nあなたは全身を震わせ、顔を上げた。\n軒先の影の中に、一羽のカラスが静かに蹲っており、四方八方に向いた奇妙な目がいっせいにあなたを見つめていた。"
  },
  Event_146268_Name = {
    Text = "古き夢 Ⅱ"
  },
  Event_146269_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146269_Desc = {
    Text = "訓練中の言いつけを胸に刻み、安全ロープに頼ってはならないと自らに言い聞かせた。\n踏ん張りながら、なんとか体勢を保つ。\nだがザックの中の何かが山壁を転がり落ち、見えないほど小さな点となって消えた。\nもう構わない――少なくとも、まだ生きている。"
  },
  Event_146269_Name = {
    Text = "無音の墜落"
  },
  Event_146270_ChoiceDesc1 = {
    Text = "【耳を澄ます】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146270_ChoiceDesc2 = {
    Text = "【耳を塞ぐ】3つの中から1つ刻印を獲得する"
  },
  Event_146270_Desc = {
    Text = "吹雪が岩壁に叩きつけられ、氷層の奥から伝わるかすかな亀裂の音と混ざり合い、途切れ途切れのすすり泣きへと砕け散る。\n人気のない高みに立ち、ふと山の旋律が聞こえてきた。\nそれは荒涼として厳かで、死者だけのための歌を低く吟じていた。"
  },
  Event_146271_ChoiceDesc1 = {
    Text = "【鈴の音だ】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印を獲得：「(EnchantConfig.Arg2)」"
  },
  Event_146271_ChoiceDesc2 = {
    Text = "【食べ物だ】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印を獲得：「(EnchantConfig.Arg2)」"
  },
  Event_146271_ChoiceDesc3 = {
    Text = "【犬の期待だ】ランダムな指令カード1枚が刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_146271_Desc = {
    Text = "「パブロフはベルを鳴らし、それから犬に餌を与えた。それを繰り返すうちに、ベルを鳴らすだけで犬は唾液を分泌するようになった。」\n「では、犬に唾液を分泌させたのは、一体何だったのか？」"
  },
  Event_146271_Name = {
    Text = "パブロフの反射"
  },
  Event_146272_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146272_Desc = {
    Text = "思い出すな。\nウィリアムは手の届く距離にいる。\n苦しみに飲み込まれるな。\n多くを見逃してきたが、まだ間に合う。"
  },
  Event_146272_Name = {
    Text = "彼岸より来たる"
  },
  Event_146273_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146273_Desc = {
    Text = "「手のひらを閉じてみなさい。」\n「かつて美しかったものも、あなたの掌の中では黒い泥の塊になるだけだ。」"
  },
  Event_146273_Name = {
    Text = "幻にして真ならず"
  },
  Event_146274_ChoiceDesc1 = {
    Text = "【元に戻る】ブラックスタンプを50獲得する"
  },
  Event_146274_ChoiceDesc2 = {
    Text = "【撫でる】ブラックスタンプを75獲得する、「(Skill.Arg2)」に感染する"
  },
  Event_146274_Desc = {
    Text = "「にゃあ。」緑色の瞳を持つ黒猫が、柔らかな足取りであなたのすねに擦り寄ってきた。\nそれと同時に、「N」の姿が消えた。"
  },
  Event_146274_Name = {
    Text = "忍び歩く黒猫"
  },
  Event_146275_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146275_Desc = {
    Text = "声は出さず、ただその視線が煙を越えてポリュクスの目の奥へと落ちるままに任せ、一寸も動かそうとしなかった。\n彼も逸らさなかった。弟はいつもそうだ――頑固さを最も深いところに隠し、先に頭を下げることを決してしない。\n堂内の詠唱の声も、香灰の匂いも、慈悲と犠牲についてのジュリエットの言葉も、突然遠くなった。まるで二人だけが残されたかのように、偽りの憐れみに満ちた堂を隔て、長い時の流れを隔て、互いに見つめ合っていた。"
  },
  Event_146275_Name = {
    Text = "古き夢 Ⅲ"
  },
  Event_146276_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146276_Desc = {
    Text = "今この瞬間、あなたは自らの蒼白く長い記憶の唯一の番人だった。\nウェンディゴは枯れ枝のような手を伸ばし、指先があなたの胸元に迫ったが、最後の瞬間にあなたは力ずくでそれを押し返した。\nそれはよろめきながら霧の中へと退き、低くしゃがれたうわ言だけを残した――\n「お前はいずれ、自ら進んでそれらをすべて私に渡すことになる……」"
  },
  Event_146276_Name = {Text = "貪食者"},
  Event_146277_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146277_Desc = {
    Text = "それは遠い夢、幼年期と呼ばれる夢だった。\n少し目を覚ませ。あなたはそこにいない。\nあなたは吹雪の中にいる。幾重にも重なるランタン信者に囲まれ、ポリュクスの刃の切っ先があなたの胸に向けられている。"
  },
  Event_146277_Name = {
    Text = "古き夢 Ⅰ"
  },
  Event_146278_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146278_Desc = {
    Text = "「私は死の訪れを受け入れる。」\n「苦難の旅路に葬られることを厭わない。」\n「絶壁の下、天地が私のために碑を刻む。」"
  },
  Event_146278_Name = {
    Text = "死兆迫る"
  },
  Event_146279_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146279_Desc = {
    Text = "倒影とは光の反射現象に過ぎない。\nティンクトが見ているのも、おそらく自分自身の影に過ぎないだろう。\n彼女の母星は何千万光年も彼方にあり、わずかな航路のずれでも、全く異なる星系へと落ちてしまう。\nそう自分に言い聞かせ、あなたは足元の倒影へのこだわりを手放した。"
  },
  Event_146279_Name = {
    Text = "湖底の倒影"
  },
  Event_146280_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146280_Desc = {
    Text = "群星より。太古より。人類がまだ知らず、あるいは永遠に知ることのないものより。\n祂に答えを求めるな。\nその代償を、お前は知らない。"
  },
  Event_146280_Name = {
    Text = "氷湖のアリア"
  },
  Event_146281_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146281_Desc = {
    Text = "足を止め、その荒涼とした楽音が耳に満ちるままに任せた。\n風の音はヴァイオリン、雪粒は太鼓の音、遠くで氷層が崩れる轟きは、長く抑えられてきた低く重い和音。\nその主題は聞き取れなかったが、それが過去にも未来にも、この地に葬られた無数の旅人のために繰り返し奏でられるのだと、確かに知っていた。"
  },
  Event_146283_ChoiceDesc1 = {
    Text = "【天光を仰ぎ見る】すべての覚醒体がArg1の狂気を回復する"
  },
  Event_146283_ChoiceDesc2 = {
    Text = "【氷峰を踏みしめる】覚醒体2体を選んで覚醒させる"
  },
  Event_146283_Desc = {
    Text = "山頂は雲霧の中で静かに光を放っている。\n山谷、岩壁、嵐——ここに居座るものは、人のために存在したことなど一度もない。\nその中にいると、あなたはなんと脆いことか。"
  },
  Event_146283_Name = {
    Text = "頂点に触れる"
  },
  Event_146284_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146284_Desc = {
    Text = "「いいえ、あなたのせいじゃない。」\n「あなたはただ、ねじを巻かれた、運命のおもちゃに過ぎないのだから。」"
  },
  Event_146284_Name = {
    Text = "食いしん坊ネズミ"
  },
  Event_146285_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146285_Desc = {
    Text = "「なるほど、あなたは客観的な経験をまとめるのが得意なタイプね。でも忘れないで、時には似たような表象の裏に、実は異なる可能性が潜んでいることもあるのよ。」鈴の音は笑いながら遠ざかっていった。"
  },
  Event_146285_Name = {
    Text = "パブロフの反射"
  },
  Event_146286_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146286_Desc = {
    Text = "善悪に報いがあることが公平なら、善悪を裁くのは誰か？\nアヌビスの天秤がそれを担うのか？\n冥界の重力が物理法則に従うなら、自分の心臓があの羽より軽いという自信は、正直なところない。"
  },
  Event_146286_Name = {
    Text = "荒唐な公平"
  },
  Event_146287_ChoiceDesc1 = {
    Text = "【問い詰める】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146287_ChoiceDesc2 = {
    Text = "【沈黙する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146287_ChoiceDesc3 = {
    Text = "【謝罪する】ブラックスタンプを25獲得する"
  },
  Event_146287_Desc = {
    Text = "「ウィリアム先輩、みんながウェンディゴに惑わされていた時、あなたが一番最初に正気に戻ったみたいでした。これからウェンディゴの群れと正面から戦うことになりますが、何か秘訣を教えてもらえますか？」\nウィリアムの瞳がかすかに揺れ、その眼差しの奥に、捉えどころのない茫然と、悲しみと、静けさが垣間見えた。\n光の差し込む海水に浸されながら、暗い海底へとゆらゆら沈んでいくような。\n「申し訳ないが、力になれることは何もなさそうだ。」"
  },
  Event_146287_Name = {
    Text = "優しき沈没"
  },
  Event_146288_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146288_Desc = {
    Text = "「情け知らずめ、情け知らずめ。」黒い影が首を振りながら現れた、「真実は骨まで刺す毒となりうる。時には幻象を受け入れる方が、今の幸せを保てるのではないか？」"
  },
  Event_146288_Name = {
    Text = "忍び歩く黒猫"
  },
  Event_146290_ChoiceDesc1 = {
    Text = "【犯人は誰だ】「(Skill.Arg1)」に感染し、ランダムなカード1枚が刻印を獲得：「(EnchantConfig.Arg2)」"
  },
  Event_146290_ChoiceDesc2 = {
    Text = "【私のせいだ】「(Skill.Arg1)」に感染し、ランダムなカード1枚が刻印を獲得：「(EnchantConfig.Arg2)」"
  },
  Event_146290_ChoiceDesc3 = {
    Text = "【食いしん坊の代償】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_146290_Desc = {
    Text = "「小さなネズミ、這え這え這え。下水道は暗くて長い。ふと漂うチーズの香り。」\n「小さなネズミ、チーズを引きずり、家へと走る。頭がぐるぐる、頭がぐるぐる。」\n「扉を開けて、扉を開けて、家の中はしんと静まり返っている。」\n「兄弟たちが床に横たわり、お腹にはみんな穴が一つ、穴が一つ。」"
  },
  Event_146290_Name = {
    Text = "食いしん坊ネズミ"
  },
  Event_146291_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146291_Desc = {
    Text = "あなたはしゃがみ込み、彼女の頬の涙を拭ってやったが、その涙が本物かどうかは問わなかった。\n「本物でも偽物でも、」あなたは言った、「誰かに証明する必要なんてない。」\nカラブは口を開きかけたが、用意していたはぐらかすような軽口は、結局言葉にならなかった。\n彼女の涙は何の前触れもなく溢れ出し、あなたの手の甲に落ちた。"
  },
  Event_146291_Name = {
    Text = "ワニの涙"
  },
  Event_146292_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146292_Desc = {
    Text = "「聞かない方がいいよ。答えを知る必要のない問いもあるから。」"
  },
  Event_146292_Name = {
    Text = "食いしん坊ネズミ"
  },
  Event_146293_ChoiceDesc1 = {
    Text = "【声を上げて注意する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146293_ChoiceDesc2 = {
    Text = "【聴き続ける】すべての覚醒体の狂気を50回復し、「(Skill.Arg1)」に感染する"
  },
  Event_146293_ChoiceDesc3 = {
    Text = "【肩をすくめて無視する】3択から1つ刻印を獲得する"
  },
  Event_146293_Desc = {
    Text = "ナラカが墜落した地には、ただ闇だけがある。\n泥濘の中から湿った旋律が流れてくる。まるで冷たく蒼白な両手が、あなたの頬をそっと撫でるように。\nそれは静かに囁く、「おいで、夜の静寂の中で、私のもとへ。」"
  },
  Event_146293_Name = {
    Text = "未練の声"
  },
  Event_146294_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146294_Desc = {
    Text = "頭を下げ、煙がポリュクスの輪郭を霞ませるままに任せた。今この瞬間の彼の表情も、灰白い霧の中に一緒に隠れていった。\nこれが一番安全だ――見なくていい、考えなくていい、と自分に言い聞かせた。\nジュリエットの説教が耳元で流れ続ける中、重ねた両手をじっと見つめ、一言も発しなかった。\n儀式の鐘が鳴り響いて初めて、ようやく目を上げる勇気が出た。\nポリュクスはずっと敬虔な姿勢を保ち続けていた。\n長い時の流れと幻想の向こうで、あの一瞬に何かが逃げ去ったのかどうか、わからなかった。"
  },
  Event_146294_Name = {
    Text = "古き夢 Ⅲ"
  },
  Event_146295_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146295_Desc = {
    Text = "「ポリュクス――」声が喉から飛び出しかけた瞬間、自ら死に物狂いで飲み込んだ。かすかな息の音だけが残り、香煙の中に散った。\n傍らの信者たちの読経の波は途切れなかったが、いくつかの視線がさりげなくこちらへ流れてきた。\nポリュクスはびくりと体を強張らせ、目の奥に一瞬の狼狽が走ったが、すぐにあの訓練された従順な表情で覆い隠された。\n応えることはなく、ただ目を伏せていたが、袖の中で指先がひそかに握り締められていた――聞こえていたのだと、わかった。"
  },
  Event_146295_Name = {
    Text = "古き夢 Ⅲ"
  },
  Event_146297_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146297_Desc = {
    Text = "少なくともあの瞬間、彼女が一人で隊を追われるのをただ見ていることは、あなたにはできなかった。\n今解決すべき問題は、今の自分に委ねよう。"
  },
  Event_146297_Name = {
    Text = "計略の中の計略"
  },
  Event_146298_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146298_Desc = {
    Text = "「ポリュクス、僕たちは別々の方向に行った方がいい。そうすれば、森の端を見つける確率が上がる。」\n「じゃあ、どうやって僕を見つけるの、お兄ちゃん？」\n朧げな記憶の向こうに、彼の落胆した表情が見えた。痛みが心臓を締め付ける。あなたは深く息を吸い、ゆっくりと吐き出した。\n「僕たちは双子だ。お互いの鼓動を読める。」\n「僕たちは永遠に離れない。」"
  },
  Event_146298_Name = {
    Text = "古き夢 Ⅰ"
  },
  Event_146299_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146299_Desc = {
    Text = "それは裁き、それは問い質す。それは還らぬすべての挑戦者に、冷たい死を与える。"
  },
  Event_146299_Name = {
    Text = "雪線の審判"
  },
  Event_146300_ChoiceDesc1 = {
    Text = "【やり直す】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染する"
  },
  Event_146300_ChoiceDesc2 = {
    Text = "【これは辛い】低級遺物「(RelicConfig.Arg1)」を獲得する、「(Skill.Arg2)」に感染する"
  },
  Event_146300_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_146300_Desc = {
    Text = "蠕虫が彼女に嘘を教えた。\nそれ以外に、彼女は生き延びる術を学んだことがなかった。\nしかし嘘はしょせん嘘に過ぎず、ある日からは、それに頼ることなく生きていかなければならない。"
  },
  Event_146300_Name = {
    Text = "幻にして真ならず"
  },
  Event_146301_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146301_Desc = {
    Text = "「そうね、でもあんなに小さなネズミに、食いしん坊の代償が何かなんて、わかるはずがないじゃない。」"
  },
  Event_146301_Name = {
    Text = "食いしん坊ネズミ"
  },
  Event_146302_ChoiceDesc1 = {
    Text = "【赤い糸を結ぶ】指令カードを1枚削除し、Arg1ブラックスタンプを獲得する"
  },
  Event_146302_ChoiceDesc2 = {
    Text = "【赤い糸を拒む】指令カードを1枚コピーする、「(Skill.Arg1)」に感染する"
  },
  Event_146302_ChoiceDesc3 = {
    Text = "【現実に戻る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_146302_Desc = {
    Text = "最初の夢。森の中の夢。十歳にも満たない二人の子供が、教主に深い森の中へ置き去りにされた。\n「夜になれば、眠っていた野獣たちが狩りを始める。その前に逃げ出しなさい。逃げ出せた子が、私のいい子だよ。」\n弟が彼の手を掴み、一本の赤い紐を取り出した。\n「お兄ちゃん、手を一緒に結ぼう。そうすれば、はぐれないから。」"
  },
  Event_146302_Name = {
    Text = "古き夢 Ⅰ"
  },
  Event_146304_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146304_Desc = {
    Text = "笑い声が聞こえた。\n喜びに満ちた、挑発するような、興味津々の笑い声。\n人類が全力を尽くして宇宙を探求しても、祂らの目には蟻の行進に過ぎない。"
  },
  Event_146304_Name = {
    Text = "見下される者"
  },
  Event_146306_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146306_Desc = {
    Text = "それは浄化する。それは溶かす。それは還らぬすべての登山者を己の中に取り込む。"
  },
  Event_146306_Name = {
    Text = "雪線の審判"
  },
  Event_146307_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146307_Desc = {
    Text = "あなたとカラスは膠着状態に陥った。\n明らかなことは、この対峙においてあなたが最後の勝者にはなれないということだ。\nジュリエットとの戦いにおいて、あなたたちはまるで永遠に勝者になれないかのようだった。"
  },
  Event_146307_Name = {
    Text = "古き夢 Ⅱ"
  },
  Event_146308_ChoiceDesc1 = {
    Text = "【誰が私を見ている？】ランダムな覚醒体1名を覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_146308_ChoiceDesc2 = {
    Text = "【目の前に集中する】3枚の指令カードから1枚を選んで刻印を獲得する：「(EnchantConfig.Arg1)」"
  },
  Event_146308_Desc = {
    Text = "氷雪を巻き込んだ風が、人類の足跡の最高点を轟々と吹き抜ける。\n仰ぎ見れば、さらに高い場所には太古から消えることのない太陽だけがある。\nだがもっと高く遠い場所に、無数の瞳が開いたり閉じたりしているのを知っていた。\nそのうちのいくつかが、今まさに静かに、足元の世界全体を見下ろしている。"
  },
  Event_146308_Name = {
    Text = "見下される者"
  },
  Event_146309_ChoiceDesc1 = {
    Text = "【まだ未練がある】呪われた遺物「(RelicConfig.Arg1)」を獲得する、「(Skill.Arg2)」に感染する"
  },
  Event_146309_ChoiceDesc2 = {
    Text = "【もう忘却した】ランダムな1枚のカードに刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_146309_Desc = {
    Text = "あなたは脳内の「記憶」を格納するモジュールを封じようとした。\nその秘密の匣の中には、あなたのすべてを構成する答えが隠されていた。口にするのも恥ずかしいすべての思い、人に見せたくないすべての空想が。\nしかし欲望とは潜在意識の呪縛、あなたが抗えない執着の幻夢だった。"
  },
  Event_146309_Name = {
    Text = "潜在意識の魔呪"
  },
  Event_146310_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146310_Desc = {
    Text = "ウィリアムはあなたの視線を避けた。\n「意識こそが惑わしに抗う武器だ。そして人それぞれの人生経験がその意識を形作る。代わりにはなれないし、伝授もできない。」\n「言えることがあるとすれば、弱さに飲み込まれるままにするな、ということだけだ。」"
  },
  Event_146310_Name = {
    Text = "優しき沈没"
  },
  Event_146311_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146311_Desc = {
    Text = "「なるほど、あなたは哲学者になりたいタイプね。でも忘れないで、期待がないことは、苦しみがないことと同じじゃないのよ。」鈴の音は笑いながら遠ざかっていった。"
  },
  Event_146311_Name = {
    Text = "パブロフの反射"
  },
  Event_146312_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染し、50黒章を獲得する"
  },
  Event_146312_Desc = {
    Text = "「腹が減った、腹が減った。」\n山は泣き叫び、山は嘆き悲しむ。\n山は耐えられない、その腹の中は空っぽだ。"
  },
  Event_146312_Name = {
    Text = "山の秘密"
  },
  Event_146313_ChoiceDesc1 = {
    Text = "【岩壁を蹴る】指令カードを1枚削除し、ライフを Arg1 ポイント回復する"
  },
  Event_146313_ChoiceDesc2 = {
    Text = "【安全ロープを掴む】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146313_Desc = {
    Text = "五色の幻覚が脳裏で渦を巻く。\n最初は緩んだ粉雪。\nそして崩れ落ちる雪庇。\n滑り落ちるのを止められず、安全ロープは金具との摩擦で目を刺すような火花を散らした。\nだが群山の前では、それはあまりにも小さく、脆かった。"
  },
  Event_146313_Name = {
    Text = "無音の墜落"
  },
  Event_146314_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146314_Desc = {
    Text = "「夢の中で私のもとへ来て、もう一度私の命を生き直させて。」\n蓄音機が一声嗚咽を漏らし、やがて息遣いが闇の中へと薄れていく。\n残るのは残響だけ。ただ残響だけ。"
  },
  Event_146314_Name = {
    Text = "未練の声"
  },
  Event_146315_ChoiceDesc1 = {
    Text = "【後悔の念が生まれる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_146315_ChoiceDesc2 = {
    Text = "【すべては運命の導き】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146315_Desc = {
    Text = "この旅が想像よりも単純ではないことは、ずっとわかっていた。この登山隊の登山者たちは、それぞれ腹に一物を抱えている。\nだがカラブの狂気に染まった傲慢な笑顔を見つめた時、それでも胸の中でガラスが砕けるような音が弾けた。\nナラカが彼女を隊から追い出そうとした時、別の選択をすべきだったのかもしれない。"
  },
  Event_146315_Name = {
    Text = "計略の中の計略"
  },
  Event_146316_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146316_Desc = {
    Text = "これまで何人がここに飲み込まれたのだろう？\n粘り気のある深淵が黒い手を伸ばし、あなたを彼らの世界へ引きずり込もうとする。\nだがあなたはただ前へ進む。それらも引き留める気はないようで、一つずつ退いていった。\n先にはまだ頂が待っている。"
  },
  Event_146316_Name = {
    Text = "未練の声"
  },
  Event_146317_ChoiceDesc1 = {
    Text = "【諦める】ブラックスタンプを25獲得する"
  },
  Event_146317_ChoiceDesc2 = {
    Text = "【身をかがめて確認する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_146317_Desc = {
    Text = "ティンクトの視線を追い、あなたは思わず湖底を見つめた。\nあの倒影の中に、一体何が彼女を引きつけているのか？\nだが見えない。氷面にはぼんやりと、あなた自身の影が映り込んでいるだけだった。"
  },
  Event_146317_Name = {
    Text = "湖底の倒影"
  },
  Event_146318_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146318_Desc = {
    Text = "呑み込まれることへの抵抗は、捨て去ることによってのみ可能だった。\n誰も、自分が持ったことのないものを失うことはできない。\nウェンディゴは歯を剥き出しにし、喉の奥から不満げな低い唸り声を上げながら、一歩一歩霧の中へと退いていった。"
  },
  Event_146318_Name = {
    Text = "潜在意識の魔呪"
  },
  Event_146319_ChoiceDesc1 = {
    Text = "【雪が私を浄化する】ランダムなカード1枚の刻印品質を上昇させる"
  },
  Event_146319_ChoiceDesc2 = {
    Text = "【雪が私を審判する】3枚の指令カードから1枚を選んで刻印を獲得する：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染する"
  },
  Event_146319_Desc = {
    Text = "目の前は最後の登攀。雪線は冷たく、どこまでも続いている。\n積雪は目が眩むほど白く、ここでは死さえも清潔に見える。"
  },
  Event_146319_Name = {
    Text = "雪線の審判"
  },
  Event_146320_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146320_Desc = {
    Text = "その光景のいかなる細部も見逃すな。\nそれらを脳裏に焼き付けろ。\nその瞬間に湧き上がった茫然と虚ろ、そして続いて押し寄せた苦しみも焼き付けろ。\n決して忘れるな。"
  },
  Event_146320_Name = {
    Text = "彼岸より来たる"
  },
  Event_146321_ChoiceDesc1 = {
    Text = "【共に戦う】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_146321_ChoiceDesc2 = {
    Text = "【なだめる】高級遺物「(RelicConfig.Arg1)」を獲得する、「(Skill.Arg2)」に感染する"
  },
  Event_146321_Desc = {
    Text = "山峰が激しく震え、まるで瀕死の生き物のようだった。\n節状の蒼白い肉が亀裂の入った岩盤の下から溢れ出し、一節また一節と高く伸び上がり絡み合って、カラブを激しく叩き落とした。\n再びあなたたちの前に現れた時、彼女の頬にはすでに一筋の涙が伝っていた。\nそれは苦しみの涙だったのか？\nあなたには分からなかった。\n数えきれないほどの嘘が彼女の口から語られてきた。誰がワニの涙を信じるだろうか？"
  },
  Event_146321_Name = {
    Text = "ワニの涙"
  },
  Event_146322_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146322_Desc = {
    Text = "あなたは答えを問い質すことなく、ただ彼女の傍らに立った。\n「立ちなさい、」あなたは言った、「芝居は半ばだ、途中で退場するな。」\nカラブはしばし呆然とし、それから力強く顔を拭った。\n彼女はよろめきながら立ち上がり、再び武器を握り締め、肩を並べてあの再び閉じゆく血の大口へと向かっていった。\n嘘をつきすぎて、彼女自身もどの涙が本物でどれが偽物か分からなくなっていた。\nだが少なくともこの一度は、誰も真偽を問わなかった。"
  },
  Event_146322_Name = {
    Text = "ワニの涙"
  },
  Event_146323_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146323_Desc = {
    Text = "「なるほど、あなたは表象を打ち破るのが得意なタイプね。でも忘れないで、あの瞬間の現実の中では、食べ物はあなたの経験と幻想の中にしか存在しなかったのよ。」鈴の音は笑いながら遠ざかっていった。"
  },
  Event_146323_Name = {
    Text = "パブロフの反射"
  },
  Event_146324_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146324_Desc = {
    Text = "あなたは足取りを軽く、ゆっくりにした。\nそっと、ゆっくりと、物音一つ立てずに……\nそのまま次の曲がり角を回り、こっそりと立ち去った。\nあのカラスは結局追いかけてきたのだろうか？\nもうとっくに忘れてしまった。"
  },
  Event_146324_Name = {
    Text = "古き夢 Ⅱ"
  },
  Event_146325_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146325_Desc = {
    Text = "旋律が突然途絶えた。\n黒い泥沼の中で、渇望に満ちた瞳が開く。\nその瞳は濡れたままあなたを見つめ、聞き取れない言葉を低く呟く。\nそしてゆっくりと、ゆっくりと閉じていった。"
  },
  Event_146325_Name = {
    Text = "未練の声"
  },
  Event_146326_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146326_Desc = {
    Text = "長居はせず、その旋律を背に置き去りにして、積雪を踏み砕く足音が風よりも急いた響きを立てた。\nだがどれほど速く歩いても、その荒涼とした楽音は頑なに後をついてきて、一歩も遅れなかった。\n逃げることはできない――それはこの雪山そのものの息吹であり、自分はただ偶然通りかかった、取るに足らない聴衆に過ぎないのだから。"
  },
  Event_146327_ChoiceDesc1 = {
    Text = "【それでは聴こう】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染する"
  },
  Event_146327_ChoiceDesc2 = {
    Text = "【気にしない】狂気値が50以上の覚醒体が1体いるごとに、ブラックスタンプを15獲得する"
  },
  Event_146327_ChoiceDesc3 = {
    Text = "【強制離脱】3つの刻印の中から1つを獲得"
  },
  Event_146327_Desc = {
    Text = "風に遠い歌声が混じっていた。\n歌声はあらゆる方向から、あるいは地の底から湧き上がるようだった。\nどの方向へ追いかけても、同じ強さで耳元に響き続けた。"
  },
  Event_146327_Name = {
    Text = "氷湖のアリア"
  },
  Event_146328_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146328_Desc = {
    Text = "「死兆の星よ、今はお前が輝く時ではない。」\n「私の旅路にはまだ辿り着いていない終点がある。」\n「どうか今しばらく消えていてくれ、今夜の空に安らぎを取り戻させてくれ。」"
  },
  Event_146328_Name = {
    Text = "死兆迫る"
  },
  Event_146329_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146329_Desc = {
    Text = "無意味な後悔が込み上げてくる。\n人はいつも、過去の自分が残した後始末をせざるを得ない。"
  },
  Event_146329_Name = {
    Text = "計略の中の計略"
  },
  Event_146330_ChoiceDesc1 = {
    Text = "【咀嚼】ランダムに1体の覚醒体を目覚めさせ、【(Skill.Arg1)】に感染する"
  },
  Event_146330_ChoiceDesc2 = {
    Text = "【拒否する】3つの中から1つの刻印を獲得"
  },
  Event_146330_Desc = {
    Text = "雪霧の奥深くに、骨と皮ばかりの躯が伏していた。肋骨が干からびた皮膚を持ち上げ、頭頂には枯れ枝のような二本の角が霧を突き破っていた。\nその腹から、虚ろな鳴き声が聞こえてきた。\nあなたとそれが視線を交わした刹那、深くくぼんだ眼窩の中に砕け散った映像が渦巻いた――それはあなたの記憶だった。それはすでにその味を知っていた。\n「まだ足りない、まだ足りないぞ……」それはしゃがれた声で呻き、干からびた手をあなたへと伸ばした。その仕草には、どこか縋るような色があった。"
  },
  Event_146330_Name = {Text = "貪食者"},
  Event_146332_ChoiceDesc1 = {
    Text = "【天葬】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_146332_ChoiceDesc2 = {
    Text = "【追い払う】黒印を75獲得、【(Skill.Arg2)】に感染"
  },
  Event_146332_Desc = {
    Text = "ヒゲワシが上昇気流に乗って高空を旋回し、縄張りを見回っていた。\n登山者の間では、これはいつも不吉な兆しとされている。\n「奴らは餌を探している。ハゲワシは死が近づく気配を嗅ぎつけるんだ。」"
  },
  Event_146332_Name = {
    Text = "死兆迫る"
  },
  Event_146333_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146333_Desc = {
    Text = "自分の両足を信じろ。\nお前は頂点を征服するだろう。"
  },
  Event_146333_Name = {
    Text = "頂点に触れる"
  },
  Event_146334_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146334_Desc = {
    Text = "名残惜しい思いが脳裏に駆け上がった瞬間、あなたはもはや抗う力がないと悟り、それが長らく封じられていた記憶の宝庫へと一気に踏み込むのを許すしかなかった。\n白い犬歯があなたのこめかみに差し込まれ、一コマ一コマの映像が根こそぎ引き抜かれていった。"
  },
  Event_146334_Name = {
    Text = "潜在意識の魔呪"
  },
  Event_146335_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146335_Desc = {
    Text = "それはあなたへと身を屈め、鼻先があなたの額にほとんど触れるほどに近づいた。深く陶酔した様子で、まるで蜜糖の塊を嗅ぐかのようだった。\n渦巻いていた不安な感情が、舐め取られるようにきれいさっぱり消えていった。\nそれは満ち足りた様子で鼻を鳴らしながら退き、瞳の奥に妖艶な光を揺らめかせた。\nあなたの胸の中にぽっかりと穴が空いたが、不思議なことに……ずいぶんと楽になっていた。"
  },
  Event_146335_Name = {Text = "貪食者"},
  Event_146336_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146336_Desc = {
    Text = "「足元に気をつけろ、一歩一歩しっかり踏み締めろ、」ナラカの声が耳元に響いた、「いつも誰かが尻拭いしてくれると思うな。」"
  },
  Event_146336_Name = {
    Text = "見下される者"
  },
  Event_146337_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146337_Desc = {
    Text = "人類は空に触れるべきだ。\n目標があれば危険を忘れられる。\n広大な天地が頭上であなたを待っている。"
  },
  Event_146337_Name = {
    Text = "頂点に触れる"
  },
  Event_146338_ChoiceDesc1 = {
    Text = "【記憶を払拭する】高級遺物「(RelicConfig.Arg1)」を獲得する、「(Skill.Arg2)」に感染する"
  },
  Event_146338_ChoiceDesc2 = {
    Text = "【幻想を捕らえる】3択の高級遺物を獲得する、「(Skill.Arg1)」に感染する"
  },
  Event_146338_ChoiceDesc3 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_146338_Desc = {
    Text = "ウィリアムを殺した下手人が、今まさにあなたの目の前にいる。\nアランのテントの中、吐き気を催す空気の中で、ウィリアムの青ざめた顔、宙に浮かぶ身体、そしてテーブルの上で解剖された小さなランタンが、再びあなたの脳裏に浮かび上がった。"
  },
  Event_146338_Name = {
    Text = "彼岸より来たる"
  },
  Event_146339_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146339_Desc = {
    Text = "安全ロープがぷつりと切れた。\n雪の中に重く叩きつけられ、五臓六腑が鈍い痛みの中で致命的な警鐘を鳴らす。\n目眩をこらえて目を開けると、名もなき白骨が目の前で向き合っていた。\nその虚ろな瞳の中で、何かがきらきらと輝いていた。"
  },
  Event_146339_Name = {
    Text = "無音の墜落"
  },
  Event_146340_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146340_Desc = {
    Text = "逃げられない。\nあなたは歯を食いしばり、身を翻して全力で駆け出した。速さで監視者を振り切ろうとしたのだ。\nカラスは不気味な声で鳴き、翼をはためかせ、余裕たっぷりにあなたたちの頭上をついてきた。悠々と一回りさえしてみせた。\n冷たい絶望が、その視線を通じて体の中へと染み込んでくる。\nあなたたちには、逃げられない。"
  },
  Event_146340_Name = {
    Text = "古き夢 Ⅱ"
  },
  Event_146341_ChoiceDesc1 = {
    Text = "【善悪には報いがある】ランダムな指令カード1枚に刻印を獲得する：「(EnchantConfig.Arg1)」"
  },
  Event_146341_ChoiceDesc2 = {
    Text = "【絶対平等】最大ライフを Arg1 ポイント上昇させ、「(Skill.Arg2)」に感染する"
  },
  Event_146341_Desc = {
    Text = "崖壁にぶら下がりながら、ふと脳裏に無関係な問いが浮かんだ。公平とは何か？"
  },
  Event_146341_Name = {
    Text = "荒唐な公平"
  },
  Event_146342_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染し、50黒章を獲得する"
  },
  Event_146342_Desc = {
    Text = "「私はまだ死ねない！」\n山は泣き叫び、山は嘆き悲しむ。\n山は耐えられない、その貪欲さゆえに明日の可能性を失った。"
  },
  Event_146342_Name = {
    Text = "山の秘密"
  },
  Event_146343_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_146343_Desc = {
    Text = "あなたは身を屈め、頬が氷面に触れるほど近づいた。\n骨まで刺すような寒さが皮膚から骨髄へと染み込み、思わず身震いする。\n判別しがたい何かが、凍りついた氷層の下でゆっくりと蠢いている。水流なのか、何かの生き物なのか？\nどちらであれ、あなたの旅とは無関係だ。"
  },
  Event_146343_Name = {
    Text = "湖底の倒影"
  },
  Event_148532_ChoiceDesc1 = {
    Text = "【祝福を受ける】戦闘開始後、ランダムな「万化の果実」を1枚生成し、デッキに加える。"
  },
  Event_148532_Desc = {
    Text = "果てしなく広がる雪原に、凍てつく風すら音を立てられず、どこからともなく現れた幻影がそっと近づき、温かな果実を差し出した。\n甘い香りが霧と混じり合い、旅人の凍えた鼻腔へと飛び込んでくる。\nこの雪域はとうに死に浸食され、空気には腐敗と氷の吐き気を催す臭いが漂っているというのに、掌の上のその果実だけは瑞々しく満ちており、まるで少女の甘い誘惑の約束のようだった。"
  },
  Event_148532_Name = {
    Text = "上空蜃気楼"
  },
  Event_20778_ChoiceDesc1 = {
    Text = "【彼女に渡す】すべての覚醒体がArg1狂気を獲得する"
  },
  Event_20778_ChoiceDesc2 = {
    Text = "【支援が必要だ】覚醒体を2体選択して覚醒させる"
  },
  Event_20778_Desc = {
    Text = "「こちらはミサゴからの通信です。\n覚醒体の異常な霊性指数の変動を検知しました。\n支援が必要ですか？」"
  },
  Event_20778_Name = {
    Text = "支援通信"
  },
  Event_20779_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_20779_Desc = {
    Text = "「緊急物資を送りました。\n受け取ったら胸章を3回叩いて確認してください」"
  },
  Event_20779_Name = {
    Text = "支援通信"
  },
  Event_20780_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_20780_Desc = {
    Text = "遥か未来からの幻影が、アイズルワースの山間に消えた。"
  },
  Event_20780_Name = {
    Text = "火山の幻影"
  },
  Event_20781_ChoiceDesc1 = {
    Text = "【幻影を遠くから見る】すべての覚醒体がArg1狂気を獲得する"
  },
  Event_20781_ChoiceDesc2 = {
    Text = "【幻影に近づく】覚醒体を2体選択して覚醒させる"
  },
  Event_20781_Desc = {
    Text = "遠くで火山が噴火しているように見え、暴風が吹き荒れる空に人型の煙が立ち上る。\n\nここはアイズルワースだ。\nアイズルワースには連なる高い雪山と石灰岩の洞窟しかない。\n\n連日の異変で気が狂ったのか？"
  },
  Event_20781_Name = {
    Text = "火山の幻影"
  },
  Event_20782_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_20782_Desc = {
    Text = "幻影はあなたに手を振り、消えてしまった。\n残されたのは冷たい雪とそびえる山々だけだ。"
  },
  Event_20782_Name = {
    Text = "火山の幻影"
  },
  Event_20783_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_20783_Desc = {
    Text = "「了解しました。\n物資を送りますので、ご確認ください」"
  },
  Event_20783_Name = {
    Text = "支援通信"
  },
  Event_21398_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_21398_Desc = {
    Text = "機械が解体され、真相が明らかに。\n\n騒がしい人生は形を消し、真実が明らかになる満足感をあなたに残す。"
  },
  Event_21398_Name = {
    Text = "目撃証言"
  },
  Event_21399_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_21399_ChoiceDesc2 = {
    Text = "【フィルムを検査する】「(Skill.Arg1)」に感染する。選択肢1で獲得した刻印を変更。あと1回使用できる"
  },
  Event_21399_Desc = {
    Text = "好奇心に駆られ、現像液の中へと視線を向ける。\n\n画像は赤い薬液に浸され、黒い汚れにまみれた罪人は、あなたと同じ顔をしている。"
  },
  Event_21399_Name = {
    Text = "目撃証言"
  },
  Event_21400_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_21400_Desc = {
    Text = "機械が解体され、真実が明らかに。\n\n喧騒の人生が形を失い、あなたに真実を残す。"
  },
  Event_21400_Name = {
    Text = "目撃証言"
  },
  Event_21811_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_21811_Desc = {
    Text = "「25年……そう、彼女は私を25年間眠らせた」\n少女は陰鬱で落ち込んだ様子であなたに答える。\n\n目覚めた時には、幼い頃から彼女を世話していた使用人たちは、年を重ねて完全な海踊教団の一員になっていた。\n\n彼女の苦悩の理解者も、彼女の痛みを気にかける者もいなくなり、教団で孤独になってしまった。\n\n彼女は眠る前の日が「星辰正しき刻」であればよかったのにと思っている。"
  },
  Event_21811_Name = {
    Text = "囚われた命"
  },
  Event_22058_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22058_Desc = {
    Text = "「いや、私は空腹ではない」\nあなたはこの饗宴の熱烈な誘いを丁重に断った。\n\n魂を奪う代償を、あなたは決して差し出そうとはしない。"
  },
  Event_22058_Name = {
    Text = "肉体の宴"
  },
  Event_22059_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22059_Desc = {
    Text = "血まみれのスコーンをむさぼり食い、胡椒で漬けた心臓と生地の香りが混ざり合う中、あなたは馴染みのある匂いを嗅ぎ取った。\n\n「力を獲得。\nには代償が必要だ」\n最後の一口の血を飲み干す。"
  },
  Event_22059_Name = {
    Text = "肉体の宴"
  },
  Event_22060_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22060_Desc = {
    Text = "白いスープと肉片を一気に飲み込み、袖で唇の跡を拭う。\n\n肉は柔らかく、スープは香ばしいが、それが誰のものだったか？"
  },
  Event_22060_Name = {
    Text = "肉体の宴"
  },
  Event_22061_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22061_Desc = {
    Text = "あなたは風鈴に刻まれた古の刻印を調べる。\n\nそれらは常人には想像できないほど歪んでおり、理解されることを望んでいないようだ。\n\n理解されない、だから邪魔もされない。"
  },
  Event_22061_Name = {
    Text = "錆びた風鈴"
  },
  Event_22062_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22062_Desc = {
    Text = "「いいね、君はとても慎重だ」\n風鈴の中から、突然遠い声が聞こえてきた。\n\n「慎重さは、君にささやかな褒美をもたらすが、それだけだ」"
  },
  Event_22062_Name = {
    Text = "錆びた風鈴"
  },
  Event_22063_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22063_Desc = {
    Text = "あなたは風鈴に刻まれた古の刻印を撫でる。\n\nそれらは常人には想像できないほど歪んでおり、理解されることを望んでいないようだ。\n\n理解されない、だから邪魔もされない。"
  },
  Event_22063_Name = {
    Text = "錆びた風鈴"
  },
  Event_22064_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22064_Desc = {
    Text = "「はぁ、残念だね……また孤独な独奏を続けるしかないのか……」\n\nピアノと手がいつ消えたのかはわからないが、せせらぎのようなピアノの音は心に残り続けた。"
  },
  Event_22064_Name = {
    Text = "ピアノの幽霊"
  },
  Event_22065_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22065_Desc = {
    Text = "「ああ、こんな友がいることは、本当に光栄な事だ！」\n\nその手は興奮し、あなたはその速さについていけない。\n演奏が終わってもなお、心を揺さぶる音があなたを高揚させた。"
  },
  Event_22065_Name = {
    Text = "ピアノの幽霊"
  },
  Event_22175_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22175_Desc = {
    Text = "ボードは自信満々に滑り、あなたの視線もそれに合わせて行き来する。\n\nしかし、彼が指し示したのはわずか2文字で、悲惨な叫び声とともに粘り気のある黒い液体に変わった。"
  },
  Event_22175_Name = {Text = "交霊板"},
  Event_22176_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22176_Desc = {
    Text = "「数学！数学！！」\n女性の声が歯ぎしりし、ボードが数字の間を素早く滑り、木の摩擦で耳障りな音を立てた。\n\n「計算をして私の視界から消えてください！」"
  },
  Event_22176_Name = {Text = "交霊板"},
  Event_22177_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22177_Desc = {
    Text = "「ちょっと、ちょっと！！」\n「聞いてよ！なんで聞かないの！」"
  },
  Event_22177_Name = {Text = "交霊板"},
  Event_22178_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22178_Desc = {
    Text = "それは今ほど激しく躍動したことはない。\nしかしその代わりに、心の穴が引き裂かれていく……"
  },
  Event_22178_Name = {
    Text = "呪われた欲望"
  },
  Event_22179_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22179_Desc = {
    Text = "魂と霊があなたの肺を満たし、静寂の中で、あなたはゆるやかに浮かび上がっていく。 \n \nそして世界の音がひとつずつ目覚め、命の交響が静かに奏でられはじめる。"
  },
  Event_22179_Name = {
    Text = "過去の水"
  },
  Event_22180_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22180_Desc = {
    Text = "すべては通常通りに進み、破滅は約束通りに訪れ、燃え尽きない残骸の中に貴重なものが埋もれ、影の中で輝いている。"
  },
  Event_22180_Name = {
    Text = "針の先を越えて"
  },
  Event_22181_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22181_Desc = {
    Text = "出会い、別れ、すれ違い。"
  },
  Event_22181_Name = {
    Text = "星月の音"
  },
  Event_22182_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22182_Desc = {
    Text = "心が静まりつつあるが、「良心」が少し慰められたかもしれない……"
  },
  Event_22182_Name = {
    Text = "呪われた欲望"
  },
  Event_22183_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22183_Desc = {
    Text = "あなたはそっと目を閉じ、この貴重な虚無と自由のひとときを味わう。 \n \nやがて、静寂の中から世界が孵化しはじめる。  \n命が音もなく、静けさの中で花開くのを感じる。"
  },
  Event_22183_Name = {
    Text = "過去の水"
  },
  Event_22184_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22184_Desc = {
    Text = "あなたは針を止め、銀の破片が柔らかな手のひらを切り裂く。\n破滅はまだ訪れていないが、足元の影は濃い闇に飲み込まれた。"
  },
  Event_22184_Name = {
    Text = "針の先を越えて"
  },
  Event_22185_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22185_Desc = {
    Text = "「逃げられない、誰も内なる悪から逃れられない」\n悪念が神経を引き裂き、深淵へと引きずり込もうとする。\nしかし、痛みは逆に意識を鮮明にする。\n\n悪念はあなたを支配できない、あなたはあなただけだ。"
  },
  Event_22185_Name = {
    Text = "無妄の念"
  },
  Event_22186_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22186_Desc = {
    Text = "「なぜダメなの？」\n恐ろしい考えを受け入れれば、すべての問題は解決し、「倫理」という矛盾は消える。"
  },
  Event_22186_Name = {
    Text = "無妄の念"
  },
  Event_22187_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22187_Desc = {
    Text = "銀色の光が目の前をよぎり、重苦しい風がすべての音を消し去った。"
  },
  Event_22187_Name = {
    Text = "無妄の念"
  },
  Event_22188_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22188_Desc = {
    Text = "気まぐれで、冷たく、よそよそしい。"
  },
  Event_22188_Name = {
    Text = "星月の音"
  },
  Event_22189_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22189_Desc = {
    Text = "膨張、収縮、一触即発。"
  },
  Event_22189_Name = {
    Text = "星月の音"
  },
  Event_22190_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22190_Desc = {
    Text = "確かに少し無謀だが、どうしてやらないのか？\n\n壁をすべて打ち壊し、終点へ向かって突き進む。\n\nたとえ思考の湖にかつてないほどの荒波を立て、太陽を追うイカロスになったとしても、少なくともあなたは目的を達成した。そうではないか？"
  },
  Event_22190_Name = {
    Text = "思考の迷宮"
  },
  Event_22191_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22191_Desc = {
    Text = "あなたの脳は迷宮で、あなたはそのアリアドネ。\n\nこの宇宙で、あなた以上に迷宮を抜け出す方法を理解している者は誰もいない。\n\n誰一人として。"
  },
  Event_22191_Name = {
    Text = "思考の迷宮"
  },
  Event_22192_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22192_Desc = {
    Text = "正しい調律で、不協和音が少し和らいだ。\n\nでも、まだ何かできるかもしれない。"
  },
  Event_22192_Name = {
    Text = "不協和音"
  },
  Event_22193_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22193_Desc = {
    Text = "あなたは音楽の達人であり、音痴でもある。\n\n音符はあなたの思考の下で役割を果たし、流れる命が密境で響き渡る。"
  },
  Event_22193_Name = {
    Text = "不協和音"
  },
  Event_22194_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22194_Desc = {
    Text = "あなたの声は静寂の中に溶けていった。  \n\n静寂の音は、膨れ上がり、限界を超え――\nついには完全に砕け散り、残骸だけが残された。"
  },
  Event_22194_Name = {
    Text = "過去の水"
  },
  Event_22195_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22195_Desc = {
    Text = "あなたは、そう簡単には騙されない。  \n\n迷いも未練もなく、きっぱりと背を向けて、その場を後にした。"
  },
  Event_22195_Name = {
    Text = "這う裂け目"
  },
  Event_22293_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22293_Desc = {
    Text = "ペンを取った瞬間、手紙が密境で燃え、灰が手の中に落ちた。\n\n気がつくと、何かが手紙と共に消えていた。"
  },
  Event_22293_Name = {
    Text = "一方的な訴え"
  },
  Event_22294_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22294_Desc = {
    Text = "手紙が密境で消えた瞬間、優しく弱々しい声が聞こえた。\n\n「こんな状況で私を思い出してくれるなんて、教師として光栄だよ。\n\nでも、密境を歩いたのは本当に久しぶりだ。\n今の私にはこれくらいしかできない……」"
  },
  Event_22294_Name = {
    Text = "一方的な訴え"
  },
  Event_22295_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22295_Desc = {
    Text = "手紙が密境で消えた瞬間、急な驚きの声が聞こえた。\n\n「守秘者、何か不快なことがあったら、必ず教えてください。\n\nパートナーとして、全力で助けます」"
  },
  Event_22295_Name = {
    Text = "一方的な訴え"
  },
  Event_22296_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22296_Desc = {
    Text = "手紙が密境で消えた瞬間、冷たいため息が聞こえた。\n\n「試験に落ちたときも、こんなに積極的に助けを求めてくれたらいいのに」"
  },
  Event_22296_Name = {
    Text = "一方的な訴え"
  },
  Event_22397_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22397_Desc = {
    Text = "あなたの登場に影たちは顔を見合わせ、靴先を星光がかすめると、人々は突然消え去り、あなたの手には最も凝縮された影が残った。"
  },
  Event_22397_Name = {
    Text = "星月の約束"
  },
  Event_22398_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_22398_Desc = {
    Text = "騒がしい囁きがぴたりと止まり、漆黒の影が次々とあなたに向き直り、見つめる。\n顔に表情はないが、どこか嘲笑を感じ取れる……"
  },
  Event_22398_Name = {
    Text = "星月の約束"
  },
  Event_22399_ChoiceDesc1 = {
    Text = "【冷静に観察する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_22399_ChoiceDesc2 = {
    Text = "【声を出して尋ねる】25黒章を獲得する"
  },
  Event_22399_Desc = {
    Text = "星と月が交差する中、囁きが絶えない。\n\n「この人なの？@4の人……」\n「人間の身では、結局@3…」"
  },
  Event_22399_Name = {
    Text = "星月の約束"
  },
  Event_22411_ChoiceDesc1 = {
    Text = "【大成功】"
  },
  Event_22411_Desc = {
    Text = "安価で使いやすい罠！"
  },
  Event_22411_Name = {
    Text = "罠を作る"
  },
  Event_24254_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_24254_Desc = {
    Text = "霊知の嵐がトゥルーを包み込んでいる。\nあなたは彼と目を合わせ、一緒に暗闇へと進む。"
  },
  Event_24254_Name = {
    Text = "海から来た者"
  },
  Event_24255_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_24255_Desc = {
    Text = "霊知の嵐がトゥルーを包み込んでいる。\n長く続く悲しみと罪悪感が空間に広がっていく。"
  },
  Event_24255_Name = {
    Text = "深淵に直面する"
  },
  Event_24256_ChoiceDesc1 = {
    Text = "【触手を握る】トゥルーの助けを受け入れる"
  },
  Event_24256_Desc = {
    Text = "彼の威厳は巨大なものが海に落ちる時のように、目の前の密境を揺るがす。\n\nその力は古く、永遠を超えるほどに強大だ。\n\n彼と敵対していないことに安堵する。"
  },
  Event_24256_Name = {
    Text = "海から来た者"
  },
  Event_24257_ChoiceDesc1 = {
    Text = "【触手を握る】トゥルーと同行する"
  },
  Event_24257_Desc = {
    Text = "トゥルーは深呼吸し、遠くからミリアムを見つめた。\n\n歴史を懐かしみ、故人を懐かしみ、自分の人生を懐かしんでいるかのように……\n彼の顔に浮かぶ複雑な表情は一瞬で消え、彼はミリアムから目をそらした。\n\n「行こう、彼女から離れよう」"
  },
  Event_24257_Name = {
    Text = "深淵に直面する"
  },
  Event_24277_ChoiceDesc1 = {
    Text = "【ハッチを閉める】"
  },
  Event_24277_Desc = {
    Text = "ラモンナは門外から飛び込んできた学生を捕まえた。\n\nその強い守秘者は、全身がボロボロなのに他に異常はないようだった。\n\nラモンナが手を握った瞬間、あなたたちは再会の喜びを確認した。"
  },
  Event_24277_Name = {
    Text = "喜びの再会"
  },
  Event_24278_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_24278_Desc = {
    Text = "ラモンナは説明の機会を与えず、あなたを暗い船室に引き入れ、慎重にハッチを閉めた……"
  },
  Event_24278_Name = {
    Text = "喜びの再会"
  },
  Event_24540_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_24540_Desc = {
    Text = "「彼女は君の堅固な盾であり、君の手にある剣。\n\n彼女は君の仲間であり、君のパートナーであり、君の信頼する友だ——\n\nたとえ彼女がどんな姿になろうとも」"
  },
  Event_24540_Name = {
    Text = "見知らぬが懐かしい存在"
  },
  Event_24541_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_24541_Desc = {
    Text = "「あなたは……いや、そんなはずはない、\nこの輪廻のあなたはもう……私もすでに……」\n\n声は姿と共に消え去り、悲しみだけが水霧の中を漂っている。"
  },
  Event_24541_Name = {
    Text = "見覚えがあり、かつ見知らぬ姿"
  },
  Event_24542_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_24542_Desc = {
    Text = "「世界のため、人類のため、私たちの大切なもののため。\n\nもちろん、一番大事なことは——\n彼女は君のためにそうなった」"
  },
  Event_24542_Name = {
    Text = "見知らぬが懐かしい存在"
  },
  Event_24543_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_24543_Desc = {
    Text = "まだ近づく前に、あなたに気づいた。\n\n人影が一瞬止まる。\n驚いたようでもあり、突然大きな悲しみに沈んだようでもある。\n\nだが何かを言う前に、霧と共に消えてしまった。"
  },
  Event_24543_Name = {
    Text = "見覚えがあり、かつ見知らぬ姿"
  },
  Event_24544_ChoiceDesc1 = {
    Text = "【彼女は誰だ？】山札からランダムに指令カードを3枚引き、1枚選択して複製する"
  },
  Event_24544_ChoiceDesc2 = {
    Text = "【彼女はなぜこうなったのか？】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_24544_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_24544_Desc = {
    Text = "また霧、また人影。\n先ほどとは違い、今回は相手をはっきりと見た。\n\nあなたと全く同じ姿、あなたと全く同じ制服で、あなたと全く同じ顔。\n\n「君は、何故ここにいるか知っているだろう」\nその人は言った。\n\n「彼女が何故ああなったかも知っているように」"
  },
  Event_24544_Name = {
    Text = "見知らぬが懐かしい存在"
  },
  Event_24545_ChoiceDesc1 = {
    Text = "【声を出して慰める】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_24545_ChoiceDesc2 = {
    Text = "【近づこうと試みる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_24545_ChoiceDesc3 = {
    Text = "【背を向けて離れる】25黒章を獲得する"
  },
  Event_24545_Desc = {
    Text = "霧があなたの進む道を覆った。\n\nぼんやりとした光の中に姿が浮かび上がる。\n目を細めても、その顔は見えない。\n途切れ途切れの、囁きだけが聞こえる。\n\n「なぜ……なぜ救えなかった……\n運命は、本当に変えられないのか……」"
  },
  Event_24545_Name = {
    Text = "見覚えがあり、かつ見知らぬ姿"
  },
  Event_35039_ChoiceDesc1 = {
    Text = "【パートナーに助けを求める】3択の上位刻印を獲得"
  },
  Event_35039_ChoiceDesc2 = {
    Text = "【撮影現場の統括】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_35039_ChoiceDesc3 = {
    Text = "【現象級の熱狂を牽引】遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_35039_Desc = {
    Text = "「《フーディーニ大師の撮影現場ガイド》には、カーシア、つまりこの私が、製作者兼監督として映画全体に責任を持つ義務と権限があると、そうはっきりと書いてある。\n\nだから勇敢なるカーシアのスタッフたちよ、これからどう動くか、スケジュールを組んで！」\n\n「ス、スケジュール？ちょっと待って、いつから私たちが、君のスタッフになった！？」\n\n「千載一遇のチャンス、迷ってる暇はないよ！」"
  },
  Event_35039_Name = {
    Text = "製作者の迷宮"
  },
  Event_35103_ChoiceDesc1 = {
    Text = "【休憩】Arg2ライフを回復する[ExDesc1][ExDesc2]"
  },
  Event_35103_ChoiceDesc2 = {
    Text = "【瞑想】覚醒体を1体選択して覚醒させる"
  },
  Event_35103_ChoiceDesc3 = {
    Text = "【処置】症状カードを最大3枚除去し、黒印をArg2獲得する。"
  },
  Event_35103_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n通信機から誰かが呼んでいる。"
  },
  Event_35103_Name = {Text = "休憩所"},
  Event_35103_Tips3 = {
    Text = "症状カードを所持していません。"
  },
  Event_35165_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35165_Desc = {
    Text = "迷いながらも、あなたは自ら秘密の出資者に通信を求めた。\n\n「ここまで来たら、もう後には引けません。\nどうか寛大なご支援を……」\n\n通信機の向こうから豪快な笑い声が聞こえ、相手は笑いながらあなたの依頼を引き受けた。\n\n「そうだ、それから……この件は、ラモンナには絶対に内緒でお願いします」"
  },
  Event_35165_Name = {
    Text = "製作者の迷宮"
  },
  Event_35236_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35236_Desc = {
    Text = "撮影現場の統括とは何をする仕事なのか？\n\nあなたは、カーシアがいつの間にか霊知転写器に突っ込んでいた書類の束を取り出し、じっくりと読み始めた。\n\nそして、頭が痛くなってきた。\n\n撮影現場設営中にロータンが引き起こした損害、オレッタとブラウンが食べたお菓子、カーシアが購入した魔法のボールの経費申請……\n\n精算すべき項目が一つ一つ目の前に並んでいる。\nあなたは苦しみながら地面にしゃがみ込んで計算するしかなかった。\n\nところで、カーシアの魔法のボールって何だ？"
  },
  Event_35236_Name = {
    Text = "製作者の迷宮"
  },
  Event_35259_ChoiceDesc1 = {
    Text = "【幻影を払う】症状に感染する[ExDesc1][ExDesc2]"
  },
  Event_35259_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_35259_Desc = {
    Text = "ぼんやりとした顔が周囲に現れ、絶望的な呻き声をあげる。"
  },
  Event_35259_Name = {Text = "幻影"},
  Event_35497_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35497_Desc = {
    Text = "社会現象級の熱狂の裏には仕掛け人が必要だ。\nそして「仕掛け人」ならば、緑のショートヘアの彼女が頭に浮かぶ。\n\n「ミサゴ大学一の仲介者、ハンナ・ピースリーが誠心誠意、お手伝いしますよ！」\n\n「守秘者のご依頼の報酬は、初回サービスとして食堂のカレーセット3食分で結構！」"
  },
  Event_35497_Name = {
    Text = "製作者の迷宮"
  },
  Event_35887_ChoiceDesc1 = {
    Text = "【前進する】"
  },
  Event_35887_Desc = {
    Text = "船の帆を上げると、何もなかった。\n\n気づいた時には、帆そのものも消えていた。\n\n純白の帆と、かすかに浮かぶ少女の面影は、ひとつのメッセージとなって残った――\nたとえこの先、どんな道を進もうとも、あなたは決して独りではない。"
  },
  Event_35887_Name = {
    Text = "純白の帆"
  },
  Event_35888_ChoiceDesc1 = {
    Text = "【帆を上げる】"
  },
  Event_35888_Desc = {
    Text = "風はなく、静かな蒼海に、純白の帆船があった。\n帆は力強く張り、まるで見えぬ風に導かれるように、海面に影を落としている。\n\nその帆の向こうに、少女の面影を垣間見た。\n輪郭は霧のように曖昧で、水面に映る像のように揺らぎながらも、確かにそこに在る。\n\n彼女は周囲の世界から切り離されたようでありながら、この光景の中心に据えられていた。\n\nその姿は波のように揺れ続けるが、ただ間違いなく言える……あなたは彼女が誰か知っている。"
  },
  Event_35888_Name = {
    Text = "純白の帆"
  },
  Event_35894_ChoiceDesc1 = {
    Text = "【下へ落ちる】35黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_35894_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_35894_Desc = {
    Text = "少女の声が空気中に広がり、泡のようにぼんやりと遠くに消える。"
  },
  Event_35894_Name = {
    Text = "生死の境"
  },
  Event_35895_ChoiceDesc1 = {
    Text = "【繰り返す】30黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_35895_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_35895_Desc = {
    Text = "体が重く、霧が弱った体を包み込む。"
  },
  Event_35895_Name = {
    Text = "生死の境"
  },
  Event_35896_ChoiceDesc1 = {
    Text = "【先人の道を読む】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_35896_ChoiceDesc2 = {
    Text = "【自分の道を書き記す】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_35896_ChoiceDesc3 = {
    Text = "【闇を見つめる】25黒章を獲得する"
  },
  Event_35896_Desc = {
    Text = "もしあなたが一人で密境を進んでいたら、今のように自分の道を確信することはできなかっただろう。\n\n密境の足跡は三つに分かれ、刻まれた足跡は見えない未来を描いている。"
  },
  Event_35896_Name = {Text = "出口"},
  Event_35897_ChoiceDesc1 = {
    Text = "【彼女を支える】"
  },
  Event_35897_ChoiceDesc2 = {
    Text = "【彼女を見る】"
  },
  Event_35897_Desc = {
    Text = "彼女は呟きながら、ふらふらとあなたの前に立ち止まった。\n\n誰かが彼女の安眠を妨げたのか、彼女の意識は現実に縛られ、魂は失われた国に留まっている。"
  },
  Event_35897_Name = {
    Text = "失われた幻影"
  },
  Event_35898_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35898_Desc = {
    Text = "この混沌とした暗闇の中で、一連のぼんやりとした足跡が広がり、それはまるで夜行者が見えない砂漠に残した深い足跡のようだ。"
  },
  Event_35898_Name = {Text = "出口"},
  Event_35899_ChoiceDesc1 = {
    Text = "【立ち去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_35899_Desc = {
    Text = "遠くに灯台が見えた。\n彼女は暗闇の縁に孤独に立ち、微弱だが確かな光を放ち、夜の海の案内人のように、さまよう魂を彼岸の安らぎへと誘っている。\n\nあなたは思わず追いかけたが、足元が突然不安定になった。\n\n暗闇の下に隠された水域に足を踏み入れてしまった。\n水面は絹のように柔らかく、静かにあなたの足音を飲み込んだ。"
  },
  Event_35899_Name = {Text = "点滅"},
  Event_35900_ChoiceDesc1 = {
    Text = "【彼女に耳を傾ける】"
  },
  Event_35900_ChoiceDesc2 = {
    Text = "【彼女を無視する】"
  },
  Event_35900_Desc = {
    Text = "あなたは灯火の源を見極めた。\nそれは女性の姿をした存在だった。\n\n流れる光が異形の頭部から溢れ出し、未知への道を照らしている。\n\n「戻って……リ@2ア……」"
  },
  Event_35900_Name = {Text = "常明灯"},
  Event_35901_ChoiceDesc1 = {
    Text = "【灯台に近づく】"
  },
  Event_35901_ChoiceDesc2 = {
    Text = "【灯台から離れる】"
  },
  Event_35901_Desc = {
    Text = "現実と夢が交錯する角を曲がると、一瞬のうちに嵐の恐ろしい光景が広がった。\n\n巨大な見えない手に持ち上げられたかのように、狂風が猛獣のように吠え、塵と希望を巻き上げ、空は重く、極限まで圧迫感があった。\n\n嵐の中心には、存在しないはずの灯台が立っており、幻想の産物のようでもあり、古代の伝説の遺跡のようでもある。\nそれは狂風が吹き荒れる舞台で、孤独でありながらも頑強に微かな光を放っている。"
  },
  Event_35901_Name = {
    Text = "嵐の中心"
  },
  Event_35902_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_35902_Desc = {
    Text = "「密境で、灯火が絶えず、触肢を持つ幻影……」\nトゥルーは目を閉じて考え込み、しばらくしてから長い息をついた。\n\n「リモリアの門番……余の従者の一人。\n彼女も結局、執念の束縛から逃れられなかった」"
  },
  Event_35902_Name = {
    Text = "ソナニール号の沈没"
  },
  Event_35903_ChoiceDesc1 = {
    Text = "【銀色の光に触れる】25黒章を獲得する"
  },
  Event_35903_ChoiceDesc2 = {
    Text = "【銀色の光と対話する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_35903_Desc = {
    Text = "通信機がこじ開けられ、暗い光が漏れ出している——これはシルバーコアが通信機の中枢に封じられてから、初めて外界と対話する機会かもしれない。"
  },
  Event_35903_Name = {
    Text = "秘銀の碑"
  },
  Event_35904_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_35904_Desc = {
    Text = "「頭が光る女性？」エルトンは驚愕の表情を浮かべた。\n彼は貨物船の密境で時折現れるその姿について聞いたことがあるようだが——\n「ソナニール号が沈んだ夜……つまり、私がシレストを召喚した夜、嵐の中でその影を見た」\n「絶対に見間違いではない」"
  },
  Event_35904_Name = {
    Text = "ソナニール号の沈没"
  },
  Event_35905_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35905_Desc = {
    Text = "密境の前方は危険が潜み、深く測り知れない。\n\nあなたの目は見えない混沌をじっと見つめていたが、混沌に飲み込まれる前に、追ってきたラモンナがあなたを捕まえ、別の方向へと引き寄せた。"
  },
  Event_35905_Name = {Text = "出口"},
  Event_35906_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35906_Desc = {
    Text = "それはあなたの神秘的な魂が生み出した果実なのか？今経験しているすべては自我と更なる自我の衝突なのか？\n考えれば考えるほど、頭の中の雑音が透明感を持って響き渡る。\n視線は霧の中に入り込み、霧の中の人を見ようとした瞬間、魂があなたを拒絶した。"
  },
  Event_35906_Name = {
    Text = "逆転の運命"
  },
  Event_35907_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35907_Desc = {
    Text = "それは体内で湧き上がり、恐れ知らずの力となる。\n霧を突き破り、恐怖を引き裂く。"
  },
  Event_35907_Name = {
    Text = "光を追う"
  },
  Event_35908_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35908_Desc = {
    Text = "意識を集中し、心を落ち着けると混乱した幻影が徐々に溶け、最後には潮が引くように消えていく。\n\n結局、脳内の雑音も跡形もなく消える——ただ、どれだけのものを見逃したのかは知る由もない。"
  },
  Event_35908_Name = {
    Text = "未来予知"
  },
  Event_35909_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35909_Desc = {
    Text = "魂は耳鳴りの中で完全に迷い、必死に抜け出そうとするが、その苦痛を解読しようとしても、意識の端をさまようばかり……"
  },
  Event_35909_Name = {
    Text = "生死の境"
  },
  Event_35910_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_35910_Desc = {
    Text = "灯台から発せられる光の一つ一つを感じることができ、それらは嵐の中で燃え、跳ね、魂の奥深くからの呼びかけのようで、最も激しい恐怖の中でも帰路を導く使命を決して放棄しない。"
  },
  Event_35910_Name = {
    Text = "嵐の中心"
  },
  Event_35911_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ上位刻印を獲得する"
  },
  Event_35911_Desc = {
    Text = "それは希望の象徴か、破滅の前兆か？\nもうそれを見ないようにし、その存在がただの精巧に編まれた幻夢であるかのように振る舞う。"
  },
  Event_35911_Name = {
    Text = "嵐の中心"
  },
  Event_35912_ChoiceDesc1 = {
    Text = "【沈淪と迷離】20黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_35912_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_35912_Desc = {
    Text = "そして、目の前に異様な灰色のヴェールがかかる。\nしばらくして、それが半透明の上まぶたであることに気づく。"
  },
  Event_35912_Name = {
    Text = "生死の境"
  },
  Event_35913_ChoiceDesc1 = {
    Text = "【離れる】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_35913_Desc = {
    Text = "あなたの心に説明し難い共鳴が湧き上がる。\n\nしかし、理性はあなたに告げる——彼女を無視せよ。"
  },
  Event_35913_Name = {Text = "常明灯"},
  Event_35914_ChoiceDesc1 = {
    Text = "【立ち去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_35914_Desc = {
    Text = "彼女の言葉は既知の碑文には刻まれていないが、空気中に最も深い懺悔と呼びかけとして凝結している。\nそれは時の彼方から漂い、年月を超えて、遠い故郷への深い愛情を伴っている。"
  },
  Event_35914_Name = {Text = "常明灯"},
  Event_35915_ChoiceDesc1 = {
    Text = "【彼女の手を握る】ランダムな低級遺物1つを高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_35915_ChoiceDesc2 = {
    Text = "【声を出して気遣う】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_35915_ChoiceDesc3 = {
    Text = "【彼女を見つめる】25黒章を獲得する"
  },
  Event_35915_Desc = {
    Text = "マーフィーは隊列の最後にいて、シレストと並んで歩いている。\nあなたはつい振り返って彼女を見てしまうが、マーフィーは常にうつむいて靴先を見つめ、表情を隠している。"
  },
  Event_35915_Name = {
    Text = "痛み管理"
  },
  Event_35915_Tips1 = {
    Text = "まだ低級遺物を所持していません。"
  },
  Event_35916_ChoiceDesc1 = {
    Text = "【身動きが取れない】40黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_35916_ChoiceDesc2 = {
    Text = "【現実を受け入れる】25黒章を獲得する"
  },
  Event_35916_Desc = {
    Text = "@1@1は新たな生を得て、魂は@2の境を越えたが、まだ完全に肉体を掌握してはいない。\n\nマーフィーの気遣う言葉が意識から遠ざかる。\n\nまるでカラスの哀号のように耳に残るが、それは心の壁に阻まれて窓の外に留まっている。"
  },
  Event_35916_Name = {
    Text = "生死の境"
  },
  Event_35917_ChoiceDesc1 = {
    Text = "【離れる】指令カードを1枚複製することを選択し、「(Skill.Arg1)」に感染する"
  },
  Event_35917_Desc = {
    Text = "彼女は現実に残された幽霊、触れることはできないが、消え離れることのない古代の断片だ。"
  },
  Event_35917_Name = {
    Text = "失われた幻影"
  },
  Event_35918_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_35918_Desc = {
    Text = "その瞬間、あなたは魂の奥深くで微かな砕ける音を聞いた。\n煙のように徐々に消えていく彼女の姿は、ますます現実味を失っていく。\n\n彼女はここに存在するものではなく、これはエルトン船長の記憶の投影に過ぎない。\n\nしかし、心に残る彼女の失望と迷いは、偽りではない。"
  },
  Event_35918_Name = {
    Text = "失われた幻影"
  },
  Event_35919_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35919_Desc = {
    Text = "指先が触れた瞬間、複雑な感覚が心に押し寄せる——熱くも冷たくもある。\n\n忘れ去られた魂が、永遠を求めて叫んでいる。"
  },
  Event_35919_Name = {
    Text = "秘銀の碑"
  },
  Event_35920_ChoiceDesc1 = {
    Text = "【火種を信じる】最大ライフをArg1増加させる"
  },
  Event_35920_ChoiceDesc2 = {
    Text = "【内心と向き合う】ランダムな2枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、2枚の「(Skill.Arg2)」に感染"
  },
  Event_35920_Desc = {
    Text = "この壮大な狩りで、ゴリアテの追跡は夜の獣のように希望の光を飲み込もうとする。\nしかし、この無情な追跡にあなたは怖気づくことはなく、むしろ心の火種を燃やして胸の中に広がり、熱くなった。"
  },
  Event_35920_Name = {
    Text = "光を追う"
  },
  Event_35921_ChoiceDesc1 = {
    Text = "【それを解読する】山札からランダムに指令カードを3枚引き、1枚選択して複製する"
  },
  Event_35921_ChoiceDesc2 = {
    Text = "【それになる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_35921_ChoiceDesc3 = {
    Text = "【それを無視する】25黒章を獲得する"
  },
  Event_35921_Desc = {
    Text = "足を踏み出す瞬間、不可視の震動が意識を引き寄せ、密境・混沌・虚無の境界を見つめさせた。"
  },
  Event_35921_Name = {
    Text = "未来予知"
  },
  Event_35922_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35922_Desc = {
    Text = "さまざまな色彩が目の前で踊り、耳元で低くささやく声、そして閃く場面やぼやけた顔が交錯し、一つ一つ未知の物語を語るようだ。\nこれらの幻影はあなたを現実から徐々に引き離し、既知でもあり未知でもある夢の中へと誘い込む。"
  },
  Event_35922_Name = {
    Text = "未来予知"
  },
  Event_35923_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35923_Desc = {
    Text = "震えは外部の騒音や触覚からではなく、説明しがたい内なる予感から来ていた。\nそれは未来の呼び声のように、あなたの感覚に響いているかのよう。"
  },
  Event_35923_Name = {
    Text = "未来予知"
  },
  Event_35924_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35924_Desc = {
    Text = "彼女は無意識に胸に手を当て、息苦しさを抑えようとしている。\n\nこの恐怖は彼女に歯を食いしばらせ、胸の痛みを無視するよう自らに強いる。\nマーフィーの顔の小さな歪みはすぐに隠され、下手な偽装で痛みを隠している。\n\n——あなたが彼女の手を握るまで。\n驚きが彼女の顔に現れる。"
  },
  Event_35924_Name = {
    Text = "痛み管理"
  },
  Event_35925_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35925_Desc = {
    Text = "「マーフィー？大丈夫？」\n\n——彼女は応えてくれない。\n\n目に見えるほどの異変が彼女の心を蝕み、ほとんど息ができない。"
  },
  Event_35925_Name = {
    Text = "痛み管理"
  },
  Event_35926_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35926_Desc = {
    Text = "あなたはもう迷わず、漆黒の未知に足を踏み入れた。\n\nその歩んだ軌跡は、かすかな光へと向かい伸びる、道しるべを描き出す。"
  },
  Event_35926_Name = {Text = "出口"},
  Event_35927_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35927_Desc = {
    Text = "目の前に跳ねる炎がある。\n\nそれは熱く、生き生きとして、揺れる冷たい炎を包み込み、不協和音を明るく追い払った。\n\n我に返ると、目の前には不思議そうにこちらを見るマーフィーが——\n「本当に大丈夫？」"
  },
  Event_35927_Name = {
    Text = "生死の境"
  },
  Event_35928_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35928_Desc = {
    Text = "意識が分離し始め、体から引き離される感覚。\n\n自分の魂がシルバーコアの残存意識と共に踊り、見えない純粋な虚無の深淵に沈んでいく……"
  },
  Event_35928_Name = {
    Text = "秘銀の碑"
  },
  Event_35929_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_35929_Desc = {
    Text = "灯火の源をさらに探ろうとする前に、それは突然震え、空気中に砕け散った。\n\n灯光は密境の中で波紋を広げ、四方に拡散した。\n\nそして何も残らなかった。"
  },
  Event_35929_Name = {Text = "点滅"},
  Event_35930_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35930_Desc = {
    Text = "それがあなたであるはずがないだろう？\nもしそれがあなたなら、悲しみが訪れたとき、なぜ彼はあなたを救わなかったのか？\nもしそれがあなたなら、苦難を経験したとき、なぜ彼は助けなかったのか？\nだから、すべては錯覚だ。"
  },
  Event_35930_Name = {
    Text = "逆転の運命"
  },
  Event_35931_ChoiceDesc1 = {
    Text = "【船長に尋ねる】"
  },
  Event_35931_ChoiceDesc2 = {
    Text = "【トゥルーに尋ねる】"
  },
  Event_35931_Desc = {
    Text = "またしても、あなたはその神秘的な姿が船室に入り、跡形もなく消えるのを見た。\n蛍光の長い髪がどこからか始まり、数本の触腕となって地面に垂れている。\n\n彼女が海踊教団の一員でなくても、失われた国と何らかの関係があることは間違いない。"
  },
  Event_35931_Name = {
    Text = "ソナニール号の沈没"
  },
  Event_35932_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35932_Desc = {
    Text = "あなたはいま、恐れている。\nすべては興奮による錯覚に過ぎない。\n\nあなたは恐れているのだ。\n自らの決断が、共に闇を背負う魂たちを傷つけてしまうことを。"
  },
  Event_35932_Name = {
    Text = "光を追う"
  },
  Event_35933_ChoiceDesc1 = {
    Text = "【逃げ場がない】25黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_35933_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_35933_Desc = {
    Text = "神経が@2への渇望で叫んでいる。"
  },
  Event_35933_Name = {
    Text = "生死の境"
  },
  Event_35934_ChoiceDesc1 = {
    Text = "【追いかける】"
  },
  Event_35934_ChoiceDesc2 = {
    Text = "【それを無視する】"
  },
  Event_35934_Desc = {
    Text = "密境の遠くで、微かで魅力的な光が灯った。\n\nそれは水面に反射する陽光のようにきらめき、揺れる星の光や小さなろうそくの火のようだった……\nあなたが近づこうとした瞬間、その光は突然消えた。\n\nそれはまるで直感で生きる蛾を誘うように、あなたを引き寄せているかのようだ。"
  },
  Event_35934_Name = {Text = "点滅"},
  Event_35935_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_35935_Desc = {
    Text = "これに悩んで、何の意味があるのだろう？\nあなたは宙に浮かぶ一枚の落ち葉で、運命の風があなたを押し進めるだけだ。"
  },
  Event_35935_Name = {
    Text = "逆転の運命"
  },
  Event_35936_ChoiceDesc1 = {
    Text = "【自嘲する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_35936_ChoiceDesc2 = {
    Text = "【徹底的に問い詰める】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」「(Skill.Arg3)」に感染する"
  },
  Event_35936_ChoiceDesc3 = {
    Text = "【もう考えない】25黒章を獲得する"
  },
  Event_35936_Desc = {
    Text = "生命の風があなたの魂を揺らし、現実の渦に巻き込まれ、霧に包まれた未知へと引き込まれる。\n\n思わず脳内の声に問いかける——\n「これは私なのか？」"
  },
  Event_35936_Name = {
    Text = "逆転の運命"
  },
  Event_36146_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36146_Desc = {
    Text = "マーフィーはついにあなたの視線に気づいた。\nおそらく、その視線にあまりにも感情がこもっていたからだろう。\n\n彼女は深呼吸を数回し、鼻から軽く「ふん」と音を立てた。\n最後に、彼女はシレストを引っ張り、あなたの後ろにぴったりとついてきた。"
  },
  Event_36146_Name = {
    Text = "痛み管理"
  },
  Event_36722_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36722_Desc = {
    Text = "指先が触れた瞬間、複雑な感覚が心に湧き上がる——それは熱くも冷たくもある。\n\n世界に忘れられた魂が、永遠を求めて叫んでいる。"
  },
  Event_36722_Name = {
    Text = "霊知の碑"
  },
  Event_36723_ChoiceDesc1 = {
    Text = "【それに触れる】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_36723_ChoiceDesc2 = {
    Text = "【回転に加わる】3つの中から1つ刻印を獲得する"
  },
  Event_36723_Desc = {
    Text = "一歩踏み出した瞬間、精神の奥深くに裂け目が静かに開く。\n名状しがたい深淵の気配が裂け目を通り、あなたの心を揺らす。\n\n銀色の混沌の星が心の中で密かに回転し、成長しているのを感じる。"
  },
  Event_36723_Name = {
    Text = "霊知の碑"
  },
  Event_36724_ChoiceDesc1 = {
    Text = "【それらについていく】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_36724_ChoiceDesc2 = {
    Text = "【それらを撫でる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」「(Skill.Arg3)」に感染する"
  },
  Event_36724_ChoiceDesc3 = {
    Text = "【邪魔しない】25黒章を獲得する"
  },
  Event_36724_Desc = {
    Text = "曲がり角を曲がった後、奇妙な光景が視界に現れる。\n数匹の猫の影が、ぼんやりと冷たい船壁のそばに漂っている。"
  },
  Event_36725_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36725_Desc = {
    Text = "「記憶」は応答せず、壁に貼り付いたまま、あなたをじっと見つめ、次の角を曲がるまで視線を外さない。"
  },
  Event_36725_Name = {
    Text = "ソナニール号の主人"
  },
  Event_36726_ChoiceDesc1 = {
    Text = "【迂回する】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_36726_ChoiceDesc2 = {
    Text = "【なぜ沈んだのか尋ねる】指令カードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_36726_ChoiceDesc3 = {
    Text = "【船員に挨拶する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_36726_Desc = {
    Text = "動力室に向かう途中で、再び密境に固定された「記憶」に出会う。\n\n彼らは幽霊ではなく、エルトン船長が亡くなった船員を想う心だ。"
  },
  Event_36726_Name = {
    Text = "ソナニール号の主人"
  },
  Event_36727_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36727_Desc = {
    Text = "「記憶」が壁から剥がれ落ち、彼は顔を歪め、喉から悲鳴を上げた。\n\n——灯台。\n\n——孤立した灯台が彼らを嵐に導いた。"
  },
  Event_36727_Name = {
    Text = "ソナニール号の主人"
  },
  Event_36728_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36728_Desc = {
    Text = "あなたは追いかけることを選んだ。\n優しく自由な魂が描くその軌跡を……たとえその先に暗闇が残した罠があっても。"
  },
  Event_36729_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36729_Desc = {
    Text = "亡者を邪魔せず、眠る記憶をかき乱さないで。"
  },
  Event_36729_Name = {
    Text = "ソナニール号の主人"
  },
  Event_36730_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36730_Desc = {
    Text = "意識が分離し始め、ゆっくりと身体から引き離されるのを感じる。\n\n自分の魂が星と共に舞い、そして見えない深淵に沈んでいくのを見る……\n\nそこは純粋な虚無だ。"
  },
  Event_36730_Name = {
    Text = "霊知の碑"
  },
  Event_36731_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36731_Desc = {
    Text = "優しい生き物として、それらはこの密境で許されない贅沢であり、ただの幻影に過ぎない。\n\nあなたはそれを理解しているが、心の奥底に一抹の温かさが広がる。"
  },
  Event_36732_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36732_Desc = {
    Text = "彼らの姿は、時空の流れに洗われた油絵のようにぼやけている。\n黒い斑点は夜空に漂う雲のようで、彼らの目は遠い星の輝きに似て、神秘的で深い光を放っている。\n\nあなたは彼らの誘惑に抗えず、手を伸ばして虚無に触れた。"
  },
  Event_36733_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36733_Desc = {
    Text = "たとえよろめき、倒れても、進み続けなければならないと知っている。"
  },
  Event_36733_Name = {
    Text = "肉体の痛み"
  },
  Event_36734_ChoiceDesc1 = {
    Text = "【彼を呼んでみる】最大ライフをArg1増加させる"
  },
  Event_36734_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_36734_Desc = {
    Text = "ここは隠された願望と、まだ触れられぬ恐怖に満ちた場所。\nそれは、彼の夢と記憶が織り重なって描かれた、豊かな絵巻だ。"
  },
  Event_36734_Name = {
    Text = "進化による変容"
  },
  Event_36735_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36735_Desc = {
    Text = "「守秘者、耐えられないなら、一人で苦しみを抱え込まないで」\n\n痛みから逃げない、それは儚い命の一部だから。\n\n夜の影から逃げない、暗闇に飲まれることを恐れないから。"
  },
  Event_36735_Name = {
    Text = "肉体の痛み"
  },
  Event_36736_ChoiceDesc1 = {
    Text = "【引き続き彼を呼ぶ】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_36736_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_36736_Desc = {
    Text = "無邪気な落書きがこの世界を形作っている。"
  },
  Event_36736_Name = {
    Text = "進化による変容"
  },
  Event_36737_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36737_Desc = {
    Text = "海踊人の祈りが耳元で渦巻く。\nそれは、狂気に満ちて息苦しい。\n\nだが、それらがあなたの意志を揺るがすことはない――絶対に。"
  },
  Event_36737_Name = {
    Text = "深海の中"
  },
  Event_36738_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_36738_Desc = {
    Text = "その視線は深く澄んでいて、深海の光のように明るく温かい。\n\n言葉も形もないが、その存在を感じることができる。\nまるで夏の夜の微風のように優しい。"
  },
  Event_36738_Name = {
    Text = "善意の覗き見"
  },
  Event_36739_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36739_Desc = {
    Text = "あなたは自分を奮い立たせ、目の前の危機に集中し、痛みを無視するように強く命じた。"
  },
  Event_36739_Name = {
    Text = "肉体の痛み"
  },
  Event_36740_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36740_Desc = {
    Text = "確かにそれは命の痕跡、確かにそれは存在の証。\n\nそれは物語を語るが、その声は、嵐の咆哮にかき消され、静かに、しかし確実に失われていった。"
  },
  Event_36740_Name = {
    Text = "さようなら、イカロス"
  },
  Event_36741_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36741_Desc = {
    Text = "その視線は深く澄んでいて、深海の光のように明るく温かい。\n\n言葉も形もないが、その存在を感じることができる。\nまるで夏の夜の微風のように優しい。"
  },
  Event_36741_Name = {
    Text = "善意の覗き見"
  },
  Event_36742_ChoiceDesc1 = {
    Text = "【最後に彼を呼ぶ】ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_36742_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_36742_Desc = {
    Text = "痛みの痕跡がこの世界を作り上げている。"
  },
  Event_36742_Name = {
    Text = "進化による変容"
  },
  Event_36743_ChoiceDesc1 = {
    Text = "【痛みを受け入れる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_36743_ChoiceDesc2 = {
    Text = "【痛みを拒む】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」と「(Skill.Arg3)」に感染する"
  },
  Event_36743_ChoiceDesc3 = {
    Text = "【痛みを無視する】25黒章を獲得する"
  },
  Event_36743_Desc = {
    Text = "痛みは頑固な石のように脳に根を下ろす。\n広がる苦しみは蔓のように神経を絡め取り、意識をねじ曲げる。"
  },
  Event_36743_Name = {
    Text = "肉体の痛み"
  },
  Event_36744_ChoiceDesc1 = {
    Text = "【強く彼を呼ぶ】ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_36744_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_36744_Desc = {
    Text = "承認欲求がこの世界を作り上げている。"
  },
  Event_36744_Name = {
    Text = "進化による変容"
  },
  Event_36745_ChoiceDesc1 = {
    Text = "【それらを見つめる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_36745_ChoiceDesc2 = {
    Text = "【彼らに助けを求める】「(Skill.Arg1)」に感染する。選択肢1で獲得した刻印を変更。2回使用できる"
  },
  Event_36745_Desc = {
    Text = "密境に流れる色彩の中で、あなたは神秘的な視線を感じる。\nそれらは無形の目で、この密境の神秘的なひだに隠れている。\n\nそれらがあなたを見つめた瞬間、心の中に強い欲望が湧き上がる。"
  },
  Event_36745_Name = {
    Text = "善意の覗き見"
  },
  Event_36746_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36746_Desc = {
    Text = "もし彼らの言葉を理解しようとしなければ、この混沌の煉獄から抜け出せないだろう。\n\n星々が水面に映るとき、跳ねる願いや祈りのひとつひとつが泡のようにゆっくりと海面に昇る。\nそして、気づかぬうちに闇に呑まれていった。"
  },
  Event_36746_Name = {
    Text = "深海の中"
  },
  Event_36747_ChoiceDesc1 = {
    Text = "【必死に彼を呼ぶ】ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_36747_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_36747_Desc = {
    Text = "醜い言葉がこの世界を作り上げている。"
  },
  Event_36747_Name = {
    Text = "進化による変容"
  },
  Event_36748_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36748_Desc = {
    Text = "あなたは彼の前に立ち、彼の魂が奇妙な記憶に飲み込まれるのを目撃した。"
  },
  Event_36748_Name = {
    Text = "進化による変容"
  },
  Event_36749_ChoiceDesc1 = {
    Text = "【それは涙だ】カードを1枚削除する"
  },
  Event_36749_ChoiceDesc2 = {
    Text = "【それは血だ】「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_36749_Desc = {
    Text = "滴り落ちた数滴の液体が甲板に広がる。\n板の隙間を伝って静かに、染み渡っていく。\n\nその痕跡は柔らかく、そして揺るぎない。\n\nその一筋一筋の湿った線は、決意と諦念を帯び、海風の咆哮と、帆船のうめき声の中で、生と死、静寂と喧騒の絵を織りなす。"
  },
  Event_36749_Name = {
    Text = "さようなら、イカロス"
  },
  Event_36750_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36750_Desc = {
    Text = "あなたはゆっくりと広がる斑点を見つめた。\n\nその本質を見極めようとしたが、天と地が交わるこの境界では、雨と血の違いさえ曖昧になる。\n\nそれは雨なのか？\n海の涙なのか？\n\nあなたにはわからない。"
  },
  Event_36750_Name = {
    Text = "さようなら、イカロス"
  },
  Event_36751_ChoiceDesc1 = {
    Text = "【同調を拒否する】3つの中から1つ低級遺物を獲得する"
  },
  Event_36751_ChoiceDesc2 = {
    Text = "【同調に加わる】低級遺物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」を獲得し、2枚の「(Skill.Arg3)」に感染する"
  },
  Event_36751_Desc = {
    Text = "海踊人の囁きと「聖なる赤子」の鼓動は、秘められた交響曲となって絡み合う。\n\nそのひとつひとつの震えが、果てしない液体の宇宙に咆哮を引き起こす。"
  },
  Event_36751_Name = {
    Text = "深海の中"
  },
  Event_36752_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_36752_ChoiceDesc2 = {
    Text = "【フィルムを検査する】「(Skill.Arg1)」に感染する。選択肢1で獲得した刻印を変更。あと1回使用できる"
  },
  Event_36752_Desc = {
    Text = "それらは悪意を持たず、その感覚はあなたの本能に根付いている。\n\nだからこそ、警戒を解き、隠れた守護者に助けを求める。\n曖昧な存在に悩みや願いを語りかける。\nまるで旧友に心を打ち明けるように。"
  },
  Event_36752_Name = {
    Text = "善意の覗き見"
  },
  Event_36874_ChoiceDesc1 = {
    Text = "【学校の面白い話をする】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_36874_ChoiceDesc2 = {
    Text = "【学校に行ったことがない】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_36874_Desc = {
    Text = "廃墟を通り過ぎると、オレッタの目がぱっと輝いた。\n\n「おばあちゃんが言ってた、ここは昔学校だったけど、学生がいなくて廃れちゃったの！」\n「オレッタは学校に行ったことがないけど、学校に行ったことある？」"
  },
  Event_36874_Name = {
    Text = "失われた喜び"
  },
  Event_36875_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36875_Desc = {
    Text = "あなたから否定的な答えを聞いて、オレッタはがっかりして頭を振った。\n\n「外の世界にも学生はいないんだ……じゃあ、最初に学校を建てたのは何のため？」"
  },
  Event_36875_Name = {
    Text = "失われた喜び"
  },
  Event_36876_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36876_Desc = {
    Text = "「ワークハウス、鼠、蝋人形……やった！冒険だ、冒険！」\nオレッタは言いながら、頭の上に見えないクエスチョンマークを浮かべた。\n\n「でも、おばあちゃんは学校がオレッタを賢くする場所だって言ってたけど……」\nオレッタが考え続ける前に、あなたは彼女を押してもう一つの角を曲がった。"
  },
  Event_36876_Name = {
    Text = "失われた喜び"
  },
  Event_36877_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36877_Desc = {
    Text = "「な、なんで？」\n\nオレッタは驚いて、顔をしかめながら指示を続ける。\n\n「ここはオレッタの家、オレッタは知ってる、広場は——あの中にある！」"
  },
  Event_36877_Name = {
    Text = "見えない闇"
  },
  Event_36878_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36878_Desc = {
    Text = "「この道は行きたくない、オレッタは他の広場への道を知ってる？」\n\nオレッタは口をとがらせ、少し困惑したが、最終的にはあなたのマントを引っ張り、別の方向を指示した。"
  },
  Event_36878_Name = {
    Text = "見えない闇"
  },
  Event_36879_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_36879_Desc = {
    Text = "これは夢だ、ただの夢だ。\n\n自分に何度も言い聞かせ、あるいは慰めながら、オレッタを連れて見えない闇に突入する。"
  },
  Event_36879_Name = {
    Text = "見えない闇"
  },
  Event_36880_ChoiceDesc1 = {
    Text = "【彼女に従う】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_36880_ChoiceDesc2 = {
    Text = "【彼女に反対する】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染する"
  },
  Event_36880_ChoiceDesc3 = {
    Text = "【彼女と相談する】25黒章を獲得する"
  },
  Event_36880_Desc = {
    Text = "オレッタがあなたのマントを引き、足跡をたどって一歩一歩進む。\n\n「えっ…間違えた！広場はあっちだよ！」\n\nオレッタが指差す方向を見ると、密境の小道は真っ暗だ。\n融蝕液や変異体が蠢き絡まり合い、現実世界も共に奈落の底へと引きずり込む。"
  },
  Event_36880_Name = {
    Text = "見えない闇"
  },
  Event_37983_ChoiceDesc1 = {
    Text = "【経費を獲得する】Arg1黒章を獲得する"
  },
  Event_37983_ChoiceDesc2 = {
    Text = "【経費を獲得する】Arg1黒章を獲得する[ExDesc1]"
  },
  Event_37983_Desc = {
    Text = "「領主が素性不明の者を放置することはないの。\nましてや修道士を」\n女王は高い玉座に座っており、その目にふと残忍な光がよぎった。\n\n「何かの役に立つことを証明なさい、さもなくば……」\n\n何かの役？窓の外の荒れた土地が目に入り、一つの考えが浮かぶ——\n経済学の知識を使ってワンダの領地を管理する手助けができるかも？\n\n貧弱な頭脳を必死に絞る——ミサゴでは経済学は目立たない選択科目だったから……\n\n女王は退屈そうにあくびをする。\n「失望したわ。やれ——」\n\nギロチンが落ちるその瞬間、アダム・スミス、マルサス、デヴィッド・リカードなどの偉大な先人たちの霊があなたの頭に降りてくる。\n\n分業！課税！人口、くそっ、人口！\n稲妻のように、講義の内容が脳裏を駆け抜けた。"
  },
  Event_37983_Name = {
    Text = "代行の密令"
  },
  Event_37984_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_37984_Desc = {
    Text = "あなたは思い切って政令を提出する。\n\n女王はざっと目を通し、冷たい微笑を浮かべる——\n「役に立たなければ、どうなるかは分かるね」"
  },
  Event_37984_Name = {
    Text = "代行の密令"
  },
  Event_37985_ChoiceDesc1 = {
    Text = "【政令を提出する】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_37985_ChoiceDesc2 = {
    Text = "【政令を提出する】呪われた遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_37985_ChoiceDesc3 = {
    Text = "【政令を提出する】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_37985_Desc = {
    Text = "「金を受け取ったからには、命を懸けて働いてもらわないとねぇ」\n女王は片手で頬杖をつき、無関心にあなたを見つめる。\n\n認めるかどうかは別として、彼女は確かに興味を持っている。\n\n「それじゃあ、あんたの計画とやらを教えてもらおうか、大改革者」"
  },
  Event_37985_Name = {
    Text = "代行の密令"
  },
  Event_38700_ChoiceDesc1 = {
    Text = "【休憩】Arg2ライフを回復する[ExDesc1]"
  },
  Event_38700_ChoiceDesc2 = {
    Text = "【瞑想】覚醒体を1体選択して覚醒させる"
  },
  Event_38700_ChoiceDesc3 = {
    Text = "【処置】症状カードを最大3枚除去し、黒印をArg2獲得する。"
  },
  Event_38700_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n通信機から誰かが呼んでいる。"
  },
  Event_38700_Name = {Text = "休憩所"},
  Event_38700_Tips3 = {
    Text = "症状カードを所持していません。"
  },
  Event_38707_ChoiceDesc1 = {
    Text = "【幻影を払う】症状に感染する"
  },
  Event_38707_ChoiceDesc2 = {
    Text = "【幻影を吸収する】Arg1ライフを失い、Arg2黒章を獲得する"
  },
  Event_38707_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_38707_Desc = {
    Text = "ぼんやりとした顔が周囲に現れ、絶望的な呻き声をあげる。"
  },
  Event_38707_Name = {Text = "幻影"},
  Event_38715_ChoiceDesc1 = {
    Text = "【政令を提出する】低級遺物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」を獲得する"
  },
  Event_38715_ChoiceDesc2 = {
    Text = "【政令を提出する】呪われた遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_38715_ChoiceDesc3 = {
    Text = "【政令を提出する】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_38715_Desc = {
    Text = "「金を受け取ったからには、命を懸けて働いてもらわないとねぇ」\n女王は片手で頬杖をつき、無関心にあなたを見つめる。\n\n認めるかどうかは別として、彼女は確かに興味を持っている。\n\n「それじゃあ、あんたの計画とやらを教えてもらおうか、大改革者」"
  },
  Event_38715_Name = {
    Text = "代行の密令"
  },
  Event_40452_ChoiceDesc1 = {
    Text = "【身分を尋ねる】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_40452_ChoiceDesc2 = {
    Text = "【離れる】ランダムな指令カード3枚が刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_40452_Desc = {
    Text = "3人の幽霊が行く手を阻んでいる。\n\n彼らは賭けのテーブルを囲み、ダイスの動きに集中している。\n\n「コロコロ」\nダイスは何度も投げられ、落ちる。\n\nこれは終わりのない賭けだ。"
  },
  Event_40452_Name = {
    Text = "終わりなき賭け"
  },
  Event_40453_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_40453_Desc = {
    Text = "「やぁ、こんにちは。私たちはワンダの一番目、二番目、そして三番目の夫だ」\n\n「え、四番目の夫はどこかって？\nうーん……ジョンはね、正直ちょっとユーモアが足りなくて、奥さんに盲目の従者にされちゃったんだ」\n\n「彼を失ったのは残念。まぁほんの少しだけね」"
  },
  Event_40453_Name = {
    Text = "終わりなき賭け"
  },
  Event_40454_ChoiceDesc1 = {
    Text = "【それと握手する】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_40454_ChoiceDesc2 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_40454_Desc = {
    Text = "牢屋を通り過ぎると、中から手が伸びてきた。\n\n「行かないで、リベッカ……」\n声は古びた風箱のようにかすれている。"
  },
  Event_40454_Name = {Text = "囚人"},
  Event_40455_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_40455_Desc = {
    Text = "手のひらにねっとりとした感触——それは融蝕液。\n\n声の主はいつの間にか消え、陰鬱な影の中に隠れていた。"
  },
  Event_40455_Name = {Text = "囚人"},
  Event_40456_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_40456_Desc = {
    Text = "あなたは何も気にせず去り、手紙の裏にある大事な過去を見逃した。\n\nだが、それが何だというのだ？\n広大な海、夜明けと夕暮れ、赤道の砂漠……\n\nあなたはこれからもっと多くのものに出会い、これからもっと多くのものを見逃すだろう。"
  },
  Event_40456_Name = {
    Text = "敬愛する夫人へ"
  },
  Event_40457_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_40457_Desc = {
    Text = "ある意味で、あなたはこの囚人と同じだ。\n\n今はまだ動かない方がいい。\n\n囚人の嘆願を無視し、背を向けて離れる。"
  },
  Event_40457_Name = {Text = "囚人"},
  Event_40458_ChoiceDesc1 = {
    Text = "【手紙を破る】1つの遺物を呪われた遺物「(RelicConfig.Arg1)」に変化させる"
  },
  Event_40458_ChoiceDesc2 = {
    Text = "【手紙を無視する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_40458_ChoiceDesc3 = {
    Text = "【返信する】25黒章を獲得する"
  },
  Event_40458_Desc = {
    Text = "手紙：\nジョン・カンブリアよりワンダへ（B.F.@2）\n\n夫には妻を処分する権利がある。\n少なくともカンブリアではそうだ。\n\nだが、どうやら私は君の狂気の度合いを低く見積もっていたようだ。今や私の目はほとんど見えず四肢も間もなく切り落とされる。\n\n悪魔の娘……いや、君こそが悪魔そのものだ。\n\n君を呪う@1君を呪う@2呪う呪う呪う……"
  },
  Event_40458_Name = {
    Text = "敬愛する夫人へ"
  },
  Event_40459_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_40459_Desc = {
    Text = "あなたは最も素朴な手段で呪いを解く事にした。\n\n何事も起こらず、紙片は無気力に地面に落ちた。\n\nあなたは肩をすくめてその場を去った。\nだが、どうにも何かがおかしいと心の中で感じていた。"
  },
  Event_40459_Name = {
    Text = "敬愛する夫人へ"
  },
  Event_40460_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_40460_Desc = {
    Text = "君は心を乱さずに賭け台を通り過ぎた。\n\n去り際に、幽霊たちが声を揃えて言った——\n「私たちの元妻——ワンダ夫人によろしく伝えてくれ」"
  },
  Event_40460_Name = {
    Text = "終わりなき賭け"
  },
  Event_40461_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_40461_Desc = {
    Text = "あなたは手紙の末尾に丁寧に返信を書く——\n\n「呪いは受け取りました。\nすべて順調であることをお祈りします」\n\n最後の一筆を入れた瞬間、手紙は怒りの青い炎に包まれた。\n\nあなたは灰を手に入れた。"
  },
  Event_40461_Name = {
    Text = "敬愛する夫人へ"
  },
  Event_44187_ChoiceDesc1 = {
    Text = "【闇に立ち向かう】[ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc2 = {
    Text = "【闇に立ち向かう】[ExDesc1][ExDesc2]"
  },
  Event_44187_ChoiceDesc3 = {
    Text = "【闇から逃れる】ランダムな高級遺物を獲得する"
  },
  Event_44187_Desc = {
    Text = "あなたの目の前の魂は曖昧で濁り、曇っている。\n\n光りと闇が同時にその身に存在し、互いに支配権を争い、魂は迷いの中に沈んでいる。\n\n「彼らには同情するよ。すべてを失った哀れな人々。でもこの世界はそういうものだろう？」\n\n「誰かが得れば、誰かが失うんだ」\n\n「他人の幸せのために、自分の幸せを諦められるかい？」"
  },
  Event_44187_Name = {Text = "心の闇"},
  Event_44188_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_44188_Desc = {
    Text = "「これは私の罪であり、私の重荷だ。\nどうすれは救える？矛盾した私の魂を」"
  },
  Event_44188_Name = {Text = "心の闇"},
  Event_44299_ChoiceDesc1 = {
    Text = "【司教に祈る】罪悪の遺物を浄化する。罪悪の遺物がない場合、ランダムな高級遺物を獲得する"
  },
  Event_44299_Desc = {
    Text = "「私は騙し、奪い、望んだ人生を手に入れた——\n金は数字になり、贅沢は日常になり、商業は私の言葉が絶対で、政治では強硬な手腕を振るった」\n\n「でもなぜ、なぜ、あの人たちを忘れられない？\n私がすべてを奪ったあの人たちを？\nなぜ、彼らの絶望の顔を忘れられない？」\n\n「酒は一時の逃避にしかならず、私の魂は自らを引き裂き、苦しみが私を飲み込もうとしている」\n\n「私は一体どうすればいい？」"
  },
  Event_44299_Name = {
    Text = "罪悪感と赦し"
  },
  Event_44301_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_44301_Desc = {
    Text = "「あなたは苦難の道を歩んでいる。\n父なる神の栄光から外れている」\n\n「戻ってきなさい、迷える子羊よ。\n父なる神の教えに従い、正しい道を歩みなさい」"
  },
  Event_44301_Name = {
    Text = "罪悪感と赦し"
  },
  Event_44395_ChoiceDesc1 = {
    Text = "【物品を求める】司教があなたの症状カードを1枚引き受ける。あなたはArg1黒章を獲得する。症状がない場合、直接黒章を獲得する"
  },
  Event_44395_ChoiceDesc2 = {
    Text = "【鮮血を求める】司教があなたの症状カードを2枚引き受ける。あなたは刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_44395_ChoiceDesc3 = {
    Text = "【さらに求める】司教はさらに症状（少なくとも4枚）を引き受ける"
  },
  Event_44395_Desc = {
    Text = "幻のような魂がぼんやりとした輪郭を形作る。\n\n司教の前に跪き、壊れた肉体と黒く染まった心をさらけ出す。\n\n「あなたは私に導きを与え、赦しを与え、救いを与えてくれました。でも、慈悲深き司教よ、それだけでは足りないのです」\n\n「私は貧しく、病に苦しみ、命は風前の灯です。\nあなたは私の唯一の救い。どうか、司教よ、私を苦しみから解き放ってください」"
  },
  Event_44395_Name = {
    Text = "司教の「祝福」"
  },
  Event_44396_ChoiceDesc1 = {
    Text = "【一礼して離れる】"
  },
  Event_44396_Desc = {
    Text = "司教は指輪を外し、ブローチを取った。それらの父なる神を象徴する青い宝石は一つずつ魂の手に置かれ、司教はかがんで哀れな魂の手を握った。\n\n「私の金銀を持っていきなさい、私のすべての財産を持っていきなさい——それがあなたに必要なものならば。\n私は父なる神の教えがあれば、生きていける」"
  },
  Event_44396_Name = {
    Text = "司教の「祝福」"
  },
  Event_44400_ChoiceDesc1 = {
    Text = "【それに溺れる】「(Skill.Arg1)」に感染し、ランダムな覚醒体を覚醒させる"
  },
  Event_44400_ChoiceDesc2 = {
    Text = "【諦める】"
  },
  Event_44400_Desc = {
    Text = "迷える魂は闇を手放そうとしない。\n\nあなたは、それを待ち受けるものが、何かを知っている。\n\n荒唐無稽な人生が幕を開けようとしており、あなたはその唯一の観客だ。"
  },
  Event_44400_Name = {Text = "心の闇"},
  Event_44401_ChoiceDesc1 = {
    Text = "【素早く行動する】Arg1黒章を獲得する"
  },
  Event_44401_ChoiceDesc2 = {
    Text = "【ほしいままに奪い取る】3つの中から1つ上位刻印を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_44401_Desc = {
    Text = "密境で発見できる黒い印。\n\n交換所となる融痕に捧げることで、遺物などの精神投影物と交換できる。\n\n現在の区域を離れると、すぐに黒い泥となって消え失せる。"
  },
  Event_44401_Name = {Text = "黒章"},
  Event_44407_ChoiceDesc1 = {
    Text = "【幻影を払う】症状に感染する"
  },
  Event_44407_ChoiceDesc2 = {
    Text = "【虚妄を抱擁する】ランダムな症状を2枚獲得し、Arg1黒章を獲得する"
  },
  Event_44407_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_44407_Desc = {
    Text = "ぼんやりとした顔が周囲に現れ、絶望的な呻き声をあげる。"
  },
  Event_44407_Name = {Text = "幻影"},
  Event_44445_ChoiceDesc1 = {
    Text = "【離れる】サーチライトを探す"
  },
  Event_44445_ChoiceDesc2 = {
    Text = "【霧に突入する】Arg2ライフを失う"
  },
  Event_44445_ChoiceDesc3 = {
    Text = "【物体を捨てる】5黒章を消費し、「啓示」を1枚獲得する"
  },
  Event_44445_Desc = {
    Text = "前方には濃い黒い霧が立ち込めている。\n軽率に侵入すれば、災いが降りかかるだろう。\n\n「サーチライト」を見つけて霧を払うべきかもしれない。"
  },
  Event_44469_ChoiceDesc1 = {
    Text = "【骨肉を求める】司教があなたの症状カードを4枚引き受ける。あなたは3つの中から1つ高級遺物+を獲得する"
  },
  Event_44469_ChoiceDesc2 = {
    Text = "【祝福を求める】司教があなたの症状カードを6枚引き受ける。あなたは3つの中から1つ時の振り子を獲得する"
  },
  Event_44469_ChoiceDesc3 = {
    Text = "【戻る】"
  },
  Event_44469_Desc = {
    Text = "幻のような魂がぼんやりとした輪郭を形作る。\n司教の前に跪き、壊れた肉体と黒く染まった心をさらけ出す。\n\n「あなたは私に導きを与え、赦しを与え、救いを与えてくれました。でも、慈悲深き司教よ、それだけでは足りないのです」\n\n「私は貧しく、病に苦しみ、命は風前の灯です。\nあなたは私の唯一の救い。どうか、司教よ、私を苦しみから解き放ってください」"
  },
  Event_44469_Name = {
    Text = "司教の「祝福」"
  },
  Event_44474_ChoiceDesc1 = {
    Text = "【要求する】司教の祝福を獲得する"
  },
  Event_44474_ChoiceDesc2 = {
    Text = "【要求する】司教の祝福を獲得する"
  },
  Event_44474_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_44474_Desc = {
    Text = "「これは私の罪であり、私の重荷だ。\nどうすれば救える？矛盾した私の魂を。」"
  },
  Event_44474_Name = {Text = "心の闇"},
  Event_44911_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_44911_Desc = {
    Text = "「すべて、すべて……そうだ、すべてを……！」\n魂は手を伸ばし、空中でむなしく掴もうとする。\n\n何かを得たが、何も得られなかった。"
  },
  Event_44911_Name = {
    Text = "君は何を得たのか"
  },
  Event_44913_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_44913_Desc = {
    Text = "「じゃあ一番大事なものだけ。一番大事な……」\n\n魂はしゃがみ込み、虚無の土から明るい願いを掘り出し、それを手のひらに載せた。"
  },
  Event_44913_Name = {
    Text = "君は何を得たのか"
  },
  Event_44916_ChoiceDesc1 = {
    Text = "【すべてを掴む】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_44916_ChoiceDesc2 = {
    Text = "【手放すことを学ぶ】ランダムな指令カード3枚が刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_44916_Desc = {
    Text = "暗い魂が苦しみに陥る。\n\nそれはその場をさまよい、すべての選択と結果に迷っている。\n\n「どう選べばいい？」と静かに呟く。\n\n「どうすればいい？」\n「どうすればすべてを手に入れられる？」"
  },
  Event_44916_Name = {
    Text = "君は何を得たのか"
  },
  Event_44919_ChoiceDesc1 = {
    Text = "【自己省察する】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_44919_ChoiceDesc2 = {
    Text = "【他人を見る】3つの中から1つ刻印を獲得する"
  },
  Event_44919_Desc = {
    Text = "漂う魂は板挟みになっている。\n\nそれは足を止め、欲望の間で迷っている。\n\n「どう選べばいい？」\nそれは小声でつぶやく。\n「どうすればいい？」\n「本当に求めているのはどれなんだ？」"
  },
  Event_44919_Name = {
    Text = "君は何を望むのか"
  },
  Event_44920_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_44920_Desc = {
    Text = "「そうだ、見なければ、見なければ……」\nそれは頭を下げ、両手を胸に入れ、虚構の心臓を取り出した——\n半分は墨のように黒く、半分は星のように明るい。"
  },
  Event_44920_Name = {
    Text = "君は何を望むのか"
  },
  Event_44921_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_44921_Desc = {
    Text = "「そうだ、そうだ……他人は鏡になると言う……見なければ……」\nそれはあなたの前に近づき、顔のない顔であなたを見つめた。\n\n「なぜあなたは困らないの？羨ましい、羨ましい……」"
  },
  Event_44921_Name = {
    Text = "君は何を望むのか"
  },
  Event_44998_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_44998_Desc = {
    Text = "「彼らは言うんだ……今の苦しみは一時的なもので、死後には父なる神の懐で永遠の喜びが待っているのだと」\n\n「でも私は、死後までなんて、待ちたくない」\n\n影は貪欲にすべてを飲み込み、魂は輝きを失い、周囲の闇とほとんど一体化してしまう。\n\nあなたは何かをしたいと思うが、無力だ。"
  },
  Event_44998_Name = {Text = "心の闇"},
  Event_45000_ChoiceDesc1 = {
    Text = "【一礼して離れる】"
  },
  Event_45000_Desc = {
    Text = "司教は鋭い刃で掌を切り、石板に滴る血が治癒の青い光となり、魂の欠けた血を補った。\n\n「私の血を持っていきなさい、あなたの命を満たすために——それがあなたに必要なものならば」"
  },
  Event_45000_Name = {
    Text = "司教の「祝福」"
  },
  Event_45001_ChoiceDesc1 = {
    Text = "【一礼して離れる】"
  },
  Event_45001_Desc = {
    Text = "司教は胸の奥から魂を取り出す。\n温かな光が石板に溶け込み、癒しの青い光となり、魂のすべての裂け目を埋める。\n\n「受け取りなさい、これは父なる神の贈り物、彼の愛の証です。\nあなたの体が健やかで、魂が満たされ、苦しみから解放されますように」"
  },
  Event_45001_Name = {
    Text = "司教の「祝福」"
  },
  Event_45002_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_45002_Desc = {
    Text = "あなたは顔に向かって歩み寄った。\n再び目を開けると、目の前はすでに暗闇に戻っていた。\n\nただ正体不明の笑い声だけが周囲に響いている。"
  },
  Event_45002_Name = {Text = "幻影"},
  Event_45036_ChoiceDesc1 = {
    Text = "【すべての遺物を削除する】"
  },
  Event_45036_Desc = {
    Text = "「これは私の罪であり、私の重荷だ。\nどうすれば救えるのか、矛盾した私の魂を？」"
  },
  Event_45036_Name = {Text = "心の闇"},
  Event_45196_ChoiceDesc1 = {
    Text = "【一礼して離れる】"
  },
  Event_45196_Desc = {
    Text = "司教は鋭い刃で骨肉を削り取る。\n白い骨と赤い肉が石板に溶け込み、癒しの青い光となり、折れた魂の骨を補う。\n\n「私の骨肉を持っていきなさい、あなたの欠けた体を補うために——それがあなたに必要ならば」"
  },
  Event_45196_Name = {
    Text = "司教の「祝福」"
  },
  Event_46144_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ低級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_46144_Desc = {
    Text = "ぼんやりとした人影が徐々に鮮明になる。\n\nそれは融蝕生物でも災厄でもなく、翼も持たず、普通の表情をしたクレメンタインだった。\n\n「奇遇ね。\nあなたも月光を楽しみに来たの？」\n彼女は微笑みながらそう言ったが、あなたは突然の眩暈を感じる。\n\n「霧深い夜だから、気をつけないとね」\n「ここの小さな者は、あまり大人しくないから」"
  },
  Event_46144_Name = {
    Text = "霧の中の影"
  },
  Event_46145_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_46145_Desc = {
    Text = "あなたは冷静に見守る。\n貴婦人が突然舞台に駆け上がる。\n\n彼女は狂ったように少年の口をこじ開け、手にした棒を強く突き込む。\n\n「話せ、話して」\n少年の口から黒い血が流れる。\n彼は不明瞭に続けた。\n\n「母への歌を……」"
  },
  Event_46145_Name = {
    Text = "終幕の儀Ⅲ"
  },
  Event_47309_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47309_Desc = {
    Text = "その日、神は彼の強力な剣でペリシテ人を罰するだろう。\n\n彼らが犯した殺戮の罪のために。\n\n何だって、不公平だって？\nいや、これが捕食者の運命だ。"
  },
  Event_47309_Name = {
    Text = "水夫の歌"
  },
  Event_47310_ChoiceDesc1 = {
    Text = "【聴き続ける】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_47310_ChoiceDesc2 = {
    Text = "【立ち去る】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_47310_Desc = {
    Text = "神は言った——彼をペリシテ人と呼べ。\n\n殺戮の役割を担わせ、貪欲の呪いを背負わせよ。\n\n彼の歩む道は光り輝き、深淵を白髪のように思わせる。\n\n広大な海には、これほど雄大な大鮫はいない。\n\n彼をすべての生き物が恐れ、審判の時が来るまで崇敬するように。"
  },
  Event_47310_Name = {
    Text = "水夫の歌"
  },
  Event_47311_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_47311_ChoiceDesc2 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_47311_ChoiceDesc3 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_47311_Desc = {
    Text = "少年は卑しい奴隷だった。\n主人は彼を息子のように扱ったが、寝床で刺し殺された。\n\n「愛しています、父さん。\nただ、もう奴隷でいたくないんです」\n\nその後、少年は「父親」の墓前に立ち、祭司の言葉を思い出した——\n<Small:生まれ育った土地を離れるな。\n\nその時、あなたの手は血に染まり、無様に死ぬだろう。\n\n野犬、ハゲワシ、海の魚もあなたを軽蔑する。>\nグレンという体の少年は結局去った。\n\n彼は自らの悪体高い物語を紡ぐことになる。"
  },
  Event_47311_Name = {
    Text = "樽の中の少年"
  },
  Event_47312_ChoiceDesc1 = {
    Text = "【前のページに戻る】低級遺物「(RelicConfig.Arg1)」を獲得し、症状を1回感染させる"
  },
  Event_47312_ChoiceDesc2 = {
    Text = "【次のページに進む】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_47312_ChoiceDesc3 = {
    Text = "【捨てる】25黒章を獲得する"
  },
  Event_47312_Desc = {
    Text = "あなたはパピルスで綴じられた本を拾った——\n……\n少年は木桶の中に隠れ、ペリシテ人の島へと漂流した。\n\n彼は弱々しく、卑劣で、野心に満ちていた。\n\n不滅の巨人の栄光が皆を驚嘆させる中、\n少年だけは影に隠れ、その光を一切近づけなかった。\n\nその後、彼はゴリアテに重責を任された。\n\nその理由は——"
  },
  Event_47312_Name = {
    Text = "樽の中の少年"
  },
  Event_47313_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47313_Desc = {
    Text = "巨人は続けて言った——\n\n「彼をそばに置くのは、彼が憂鬱で滑稽だからだ。そして彼は決して私を殺せない」"
  },
  Event_47313_Name = {
    Text = "樽の中の少年"
  },
  Event_47314_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47314_Desc = {
    Text = "後の部分は聞こえなかったが、その歌詞は別の歌を思い出させた——\n\n「この珍しい巨大なサメは、嵐の中に身を置く。\n海はそいつの住処。\n強さが正義なら、彼は強さの巨人、\n果てしない海の王だ」"
  },
  Event_47314_Name = {
    Text = "水夫の歌"
  },
  Event_47315_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47315_Desc = {
    Text = "今は読む時じゃない。\n急いで本を閉じ、最後の内容を見逃した——\n\n……彼が影に隠れるのは嫉妬からではなく、純粋な恐怖からだ。\n光の下に立つと、卑しい魂は完全に消え去り、灰さえも残らない。"
  },
  Event_47315_Name = {
    Text = "樽の中の少年"
  },
  Event_47463_ChoiceDesc1 = {
    Text = "【催眠に入る】指定した覚醒体を精神分裂させ、初期の指令カード4枚を失う"
  },
  Event_47463_Desc = {
    Text = "医師は分厚い本から顔を上げて言った——\n\n「あなたは稀有なサンプルですので、料金はいただきません。\n代わりといっては何ですが、ある催眠療法を試してほしいのです。\n\nこれは新しいタイプの治療法で、無条件で完全に意識を裸にできるのです。\n\nどうです、試してみませんか？」"
  },
  Event_47463_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47464_ChoiceDesc1 = {
    Text = "【きらめく記憶】[ExDesc1][ExDesc2]"
  },
  Event_47464_ChoiceDesc2 = {
    Text = "【くすんだ記憶】山札にあるすべての合奏刻印を上位合奏刻印にアップグレードする"
  },
  Event_47464_Desc = {
    Text = "彼女は意識の海の浜辺をさまよっていた。\n\n波の裾が彼女の両足に触れ、散らばった記憶を岸辺へと運び寄せる。\n\nそれらは、あるものは輝き、あるものはくすみ、あるものはロンディニウムの雨季の匂いがした。\n\nどの記憶を拾い上げる？\n彼女は意識の海の浜辺を彷徨っていた。"
  },
  Event_47465_ChoiceDesc1 = {
    Text = "【試みを断る】ランダムな1枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_47465_ChoiceDesc2 = {
    Text = "【溶剤の瓶を砕く】罪業の遺物を浄化する"
  },
  Event_47465_ChoiceDesc3 = {
    Text = "【実験を受け入れる】時の振り子を1つ獲得する「(RelicConfig.Arg1)」"
  },
  Event_47465_Desc = {
    Text = "医者は碧緑色の溶剤を揺らしながら、興奮気味に彼女に告げた。\n\n「これを一口飲めば、あなたは明晰夢に入ることができます。\nそれは、集合的無意識の念動力の再現です。\n\n今から、あなたは無数の生き物と同じ意識の海を共有することになります。\n\n試してみませんか？」"
  },
  Event_47465_Name = {
    Text = "「明晰夢」"
  },
  Event_47466_ChoiceDesc1 = {
    Text = "【声に応える】精神分裂した覚醒体の指令カードを1枚獲得する"
  },
  Event_47466_Desc = {
    Text = "肉体は檻であり、バラバラになった人格を閉じ込めている。\n\n「24」と名付けられた監獄は今や満員だ。\n\n「眠らないで、心を穏やかにしないで」\n暗闇の中で、声がそっと言った。"
  },
  Event_47466_Name = {
    Text = "「自己覚知」"
  },
  Event_47848_ChoiceDesc1 = {
    Text = "【目を閉じる】3つの中から1つ高級遺物を獲得する"
  },
  Event_47848_ChoiceDesc2 = {
    Text = "【こっそり見る】覚醒体を2体選択して覚醒させ、その覚醒カードの行動力消費を1点減少させる"
  },
  Event_47848_ChoiceDesc3 = {
    Text = "【目を開ける】低級遺物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」「(RelicConfig.Arg3)」を獲得する"
  },
  Event_47848_Desc = {
    Text = "催眠に入る前、医師は言った——\n「私の許可なく、目を開けてはいけません」\n\nそこで彼女は目を固く閉じた。\n息を吸い……吐き……\n\nうつらうつらとする中、彼女は「シュー……」という息遣いのような音を聞いた気がした。\n\nその後、彼女は冷たい視線を浴びた——\n何かが彼女を見ている。\n\nそっと目を開けて、こっそり見てみてみようか？"
  },
  Event_47848_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47876_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47876_Desc = {
    Text = "彼女はかがんで、きらめく記憶を拾い上げた。\n\n一つ、二つ……無数の喜びが次々と押し寄せる。\n\n彼女は両腕を広げ、それらの周りをくるくると回った。"
  },
  Event_47877_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47877_Desc = {
    Text = "彼女は腰をかがめて薄れゆく記録を拾い上げた。\n一つ、二つ…………無数の卑しいものが次々とやってきて、\n彼女は両腕を広げ、それらすべてを胸に抱きしめた。"
  },
  Event_47878_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47878_Desc = {
    Text = "あなたはこれらの奇妙な溶剤の犠牲者になることを拒否した。\n\n医者は少し残念そうだったが、あなたに無理強いはしなかった。\n\n「私は人間の臆病さと短慮を許しましょう」"
  },
  Event_47878_Name = {
    Text = "「明晰夢」"
  },
  Event_47879_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47879_Desc = {
    Text = "ガシャン！あなたは一気に瓶を叩き割った。\n\n碧緑色の溶液は、すぐさま床を腐食させた。\n\n「いいですね、無知な衝動。\nでも次はないことを願います。\n\nそうでないと、私はそれによって悲しくて涙を流してしまうでしょう」"
  },
  Event_47879_Name = {
    Text = "「明晰夢」"
  },
  Event_47880_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47880_Desc = {
    Text = "ゴクッと一口飲み込んだ。\n\nゴクゴク……あなたの脳と喉から、同時に無数の泡が湧き出る。\n\nまるでパチパチと弾ける小さな花火のようだ。\n\n「勇敢なる人間よ、称賛します。\nあなたは無限に触れる機会を得ました。\n\nそして私は、その無限を見届けるのです」"
  },
  Event_47880_Name = {
    Text = "「明晰夢」"
  },
  Event_47881_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47881_Desc = {
    Text = "彼女は目を開けて言った——\n\n「そうね、すべてが間違っている。\n涙を流すべきだわ、抗うべきだわ」\n\n暗闇の中でかすかなざわめきが響き、彼女は善意の応えを受け取った。"
  },
  Event_47881_Name = {
    Text = "「自己覚知」"
  },
  Event_47900_ChoiceDesc1 = {
    Text = "【蛇を見た】高級遺物+「(RelicConfig.Arg1)」を獲得する"
  },
  Event_47900_ChoiceDesc2 = {
    Text = "【あなたを見た】罪悪の遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_47900_Desc = {
    Text = "パチンッ。\n\n軽く指を鳴らす音で彼女は現実に引き戻された。\n\n医師はいつの間にか顔を近づけており、コバルトイエローの瞳を興奮で細めていた。\n\n「教えてください、さきほど、あなたは何を見ましたか？」"
  },
  Event_47900_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47901_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47901_Desc = {
    Text = "彼女は両目を開けた。\n\n光影が朧に揺れる中で、彼女は暗闇の中に、白い巨大な蛇がとぐろを巻き、静かにゆっくりとうごめいているのを見た気がした。\n\nああ、そして、その目――\n\nそれは一切の混じり気のない純粋な金色だった。\n\n悲しみも、喜びもなく、何の評価も含まない――その眼差しは、真夏の悪夢から目覚めさせるのに十分だった。"
  },
  Event_47901_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47909_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47909_Desc = {
    Text = "彼女はそっと片目を開けた。\n\n視界に入ったのは、暗闇の中でゆっくりとうごめく、ぼやけた白い光の塊だった。\n\nその光の塊の中で、薄い金色が一瞬きらめく。\n彼女の規則違反を警告しているかのようだった。\n\n彼女はそれ以上、見続ける勇気はなかった。"
  },
  Event_47909_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47910_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47910_Desc = {
    Text = "彼女は医師の指示を守り、一瞬たりとも目を開けなかった。\n\n冷たい息が彼女の周りの空気を撫で、顔に長く留まった。\n\nどれほどの時間が経ったのか、すべてが元通りになった。\n\nまるで何も起こらなかったかのように。"
  },
  Event_47910_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47911_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47911_Desc = {
    Text = "「私は……とても美しい蛇を見ました」\n医師は鋼のペンを握る手を一瞬止めた。\n\n「どんな蛇でしたか？」\n\n「とても、美しかった！全身が白くて、その上に金色の模様がありました……」\n\n医師はそれ以上何も言わず、口元をわずかに、ほとんど気づかれないほどつり上げた。\n\n「ありがとう」"
  },
  Event_47911_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47912_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47912_Desc = {
    Text = "彼女はまっすぐに医師のコバルトイエローの目を見つめた。\n\n「私は、あなたが蛇に変わるのを見ました」\n「おお。なぜ君はそれが、私だと確信したの？」\n\nなぜなら、それは神秘的で、静止していて、複雑だったから。\nそれに……\n\nそれは、とても疲れているように見えた。\nまるで千年にもわたる冬眠から目覚めたばかりのようだった。"
  },
  Event_47912_Name = {
    Text = "「催眠の蛇」"
  },
  Event_47992_ChoiceDesc1 = {
    Text = "【休憩】Arg2ライフを回復する"
  },
  Event_47992_ChoiceDesc2 = {
    Text = "【瞑想】覚醒体を1体選択して覚醒させる"
  },
  Event_47992_ChoiceDesc3 = {
    Text = "【処置】症状カードを最大3枚除去し、黒印をArg2獲得する。"
  },
  Event_47992_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n\n通信機から誰かが呼んでいる。"
  },
  Event_47992_Name = {Text = "休憩所"},
  Event_47992_Tips3 = {
    Text = "症状カードを所持していません。"
  },
  Event_47993_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_47993_ChoiceDesc2 = {
    Text = "【離れる】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得し、そのカードの未強化コピーを1枚複製する"
  },
  Event_47993_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_47993_Name = {Text = "休憩所"},
  Event_48225_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_48225_Desc = {
    Text = "猫は嬉しそうにあなたの手を舐めた。\n\n「ありがとう、悲しまないでにゃ。\n\nここでは人格が常に死んで生まれ変わるから、\n必ず戻ってくるにゃ！\nニャーニャー、ニャーニャーニャー！」"
  },
  Event_48225_Name = {
    Text = "最期の願い"
  },
  Event_48226_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_48226_Desc = {
    Text = "猫はあなたが自分の意図を理解していないと思い、あなたの手にすり寄った。\n\n「もし約束してくれるにゃら、隠していたおやつを全部あげるにゃ。\n\nカンブレー地区@2号に大切に保管されているにゃ……」"
  },
  Event_48226_Name = {
    Text = "最期の願い"
  },
  Event_48227_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_48227_Desc = {
    Text = "あなたはジョージに心からの謝罪を伝えた。\n\n「ふん、礼儀を知っている奴だとはな。\n\nジョージは呪いの強さを10%、せいぜい15%下げることを考えてやる——これがジョージの限界だ」"
  },
  Event_48227_Name = {
    Text = "ジョージの幽霊"
  },
  Event_48228_ChoiceDesc1 = {
    Text = "【それを受け入れる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_48228_ChoiceDesc2 = {
    Text = "【それを拒否する】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_48228_ChoiceDesc3 = {
    Text = "【沈黙を保つ】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_48228_Desc = {
    Text = "「にゃんこ24」は重傷を負い、必死にあなたに伝える——\n\n「うう、もう長くないにゃ。\n友達がいるにゃ、銀ダラなんだけどにゃ。\nもし会ったら、遠くに行ったって伝えてにゃ。\n\n長い間いなくなるにゃ。\n揚げてない魚のフィッシュアンドチップスをたくさんお土産に持って帰るにゃ。\n\n必ず伝えてにゃ！」"
  },
  Event_48228_Name = {
    Text = "最期の願い"
  },
  Event_48229_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_48229_Desc = {
    Text = "猫は少し残念そうだった。\n\nでも、彼はいつも従順でお利口な猫で、決して無理強いはしない。\n\n最後に、彼女は未練を残しながら目を閉じた。"
  },
  Event_48229_Name = {
    Text = "最期の願い"
  },
  Event_48230_ChoiceDesc1 = {
    Text = "【それに謝る】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_48230_ChoiceDesc2 = {
    Text = "【それを嘲笑する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_48230_ChoiceDesc3 = {
    Text = "【それを無視する】25黒章を獲得する"
  },
  Event_48230_Desc = {
    Text = "ジョージの幽霊が頭上を漂う。\n\n「ジョージは無様に死んだ。\n\nでも構わない。\nジョージはこの屈辱を忘れない。\n\n守秘者、お前は大変なことになるぞ、ふふふ……」"
  },
  Event_48230_Name = {
    Text = "ジョージの幽霊"
  },
  Event_48231_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_48231_Desc = {
    Text = "「ふふ、ジョージを嘲笑するとは。\n\n安心しろ、食事中も、寝ている時も、歌っている時も……\nジョージはそばで漂い、思い出させ、苦しめてやる。\n\n罪を永遠に刻み込むためにな。\n\n幽霊は絶対に捕まえられない、ラララ〜」"
  },
  Event_48231_Name = {
    Text = "ジョージの幽霊"
  },
  Event_48232_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_48232_Desc = {
    Text = "あなたは大股で前進し、ジョージの呪いを振り払った。\n\n背後からすすり泣く声が聞こえ、ジョージが大泣きし始めた。\n\n「うう……こんなに可愛い私が、おまえの尻に——\n気持ち悪い！気持ち悪い！\nジョージはパンディアの鞭で死んだ方がマシだ！」"
  },
  Event_48232_Name = {
    Text = "ジョージの幽霊"
  },
  Event_49055_ChoiceDesc1 = {
    Text = "【覚醒体を呼ぶ】すべての覚醒体の100狂気を消費し、症状カードを1枚削除する"
  },
  Event_49055_ChoiceDesc2 = {
    Text = "【必死にもがく】Arg1ライフを回復する、2枚の「(Skill.Arg2)」に感染する"
  },
  Event_49055_ChoiceDesc3 = {
    Text = "【シルバーキーを差し込む】すべてのキーエネルギーを空にする"
  },
  Event_49055_Desc = {
    Text = "ぼんやりと見えていた血の池は、あなたが足を踏み入れた瞬間にその正体を現した。\n\n赤黒い無数の血の腕が足首に絡みつき、深淵へ引きずり込もうと絶えず上へとのぼりつめる。"
  },
  Event_49055_Name = {Text = "血の池"},
  Event_49097_ChoiceDesc1 = {
    Text = "【前進する】"
  },
  Event_49097_Desc = {
    Text = "腹部が緊張し、数秒後に落ち着きを取り戻した。\nなぜか、体の中でまた鼓動が聞こえるような気がする……"
  },
  Event_49097_Name = {
    Text = "母なる存在"
  },
  Event_49098_ChoiceDesc1 = {
    Text = "【一気に飲み干す】[ExDesc3][ExDesc4]枚の指令カードを選び、刻印を獲得させる：「(EnchantConfig.Arg1)」[ExDesc1][ExDesc2]"
  },
  Event_49098_Desc = {
    Text = "古びた陶器が低い岩壁の隙間からあなたを見つめている。\n\n水は砂漠で最も貴重な物資で、酒は狂気と幻の世界への誘いだ。\n\nこの荒れた地で、理性を保つ者がそれを拒むのは難しい。"
  },
  Event_49098_Name = {
    Text = "母なる存在"
  },
  Event_49312_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49312_Desc = {
    Text = "シルバーキーが輝きを放ち、血の腕たちは何かの力に怯えたように血の池に隠れ、そして消えていった。"
  },
  Event_49312_Name = {Text = "血の池"},
  Event_49313_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49313_Desc = {
    Text = "必死に抵抗するが、ますます深みに嵌っていく。\n呪いのような囁きが頭の中で響く。\n\n気がつくと、血の腕たちは満足したかのように退いていった。\n\n全身が爽快に感じられるが、漠然と何かを失ってしまったような気がする……"
  },
  Event_49313_Name = {Text = "血の池"},
  Event_49314_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49314_Desc = {
    Text = "その音に呼応した覚醒体は、ためらうことなくあなたを血の池から引きずり出した。\n\nあなたとつながっていた腕は引き裂かれ、濁った泥水が飛び散る。\n\n水中に潜む無数の腕は、何かを渇望し飲み込もうとしているかのようだ。"
  },
  Event_49314_Name = {Text = "血の池"},
  Event_49867_ChoiceDesc1 = {
    Text = "ランダムな覚醒体が50狂気を獲得する"
  },
  Event_49907_ChoiceDesc1 = {
    Text = "【真偽を尋ねる】"
  },
  Event_49907_ChoiceDesc2 = {
    Text = "【撫でることを求める】"
  },
  Event_49907_Desc = {
    Text = "「いつも私の角をじっと見てるけど、何か気になるの？」\nタイスが突然肩に近づき、蜂蜜色の飾りが頬をかすめる。"
  },
  Event_49907_Name = {
    Text = "角のある人"
  },
  Event_49908_ChoiceDesc1 = {
    Text = "【上を見る】"
  },
  Event_49908_ChoiceDesc2 = {
    Text = "【タイスへ向かう】"
  },
  Event_49908_Desc = {
    Text = "廃墟の中に煙と塵が四方に散り、片隅の壊れた窓の外に、突然タイスの姿が現れた。彼女は気にする様子もなく埃まみれの窓枠に身を伏せ、神秘めかして梁の上を指差した。"
  },
  Event_49908_Name = {Text = "潜む者"},
  Event_49909_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_49909_Desc = {
    Text = "頭を上げると、錆びた銅管が蜘蛛の巣のように頭上を覆っている。\n影がよぎるが、それは餌を探す野良猫か、それとも影に潜む敵か？\n振り返ると、タイスの姿も消えている。"
  },
  Event_49909_Name = {Text = "潜む者"},
  Event_49910_ChoiceDesc1 = {
    Text = "【彼女を見つめる】"
  },
  Event_49910_ChoiceDesc2 = {
    Text = "【彼女を呼ぶ】"
  },
  Event_49910_Desc = {
    Text = "またあの「幻影」に出会った。\n\n今回は彼女の名前を知っている。\n\nタイスは遠くの母なる木の下で、木に向かって祈りを捧げている。\n\n彼女の輪郭は母なる木の幻影と一体化しているかのようだ。"
  },
  Event_49910_Name = {Text = "祈願者"},
  Event_49911_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_49911_Desc = {
    Text = "あなたはタイスの姿を遠くから見つめる。\n彼女の輪郭はこの終末の嵐の中で神聖な孤峰のようで、砂嵐がその威厳を少しも削ぐことはない。\n\n彼女の歩みはゆっくりと安定しており、その姿は高貴で侵すことができない。\nあなたはその姿に見とれる。"
  },
  Event_49911_Name = {Text = "不死者"},
  Event_49912_ChoiceDesc1 = {
    Text = "【離れる】指令カードを1枚複製することを選択する"
  },
  Event_49912_Desc = {
    Text = "「どう思う？」\n彼女は「しーっ」と言い、さらに近づいてくる。\n角の先が頬に触れ、ひんやりとしたくすぐったい感触が……"
  },
  Event_49912_Name = {
    Text = "角のある人"
  },
  Event_49913_ChoiceDesc1 = {
    Text = "【立ち去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_49913_Desc = {
    Text = "「触りたいなら素直に言えばいいのに、断るわけないでしょ？」\n彼女は軽く笑いながら手を引き、指先の感触は温かく滑らかで、思わず引き込まれそうになる……"
  },
  Event_49913_Name = {
    Text = "角のある人"
  },
  Event_49914_ChoiceDesc1 = {
    Text = "【離れる】覚醒体を1体選択して覚醒させ、その霊知覚醒カードの行動力消費を1点減少させる。「(Skill.Arg1)」に感染する"
  },
  Event_49914_Desc = {
    Text = "あなたは皆と共に地にひれ伏す。\n\n「わかってた、わかってた、女王様、女王様はずっと私たちを守ってくれてた！」\n喜びの涙声、長い呼び声が風の音と混ざり、あなたの頭の中で共鳴する。\n\nぼんやりと、何か重要な思考が一瞬よぎるが、捕まえることができない。"
  },
  Event_49914_Name = {Text = "不死者"},
  Event_49915_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ低級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_49915_Desc = {
    Text = "あなたは彼女に手を振る。\n\n「何してるの？」ラモンナが不思議そうにあなたを見る。\n\n「あそこ……」\n言葉が出る前に、遠くの女性はもう姿を消している。\n\n錯覚だったのか？"
  },
  Event_49915_Name = {
    Text = "水を汲む人"
  },
  Event_49916_ChoiceDesc1 = {
    Text = "【彼女に応える】"
  },
  Event_49916_ChoiceDesc2 = {
    Text = "【ためらう】"
  },
  Event_49916_Desc = {
    Text = "遠くから見ると、1人の女性が川岸で水を汲んでいる。\n\nあなたの視線に気づいたのか、彼女は振り返って手を振っている。\n\n彼女の振り返り方が少し変わっていることに気づく。"
  },
  Event_49916_Name = {
    Text = "水を汲む人"
  },
  Event_49917_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_49917_Desc = {
    Text = "あなたがためらっている間に、女性は振り返ってオアシスに飛び込んで姿を消した。\n\n自分の目を信じられない……彼女は羊の蹄を持っていたようだ？"
  },
  Event_49917_Name = {
    Text = "水を汲む人"
  },
  Event_49918_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_49918_Desc = {
    Text = "「木よ、どうか@1人の祈りをお聞きください、私はあなたの乳汁を浴びて再生し、あなたの代行者となり、あなたのためにレムワシの黄砂の間を歩き、あなたの根がレムワシの隅々まで触達するようにいたします…………」\n\n幼い祈りの声が次々と空間の中に残響した。"
  },
  Event_49918_Name = {Text = "祈願者"},
  Event_49919_ChoiceDesc1 = {
    Text = "【離れる】ランダムに覚醒体を1体覚醒させる"
  },
  Event_49919_Desc = {
    Text = "タイスの曖昧な視線があなたの注意を引き、何か不思議な力があなたを惑わせる。\n彼女に引き寄せられるように歩み寄る。\n\n「見えないものも、存在しているのよ」\n彼女が耳元で囁くと、何かを悟るが、まるで白いヴェールに包まれたように不明瞭だ。\n\nこれは予言なのか？気づけば、タイスの姿は消えている。"
  },
  Event_49919_Name = {Text = "潜む者"},
  Event_49920_ChoiceDesc1 = {
    Text = "【遠くを眺める】"
  },
  Event_49920_ChoiceDesc2 = {
    Text = "【ひざまずく】"
  },
  Event_49920_Desc = {
    Text = "羊の黒い蹄が砂嵐の大地を踏む。\n\nタイスが未知の祈りを唱え、無数のアラン族が彼女の進む方向にひれ伏す。"
  },
  Event_49920_Name = {Text = "不死者"},
  Event_49921_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_49921_Desc = {
    Text = "巨木が無数の太い枝を伸ばし、絡み合う触手のようにタイスの手首と足首をしっかりと縛り、彼女の抵抗を無視して、彼女の体を膨らむ木の幹の腹腔に無理やり取り込む……\n\n遠くの幻影であっても、彼女の苦しみは水の波動とともにあなたの心に直接響く。"
  },
  Event_49921_Name = {Text = "祈願者"},
  Event_49922_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_49922_Desc = {
    Text = "樹の樹液と共に流れる麻痺した四肢、彼女は必死に抵抗するが、四肢はまるで条虫になったように言うことを聞かない。\n\n「骨は完全に溶けてしまったわね」タイスの目尻には悲しみが染み込んでいる。\n「彼女はもう木の一部」\n「私たちには逆転の力が必要だわ……時間を超える力が」"
  },
  Event_49922_Name = {
    Text = "腐蝕の人"
  },
  Event_49923_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_49923_Desc = {
    Text = "「それに、あの「逆さまの目のない瞳」からは、なぜか胸の奥に響くような強い呼びかけを感じるのよね……」\n「あら、私の話ですか？」\n「メディナイトが、君の語りを絶賛していたよ。」\n\nあの篝火が静かに燃える夜、彼女はあなたに1杯の酒を注いでくれた。"
  },
  Event_49923_Name = {
    Text = "腐蝕の人"
  },
  Event_49924_ChoiceDesc1 = {
    Text = "【瘤を切り開く】"
  },
  Event_49924_ChoiceDesc2 = {
    Text = "【思い出す】"
  },
  Event_49924_Desc = {
    Text = "一つの木の瘤。\n\nそれは邪悪に膨れ上がり、脆く透明な血色の表皮の内側に、今にも破裂しそうな歪んだ苦痛の顔が浮かび上がる。\n\n「メディナイト」タイスは悲し気な表情で、その顔の名前を優しく呼びかけた。"
  },
  Event_49924_Name = {
    Text = "腐蝕の人"
  },
  Event_49939_ChoiceDesc1 = {
    Text = "【ライカーを信じる】すべての覚醒体がArg1狂気を獲得する"
  },
  Event_49939_ChoiceDesc2 = {
    Text = "【ライカーを心配する】覚醒体を2体選択して覚醒させる"
  },
  Event_49939_Desc = {
    Text = "「私の幸運を信じてくれ」"
  },
  Event_49939_Name = {
    Text = "幸運の探偵"
  },
  Event_49940_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49940_Desc = {
    Text = "ライカーが得意なのは3つだけ——調査、聞き耳、ダイス投げ。\n\nつまり、戦闘は得意じゃない。\n\n心配が抑えきれず、狂気が増す。"
  },
  Event_49940_Name = {
    Text = "幸運の探偵"
  },
  Event_49941_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49941_Desc = {
    Text = "信じる心は魔法だ。\n彼は必ず目の前の障害を乗り越える。"
  },
  Event_49941_Name = {
    Text = "幸運の探偵"
  },
  Event_49943_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49943_Desc = {
    Text = "申し訳ない気持ちでいっぱいになりながらも、病床のラモンナを期待に満ちた目で見つめた。\n\n「私がやるわ」\n\n彼女は少し赤い顔のまま、手提げ鞄から新品の採集瓶を取り出し、素早く蜘蛛を捕らえた。"
  },
  Event_49943_Name = {Text = "毒蜘蛛"},
  Event_49944_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49944_Desc = {
    Text = "ライカーは指を鳴らし、毛むくじゃらの人差し指を高く上げた蜘蛛に向けた。\n\nこのような模様のある種は大抵、毒を持っているので注意を促そうとしたが、敵意に満ちていた蜘蛛は彼の指に軽やかに飛び乗り、丸まった。\n\nまあ、やり方は人それぞれか。"
  },
  Event_49944_Name = {Text = "毒蜘蛛"},
  Event_49945_ChoiceDesc1 = {
    Text = "【ラモンナを見る】3つの中から1つ刻印を獲得する"
  },
  Event_49945_ChoiceDesc2 = {
    Text = "【ライカーを見る】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_49945_Desc = {
    Text = "多くの複眼があなたをじっと見つめる。\n\n複眼の持ち主は半歩後退し、威嚇するように牙をむく。\n\n高く持ち上げた脚と触肢、体を支える二対の足から見て、これは確かに珍しい蜘蛛の生物だ。\n\n出発前のハレトの言葉を思い出す。\n「追加任務として、地元の種のサンプルを採集し、地元の調査所に保存せよ」\n\nあなたはバックパックの中の採集瓶を振る。数週間の旅の末、瓶は虫でいっぱいになっている。"
  },
  Event_49945_Name = {Text = "毒蜘蛛"},
  Event_49946_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49946_Desc = {
    Text = "「時をわきまえない貪欲は病気だ」"
  },
  Event_49946_Name = {
    Text = "あなたの答え"
  },
  Event_49947_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49947_Desc = {
    Text = "「教科書通りでは好感を得られないぞ、子供よ」"
  },
  Event_49947_Name = {
    Text = "あなたの答え"
  },
  Event_49948_ChoiceDesc1 = {
    Text = "【金の鍵】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_49948_ChoiceDesc2 = {
    Text = "【鉄の鍵】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_49948_ChoiceDesc3 = {
    Text = "【銀の鍵】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_49948_Desc = {
    Text = "正午、聖なる川の蒸気が2つの幻影を形作った。\n\n幻影がぼんやりとした声で尋ねる——\nこれはあなたが落とした金の鍵、銀の鍵、それとも鉄の鍵？"
  },
  Event_49948_Name = {
    Text = "あなたの答え"
  },
  Event_49949_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_49949_Desc = {
    Text = "「正直さはより安定した結果をもたらすことが多いが、同時に何かを逃すこともあるかもしれない」"
  },
  Event_49949_Name = {
    Text = "あなたの答え"
  },
  Event_50013_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50013_Desc = {
    Text = "じっくりと見極めようとするが、その顔は水面の揺れでぼやけている。\n\nじっと見つめるほど、呼吸が遅くなり、酸欠のような感覚が脳に広がる。\nラモンナの呼び声でようやく現実に引き戻された。\n\n水面に映る太陽は異常に眩しいが、水面下には何かが光っているようだ。"
  },
  Event_50013_Name = {
    Text = "死の幻影"
  },
  Event_50014_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50014_Desc = {
    Text = "幻影は触れるとすぐに消え、手には何も残らず、こめかみに激しい痛みが走る。\n\n水面に映る太陽は異常に眩しいが、水面下には何かが光っているようだ。"
  },
  Event_50014_Name = {
    Text = "死の幻影"
  },
  Event_50015_ChoiceDesc1 = {
    Text = "【懸命に確認する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50015_ChoiceDesc2 = {
    Text = "【手を伸ばして触れる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50015_ChoiceDesc3 = {
    Text = "【目をこする】25黒章を獲得する"
  },
  Event_50015_Desc = {
    Text = "ヌビアに押されて、片足が聖なる川に沈んだ。\n\n体勢を立て直そうとするが、揺れる水面に見えてはいけない影を見た。\n\nそれはミサゴ大学の制服を着た、背の高い青年で、彼の体は聖なる川の流れに沈んでいた。"
  },
  Event_50015_Name = {
    Text = "死の幻影"
  },
  Event_50016_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50016_Desc = {
    Text = "恐慌が心を蝕み、痛みで意識がぼやける。\n\n必死に引き裂こうとするが、蔓はますます締め付け、鼻腔に異臭を放つ粘液が染み込む。\n\n呼吸するたびに粘り気のある絶望が押し寄せる。\n\nラモンナが剣を振り下ろし、ヌビアは足を切られて逃げる。\n\n顔に張り付いた最後の触腕を引き剥がすと、そこにはぼやけた血肉が付着していた。"
  },
  Event_50016_Name = {
    Text = "襲いかかる"
  },
  Event_50017_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50017_Desc = {
    Text = "銀の光がヌビアの体に突き刺さり、血肉が爆裂する感覚がシルバーキーを通じて指先と手首に伝わる。\n\nヌビアのねじれた触肢が空に向かって高く掲げられ、恐怖と哀れみの悲鳴を上げ、全身が粘り気のある液体に変わる。"
  },
  Event_50017_Name = {
    Text = "襲いかかる"
  },
  Event_50018_ChoiceDesc1 = {
    Text = "【引き裂く】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50018_ChoiceDesc2 = {
    Text = "【スパイク】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_50018_Desc = {
    Text = "ヌビアの絡みつく触腕がねじれながら、隙を突いてあなたの頬に飛びかかり、口と鼻へ激しく侵入する。"
  },
  Event_50018_Name = {
    Text = "襲いかかる"
  },
  Event_50019_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50019_Desc = {
    Text = "水面にはきらめく波光だけが映る。\n\n濡れた足を引き上げ、靴の中の湿った砂利を出す。\n\nさっきの映像がまだ頭の中を巡り、消えない。"
  },
  Event_50019_Name = {
    Text = "死の幻影"
  },
  Event_50029_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50029_Desc = {
    Text = "「彼は戻ってくるのか？\nそれとも永遠にこの果てしない砂海に君を置き去りにするのか？」\n\n「彼は君を見つけられるのか？\nそれとも風向きと砂丘の変化で君の座標を見失うのか？」\n\n「他人に託した希望、本当にそんなに頼りになるのか？」"
  },
  Event_50029_Name = {
    Text = "失われた砂洲"
  },
  Event_50030_ChoiceDesc1 = {
    Text = "【救援を求める】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_50030_ChoiceDesc2 = {
    Text = "【共に前進する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_50030_Desc = {
    Text = "古く遠くからの声が、せせらぎの音と共にあなたに問いかける。\n\n「あなたは広大な砂漠に迷い込んでいる」\n\n「目の前には2つの選択肢がある。\n仲間の足が速いので、彼に食料と水を持たせて救援を求めに行かせ、最小限の消耗でその場に留まる」\n\n「または、すべてを共有して進み続ける」"
  },
  Event_50030_Name = {
    Text = "失われた砂洲"
  },
  Event_50031_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50031_Desc = {
    Text = "「君たちは必ずしも遠くまで行けるわけではないが、君たちの魂と肉体はしっかりと結びつき、互いに力を与える」\n\n「これが君の選択だ」\n\nそう言って、空高くの灼熱の太陽が目を閉じた。"
  },
  Event_50031_Name = {
    Text = "失われた砂洲"
  },
  Event_50064_ChoiceDesc1 = {
    Text = "【赤い絹を切断する】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_50064_ChoiceDesc2 = {
    Text = "【対抗する】指令カードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_50064_ChoiceDesc3 = {
    Text = "【ラモンナを呼ぶ】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_50064_Desc = {
    Text = "カーシアが赤い絹を投げ、瞬時にあなたの手提げを絡め取った。"
  },
  Event_50064_Name = {
    Text = "絡みつく絹"
  },
  Event_50065_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50065_Desc = {
    Text = "時折途切れる澄んだ音が、頭上の交錯するパイプの間で反響し、まるで独りで踊る幽霊がこの無音の中で無力な腕を振っているようだ。\n\nこの想像が心の奥底で古代の恐怖を呼び起こし、厳かな寒気を感じさせる。"
  },
  Event_50065_Name = {
    Text = "不気味な音階"
  },
  Event_50066_ChoiceDesc1 = {
    Text = "【洞窟の入り口を探索する】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_50066_ChoiceDesc2 = {
    Text = "【洞窟の奥へ進む】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50066_Desc = {
    Text = "「ここに洞窟があるわ」\n\nタイスが体を横にしてあなたを誘う。\n\n「中を見てみる？」\n\n狭い洞窟は暗く深く、悪魔の大口のように無限の闇へと伸びている。\n誰もがこの荒れた地に足を踏み入れると、背筋の奥から不吉な予感を振り払えない。\n洞窟の隅々に、日光を恐れる古代の生物が潜んでいるかのように、侵入者を待ち構えている。"
  },
  Event_50066_Name = {
    Text = "暗闇の洞窟"
  },
  Event_50067_ChoiceDesc1 = {
    Text = "【一つずつ撃破する】ランダムな低級遺物1つを高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_50067_ChoiceDesc2 = {
    Text = "【二人を囲む】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50067_ChoiceDesc3 = {
    Text = "【盗み聞きする】25黒章を獲得する"
  },
  Event_50067_Desc = {
    Text = "2人のアラン族が工場の門を守っている。\n\nそのうちの1人は暇そうにうろつき、もう1人に話しかけている。\n\n「誰かが言ってたけど、ジュリエット様がまた嵐の壁を突破しようとするチームを数えてるって」\n「絶対に選ばれたくないな」"
  },
  Event_50067_Name = {
    Text = "気ままな門番"
  },
  Event_50067_Tips1 = {
    Text = "まだ低級遺物を所持していません。"
  },
  Event_50068_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50068_Desc = {
    Text = "見ない、聞かない、考えない。\n\n不適切な音色がどこから来るのか幻想せず、母樹の遺骸へ直行する。"
  },
  Event_50068_Name = {
    Text = "不気味な音階"
  },
  Event_50069_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50069_Desc = {
    Text = "ラモンナが剣で赤い布を振るうカーシアを刺すと、カーシアは急いで避け、絡みついていた赤い布も瞬時に緩む。"
  },
  Event_50069_Name = {
    Text = "絡みつく絹"
  },
  Event_50070_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50070_Desc = {
    Text = "二手に分かれ、あなたとラモンナは左、ライカーは右から挟み撃ち。\n\nあなたが合図を送り、ラモンナとライカーが一斉に動き、2人のアラン族の守衛が無言で倒れる。"
  },
  Event_50070_Name = {
    Text = "気ままな門番"
  },
  Event_50071_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50071_Desc = {
    Text = "今は罠に深入りするべきではない。\n洞口をうろつくだけで、邪悪な鼓動を感じ取れる。"
  },
  Event_50071_Name = {
    Text = "暗闇の洞窟"
  },
  Event_50072_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50072_Desc = {
    Text = "あなたの合図で、ライカーは沈黙するアランの警備員をダイスでノックアウトし、まだおしゃべりをしているもう一人の男に静かに近づきました。\n\n「ねえ、お兄さん、あのジュリエット様が嘘つきだったらどうしたらいいと思いますか？」\n\n「どうすればいいのか分かりません」\n\nライカーは嬉しそうに歯をむき出した。\nライカーが口と鼻を覆ったとき、警備員は震えて叫びそうになった。"
  },
  Event_50072_Name = {
    Text = "気ままな門番"
  },
  Event_50073_ChoiceDesc1 = {
    Text = "【注意深く耳を傾ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_50073_ChoiceDesc2 = {
    Text = "【耳を塞ぐ】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_50073_ChoiceDesc3 = {
    Text = "【確認する】3つの中から1つ刻印を獲得する"
  },
  Event_50073_Desc = {
    Text = "遺骸がある階に入ると、廃工場の中で突然、心地よいピアノの音が響き渡る。\n錆びついた鉄の廃墟には不釣り合いな清らかな音色だ。"
  },
  Event_50073_Name = {
    Text = "不気味な音階"
  },
  Event_50074_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50074_Desc = {
    Text = "「ねえ、お兄さん、あのジュリエット夫人が嘘つきだったらどうしたらいいと思いますか？」\n\n「くだらないことを言わないでください。\nジュリエットが到着してからすべてが順調に進んでいます。\n彼女は嘘つきです。なぜ彼女はアラン族をそんなに助けるのですか？」\n\n彼らが雑談している間、ライカーは静かに待ち伏せの場所を選び、そして、2つのダイスが飛び出して、2人を地面に叩きつけた。"
  },
  Event_50074_Name = {
    Text = "気ままな門番"
  },
  Event_50075_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50075_Desc = {
    Text = "あなたは勇気を出して眼を見返す。\n\nしかし、幕の大きな眼は突然歪んで恐ろしく笑い、あなたの抗う意思は揺らぎ破られる。"
  },
  Event_50075_Name = {
    Text = "魔術の眼"
  },
  Event_50076_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50076_Desc = {
    Text = "君は集中して幕を引き裂いた。\n\n巨大な眼はあなたの手の下で平面的な破れた布に変わった。"
  },
  Event_50076_Name = {
    Text = "魔術の眼"
  },
  Event_50077_ChoiceDesc1 = {
    Text = "【睨み返す】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50077_ChoiceDesc2 = {
    Text = "【幕布を引き裂く】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_50077_Desc = {
    Text = "幕が開き、無数のねじれた巨大な眼が現れる。\n\n眼の奥に潜む巨大な存在が異常な飢えを露わにし、動き出そうとしている。"
  },
  Event_50077_Name = {
