  },
  Event_50078_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50078_Desc = {
    Text = "廃棄された長い部品があなたたちの動きで揺れ、鉄の管を叩いている。"
  },
  Event_50078_Name = {
    Text = "不気味な音階"
  },
  Event_50079_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50079_Desc = {
    Text = "タイスは落ち着いて洞窟に入り、あなたは後ろから慎重に探索する。\n\n「気をつけて！」\n突然引っ張られ、柔らかい腕の中に倒れ込む。\n目の前で、漆黒の巨獣が洞穴から猛然と飛び出した。\n\n「ここを見て」\nまだ驚きが冷めやらぬ中、タイスが口を開く。\n彼女の目は暗闇で微かに光っている。\n「恐らくこれはあの獣の宝物ね」"
  },
  Event_50079_Name = {
    Text = "暗闇の洞窟"
  },
  Event_50080_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50080_Desc = {
    Text = "必死に手提げ鞄の取っ手を掴み、赤い布と対抗する。\n\nしかし赤い布の力は強大で、手避け鞄が手から離れ、中身が散らばる。"
  },
  Event_50080_Name = {
    Text = "絡みつく絹"
  },
  Event_50081_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50081_Desc = {
    Text = "束縛されるのが嫌いだ。\n\n赤い布を引っ張り、ビリッと引き裂く。\n\n残った半分の赤い布は赤い蛇のように動き回る。"
  },
  Event_50081_Name = {
    Text = "絡みつく絹"
  },
  Event_50276_ChoiceDesc1 = {
    Text = "【供物を消滅させる】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50276_ChoiceDesc2 = {
    Text = "【縄を解く】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_50276_ChoiceDesc3 = {
    Text = "【前進し続ける】50黒章を獲得する"
  },
  Event_50276_Desc = {
    Text = "3人のアラン族が高台に縛られている。\n\n彼らの体には、見たことのある樹皮状の暗い模様が浮かび、呪文を唱えている。"
  },
  Event_50276_Name = {
