  },
  Event_50277_ChoiceDesc2 = {
    Text = "【無視する】3つの中から1つ刻印を獲得する"
  },
  Event_50277_Desc = {
    Text = "アラン族は砂嵐の中でひざまずく。\n\n嵐が彼らの体を叩き、砂が彼らの信仰心を巻き込む。\n\n砂塵の渦の中、無数の巨大な目が歪んだ大地を見下ろしているようだ。"
  },
  Event_50277_Name = {
    Text = "砂塵の巨物"
  },
  Event_50278_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50278_Desc = {
    Text = "思い出したくない光景が再び目の前に浮かぶ。\n\n揺れる触手、ガラス片が切り裂く血の跡……\n吐き気がする。"
  },
  Event_50278_Name = {
    Text = "孤独な旅Ⅱ"
  },
  Event_50279_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50279_Desc = {
    Text = "彼女はここにいない、彼女は最も危険な熱狂の中にいない。\n\nそれだけで安心できる。"
  },
  Event_50279_Name = {
    Text = "孤独な旅Ⅰ"
  },
  Event_50280_ChoiceDesc1 = {
    Text = "【奇襲】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_50280_ChoiceDesc2 = {
    Text = "【攻撃する】ランダムな指令カード3枚が刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50280_Desc = {
    Text = "ヌビアが激しい砂嵐の中で奮闘している。\n\n4つの蹄が深く砂に埋まり、渦に巻き込まれないよう必死に耐えている。"
  },
  Event_50280_Name = {
    Text = "自然の砂嵐"
  },
  Event_50281_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50281_Desc = {
    Text = "あなたは果敢に突入し、アラン族の驚きの声の中で縄を引きちぎる。\n\nアランの戦士が近づくと、あなたは彼の手から槍を奪い、暗闇の群衆に向ける。"
  },
  Event_50281_Name = {
    Text = "3つの供物"
  },
  Event_50282_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50282_Desc = {
    Text = "理性は彼がもう戻らないと告げる。\n\nそうだ、誰がギャンブラーの約束を信じるのか？\nあなたには孤独しかない。"
  },
  Event_50282_Name = {
    Text = "孤独な旅Ⅲ"
  },
  Event_50283_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50283_Desc = {
    Text = "異常な高熱は母なる木の復活と共に悪化するのか？\n\nラモンナは嵐の中で1人でやっていけるのか？\n\n今は気を散らす時ではないが、パートナーのことが心配でならない。"
  },
  Event_50283_Name = {
    Text = "孤独な旅Ⅰ"
  },
  Event_50284_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50284_Desc = {
    Text = "あなたは正面から挑むことを決意し、ヌビアは逆に足場を見つけたかのように飛び上がり、あなたの頭にしがみついた。\n\nあなたは砂嵐とヌビアの二重の絡み合いに陥った。\n\n「ただの勇気では勝てない」\nウィリアムの冷たい声は耳を塞がれたあなたにとってまるで天使の福音のようだった。\n\n「チャンスを掴むことを学べ」"
  },
  Event_50284_Name = {
    Text = "自然の砂嵐"
  },
  Event_50285_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50285_Desc = {
    Text = "今はのんびり新聞を読むときじゃない。"
  },
  Event_50285_Name = {
    Text = "彼女の忠告"
  },
  Event_50286_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50286_Desc = {
    Text = "考えない、思い出さない。\n\n思いたくない、思い出したくない。\n\nミサゴの伝説は終わるが、ミサゴの旅は止まらない。\n\n進み続けなければならない。\n進み続けなければならない。"
  },
  Event_50286_Name = {
    Text = "孤独な旅Ⅱ"
  },
  Event_50287_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50287_Desc = {
    Text = "「親愛なる守秘者へ\n元気にしてる？\n\n今回のヴォルムワヒの旅で体調を崩してしまって、あなたのそばにいられなくてごめんなさい。\n\nでも大事なときには、唯一の相棒を信じてほしい。\n\n必要なとき、私はいつでもいるから」\n\n時間の都合で、これ以上読むことはできない。\n\nしかし、見慣れた筆跡が心を落ち着かせてくれた。"
  },
  Event_50287_Name = {
    Text = "彼女の忠告"
  },
  Event_50288_ChoiceDesc1 = {
    Text = "【彼はまた来る】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_50288_ChoiceDesc2 = {
    Text = "【彼はもう来ない】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50288_Desc = {
    Text = "最後に去ったのはライカー。\n\nカーシアを止めるため、彼は天幕に留まることを選んだ。\n\n彼はかつてあなたに、儀式の場に突入して母樹を焼くと約束し、必ず付き合うと言った。\n\nしかし、彼はまだあなたのそばに戻っていない。\n\nあなたを一人残して。"
  },
  Event_50288_Name = {
    Text = "孤独な旅Ⅲ"
  },
  Event_50289_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50289_Desc = {
    Text = "ぐるぐると恐怖を感じる3つの物体が儀式の場に転がる。\n\n自分が自分でないように感じ、病的な狂熱の儀式の雰囲気に巻き込まれ、形容しがたい虚無に引き込まれる。"
  },
  Event_50289_Name = {
    Text = "3つの供物"
  },
  Event_50290_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50290_Desc = {
    Text = "アランの信仰は非常に篤く、何度も砂に埋もれることを厭わない。\n\nしかし、あなたが見上げると、嵐の中に太陽はない。"
  },
  Event_50290_Name = {
    Text = "砂塵の巨物"
  },
  Event_50291_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50291_Desc = {
    Text = "砂の海が彼らの信仰に応えることを願う。"
  },
  Event_50291_Name = {
    Text = "砂塵の巨物"
  },
  Event_50292_ChoiceDesc1 = {
    Text = "【記憶から逃れる】ランダムなカード1枚の刻印をアップグレードする"
  },
  Event_50292_ChoiceDesc2 = {
    Text = "【記憶を捉える】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_50292_Desc = {
    Text = "2人目に去ったのはウィリアム。"
  },
  Event_50292_Name = {
    Text = "孤独な旅Ⅱ"
  },
  Event_50293_ChoiceDesc1 = {
    Text = "【安心する】25黒章を獲得する"
  },
  Event_50293_ChoiceDesc2 = {
    Text = "【心配する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50293_Desc = {
    Text = "旅に出た日のことを突然思い出す。\n\nラモンナは荷物を忘れずに整えるようにと君に念を押した。\n\nウィリアムは道中の記録を綴るための手帳を用意してくれた。\n\nライカーはこっそりとウイスキーの瓶を君のバッグに忍ばせた。\n\n——だが、今や彼らは皆、去ってしまった。\n\n最初に去ったのはラモンナだった。\n\nタヴィの力は「嵐の壁」の権能と衝突し、彼女はそれに敗れた。\n\n炎のような高熱に蝕まれながら、彼女は道中で倒れてしまった。"
  },
  Event_50293_Name = {
    Text = "孤独な旅Ⅰ"
  },
  Event_50294_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50294_Desc = {
    Text = "あなたはヌビアの足を奇襲し、数本の蔓のような触手が空中で激しく乱舞し、最終的に砂嵐に巻き込まれた。"
  },
  Event_50294_Name = {
    Text = "自然の砂嵐"
  },
  Event_50295_ChoiceDesc1 = {
    Text = "【読む】カードを1枚削除する"
  },
  Event_50295_ChoiceDesc2 = {
    Text = "【しまう】「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_50295_Desc = {
    Text = "カタカタ。\n\nこの人間界とは思えない狂熱の祭壇の下、重い太鼓の音が砂風と共に響いてくる。\n絶え間ない詠唱の中、あなたはタイプライターの微かな音を聞く——それはミサゴからの呼びかけであり、あなたの不安な心を慰める。"
  },
  Event_50295_Name = {
    Text = "彼女の忠告"
  },
  Event_50296_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50296_Desc = {
    Text = "ライカーは世俗を超えた幸運を持っている。\n\n彼は約束したことを、必ずやり遂げる。\n\n絶対に。"
  },
  Event_50296_Name = {
    Text = "孤独な旅Ⅲ"
  },
  Event_50297_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_50297_Desc = {
    Text = "あなたには関係ない。\n\n今あなたに必要なのは、母樹の遺骸に接触し破壊することだ。"
  },
  Event_50297_Name = {
    Text = "3つの供物"
  },
  Event_52373_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_52373_Desc = {
    Text = "あなたは生き延びた。\n無数の土を積んだ山、焼かれた遺体を目にした。\n\nあなた自身の何かもまた、焼かれたようだ。\nだが、それはもう重要ではない。\n\nあなたは聞いた。\n神国の鐘の音がすでに鳴り響いている。"
  },
  Event_52373_Name = {
    Text = "疫病の襲来"
  },
  Event_52374_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_52374_Desc = {
    Text = "あなたは生き延びた。\n無数の土を積んだ山、焼かれた遺体を目にした。\n\nあなたは必死に自らの大切なものを守ろうとし、そのために痛ましい代償を払った。\nだが、それはもはや重要ではない。\n\n唯一重要なのは、神の国に一歩近づいたことだ。"
  },
  Event_52374_Name = {
    Text = "疫病の襲来"
  },
  Event_52375_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_52375_Desc = {
    Text = "巨人の怒りは一時的に消えた。\n雲が消え、雨が止み、風も静まった。\n\n海は永遠の慈母のように、優しい潮汐でリモリアの背をそっと撫でる。\nそして、リモリアには、荒れ果てた死体と廃墟だけが残された。\n\nあなたの何かが海に葬られたようだ。/nだが、それはもはや重要ではない。\n\n海の中で、あなたは神の国の輪郭を垣間見た。"
  },
  Event_52375_Name = {
    Text = "海の轟音の響き"
  },
  Event_52376_ChoiceDesc1 = {
    Text = "【追加の供物を捧げる】指令カード1枚を削除し、3種の「神国の幻影」各1枚をデッキに追加"
  },
  Event_52376_Desc = {
    Text = "リモリアの崩れ落ちた王座の前に立ち、あなたは最後の祈りを唱える。\n\n果てしなき深淵が目の前に広がる。\nあなたは跪き、微笑み、涙を流す。\n\n「見よ、父よ、デボラよ。見よ、我が至高の王——神国が、私の前に降臨したのです！」"
  },
  Event_52376_Name = {
    Text = "迎えよ、神の国"
  },
  Event_52377_ChoiceDesc2 = {
    Text = "【大切なものを守る】Arg1ライフを失い、ランダムな症状カードを1枚獲得する"
  },
  Event_52377_Desc = {
    Text = "大地。\n静かな大地、安定した大地。\n人類を支える大地、永遠不滅の大地。\n\nしかし今、その大地は震えている。\n底知れぬ裂け目を穿ち、支えていたすべてが揺らぎ崩れ落ちようとしている。\n\nあなたはすべての希望を大地に託した。\nだがその大地が震え始めた今、あなたはどこへ向かうというのか？\n\n捧げよ、リモリアの民があなたを呼びかける。\nすべてを捧げ、災いなき神の国を降臨させよ。"
  },
  Event_52377_Name = {
    Text = "大地の震え"
  },
  Event_52378_ChoiceDesc2 = {
    Text = "【大切なものを守る】Arg1ライフを失い、ランダムな症状カードを1枚獲得する"
  },
  Event_52378_Desc = {
    Text = "海。海はリモリアを育む母であり、あなたの生活であり、あなたの信仰である。\n\nしかし今、海は伝説の怒れる巨神のごとく立ち上がった。\nそれは叫び、吠える。温かな海水を、硬き巨岩と鋭き刃へと変え、目の前のすべてを薙ぎ払う。\n\nそれは冷ややかに、足元で戦慄するリモリアを、虫のように逃げ惑うリモリア人を見下ろす。\n\nそれはリモリアを破壊するだろう。\nリモリア事態とは一切の関係なく。\n\n捧げよ、リモリアの民があなたに呼びかける。\nすべてを捧げ、災いなき神の国を降臨させよ。"
  },
  Event_52378_Name = {
    Text = "海の轟音の響き"
  },
  Event_52379_ChoiceDesc2 = {
    Text = "【大切なものを守る】Arg1ライフを失い、ランダムな症状カードを1枚獲得する"
  },
  Event_52379_Desc = {
    Text = "疫病。\n疫病は至るところにある。\n\n疫病は最も恥知らぬ従僕であり、大地と海の神罰が過ぎ去った後に訪れる。\n\nそれは神の代わり、言葉にできぬ死を宣告する。\n\n肉親の遺体を埋葬し、焼却し、己を守るために死んだ最愛の家族に祈り……\nそして、できる限り己から遠ざける。\n生命も人間性も、疫病の前では打ち砕かれる。\n\n捧げよ、リモリアの民があなたに呼びかける。\nすべてを捧げ、災いのない神の国を降臨させよ。"
  },
  Event_52379_Name = {
    Text = "疫病の襲来"
  },
  Event_52380_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_52380_Desc = {
    Text = "激しい振動は収まった。\n街路には鮮紅の血痕が染みつき、崩れ落ちた家屋の下に無数の人々が埋もれている。\n\nあなたは必死に自らの大切なものを守ろうとし、そのために痛ましい代償を払った。\nだが、それはもはや重要ではない。\n\n唯一重要なのは、神の国に一歩近づいたことだ。"
  },
  Event_52380_Name = {
    Text = "大地の震え"
  },
  Event_52381_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_52381_Desc = {
    Text = "リモリアの崩れ落ちた王座の前に立ち、あなたは最後の祈りを唱える。\n\n果てしなき深淵が目の前に広がる。\nあなたは跪き、微笑み、涙を流す。\n\n「見よ、父よ、デボラよ。見よ、我が至高の王——神国が、私の前に降臨したのです！」"
  },
  Event_52381_Name = {
    Text = "迎えよ、神の国"
  },
  Event_52382_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_52382_Desc = {
    Text = "激しい振動は収まった。\n街路には鮮紅の血痕が染みつき、崩れ落ちた家屋の下に無数の人々が埋もれている。\n\nあなた自身の何かもまた、瓦礫の下に葬られたようだ。/nだが、それはもはや重要ではない。\n\n唯一重要なのは、神の国に一歩近づいたことだ。"
  },
  Event_52382_Name = {
    Text = "大地の震え"
  },
  Event_52383_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_52383_Desc = {
    Text = "巨人の怒りは一時的に消えた。\n雲が消え、雨が止み、風も静まった。\n\n海は永遠の慈母のように、優しい潮汐でリモリアの背をそっと撫でる。\nそして、リモリアには、荒れ果てた死体と廃墟だけが残された。\n\nあなたの何かが海に葬られたようだ。/nだが、それはもはや重要ではない。\n\n海の中で、あなたは神の国の輪郭を垣間見た。"
  },
  Event_52383_Name = {
    Text = "海の轟音の響き"
  },
  Event_52384_ChoiceDesc1 = {
    Text = "【敬虔な祈り】山札にある通常の症状カードを、1枚ごとに「神国の幻影」へと変化させ、さらに「神国の幻影」を2枚獲得する。"
  },
  Event_52384_ChoiceDesc2 = {
    Text = "【敬虔な祈り】山札にある通常の症状カードを、1枚ごとに「神国の幻影」へと変化させ、さらに「神国の幻影」を2枚獲得する。"
  },
  Event_52384_Desc = {
    Text = "大地はもはや戦慄せず、海はもはや轟かず、疫病ももはや襲い来ない。\n天災はリモリアを滅ぼし、あなただけが残った。\n\nあなたは頭を上げて周囲を見渡す。\n目に映るのは荒れ果てた光景。\nあなたはうつむき、手元を見下ろす。\nそこには何もない。\n\nだが、それがどうしたというのか、尊き祭司よ。\nリモリアの瓦礫と屍を踏み越え、なお前へ進め。\n\nあなたは神国まで、ただあと一歩の距離にある。"
  },
  Event_52384_Name = {
    Text = "迎えよ、神の国"
  },
  Event_53140_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_53140_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_53140_Name = {Text = "休憩所"},
  Event_53141_ChoiceDesc1 = {
    Text = "【休憩】Arg2ライフを回復する"
  },
  Event_53141_ChoiceDesc2 = {
