  },
  Event_53141_ChoiceDesc3 = {
    Text = "【処置】症状カードを最大3枚除去し、黒印をArg2獲得する。"
  },
  Event_53141_ChoiceDesc4 = {
    Text = "【狂気に堕ちる】ランダムな覚醒体を2体選択して覚醒させ、ランダムな症状を1枚獲得する"
  },
  Event_53141_ChoiceDesc5 = {
    Text = "【ためらい】その他"
  },
  Event_53141_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n\n通信機から誰かが呼んでいる。"
  },
