  },
  Event_53148_Desc = {
    Text = "あなたは通信に応答した。\n通信機の向こうから響いたのは、狂気に満ちた、しかし魅了されるような声だった。\n\n「銘記しなさい。\nこれは神国があなたに与える恩寵です」"
