  Event_55782_ChoiceDesc1 = {
    Text = "【茨を断ち切る】次の戦闘で敵のライフが30%増加し、ダメージが15%増加する。Arg1枚のイメージ「(Skill.Arg2)」を獲得する。"
  },
  Event_55782_ChoiceDesc2 = {
    Text = "【茨を断ち切る】次の戦闘で敵のライフが30%増加し、ダメージが15%増加する。Arg1枚のイメージ「(Skill.Arg2)」を獲得する。"
  },
  Event_55782_ChoiceDesc3 = {
    Text = "【茨を押し分ける】「(Skill.Arg3)」に感染し、Arg1枚のイメージ「(Skill.Arg2)」を山札に追加する。"
  },
  Event_55782_ChoiceDesc4 = {
    Text = "【茨を押し分ける】「(Skill.Arg3)」に感染し、Arg1枚のイメージ「(Skill.Arg2)」を山札に追加する。"
  },
  Event_55782_ChoiceDesc5 = {
    Text = "【茨から離れる】「オルラのペンとインク」がArg1点の「ペンとインク」を獲得する"
  },
  Event_55782_Desc = {
    Text = "何かがあなたの心を打った。\n足を止め、庭の隅を見つめる。\n\n茨の下で、光の点が跳ねており、束縛を解こうとしている。\n\n何？蝶？鳥？あなたはそれに近づく。"
  },
  Event_55782_Name = {
    Text = "ミューズの加護"
  },
  Event_55782_Tips1 = {
    Text = "次の戦闘の敵が強化されています。再選択できません。"
  },
  Event_55783_ChoiceDesc1 = {
    Text = "【献詩を創作する】3枚の「イメージ」カードを選択し、オルラに「献詩」を創作させる。"
  },
  Event_55783_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_55783_Desc = {
    Text = "美しい温室の前に来て、窓越しに中を覗くが、何も見えない。\n\n風が吹き、温室の花びらと落ち葉が舞い上がり、空中で舞い集まる。\nその中に少女の姿が見えた。\n\n「あ！花、庭にお客さんが！」\n少女は驚きと緊張でこちらを見つめる。\n\n「ごめんなさい、コレットは外出中で……花を買うなら、値段はよくわからなくて……」\n少女は突然止まり、近づいてこちらをじっと見た。\n\n「あ、お客様に詩のイメージを感じます……一緒に詩を作りませんか？」"
  },
  Event_55783_Name = {
    Text = "春の贈り物"
  },
  Event_55783_Tips1 = {
    Text = "「イメージ」カードが3枚未満のため、合成できません。"
  },
  Event_55799_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_55799_Desc = {
    Text = "生きている茨は少し動揺しているようだが、その代償は些細なものだ——\n\nその光点の中から、あなたはミューズの呼び声を聞いた。"
  },
  Event_55799_Name = {
    Text = "ミューズの加護"
  },
  Event_55819_ChoiceDesc1 = {
    Text = "【肉体の記憶に従う】戦闘をスキップして即座に勝利するが、Arg1ライフを失う"
  },
  Event_55819_ChoiceDesc2 = {
    Text = "【離れる】戦闘に入る"
  },
  Event_55819_Desc = {
    Text = "馴染みの敵に直面した。\n\n次の戦いはもうお手の物だ。"
  },
  Event_55819_Name = {
    Text = "肉体の記憶"
  },
  Event_55997_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_55997_Desc = {
    Text = "集めたイメージから、いくつかを選んで少女に手渡した。\n\n「なんて美しいイメージ！お客様、ちょっと待って……これをどうぞ。\nこれは春がもたらした、あなた専用の献詩です！」\n一編の詩があなたの手に現れ、それはまるであなたのために咲いた花のようだった。\n\n少女に感謝したいと思ったが、顔を上げたときには少女の姿は消えていた。\n孤独な温室には、枯れた花と葉だけが残っていた。\n\n——それは春が燃え尽きた後に残した灰だった。"
  },
  Event_55997_Name = {
    Text = "春の贈り物"
  },
  Event_55999_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_55999_Desc = {
    Text = "重なる棘に尻込みした。\n光点を離れたが、短い凝視が新たな啓示で心を満たした——\n\nその光点の中から、あなたはミューズの呼び声を聞いた。"
  },
  Event_55999_Name = {
    Text = "ミューズの加護"
  },
  Event_56000_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_56000_Desc = {
    Text = "あなたは手で棘をかき分け、そのために少し傷を負ったが、その代償は些細なものだ——\n\nその光点の中から、あなたはミューズの呼び声を聞いた。"
  },
  Event_56000_Name = {
    Text = "ミューズの加護"
  },
  Event_56024_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_56024_Desc = {
    Text = "まだ足りない……さらに光に近づく。\n茨が怒り、鋭い棘を見せてきた。\nしかし、それでも価値がある。\n\nその光が手のひらから広がり、光の幕の中で、ミューズの加護をはっきりと感じた。"
  },
  Event_56024_Name = {
    Text = "ミューズの加護"
  },
  Event_56025_ChoiceDesc1 = {
    Text = "【光点に近づく】次の戦闘で敵のライフが追加で30%増加し、ダメージが追加で15%増加する。1枚の「イメージ」をアップグレードすることを選択できる。"
  },
  Event_56025_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_56025_Desc = {
    Text = "持ち歩いている道具で茨を切り払った。\n生きている茨は少し動揺しているようだが、その代償は些細なものだ——\n\nその光点の中から、あなたはミューズの呼び声を聞いた。"
  },
  Event_56025_Name = {
    Text = "ミューズの加護"
  },
  Event_56146_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_56146_Desc = {
    Text = "まだ足りない……光に近づき続ける。\n鋭い棘が手を傷つけ、血が止まらない。\nでも、それだけの価値がある。\n\nその光が手のひらから広がり、光の幕の中で、ミューズの加護をはっきりと感じた。"
  },
  Event_56146_Name = {
    Text = "ミューズの加護"
  },
  Event_56147_ChoiceDesc1 = {
    Text = "【創作衝動】すべての覚醒体がすべての狂気を失う。3枚の「イメージ」カードを選択し、オルラに「献詩」を創作させる"
  },
  Event_56147_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_56147_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_56147_Name = {Text = "休憩所"},
  Event_56147_Tips1 = {
    Text = "「イメージ」カードが3枚未満のため、合成できません。"
  },
  Event_56148_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_56148_Desc = {
    Text = "校章の銀光に心が揺れる。\n心の導きに従い、手に持っていたものを茨に投げ込む。\n\n茨の下の光が輝き始め、その光の中で新たな啓示を得た。"
  },
  Event_56148_Name = {Text = "休憩所"},
  Event_56149_ChoiceDesc1 = {
    Text = "【光点に近づく】ライフ上限が10%減少する。1枚の「イメージ」をアップグレードすることを選択できる。"
  },
  Event_56149_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_56149_Desc = {
    Text = "あなたは手で棘をかき分け、そのために少し傷を負ったが、その代償は些細なものだ——\n\nその光点の中から、あなたはミューズの呼び声を聞いた。"
  },
  Event_56149_Name = {
    Text = "ミューズの加護"
  },
  Event_56149_Tips1 = {
    Text = "強化できない「イメージ」です。"
  },
  Event_56150_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_56150_Desc = {
    Text = "校章の銀の輝きに心が揺さぶられる。\n\n強い衝動に駆られ、頭に浮かんだ詩句を書き留めた。"
  },
  Event_56150_Name = {Text = "休憩所"},
  Event_56151_ChoiceDesc1 = {
    Text = "【新たな啓示】1枚の「イメージ」を選択し除去する。ランダムな「イメージ」1枚を「詳細なイメージ」にアップグレードする"
  },
  Event_56151_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_56151_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_56151_Name = {Text = "休憩所"},
  Event_56151_Tips1 = {
    Text = "「イメージ」カードはありません。"
  },
  Event_57738_ChoiceDesc1 = {
    Text = "【強行突破】すべての覚醒体が30狂気を獲得するが、「(Skill.Arg1)」を2枚デッキに加える"
  },
  Event_57738_ChoiceDesc2 = {
    Text = "【武装解除】次の戦闘で敵のライフが60%増加し、ダメージが30%増加する"
  },
  Event_57738_ChoiceDesc3 = {
    Text = "【待ち伏せ】すべての覚醒体の狂気を消費し、30黒章を獲得し、守衛を排除する"
  },
  Event_57738_Desc = {
    Text = "死角から外を覗く。\n監視員は別の方向を見ていて、こちらに気づいていない。\n\n訓練の光景が頭をよぎり、この道を塞ぐ敵への対処法をすぐに思いついた。"
  },
  Event_57738_Name = {Text = "監視員"},
  Event_57738_Tips3 = {
    Text = "すべての覚醒体は狂気を所持していません。"
  },
  Event_57739_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_57739_Desc = {
    Text = "注意深く観察する。\n監視員が進路を塞ぎ、目の前のエリアを厳重に監視している。\n\n多くの敵を前に、対抗することはできない。\n\n進むか、退くか？"
  },
  Event_57739_Name = {Text = "拘留所"},
  Event_57776_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_57776_ChoiceDesc2 = {
    Text = "【偽装降伏】このエリアを探索後、拘留所に転送され、ランダムな「症状」を2枚獲得する"
  },
  Event_57776_ChoiceDesc3 = {
    Text = "【突入】このエリアを探索後、拘留所に転送され、Arg1ライフを失う"
  },
  Event_57776_Desc = {
    Text = "注意深く観察する。\n監視員が進路を塞ぎ、目の前のエリアを厳重に監視している。\n\n多くの敵を前に、対抗することはできない。\n\n進むか、退くか？"
  },
  Event_57776_Name = {Text = "検査所"},
  Event_57776_Tips3 = {
    Text = "ライフが不足しています。"
  },
  Event_59193_ChoiceDesc1 = {
    Text = "【アリステアの祝福】「極夜の微光」を1枚山札に加える"
  },
  Event_59193_Desc = {
    Text = "この入学証書はずっと手提げ鞄の底にしまっていた。\n星の輝きを帯びた精巧な縁を撫で、紙特有の淡いインクの香りを嗅ぐ。\n\nミサゴの校章は未来への輝かしい入口のようで、あの日も今も、あなたの渇望する目を引きつける。"
  },
  Event_59193_Name = {Text = "入学式"},
  Event_59527_ChoiceDesc1 = {
    Text = "指令カード1枚を選択して「知識の理」を刻印する。\n「知識の理」：カードを2枚引き、それらの行動力消費を刻印カードの行動力と同じだけ減少する。各戦闘で1回のみ発動可能。"
  },
  Event_59527_Desc = {
    Text = "知識の印があなたの証明書に刻まれる。\n\nタヴィの思考があなたの頭に流れ込む。\n無限の可能性の中で、あなたは唯一の正しい道を進んでいる。"
  },
  Event_59527_Name = {Text = "入学式"},
  Event_59528_ChoiceDesc1 = {
    Text = "指令カード1枚を選択して「歓喜の理」を刻印する。\n「歓喜の理」：この覚醒体以外のすべてのカードを捨て、ランダムな非覚醒体のカードを5枚獲得。各戦闘で1回のみ発動可能。"
  },
  Event_59528_Desc = {
    Text = "歓喜の印があなたの証明書に刻まれる。\n\n印を通じて、Nがあなたを見ている。\n彼はあなたがもたらす未曾有の結末を期待している。"
  },
  Event_59528_Name = {Text = "入学式"},
  Event_59529_ChoiceDesc1 = {
    Text = "指令カードを1枚選択して「繁殖の理」を刻印する。「繁殖の理」：<RetainIconKeywords:保持>と<DepleteIconKeywords:除外>を付与した未強化コピーを3枚獲得。各戦闘で1回のみ発動可能。"
  },
  Event_59529_Desc = {
    Text = "繁殖の印があなたの証明書に刻まれる。\n\nタイスはあなたに希望を託し、すべての世界で共生する。"
  },
  Event_59529_Name = {Text = "入学式"},
  Event_59566_ChoiceDesc1 = {
    Text = "【血の涙を拭う】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_59566_ChoiceDesc2 = {
    Text = "【目を開け続ける】ランダムな指令カード3枚が刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59566_Desc = {
    Text = "無数のあなたの願いが一つに溶け合い、かつてあなたたちは同じ出自を持ち、今は同じ体を共有している。\n\n無数の目が一斉に開き、その巨大な瞳に立ち向かう。\n\n無数の目が一斉に砕け、痛みと乾いた血の涙を流す。"
  },
  Event_59566_Name = {
    Text = "私の融合"
  },
  Event_59567_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59567_Desc = {
    Text = "君はその狂気の声に反論し、虚無の理念に異議を唱える。\n\n「すべては死に向かうが、ライフそのものに意味はないのか？」\n君は理論で戦うが、その笑い声は減ることなく、君の愚かさを嘲笑しているようだ。"
  },
  Event_59567_Name = {
    Text = "死を待つ子羊"
  },
  Event_59568_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59568_Desc = {
    Text = "あなたはその扉を見つめ、無知の痛みをもう耐えたくないと思っている。\n\n扉の向こうの景色を見たい。\n\n虚構の扉が幻想的に揺れ、無数の世界の幻影が一瞬で過ぎ離れる。\n\n見極める暇もなく、無限の情報があなたの精神を押し流し、脳が混乱のノイズで満たされる。"
  },
  Event_59568_Name = {
    Text = "扉の向こう"
  },
  Event_59569_ChoiceDesc1 = {
    Text = "【断固として指揮する】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_59569_ChoiceDesc2 = {
    Text = "【共に話し合う】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_59569_Desc = {
    Text = "すべてが突然起こり、周囲はぼんやりとした煙に包まれている。\n君は必死に見渡すが、何も見えない。\n\n覚醒体たちは君の指示を待っている。\n\n今、君は孤立無援で、自分の力に頼るしかない。"
  },
  Event_59569_Name = {
    Text = "無知の目"
  },
  Event_59570_ChoiceDesc1 = {
    Text = "【犠牲によって】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59570_ChoiceDesc2 = {
    Text = "【勇気をもって】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_59570_ChoiceDesc3 = {
    Text = "【直視によって】50黒章を獲得する"
  },
  Event_59570_Desc = {
    Text = "数え切れないほどのあなたは、あたかも兄弟姉妹であるかのように、数え切れないほどの世界に肩を並べて手をつないで立っている。\n\n今、あなた方二人はその巨大な影の下に立って、顔を上げて一歩も退かないでいる。\n\n究極の自分に勝つには何をするべきか？"
  },
  Event_59570_Name = {
    Text = "私の答え"
  },
  Event_59571_ChoiceDesc1 = {
    Text = "【答えを探す】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_59571_ChoiceDesc2 = {
    Text = "【諦める】25黒章を獲得し、離れる"
  },
  Event_59571_Desc = {
    Text = "扉を通り抜ける幻影、あなたが経験したすべてが頭の中でフラッシュバックする。\n\n死んだ者、狂った者、耐えた者、堕ちた者……\n無数の道、無数の選択が目の前でフラッシュバックし、一瞬で長い人生を生きたように感じる。\n\n今、無数の頭脳、無数の口が同時に動いている。\n\n時空を超えて無数の自分と対話し、無限の記憶から答えを探ろうとする。"
  },
  Event_59571_Name = {
    Text = "私の自問"
  },
  Event_59572_ChoiceDesc1 = {
    Text = "【力を交換する】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_59572_ChoiceDesc2 = {
    Text = "【幸運を交換する】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_59572_Desc = {
    Text = "すべての選択には代償がある。\n\n生命、精神、感情、記憶……\nあなたは運命で何を交換し、何を天秤にかけるのか？"
  },
  Event_59572_Name = {
    Text = "運命の選択"
  },
  Event_59573_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59573_Desc = {
    Text = "人はどうして心臓がないのに生きられるの？\n\n慌てて周りを探し、呼吸がだんだん速くなり、死の恐怖が脳を覆う。\n\n「息ができない……心臓が止まりそうだ……」\n\n待って、もう心臓は必要ないみたいだ。\n\nあなたは気づいて、笑みがこぼれた。"
  },
  Event_59573_Name = {
    Text = "胸の空洞"
  },
  Event_59574_ChoiceDesc1 = {
    Text = "【直視する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59574_ChoiceDesc2 = {
    Text = "【逃避する】ランダムな覚醒体を2体選択して覚醒させ、2枚の「(Skill.Arg1)」に感染する"
  },
  Event_59574_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_59574_Desc = {
    Text = "虚空から何かがあなたを見つめているのを感じる。\n\nどこへ行っても、その視線は影のように付きまとう。\n\n小さな獲物として狙われているようで、背中が刺すように痛む。"
  },
  Event_59574_Name = {
    Text = "虚空からの視線"
  },
  Event_59575_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59575_Desc = {
    Text = "狂乱の演奏に動じず、自分のペースを貫く。\n\n相手の攻撃や誘惑は効かず、ピアノで二つの曲が同時に奏でられる。\n最後まで耐えた者がすべての音符を操る。"
  },
  Event_59575_Name = {
    Text = "終末の狂騒曲"
  },
  Event_59576_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59576_Desc = {
    Text = "あなたはすべての勇気を振り絞り、どんな困難にも仲間と共に立ち向かう。"
  },
  Event_59576_Name = {
    Text = "未来の固定"
  },
  Event_59577_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59577_Desc = {
    Text = "「今どこにいるの？」\n「先生たちはどうするつもり？」\n「次に何をすればいい？」\nあなたは急いで問いかけ、いつものように頼れる存在に依存したいと思った。\n\n通信機はフリーズしたかのように反応を失い、あなたは機械を揺らし、揺れの中で返事の文字が歪んで蝶の群れとなり、あなたの顔に舞い降りた。\n\n目をこすり、すべてが幻覚であることに気づいた。\n\n返事の紙には何も書かれていなかった。"
  },
  Event_59577_Name = {
    Text = "幻惑の共鳴"
  },
  Event_59578_ChoiceDesc1 = {
    Text = "【慌てて探す】最大ライフをArg1増加させる"
  },
  Event_59578_ChoiceDesc2 = {
    Text = "【埋めようとする】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_59578_Desc = {
    Text = "胸の中が空虚で軽くなったのを感じ、下を見ると、胸が鍵穴の形に開いていて心臓が消えていた。"
  },
  Event_59578_Name = {
    Text = "胸の空洞"
  },
  Event_59579_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59579_Desc = {
    Text = "あなたは彼の目的を問い詰めるが、変わらぬ微笑みしか返ってこない。\n\n彼はすでに世界を離れ、何にも縛られない者は何にも責任を持たない。\n\nあなたは無駄に抵抗するしかなかった。"
  },
  Event_59579_Name = {
    Text = "狂気の紳士"
  },
  Event_59580_ChoiceDesc1 = {
    Text = "【リズムを乱す】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59580_ChoiceDesc2 = {
    Text = "【自分を保つ】3つの中から1つ刻印を獲得する"
  },
  Event_59580_Desc = {
    Text = "あなたは狂気の人と共に演奏しているようだ。\n彼女はあなたを鍵盤に縛り付け、彼女の狂気の曲に巻き込む。\n\n彼女のリズムの中で、あなたは必死に演奏し、よろめきながら進む。\n\nあなたは彼女と戦い、曲調をコントロールしようとする。"
  },
  Event_59580_Name = {
    Text = "終末の狂騒曲"
  },
  Event_59581_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59581_Desc = {
    Text = "無敵の力を持ち、すべての枷や障害を打ち砕きたいと願う。\n\nしかし人の力には限界があり、神に挑む小さな体は、マッチのように生命を燃やし尽くすだろう。"
  },
  Event_59581_Name = {
    Text = "運命の選択"
  },
  Event_59582_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59582_Desc = {
    Text = "「なくなった……なくなった……」\n\n虚しさが辛くて、懐中時計、リンゴ、制服の上着を手に取り、胸の空洞を埋めようとした。\n\n胸が再びいっぱいになったが、満腹感が強すぎる気がした。\n\n大丈夫、物事は完璧にはならないものだ。"
  },
  Event_59582_Name = {
    Text = "胸の空洞"
  },
  Event_59583_ChoiceDesc1 = {
    Text = "【説得する】25黒章を獲得する"
  },
  Event_59583_ChoiceDesc2 = {
    Text = "【問い詰める】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59583_Desc = {
    Text = "Nの革靴があなたの前で止まり、あなたはその漆黒の顔に浮かぶ大げさな笑みを見た。\n彼はいつも品よく装っているが、あなたはその紳士的な外見の下には最も純粋な発狂しかないことを知っている。\n彼には友人もなく、敵もほとんどいない。\nなぜならそういった人々は最も劇的な形で完全に消えてしまうからだ。\n\n残念なことに、今あなたは彼に次の劇の主役として選ばれた。\n幕開けの台詞を用意しなさい、この最も気難しい観客を満足させるにはどうすればよいのか？"
  },
  Event_59583_Name = {
    Text = "狂気の紳士"
  },
  Event_59584_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59584_Desc = {
    Text = "覚醒体たちもあなた以上に知っているわけではないが、彼らは最も忠実な仲間であり、戦友であり、支えだ。\n\nあなたは覚醒体たちと対策を話し合い、心の中で迷いながらも再出発の勇気を持つ。"
  },
  Event_59584_Name = {
    Text = "無知の目"
  },
  Event_59585_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59585_Desc = {
    Text = "まるで自分に決意を固めたかのように、あなたは力強く応答する。\n\nあなたの声は無数の泡の間で響き渡り、まるで無数のあなたが一緒に誓っているかのようだ。\n\nあなたはすべてに立ち向かう準備ができている。"
  },
  Event_59585_Name = {
    Text = "彼の問い"
  },
  Event_59586_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59586_Desc = {
    Text = "あなたは動かず、ただ返事の文字をじっと見つめていた。\n\nその視線の中で、文字は徐々にぼやけて歪み、最終的には蝶の群れとなってあなたの顔に舞い降りた。\n\n両手で蝶を追い払い、振り返ると返事の紙には何も書かれていなかった。"
  },
  Event_59586_Name = {
    Text = "幻惑の共鳴"
  },
  Event_59587_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59587_Desc = {
    Text = "あなたはこれらの卑劣な糸を憎んでいる。\n\nあなたはそれらを力いっぱい引っ張り、一部の糸は切れるが、無数の糸が再び絡みつく。\n\nあなたは全力を尽くし、それらと絶えず対抗する。"
  },
  Event_59587_Name = {
    Text = "操られた手"
  },
  Event_59588_ChoiceDesc1 = {
    Text = "【人影を斬る】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_59588_ChoiceDesc2 = {
    Text = "【胚胎を踏み砕く】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_59588_ChoiceDesc3 = {
    Text = "【目を閉じる】25黒章を獲得する"
  },
  Event_59588_Desc = {
    Text = "ぼんやりと、アランで見たことのある人々があなたに近づいてくる。\n\n彼らは笑いながら、酒を飲み、踊り、美食を楽しむように誘う。\n\nそして彼らの血肉が次々と剥がれ落ち、地面に落ちたものが蠢いて新たな胚胎を生み出す。\n\n彼らは手を差し伸べ、血肉と新生の狂宴にあなたを誘う。"
  },
  Event_59588_Name = {
    Text = "過去の影"
  },
  Event_59589_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59589_Desc = {
    Text = "手を差し伸べる前に、こんな猫を育てたことがないことを思い出した。\n\n見つめると、猫はあなたにウインクする。\n\n戸惑うあなたを気にせず、猫は親愛の情を向けてくる。"
  },
  Event_59589_Name = {
    Text = "猫の誘惑"
  },
  Event_59590_ChoiceDesc1 = {
    Text = "【象嵌する】1つの遺物を呪われた遺物「(RelicConfig.Arg1)」に変化させる"
  },
  Event_59590_ChoiceDesc2 = {
    Text = "【飲み込む】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59590_ChoiceDesc3 = {
    Text = "【しまう】25黒章を獲得する"
  },
  Event_59590_Desc = {
    Text = "体内の三大神子の力が融合し、あなたはこの巨大な力を必死に操る。\n\n精神空間が膨張し、ここに銀河が誕生し、広がっていく。\n\n絶え間なく現れる敵に直面し、あなたは心からこの星空に祈り、この力の助けを願う。\n\n一つの星が銀河から落ちてあなたの手のひらに届き、魅惑的な光を放つ。"
  },
  Event_59590_Name = {Text = "願い星"},
  Event_59591_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59591_Desc = {
    Text = "あなたも沈黙で応じる。\n交流はなく、沈黙がすべての答え。\n\nあなたはすべてに立ち向かう準備ができている。"
  },
  Event_59591_Name = {
    Text = "彼の問い"
  },
  Event_59592_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59592_Desc = {
    Text = "あの猫は詐欺師なのか？\n池のような青い目を疑い始め、耳元で笑い声が絶え間なく響く。\n\n「詐欺師、詐欺師、騙されたな！」\n心の中に不安が湧き上がる。"
  },
  Event_59592_Name = {
    Text = "秘密の囁き"
  },
  Event_59593_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59593_Desc = {
    Text = "あなたは傍観者のように、徐々に見知らぬ感情を静かに見つめている。\n\nすべての未練を抑え、魂が徐々に冷たくなるのを感じる。\n\nこれはあなたの運命であり、避けられない道だ。"
  },
  Event_59593_Name = {
    Text = "感情の結晶"
  },
  Event_59594_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59594_Desc = {
    Text = "その笑顔は無表情で、理性や感情で彼を動かすことはできない。\n\n人間の欲望は彼には関係ない。\n\nあなたの言葉は人間の想像を超えられるのか？"
  },
  Event_59594_Name = {
    Text = "狂気の紳士"
  },
  Event_59595_ChoiceDesc1 = {
    Text = "【応える】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59595_ChoiceDesc2 = {
    Text = "【沈黙する】ランダムな覚醒体を2体選択して覚醒させ、2枚の「(Skill.Arg1)」に感染する"
  },
  Event_59595_Desc = {
    Text = "無数の泡が無数の丸い目のように、彼は沈黙してあなたを見つめ、無言の問いかけをしているようだ。\n\n準備はできたか？\n\nすべてを捨てる準備はできたか？\n\nすべてを背負う準備はできたか？"
  },
  Event_59595_Name = {
    Text = "彼の問い"
  },
  Event_59596_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59596_Desc = {
    Text = "相手が攻撃を仕掛けた瞬間、あなたはすぐに反撃を開始した。\n\n彼らの本当の姿を賢明に見抜いた、彼らは牙をむく獣の群れだった。\n\nあなたは幸運にも勝利した。\n\n今すぐ逃げよう、絶対に捕まらないように。"
  },
  Event_59596_Name = {
    Text = "深淵に沈む"
  },
  Event_59597_ChoiceDesc1 = {
    Text = "【答えを探す】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_59597_ChoiceDesc2 = {
    Text = "【諦める】離れる"
  },
  Event_59597_Desc = {
    Text = "どうするべきか？\n\n無数の自分を見つめ、無数の同じ顔があなたを見つめている。\n\n希望の糸を掴むように、必死に探し、聞き、最終的な答えを求める。"
  },
  Event_59597_Name = {
    Text = "私の自問"
  },
  Event_59598_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59598_Desc = {
    Text = "時機はまだ来ていない、あなたは忍耐強く待つ必要がある。\n\nあなたは悔しさと憎しみを飲み込み、一か八かのその瞬間を待っている。"
  },
  Event_59598_Name = {
    Text = "操られた手"
  },
  Event_59599_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59599_Desc = {
    Text = "何かに引き寄せられるような感覚があり、その視線の源を見極めたいと思う。\n\n虚空を見つめるうちに、何かを見たような気がする。\n\n視界が一瞬で雪のようにぼやけ、世界が変わったように感じる。\n\n目をこすり、血の涙が流れているのに気づく。"
  },
  Event_59599_Name = {
    Text = "虚空からの視線"
  },
  Event_59600_ChoiceDesc1 = {
    Text = "【懸命に思い出す】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_59600_ChoiceDesc2 = {
    Text = "【悲しみを味わう】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_59600_ChoiceDesc3 = {
    Text = "【黙って受け入れる】25黒章を獲得する"
  },
  Event_59600_Desc = {
    Text = "まるで精密な脳手術を受けたかのように、あなたは大切な記憶が頭から抜け落ちていくのをはっきりと感じ、脳がぼんやりと溶けそうになる。\n\n苦しみながら震え、止めようとする手を押さえる。\n\n涙が頬を伝うが、それは何のために流れているのだろう？\n\n思い出せないようだ。\n\n何とも言えない悲しみがこみ上げてくる。"
  },
  Event_59600_Name = {
    Text = "記憶解離"
  },
  Event_59601_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59601_Desc = {
    Text = "猫との友情は疑いようもなく、手を振って振り返らずに進む。\n\n「バカ！バカ！」\n耳元で声が怒り狂う。"
  },
  Event_59601_Name = {
    Text = "秘密の囁き"
  },
  Event_59602_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59602_Desc = {
    Text = "どんな犠牲を払っても、みんなの希望を胸に最後まで戦うと決意する。"
  },
  Event_59602_Name = {
    Text = "未来の固定"
  },
  Event_59603_ChoiceDesc1 = {
    Text = "【抑制】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_59603_ChoiceDesc2 = {
    Text = "【注視する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59603_Desc = {
    Text = "タヴィが守る扉の先には無限の世界と無限の真理がある。\n\n彼女が扉の向こうで何を見たかは知らないが、彼女はすべてを知っている。\n\n今、この扉があなたの前に開かれ、すべての真実が招待をしている。"
  },
  Event_59603_Name = {
    Text = "扉の向こう"
  },
  Event_59604_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59604_Desc = {
    Text = "未知の存在には敬意を払い、避けるのが賢明な選択だ。\n\n頭を下げ、胸のシルバーキーを握りしめ、少し安心する。\n\n少なくとも、まだ力があり、覚醒体たちがいる。\n\nその視線を無視し、目の前の道に集中する。\n\nだが、その視線は本当に消えたのか？\n心の中では分かっている。"
  },
  Event_59604_Name = {
    Text = "虚空からの視線"
  },
  Event_59605_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59605_Desc = {
    Text = "もし神に抗う手段がすべて無駄なら、唯一持ち続けられるのは諦めない勇気だけだ。\n\n無限の破壊が空から迫るとき、あなたは最前線に立つ者となる。"
  },
  Event_59605_Name = {
    Text = "私の答え"
  },
  Event_59606_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59606_Desc = {
    Text = "流れ落ちる涙をぼんやりと触れ、どこから来たのかわからない悲しみを噛みしめる。\n\n大切なものを自ら捨てたようだが、それが何か思い出せない。\n\n本当に残念だ。\n\n涙を拭いながら、苦い笑みを浮かべる。"
  },
  Event_59606_Name = {
    Text = "記憶解離"
  },
  Event_59607_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59607_Desc = {
    Text = "彼らの声を無視した。\n\n猫が嘘つきかどうかは気にせず、自分の力を信じるだけ。\n\n耳元で声がため息をつく。"
  },
  Event_59607_Name = {
    Text = "秘密の囁き"
  },
  Event_59608_ChoiceDesc1 = {
    Text = "【答えを探す】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_59608_ChoiceDesc2 = {
    Text = "【諦める】離れる"
  },
  Event_59608_Desc = {
    Text = "もう一人の自分が笑っている。\n\nその自分は、すべてが無駄な抵抗であり、早く諦めた方がいいと言う。\n\nあなたは眉をひそめる。\n\nその自分は突然微笑んで振り返り、皆が苦しみを味わうより、命を自ら終わらせた方良いと言う。\n\nあなたはその声を振り払い、自らの信念を貫く。"
  },
  Event_59608_Name = {
    Text = "私の自問"
  },
  Event_59609_ChoiceDesc1 = {
    Text = "【問い詰める】カードを2枚削除する"
  },
  Event_59609_ChoiceDesc2 = {
    Text = "【突き破る】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59609_ChoiceDesc3 = {
    Text = "【離れる】Arg1黒章を獲得する"
  },
  Event_59609_Desc = {
    Text = "長い待ち時間の中、あなたは再び通信機を開いた。\nもしかするとあなたの思念と祈りが通じたのかもしれない。\n返信の紙に彼女の親しみある応答が次々と湧き出てくる。\n\n彼女は今とても安全で、師長たちはすでに手配済み、ミサゴの運営はすべて順調……\n雪のように舞い込む良い知らせを見て、心が動かずにはいられない。"
  },
  Event_59609_Name = {
    Text = "幻惑の共鳴"
  },
  Event_59610_ChoiceDesc1 = {
    Text = "【星を捕らえる】1つの低級遺物を高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_59610_ChoiceDesc2 = {
    Text = "【星を砕く】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」と「(Skill.Arg3)」に感染する"
  },
  Event_59610_ChoiceDesc3 = {
    Text = "【黙って見る】25黒章を獲得する"
  },
  Event_59610_Desc = {
    Text = "あなたの感情は記憶と共に剥がれ落ち、巨大な存在になりつつあるのを感じる。\nそれはまるで怪物が古代の暖かい巣に戻ったかのようだ。\n\n無数の喜怒哀楽が凝縮され、輝く星々となって精神の次元で光の雨を降らせる。\n\nあなたの生きた痕跡は流星となって消えていく。\n\n静かに見つめ、目の前の星を拾い上げると、そこからあなたの笑い声が聞こえてくる。\n\nそしてあなたも一緒に笑い、甘美に浸る。"
  },
  Event_59610_Name = {
    Text = "感情の結晶"
  },
  Event_59611_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59611_Desc = {
    Text = "これが過去の残影に過ぎないことを知っているあなたは、無表情でかつて語り合った人々を屠る。\n\n彼らの笑顔と涙はあなたの手で砕け、あなたは一瞬の躊躇も許されない。\n\nもしこれが必要な試練なら、あなたは最も無情な処刑人となるだろう。"
  },
  Event_59611_Name = {
    Text = "過去の影"
  },
  Event_59612_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59612_Desc = {
    Text = "その柔らかな毛皮と澄んだ瞳が自然と信頼を感じさせる。\n\n猫に近づくと、猫も尻尾は高くして近づいてくる。"
  },
  Event_59612_Name = {
    Text = "猫の誘惑"
  },
  Event_59613_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59613_Desc = {
    Text = "あなたは好奇心を抑え、この扉を開けるべきではないと知っている。\n\nあまりにも多くの真実は時に呪いとなる。\n\nあなたは胸のシルバーキーを握り、この扉を永遠に閉じる決意をした。"
  },
  Event_59613_Name = {
    Text = "扉の向こう"
  },
  Event_59614_ChoiceDesc1 = {
    Text = "【勇気】2枚のカードの刻印効果をランダムにアップグレードする"
  },
  Event_59614_ChoiceDesc2 = {
    Text = "【決意】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_59614_Desc = {
    Text = "タヴィの言葉があなたの頭に響く。\n\n無数の結末の中で、ただ一つが正しい道。\n\nぼんやりと、あなたの目の前に多くの世界の幻影がフィルムの断片のように過ぎ去り、ボタンを押して固定する瞬間を待っている。\n\nこの一秒が過ぎた後、世界はどんな結末を迎えるのか？"
  },
  Event_59614_Name = {
    Text = "未来の固定"
  },
  Event_59615_ChoiceDesc1 = {
    Text = "【疑念を無視する】50黒章を獲得する"
  },
  Event_59615_ChoiceDesc2 = {
    Text = "【独断専行する】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59615_Desc = {
    Text = "Nの嘲笑と共に、あなたは出会ったすべての人を疑い始める。\n\nどれが彼の化身で、どれが本当の師友なのか？\n彼の影は絶えず変化し、その中に無数の顔があり、あなたに向かって微笑んでいるようだ。"
  },
  Event_59615_Name = {
    Text = "影の百の顔"
  },
  Event_59616_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59616_Desc = {
    Text = "誰もが裏切る可能性があるなら、誰にも頼らない。\n\n暗闇の中で、唯一の真実を確認できる。\n\n少なくとも自分自身は信頼できる——最も忠実な自分を。"
  },
  Event_59616_Name = {
    Text = "影の百の顔"
  },
  Event_59617_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59617_Desc = {
    Text = "力を込めて握りしめると、輝く結晶が指先で粉々になる。\n\n過去からの感情を貪欲に吸い込む。\n\n瞬間的に濃厚な喜びが脳に押し寄せ、幻覚のようにゆっくりと消えていく。\n\n口角が高く上がり、そしてゆっくりと下がる。"
  },
  Event_59617_Name = {
    Text = "感情の結晶"
  },
  Event_59618_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59618_Desc = {
    Text = "すべてには代償があることを知っている。\nもし救うための代償が犠牲であるなら、その代償をすべて自分で支払う。\n\nあなたはいつでもすべてを捧げる準備ができている。"
  },
  Event_59618_Name = {
    Text = "私の答え"
  },
  Event_59619_ChoiceDesc1 = {
    Text = "【答えを探す】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_59619_ChoiceDesc2 = {
    Text = "【諦める】離れる"
  },
  Event_59619_Desc = {
    Text = "もう一人の自分が叫んでいる。\n\nその自分は、自身が逃げ出すことを熱望する。\n\n抗うことは必ず失敗に終わり、終わりなき逃亡だけが、最後の消滅を先延ばしにできると言う。\n\nあなたは半信半疑のまま立ち尽くす。"
  },
  Event_59619_Name = {
    Text = "私の自問"
  },
  Event_59620_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59620_Desc = {
    Text = "あなたは胚胎の増殖速度の恐ろしさを知っている。\n新生はここでは蝗害のような呪いだ。\n\n新生児が泣き出す前に、それらを踏み潰す。\n\n血肉でできた人々はあなたを怨み、神聖な命を冒涜する理由を問い詰める。\n\nあなたは無限の殺戮で応える。"
  },
  Event_59620_Name = {
    Text = "過去の影"
  },
  Event_59621_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59621_Desc = {
    Text = "今この瞬間、最も幸運な人になり、完璧な結末を迎えたいと願う。\n\nしかし幸運の代償は時に残酷で、幸運と不運はしばしば共に訪れる。\n得た瞬間に、失ったものを確認することを忘れないで。"
  },
  Event_59621_Name = {
    Text = "運命の選択"
  },
  Event_59622_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59622_Desc = {
    Text = "あなたは誰かと同じ車のハンドルを奪い合っているようだ。\n両手を全力で動かし、曲のリズムを掌握しようとする。\n\n激しい対抗の中で、あなたは突然一列の鍵盤を強く押し下げる。\n\n狂乱の演奏が乱れ、あなたは口元を緩め、狂気とさらなる狂気の対抗に陥る。"
  },
  Event_59622_Name = {
    Text = "終末の狂騒曲"
  },
  Event_59623_ChoiceDesc1 = {
    Text = "【親しむ】25黒章を獲得する"
  },
  Event_59623_ChoiceDesc2 = {
    Text = "【注視する】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_59623_Desc = {
    Text = "あなたのそばには猫が寄り添っている。\nその毛は滑らかで清潔、前足は雪のように白い。\n\n猫は常にあなたのそばに寄り添い、まるで忠実な下僕のように従っている。\n\nあなたの心の中の迷いや無力感、痛みや不安はすべて和らげられた。"
  },
  Event_59623_Name = {
    Text = "猫の誘惑"
  },
  Event_59624_ChoiceDesc1 = {
    Text = "【否定する】「(Skill.Arg1)」に感染し、呪われた遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_59624_ChoiceDesc2 = {
    Text = "【反論する】2枚の「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」「(RelicConfig.Arg3)」を獲得する"
  },
  Event_59624_ChoiceDesc3 = {
    Text = "【沈黙する】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_59624_Desc = {
    Text = "虚無の幻影に陥る。\n\n終末の影の下で沈黙する無数の人々が見える。\n\n彼らはぼんやりと、灰色で、希望を失っている。\n\n誰かの鋭い笑い声が聞こえる。\n\n「見ろ、これが君たちの結果だ」\n「世界に終わりはなく、すべてが無意味だ」"
  },
  Event_59624_Name = {
    Text = "死を待つ子羊"
  },
  Event_59625_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59625_Desc = {
    Text = "いや、違う、これは現実じゃない。\n\n君はその狂気の声を否定し続けるが、灰色の人影は無反応で、虚無の結末を証明するかのようだ。\n\nその笑い声はますます大きくなり、君の無力さを嘲笑している。"
  },
  Event_59625_Name = {
    Text = "死を待つ子羊"
  },
  Event_59626_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59626_Desc = {
    Text = "大きな後悔と未練を感じ、無意識に必死で過去の影を記憶の断片から探そうとする。\n\nぼんやりとした映像が急速に遠ざかり、手を伸ばしても指の間から消えていく。\n\n何もかも失うことに気づく。"
  },
  Event_59626_Name = {
    Text = "記憶解離"
  },
  Event_59627_ChoiceDesc1 = {
    Text = "【親しむ】25黒章を獲得する"
  },
  Event_59627_ChoiceDesc2 = {
    Text = "【注視する】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_59627_Desc = {
    Text = "あなたのそばには猫が寄り添っている。\nその毛は滑らかで清潔、前足は雪のように白い。\n\n猫は常にあなたのそばに寄り添い、まるで忠実な下僕のように従っている。\n\nあなたの心の中の迷いや無力感、痛みや不安はすべて和らげられた。"
  },
  Event_59627_Name = {
    Text = "猫の誘惑"
  },
  Event_59628_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59628_Desc = {
    Text = "あなたは最終的な自分とここで出会う。\n世界を滅ぼす戦いは、実は目と目の対決に過ぎない。\n\n彼があなたを見るとき、その視線が消えるまで、あなたはしっかりと見返さなければならない。"
  },
  Event_59628_Name = {
    Text = "私の答え"
  },
  Event_59629_ChoiceDesc1 = {
    Text = "【呼吸する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59629_ChoiceDesc2 = {
    Text = "【反撃する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」「(Skill.Arg3)」に感染する"
  },
  Event_59629_ChoiceDesc3 = {
    Text = "【足掻く】25黒章を獲得する"
  },
  Event_59629_Desc = {
    Text = "密集した足音が響き、監視員たちがあなたの行く手を阻む。\n\n「調査に協力してください」\n冷たい声に悪意が含まれている。\n\nドボンと音を立てて静かな水面が破られ、彼らはあなたを深い淵に投げ込む。"
  },
  Event_59629_Name = {
    Text = "深淵に沈む"
  },
  Event_59630_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59630_Desc = {
    Text = "必死にもがく。\n\n前へ、さらに前へ。\n\nどんな代償を払っても、必ず守り抜く。\n\n手を伸ばすと、糸が肉に食い込むが、気にしない。"
  },
  Event_59630_Name = {
    Text = "操られた手"
  },
  Event_59631_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59631_Desc = {
    Text = "あなたは頭を強く振り混乱した記憶を振り払う。\n\nやがて騒がしい音が徐々に消え、意識がようやく独立を取り戻す。\n\n失敗した過去からは助けを得られない、今に集中することで希望を見つけるしかない。"
  },
  Event_59631_Name = {
    Text = "私の自問"
  },
  Event_59632_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_59632_Desc = {
    Text = "手を差し伸べる前に、こんな猫を育てたことがないことを思い出した。\n\n見つめると、猫はあなたにウインクする。\n\n戸惑うあなたを気にせず、猫は親愛の情を向けてくる。"
  },
  Event_59632_Name = {
    Text = "猫の誘惑"
  },
  Event_59633_ChoiceDesc1 = {
    Text = "【答えを探す】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59633_ChoiceDesc2 = {
    Text = "【諦める】離れる"
  },
  Event_59633_Desc = {
    Text = "もう一人の自分が悲しみの涙を流している。\n\nその自分は悲しみに満ち、最愛の人を抱きしめたいと思っている。\n\n破滅の時に大切な人と一緒にいられなかったことが、ソレにとっての最大の後悔だった。\n\nあなたは胸が締め付けられ、共に悲しまずにはいられない。"
  },
  Event_59633_Name = {
    Text = "私の自問"
  },
  Event_59634_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59634_Desc = {
    Text = "君は無数の灰色の人影を見つめ、その嘲笑の笑い声を無視する。\n\n崩壊する世界をどう救う？\n君は沈黙の滅亡の中で考え続ける。"
  },
  Event_59634_Name = {
    Text = "死を待つ子羊"
  },
  Event_59635_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59635_Desc = {
    Text = "肺の中の空気が徐々に消え、水中で呼吸しようとする。\n\nなんて愚かな行為だが、成功した。\n\n肺が再び満たされ、自由に息を吐ける。\n\nだが、吸い込んでいるのは一体何なのか？"
  },
  Event_59635_Name = {
    Text = "深淵に沈む"
  },
  Event_59636_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59636_Desc = {
    Text = "あなたは粘つく液体に沈んだ。\n\n必死にもがくが、どんどん深みにハマるだけ。\n\nこの泥沼から一人では逃れられない。"
  },
  Event_59636_Name = {
    Text = "深淵に沈む"
  },
  Event_59637_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59637_Desc = {
    Text = "あなたは疑念を忘れようと努める。\n\n今、疑うことは無意味だと知っているから、信じるしかない。\n\n箱が開かれるまで、中の真実はわからない。\n\n時には、愚か者でいる方が安らぎを得やすい。"
  },
  Event_59637_Name = {
    Text = "影の百の顔"
  },
  Event_59638_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59638_Desc = {
    Text = "皆の視線があなたに集まり、リーダーとしての強さを見せなければならない。\n\n「昏き海へ行けば、すべてが良くなる」\n\nあなたは冷静に指示を出し、自分でも信じられない約束をする。"
  },
  Event_59638_Name = {
    Text = "無知の目"
  },
  Event_59639_ChoiceDesc1 = {
    Text = "【疑う】「(Skill.Arg1)」に感染し、呪われた遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_59639_ChoiceDesc2 = {
    Text = "【軽蔑する】2枚の「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」「(RelicConfig.Arg3)」を獲得する"
  },
  Event_59639_ChoiceDesc3 = {
    Text = "【無視する】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_59639_Desc = {
    Text = "目の前に三人の彷徨う人影があり、何かをぶつぶつと囁いている。\n\n耳を近づけて聞くと、言葉と息遣いがはっきりと聞こえてくる。\n\n「その猫を信じるな、あいつは詐欺師だ」\n急いで振り返ると、誰もいないことに気づく。"
  },
  Event_59639_Name = {
    Text = "秘密の囁き"
  },
  Event_59640_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59640_Desc = {
    Text = "星はとても美味しそうに見え、その力を欲しがり、一口で飲み込みました。\n\nごくん。\n\n精神がかつてないほど満たされ、視界の端で光が輝いています。\n\n下を向くと、星はまだ胃の中で光っている。"
  },
  Event_59640_Name = {Text = "願い星"},
  Event_59641_ChoiceDesc1 = {
    Text = "【前に進む】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_59641_ChoiceDesc2 = {
    Text = "【糸を断ち切る】指令カードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_59641_ChoiceDesc3 = {
    Text = "【耐え忍ぶ】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_59641_Desc = {
    Text = "道中、あなたは進むように押され、すべての選択が見えない糸で操られている。\n\n必死に両手を動かし、大切なものを掴もうとする。\n\n世界の運命はあなたの指先にかかっている。\n\n無数の糸が絡みつき、全身を縛りつける。"
  },
  Event_59641_Name = {
    Text = "操られた手"
  },
  Event_59642_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59642_Desc = {
    Text = "あなたは目尻の血の涙を拭うが、無数の血の涙がまた流れ続ける。\n\n赤が視界を覆い、血なまぐさい犠牲を予感させる。\n\n拭き続けるが、痛みで震えることはあっても、恐れは微塵もない。"
  },
  Event_59642_Name = {
    Text = "私の融合"
  },
  Event_59643_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59643_Desc = {
    Text = "あなたはこの不思議な宝石を撫で、シルバーキーにはめ込みました。\n\n目がくらむような星の光があなたを照らす。"
  },
  Event_59643_Name = {Text = "願い星"},
  Event_59644_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59644_Desc = {
    Text = "あなたは構わず、目を開け続け、心の中の信念が頑固な怒号に変わる。\n\nたとえ砕け散っても、一歩も退かない。"
  },
  Event_59644_Name = {
    Text = "私の融合"
  },
  Event_59645_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59645_Desc = {
    Text = "もう一人の自分が沈黙している。\n\nその自分の絶望と沈黙の表情を見れば、ソレが最後までやり遂げていないことがわかる。\n\nあなたは自分たちの中で最も遠くまで進んできた者であり、あなたの答えだけが最後の希望だ。"
  },
  Event_59645_Name = {
    Text = "私の自問"
  },
  Event_59646_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59646_Desc = {
    Text = "手を伸ばし、無数の流星を次々と掴み取る。\n輝く結晶が指先をかすめる。\n\n喜び、悲しみ、怒り、恐怖……\n貪欲にすべての感情を掴み取るが、それらが手から消えていくのを見つめる。\n\n華やかな光が顔を照らし、瞳は次第に漆黒で深淵になる。"
  },
  Event_59646_Name = {
    Text = "感情の結晶"
  },
  Event_59657_ChoiceDesc1 = {
    Text = "【呼ぶ】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_59657_ChoiceDesc2 = {
    Text = "【触れる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_59657_Desc = {
    Text = "あなたは人形が崩壊するのを目撃する。\n\n彼女はかつて最も理性的で、最も忠実な助手だった。\nあなたたちが得たすべての情報を大切に保管していた。\n\nしかし今、彼女はあなたたちのすべての時間を忘れてしまったようだ。\n\n人形の目尻から透明な液体が滴るのを見た。"
  },
  Event_59657_Name = {
    Text = "人形の涙"
  },
  Event_59658_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59658_Desc = {
    Text = "あなたは諦めず、彼女のエネルギーコアに触れようとする。\n\n機械なら、再起動すれば修理できるはずだ。\n\nだが、無情な人形はあなたにそんな甘い機会を与えなかった。\n\nあなたの手加減は人形の情けを引き出せず、全力で戦うしかない。"
  },
  Event_59658_Name = {
    Text = "人形の涙"
  },
  Event_59659_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_59659_Desc = {
    Text = "あなたはかつての仲間を壊したくない。\n\n彼女の名前を必死に呼び、すべての指令を出すが、何の効果もない。\n\n人形はあなたたちを裏切り、無機物の冷たさに戻った。"
  },
  Event_59659_Name = {
    Text = "人形の涙"
  },
  Event_60944_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_60944_Desc = {
    Text = "時間がない。\n最も直接的な方法で封鎖を突破した。\n\n覚醒体たちは奮起している。\n\n警戒を強めた敵とはいえ問題ではない。"
  },
  Event_60944_Name = {Text = "監視員"},
  Event_60945_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_60945_Desc = {
    Text = "監視員が気づく前に、背後へ回り武器を奪った。\n\n増援が来る前に離れたが、情報は広まり後続の敵は準備を整えているかもしれない。"
  },
  Event_60945_Name = {Text = "監視員"},
  Event_60946_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_60946_Desc = {
    Text = "監視員は口笛に引き寄せられ、隠れた場所に近づいてくる。\n\n彼が近づいた瞬間、待ち構えていた覚醒体たちが一斉に攻撃を仕掛けた。\n\n完璧な待ち伏せで、危機は去った。"
  },
  Event_60946_Name = {Text = "監視員"},
  Event_60947_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_60947_Desc = {
    Text = "大勢の敵に直面し、対抗することができない。\nあなたは自ら捕まった。\n\n搬送される拘留所から逃げ出し、新しい道を探すつもりだ。"
  },
  Event_60947_Name = {Text = "検査所"},
  Event_60948_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_60948_Desc = {
    Text = "大勢の敵に直面し、対抗することができない。\n短い戦闘の後、抵抗を諦めた。\n\n搬送される拘留所から逃げ出し、新しい道を探すつもりだ。"
  },
  Event_60948_Name = {Text = "検査所"},
  Event_60949_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_60949_Desc = {
    Text = "大勢の敵に直面し、対抗することができない。\n\n一時的にここを離れ、新しい道を探すことにした。"
  },
  Event_60949_Name = {Text = "検査所"},
  Event_61058_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61058_Desc = {
    Text = "あなたは自分の両手と、全身をじっと見つめる。\n心は希望と決意に満ちていた。\n\nもし、このすべてが運命の定めだというのなら、すべてに立ち向かう準備はもうできている。\n\nもし最後の瞬間に、天国か地獄へと続く扉があるのなら、この世界のために、あなた自身の手でその扉を開いてみせる。"
  },
  Event_61058_Name = {Text = "覗き見"},
  Event_61059_ChoiceDesc1 = {
    Text = "【戦闘準備】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_61059_ChoiceDesc2 = {
    Text = "【観察を続ける】「(Skill.Arg1)」に感染し、再刻印を最大1回まで行う"
  },
  Event_61059_Desc = {
    Text = "あなたは急いで迎撃せず、冷静に状況を整理しようとする。\n\nこの突然現れた指揮者は敵か味方か分からず、彼が何をしようとしているのか不明だ。\n\nいずれにせよ、あなたは十分な準備を整え、まず彼の挑戦を受け、その後ゆっくりと彼の意図を探ることに決めた。"
  },
  Event_61059_Name = {
    Text = "悪魔の指揮者"
  },
  Event_61060_ChoiceDesc1 = {
    Text = "【聴く】3つの中から1つ上位刻印を獲得する"
  },
  Event_61060_ChoiceDesc2 = {
    Text = "【叫ぶ】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_61060_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_61060_Desc = {
    Text = "事故以来、パートナーからの連絡は途絶えた。\n\n無数の連絡を試みたが、まるで石を投げたように何の反応もない。\n\n希望失いかけた時、通信機が突然音を立てた。\n\n手提げ箱を開け、受話器を耳に近づける。\n\n「守秘者……」\nぼんやりと、ずっと思い続けていた声が、遠く虚空を隔てて響いてくる。"
  },
  Event_61060_Name = {
    Text = "思い出のこだま"
  },
  Event_61061_ChoiceDesc1 = {
    Text = "【闇を受け入れる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_61061_ChoiceDesc2 = {
    Text = "【泳いでみる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_61061_ChoiceDesc3 = {
    Text = "【幽霊を呼ぶ】25黒章を獲得する"
  },
  Event_61061_Desc = {
    Text = "前方へ走り出すと、足元の土地が突然歩けない海原に変わり土壌に落ちる。\n\n無数に粘つく幽霊のような闇が現れ、容赦なく口と鼻に侵入する。"
  },
  Event_61061_Name = {
    Text = "地底に落ちる"
  },
  Event_61062_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61062_Desc = {
    Text = "あなたは目を見開き、すべての手がかりを探そうと必死になる。\n\n百の目が同時に動き、あなたは目の前の人面犬の足跡を見て、背後のハムリンの指揮棒の軌跡を見た。\n\nあなたは貪欲にすべてを観察する。\n\n突然、地面に見覚えのある眼球が転がっているのを見た。\n\nそれはまるで自分の目のようだった。"
  },
  Event_61062_Name = {
    Text = "知識を求める貪欲"
  },
  Event_61063_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61063_Desc = {
    Text = "違う、こんなに多くのものを見ることはできない。\n\nあなたには……ほんの数個の目しかないはずだ。\n\n急いで目を閉じ、顔に手を伸ばして探る。\n\n一つ、二つ……\n再び目を開けると視界は狭く無知になった。\n\nやはりあなたには二つの目しかないのか、残念だ。"
  },
  Event_61063_Name = {
    Text = "知識を求める貪欲"
  },
  Event_61064_ChoiceDesc1 = {
    Text = "【捜索する】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_61064_ChoiceDesc2 = {
    Text = "【目を閉じる】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_61064_Desc = {
    Text = "ますます多くの手がかりが糸のように絡まり、あなたは焦り、迷い、憤りを感じる。\nなぜ何も知らないのかと自分を責める。\n\n巨大なプレッシャーで精神が一本の細い糸のように張り詰める。\n\nプツンと音がして、突然頭皮が緩み、周囲のすべての景色が見えるようになる。\n虚空に揺れる影が見える。\n\nもっと、もっと見たい……"
  },
  Event_61064_Name = {
    Text = "知識を求める貪欲"
  },
  Event_61065_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61065_Desc = {
    Text = "あなたは土の中を泳ぎ、最も俊敏な魚を想像する。\n\n魚になるには、人間の足を捨てなければならない。\n\nそれが取引の代償だ。\n\nすぐに、かつてないほどの軽さを感じ、地底で最も自由な存在となる。\n\n地上に戻るが、歩き方を忘れてしまった。"
  },
  Event_61065_Name = {
    Text = "地底に落ちる"
  },
  Event_61066_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61066_Desc = {
    Text = "あなたの指先が銀の鍵の馴染んだ感触に触れる。\nそれは、すべての光の核心だ。\n\nこれこそは、自身の命の凝縮であり、自身の運命の化身である。\n\nこれまでの経験が次々と目の前を駆け巡る。\n\nあなたの選択は、この世界の選択と固く結ばれている。\n\nあなたの運命は、すでに多くの人々と深く繋がっている。"
  },
  Event_61066_Name = {Text = "覗き見"},
  Event_61067_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61067_Desc = {
    Text = "多くの親しい存在に囲まれていると感じる。\n\n存在しないかもしれない幽霊に呼びかける。\n\n奇跡が起こり、再び地上に戻る。\n\n無数の墓石は依然として沈黙している。"
  },
  Event_61067_Name = {
    Text = "地底に落ちる"
  },
  Event_61068_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61068_Desc = {
    Text = "感傷に浸っている暇はない。\nあなたは、この崩壊しつつあるすべてを、一刻も早く救いたいと願っている。\n\nもし星になるのなら、流れ星になればいい。\n\n夜空を照らすことができれば良い——たとえ、いつか墜ちる運命でも。"
  },
  Event_61068_Name = {Text = "覗き見"},
  Event_61069_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61069_Desc = {
    Text = "耳をぴったりと当て、すべての微かな音を頭に入れる。\n\n「私……」\n「あなたはきっと……」\n途切れた言葉しか聞こえず、意味はわからない。\n\nしかし声を出す勇気はなく一言も逃したくない。\n\nだが運命はそれ以上の慈悲を与えない。\n\n残された音も消え、再び静寂が戻る。"
  },
  Event_61069_Name = {
    Text = "思い出のこだま"
  },
  Event_61070_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61070_Desc = {
    Text = "あなたは考え続けることをやめ、覚醒体たちを指揮して列を整え、彼の挑戦を迎えた。"
  },
  Event_61070_Name = {
    Text = "悪魔の指揮者"
  },
  Event_61071_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61071_Desc = {
    Text = "彼女の名前を呼び続け、少しでも気持ちを伝えようとする。\n\n彼女が聞こえたかはわからないが、マイクの曖昧な音を必死に聞き取る。\n\nそれは彼女の返事のようで、過去の断片が繰り返し流れているようでもある。\n\n共に経験し、分かち合ってきた喜びと悲しみ、出会いが再生される。"
  },
  Event_61071_Name = {
    Text = "思い出のこだま"
  },
  Event_61072_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_61072_Desc = {
    Text = "この闇こそが本当の世界かもしれない、加わるのも悪くない？\n\n闇を完全に受け入れ、闇もまたあなたを拒まなくなる。\n自由に呼吸できる。\n\n次の瞬間、地上に戻る。\n何かが永遠に地下に残ったかもしれないが、それはもう重要ではない。"
  },
  Event_61072_Name = {
    Text = "地底に落ちる"
  },
  Event_61073_ChoiceDesc1 = {
    Text = "【光を見つめる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_61073_ChoiceDesc2 = {
    Text = "【胸に触れる】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染する"
  },
  Event_61073_ChoiceDesc3 = {
    Text = "【走り続ける】25黒章を獲得する"
  },
  Event_61073_Desc = {
    Text = "あなたは心の中は混乱しすぎて、色々考える暇もなかった。\n\n突然、胸のあたりが虚ろになったように感じた。\n下を見ると、心臓があった場所に鍵の形をした光が現れていた。\n\nその光はどんどん明るくなり、次第に全身に広がっていき、あなたは自分が一つの星に変わっていくのを見た。\n\nあなたは、ふと、これがずっと自分の使命だったのかもしれないと悟った。"
  },
  Event_61073_Name = {Text = "覗き見"},
  Event_61074_ChoiceDesc1 = {
    Text = "【戦闘準備】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_61074_ChoiceDesc2 = {
    Text = "【注意深く観察する】「(Skill.Arg1)」に感染し、再刻印を最大2回まで行う"
  },
  Event_61074_Desc = {
    Text = "「ちょっと……待って！どういう状況！？」\n「リハーサルです」\n男は無表情であなたを見つめる。\n\n「音楽で覚醒体のリンクを維持するのは新しい試みです。楽団の水準を確かめることで、演奏の完璧さを保証できます」\n\n彼は指揮棒を上げ、空中に優雅な始まりの音符を描く。\n\n「さあ演奏を、守秘者。\nあなたが何を成し遂げられるか、拝見します」"
  },
  Event_61074_Name = {
    Text = "悪魔の指揮者"
  },
  Event_61075_ChoiceDesc1 = {
    Text = "【戦闘準備】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_61075_Desc = {
    Text = "彼が何を目的としているにせよ、少なくとも彼はあなたを審査会の包囲から救い出した。\n\nもし彼があなたに害を及ぼすつもりなら、助ける必要はなかった。\n\nあなたは冷静になり、最後の準備を整えた。"
  },
  Event_61075_Name = {
    Text = "悪魔の指揮者"
  },
  Event_65400_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65400_Desc = {
    Text = "連絡員が外界からの救助の確約を伝えてくれた。\n\n救援隊がすでに入山の手立てを方法を模索していると聞き、皆の胸に希望の灯が再び灯った。"
  },
  Event_65400_Name = {Text = "休憩所"},
  Event_65401_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65401_Desc = {
    Text = "調査隊のメンバーは誰一人として雪山から戻れなかった。\n災厄を前に、あなたはいつも自分を優先し、他人の命など眼中になかった。人間性を捨て去って最後まで辿り着いたのだ。\n\n救援隊は複雑な表情であなたを見つめたが、あなたは意に介さず、振り返って風雪の中へと歩き出した。\n\nいつか真夜中に夢から醒めたとき、あなたの冷淡さゆえに命を落とした魂たちが枕元に集い、無言であなたを見つめているかもしれない。"
  },
  Event_65401_Name = {
    Text = "安全な退避所"
  },
  Event_65402_ChoiceDesc1 = {
    Text = "【隊員避難】遺物「調査隊」を除去する。調査隊員の人数に応じて、異なる等級の「救難勲章」を獲得する。"
  },
  Event_65402_Desc = {
    Text = "あなたは調査隊を無事に避難所へ送り届け、救援隊がすべてを引き継いだ。\n救出された人々は地面に崩れ落ち、まるで別世界から戻ったかのようだ。\n\nしかし、本当の危機はまだ解決されていない。\nあの巨大な獣は今もなお山の中に潜み、腹を空かせてあなたたちを待ち構えている。"
  },
  Event_65402_Name = {
    Text = "安全な退避所"
  },
  Event_65403_ChoiceDesc1 = {
    Text = "【補給品を交換する】25黒章を獲得する。調査隊員1名につき、追加で1黒章(Arg1)を獲得する。"
  },
  Event_65403_ChoiceDesc2 = {
    Text = "【救援の約束】刻印を1つ獲得する。調査隊員を2名補充する。"
  },
  Event_65403_ChoiceDesc3 = {
    Text = "【効率優先】調査隊員を10名失い、高級遺物+を1つ獲得する。"
  },
  Event_65403_Desc = {
    Text = "あなたたちは風雪の中を懸命に進み、遠くの緊急休憩所で揺らぐ灯りを追い続ける。\n\n数え切れぬほどの祈りの末、ついに、希望を秘めた小屋を見つけた。"
  },
  Event_65403_Name = {Text = "休憩所"},
  Event_65403_Tips3 = {
    Text = "調査隊の人数が不足しています。"
  },
  Event_65404_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65404_Desc = {
    Text = "連絡員から休憩所の倉庫の暗証番号を教わり、全員の2日分の物資を手に入れた。\n\nこれで少なくとも、飢えや寒さで死ぬことはないだろう。"
  },
  Event_65404_Name = {Text = "休憩所"},
  Event_65415_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_65415_Desc = {
    Text = "雪山は瞬く間に「食事」を終え、2名の調査隊員が底知れぬ氷の割れ目に消え去った。しかし、あなたたちはそのことにまったく気づいていなかった。"
  },
  Event_65415_Name = {Text = "幻影"},
  Event_65416_ChoiceDesc1 = {
    Text = "【離れる】サーチライトを探す"
  },
  Event_65416_ChoiceDesc2 = {
    Text = "【吹雪へ踏み込む】調査隊員を2名失う"
  },
  Event_65416_Desc = {
    Text = "雪山に突如、激しい風が吹き荒れる。\n耳元で唸りを上げる風は、まるで巨獣の咆哮のようだ。\n一瞬にして真っ白な吹雪が視界を遮り、果てしない真っ白な霧の中を何かが駆け抜けていくようだった。\n\nあなたたちは歩みを止めざるを得ず、斜面を滑り落ちまいと、両足を深く雪に突き立てた。"
  },
  Event_65417_ChoiceDesc1 = {
    Text = "【音もなく消える】調査隊員を2名失う"
  },
  Event_65417_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_65417_Desc = {
    Text = "雪山の中腹から轟音が響いた。\n飢えた獣が不満の咆哮を上げるかのようだ。大地が震え、積雪の下の氷がひそやかに裂けていく。まるで雪山が大口を開けたかのように。\n\nやがて大地の震えが止むと、人々は茫然と辺りを見渡し、あなたは振り返って隊を確認した。"
  },
  Event_65417_Name = {Text = "幻影"},
  Event_65468_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65468_Desc = {
    Text = "隊の機動力を確保するため、あなたは行動が困難な人々を孤立した小屋に置き去りにした。\n\n残された者たちの生存率は上がるかもしれない。だが、口惜しさと恨みに満ちた彼らの眼差しを間にして、あなたの心は本当に揺らがないのか？"
  },
  Event_65468_Name = {Text = "休憩所"},
  Event_65483_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65483_Desc = {
    Text = "あなたは何人かを救ったものの、多くの人が帰らぬ人となった。\nそれでも、最善は尽くしたのだ。\n\n救助隊はのちにこの貢献は称えられると告げたが、あなたは手を振り、風雪の中へと歩き去った。"
  },
  Event_65483_Name = {
    Text = "安全な退避所"
  },
  Event_65484_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65484_Desc = {
    Text = "あなたは他を顧みる余裕もなく、雪山を脱するために最も効率のよい方法を選んだ。\n最後まで生き残った者の目には、あなたは悪魔のように映ったかもしれない。\n\n救援隊はのちにこの貢献は称えられると告げたが、あなたは手を振って、風雪の中へと歩き去った。"
  },
  Event_65484_Name = {
    Text = "安全な退避所"
  },
  Event_65485_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65485_Desc = {
    Text = "あなたの惜しみない献身のおかげで、調査隊は一人の犠牲も出さずに済んだ。あなたに出会えたことは、彼らの不幸中における最大の幸運であり、紛れもない救世主だったのだ。\n\nあなたは災厄の中で奇跡を起こし、雪山の英雄としてその名を馳せることになるだろう。\n\n救助隊はこの偉大な貢献はのちに称えられると厳かに告げ、あなたは笑顔で手を振り、風雪の中に歩み去った。"
  },
  Event_65485_Name = {
    Text = "安全な退避所"
  },
  Event_65486_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65486_Desc = {
    Text = "あなたは人々の命を心から大切にし、その多くを救った。\n人々は涙を流し、あなたの保護に感謝を繰り返した。\n\n救助隊はあなたの傑出した貢献はのちに称えられると厳かに告げ、あなたは微笑んで手を振り、風雪の中へと歩み去った。"
  },
  Event_65486_Name = {
    Text = "安全な退避所"
  },
  Event_65487_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_65487_Desc = {
    Text = "あなたは未曾有の災厄に立ち向かい、人々を死神の手から奪い返した。\nその奮闘の末、悲劇の結末はわずかに逸れたのだ。\n\n救助隊はあなたの貴重な貢献は、後に称えられると厳かに告げ、あなたは笑顔で手を振り、風雪の中に歩み去った。"
  },
  Event_65487_Name = {
    Text = "安全な退避所"
  },
  Event_6817_ChoiceDesc1 = {
    Text = "【ほどほどにする】3つの中から1つ刻印を獲得する"
  },
  Event_6817_ChoiceDesc2 = {
    Text = "【読み続ける】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6817_Desc = {
    Text = "木製の本棚の一番上に、金色の表紙の本が置かれている。本の名前は見えない。\n\nなぜか読むことへの欲望が湧き上がる……\nその欲望は抑えきれないほど膨れ上がり、梯子に登って、急いで読み始める……\n\nぼんやりとした印象があなたの思考の海に浮かび、幻影の海に沈んでいく……"
  },
  Event_6817_Name = {
    Text = "大人の本"
  },
  Event_6818_ChoiceDesc1 = {
    Text = "【耳を傾ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6818_ChoiceDesc2 = {
    Text = "【合奏する】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_6818_ChoiceDesc3 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_6818_Desc = {
    Text = "ピアノの音が突然耳に届く。\n透ける緑の指が鍵盤を跳ね、優雅な音色が小川のように流れる。\n\nその手は言葉を持たないが、ピアノの音で問いかけてくる。\n\n「やぁ友よ、一緒に演奏しないかい？」"
  },
  Event_6818_Name = {
    Text = "ピアノの幽霊"
  },
  Event_6819_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6819_Desc = {
    Text = "ラモンナは音の発生源を見たが、壁に溶け込んだ蓄音機のような、消えゆく幻影が見えただけだった。"
  },
  Event_6819_Name = {Text = "噂話"},
  Event_6820_ChoiceDesc1 = {
    Text = "【タイプライターを掃除する】指令カードを1枚削除し、25黒章を獲得する"
  },
  Event_6820_ChoiceDesc2 = {
    Text = "【文字を判別してみる】山札にあるカードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_6820_Desc = {
    Text = "手提げ箱の中のタイプライターが突然濃いインクを噴き出し、列車の揺れに合わせて線状に飛び散る。"
  },
  Event_6820_Name = {
    Text = "タイプライターの囁き"
  },
  Event_6821_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6821_Desc = {
    Text = "拳で幻影を打ち消す瞬間、記憶が脳に突入し、魂を打ちつけ、鈍い痛みを感じる。"
  },
  Event_6821_Name = {Text = "蜃気楼"},
  Event_6822_ChoiceDesc1 = {
    Text = "【手紙を捨てる】カードを1枚削除する"
  },
  Event_6822_ChoiceDesc2 = {
    Text = "【身につけておく】「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6822_Desc = {
    Text = "タイプライターに巻き込まれた数枚の手紙を引き抜くと、にじんだ文字が濃いインクの香りを放つ。\n手紙の内容をざっと見て、思わず眉をひそめる。\n\n内容のほとんどが消され、残ったものも文になっておらず、読むべきものはほとんどない。"
  },
  Event_6822_Name = {
    Text = "塗りつぶされた手紙"
  },
  Event_6823_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6823_Desc = {
    Text = "紙の上のぼんやりとした文字を必死に読み取る。\nそれらは絶えず歪み、全く異なる内容が現れる。\n\n「@2あなたは、あの報道を新聞で見たはず。\n\nそう、あなたの父親はあなたを相続人から外しました……私たちも@2するつもりはありません。\n\n悪魔、悪魔……\n\n直ちにあのハーバート氏との交際をやめなさい。さもなければ、経済的支援は打ち切ります……」"
  },
  Event_6823_Name = {
    Text = "お手紙拝見"
  },
  Event_6824_ChoiceDesc1 = {
    Text = "【シルバーキーを握る】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_6824_ChoiceDesc2 = {
    Text = "【目を閉じる】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染する"
  },
  Event_6824_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6824_Desc = {
    Text = "あなたは巨大な不条理に引き裂かれ、四肢がねじ曲がり、地面を這いずり回った。\nまるで次元外の@2に操られているかのようだ。\n\n「いや……いやだ……」\n\n正気が少しずつ崩壊していく——狂気の笑いと叫びが交錯し、巨大な網のように意識を絡め取る。\n\n口から漏れるのは支離滅裂な悲鳴だけ。"
  },
  Event_6824_Name = {
    Text = "凝視の眼"
  },
  Event_6825_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6825_Desc = {
    Text = "守秘者に渡して処理してもらおう。\nどんな個体が召喚されるかはわからない。"
  },
  Event_6825_Name = {
    Text = "孤独なシルバーコア"
  },
  Event_6826_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6826_Desc = {
    Text = "悲しげなメロディーが耳元を流れ、苦悩と痛みが脳と魂を満たす。\n気づいたときには、誰かの目尻がすでに湿っていた。"
  },
  Event_6826_Name = {
    Text = "無体の音"
  },
  Event_6827_ChoiceDesc1 = {
    Text = "【左側の扉を押して開ける】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6827_ChoiceDesc2 = {
    Text = "【右側の扉を押して開ける】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6827_Desc = {
    Text = "扉。扉。無数の扉。\n\n扉の数は、あなたとラモンナが巡回した時よりも多いようだ。\n\n廊下で立ち止まり、次の扉を開ける準備をする。\n\n左側の扉の向こうは静寂に包まれている。\n\n右側の扉の向こうからは不明瞭な会話が聞こえてくる。"
  },
  Event_6827_Name = {
    Text = "無限の扉"
  },
  Event_6828_ChoiceDesc1 = {
    Text = "【耳を澄ます】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6828_ChoiceDesc2 = {
    Text = "【耳を塞ぐ】3つの中から1つ刻印を獲得する"
  },
  Event_6828_Desc = {
    Text = "狂乱の鍵盤の音だけが聞こえる。\n嵐のように襲いかかり、隕石が地面に落ちるような震えがピアノ全体を揺るがす。\n\nハンマーが軋み、跳ねるペダルが悲痛な叫びを漏らす。\n\n不気味な音楽の中で、馴染みのある旋律が耳膜をかすめる。"
  },
  Event_6828_Name = {
    Text = "禁忌の音色"
  },
  Event_6829_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6829_Desc = {
    Text = "「ウィリアム調査員が緊急物資を輸送しました。\n受け取り後、胸章を3回叩いて確認してください」"
  },
  Event_6829_Name = {
    Text = "支援通信"
  },
  Event_6830_ChoiceDesc1 = {
    Text = "【左側の扉を押して開ける】3つの中から1つ刻印を獲得する"
  },
  Event_6830_ChoiceDesc2 = {
    Text = "【右側の扉を押して開ける】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_6830_Desc = {
    Text = "扉。扉。無数の扉。\n\n扉の数は、あなたとラモンナが巡回した時よりも多いようだ。\n\n廊下で立ち止まり、次の扉を開ける準備をする。\n\n左側の扉の向こうは静寂に包まれている。\n\n右側の扉の向こうからは不明瞭な会話が聞こえてくる。"
  },
  Event_6830_Name = {
    Text = "無限の扉"
  },
  Event_6831_ChoiceDesc1 = {
    Text = "【書簡を読む】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_6831_ChoiceDesc2 = {
    Text = "【鞄をしっかり閉める】"
  },
  Event_6831_Desc = {
    Text = "手提げ鞄が震え続けている。\nまるで何かが卵の殻を噛み破り、今にも羽化しようとしているかのようだ。\n\nあなたは自分の意思に反して鞄を開ける。\n手紙が放たれた蝶のように四方に飛び散った。"
  },
  Event_6831_Name = {
    Text = "予期せぬ手紙"
  },
  Event_6832_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6832_Desc = {
    Text = "急なベルの音が心をざわつかせる。\n受話器を取り、机に置く。\nベルは突然止まり、頭の中に残響だけが残る。"
  },
  Event_6832_Name = {
    Text = "列車からの電話"
  },
  Event_6833_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6833_ChoiceDesc2 = {
    Text = "【フィルムを検査する】「(Skill.Arg1)」に感染する。選択肢1で獲得した刻印を変更。2回使用できる"
  },
  Event_6833_Desc = {
    Text = "アトリエの隅には古いカメラ、数巻のフィルム、散らばった写真が置かれている。\nそれらは蝋人形師の仕事と美学を忠実に記録している。"
  },
  Event_6833_Name = {
    Text = "正確な記録"
  },
  Event_6834_ChoiceDesc1 = {
    Text = "【質問をする】最大ライフをArg1増加させる"
  },
  Event_6834_ChoiceDesc2 = {
    Text = "【影を掴む】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6834_Desc = {
    Text = "黄金の塵の中で、影が唱える……\n「真実を知る者は……その権威として鍵を握り、必ずや世の人々に道を示すだろう」\nこれは古い格言だ。\n\nあなたの直感は、それがあなたが探し求める真実に非常に近いことを告げている。\nそしてあなたの直感はいつも正しい。"
  },
  Event_6834_Name = {
    Text = "シルバーキーの使い手"
  },
  Event_6835_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6835_Desc = {
    Text = "あなたは狂気のへの共鳴を隠さなかった。\nその存在の錯乱した誘惑に引き込まれる。\n\nしかし、寸前で食卓に縛られるのから逃れた。"
  },
  Event_6836_ChoiceDesc1 = {
    Text = "【カラスを呼ぶ】30黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_6836_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_6836_Desc = {
    Text = "あなたが去らない限り、彼らもそこを離れない。\n\n奇妙な縄が、あなたの精神と彼らの精神をつないでいる。\n\n彼らは何かをあなたに伝えたがっているようだ。"
  },
  Event_6836_Name = {
    Text = "群れから離れたカラス"
  },
  Event_6837_ChoiceDesc1 = {
    Text = "【抵抗を諦める】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_6837_ChoiceDesc2 = {
    Text = "【両手を引っ込める】"
  },
  Event_6837_Desc = {
    Text = "一匹、二匹、三匹……\n顔や指先に、群れをなす蝶が空に咲く花火のように、暗闇で宝石のように輝く。\n\nこのタイプライターは実用性はないが、美を創造することに長けている。"
  },
  Event_6837_Name = {
    Text = "インスピレーション"
  },
  Event_6838_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6838_Desc = {
    Text = "もっと重要なことが目の前にある。\n\nあなたは箱を閉じて無視することに決めた。\n\nタイプライターも次第に沈黙した。"
  },
  Event_6838_Name = {
    Text = "不意の警告"
  },
  Event_6839_ChoiceDesc1 = {
    Text = "【月を聴く】「(Skill.Arg1)」に感染する"
  },
  Event_6839_ChoiceDesc2 = {
    Text = "【矮星を聴く】「(Skill.Arg1)」に感染する"
  },
  Event_6839_ChoiceDesc3 = {
    Text = "【流星を聴く】25黒章を失う"
  },
  Event_6839_Desc = {
    Text = "熱烈で、明るく、永遠に終わらない。"
  },
  Event_6839_Name = {
    Text = "星月の音"
  },
  Event_6840_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6840_Desc = {
    Text = "光の中心には固化したシルバーコアが一滴、だが理性はそれが光っていないと告げる。\n\n視線は光源を追うが、一瞬で暗闇と未知の罠にぶつかる……"
  },
  Event_6840_Name = {
    Text = "暗夜の蛍光"
  },
  Event_6841_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6841_Desc = {
    Text = "北、北側の出口！\n\nラモンナの決断と同じように、北には必ず道がある。"
  },
  Event_6841_Name = {
    Text = "一路北へ"
  },
  Event_6842_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6842_Desc = {
    Text = "ああ……無垢な銀色、魂が君に仕掛けた冗談を意味する。\n\nさて、次の選択は？"
  },
  Event_6842_Name = {
    Text = "ショーの始まり"
  },
  Event_6843_ChoiceDesc1 = {
    Text = "【立ち去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6843_Desc = {
    Text = "頭を振って、声を振り払う。\n\nかすかなため息が、いくらかの助けをもたらした。"
  },
  Event_6843_Name = {
    Text = "一路北へ"
  },
  Event_6844_ChoiceDesc1 = {
    Text = "【回廊の奥へ進む】「(Skill.Arg1)」に感染する。さらに前進しますか"
  },
  Event_6844_ChoiceDesc2 = {
    Text = "【背を向ける】25黒章を獲得する"
  },
  Event_6844_Desc = {
    Text = "月光は消え、回廊に飲み込まれ、不吉な気配を漂わせる扉だけが目の前に残る。"
  },
  Event_6844_Name = {
    Text = "静寂の回廊"
  },
  Event_6845_ChoiceDesc1 = {
    Text = "【回廊の奥へ進む】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する。さらに前進しますか"
  },
  Event_6845_ChoiceDesc2 = {
    Text = "【背を向ける】25黒章を獲得する"
  },
  Event_6845_Desc = {
    Text = "未知の全貌、深入すべきではない。"
  },
  Event_6845_Name = {
    Text = "静寂の回廊"
  },
  Event_6846_ChoiceDesc1 = {
    Text = "【回廊の奥へ進む】「(Skill.Arg1)」に感染する。さらに前進しますか"
  },
  Event_6846_ChoiceDesc2 = {
    Text = "【背を向ける】25黒章を獲得する"
  },
  Event_6846_Desc = {
    Text = "左の扉から不気味な笑い声が響き、微かに震えて悪意を振り払う。"
  },
  Event_6846_Name = {
    Text = "静寂の回廊"
  },
  Event_6847_ChoiceDesc1 = {
    Text = "【回廊の奥へ進む】低級遺物「(RelicConfig.Arg1)」を獲得する。さらに前進しますか"
  },
  Event_6847_ChoiceDesc2 = {
    Text = "【背を向ける】25黒章を獲得する"
  },
  Event_6847_Desc = {
    Text = "右の扉が開いており、血が地面に既定の軌跡を描いている。"
  },
  Event_6847_Name = {
    Text = "静寂の回廊"
  },
  Event_6848_ChoiceDesc1 = {
    Text = "【もう何もありません、あなたは引き返した】"
  },
  Event_6848_Desc = {
    Text = "必ず突進しなければならないと誰が言った？一歩下がれば、広い海と空があるかもしれない。"
  },
  Event_6848_Name = {
    Text = "静寂の回廊"
  },
  Event_6849_ChoiceDesc1 = {
    Text = "【蝋人形を修復する】カードを選択し、その行動力消費を1点減少させる"
  },
  Event_6849_Desc = {
    Text = "蝋人形の修復作業は続いている。\nあなたは芸術家でもなければ、美学教育すら受けていない。\n\nしかし、型取り、成形、着色を熟練し始める……\nまるで生まれつき彫刻刀を持つべき存在であるかのように。"
  },
  Event_6849_Name = {
    Text = "未完成の蝋人形"
  },
  Event_6850_ChoiceDesc1 = {
    Text = "【蝋人形を修復する】カードを選択し、その行動力消費を1点減少させる"
  },
  Event_6850_Desc = {
    Text = "ガラテア、ガラテアよ……\nあなたは呼び声に導かれて、未完成の蝋人形を再び見つけた。 \n\nそれはあまりにも完璧な美しさを持ち、不安さえ覚えるほどだった。\n\n「醜さとは、完璧を裂くひと筋の裂け目」\nそして最後の瞬間、あなたはそれに、何かをしようと決意した。"
  },
  Event_6850_Name = {
    Text = "未完成の蝋人形"
  },
  Event_6851_ChoiceDesc1 = {
    Text = "【幻覚を受け入れる】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6851_ChoiceDesc2 = {
    Text = "【幻覚を否定する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6851_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6851_Desc = {
    Text = "重厚な暗い鉄橋の下、葦が生い茂る静かな河岸に、突然光る蝶が飛び出す。\n\n蝶が軽やかに手のひらに舞い降りると、悪夢のような叫び声が止み、代わりに列車が錆びた鉄橋を轢く轟音の響き、石炭が燃えるパチパチ音、車輪が回る金属の摩擦音が響く……"
  },
  Event_6851_Name = {
    Text = "鉄道の幻覚"
  },
  Event_6852_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6852_Desc = {
    Text = "そう、逃走だ。\n何かに追われ、生存本能で全力疾走し、行き止まりまで逃げる。\n違う、行き止まりのはず……地獄の番犬じゃないのか？"
  },
  Event_6852_Name = {Text = "走る"},
  Event_6853_ChoiceDesc1 = {
    Text = "【これは真実ではない】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6853_ChoiceDesc2 = {
    Text = "【落ちる、落ちる……】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6853_Desc = {
    Text = "床に落ちた鏡には、精巧な四角い枠があった。\nその枠の中に、また枠、その中にも、また枠……\n\nアリスが跳び込むように落ちていった。\n終わりのないウサギ穴を果てしなく落ち続ける。\n鏡が次々と現れる。\n\n幾つもの精神がここに囚われているのが見える。\nしかし、自分自身の姿だけは映っていなかった。"
  },
  Event_6853_Name = {
    Text = "鏡の中の鏡"
  },
  Event_6854_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6854_Desc = {
    Text = "風雪の窓越しに雪山を見下ろすと、黒いアリたちが一匹の黒いアリを追いかけている……\n思考が途切れた。"
  },
  Event_6854_Name = {
    Text = "火山の追憶"
  },
  Event_6855_ChoiceDesc1 = {
    Text = "【前に出て握る】25黒章を獲得する"
  },
  Event_6855_ChoiceDesc2 = {
    Text = "【友好的に応える】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_6855_Desc = {
    Text = "どこからともなく現れた猫が融蝕液の中に座っている。\nそのぼんやりとした輪郭は、精神次元の住民であることを示している。\n\nその見えない顔の投影が、賢い目でラモンナを見つめ、白い前足を上げて彼女に手招きする。"
  },
  Event_6855_Name = {
    Text = "彷徨う住人"
  },
  Event_6856_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6856_Desc = {
    Text = "陽気な人々の群像。\n蝋人形たちは盛装し、椅子に整然と座り、同じ誇張された笑顔を浮かべている。\nそれはまるでどこかの精神病院で見かける光景のように調和している。\n\n署名：A.F.305年、@2ロジャーズ"
  },
  Event_6856_Name = {
    Text = "肖像画の回廊"
  },
  Event_6857_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6857_Desc = {
    Text = "あなたは慎重に破片を取り外し、注意深く調べる。\nそれは再び動かなくなった。\n\n「不器用ね、動かさないでよ」\nドールがあなたの後頭部を軽く叩く。\n「短期間で二つ目は作れないんだから」"
  },
  Event_6857_Name = {
    Text = "不安のブローチ"
  },
  Event_6858_ChoiceDesc1 = {
    Text = "【鍵を使う】"
  },
  Event_6858_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_6858_Desc = {
    Text = "扉が行く手を阻んでいる。\n\nあらゆる方法を試したが、びくともしない。"
  },
  Event_6858_Name = {Text = "扉"},
  Event_6858_Tips1 = {
    Text = "「扉の鍵」が必要です。"
  },
  Event_6859_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6859_Desc = {
    Text = "あなたは自分の独断を恥じた。\n守秘者は慎重でなければならず、軽率に「質が良くない」と判断すべきではなかった。\n\nそこで、あなたはそれらを注意深く観察することにした。5分が過ぎ、10分が過ぎ……\n\nさて、今あなたは判断を下せる——\n確かにゴミだ。"
  },
  Event_6859_Name = {
    Text = "縛られた魂"
  },
  Event_6860_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6860_Desc = {
    Text = "あなたと仲間たちは武器を下ろした。\n\nこれは慈悲ではなく、蝋人形の揺れる体が長くは持たないと理解しているからだ。\n\n事実、あなたの判断は正しかった。"
  },
  Event_6860_Name = {Text = "習作"},
  Event_6861_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6861_Desc = {
    Text = "「追いついてみろよ！」\n「来いよ、バーカ！」\n「捕まえられるもんなら、捕まえてみな！」\n子供たちの声は得意げだ。\n\n「このガキども！止まれ！」\n大人の声は息を切らしている。"
  },
  Event_6861_Name = {
    Text = "私たちの記憶"
  },
  Event_6862_ChoiceDesc1 = {
    Text = "【進む】霧を抜けて、反対側へ"
  },
  Event_6862_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_6862_Desc = {
    Text = "これが探していた人だ、任務を完了した。"
  },
  Event_6862_Name = {
    Text = "一方通行の隠し通路26"
  },
  Event_6863_ChoiceDesc1 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6863_Desc = {
    Text = "ああ！あと少しだったのに！待って、なんで3つのダイスで10点が出たの？\nダイスはおとなしくあなたの前に転がり、無邪気で無垢に見える。"
  },
  Event_6863_Name = {
    Text = "止まらぬ賭け"
  },
  Event_6864_ChoiceDesc1 = {
    Text = "【離れる】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6864_Desc = {
    Text = "くそ！6点じゃないけど、まだ少しは儲けた。\n\nそれで、あいつら何点だったんだ？"
  },
  Event_6864_Name = {
    Text = "止まらぬ賭け"
  },
  Event_6865_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_6865_Desc = {
    Text = "外れたけど、まあいいか。\n\nあいつら、結局何点出したんだ？"
  },
  Event_6865_Name = {
    Text = "止まらぬ賭け"
  },
  Event_6866_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6866_Desc = {
    Text = "あなたは頭を下げて石膏の破片を選び取り、彼女を一つ一つ組み立てていく。\n彼女の体の一部があなたの手の中で徐々に形を成していく。"
  },
  Event_6866_Name = {
    Text = "残躯を組み立てる"
  },
  Event_6867_ChoiceDesc1 = {
    Text = "【鍵を拾う】"
  },
  Event_6867_Desc = {
    Text = "錆びた鍵束。\n扉の鍵を解放するために使用する。"
  },
  Event_6867_Name = {Text = "扉の鍵"},
  Event_6868_ChoiceDesc1 = {
    Text = "【表】50%の確率で高級遺物「(RelicConfig.Arg2)」を獲得し、50%の確率で「(Skill.Arg3)」に感染する"
  },
  Event_6868_ChoiceDesc2 = {
    Text = "【裏】50%の確率で75黒章を獲得し、50%の確率で「(Skill.Arg3)」に感染する"
  },
  Event_6868_ChoiceDesc3 = {
    Text = "【相手に先に選ばせる】50%の確率で呪われた遺物「(RelicConfig.Arg2)」を獲得し、50%の確率で「(Skill.Arg3)」に感染する"
  },
  Event_6868_Desc = {
    Text = "ただの賭けだ、負けるはずがない。\n\n模様が刻まれたコインが高く投げられ、すぐに落ちて、あなたの手のひらに温もりを伝える。"
  },
  Event_6868_Name = {
    Text = "有体なギャンブラー"
  },
  Event_6869_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6869_Desc = {
    Text = "「運命に頼る者は、運命に翻弄される」\nあなたは離れることを選んだ。"
  },
  Event_6869_Name = {
    Text = "有体なギャンブラー"
  },
  Event_6870_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6870_Desc = {
    Text = "「守秘者」\nラモンナの声で目が覚める。\n\nしかし、落下する感覚は消えない。"
  },
  Event_6870_Name = {
    Text = "鏡の中の鏡"
  },
  Event_6871_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6871_Desc = {
    Text = "セレナーデは恋の歌から生まれた曲と言われる。\n夏の夜、窓辺で、数人の仲間と共に奏でられる、そんな情感豊かな曲。\n\nその旋律は気ままで表面的で、ロジャーズの美学にはまるでそぐわない。\nそれでも彼のレパートリーに残っている。\nその理由を知っているのは彼自身だけだろう。"
  },
  Event_6871_Name = {Text = "悪趣味"},
  Event_6872_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6872_Desc = {
    Text = "あなたは彼らの夢語りに惑わされることを拒む。\n\n「嘘ばかりだ！君たちは永遠の夜に囚われているのに、どうやって宇宙を旅するというんだ？」\n\n眼たちは笑った。無数の笑い声が巨大な音の波となり押し寄せ、あなたの心臓が震える。\n\n眼は言った。\n「他の眼を奪うことで。全ての眼は一つの宇宙。\n千の眼を持てば、真の時空の旅に出られる」"
  },
  Event_6873_ChoiceDesc1 = {
    Text = "【受け取る】3つの中から1つ高級遺物を獲得する"
  },
  Event_6873_Desc = {
    Text = "ああ、そうだ、あの忌まわしい影は君自身だよ。\n\n溢れ出る悪意が足元の黒い泥と混じり合って踊っている。\n嫌じゃなければ、それが君の肩に乗りたがっているんだ。"
  },
  Event_6873_Name = {
    Text = "鏡面の下"
  },
  Event_6874_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6874_Desc = {
    Text = "しばらくして、束縛が突然緩み、よろけてしまう。\n\n静かな糸を振り返る——「流砂をかき乱すな」、この言葉は密境でも通用するかもしれない。"
  },
  Event_6874_Name = {
    Text = "深淵に沈む"
  },
  Event_6875_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6875_Desc = {
    Text = "知識の火が灯り、すべての束縛を焼き尽くした——\n少なくとも、そう思った。"
  },
  Event_6875_Name = {
    Text = "深淵に沈む"
  },
  Event_6876_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6876_Desc = {
    Text = "全力で束縛を振りほどき、糸が衣服を裂き、肌に細かな血痕を残す。\n\n蜘蛛の巣が通行料として何かを残したが、心は軽くなった——自由だ。"
  },
  Event_6876_Name = {
    Text = "深淵に沈む"
  },
  Event_6877_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6877_Desc = {
    Text = "融蝕の異物が生み出した手紙、その情報もほとんど消されてしまう。\n\n手紙から有益な情報を得られず、破り捨てた。"
  },
  Event_6877_Name = {Text = "蝶の章"},
  Event_6878_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6878_Desc = {
    Text = "文字が意図的に消されても、手紙の価値をはっきりと感じ取れる。"
  },
  Event_6878_Name = {Text = "蝶の章"},
  Event_6879_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6879_Desc = {
    Text = "慎重に行動する。\n\nラモンナは腰をかがめ、廊下に戻り、次の部屋に潜り込む。"
  },
  Event_6879_Name = {
    Text = "窓の中の影"
  },
  Event_6880_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6880_Desc = {
    Text = "あなたは絶望の叫び声を上げる。\n\nカラスの群れはその声に惑わされたかのように、すぐに姿を消し、黒い痕跡を残す。"
  },
  Event_6880_Name = {
    Text = "カラスの群の歌"
  },
  Event_6881_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6881_Desc = {
    Text = "あなたは体を丸め、黒い点になろうとする。\n\nそうすれば、彼らはあなたに気づかないだろう。\n\nどれくらい経ったかわからないが、あなたは目を開ける。\n\n光が見える。"
  },
  Event_6881_Name = {
    Text = "カラスの群の歌"
  },
  Event_6882_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6882_Desc = {
    Text = "影は指の間から静かに流れ去り消える。\nそれは金色の塵となった。"
  },
  Event_6882_Name = {
    Text = "シルバーキーの使い手"
  },
  Event_6883_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6883_Desc = {
    Text = "あなたは髪を無意識にかきむしる。\n\n妄想と狂気が脳内で先を争って噴出する。\n黒い粘液に包まれた塊が奥深くに潜んでいる。\n\nそれを切り開けば、あなたに一体どのような贈り物が与えられるだろうか？"
  },
  Event_6883_Name = {
    Text = "大脳撹拌"
  },
  Event_6884_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6884_Desc = {
    Text = "カラフルな油膜が次第に視界いっぱいに広がる。\n\nあなたの感情は無秩序な狂喜に陥る。"
  },
  Event_6884_Name = {
    Text = "大脳撹拌"
  },
  Event_6885_ChoiceDesc1 = {
    Text = "【ポケットに入れる】"
  },
  Event_6885_Desc = {
    Text = "水銀に近い物質。\n\n融蝕液から抽出され、主に儀式で覚醒体を召喚するために使用される。"
  },
  Event_6885_Name = {
    Text = "シルバーコア"
  },
  Event_6886_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6886_Desc = {
    Text = "箱から楽しげな笑い声が溢れ出し、温かい光が消えた後にカードが見えた。\n\nそこには3人の棒人間が描かれていた。\nあなたと、銀髪のラモンナ、金髪のオジール。\n\n横には一行の文字があった。\n   「ありがとう！」"
  },
  Event_6886_Name = {
    Text = "善意の贈り物"
  },
  Event_6887_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6887_Desc = {
    Text = "あなたの肉体は蝶の群れを避けたが、蝶たちは目的を失わず、あなたの手提げ箱に入り込み、タイプライターのインクを貪り吸う。"
  },
  Event_6887_Name = {
    Text = "妄念の噴出"
  },
  Event_6888_ChoiceDesc1 = {
    Text = "【誤りを指摘する】1枚の指令カードを選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6888_ChoiceDesc2 = {
    Text = "【演奏を聴き終える】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_6888_ChoiceDesc3 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_6888_Desc = {
    Text = "少年の蝋人形がピアノの前で練習曲を弾いている。\n\n彼の先生もまた蝋人形で、そばで指導している。\n\n133，355，244……\n間違っている、すべての音が間違っている。"
  },
  Event_6888_Name = {
    Text = "ピアノレッスン"
  },
  Event_6889_ChoiceDesc1 = {
    Text = "【抵抗を諦める】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_6889_ChoiceDesc2 = {
    Text = "【両手を引っ込める】"
  },
  Event_6889_Desc = {
    Text = "あなたは内なる衝動に抗えない。\n指先は森で迷子になった子供のように、キーボードの上をさまよい、遊び……\n\nやがて、タイプライターから蝶が飛び出した。\n一匹、二匹、三匹……\n顔や指先に、群れをなす蝶が空に咲く花火のように、暗闇で宝石のように輝く。\n\nこのタイプライターは実用性はないが、美を創造することに長けている。"
  },
  Event_6889_Name = {
    Text = "インスピレーション"
  },
  Event_6890_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6890_Desc = {
    Text = "紙を暗赤色の光にかざし、細部を見逃さないようにする。\nこれは健康診断書で、受診者はメイソンだ。\n\n「体重40kg、血中酸素濃度正常、同調率30%、共鳴値……」\n続きを見たかったが、全体の文字が徐々に消えていき、白紙に戻ってしまった。"
  },
  Event_6890_Name = {
    Text = "タイプライター"
  },
  Event_6891_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6891_Desc = {
    Text = "そう、逃げているわけじゃない。\n追っているのは、雪の積もった狭い路地を駆け抜ける「地獄の番犬」だ。\nあの日、トゥングースで瓦礫から引き上げてくれた人の顔を忘れないように、このことも忘れない。\n……誰だったっけ？"
  },
  Event_6891_Name = {Text = "走る"},
  Event_6892_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6892_Desc = {
    Text = "この隔離された空間では、あなたが頼ることができるのは、ただ自分自身だけだ。"
  },
  Event_6892_Name = {
    Text = "悪夢の旅人"
  },
  Event_6893_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6893_Desc = {
    Text = "危機とリスクが共存する。\n錠に触れた瞬間、腐蝕性の液体が手のひらを焼く。\n扉の向こうの遺物が価値あるものであることを願う。"
  },
  Event_6893_Name = {
    Text = "鉄門の向こう"
  },
  Event_6894_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6894_Desc = {
    Text = "触れたことのない世界の中を無謀に突き進むなんて……あなたの精神は不安定だが、まだ理性を失うほどではなかった。\n\n未知なる物の恐ろしさを、あなたは深く心に刻んでいる。"
  },
  Event_6894_Name = {
    Text = "悪夢の旅人"
  },
  Event_6895_ChoiceDesc1 = {
    Text = "【大声で叫ぶ】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6895_ChoiceDesc2 = {
    Text = "【静寂を感じる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」「(Skill.Arg3)」に感染する"
  },
  Event_6895_ChoiceDesc3 = {
    Text = "【水面に浮かび上がる】25黒章を獲得する"
  },
  Event_6895_Desc = {
    Text = "あなたは、静寂を聞いた。  \nそれは増幅された静けさであり――\n波の音のように、空間のすべてを満たしていた。\n\nあなたはそっと顔を上げた。  \n星空を見上げる小さな点のように。"
  },
  Event_6895_Name = {
    Text = "過去の水"
  },
  Event_6896_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6896_Desc = {
    Text = "耳を澄ませて音の出所を探し、悪戯者を見つけようとする。\n\nしかし、追い詰めたと思った瞬間に、まるで迷路に迷い込んだように元の場所に戻ってしまう。\n\nがっかりしてレンガの壁を蹴ると、レンガが落ち、壁の空洞に秘宝が輝いている。"
  },
  Event_6896_Name = {
    Text = "迷踪の声"
  },
  Event_6897_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6897_Desc = {
    Text = "再生の問題に違いない、きっとそうだ。\n\nあなたは針を戻し、前半の不快な音楽を我慢して聞いたが、記憶の中のノック音は鳴らなかった。\n\n何もない背後で、小さな影が静かに逃げていく。"
  },
  Event_6897_Name = {
    Text = "迷踪の声"
  },
  Event_6898_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6898_Desc = {
    Text = "あなたの周りには誰もいない。\nノック音の秘密は蓄音機の内部に隠されているに違いない。\n\n自分の判断に自信を持ち、古い蓄音機を分解してみた。\n\nしかし、内部の腐蝕した金属部品と厚い埃以外、何も見つからなかった。\n\nただ一つの笑い声が霧の中に消え、夢の中にいるかのように軽やかだった。"
  },
  Event_6898_Name = {
    Text = "迷踪の声"
  },
  Event_6899_ChoiceDesc1 = {
    Text = "【愚者の白質】Arg1ライフを回復する"
  },
  Event_6899_ChoiceDesc2 = {
    Text = "【狂人の心臓】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6899_ChoiceDesc3 = {
    Text = "【食べるのを拒否する】25黒章を獲得する"
  },
  Event_6899_Desc = {
    Text = "「愚者の白質は煮えた魚のスープのように美味で、狂人の心臓は熱々で血まみれのスコーンのようだ」\n黒い影が不明な食材を含む料理をあなたの前に差し出す。\n\n香りが鼻腔に強引に入り込み、唾液腺は降参し、胃腸は悲しく痙攣し、渇望の呻き声を上げる。"
  },
  Event_6899_Name = {
    Text = "肉体の宴"
  },
  Event_6900_ChoiceDesc1 = {
    Text = "【風鈴に触れる】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_6900_ChoiceDesc2 = {
    Text = "【風鈴を観察する】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_6900_ChoiceDesc3 = {
    Text = "【何もしない】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6900_Desc = {
    Text = "チリン、チリン……\n\nそれは錆びた風鈴。\nぎこちない音色が、隙間から這い出てくる。"
  },
  Event_6900_Name = {
    Text = "錆びた風鈴"
  },
  Event_6901_ChoiceDesc1 = {
    Text = "【成り行きを見守る】生き残りを試みる"
  },
  Event_6901_ChoiceDesc2 = {
    Text = "【武器を振るう】突破を試みる"
  },
  Event_6901_ChoiceDesc3 = {
    Text = "【片手を握る】25黒章を獲得する"
  },
  Event_6901_Desc = {
    Text = "足元に突然黒い沼が現れ、無数の手がそこから湧き出てきた。\n\nそれらはさまざまな肌色、材質、質感を持ち、孔雀ブルーや鱗のあるもの、目がついているものなど、無数の次元と空間を越えてきたようで、次の不運な者を彼らの大家族に引き込もうとしている。\n\nあなたは決断する——"
  },
  Event_6901_Name = {
    Text = "暗色の沼"
  },
  Event_6902_ChoiceDesc1 = {
    Text = "【それを押さえる】山札からランダムに指令カードを3枚引き、1枚選択して複製する"
  },
  Event_6902_ChoiceDesc2 = {
    Text = "【少し揺らす】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6902_ChoiceDesc3 = {
    Text = "【何もしない】25黒章を獲得する"
  },
  Event_6902_Desc = {
    Text = "チリン、チリン……\n\nそれは錆びた風鈴。\nぎこちない音色が、隙間から這い出てくる。"
  },
  Event_6902_Name = {
    Text = "小さな風鈴"
  },
  Event_6903_ChoiceDesc1 = {
    Text = "【それらに反論する】低級遺物「(RelicConfig.Arg1)」を獲得し、症状を1回感染させる"
  },
  Event_6903_ChoiceDesc2 = {
    Text = "【それらに同調する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_6903_ChoiceDesc3 = {
    Text = "【新しい観点を提示する】25黒章を獲得する"
  },
  Event_6903_Desc = {
    Text = "「私たちに近づかないで」\n群れをなす鼠があなたを中心に囲み、少なくとも五フィートの距離を保っている。\n\n「私たちは繁殖し、成長し、食べ物を選ばない——だから人間に病気、不安、苦痛をもたらす」\n「私たちと人間は近づきすぎてはいけない、ここはあなたが来るべき場所ではない」\n鼠たちの警戒を解くために、あなたは決断する——"
  },
  Event_6903_Name = {Text = "ペスト"},
  Event_6904_ChoiceDesc1 = {
    Text = "【墜落を続ける】「(Skill.Arg1)」に感染する。引き続き墜落しますか"
  },
  Event_6904_ChoiceDesc2 = {
    Text = "【手を引いて離れる】25黒章を獲得する"
  },
  Event_6904_Desc = {
    Text = "「あなた」があなたを招いている。\n螺旋の奥で、過去と未来の「あなた」が異なる次元からの「贈り物」を送ってきた。"
  },
  Event_6904_Name = {
    Text = "螺旋の深淵"
  },
  Event_6905_ChoiceDesc1 = {
    Text = "【カラスを押さえつける】40黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_6905_ChoiceDesc2 = {
    Text = "【放置する】25黒章を獲得し、離れる"
  },
  Event_6905_Desc = {
    Text = "孤独なカラスが、かすれた喉で鳴きながら、  \n自らの漆黒の羽根を一本ずつ引き抜いていく。  \n\n痛みに震え、鋭く叫ぶが、動きを止められない。\n\n「カァ——カァ——」\n\nその目からは黒い液体を伴った青い涙が流れる。  \nそれを目にしたのは、あなただけだった。"
  },
  Event_6905_Name = {
    Text = "融蝕液の涙"
  },
  Event_6906_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6906_Desc = {
    Text = "赤、それは情熱的で奔放で、華やかだ。\n\nちょうどそんな美しい人を知っている。\nいずれ会うことになるだろう。\n\nさて、次の選択は？"
  },
  Event_6906_Name = {
    Text = "ショーの始まり"
  },
  Event_6907_ChoiceDesc1 = {
    Text = "【大声で喝采する】"
  },
  Event_6907_ChoiceDesc2 = {
    Text = "【うとうとする】"
  },
  Event_6907_Desc = {
    Text = "あなたはとても長い夢を見た。\n夢の中で、あなたは観客席に座り、舞台の上で歌う少年を見ている。\n\n「チャーリーの、大事な大事なトラ猫ちゃん……\nある日どこかにいっちゃって……\nチャーリーは、ほうぼう探したの」\n……\n空虚で乾いた声は機械的に繰り返され、果てしなく終わりがない……"
  },
  Event_6907_Name = {
    Text = "終幕の儀Ⅳ"
  },
  Event_6908_ChoiceDesc1 = {
    Text = "【上部の枝節を解く】"
  },
  Event_6908_ChoiceDesc2 = {
    Text = "【下部の枝節を解く】"
  },
  Event_6908_Desc = {
    Text = "残留する密境の知識が絡み合い、不安定な力場を作り出している。\n\nもしかしたら、絡まった霊知を解きほぐし、自分の進むべき道を見つけられるかもしれない。"
  },
  Event_6908_Name = {
    Text = "絡み合う道"
  },
  Event_6909_ChoiceDesc1 = {
    Text = "【離れる】覚醒体を2体選択して覚醒させる"
  },
  Event_6909_Desc = {
    Text = "立ち上がり、すぐに出口へ向かう。\n「君は覆いをめくった……\n秘密、君は秘密を見つけた……」\n\nその声の波が、喧騒の海となって押し寄せる。\n床が恐ろしい共振に揺れ、君の心音すらかき消しそうだった。\n\n振り返ることなく、全速力でその場を離れた。"
  },
  Event_6909_Name = {
    Text = "終幕の儀Ⅴ"
  },
  Event_6910_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6910_Desc = {
    Text = "あなたは抵抗せず、沈むことも選ばない。"
  },
  Event_6910_Name = {
    Text = "頭の中の穴"
  },
  Event_6911_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6911_Desc = {
    Text = "あなたは抵抗せず、汚れが身体と精神を飲み込むままにし、長い眠りの後、銀の光があなたの握る手に落ちた。"
  },
  Event_6911_Name = {
    Text = "頭の中の穴"
  },
  Event_6912_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6912_Desc = {
    Text = "もがくほど、脳の汚れが深く沈み、罪悪感で満ちた脳の奥底には、謎の贈り物が埋まっていた。"
  },
  Event_6912_Name = {
    Text = "頭の中の穴"
  },
  Event_6913_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6913_Desc = {
    Text = "網が壊れると何かが頭をよぎり、子供たちの笑顔が浮かんだようだ。"
  },
  Event_6913_Name = {
    Text = "迷走ネットワーク"
  },
  Event_6914_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6914_Desc = {
    Text = "猫は満足そうにうなずき、すぐに影となって消え、いくつかの黒く丸い物体を残した。"
  },
  Event_6914_Name = {
    Text = "彷徨う住人"
  },
  Event_6915_ChoiceDesc1 = {
    Text = "【書簡を読む】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_6915_ChoiceDesc2 = {
    Text = "【箱をしっかり閉める】"
  },
  Event_6915_Desc = {
    Text = "舞い上がる手紙が視界いっぱいに広がる。\nそれは、まるで無言で催促しているかのようだ。"
  },
  Event_6915_Name = {
    Text = "予期せぬ手紙"
  },
  Event_6916_ChoiceDesc1 = {
    Text = "【進む】霧を抜けて、反対側へ"
  },
  Event_6916_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_6916_Desc = {
    Text = "目の前の道に隠し通路が現れた。\n\n中は黒い霧が立ち込め、どこに通じているかわからない。"
  },
  Event_6916_Name = {
    Text = "隠し通路"
  },
  Event_6917_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6917_Desc = {
    Text = "あなたはその苦しみを終わらせる決意をする。\n柔らかな身体に手を伸ばして握りしめた。  \n強く、さらに強く……\n\nそれはあなたの手の中で最後の抵抗をし、やがて温かな液体となって弾けた。"
  },
  Event_6917_Name = {
    Text = "融蝕液の涙"
  },
  Event_6918_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6918_Desc = {
    Text = "安心して、これは次元で砕けた他人の記憶だよ。\nあなたには影がある。\nでも、その影の中の人は本当にあなたなの？"
  },
  Event_6918_Name = {
    Text = "記憶の破片・ビール"
  },
  Event_6919_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6919_Desc = {
    Text = "あなたはカラスが羽をちぎろうとするのを力いっぱい止めたが、カラスは執拗に頭をねじり、骨がきしむほどの力で抵抗した。\n\n顔を真っ赤にして全力でカラスの体を押さえ込み、その狂った自傷行為を止めた。\n\nほっとした瞬間、カラスの半分禿げた首が急に後ろにねじれ、体が力を失い、手の中で黒い濃い液体に変わった。"
  },
  Event_6919_Name = {
    Text = "融蝕液の涙"
  },
  Event_6920_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6920_Desc = {
    Text = "あなたは絶望的なベルの音を冷酷に無視した。\n\n次の瞬間に原始世界に戻されるとしても、あなたと偉大な使命が共に葬られるとしても。\n\n出るべきではない電話には、出ない。\n\nこのシンプルな真理をあなたはよく知っている。"
  },
  Event_6920_Name = {
    Text = "電話に出てください"
  },
  Event_6921_ChoiceDesc1 = {
    Text = "【うつむいて見る】25黒章を獲得する"
  },
  Event_6921_ChoiceDesc2 = {
    Text = "【私は必ず見つける】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6921_Desc = {
    Text = "黒い影を追いかけると、突然浅い水たまりに足を踏み入れる。色の見えない液体が靴を覆い、冷たさが染み込む。\n\n水中から声がする「あなたは見つけたくない」"
  },
  Event_6921_Name = {
    Text = "あなたは見つけたくない"
  },
  Event_6922_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6922_Desc = {
    Text = "安全な選択。"
  },
  Event_6922_Name = {
    Text = "草むらの後ろ"
  },
  Event_6923_ChoiceDesc1 = {
    Text = "【カラスを追い払う】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_6923_ChoiceDesc2 = {
    Text = "【無視する】25黒章を獲得し、離れる"
  },
  Event_6923_Desc = {
    Text = "療養所の部屋にカラスがいるなんて？\n\nしかし、確かにカラスの不気味な笑い声を聞いた。\n暗闇の中、まだ舞台に上がっていない勢力が、その空洞の鳥の目からあなたたちを見つめている。\n黒い生物たちは首をねじり、路地の吊り灯に立ち、悪意を含んだ目であなたを見下ろしている。\nその重なり合った頭部は、まるで融蝕液に浸かった同じ体を共有しているかのようだ。"
  },
  Event_6923_Name = {
    Text = "提灯の黒いカラス"
  },
  Event_6924_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6924_Desc = {
    Text = "汚れを恐れるな、獲得。\nものは失うものより多い。"
  },
  Event_6924_Name = {
    Text = "草むらの後ろ"
  },
  Event_6925_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6925_Desc = {
    Text = "霊知の嵐がトゥルーを包み込んでいる。\nあなたは彼と目を合わせ、一緒に暗闇へと進む。"
  },
  Event_6925_Name = {
    Text = "代行者の承諾"
  },
  Event_6926_ChoiceDesc1 = {
    Text = "【進む】霧を抜けて、反対側へ"
  },
  Event_6926_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_6926_Desc = {
    Text = "あなたは暗闇に落ちた。\n視界の果てに、鍵穴のような隙間から一筋の光が漏れている。\n\nシルバーキーが微かに光り、あなたをその通路へと導く。"
  },
  Event_6926_Name = {
    Text = "一方通行の隠し通路"
  },
  Event_6927_ChoiceDesc1 = {
    Text = "【「(Skill.Arg1)」に感染し、遺物：「(RelicConfig.Arg2)」を獲得する】"
  },
  Event_6927_ChoiceDesc2 = {
    Text = "【指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する】"
  },
  Event_6927_Desc = {
    Text = "事件203（開発中）、最終効果ではありません"
  },
  Event_6927_Name = {
    Text = "事件203（開発中）"
  },
  Event_6928_ChoiceDesc1 = {
    Text = "【つなぎ合わせる】指令カードを1枚削除し、遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6928_ChoiceDesc2 = {
    Text = "【撫でる】攻撃/防御カードを1枚削除し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6928_ChoiceDesc3 = {
    Text = "【嫌悪する】25黒章を獲得する"
  },
  Event_6928_Desc = {
    Text = "「私の残骸が好き？もしよければ、体を組み立てるのを手伝ってくれる？」\n半身だけの石膏像が唇を動かし、耳元に落ちる柔らかな声が、硬く冷たいはずの唇から溢れ出す。"
  },
  Event_6928_Name = {
    Text = "残躯を組み立てる"
  },
  Event_6929_ChoiceDesc1 = {
    Text = "【封筒を捨てる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6929_ChoiceDesc2 = {
    Text = "【胸に抱きしめる】「(Skill.Arg1)」に感染し、遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_6929_Desc = {
    Text = "これは救助を求める手紙で、書き手は冷静を保とうと努めているが、時折歪む筆跡が彼の隠された恐怖を露わにしている。\n\n「すべてが予想を超えている。\n今誰かが呪われていると言ったら、私は絶対に信じる」\n「誰かが私を狂人だと言ったが、それは半分正しい。\n私は狂気の境界で揺れている」\n「でも本当に見たんだ！それは変異し消えていく。\n増殖する黒い粘着物が全身に這い上がろうとしている！」\n「逃げた！速く逃げたが、視線は私から離れない。\n予感がする、必ず見つけられる！あの忌まわしい黒泥が再び頭蓋骨に流れ込む。\n誰でもいい、この手紙を受け取った人、お願いだ、助けて——」"
  },
  Event_6929_Name = {
    Text = "救助要請の手紙"
  },
  Event_6930_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6930_Desc = {
    Text = "「落ち着いて」\nラモンナがあなたの頭を軽く叩く。\n「ただの過去の断片よ。\n誰かがこの次元の通路に落としたものね」\n\n確かに、懐かしい感じがする。"
  },
  Event_6930_Name = {
    Text = "緊急通信"
  },
  Event_6931_ChoiceDesc1 = {
    Text = "【ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する】"
  },
  Event_6931_ChoiceDesc2 = {
    Text = "【ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する】"
  },
  Event_6931_ChoiceDesc3 = {
    Text = "【ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する】"
  },
  Event_6931_Desc = {
    Text = "事件205（開発中）、最終効果ではありません"
  },
  Event_6931_Name = {
    Text = "事件205（開発中）"
  },
  Event_6932_ChoiceDesc1 = {
    Text = "【遺物：「(RelicConfig.Arg1)」を獲得する】"
  },
  Event_6932_ChoiceDesc2 = {
    Text = "【遺物：「(RelicConfig.Arg1)」を獲得する】"
  },
  Event_6932_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_6932_Desc = {
    Text = "事件204（開発中）、最終効果ではありません"
  },
  Event_6932_Name = {
    Text = "事件204（開発中）"
  },
  Event_6933_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6933_Desc = {
    Text = "孤独な月が空に高く掛かり、あなたにはその祈りの讃歌がはっきりと聞こえた。\n奇妙な音色は、穢れたものの囁きのようだった。\n\n祈りが止み、あなたは立ち去ろうとする。\nすると、背後に白い幻影が現れる。\n\n「運命と祈りを覗き見る冒涜者よ、恩恵と代償も約束通りに訪れるだろう」"
  },
  Event_6933_Name = {
    Text = "銀月の破片"
  },
  Event_6934_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6934_Desc = {
    Text = "背後からガラスの割れる音が聞こえ、しばし考えた後、振り返らずに離れる。"
  },
  Event_6934_Name = {
    Text = "銀月の破片"
  },
  Event_6935_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6935_Desc = {
    Text = "手のひらにすくった月光が石碑に落ちる。\n\n誰かが厚い泥の下に埋められ、見物人たちは自然死を迎えたと主張し、地下で安らかに眠るだろうと言う。\n\nしかし埋もれた泥が動き、悲鳴の中で、ぐったりとした月が這い出てきた。"
  },
  Event_6935_Name = {
    Text = "銀月の破片"
  },
  Event_6936_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6936_Desc = {
    Text = "ただ生き延びようとする生き物が、休むための浮木を求めているだけ……\nあなたはため息をつき、蝶の尾から流れる黒い液体をそのままにする。"
  },
  Event_6936_Name = {
    Text = "存在しないはずのもの"
  },
  Event_6937_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6937_Desc = {
    Text = "これは予告された罠であり、あなたはその危険をよく知っている。\n\n宝石よりも、あなた自身がより貴重な存在だ。"
  },
  Event_6937_Name = {
    Text = "翻覆の魔手"
  },
  Event_6938_ChoiceDesc1 = {
    Text = "【シルバーキーを差し込む】"
  },
  Event_6938_Desc = {
    Text = "飽和した融蝕液の中に何かが含まれているようだ…シルバーキーで観測してみよう。"
  },
  Event_6938_Name = {
    Text = "黒い水たまり"
  },
  Event_6939_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6939_Desc = {
    Text = "あなたは依頼を受けたが、少し問題が発生した。\n「その蝋人形は……どんな形ですか？」\n\n「それは私の半身だからね。\nもちろん私とそっくりだよ」\n\n「でも……」\n「あなたの顔は、もう完全に腐っているんですよ……」"
  },
  Event_6939_Name = {
    Text = "私の半身"
  },
  Event_6940_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6940_Desc = {
    Text = "君は仲間の手を握り締めた。\nラモンナは驚いて君に目を向けたが、最終的には無礼を許した。"
  },
  Event_6940_Name = {
    Text = "夢の祈り"
  },
  Event_6941_ChoiceDesc1 = {
    Text = "【誰か尋ねる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_6941_ChoiceDesc2 = {
    Text = "【向かい合う】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染"
  },
  Event_6941_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6941_Desc = {
    Text = "強烈な視線を感じて足を止める。\n「誰だ？」\n\n濃霧の中で見渡す。\n「ジェンキン、君なのか？」\n\n霧は深く立ち込め、庭の奥から融蝕生物の叫びがかすかに聞こえる。\n何の手がかりも得られず振り返ると、空中に浮かぶ巨大な目にぶつかりそうになる。"
  },
  Event_6941_Name = {
    Text = "盲目の注視"
  },
  Event_6942_ChoiceDesc1 = {
    Text = "【硬貨に触れない】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6942_ChoiceDesc2 = {
    Text = "【硬貨に触れる】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_6942_Desc = {
    Text = "あなたは黒い泥に沈んでいた一枚の古びた硬貨を見つけた。\n\nその片面には赤と青の絡み合う血管が形作られ、もう片面には純白の公爵夫人の横顔が、浮き彫りで精緻に描かれていた。\n\nその表情は微笑み、あなたの蒼白の瞳をじっと見つめていた。\nそれが一瞬震えたかと思うと、急に不規則に動き始めた。"
  },
  Event_6942_Name = {
    Text = "古びた硬貨"
  },
  Event_6943_ChoiceDesc1 = {
    Text = "【振り向く】25黒章を獲得する"
  },
  Event_6943_ChoiceDesc2 = {
    Text = "【前進し続ける】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6943_Desc = {
    Text = "再び、あの奇妙な足音が聞こえてくる。\nそれはあなたの後ろにぴったりとついてきて、作業室から館長室、そして地下室へとついてくる。\n\n彼は距離を保ちながら、失礼にならないようにしているようだが、気が散って仕方ない。"
  },
  Event_6943_Name = {Text = "足音"},
  Event_6944_ChoiceDesc1 = {
    Text = "【観察する】25黒章を獲得する"
  },
  Event_6944_ChoiceDesc2 = {
    Text = "【撫でる】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_6944_Desc = {
    Text = "小路に突然黒猫が飛び出してきて、異常に親しげに足元に絡みついてきた。\n\nその瞳は、まるで「追いかけるのをやめて、しばらく私と遊んで」と言わんばかりに、ぞっとするような光で輝いていた。"
  },
  Event_6944_Name = {
    Text = "夜の精霊"
  },
  Event_6945_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6945_Desc = {
    Text = "覚醒体たちはあなたの指示を待っているが、あなたには他に気を配る余裕がない。"
  },
  Event_6945_Name = {
    Text = "角度から"
  },
  Event_6946_ChoiceDesc1 = {
    Text = "【フィルムを検査する】「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_6946_ChoiceDesc2 = {
    Text = "【カメラをチェックする】50黒章を獲得する"
  },
  Event_6946_Desc = {
    Text = "内臓を引き出すように、カメラの中のフィルムが引き裂かれ、無造作に捨てられている。\n\n眩しい白い光が一閃し、街角に捨てられたカメラが傾き、シャッターが勝手に押される。\n\n「カシャ——」\n驚愕し呆然とした表情が、カメラのフィルムに忠実に記録された。"
  },
  Event_6946_Name = {
    Text = "無罪記録"
  },
  Event_6947_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6947_Desc = {
    Text = "ただ風が錠を揺らす音だけで、気にすることはない、無視していい。"
  },
  Event_6947_Name = {
    Text = "鉄門の向こう"
  },
  Event_6948_ChoiceDesc1 = {
    Text = "【選択する】「(Skill.Arg1)」に感染する"
  },
  Event_6948_ChoiceDesc2 = {
    Text = "【選択する】「(Skill.Arg1)」に感染する"
  },
  Event_6948_ChoiceDesc3 = {
    Text = "【選択する】「(Skill.Arg1)」に感染する"
  },
  Event_6948_Desc = {
    Text = "「私」は唯一無二の私、無数の宇宙の中で、他にない存在。"
  },
  Event_6948_Name = {
    Text = "魂の共鳴"
  },
  Event_6949_ChoiceDesc1 = {
    Text = "【受け取る】1つの低級遺物を選択する"
  },
  Event_6949_Desc = {
    Text = "それは「私」かもしれない。\n\n時間の影を越え、次元の壁を越え、一筋の裂け目を通して私と対峙する「私」。"
  },
  Event_6949_Name = {
    Text = "魂の共鳴"
  },
  Event_6950_ChoiceDesc1 = {
    Text = "【問題を指摘する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_6950_ChoiceDesc2 = {
    Text = "【疑問を飲み込む】「(Skill.Arg1)」に感染し、再刻印をあと1回行える"
  },
  Event_6950_Desc = {
    Text = "少女にとって、これは言い難いことだろう。\nあなたは疑問を飲み込んだ。\n\nしかし、彼女は胸元を撫でながら静かに語った。\n25年間続いた長い夢の話を、そして夢から覚めた後の孤独を。"
  },
  Event_6950_Name = {
    Text = "囚われた命"
  },
  Event_6951_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6951_Desc = {
    Text = "あなたは紙と木くずを火の中に投げ入れた。\n\n火はそれらを貪欲に飲み込み、満足そうにげっぷをした。\n\n世界を滅ぼす準備が整ったようだ。\n離れる前に、あなたにささやかな祝福をくれた。"
  },
  Event_6951_Name = {
    Text = "微かな火"
  },
  Event_6952_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6952_Desc = {
    Text = "残された憎しみの火種を、無情に踏み潰した。\n\n周囲の怨みと未練が、少し和らいだようだ。"
  },
  Event_6952_Name = {
    Text = "微かな火"
  },
  Event_6953_ChoiceDesc1 = {
    Text = "【カラスを追い払う】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6953_ChoiceDesc2 = {
    Text = "【無視する】離れる"
  },
  Event_6953_Desc = {
    Text = "カラスを捕まえようとすると、部屋の端から端へと飛び、奇妙な鳴き声を上げ続ける。\nカラスが飛び去った場所には、黒い粘液が黒い跡となって滴り落ちる。"
  },
  Event_6953_Name = {
    Text = "提灯の黒いカラス"
  },
  Event_6954_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6954_Desc = {
    Text = "「あなたは要点をよく捉えていますね」\n男は満面の笑みを浮かべた。\n\n「それはこの世で最も美味なる食材で、どんな美食家も丁寧に調理し、味わい尽くすに値します」\n\n「残念ながら今回は味見させてあげられません。お詫びとして、私の持つ別の美味を差し上げましょう」\n\nそう言って、男は淡い紅色の柔らかい肉片を投げた。肉片は橋の上に落ち、ねっとりとした触手がゆがみながら蠢いている。\n\nあなたが再び顔を上げると、男の姿は複雑な鋼の骨組みの奥に消え、跡形もなかった。"
  },
  Event_6954_Name = {
    Text = "奇妙な旅の伴Ⅵ"
  },
  Event_6955_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6955_Desc = {
    Text = "糸を引くように、段階的に進むのはあなたの得意技だ。\n\n直感の閃きで頭が冴え、現実を見通すことができる——\n誰が人形を操っていようと、逃げて生き延びる。"
  },
  Event_6955_Name = {
    Text = "インスピレーション"
  },
  Event_6956_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6956_Desc = {
    Text = "蝶があなたの手のひらで砕け散る。\n\nそれはまるでガラスの天井が突然砕けたように、欠片が重力に引かれて落ちていく、落ちていく、落ちていく——"
  },
  Event_6956_Name = {
    Text = "鉄道の幻覚"
  },
  Event_6957_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6957_Desc = {
    Text = "ラモンナが近づこうとしないのを見て、猫は頭を振り、影となってその場から消えた。"
  },
  Event_6957_Name = {
    Text = "彷徨う住人"
  },
  Event_6958_ChoiceDesc1 = {
    Text = "【約束をする】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6958_ChoiceDesc2 = {
    Text = "【拒否する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6958_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6958_Desc = {
    Text = "「それは本当に忘れられない記憶だ。\n私の頭と四肢は石膏に強く押し込まれたんだ。\n\n窒息と死に瀕する幻覚に、全身を包み込まれ——そして力強く引きずり出され、闇の海岸に投げ捨てられた。\n私はそれを見つめながら、自分の一部分が一緒に引き裂かれ、奪われたのを感じた。\n\n失われた魂の半分は、それ以来、あの小さくて最初に作られた蝋人形に宿っている。\nだから……私の半身を見つけてくれないか？」"
  },
  Event_6958_Name = {
    Text = "私の半身"
  },
  Event_6959_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ上位刻印を獲得する"
  },
  Event_6959_Desc = {
    Text = "あなたは記憶の傍観者であり、少女が光のない海に沈むのをただ見ているしかない。\n\n水流がドレスの裾を押し上げるが、彼女は沈んでいく、まるで開かない花のように。"
  },
  Event_6959_Name = {
    Text = "海に沈む"
  },
  Event_6960_ChoiceDesc1 = {
    Text = "【シルバーキーを差し込む】"
  },
  Event_6960_Desc = {
    Text = "飽和した融蝕液の中に何かが含まれているようだ…シルバーキーで観測してみよう。"
  },
  Event_6960_Name = {
    Text = "黒い水たまり"
  },
  Event_6961_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6961_Desc = {
    Text = "敵の誘惑に乗らないで、罠かもしれない。"
  },
  Event_6961_Name = {
    Text = "呪われた怪鳥"
  },
  Event_6962_ChoiceDesc1 = {
    Text = "【彼を助ける】"
  },
  Event_6962_ChoiceDesc2 = {
    Text = "【冷徹に傍観する】"
  },
  Event_6962_Desc = {
    Text = "少年は舞台に立つ。\n青白いライトが彼の顔を照らす。\n\n「ささ、捧げます……」\n少年は顔を赤らめた。\n口を開けたが、音が出ない。\n黒い口がどんどん大きく開いていく……"
  },
  Event_6962_Name = {
    Text = "終幕の儀Ⅲ"
  },
  Event_6963_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6963_Desc = {
    Text = "「憎い、憎い！」\n何かのスイッチが入ったように、黒猫が突然凶暴になり、あなたの腕に噛みつこうとする。\n\n幸いにも素早く避け、服の端だけが噛まれる。\n黒猫は街角に飛び込み、路地の下水道に消えた。"
  },
  Event_6963_Name = {
    Text = "夜の精霊"
  },
  Event_6964_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6964_Desc = {
    Text = "脳内で渦巻く泥水に押し流されるように、あなたは扉を押し開き、戻れない道へと足を踏み出す。\n\n扉の外の熾烈な白い光——\nそれは、救済か、それとも破滅か？"
  },
  Event_6964_Name = {
    Text = "重なる扉の外"
  },
  Event_6965_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6965_Desc = {
    Text = "あなたは思い切って前に出て確認する。\n\nすると、テーブルの上に覆いかぶさっていた粘液が突然裂け、その下のものが露わになった。"
  },
  Event_6965_Name = {
    Text = "重なる扉の外"
  },
  Event_6966_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6966_Desc = {
    Text = "唾を飲み込み、疑問を抑え、敵に集中する。\n\n蝶を体内に一時的に留めておく。\nたとえその羽ばたきが内臓を引き裂こうとも。"
  },
  Event_6966_Name = {
    Text = "バタフライ効果"
  },
  Event_6967_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_6967_Desc = {
    Text = "猫は満足そうにうなずき、すぐに影となって消え、いくつかの黒く丸い物体を残した。"
  },
  Event_6967_Name = {
    Text = "彷徨う住人"
  },
  Event_6968_ChoiceDesc1 = {
    Text = "【シルバーキーを差し込む】"
  },
  Event_6968_Desc = {
    Text = "飽和した融蝕液の中に何かが含まれているようだ…シルバーキーで観測してみよう。"
  },
  Event_6968_Name = {
    Text = "黒い水たまり"
  },
  Event_6969_ChoiceDesc1 = {
    Text = "【離れる】ランダムな高級遺物を1つ獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_6969_Desc = {
    Text = "あなたがまだ迷っていると、クムが土の山に飛び込み、前足で素早く何かを掘り出し、あなたの前に押し出した。"
  },
  Event_6969_Name = {
    Text = "埋もれた物"
  },
  Event_6970_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6970_Desc = {
    Text = "紙には「メイリム」と印字されていた。\nメイソンなど存在しなかった。\n\n過度に疑り深いのは良い兆候ではない、守秘者。"
  },
  Event_6970_Name = {
    Text = "タイプライター"
  },
  Event_6971_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_6971_Desc = {
    Text = "土の山には彫刻家協会の数々の罪が埋まっていた。"
  },
  Event_6971_Name = {
    Text = "埋もれた物"
  },
  Event_6972_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6972_Desc = {
    Text = "鳥たちには、彼らのルールがある。\n\nあなたの意志に従って行動するわけではないし、あなたも自然の法則に干渉することもできない。"
  },
  Event_6972_Name = {
    Text = "群れから離れたカラス"
  },
  Event_6973_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_6973_Desc = {
    Text = "なぜだろう、なぜ沈んだのだろう？\nあの日は雷雨も嵐もなかった。\n夜空は澄み渡り、一つの星もなく、満月が海面に低く垂れ下がり、冷たい太陽のようだった。"
  },
  Event_6973_Name = {
    Text = "海に沈む"
  },
  Event_6974_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6974_Desc = {
    Text = "「車掌！我々は恐怖の襲撃を受けた！\n……ザー……」\n運転手からの報告電話のようだ。\n\n「繰り返す、こちらはミサゴ外勤組第四小隊、北線夜行特急列車で救援人質を護送中に襲撃を……ああ！」\n\n電話の声がかすれた低い声に変わり、恐ろしい叫び声が混じる。\n\n「聖なる儀式は完了した。\n迷える子羊よ、この神聖な洗礼があなたの魂を浄化しますように……」"
  },
  Event_6974_Name = {
    Text = "列車からの電話"
  },
  Event_6975_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6975_Desc = {
    Text = "シルバーコアの収集も守秘者の仕事の一つ。\n\n銀白色の結晶内を漂う魂は、未来に新たな姿で世に戻るだろう。"
  },
  Event_6975_Name = {
    Text = "縛られた魂"
  },
  Event_6976_ChoiceDesc1 = {
    Text = "【墜落を続ける】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する。引き続き墜落しますか"
  },
  Event_6976_ChoiceDesc2 = {
    Text = "【手を引いて離れる】25黒章を獲得する"
  },
  Event_6976_Desc = {
    Text = "「あなた」があなたを招いている。\n螺旋の奥で、過去と未来の「あなた」が異なる次元からの「贈り物」を送ってきた。"
  },
  Event_6976_Name = {
    Text = "螺旋の深淵"
  },
  Event_6977_ChoiceDesc1 = {
    Text = "【腰をかがめて身を乗り出す】「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_6977_ChoiceDesc2 = {
    Text = "【確認を諦める】50黒章を獲得する"
  },
  Event_6977_Desc = {
    Text = "手術台の下にフィルムが挟まっているようだ。"
  },
  Event_6977_Name = {
    Text = "記憶の光影"
  },
  Event_6978_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6978_Desc = {
    Text = "干渉を拒否し、目の前に集中することにする。\nまだやるべきことがある。"
  },
  Event_6978_Name = {
    Text = "私の半身"
  },
  Event_6979_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6979_Desc = {
    Text = "失われた聖器、価値ある遺物、願いを叶える装置……\n宝物だけがこれほど魅力的なのかもしれない。"
  },
  Event_6979_Name = {
    Text = "謎の入力法"
  },
  Event_6980_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6980_Desc = {
    Text = "「あなたはリリーの『母親』なのに、彼女を研究と戦闘の道具としてしか扱っていない」\n\nあなたは答えた。\n「幼い子供は母親に従うかもしれないが、あなたはリリーの『母親』であるべきではない」"
  },
  Event_6980_Name = {
    Text = "彼女の選択"
  },
  Event_69813_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_69813_Desc = {
    Text = "シルバーキーが輝きを放ち、血の腕たちは何かの力に怯えたように血の池に隠れ、そして消えていった。"
  },
  Event_69813_Name = {Text = "血の池"},
  Event_69814_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_69814_Desc = {
    Text = "あなたはますます深くはまり込み、頭の中には至高の意志の混沌としたささやきが響き渡った。\n\n目を閉じ、自身の体内の権能を呼び起こす。\n\n突然、すべての音と異常な感触が消える。\nあなたは扉の向こうに立っており、血の腕は跡形もなく、最初から存在しなかったかのようだ。\n\n全身が爽快に感じる。代償を支払ったことは理解しているが、それは取るに足らないことだ。\n\nあなたはさらに強大な姿で、その至高の存在に立ち向かうだろう。"
  },
  Event_69814_Name = {Text = "血の池"},
  Event_69815_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_69815_Desc = {
    Text = "あなたの記憶により作り出された覚醒体はためらうことなくあなたを血の池から引きずり出した。\n\nあなたとつながっていた腕は引き裂かれ、濁った泥水が飛び散る。\n\n水の中では、肉眼では判別しがたい無数の生物がうごめいており、原初の創造主と破壊者が、貪り食うことを渇望していた。"
  },
  Event_69815_Name = {Text = "血の池"},
  Event_69816_ChoiceDesc1 = {
    Text = "【覚醒体を呼ぶ】すべての覚醒体の100狂気を消費し、症状カードを1枚削除する"
  },
  Event_69816_ChoiceDesc2 = {
    Text = "【血の池で浴びる】最大ライフをArg1増加させる、2枚の「(Skill.Arg2)」に感染する"
  },
  Event_69816_ChoiceDesc3 = {
    Text = "【シルバーキーを差し込む】すべてのキーエネルギーを空にする"
  },
  Event_69816_Desc = {
    Text = "命の権能、原初の眼には死の形で現れる。\n\nあなたがこの影の地に足を踏み入れると、生臭い血の池が瞬時にその正体を現した。\n\n赤黒い無数の血の腕が足首に絡みつき、深淵へ引きずり込もうと絶えず上へとのぼりつめる。"
  },
  Event_69816_Name = {Text = "血の池"},
  Event_6981_ChoiceDesc1 = {
    Text = "【鍵を拾う】"
  },
  Event_6981_Desc = {
    Text = "錆びた鍵束。\n\n扉の鍵を解放するために使用する。"
  },
  Event_6981_Name = {Text = "扉の鍵"},
  Event_6982_ChoiceDesc1 = {
    Text = "【離れる】指令カードを1枚複製することを選択し、「(Skill.Arg1)」に感染する"
  },
  Event_6982_Desc = {
    Text = "船歌とシレストの導きで、あなたは暗く光のない船室の奥を見つめた——あなたたちの命運は、その果てしない闇の中にあるのだろうか？"
  },
  Event_6983_ChoiceDesc1 = {
    Text = "【一緒に離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6983_ChoiceDesc2 = {
    Text = "【離れるのを拒否する】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6983_Desc = {
    Text = "これは幻覚だろうか？\nあなたは、空を旋回するカラスを見た。\nそれは懐かしいメロディを口ずさんでいる。\n\n「じゃあ、一緒に行こう、君と僕～\n夜の帳がちょうど降りた頃～\n瀕死の酔っ払いのように、大通りで倒れる～」"
  },
  Event_6983_Name = {
    Text = "カラスの群れの声"
  },
  Event_6984_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6984_Desc = {
    Text = "追跡の力でしばらく休憩所を探せないが、一時的な安らぎを得た。"
  },
  Event_6984_Name = {
    Text = "異常な連絡"
  },
  Event_6985_ChoiceDesc1 = {
    Text = "【螺旋に墜ちる】螺旋の尽頭を眺める"
  },
  Event_6985_ChoiceDesc2 = {
    Text = "【手を引いて離れる】25黒章を獲得する"
  },
  Event_6985_Desc = {
    Text = "舷窓の外にはもう海面が見えない。\n\nガラスに白い顔が映り、その瞳には「君自身」も映っている。\n\n現実と密境が重なり、交差し、最終的に重なり合った螺旋を形成にねじれる。"
  },
  Event_6985_Name = {
    Text = "螺旋の深淵"
  },
  Event_6986_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6986_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_6986_Name = {Text = "休憩所"},
  Event_6987_ChoiceDesc1 = {
    Text = "【肯定する】"
  },
  Event_6987_ChoiceDesc2 = {
    Text = "【否定する】"
  },
  Event_6987_ChoiceDesc3 = {
    Text = "【どちらとも言わない】"
  },
  Event_6987_Desc = {
    Text = "「お久しぶりです、皆さん」\n\n提灯教会の信者との戦いから逃れ、少しの休息を得たあなたたちは、あの長い髪の男が再び道端に現れ、微笑んで挨拶しているのに気づく。\n\nまるで先ほどの戦いなど、なかったかのように。\n\n「前回会った時と比べて、あなたからケルベロスの匂いがずいぶん強くなりましたね。\n\nこの間、きっと遠くまで行かれたのでしょう？」"
  },
  Event_6987_Name = {
    Text = "奇妙な旅の伴Ⅴ"
  },
  Event_6988_ChoiceDesc1 = {
    Text = "【彼に道を尋ねる】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6988_ChoiceDesc2 = {
    Text = "【その場を離れる】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_6988_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6988_Desc = {
    Text = "影は痩せこけた街灯の下に立っていた。\n「ちょっと火を貸してもらえませんか、先生」\nあなたは@2の習慣はないが、小さな「魔法」を使うのは厭わない。\nあなたの助けで、影は火のついた@2を、底の見えない黒い渦の中へと深く差し入れた。\nほどなくして、白い煙が立ち上るのが見えた。\n「ああ――」\n影は愉悦に満ちたため息をついた。"
  },
  Event_6988_Name = {
    Text = "街灯の下の影"
  },
  Event_6989_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_6989_Desc = {
    Text = "盤上のものは真実にあらず\n\n進む道を阻むのは壁ではなく、枯れた好奇心かもしれない。"
  },
  Event_6989_Name = {
    Text = "幻影空間"
  },
  Event_6990_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6990_Desc = {
    Text = "「痛い、痛いよ……サラ姉さん……」\n\nあなたはサラを見つめる。\n彼女は緊張して二人の子供を守っており、聞こえていないようだ。\n\n声は徐々に消えていく。"
  },
  Event_6990_Name = {
    Text = "「サラ姉さん」"
  },
  Event_6991_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_6991_Desc = {
    Text = "立ち上がって少年に拍手を送る。\nあなたの励ましを感じたのか、少年は小さな胸を張る。\n黒い血が口から溢れ続けるが、歌声は止まない。"
  },
  Event_6991_Name = {
    Text = "終幕の儀Ⅳ"
  },
  Event_6992_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6992_Desc = {
    Text = "一部の悲しみが蒸発しているが、涙は止まらず奇玦の過去へ流れ続ける。"
  },
  Event_6992_Name = {
    Text = "冥滩の涙"
  },
  Event_6993_ChoiceDesc1 = {
    Text = "【歌い手の喉を絞める】「(Skill.Arg1)」に感染し、呪われた遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_6993_ChoiceDesc2 = {
    Text = "【踊り手の足を引っかける】2枚の「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」「(RelicConfig.Arg3)」を獲得する"
  },
  Event_6993_ChoiceDesc3 = {
    Text = "【迂回して離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6993_Desc = {
    Text = "粘つく人影が3つ、道を塞いでいる。\n\n1つは歌を歌い、声はかすれ、歌詞は奇妙だ。\n\n1つは踊り、動きはぎこちなく、足取りは不安定だ。\n\n1つは詩を吟じ、韻律は壊れ、言葉は通じず、あなたは我慢できずに——"
  },
  Event_6993_Name = {
    Text = "狭路の悪党"
  },
  Event_6994_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_6994_Desc = {
    Text = "一部の怒りが沸騰しているが、涙は止まらず未知の過去へ流れ続ける。"
  },
  Event_6994_Name = {
    Text = "冥滩の涙"
  },
  Event_6995_ChoiceDesc1 = {
    Text = "【無視する】「(Skill.Arg1)」に感染する"
  },
  Event_6995_ChoiceDesc2 = {
    Text = "【背を向け離れる】ランダムに覚醒体を1体覚醒させる"
  },
  Event_6995_Desc = {
    Text = "残酷な運命が、歩く者の足元に這い寄る。\nその道は鏡のように滑らか。\n背後からは、かすかな破砕音が響いてくる。\n\n一体誰が足元の運命を踏み砕いたのか？\nそれは虚妄か罠か、あるいは夢語りか虚言か……\n\nあなたの前に、ゆっくりと這う亀裂が現れた。\n\n<Italic:それは覚醒した霊知を沈み込ませるかのようだ。>"
  },
  Event_6995_Name = {
    Text = "這う裂け目"
  },
  Event_6996_ChoiceDesc1 = {
    Text = "【試練を受ける】「(Skill.Arg1)」に感染し、成功すれば1つの高級遺物を獲得し、失敗すれば50黒章を獲得する"
  },
  Event_6996_ChoiceDesc2 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_6996_Desc = {
    Text = "あなたは足元の鏡のように反射する黒い液体から、いくつかの秘密を垣間見た。\n\nその反射の縁はぼやけ、周囲には消えない黒い気が漂っている。\n何かに見覚えがあるが、それが何なのかはっきりしない。"
  },
  Event_6996_Name = {
    Text = "鏡面の下"
  },
  Event_6997_ChoiceDesc1 = {
    Text = "【猫の鳴き真似をする】50%の確率で125黒章を獲得し、50%の確率で「(Skill.Arg2)」に感染する"
  },
  Event_6997_ChoiceDesc2 = {
    Text = "【餌をやる】75%の確率で100黒章を獲得し、25%の確率で「(Skill.Arg2)」に感染する"
  },
  Event_6997_ChoiceDesc3 = {
    Text = "【脱兎のごとく逃げる】50黒章を獲得する"
  },
  Event_6997_Desc = {
    Text = "あなたは黒猫の縄張りに迷い込んだ。\n\n無数の目が暗闇で突然開き、探るように、見定めるように、警戒しながら……ただし善意はない。\n\nエメラルドグリーン、琥珀色、ピーコックブルー……まるで輝く宝石の海にいるようだ。\n脱出するために、あなたは——"
  },
  Event_6997_Name = {Text = "猫の街"},
  Event_6998_ChoiceDesc1 = {
    Text = "【ダフォダイルについて】ランダムな指令カード2枚がそれぞれ刻印「(EnchantConfig.Arg1)」「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_6998_ChoiceDesc2 = {
    Text = "【地獄の番犬について】呪われた遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_6998_ChoiceDesc3 = {
    Text = "【リリーについて】「(Skill.Arg1)」に感染する"
  },
  Event_6998_Desc = {
    Text = "「こちらダフォダイルのヒントの時間です」"
  },
  Event_6998_Name = {
    Text = "ヒントの時間"
  },
  Event_6999_ChoiceDesc1 = {
    Text = "【針を放任する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6999_ChoiceDesc2 = {
    Text = "【針を押さえる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_6999_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_6999_Desc = {
    Text = "カチッ、カチャッ、カチ——\n運命の針が少しずつ動き、機械の音が冷たく響き、あなたが絶対に見たくない方向へと猛進していく。"
  },
  Event_6999_Name = {
    Text = "針の先を越えて"
  },
  Event_7000_ChoiceDesc1 = {
    Text = "【聞き入れない】山札からランダムに指令カードを3枚引き、1枚選択して削除し、75黒章を獲得する"
  },
  Event_7000_ChoiceDesc2 = {
    Text = "【慎重に調べる】山札からランダムに指令カードを3枚引き、1枚選択して未強化のコピーを山札に追加し、25黒章を獲得する"
  },
  Event_7000_ChoiceDesc3 = {
    Text = "【背を向けて離れる】50黒章を獲得する"
  },
  Event_7000_Desc = {
    Text = "残酷な運命が、歩く者の足元に這い寄る。\nその道は鏡のように滑らか。\n背後からは、かすかな破砕音が響いてくる。\n\n一体誰が足元の運命を踏み砕いたのか？\nそれは虚妄か罠か、あるいは夢語りか虚言か……\n\nあなたの前に、ゆっくりと這う亀裂が現れた。"
  },
  Event_7000_Name = {
    Text = "這う裂け目"
  },
  Event_7001_ChoiceDesc1 = {
    Text = "【カラスを呼ぶ】25黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7001_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_7001_Desc = {
    Text = "鋭い爪がマントを裂き、肩に深く食い込む。"
  },
  Event_7001_Name = {
    Text = "群れから離れたカラス"
  },
  Event_7002_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7002_Desc = {
    Text = "恐怖は時に実体から来るものではない。\n\n「地獄の番犬」が通った後には赤い液滴が残り、あなたの輪郭を映し出す。"
  },
  Event_7002_Name = {
    Text = "無形の影"
  },
  Event_7003_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7003_Desc = {
    Text = "微かな電流と共に、女性の囁きが聞こえる。\n\n彼女は泣きながら延々と自分境遇を語り続ける。\n\n一時間……一日……彼女が何故悲しんでいるのかを忘れてしまうほどの時が過ぎる。\n\n最後に彼女は嬉しそうに電話を切り、大きな贈り物を約束する。\n\nあなたはその贈り物を受け取った。\n\n何にせよ、贈り物はいつも嬉しいものだ。"
  },
  Event_7003_Name = {
    Text = "電話に出てください"
  },
  Event_7004_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7004_Desc = {
    Text = "仲間たちの不思議そうな視線の中、あなたは頭を下げて片膝をつき、右手を拳にして額に当てた。\n\nこれで顔を隠すのは完璧だ。"
  },
  Event_7004_Name = {
    Text = "見事な偽装"
  },
  Event_7005_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7005_Desc = {
    Text = "「私にヴェールをかけてくれたのですね」\n蝋人形は穏やかに微笑みながら語る。\n\n「私は真実をあなたに捧げます。あなたの勤勉な働きへの報酬として」\n\n彼女の腹部から黒い粘液がとめどなく流れ出し、あなたの身体をしっかりと包み込む。\n世界は闇に沈みながらも、驚くほど温かかった。\n\nあなたは身を丸めて大きなあくびをひとつ。\nそうして、@1度目の夢の中へ……"
  },
  Event_7005_Name = {
    Text = "未完成の蝋人形"
  },
  Event_7006_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_7006_Desc = {
    Text = "霧の中で何も得られなかった"
  },
  Event_7006_Name = {
    Text = "混沌の霧"
  },
  Event_7007_ChoiceDesc1 = {
    Text = "【電話に出る】3つの中から1つ上位刻印を獲得する"
  },
  Event_7007_ChoiceDesc2 = {
    Text = "【呼び出し音を無視】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7007_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7007_Desc = {
    Text = "「リンリンリン……」\n隅から耳障りな電話のベルが鳴り響く。\n\n急かすような音が次第に大きくなる。\n\nまるで、今すぐ出なければ爆発して、世界を破壊するかのような錯覚を覚える。"
  },
  Event_7007_Name = {
    Text = "電話に出てください"
  },
  Event_7008_ChoiceDesc1 = {
    Text = "【幻影に近づく】3つの中から1つ低級遺物を獲得する"
  },
  Event_7008_ChoiceDesc2 = {
    Text = "【幻影を打ち払う】低級遺物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」を獲得し、2枚の「(Skill.Arg3)」に感染する"
  },
  Event_7008_Desc = {
    Text = "密境の蜃気楼か、それとも消えない記憶か？\n目をこすり、遠くの幻影が近づく——賑わう市場、融蝕で消えた蝋人形館、吹雪の小町の精神病院、風景がぼやけたアクートか？"
  },
  Event_7008_Name = {Text = "蜃気楼"},
  Event_7009_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7009_Desc = {
    Text = "熱湯で焼かれたように、反射的に耳を塞ぎ、その毒々しい音楽を遮断した。"
  },
  Event_7009_Name = {
    Text = "禁忌の音色"
  },
  Event_7010_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7010_Desc = {
    Text = "明るいメロディーが緊張と恐怖を吹き飛ばし、あなたは喜びに満ち、大股でラモンナを後ろに置き去りにする——「守秘者！？そんなに速く行かないで！」"
  },
  Event_7010_Name = {
    Text = "無体の音"
  },
  Event_7011_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7011_Desc = {
    Text = "「踊りを止めろ！！！融蝕の怪物の方がまだマシな踊りをするぞ！」\n\n観客を解放してくれ……\n心の中で祈る。"
  },
  Event_7011_Name = {
    Text = "狭路の悪党"
  },
  Event_7012_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7012_Desc = {
    Text = "これはただの密境だ。\n\n君が守りたい、逃げたいのは唯一無二の現実だ。"
  },
  Event_7012_Name = {
    Text = "螺旋の深淵"
  },
  Event_7013_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7013_Desc = {
    Text = "「憎々しいやつめ」\n\nあなたは原稿を引き裂き、風に舞わせ、花びらのように散らす。\n\n詩人は文字が風に舞うのを見上げ、口元に陶酔の笑みを浮かべる。\n\n「なんて美しい……」"
  },
  Event_7013_Name = {
    Text = "狭路の悪党"
  },
  Event_7014_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7014_Desc = {
    Text = "ポスターを丸ごと剥がすと、裏面には蝋人形館の支出が雑に記録されているのを発見した。\n筆跡の主は明らかに算数に弱く、帳簿はどうにも帳尻が合わない。\n\nざっと見たところ、最大の支出は「蝋人形の保護と清掃」だ。\n従業員の支出はわずかで、最近の出費は「馬のたてがみの鞭」12本で、価格は約20スタール。\n\nもう一つの特別な支出項目——「彼らの食べ物」。\n「彼ら」とは誰のことだ？"
  },
  Event_7014_Name = {
    Text = "暗闇の中の笑い声"
  },
  Event_7015_ChoiceDesc1 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7015_Desc = {
    Text = "「狡猾……だが正しい答えだ」\n声の主はこの答えに興味を示し、銀色の物体が水面から投げ出された。\n\n「覚えておけ、すべてには代償がある」"
  },
  Event_7015_Name = {
    Text = "界外の音"
  },
  Event_7016_ChoiceDesc1 = {
    Text = "【第二の蝶を掴む】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_7016_ChoiceDesc2 = {
    Text = "【もう引き返さない】"
  },
  Event_7016_Desc = {
    Text = "彼らは精神次元の住人なのか？\nそれとも融蝕から生まれた生命か。\n\n疑問を抱きながら、蝶の嵐に足を踏み入れる。"
  },
  Event_7016_Name = {
    Text = "霊知の嵐"
  },
  Event_7017_ChoiceDesc1 = {
    Text = "【第三の蝶を観察する】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_7017_ChoiceDesc2 = {
    Text = "【もう引き返さない】"
  },
  Event_7017_Desc = {
    Text = "指先の痛みに耐えきれず、思わず手を放した。"
  },
  Event_7017_Name = {
    Text = "霊知の嵐"
  },
  Event_7018_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7018_Desc = {
    Text = "「お前たち人間には他に答えがないのか？」\n声の主が苛立ちの低い唸りを上げ、空間全体が震えた。\n\n「貪欲で無知……それが私がお前たちを嫌う理由だ」"
  },
  Event_7018_Name = {
    Text = "界外の音"
  },
  Event_7019_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7019_Desc = {
    Text = "「心配しないで、ただ欲張りな客にちょっとした罰を与えただけさ。\n仕方ないね、僕はビールが好きじゃないから～」"
  },
  Event_7019_Name = {
    Text = "記憶の破片・ビール"
  },
  Event_7020_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7020_Desc = {
    Text = "「もう歌わないで——」\n\n音痴の歌手に警告する。耳が腐ってしまう。"
  },
  Event_7020_Name = {
    Text = "狭路の悪党"
  },
  Event_7021_ChoiceDesc1 = {
    Text = "【離れる】覚醒体を2体選択して覚醒させる"
  },
  Event_7021_Desc = {
    Text = "あなたはきびすを返してそこから離れたが、長い廊下で迷子になる。\n\n終わりのない回廊に、あなたは忍耐力をほぼ使い切るが、ついに小さな古びた舞台を見つける。\n\nあなたが瞬きをすると、舞台は消えてしまった。"
  },
  Event_7021_Name = {
    Text = "終幕の儀Ⅱ"
  },
  Event_7022_ChoiceDesc1 = {
    Text = "【酒杯を拾い上げる】特殊カードを獲得する"
  },
  Event_7022_Desc = {
    Text = "夕陽の残光のように澄んだ、秋の麦浪のように揺れる金色の液体が、蜂蜜のように甘く魅惑的な香りを放っている。それは何でできているのか？誰がここに置いたのか？なぜ誰も見ていないのか？\nこれらの疑問が解決される前に、神秘的な考えがあなたの頭に浮かぶ：今すぐ、直ちに飲まなければならない。\nその瞬間、あなたは炎に魅了された蛾、ウツボカズラに捕らえられた虫のように、抑えきれずにその甘酒を手に取る——"
  },
  Event_7022_Name = {Text = "蜂蜜酒"},
  Event_7023_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7023_Desc = {
    Text = "この扉を調べようとしたが、触れた瞬間に扉が消え、遠くで何かが開く音が聞こえた。"
  },
  Event_7023_Name = {
    Text = "奇妙な扉"
  },
  Event_7024_ChoiceDesc1 = {
    Text = "【処理しない】"
  },
  Event_7024_ChoiceDesc2 = {
    Text = "【掌の痕を払う】"
  },
  Event_7024_Desc = {
    Text = "フランシスのオフィスは冷たく整然としており、主人の几帳面さを示している。\n\n隅の箱の上で、5インチ四方の灰の拓印を見つけた。\n\n掌印の形は奇妙で、外側の輪郭は獣の足跡のようで、中には小さな人間の少女の手形が埋め込まれている。\nまるで人間の手形が先に残され、その上に獣の巨大な掌が覆ったようだ。\n\nもちろん、温かい光景を想像することもできる。\n例えば、従順な獣が少女の手の甲に優しく爪を重ねるような。\n\nしかし、あなたは真実を知っている——それは残酷な実験で融合された怪物が残した痕跡だ。"
  },
  Event_7024_Name = {
    Text = "巨獣の足跡"
  },
  Event_7025_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7025_Desc = {
    Text = "さまよう実験体に疲れ果て、短い休息も乾いた砂漠の恵みのように感じる。"
  },
  Event_7025_Name = {
    Text = "無限の扉"
  },
  Event_7026_ChoiceDesc1 = {
    Text = "【主人】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7026_ChoiceDesc2 = {
    Text = "【それを持ち去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_7026_ChoiceDesc3 = {
    Text = "【それを分解する】50黒章を獲得する"
  },
  Event_7026_Desc = {
    Text = "あなたは前に進んでいて、足元で何かを蹴った。\n\nそれは羅針盤で、ガラスカバーは壊れており、残りの部分も融蝕液で覆われている。\nあなたは注意深くそれをひっくり返し、背面に刻まれたミサゴ大学の校章をかすかに見た。"
  },
  Event_7026_Name = {
    Text = "彼女の選択"
  },
  Event_7027_ChoiceDesc1 = {
    Text = "【書簡を読む】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_7027_ChoiceDesc2 = {
    Text = "【鞄をしっかり閉める】"
  },
  Event_7027_Desc = {
    Text = "一通、また一通。\n\n手紙にはあなたの過去が綴られている。\nそして、未来が描かれている。\n\n奇妙な誘惑に駆られ、あなたは手紙を引き裂き、むさぼり食べるのを止められなかった。\n\n「ねぇ？また、どうしちゃったのよ？\n空気を飲みこんでるの？」\n\nマーフィーに蹴られて、幻覚から覚める。\n我に返ると、目の前には何もなかった。"
  },
  Event_7027_Name = {
    Text = "予期せぬ手紙"
  },
  Event_7028_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_7028_Desc = {
    Text = "あなたの声を聞いて、人影は立ち止まり、クレメンタインの声が水霧を突き抜けてやってきた。\n「あなたなのね、」彼女の声はぼんやりとかすんで、水に溶けた月明かりのようだった、「心配しないで、あなたは大丈夫よ、彼はそう思っているけど、彼にはできない。」\n「ここが終わったら、また会いましょう。」"
  },
  Event_7028_Name = {
    Text = "霧の中の影"
  },
  Event_7029_ChoiceDesc1 = {
    Text = "【宛先：教務室】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7029_ChoiceDesc2 = {
    Text = "【宛先：相棒】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7029_Desc = {
    Text = "受取人を書いた瞬間、手紙から煙が立ち上る。\n見えない手が虚空を越えて、あなたの手から手紙を強引に奪い去った——\n咀嚼音のような音と共に、体が急に重くなった。\n\nしかし、手にした遺物が今回の旅が無駄ではなかったことを教えてくれる。"
  },
  Event_7029_Name = {
    Text = "一方的な訴え"
  },
  Event_7030_ChoiceDesc1 = {
    Text = "【シルバーキーを差し込む】"
  },
  Event_7030_Desc = {
    Text = "飽和した融蝕液の中に何かが含まれているようだ…シルバーキーで観測してみよう。"
  },
  Event_7030_Name = {
    Text = "黒い水たまり"
  },
  Event_7031_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7031_Desc = {
    Text = "彼らが影から現れるのを待とう。"
  },
  Event_7031_Name = {
    Text = "提灯の黒いカラス"
  },
  Event_7032_ChoiceDesc1 = {
    Text = "【カラスを呼ぶ】35黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7032_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_7032_Desc = {
    Text = "漆黒の鳥たちはあなたに呼び寄せられる。\nそして身体を膨らませ、何かを手に吐き出した。\n\n彼らは羽ばたいてマストの上に戻ると、じっと、燃えるような眼差しであなたを見つめる。"
  },
  Event_7032_Name = {
    Text = "群れから離れたカラス"
  },
  Event_7033_ChoiceDesc1 = {
    Text = "【洞窟に入る】"
  },
  Event_7033_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7033_Desc = {
    Text = "「ゴホッ、ゴホゴホ……」\n聞き覚えのある声……思い出したチュ！\n人間が病気や死にかけているときに出す声だ！\n急いで見に行くチュ！"
  },
  Event_7033_Name = {
    Text = "洞窟の奥"
  },
  Event_7034_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7034_Desc = {
    Text = "あなたはシルバーコアの品質を鑑定する知識も学んでいた。\n\n明らかに、これらのシルバーコアは精錬の基準を満たしておらず、そこに囚われたかもしれない魂のかけらは諦めざるを得ない。\n\n捨てることを学ぶのも守秘者の必修科目だ。"
  },
  Event_7034_Name = {
    Text = "縛られた魂"
  },
  Event_7035_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7035_Desc = {
    Text = "これは一方通行で、入口に戻ることはできない。"
  },
  Event_7035_Name = {Text = "通路"},
  Event_7036_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7036_Desc = {
    Text = "早く終わらせて、安心しよう。\nミサゴの調査員は危険を恐れない。"
  },
  Event_7036_Name = {
    Text = "無限の扉"
  },
  Event_7037_ChoiceDesc1 = {
    Text = "【すみません、急用なので通してください】"
  },
  Event_7037_ChoiceDesc2 = {
    Text = "【詳しく聞かせてください】"
  },
  Event_7037_Desc = {
    Text = "「そちらの学生さん、少しお待ちください。\n皆さん顔色が険しく、お急ぎに見えます。\nおそらく何か困難に陥っているのでしょう。\n\nしかし、目の前の問題にとらわれ、全体的な視野や冷静さを失うのは危険ですよ。\n\n例えば、私はここ数日真剣に考えていたのですがケルベロスの伝説には現在の状況と、一致しない点がたくさんあるんです」"
  },
  Event_7037_Name = {
    Text = "奇妙な旅の伴Ⅱ"
  },
  Event_7038_ChoiceDesc1 = {
    Text = "【贈り物を受け取る】"
  },
  Event_7038_ChoiceDesc2 = {
    Text = "【丁寧に断る】"
  },
  Event_7038_Desc = {
    Text = "少年は窓辺に座り、あなたを見つめている。\n彼はずっとあなたを待っていたのだ。\n\n「舞台は大成功だった。あ、ありがとう」\n「もう行かなくちゃ……これは君への贈り物」\n少年は手を差し出す。\n\n美しく包装されたプレゼントが差し出される。\n中から血が溢れ出し、少年の手を真っ赤に染めていった。"
  },
  Event_7038_Name = {
    Text = "終幕の儀Ⅵ"
  },
  Event_7039_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7039_Desc = {
    Text = "いつまでもその自信を持ち続けられますように。"
  },
  Event_7039_Name = {
    Text = "無形の影"
  },
  Event_7040_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7040_Desc = {
    Text = "あなたはこの小さく柔らかい耳を受け取った。\n\nそれは粘り気のある油蝋に包まれ、静かにあなたの手のひらの中央に横たわる。\n\nあなたの心の奥底に強い責任感が湧き上がる。\n\nまず、バーには気軽に行ってはいけない。\nあそこの音楽はあまりにも騒がしい。\n\n次に、ウェリントンガーデン劇場にも行けない。\nあそこはオーケストラの演奏がすでに古くさい。\n\nそして……\nあなたと仲間たちは、この小さなペットが増えたことをうまく受け入れた。"
  },
  Event_7040_Name = {
    Text = "耳を傾ける"
  },
  Event_7041_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7041_Desc = {
    Text = "「アリステア教授はミサゴの礎だ。\n彼がいなくなれば、ミサゴのすべてのシステムは機能停止するだろう」\n\nあなたは、ある眠気を誘う授業で、ハレトが顔を引き締めて、黒板を叩きながらこの言葉を言ったのをぼんやりと思い出した。\n\nもしこの礎が砕け散ってしまったら、あなたは一体どうすればいいのだろう？\n巨大な恐怖があなたを覆い尽くした。\n\n「どこに行くの？」\nラモンナの呼び声があなたを現実に引き戻す。\n\nそれは過去なのか未来なのか、現実なのか想像なのか、あるいは別の次元の幻だったのか？\nあなたにもわからなかった。\n\nただあなたの手には「贈り物」が握られていた。"
  },
  Event_7041_Name = {
    Text = "混沌の哀号"
  },
  Event_7042_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7042_Desc = {
    Text = "「この車椅子が私の第二の足だ。一生これから離れられないだろう」\n\nアリステア教授は苦笑しながら言った。\n「残念ながら、これでずいぶん背が低くなってしまった」\n\nだから、これは本物のアリステア教授ではありえない。"
  },
  Event_7042_Name = {
    Text = "混沌の哀号"
  },
  Event_7043_ChoiceDesc1 = {
    Text = "【誰が話しているのか？】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7043_ChoiceDesc2 = {
    Text = "【ウィスキーとは何だ、私にも味わわせろ】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7043_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7043_Desc = {
    Text = "「本当に一口も飲まないの？\nこれは最高のウイスキーだよ。\nあのバーの店主が気前よく一本くれなかったら、君に分けるなんて考えられないね」\n\n「つまり、君はあの痩せこけた、ゴムのように肌が張り詰めた、ブラッディ・マリーしか飲まない奴を追い払ったんだ。\nそれが店主からの報酬全部。\n調査に一ヶ月かけて、三十軒訪ねて、十一回も門前払いされて、リボルバーの弾を十七発使った。\n一瓶のウイスキーじゃ元は取れないよ」\n\n「まあまあ、そんなに気にしないで。\n少なくとも、今はこのウイスキーがあるじゃないか？」"
  },
  Event_7043_Name = {
    Text = "記憶の断片・ウイスキー"
  },
  Event_7044_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7044_Desc = {
    Text = "あなたは覚醒体の触肢を引き止めた。\n彼は振り返り、曖昧な光を目に宿してあなたを見た。\n\n彼は何も言わなかったが、あなたは彼の心の声を読み取った——\n「越権だ」"
  },
  Event_7044_Name = {
    Text = "バタフライ効果"
  },
  Event_7045_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7045_Desc = {
    Text = "電報機は完全に壊れている。\n嵐の中で電報機の持ち主が感じた絶望を想像できる……今のあなたと同じだ。"
  },
  Event_7045_Name = {
    Text = "先人の遺物"
  },
  Event_7046_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7046_Desc = {
    Text = "名前：レーア\n年齢：20歳\n合併症：血液渇望症、重度のヒステリー\n付属物：深紅の触手@2口器\n移植物：直系血縁者の器官組織@3\n移譲理由：特に理由はない。彼女が嫌いだった。\n（後の内容は消されている）"
  },
  Event_7046_Name = {
    Text = "臓器登録"
  },
  Event_7047_ChoiceDesc1 = {
    Text = "【「祝福を受け入れる」を選択する】すべての黒章を失う。高級遺物を1つ獲得する"
  },
  Event_7047_Desc = {
    Text = "黒い泥が目の前に現れ、震えながら書類を差し出してきた。\n\n「今は表に出られないけど……私たちのカスタムサービスを見てみて……」\n女性の声が黒い泥の中から慌てた様子で聞こえ、何かを避けているようだ。\n\n「妖精の祝福は会員ランクに応じて効果を発揮し、誰にも公平です」\n「サインして、早くサイン！」"
  },
  Event_7047_Name = {
    Text = "妖精の祝福"
  },
  Event_7048_ChoiceDesc1 = {
    Text = "【耳を澄ます】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7048_ChoiceDesc2 = {
    Text = "【前に出て確認する】すべての覚醒体が50狂気を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7048_ChoiceDesc3 = {
    Text = "【直接離れる】3つの中から1つ刻印を獲得する"
  },
  Event_7048_Desc = {
    Text = "「ねぇ、知ってる？」\nラモンナが謎の人物を探していると、突然声が聞こえた。まるで誰かがひそひそ話しているように。\n\n「あのこと、知ってる？あの大事件のこと」"
  },
  Event_7048_Name = {Text = "噂話"},
  Event_7049_ChoiceDesc1 = {
    Text = "【集中】症状カードを最大2枚削除する"
  },
  Event_7049_ChoiceDesc2 = {
    Text = "【瞑想】覚醒体を1体選択して覚醒させる"
  },
  Event_7049_ChoiceDesc3 = {
    Text = "【休憩】Arg2ライフを回復する"
  },
  Event_7049_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n\n通信機から誰かが呼んでいる。"
  },
  Event_7049_Name = {Text = "休憩所"},
  Event_7050_ChoiceDesc1 = {
    Text = "【慎重に対応する】最大ライフをArg1増加させる"
  },
  Event_7050_ChoiceDesc2 = {
    Text = "【前へ進み出る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7050_Desc = {
    Text = "密境が生み出した影があなたに手を差し伸べる。\n\nあなたは記憶していた……かつてミサゴの調査員がこの船に乗ったことを。\n\nそれが彼だろうか？\n\nそれとも、密境に囚われた哀れな記憶の一つに過ぎないのか。"
  },
  Event_7050_Name = {
    Text = "シルバーキーの使い手"
  },
  Event_7051_ChoiceDesc1 = {
    Text = "【離れる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7051_Desc = {
    Text = "「ほら、私の雑談で、一番緊急の状況を見落としてしまいました。それはよくない。\n\n失礼、これ以上遅れると、あなたたちの獲物は逃げてしまいますね。\n\nお詫びの印として、この品を差し上げます」\n\n男性は勝手に話題を変え、何かを差し出した。"
  },
  Event_7051_Name = {
    Text = "奇妙な旅の伴Ⅱ"
  },
  Event_7052_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7052_Desc = {
    Text = "「願いが叶うといいですね」\n\nその男性は気にせず、体をずらして道を開けた。"
  },
  Event_7052_Name = {
    Text = "奇妙な旅の伴Ⅱ"
  },
  Event_7053_ChoiceDesc1 = {
    Text = "【ポケットに入れる】"
  },
  Event_7053_Desc = {
    Text = "水銀に近い物質。\n\n融蝕液から抽出され、主に儀式で覚醒体を召喚するために使用される。"
  },
  Event_7053_Name = {
    Text = "シルバーコア"
  },
  Event_7054_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7054_Desc = {
    Text = "また新たな分かれ道に入った。\n\n太陽はいつも通り昇り、\n人はいつも通り死に、\nあなたはいつも通り迷う。\n\n新しいものは何もない。"
  },
  Event_7054_Name = {
    Text = "眼の迷宮"
  },
  Event_7055_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7055_Desc = {
    Text = "それは光の屈折で歪んだ影のようだ。"
  },
  Event_7055_Name = {
    Text = "樽の中の浮遊物"
  },
  Event_7056_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7056_Desc = {
    Text = "振り返ると、そこには革靴が一足だけ。\n「ごめんなさい、悪意はありません」\n「もし私の体を見かけたら、1号展示室の45番ケースで待っていると伝えてください」\n「——牛革の方です。山羊革ではありません」"
  },
  Event_7056_Name = {Text = "革靴"},
  Event_7057_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7057_Desc = {
    Text = "きっとミサゴの同門の徒だ——あなたは彼に向かって両腕を広げたが、次に来たのは骨まで響く痛みだった。\n\nしかし、その痛みが消えた後、四肢はかつてないほど力強くなった。"
  },
  Event_7057_Name = {
    Text = "シルバーキーの使い手"
  },
  Event_7058_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7058_Desc = {
    Text = "目の前の霧が薄れたように感じる\n\n次の行動で視界が良くなった気がする"
  },
  Event_7058_Name = {
    Text = "修羅の試練"
  },
  Event_7059_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7059_Desc = {
    Text = "幻影が近づき、記憶が急に戻り、視界がクリアになる。"
  },
  Event_7059_Name = {Text = "蜃気楼"},
  Event_7060_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7060_Desc = {
    Text = "彼の神の無意識の心は暗闇の中でまだ何かを変え続けていた。"
  },
  Event_7060_Name = {
    Text = "彼の神の視線"
  },
  Event_7061_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7061_Desc = {
    Text = "危機が迫る今は、シルバーコアを集める時ではない。"
  },
  Event_7061_Name = {
    Text = "存在の証明"
  },
  Event_7062_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ低級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7062_Desc = {
    Text = "ぼんやりとした人影が徐々に鮮明になる。\nそれは融蝕生物でも災厄でもなく、翼も持たず、普通の表情をしたクレメンタインだった。\n\n「奇遇ね。あなたも月光を楽しみに来たの？」\n彼女は微笑みながらそう言ったが、あなたは突然の眩暈を感じる。\n\n「霧深い夜だから、気をつけないとね」\n「ここの小さな者は、あまり大人しくないから」"
  },
  Event_7062_Name = {
    Text = "霧の中の影"
  },
  Event_7063_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7063_Desc = {
    Text = "石膏の破片が地面に投げられ砕ける音と共に、彼女の体も砕け散る。\n不満の叫びがあなたの頭の中を満たすが、幸いにも、あなたは間一髪で踏みとどまった。"
  },
  Event_7063_Name = {
    Text = "残躯を補完する"
  },
  Event_7064_ChoiceDesc1 = {
    Text = "【悲しみに耳を傾ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7064_ChoiceDesc2 = {
    Text = "【喜びを聴く】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_7064_ChoiceDesc3 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_7064_Desc = {
    Text = "悠然、叙情、歓喜、哀愁……メロディーが密境に響き渡り、出所が分からない。\n\n幽霊船の音響から流れるソナタか、それとも密境に囚われた夜の狂想曲か？"
  },
  Event_7064_Name = {
    Text = "無体の音"
  },
  Event_7065_ChoiceDesc1 = {
    Text = "【彼らは誰かを探している】指令カードを1枚削除し、25黒章を獲得する"
  },
  Event_7065_ChoiceDesc2 = {
    Text = "【彼らは何かを探している】山札にあるカードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_7065_Desc = {
    Text = "提灯教会の信者がなぜ突然ライの町に？謎が多すぎる。\n\n地獄の番犬ケルベロス、ライ精神病院の院長フランシス、彫刻家協会、提灯教会……\n何かが彼らをこの小さな町に集めているに違いない。\n\nタイプライターが突然インクを噴き出し、何かを入力するよう促す。"
  },
  Event_7065_Name = {
    Text = "謎の入力法"
  },
  Event_7066_ChoiceDesc1 = {
    Text = "【目を固く閉じる】"
  },
  Event_7066_ChoiceDesc2 = {
    Text = "【その場から逃げる】"
  },
  Event_7066_Desc = {
    Text = "舞台の公演が突然止まる。\n\n周りを見渡すと、観客でいっぱいだった。\n彼らは少年と同じ顔をしており、それらは皆、\nあなたを見ていた。\n\nああ——\n彼らは無言で黒い口を開けている。"
  },
  Event_7066_Name = {
    Text = "終幕の儀Ⅴ"
  },
  Event_7067_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7067_ChoiceDesc2 = {
    Text = "【フィルムを検査する】「(Skill.Arg1)」に感染する。選択肢1で獲得した刻印を変更。あと1回使用できる"
  },
  Event_7067_Desc = {
    Text = "あなたはフィルムを赤い光の下に置き、半透明のフィルムベースからぼんやりと映像が浮かび上がる。\n\n手、足、眼球、内臓……想像できる、できないすべての人体器官が忠実にフィルムに記録されている。\n\nそれらは丁寧に洗浄され、配置され、まるであなたが書いた最初の詩のように整然としている。"
  },
  Event_7067_Name = {
    Text = "正確な記録"
  },
  Event_7068_ChoiceDesc1 = {
    Text = "【姫君の従者】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_7068_ChoiceDesc2 = {
    Text = "【考える人】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7068_Desc = {
    Text = "「タッ、タッ、タッ……」\n足音が遠くから近づく。\n誰かがアトリエのドアを開けようとしている。\n\n逃げ場がない。\n薄暗い光の中だ……蝋人形のふりをして、視線を避けることにする。"
  },
  Event_7068_Name = {
    Text = "見事な偽装"
  },
  Event_7069_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7069_Desc = {
    Text = "「やった、やった！」\n声は喜びに満ちている。\n「ついに私と同じになったね、サラ姉さん！」"
  },
  Event_7069_Name = {
    Text = "「サラ姉さん」"
  },
  Event_7070_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7070_Desc = {
    Text = "誰かが彼らをここに導いたのかもしれない。\n\n探索を進めるうちに、その人物の正体が明らかになるだろう。"
  },
  Event_7070_Name = {
    Text = "謎の入力法"
  },
  Event_7071_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7071_Desc = {
    Text = "早く終わらせて安心したい。\nミサゴの調査員は危険を恐れない。"
  },
  Event_7071_Name = {
    Text = "無限の扉"
  },
  Event_7072_ChoiceDesc1 = {
    Text = "【道徳を選ぶ】Arg1ライフを回復する"
  },
  Event_7072_ChoiceDesc2 = {
    Text = "【生命を選ぶ】全ライフを回復し、「(Skill.Arg2)」に感染する"
  },
  Event_7072_Desc = {
    Text = "かつてあなたは金色の心を持っていたかもしれない。\n\nそれは昼夜を問わず鼓動し、あなたの命と生活のために全力を尽くしていた……温かく、熱烈で希望に満ちていた。\n\nしかし、いつの間にか、その速度は徐々に遅くなっていった。\nまるで命と道徳、そのどちらかしか耐えられないかのように……"
  },
  Event_7072_Name = {
    Text = "呪われた欲望"
  },
  Event_7073_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7073_ChoiceDesc2 = {
    Text = "【フィルムを検査する】「(Skill.Arg1)」に感染する。選択肢1で獲得した刻印を変更。2回使用できる"
  },
  Event_7073_Desc = {
    Text = "「だから、あなたはすべてを正直に記録したのですね」\n\n「はい、フィルムには真実が映っています」\n\n会話が突然止まり、無数の視線があなたに向けられ、最後の判断を待っているようだ。"
  },
  Event_7073_Name = {
    Text = "目撃証言"
  },
  Event_7074_ChoiceDesc1 = {
    Text = "【離れる】最大ライフをArg1増加させ、さらに25黒章を獲得する"
  },
  Event_7074_Desc = {
    Text = "あなたの呼びかけは風の轟音にかき消された。\n\n「あなたは私を知る必要はない」\n言葉に混じるシューシュー音が、ますます鮮明に聞こえる。\n\n「ハーバート、ハーバートこそが、あなたたちの探す人物。あいつを墜とせ、偽りの幻想から、厳しく冷たい現実へと」\n\n「私はあなたたちに祝福を与えましょう、この世で最も美味なるものを……」"
  },
  Event_7074_Name = {
    Text = "奇妙な旅の伴Ⅵ"
  },
  Event_7075_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7075_Desc = {
    Text = "「ええ、哀れな迷える者、力を持ちながらも己を見失った者。\n\nあなたは手を差し伸べますか？\nそれとも彼女に武器を向けますか？」\n\n男は勢いよく激流に飛び込んだ。\nその刹那、あなたと彼の視線がぴたりと交わる。\n\nそこにあったのは、滴る蜂蜜のような黄金色の、蛇の縦長の瞳だった。\n\n彼が立っていた場所には、小さな紫色の煙を放つ灯りが残されていた。"
  },
  Event_7075_Name = {
    Text = "奇妙な旅の伴Ⅵ"
  },
  Event_7076_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7076_Desc = {
    Text = "「慎重さは美徳だが、過度な慎重は時代遅れだ、」\n変わらぬ穏やかな声に不満が含まれる。\n\n「星辰の運行は覚醒体の真貌を妨げるが、適切な時期には彼らの狂気が風船のように膨らむ。\n\nとにかく、今ならまだ彗星の尾を掴める。\n次は亀のような反応速度を改善しろ」"
  },
  Event_7077_ChoiceDesc1 = {
    Text = "【回復】現在の心労値が半分減少する"
  },
  Event_7077_Desc = {
    Text = "安全地帯で、現在の心労値を回復できる"
  },
  Event_7077_Name = {
    Text = "安全地帯"
  },
  Event_7078_ChoiceDesc1 = {
    Text = "【彼女を慰める】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_7078_ChoiceDesc2 = {
    Text = "【彼女を非難する】ランダムな指令カード3枚が刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7078_Desc = {
    Text = "「私は死んだ調査員の影、犯人はあの銀色の鍵」\n女性は苦しそうに頭を抱える。\n\n彼女の髪は濃く、その上には無数の輝く目が瞬いている……\n\n「彼らはいつも言うの——\nダメだ、シャーロット！ああ、シャーロット！\nだから私は思ったの、もし多くの覚醒体と一度にリンクできたら、みんな黙るだろうって」\n\n「それから……何が起こったのか分からない。\n目覚めたらこの姿になっていた。ああ！」"
  },
  Event_7078_Name = {
    Text = "調査員の影"
  },
  Event_7079_ChoiceDesc1 = {
    Text = "【高壁を乗り越える】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7079_ChoiceDesc2 = {
    Text = "【迷宮に入る】ランダムなカード1枚に刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_7079_Desc = {
    Text = "あなたの脳は一つの迷宮だ。\nあまりにも多くの思念がその中に絡み合い、出口は眼差しの届く場所にあるのに、思考の高い壁があなたたちの間に立ち並んでいる。"
  },
  Event_7079_Name = {
    Text = "思考の迷宮"
  },
  Event_7080_ChoiceDesc1 = {
    Text = "【幻影を遠くから見る】3つの中から1つ低級遺物を獲得する"
  },
  Event_7080_ChoiceDesc2 = {
    Text = "【幻影に近づく】低級遺物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」を獲得し、2枚の「(Skill.Arg3)」に感染する"
  },
  Event_7080_Desc = {
    Text = "遠くで火山が噴火しているように見え、暴風が吹き荒れる空に人型の煙が立ち上る。\n\nここはアイズルワースだ。\nアイズルワースには連なる高い雪山と石灰岩の洞窟しかない。\n\n連日の異変で気が狂ったのか？"
  },
  Event_7080_Name = {
    Text = "火山の幻影"
  },
  Event_7081_ChoiceDesc1 = {
    Text = "【私は何かを見た】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7081_ChoiceDesc2 = {
    Text = "【私は何も見ていない】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7081_Desc = {
    Text = "あなたの眼の奥から液体が漏れ出てくる。\nその粘つく感触が恐ろしい。\n\n突き詰めれば、それは、あなたが目にしたものによって生じたはずだが、あなたは——本当に何も見ていないのか？"
  },
  Event_7081_Name = {
    Text = "見てはいけない"
  },
  Event_7082_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7082_Desc = {
    Text = "喜びも悲しみも感じるが、今あなたを覆うのは自分の感情ではない。\n耳を塞ぎ、シルバーキーが眩しい光を放つ。\n\nやっと息ができるようになった。"
  },
  Event_7082_Name = {
    Text = "溺れ沈む"
  },
  Event_7083_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7083_Desc = {
    Text = "短剣持ちが鳴き声を上げ、まるで真夜中の墓地の不吉な鳥のよう。\n\n声は瞬く間に消え、他の二人の海踊人も姿を消した……これは密境が映し出した幻影に過ぎなかった。"
  },
  Event_7083_Name = {Text = "追撃"},
  Event_7084_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7084_Desc = {
    Text = "それは静かに空中に浮かび、瞬きもせず、切実な目で何かを伝えようとしているようだ。\n\n目には魂が宿るかもしれないが、言葉がなければ、少しの焦りと悲しみを感じるだけだった。\n\nそれは突然消え去った。"
  },
  Event_7084_Name = {
    Text = "盲目の注視"
  },
  Event_7085_ChoiceDesc1 = {
    Text = "【賛同する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7085_ChoiceDesc2 = {
    Text = "【贈り物を捧げる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7085_ChoiceDesc3 = {
    Text = "【背を向けて離れる】25黒章を獲得する"
  },
  Event_7085_Desc = {
    Text = "「もしもいつか、私が堕ちる運命にあるのなら、私は水の中に落ちたい。\n鼻腔を満たす水流は、優しい昔の夢のよう。\n私が沈む液体こそが、@2が最も渇望する器」"
  },
  Event_7086_ChoiceDesc1 = {
    Text = "【幻覚に抵抗する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7086_ChoiceDesc2 = {
    Text = "【狂気を汲み取る】ランダムな覚醒体を2体選択して覚醒させ、「(Skill.Arg1)」を2枚感染する"
  },
  Event_7086_Desc = {
    Text = "崩れゆく次元に他の次元の幻覚が病んだ部屋に流れ込む。"
  },
  Event_7086_Name = {
    Text = "次元の幻象"
  },
  Event_7087_ChoiceDesc1 = {
    Text = "【離れる】ランダムに覚醒体を1体覚醒させる"
  },
  Event_7087_Desc = {
    Text = "少女は一瞬驚き、手をスカートの端に滑らせた。\n\n「私ができることは……これだけです」"
  },
  Event_7087_Name = {
    Text = "白いドレスの少女"
  },
  Event_7088_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7088_Desc = {
    Text = "誰が話しているのか？\nあなたは頭を下げ、ぼんやりとした逆さまの影を見た――それはあなたと同じ服を着ているが、手にナイフを握り、あなたに向かって微笑んでいる。"
  },
  Event_7088_Name = {
    Text = "あなたは見つけたくない"
  },
  Event_70892_ChoiceDesc1 = {
    Text = "【肉体の記憶に従う】戦闘をスキップして即座に勝利するが、Arg1ライフを失う"
  },
  Event_70892_ChoiceDesc2 = {
    Text = "【離れる】戦闘に入る"
  },
  Event_70892_Desc = {
    Text = "敵は非常に強力だが、倒すコツはもう知っている。"
  },
  Event_70892_Name = {
    Text = "肉体の記憶"
  },
  Event_7089_ChoiceDesc1 = {
    Text = "【クムを引き離す】"
  },
  Event_7089_ChoiceDesc2 = {
    Text = "【実験体を攻撃する】"
  },
  Event_7089_Desc = {
    Text = "クムは実験体の首の後ろから噛みつき、振り回そうとした。\n\nその瞬間、実験体はフクロウのように、頭を180°回転させ、クムの顔を突こうとした。"
  },
  Event_7089_Name = {Text = "闘技場"},
  Event_7090_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7090_Desc = {
    Text = "あなたはシルバーキーを握り、次元の暗流で真貌の呼び声を感じる。\n\n正体不明の地獄の番犬に対抗するため、可能な限りすべての力を借りなければならない。"
  },
  Event_7090_Name = {
    Text = "次元の幻象"
  },
  Event_7091_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7091_Desc = {
    Text = "「その調査員については、館長が直接尋問するつもりだ……\n生かしておけ……」\n声は次第に小さくなり、ついには闇に消えた。"
  },
  Event_7091_Name = {
    Text = "壁に耳あり"
  },
  Event_7092_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7092_Desc = {
    Text = "落下する感覚から、急に目が覚める。\n\n地面はしっかりしていて、足元には精巧な四角い鏡が横たわっている。"
  },
  Event_7092_Name = {
    Text = "鏡の中の鏡"
  },
  Event_7093_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7093_Desc = {
    Text = "あなたはすでに発狂して手の施しようがない者と議論することは決してない。それはあなたの魂を真夜中の問いかけの中で完全に捕食させてしまうだろう。あなたを解放してあげよう！"
  },
  Event_7094_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7094_Desc = {
    Text = "蝋人形の顔は、どうあるべきだろうか？\nあなたは目を閉じ、その脳裏に幾千ものぼんやりとした顔がよぎっていく。\n\nそれらは、暗い河の流れに現れては消えていく、青白い炎を引きずる蝋燭のようだった。\n\nあなたはその河を辿って、終着点へと向かう。\nそこに立つ、唯一にして、最後の蝋人形。\nそれに近づくと、目に映ったのは……@2。"
  },
  Event_7094_Name = {
    Text = "未完成の蝋人形"
  },
  Event_7095_ChoiceDesc1 = {
    Text = "【短剣を持つ者を襲撃する】「(Skill.Arg1)」に感染し、呪われた遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7095_ChoiceDesc2 = {
    Text = "【刀を持つ者を待ち伏せする】2枚の「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」「(RelicConfig.Arg3)」を獲得する"
  },
  Event_7095_ChoiceDesc3 = {
    Text = "【槍を持つ者の足を引っかける】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7095_Desc = {
    Text = "三人の海踊人があなたたちを執拗に追い詰め、狂気のような熱い視線があなたのマントを燃やしそうだ。\n\n振り返ると、彼ら三人はそれぞれ異なる特徴を持っていることに気づく——\n大刀を振るう者は最も激しく叫び、行動は少し無頓着。\n\n槍を持つ者は慎重に歩み、まるで言葉を覚えたての子供のよう。\n\n短剣を握る者は最後尾にいて、口から狂信的な祈りを絶え間なくつぶやいている。"
  },
  Event_7095_Name = {Text = "追撃"},
  Event_7096_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7096_Desc = {
    Text = "あなたは贈り物を受け取り、慎重に開ける。\n\n 一対の眼球が静かに箱の中に横たわっていた。 \n\n「僕の目を君にあげるよ」 \n\n「かつて彼が、僕にしてくれたように」"
  },
  Event_7096_Name = {
    Text = "終幕の儀Ⅵ"
  },
  Event_7097_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7097_Desc = {
    Text = "光の中心を手で通り抜け、固まったシルバーコアの一滴を拾い上げました。\nこの記憶と魂の貴重な媒体は非常に熱く、異様な色を反射している。\n\nそれがすべての光をねじ曲げる前に、焼けるような痛みで再び暗闇に投げ入れた。"
  },
  Event_7097_Name = {
    Text = "暗夜の蛍光"
  },
  Event_7098_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7098_Desc = {
    Text = "あなたは少年の贈り物を断った。 \n少年は空洞の眼窩であなたを見つめる。\n彼は静かに、ため息をひとつつく。\n\n 「じゃあ、さようなら」 \nそう言うと彼は深々と礼をし、舞台の最後を飾るように身を傾け——窓の外へ、ふわりと倒れた。\n\n彼の姿は、舞う蝶のように。\n風のように、儚く消えていった。"
  },
  Event_7098_Name = {
    Text = "終幕の儀Ⅵ"
  },
  Event_7099_ChoiceDesc1 = {
    Text = "下位刻印を選択"
  },
  Event_7100_ChoiceDesc1 = {
    Text = "【耳を受け取る】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7100_ChoiceDesc2 = {
    Text = "【願いを拒否する】3つの中から1つ刻印を獲得する"
  },
  Event_7100_Desc = {
    Text = "華麗な旋律が、その指先から溢れ落ちていく。\n憂いを湛えた蝋人形のピアニストが、窓辺に一人座り奏でている。\n\n彼の意識が芽生えた時から、この蝋人形館だけが彼の世界のすべてだった。\n\n閉ざされた世界の中で、違う音楽を聴いてみたいと思うようになったという。\nとりわけ……ジャズという音楽を。\n\n話の最後に、彼は自らの片耳を引きちぎり、あなたに持って行ってくれと頼み、差し出した。\n\n「外の音楽を聴かせてほしい……\nそれをただ、ポケットに入れてくれればいい」"
  },
  Event_7100_Name = {
    Text = "耳を傾ける"
  },
  Event_7101_ChoiceDesc1 = {
    Text = "【休憩】Arg2ライフを回復する[ExDesc1]"
  },
  Event_7101_ChoiceDesc2 = {
    Text = "【瞑想】覚醒体を1体選択して覚醒させる[ExDesc1]"
  },
  Event_7101_ChoiceDesc3 = {
    Text = "【処置】症状カードを最大3枚除去し、黒印をArg2獲得する。"
  },
  Event_7101_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n\n通信機から誰かが呼んでいる。"
  },
  Event_7101_Name = {Text = "休憩所"},
  Event_7101_Tips3 = {
    Text = "症状カードは所持していません。"
  },
  Event_7102_ChoiceDesc1 = {
    Text = "【挑戦を受ける】"
  },
  Event_7102_ChoiceDesc2 = {
    Text = "【彼に一撃を加える】25黒章を獲得する"
  },
  Event_7102_Desc = {
    Text = "影の中から痩せた人影が現れ、あなたの行く手を阻んだ。\n\n永遠に束縛された記憶の一片が、突如として密境に侵入した。\n\n「N」と名乗ったその虚像は、手の中のチップをもてあそびながら、曖昧な声色であなたを彼のゲームに誘った。\n\n三色のチップがあなたの前に広げられる。\n\n彼と「ゲーム」をしなければ、彼はあなたを簡単には行かせてくれないだろう。"
  },
  Event_7102_Name = {
    Text = "ショーの始まり"
  },
  Event_7103_ChoiceDesc1 = {
    Text = "【シルバーキーを差し込む】"
  },
  Event_7103_Desc = {
    Text = "飽和した融蝕液の中に何かが含まれているようだ…シルバーキーで観測してみよう。"
  },
  Event_7103_Name = {
    Text = "黒い水たまり"
  },
  Event_7104_ChoiceDesc1 = {
    Text = "【足掻いて目覚める】最大ライフをArg1増加させる"
  },
  Event_7104_ChoiceDesc2 = {
    Text = "【沈眠に身を委ねる】ランダムな2枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、2枚の「(Skill.Arg2)」に感染"
  },
  Event_7104_Desc = {
    Text = "あなたは胸に、ひときわ輝く宝石を抱えている。\nそれは胸から全身に広がり、蝋燭のような温かな記憶が頭に流れ込む。\n\nパチパチと音を立てる炭火、炉ばたの安楽椅子、芳醇な熱い紅茶、足元で丸まる猫のお腹……\n\nこの心地よい眠気の中で、あなたの意識は沈み、柔らかな世界に落ちる。"
  },
  Event_7104_Name = {
    Text = "過去に沈む"
  },
  Event_7105_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7105_Desc = {
    Text = "あなたはためらうことなくフィルムの残り半分を引き出した。\nそれらはカメラの中に隠れていたが、突然引き出され、そこに映る光景に言葉を失った。\n\n未現像のフィルムには、あなたが黒い泥の中に倒れている姿が記録されていた。"
  },
  Event_7105_Name = {
    Text = "無罪記録"
  },
  Event_7106_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7106_Desc = {
    Text = "あなたはカメラをしっかりとチェックした。\n革と黒金が本体に埋め込まれ、わずかに油光りしている。\n\nレンズはあなたを見つめ、まるで覗き込んでいるかのようだ……"
  },
  Event_7106_Name = {
    Text = "無罪記録"
  },
  Event_7107_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7107_Desc = {
    Text = "手のひらにすくった月光が石碑に落ちる。\n\n誰かが厚い泥の下に埋められ、見物人たちは自然死を迎えたと主張し、地下で安らかに眠るだろうと言う。\n\nしかし埋もれた泥が動き、悲鳴の中で、ぐったりとした月が這い出てきた。"
  },
  Event_7107_Name = {
    Text = "銀月の破片"
  },
  Event_7108_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7108_Desc = {
    Text = "そっと蝶の黒い翼に触れると、蝶は羽ばたき、黒い液体となって手のひらに落ちる。"
  },
  Event_7108_Name = {
    Text = "存在しないはずのもの"
  },
  Event_7109_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7109_Desc = {
    Text = "孤独な月が空に高く掛かり、あなたにはその祈りの讃歌がはっきりと聞こえた。\n奇妙な音色は、穢れたものの囁きのようだった。\n\n祈りが止み、あなたは立ち去ろうとする。\nすると、背後に白い幻影が現れる。\n\n「運命と祈りを覗き見る冒涜者よ、恩恵と代償も約束通りに訪れるだろう」"
  },
  Event_7109_Name = {
    Text = "銀月の破片"
  },
  Event_7110_ChoiceDesc1 = {Text = "【3点】"},
  Event_7110_ChoiceDesc2 = {Text = "【6点】"},
  Event_7110_ChoiceDesc3 = {Text = "【1点】"},
  Event_7110_Desc = {
    Text = "どうやら今日は運が良さそうだ。\n\nダイスが震え、興奮した音を立てる。\n\nあなたは点数を予想することに決めた。"
  },
  Event_7110_Name = {
    Text = "止まらぬ賭け"
  },
  Event_7111_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7111_Desc = {
    Text = "この賭けは大きな詐欺だ！\nあなたは「ガタン」と立ち上がるが、眩暈を感じる。\n\nダイスがざわめき、魅惑的な声が頭に響く——\n「一度きり…今のが最後…」"
  },
  Event_7111_Name = {
    Text = "止まらぬ賭け"
  },
  Event_7112_ChoiceDesc1 = {
    Text = "【シルバーコアを使う】1つの低級遺物を高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_7112_ChoiceDesc2 = {
    Text = "【シルバーコアをしまう】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」と「(Skill.Arg3)」に感染する"
  },
  Event_7112_ChoiceDesc3 = {
    Text = "【引き出しに戻す】25黒章を獲得する"
  },
  Event_7112_Desc = {
    Text = "机の右側2番目の引き出しに、孤独に置かれた成形済みのシルバーコアがある。\nそっと触れると、嵐のうなり声が聞こえ、雪粒が砕ける音とすすり泣く笛の音が混ざっている……"
  },
  Event_7112_Name = {
    Text = "孤独なシルバーコア"
  },
  Event_7113_ChoiceDesc1 = {
    Text = "【耳を澄ます】「(Skill.Arg1)」に感染し、呪われた遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7113_ChoiceDesc2 = {
    Text = "【変更を加える】遺物を1つ破棄することを選択し、報酬を1つ獲得する"
  },
  Event_7113_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7113_Desc = {
    Text = "すべての音楽が心を動かすわけではない。\n\n純粋な不協和音が悲鳴を作り出した。"
  },
  Event_7113_Name = {
    Text = "不協和音"
  },
  Event_7114_ChoiceDesc1 = {
    Text = "【それを拾い上げる】「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7114_ChoiceDesc2 = {
    Text = "【それを諦める】25黒章を獲得する"
  },
  Event_7114_Desc = {
    Text = "隠れた腐臭がする草むらの角、ひび割れた融蝕痕の中に、何かが静かに横たわっている。"
  },
  Event_7114_Name = {
    Text = "草むらの後ろ"
  },
  Event_7115_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7115_Desc = {
    Text = "その影は近づかず、しばらくあなたを見つめた後、銀の砂に変わった。"
  },
  Event_7115_Name = {
    Text = "シルバーキーの使い手"
  },
  Event_7116_ChoiceDesc1 = {
    Text = "【触手を握る】トゥルーの助けを受け入れる"
  },
  Event_7116_Desc = {
    Text = "ため息の後、トゥルーが追いかけてきた。\n\n重く冷たい触肢があなたを引き寄せ、敵陣に突っ込むという恐ろしい考えを消し去った。\n\n「今だけ、余は貴様の助けとなろう」"
  },
  Event_7116_Name = {
    Text = "代行者の承諾"
  },
  Event_7117_ChoiceDesc1 = {
    Text = "【鍵を獲得】"
  },
  Event_7117_Desc = {
    Text = "1、2、3……\nジェンキンと机の距離は10フィート。\n短い距離だが、彼女の一生のように長い。\n\n彼女は柔らかなサテンのリボンを思い出し、\n金色の蝶のキャンディの包み紙を思い出し、\n母の涙を思い出していた。\n\n彼女はさらに多くのことを考えた……\n\n痩せた体が黒い川を渡り、少しずつ机に近づく。\n鍵は引き出しの中にあり、手に入れるために必要なものは、勇気、器用さ、そして少しの運。\n\n運以外は、ジェンキンには何も欠けていない。"
  },
  Event_7117_Name = {
    Text = "最後の鍵"
  },
  Event_7118_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7118_Desc = {
    Text = "ただの賭けだ、負けるはずがない。\n\n模様が刻まれたコインが高く投げられ、すぐに落ちて、あなたの手のひらに温もりを伝える。"
  },
  Event_7118_Name = {
    Text = "有体なギャンブラー"
  },
  Event_7119_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7119_Desc = {
    Text = "ただの賭けだ、負けるはずがない。\n\n模様が刻まれたコインが高く投げられ、すぐに落ちて、あなたの手のひらに温もりを伝える。"
  },
  Event_7119_Name = {
    Text = "有体なギャンブラー"
  },
  Event_7120_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7120_Desc = {
    Text = "ただの賭けだ、負けるはずがない。\n\n模様が刻まれたコインが高く投げられ、すぐに落ちて、あなたの手のひらに温もりを伝える。"
  },
  Event_7120_Name = {
    Text = "有体なギャンブラー"
  },
  Event_7121_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7121_Desc = {
    Text = "あなたはこの厳粛なピアノレッスンに加わるつもりはない。\n\n小節が終わるたびに、学生は苦労して頭をひねり、聞いているふりをする。\n\nそして先生も少し身をかがめ、唇を動かし、丸い目で存在しない楽譜を見つめている。\n\n彼らは自分が何をしているのか分からず、なぜ人間が何年もかけてこの機械的な練習をするのか理解することはないだろう。\n\n彼らはただ模倣しているだけだ。"
  },
  Event_7121_Name = {
    Text = "ピアノレッスン"
  },
  Event_7122_ChoiceDesc1 = {
    Text = "【シルバーキーを差し込む】"
  },
  Event_7122_Desc = {
    Text = "飽和した融蝕液の中に何かが含まれているようだ…シルバーキーで観測してみよう。"
  },
  Event_7122_Name = {
    Text = "黒い水たまり"
  },
  Event_7123_ChoiceDesc1 = {
    Text = "【歌詞を聞き分ける】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7123_ChoiceDesc2 = {
    Text = "【静かに口ずさむ】3つの中から1つ刻印を獲得する"
  },
  Event_7123_Desc = {
    Text = "古い船歌が密境に響く。\n\n密境に閉じ込められた記憶が、聞いたことのない言葉で、波、空、酒を歌う。"
  },
  Event_7123_Name = {Text = "海の歌"},
  Event_7124_ChoiceDesc1 = {
    Text = "【カラスを呼ぶ】20黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7124_ChoiceDesc2 = {
    Text = "【遠く離れる】"
  },
  Event_7124_Desc = {
    Text = "漆黒の鳥はあなたをじっと見つめる。\n\n長い時間が経ってから、ふいに、その羽の下から何かが落ちた……"
  },
  Event_7124_Name = {
    Text = "群れから離れたカラス"
  },
  Event_7125_ChoiceDesc1 = {
    Text = "【前に出て握る】25黒章を獲得する"
  },
  Event_7125_ChoiceDesc2 = {
    Text = "【友好的に応える】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_7125_Desc = {
    Text = "どこからともなく現れた猫が融蝕液の中に座っている。\nそのぼんやりとした輪郭は、精神次元の住民であることを示している。\n\nその見えない顔の投影が、賢い目でラモンナを見つめ、白い前足を上げて彼女に手招きする。"
  },
  Event_7125_Name = {
    Text = "彷徨う住人"
  },
  Event_7126_ChoiceDesc1 = {
    Text = "【北へ猛進する】"
  },
  Event_7126_ChoiceDesc2 = {
    Text = "【声を無視する】"
  },
  Event_7126_Desc = {
    Text = "敵の攻勢が雨のように背後に降り注ぎ、刀の刃がマントを何度もかすめ、留まっているカモメの群れを驚かせた。\n\n「北へ…あるいは船に……」\n\nどんなに鈍い人でも、何らかの力が密かに助けていることに気づくだろう。"
  },
  Event_7126_Name = {
    Text = "一路北へ"
  },
  Event_7127_ChoiceDesc1 = {
    Text = "【太陽を聴く】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7127_ChoiceDesc2 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7127_Desc = {
    Text = "現実と虚構の交錯の中、天体は既定の軌道を永遠に回る。\n\n無数のすれ違いが、奇妙な楽章を奏でる……"
  },
  Event_7127_Name = {
    Text = "星月の音"
  },
  Event_7128_ChoiceDesc1 = {
    Text = "【悲しみに身を任せる】カードを複製する。症状カードを複製した場合、75黒章を獲得する"
  },
  Event_7128_ChoiceDesc2 = {
    Text = "【怒りとともに去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_7128_Desc = {
    Text = "液体が瞳孔から噴き出し、冷たく激しく魂の一部を奪い離れる。"
  },
  Event_7128_Name = {
    Text = "冥滩の涙"
  },
  Event_7129_ChoiceDesc1 = {
    Text = "【回廊の奥へ進む】"
  },
  Event_7129_ChoiceDesc2 = {
    Text = "【背を向ける】25黒章を獲得する"
  },
  Event_7129_Desc = {
    Text = "白い月光が時の流れを無視して、静寂の回廊に降り注ぐ。\n\n門は月光に照らされ、不気味な光を放つ。"
  },
  Event_7129_Name = {
    Text = "静寂の回廊"
  },
  Event_7130_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7130_Desc = {
    Text = "目の前の蝋人形の修復に取り掛かることにした。\n\n周辺に散らばった工具の中から、ひときわ目を引く「プルシアンブルー」という染料を手に取る。\n\nその青は、まるで病のように深く、深く、不穏な色をしていた。"
  },
  Event_7130_Name = {
    Text = "未完成の蝋人形"
  },
  Event_7131_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7131_Desc = {
    Text = "膿が鋭く身の毛もよだつような叫び声を上げた。\n\n耳の後ろで、存在しないはずの風の音、幻聴めいた笛の音、膿がうごめく音が重なって聞こえる。\n\n膿は奇妙に痙攣し、やがて硬直したまま静寂の底へ沈んでいった。\n\nこの光景を共に見ていたあなたの隣の覚醒体が、まるで何かに呼び寄せられるように反応した。"
  },
  Event_7131_Name = {
    Text = "奇妙な膿"
  },
  Event_7132_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7132_Desc = {
    Text = "あなたの指先が彫像に触れると、時折意外なほど柔らかい凹みを感じる。\nそれは錯覚だと思い込んでいた。"
  },
  Event_7132_Name = {
    Text = "残躯を組み立てる"
  },
  Event_7133_ChoiceDesc1 = {
    Text = "【彼女のために涙を流す】"
  },
  Event_7133_ChoiceDesc2 = {
    Text = "【彼女に祈る】"
  },
  Event_7133_Desc = {
    Text = "体が船の縁に触れた瞬間、他人の記憶が頭に流れ込んできた。\n\n人々は彼女に清らかな白いドレスを着せ、宝石で彼女を飾り立てた。\n人々は彼女を高い祭壇に載せ、小さな町の住民たちは足元でひれ伏していた。\n\nそれは希望に満ちた目だった——船乗りは航海の加護を、漁師は穏やかな漁期を、他の住民たちは一年の安泰を願っていた。\n\nひれ伏す人々の中には、幼い頃の友達や、日々を共にする両親や兄弟もいた。\n\n彼女は何も欲しくない、何が欲しいのかもわからない。\n\n願いに受動的に応えることが、彼女の人生で唯一の役割のようだった。"
  },
  Event_7133_Name = {
    Text = "航前の儀式"
  },
  Event_7134_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7134_Desc = {
    Text = "その欠けた体の白い瞳がゆっくりと動き、あなたが去っていく姿を見つめ、淡い笑みを浮かべる。"
  },
  Event_7134_Name = {
    Text = "残躯を組み立てる"
  },
  Event_7135_ChoiceDesc1 = {
    Text = "【積極的に迎え撃つ】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7135_ChoiceDesc2 = {
    Text = "【抵抗を諦める】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_7135_ChoiceDesc3 = {
    Text = "【急いで離脱する】50黒章を獲得する"
  },
  Event_7135_Desc = {
    Text = "いくつかの蝋人形の原型が道を塞いでいる。\n\nそれらは歪んでいて、粗い顔立ちで、ロジャーズの技術とは思えない。\n\n「命令……主の命令……」"
  },
  Event_7135_Name = {Text = "習作"},
  Event_7136_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7136_Desc = {
    Text = "あなたは勇敢に眼を見つめることを選んだ。\n\nそれらは暗闇の中で輝く星々のようだ。\nそして笑い、無数の三日月に変わった。\n\n「あなたは視線を恐れない。\n恐れるべきではない……久しぶりだな、@2」\n\n消える前に、彼らは「再会の記念」として小さな贈り物をくれた。"
  },
  Event_7137_ChoiceDesc1 = {
    Text = "【スイッチを入れる】現在の視野を広げる[ExDesc1]"
  },
  Event_7137_Desc = {
    Text = "先人が残した照明装置で、周囲の黒い霧を払うことができる。"
  },
  Event_7137_Name = {
    Text = "サーチライト"
  },
  Event_7138_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7138_Desc = {
    Text = "あなたの背中に透明な翼が広がり、旋回しながらカラスと共に静かな海底へと流れ込む。"
  },
  Event_7138_Name = {
    Text = "カラスの群れの声"
  },
  Event_7139_ChoiceDesc1 = {
    Text = "【それを消滅させる】「異形の心臓」を獲得する"
  },
  Event_7139_Desc = {
    Text = "誰かにより、道端に捨てられた奇妙な奇形の膿。\n\nそれは、表面に汚濁した油のような緑色の光沢がゆらめき、今も不安定に変形し蠢いている。\n\nそれは怪物というよりも、灼熱の太陽に晒されたアイスクリームのようで、じきに濁る液体となり空気中へと溶けて消えてしまいそうだった。"
  },
  Event_7139_Name = {
    Text = "奇妙な膿"
  },
  Event_7140_ChoiceDesc1 = {
    Text = "【耳を塞ぐ手を下ろす】「(Skill.Arg1)」に感染し、報酬を1つ獲得することを選択する"
  },
  Event_7140_ChoiceDesc2 = {
    Text = "【カラスを1羽捕まえる】「(Skill.Arg1)」を獲得し、報酬を1つ獲得することを選択する"
  },
  Event_7140_ChoiceDesc3 = {
    Text = "【目を閉じる】50黒章を獲得する"
  },
  Event_7140_Desc = {
    Text = "叫び声、終わりなき叫び声——\n\nカラスの歌い手は黒光りする羽毛をまとい、鋭いくちばしは冷たい光を放つ。\n鋭い悲鳴が何度もあなたの鼓膜を突き破る。\n\n——耳を塞ぐ手を下ろせ！\n\n夜に高らかに鳴くカラスの群れは、あなたの身に潜む未熟な震えを飲み干そうとしている。"
  },
  Event_7140_Name = {
    Text = "カラスの群の歌"
  },
  Event_7141_ChoiceDesc1 = {
    Text = "【離れる】何も発見なし"
  },
  Event_7141_Desc = {
    Text = "探している人ではない"
  },
  Event_7141_Name = {Text = "2_6仮"},
  Event_7142_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7142_Desc = {
    Text = "あなたは進むことを選んだ。\n\nあの、ひどい蝋人形の芸術がもたらす精神的、肉体的なダメージと比べれば、この小さな悩みは大したことではない。\n\nもっと大きな使命を果たさなければならない。"
  },
  Event_7142_Name = {Text = "足音"},
  Event_7143_ChoiceDesc1 = {
    Text = "【問題を指摘する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7143_Desc = {
    Text = "「何よ！\nそんなに他人の傷をつつくのが好きなの！？」\n\n「そうよ！\n私は今、理由もなく25歳も年を取ったのよ！\n今から私をマーフィーお姉様と呼びなさい！」"
  },
  Event_7143_Name = {
    Text = "囚われた命"
  },
  Event_7144_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ低級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7144_Desc = {
    Text = "少女の顔は今夜の月光のように静かで、あなたに応えず、手にした羅針盤を高く掲げた——彼女は震えており、小さな羅針盤を掲げるだけで命を使い果たしたかのようだった。"
  },
  Event_7144_Name = {
    Text = "白いドレスの少女"
  },
  Event_7145_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7145_Desc = {
    Text = "「美味しい！美味しい！」カラスは怪しく笑い、腐敗した息がその広げた翼とともにあなたの鼻に漂う。"
  },
  Event_7145_Name = {
    Text = "呪われた怪鳥"
  },
  Event_7146_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7146_Desc = {
    Text = "言わせてもらえば、ノイズは新世代の模範だ。\nそれらは無秩序なビートと崩壊するメロディーで世界を席巻している。\n\n容赦なく、揺るがず、妥協もない。\n\n規律を嫌い、テーマを捨て、ノイズは誰も喜ばせない——もちろん、我々の蝋人形師も含めてね。"
  },
  Event_7146_Name = {Text = "悪趣味"},
  Event_7147_ChoiceDesc1 = {
    Text = "【道案内をする】"
  },
  Event_7147_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7147_Desc = {
    Text = "誰かがあなたの服をそっと引っ張っている。\nさっき会った男の子だ。\n彼は隅で憂鬱そうにあなたを見つめている。\n\n「ぼく、学園の演劇に出たいんだ。\nでも、舞台への道がわからないんだ」"
  },
  Event_7147_Name = {
    Text = "終幕の儀Ⅱ"
  },
  Event_7148_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7148_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7148_Desc = {
    Text = "鼻先に慣れ親しんだ匂いが漂い、家庭的で満足感を与える。\n食堂の香りをもう一度嗅ごうとすると、その香りはすっかり消えてしまった。"
  },
  Event_7148_Name = {
    Text = "異常な連絡"
  },
  Event_7149_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7149_Desc = {
    Text = "彼らは温かい色彩。\n\n熱烈で、優しく、愛おしい色彩。\n\n彼らは少女に懐かしい抱擁を与え、風のように消えた。"
  },
  Event_7149_Name = {
    Text = "懐かしい色"
  },
  Event_7150_ChoiceDesc1 = {
    Text = "【あなたは、一体何者ですか？】"
  },
  Event_7150_ChoiceDesc2 = {
    Text = "【どう考え方を変えるといいですか？】"
  },
  Event_7150_Desc = {
    Text = "長い髪の男が再び道を塞いだ。\n前回の経験から、ラモンナは不機嫌そうだ。\n\n「どうか落ち着いてください、友よ」\n\nゆっくりと話す男のその声は、磁力で引くように魅力的で、狭い気道を通る気流が擦れるような音を伴っていた。\n\n「私はしばらく観察していたのですが、あなたはきっと、考え方を変えることで目標に近づけると思いますよ」"
  },
  Event_7150_Name = {
    Text = "奇妙な旅の伴Ⅲ"
  },
  Event_7151_ChoiceDesc1 = {
    Text = "【私は探している】最大ライフをArg1増加させる"
  },
  Event_7151_ChoiceDesc2 = {
    Text = "【回避している】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7151_Desc = {
    Text = "私は見た……誰かが、探している。\nそれが探しているものは、探すことのできない、悲哀の対となる、そして真実と呼ばれるもの。\n\n私は見た……誰かが、逃げている。\nそれが逃げているのは、逃げることのできない、隠された残酷な、そして真実と呼ばれるもの。\n\nあなたは、はたしてどちらだ？"
  },
  Event_7151_Name = {
    Text = "探し求めるもの"
  },
  Event_7152_ChoiceDesc1 = {
    Text = "【注意深く調べる】1つの低級遺物を高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_7152_ChoiceDesc2 = {
    Text = "【耳を傾ける】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」と「(Skill.Arg3)」に感染する"
  },
  Event_7152_ChoiceDesc3 = {
    Text = "【慎重にしまう】25黒章を獲得する"
  },
  Event_7152_Desc = {
    Text = "前方の霧が小さなものに照らされている。\n\nそれはガラスかクリスタルの破片のように見え、無数の目立つ色や淡い色が、中で渦巻いている。"
  },
  Event_7152_Name = {
    Text = "私たちの記憶"
  },
  Event_7153_ChoiceDesc1 = {
    Text = "【挑戦を受ける】勝利すれば低級遺物を獲得し、失敗すれば症状を獲得する。勝敗に関わらず、その後の調査には影響しない"
  },
  Event_7153_ChoiceDesc2 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7153_Desc = {
    Text = "鏡に映るのは誰？\n呼吸も心拍もあなたと同調し、同じ奇妙な悪ふざけを共有している。\n\n密境のいたずらか、次元を超えた影か？\nまるで虚構の挑戦の誘い？"
  },
  Event_7153_Name = {
    Text = "魂の共鳴"
  },
  Event_7154_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7154_Desc = {
    Text = "その視線は歴史と時間を超越している。\n\nもしかしたら非線形的で、惑星誕生前の混沌の中からあなたを見下ろしているのかもしれない。\n\nあるいは未来のある日に、それは、あなたを待ち構えているのかもしれない。"
  },
  Event_7154_Name = {Text = "覗き見"},
  Event_7155_ChoiceDesc1 = {
    Text = "【受け取る】50黒章を獲得する"
  },
  Event_7155_Desc = {
    Text = "そこには何もなく、黒い液体が地面に広がり、何も映し出さない。\n\n錯覚だろうか？何かが指の間をすり抜けるように感じる。"
  },
  Event_7155_Name = {
    Text = "鏡面の下"
  },
  Event_7156_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7156_Desc = {
    Text = "「あなたは本当に寛大な方ですね。\n今日も明日も明後日も願いが叶いますように」\n「ちなみに、これは一度きりの取引です……」\n妖精は満足そうに口を鳴らし、体残惜しそうに別れを告げた。"
  },
  Event_7156_Name = {
    Text = "妖精の祝福"
  },
  Event_7157_ChoiceDesc1 = {
    Text = "【財布を返してくれ！】3つの中から1つ刻印を獲得する"
  },
  Event_7157_ChoiceDesc2 = {
    Text = "【躊躇する】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7157_Desc = {
    Text = "「財布を取り戻しに来いよ！」\n遠くの子供が手を振っている。\n\nあなたは走り出し、手を伸ばした瞬間、頭に大きな雑音が響いた。\n\n「どこの汚い子供だ！」\n「街の鼠が公爵夫人の服に触れるなんて！」\n「早く追い出せ！」\n「硬貨を持っているか？持っていないなら黒パン一つも手に入らないぞ！」"
  },
  Event_7157_Name = {Text = "無の書"},
  Event_7158_ChoiceDesc1 = {
    Text = "【歌声を追う】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7158_ChoiceDesc2 = {
    Text = "【一緒に歌う】「(Skill.Arg1)」に感染し、再刻印を最大2回まで行う"
  },
  Event_7158_Desc = {
    Text = "遠くの歌声が星屑に砕ける：\n「夜の路地の汚れた水たまりを呪う、崩れた壁の根元に腐った花が咲き、鎖が脳を泥に引きずり込む、濃霧が私の存在を消す前に、夕闇が最深の@2に沈む」"
  },
  Event_7158_Name = {
    Text = "白質の呪い"
  },
  Event_7159_ChoiceDesc1 = {
    Text = "【供養を残す】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7159_ChoiceDesc2 = {
    Text = "【祂を連れ去る】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7159_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7159_Desc = {
    Text = "あなたが近づいた瞬間、無秩序な混沌の霊魂が、泥沼から突然現れた。\n\n黒く染まった腕があなたをしっかりと絡め取り、それは泣きながら、祈りを求めてくる——\n\n供物を捧げるか、それを連れ出すか。"
  },
  Event_7159_Name = {
    Text = "混沌の霊"
  },
  Event_7160_ChoiceDesc1 = {
    Text = "【供物を捧げる】ランダムなカード1枚の刻印をアップグレードする"
  },
  Event_7160_ChoiceDesc2 = {
    Text = "【それを連れ去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7160_Desc = {
    Text = "あなたが近づいた瞬間、無秩序な混沌の霊魂が、泥沼から突然現れた。\n\n黒く染まった腕があなたをしっかりと絡め取り、それは泣きながら、祈りを求めてくる——\n\n供物を捧げるか、それを連れ出すか。"
  },
  Event_7160_Name = {
    Text = "混沌の霊"
  },
  Event_7161_ChoiceDesc1 = {
    Text = "【手を振って追い払う】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7161_ChoiceDesc2 = {
    Text = "【留まるに任せる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7161_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7161_Desc = {
    Text = "蝶が羽ばたき、黒い粘液をまとわりつかせながら、上下に揺れ飛んでいる。\n\n羽から溢れた黒い液体は固まると風化して剥がれ落ちる。\n\n疲れた蝶はあなたの鼻先に止まった。"
  },
  Event_7161_Name = {
    Text = "黒い液体の蝶"
  },
  Event_7162_ChoiceDesc1 = {
    Text = "【手を振って追い払う】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7162_ChoiceDesc2 = {
    Text = "【留まるに任せる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7162_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7162_Desc = {
    Text = "蝶が羽ばたき、黒い粘液をまとわりつかせながら、上下に揺れ飛んでいる。\n\n羽から溢れた黒い液体は固まると風化して剥がれ落ちる。\n\n疲れた蝶はあなたの鼻先に止まった。"
  },
  Event_7162_Name = {
    Text = "黒い液体の蝶"
  },
  Event_7163_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7163_Desc = {
    Text = "「勇気、意志、星のように輝く精神を見た。蝋で封じられた記憶を辿れば、願いは叶うだろう」"
  },
  Event_7163_Name = {
    Text = "探し求めるもの"
  },
  Event_7164_ChoiceDesc1 = {
    Text = "【そのままにしておく】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7164_ChoiceDesc2 = {
    Text = "【手を振って追い払う】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7164_ChoiceDesc3 = {
    Text = "【蝶を迎える】25黒章を獲得する"
  },
  Event_7164_Desc = {
    Text = "あなたたちは冷たい風が吹きすさぶ療養所を歩いていると、季節外れの黒い蝶が舞い降りてきた。\n\n蝶の羽ばたきには黒い粘液がまとわりつき、上下に揺れながら飛び、羽から溢れた黒い液体は固まって風化し剥がれ落ちる。\n\n疲れた蝶は、あなたの指先に止まった。"
  },
  Event_7164_Name = {
    Text = "存在しないはずのもの"
  },
  Event_7165_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ低級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7165_Desc = {
    Text = "疲れを感じ始める。\n意識があなたを引っ張り、池を越え、山を越え、\n太陽の外へ、光年の彼方へ、\n唯一無二の……宇宙の温床へと飛んでいく。"
  },
  Event_7165_Name = {
    Text = "終幕の儀Ⅳ"
  },
  Event_7166_ChoiceDesc1 = {
    Text = "【もう少し探す】"
  },
  Event_7166_Desc = {
    Text = "巨大な影があなたを完全に覆い、臭い唾液があなたをびしょ濡れにする。\n「小さな鼠、こっちにおいで。あとほんの少しだけ……」\n「誓って、君を食べるつもりは全くない……」\n「君の美味しそうなお腹を見つめてたりはしないよ！」"
  },
  Event_7167_ChoiceDesc1 = {
    Text = "【もう少し探す】"
  },
  Event_7167_Desc = {
    Text = "しおれた哲学者の蝋人形が煙草を吸い、白い煙幕に包まれている。\n\n「向こう側は存在するが、知ることはできない。だから、向こう側を知ることもできないのだ」\n\n「この世界をゲームだと考えてみようか……君が探しているものは、地図の向こう側にあるかもしれない」"
  },
  Event_7168_ChoiceDesc1 = {
    Text = "【もう少し探す】"
  },
  Event_7168_Desc = {
    Text = "「ごめん、気を悪くしないでおくれよ……」\n「鼠は好きじゃないんだ。鼠の厄介な所は、人間を全く恐れないことだな……」\n無精ひげの老人が隅で横たわり、憂鬱な目であなたを見つめている。\n「もちろん、君たちはとても意欲的だ。\nそれは良いことだが、それだけでは災厄を避けるのは難しいんだよ……」"
  },
  Event_7169_ChoiceDesc1 = {
    Text = "【呪いを見せる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7169_ChoiceDesc2 = {
    Text = "【カラスを拒否する】3つの中から1つ刻印を獲得する"
  },
  Event_7169_ChoiceDesc3 = {
    Text = "【無視する】"
  },
  Event_7169_Desc = {
    Text = "漆黒で病的な多頭のカラスが提灯教会の黒いローブから飛び出し、あなたの肩に止まった。\n\n「私の頭を見たか？呪いを味わえば、新しい頭が生えてくる。\n見せてくれ、君の呪いを！」"
  },
  Event_7169_Name = {
    Text = "呪われた怪鳥"
  },
  Event_7170_ChoiceDesc1 = {
    Text = "【呼びかけに応える】指令カードを1枚削除し、Arg1ライフを回復する"
  },
  Event_7170_ChoiceDesc2 = {
    Text = "【私は逃亡者ではない】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7170_Desc = {
    Text = "小道を全力で駆け抜ける。\nアドレナリンが放出され、乳酸が生成され、グルコースが消費される……混沌が脳を侵食し、思考を支配し、色とりどりの幻覚の中でゴールへ逃げるよう促す。\n\nそう、逃走だ。\nもし本当に逃走でないなら、待っているのは混沌と虚無、何も得られず、何も終わらないのはなぜだ？"
  },
  Event_7170_Name = {Text = "走る"},
  Event_7171_ChoiceDesc1 = {
    Text = "【音の発生源を追跡する】"
  },
  Event_7171_ChoiceDesc2 = {
    Text = "【リリーとクムを呼ぶ】"
  },
  Event_7171_Desc = {
    Text = "次元の通路の彼方から、恐怖と期待、不安が混じった低く重い声が聞こえ、あなたたちを呼んでいるようだ。\n\n続いて少女のぼんやりとしたつぶやきが聞こえ、やがて両方の声が次第に消えていった。"
  },
  Event_7171_Name = {
    Text = "導きの声"
  },
  Event_7172_ChoiceDesc1 = {
    Text = "【ポケットに入れる】"
  },
  Event_7172_Desc = {
    Text = "水銀に近い物質。\n\n融蝕液から抽出され、主に儀式で覚醒体を召喚するために使用される。"
  },
  Event_7172_Name = {
    Text = "シルバーコア"
  },
  Event_7173_ChoiceDesc1 = {
    Text = "【彼に道を譲るよう頼む】"
  },
  Event_7173_ChoiceDesc2 = {
    Text = "【身元を尋ねる】"
  },
  Event_7173_Desc = {
    Text = "あなたたちは薄暗い車両に足を踏み入れた。\n異様な違和感が心に浮かぶ。\n\nこの車両は空っぽで、乗客はすでに逃げ去っていた。地面には怪物の残骸が散らばり、徐々に消えつつあった。\n\n車両の中央に、あの男が立っていた。\n\n「私は世の中に縁があると信じています。そしてその縁が、私たちを同じ地下鉄に乗せたのです」"
  },
  Event_7173_Name = {
    Text = "奇妙な旅の伴Ⅳ"
  },
  Event_7174_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7174_Desc = {
    Text = "「君の目は本当に綺麗だね、星みたいに」\nシャーロットはクスクス笑い、乱れた髪がしなやかに垂れた。\n\n「学校で人気者なんだろうね、私も君が好き」\n去り際に、彼女はあなたの額にキスをした。\n\n体がぽかぽかして、何かが変わった気がした。"
  },
  Event_7174_Name = {
    Text = "調査員の影"
  },
  Event_7175_ChoiceDesc1 = {
    Text = "【読む】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7175_ChoiceDesc2 = {
    Text = "【スーツケースにしまう】「(Skill.Arg1)」に感染し、遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7175_Desc = {
    Text = "提灯教会のローブから黄ばんだ紙が落ちた。\n\n紙には奇妙な形の古代文字がびっしりと書かれており、象形文字のようなものもあれば、奇妙に上向きのものもあり、文字が重なっているものもある。\nわずかに判読できる文字もある。"
  },
  Event_7175_Name = {
    Text = "密命・上"
  },
  Event_7176_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7176_Desc = {
    Text = "あなたは言った——\n「ああ、シャーロット！ダメだ！」\n\nシャーロットの髪が激しく動き、彼女は怒った。\n\n「見せてあげる！私の力を見てて！」"
  },
  Event_7176_Name = {
    Text = "調査員の影"
  },
  Event_7177_ChoiceDesc1 = {
    Text = "【「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する】"
  },
  Event_7177_ChoiceDesc2 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7177_Desc = {
    Text = "事件302（開発中）、最終版ではありません"
  },
  Event_7177_Name = {
    Text = "事件302（開発中）"
  },
  Event_7178_ChoiceDesc1 = {
    Text = "【要求を受け入れる】「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7178_ChoiceDesc2 = {
    Text = "【要求を拒否する】25黒章を獲得する"
  },
  Event_7178_Desc = {
    Text = "顎骨がカチカチと音を立て、リズムのある音が響く。\nあなたの仲間は少し暗号学の知識を持っている。\n\n解読されたメッセージは以下の通り——\n「こんにちは、私を@2博士と呼んでください。\n私はかつて収集家であり、博物学者でした……\n\n（ここには長々とした経歴と肩書の紹介が続く、省略）\n\n要するに私のもう片方を見つけてくれませんか？それは小さな上顎骨です。\n\nそれを見つけてくれれば、私の宝物庫をあなたに開放します」"
  },
  Event_7178_Name = {
    Text = "カチカチ響く"
  },
  Event_7179_ChoiceDesc1 = {
    Text = "【100スタールを投入】「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7179_ChoiceDesc2 = {
    Text = "【5ペニーを投入】25黒章を獲得する"
  },
  Event_7179_Desc = {
    Text = "刺繍された財布がうごめいていた。\nその黒い大口を、あなたに向かって開けている。\n\nその財布は、裕福な女主人と離れて以来、何十年も空腹で、すぐにでも腹を満たされたかった。\n\nあなたが財布の中を覗くとそこには何もなく――ただ底の見えないほど濃密な闇が広がっていた。"
  },
  Event_7179_Name = {
    Text = "貪欲な財布"
  },
  Event_7180_ChoiceDesc1 = {
    Text = "【確固たる決意だ】指令カードを1枚削除し、Arg1ライフを回復する"
  },
  Event_7180_ChoiceDesc2 = {
    Text = "【成功への渇望だ】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7180_Desc = {
    Text = "「頭の固いお二人さん、ワークハウスはもう危険よ」\n通信機から突然ドールの声が聞こえた。\n「次はどうするつもり？彼女の頭でも縫ってみる？」\n「今は冷やかしてる場合じゃないよ、ドール！」\n「わかってる。声を聞いて判った」ドールは言った。\n「落ち着いて。成功の鍵は、何だかわかる？」"
  },
  Event_7180_Name = {
    Text = "ロゴス（理性）の原理"
  },
  Event_7181_ChoiceDesc1 = {
    Text = "【「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する】"
  },
  Event_7181_ChoiceDesc2 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7181_Desc = {
    Text = "事件304（開発中）、最終版ではありません"
  },
  Event_7181_Name = {
    Text = "事件304（開発中）"
  },
  Event_7182_ChoiceDesc1 = {
    Text = "【「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する】"
  },
  Event_7182_ChoiceDesc2 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7182_Desc = {
    Text = "事件305（開発中）、最終版ではありません"
  },
  Event_7182_Name = {
    Text = "事件305（開発中）"
  },
  Event_7183_ChoiceDesc1 = {
    Text = "【受話器を置く】3つの中から1つ上位刻印を獲得する"
  },
  Event_7183_ChoiceDesc2 = {
    Text = "【電話に出る】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7183_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7183_Desc = {
    Text = "あなたたちは車掌の休憩室を通り過ぎ、隠れた場所で電話のベルが鋭く鳴り響く。"
  },
  Event_7183_Name = {
    Text = "列車からの電話"
  },
  Event_7184_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7184_Desc = {
    Text = "輝きは薄れているが、確かに存在している。\n\nこれほど薄暗いシルバーコアでは覚醒体を召喚するのは難しいが、強化には最適だ——これがシルバーコアテクノロジーというものだ。"
  },
  Event_7184_Name = {
    Text = "存在の証明"
  },
  Event_7185_ChoiceDesc1 = {
    Text = "【淑女の肖像画】ランダムなカード1枚の刻印をアップグレードする"
  },
  Event_7185_ChoiceDesc2 = {
    Text = "【ワックス像の家族写真】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7185_Desc = {
    Text = "蝋人形館には多くの絵画作品も収蔵されている。\n人物、風景、静物、写実的なものから抽象的なものまで……\nそれらは単調な壁面を飾り、退屈さを無くす。\nあなたの目はその中の一つに深く引き込まれる。それは——"
  },
  Event_7185_Name = {
    Text = "肖像画の回廊"
  },
  Event_7186_ChoiceDesc1 = {
    Text = "【読み続ける】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7186_ChoiceDesc2 = {
    Text = "【離れる】最大ライフをArg1増加させ、さらに「(Skill.Arg2)」に感染する"
  },
  Event_7186_Desc = {
    Text = "重さを測るための天秤。\nその背後には、無数の臓器が赤いホルマリン液に浸かり、それらは整然と棚に置かれていた。\n\n近くのノートを拾い読みする。\n「心臓：8オンス、脳：50オンス……」"
  },
  Event_7186_Name = {
    Text = "臓器登録"
  },
  Event_7187_ChoiceDesc1 = {
    Text = "【プレゼントを開ける】特殊カードを獲得する"
  },
  Event_7187_Desc = {
    Text = "子供の幻影が目の前を一瞬で通り過ぎた。\n実際の子供なのか、密境の精神的な投影なのかは分からない。\n\nしかし——地面に残された箱を見ると、幼い字で「贈り物」と書かれていた。"
  },
  Event_7187_Name = {
    Text = "善意の贈り物"
  },
  Event_7188_ChoiceDesc1 = {
    Text = "【カラスを呼ぶ】40黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7188_ChoiceDesc2 = {
    Text = "【遠く離れる】25黒章を獲得する"
  },
  Event_7188_Desc = {
    Text = "白いカモメがマストのてっぺんに留まっていた。\nそのマストは白い霜で覆われている。\n\n鳴管が共鳴し、黒い存在を排斥する。\nそして、遠洋には属さないはずの漆黒の鳥たちを排斥する。"
  },
  Event_7188_Name = {
    Text = "群れから離れたカラス"
  },
  Event_7189_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7189_Desc = {
    Text = "その歌がラブソングの替え歌だと気づく。\nその本来の歌詞の終わりで、詩人は言っていた。\n\n「人間の声が私たちを呼び覚ましたとき……\n私たちは溺れて死ぬ」\n\n「今じゃない」あなたは心の中で言う。 \nあなたはまだ、人間が自分を目覚めさせてくれるのを待っている。"
  },
  Event_7189_Name = {
    Text = "カラスの群れの声"
  },
  Event_7190_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7190_Desc = {
    Text = "埃をかぶったフィルムの巻物。\nしかし、この部屋には映写機がない。\n\nフィルムの内容を知る機会は、ずっと後になるかもしれない。"
  },
  Event_7190_Name = {
    Text = "記憶の光影"
  },
  Event_7191_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ上位刻印を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7191_Desc = {
    Text = "あなたは少年の後ろを、遠すぎず近すぎず追う。\nタッ。タッ。タッ……少年は街角で立ち止まる。\n\n彼の後ろに揺れる赤い微光が見え、直感で蝋人形館が前方にあると感じる。\n少年が振り返る。彼に目はなく、眼窩は真っ黒。\n彼はあなたに微笑む。"
  },
  Event_7191_Name = {
    Text = "終幕の儀Ⅰ"
  },
  Event_7192_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7192_Desc = {
    Text = "あなたは彼の肩を軽く叩く。\n少年が振り返る。彼に目はなく、眼窩は真っ黒。\n\n「こんばんは。蝋人形館への道を探しています」\n少年は前方を指さす。彼の後ろに揺れる赤い微光が見える。直感で蝋人形館がそこだと感じる。\n気がつくと、少年はすでに去り、街灯が長い影を残している。"
  },
  Event_7192_Name = {
    Text = "終幕の儀Ⅰ"
  },
  Event_7193_ChoiceDesc1 = {
    Text = "【カラスを押さえつける】35黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7193_ChoiceDesc2 = {
    Text = "【放置する】離れる"
  },
  Event_7193_Desc = {
    Text = "孤独なカラスが、かすれた喉で鳴きながら、  \n自らの漆黒の羽根を一本ずつ引き抜いていく。  \n\n痛みに震え、鋭く叫ぶが、動きを止められない。\n\n「カァ——カァ——」\n\nその目からは黒い液体を伴った青い涙が流れる。  \nそれを目にしたのは、あなただけだった。"
  },
  Event_7193_Name = {
    Text = "融蝕液の涙"
  },
  Event_7194_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7194_Desc = {
    Text = "貴重な知識が脳内に流れ込み、霧となる……\n\n目覚めると、あの奇妙な表紙の本は消えていた……"
  },
  Event_7194_Name = {
    Text = "大人の本"
  },
  Event_7195_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7195_Desc = {
    Text = "あなたはそれらの蝋人形を簡単に打倒できた。\nそれらは頭を垂れてあなたの前に倒れている。\n\n蝋人形の底部にいくつかの文字が書かれていた。\n「A.F.@2年11月　ロジャーズ制作　@2学院」\n\nロジャーズが、かつてある芸術学院の彫刻科を専攻していたことを思い出す。\n\n不器用な蝋人形達は彼の当時の習作に違いない。"
  },
  Event_7195_Name = {Text = "習作"},
  Event_7196_ChoiceDesc1 = {
    Text = "【なぜだろう】"
  },
  Event_7196_ChoiceDesc2 = {
    Text = "【深海へ墜ちる】"
  },
  Event_7196_Desc = {
    Text = "「偽物め！息子を返せ！」\n「お前は航海の聖女じゃないのか？船を守るのが役目じゃないのか？なぜ一隻しか戻らなかったんだ、答えろ、答えろ！」\n「溺れさせろ！父が死ぬ前に味わった苦しみを、彼女にも味わわせろ！」\n「溺れさせろ、溺れさせろ！」\n「この偽物を溺れさせろ！石に縛り付けろ！」\n海水が鼻と口に押し寄せ、肺の隅々から空気が押し出されるとき、彼女はまだその豪華で清らかな白いドレスを着ていた。\n\n聖女になってから最初の考えが、頭の最も暗い隅から這い出てきた、遅れて。\n\n「そうだ、あの船たちは、なぜ沈んだのだろう？」"
  },
  Event_7196_Name = {
    Text = "海に沈む"
  },
  Event_7197_ChoiceDesc1 = {
    Text = "【カラスを押さえつける】30黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7197_ChoiceDesc2 = {
    Text = "【放置する】離れる"
  },
  Event_7197_Desc = {
    Text = "孤独なカラスが、かすれた喉で鳴きながら、  \n自らの漆黒の羽根を一本ずつ引き抜いていく。  \n\n痛みに震え、鋭く叫ぶが、動きを止められない。\n\n「カァ——カァ——」\n\nその目からは黒い液体を伴った青い涙が流れる。  \nそれを目にしたのは、あなただけだった。"
  },
  Event_7197_Name = {
    Text = "融蝕液の涙"
  },
  Event_7198_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7198_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7198_Desc = {
    Text = "肩に力強く確かな手が触れたが、振り返るとその感触は消えていた。"
  },
  Event_7198_Name = {
    Text = "異常な連絡"
  },
  Event_7199_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7199_Desc = {
    Text = "鉄道橋、ロンディニウムの血管と神経、都市の心臓と四肢をつなぐ。ライ精神病院は四肢の末端に位置し、静かに血液と信号の輸送を待っている。"
  },
  Event_7199_Name = {
    Text = "鉄道の幻覚"
  },
  Event_7200_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7200_Desc = {
    Text = "あなたは手提げ鞄を地面に置くと、何度か強く踏みつけた。\n\n震えが止まったのを確認してから、再びそれを手に取る。\n\n上の埃を払い、マーフィーの怪訝な視線を受けながら、あなたたちは先に進み続ける。"
  },
  Event_7200_Name = {
    Text = "予期せぬ手紙"
  },
  Event_7201_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7201_Desc = {
    Text = "木製のドア越しに睨まれている脅威を感じる……何も言わず、そっと本棚に戻した。"
  },
  Event_7201_Name = {
    Text = "大人の本"
  },
  Event_7202_ChoiceDesc1 = {
    Text = "【カラスを追い払う】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7202_ChoiceDesc2 = {
    Text = "【無視する】離れる"
  },
  Event_7202_Desc = {
    Text = "それ、またはそれらは、寝室を旋回し、ランプシェードにぶつかってガタガタと音を立てている。"
  },
  Event_7202_Name = {
    Text = "提灯の黒いカラス"
  },
  Event_7203_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7203_Desc = {
    Text = "ここは精神の次元、啓示の世界。\n\n彼らはあなたの頭をかき乱すことしかできない。"
  },
  Event_7203_Name = {
    Text = "霊知の嵐"
  },
  Event_7204_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7204_Desc = {
    Text = "頭蓋骨：ハンク・ティリンハースト A.F.186 - A.F.203 クレオール島\n脊椎：アンディ・クロフォード A.F.177 - A.F.203 ナラガンセット\n……深く考えない方がいい。"
  },
  Event_7204_Name = {Text = "銘板"},
  Event_7205_ChoiceDesc1 = {
    Text = "【破片を調べる】山札からランダムに指令カードを3枚引き、1枚選択して削除し、75黒章を獲得する"
  },
  Event_7205_ChoiceDesc2 = {
    Text = "【ドールに尋ねる】山札からランダムに指令カードを3枚引き、1枚選択して未強化のコピーを山札に追加し、25黒章を獲得する"
  },
  Event_7205_ChoiceDesc3 = {
    Text = "【無視する】50黒章を獲得する"
  },
  Event_7205_Desc = {
    Text = "ドールがくれた金属片が胸で不安に震えている。"
  },
  Event_7205_Name = {
    Text = "不安のブローチ"
  },
  Event_7206_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7206_Desc = {
    Text = "「彼は終点で静かに待っている。終点をどこに定めようとも——若き管理者を見よ、彼女の逃避は狂気を招く」"
  },
  Event_7206_Name = {
    Text = "探し求めるもの"
  },
  Event_7207_ChoiceDesc1 = {
    Text = "【離れる】何も発見なし"
  },
  Event_7207_Desc = {
    Text = "開発中、特殊事件"
  },
  Event_7207_Name = {Text = "2_16仮"},
  Event_7208_ChoiceDesc1 = {
    Text = "【それを慰める】最大ライフをArg1増加させる"
  },
  Event_7208_ChoiceDesc2 = {
    Text = "【それを無視する】ランダムな2枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、2枚の「(Skill.Arg2)」に感染"
  },
  Event_7208_Desc = {
    Text = "温もりを持つ人間の心臓の器官とリンクする。\n\nそれはリンクの呼吸のリズムに合わせて鼓動し、そうすることで捨てられず、永遠にリンクと共に歩む権利を獲得。\nかのようだ。"
  },
  Event_7209_ChoiceDesc1 = {
    Text = "ランダムな上位刻印"
  },
  Event_7210_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7210_Desc = {
    Text = "あなたの冷淡さに声の主は残念がり、水面にいくつかの波紋が広がり、再び静かになった。"
  },
  Event_7210_Name = {
    Text = "界外の音"
  },
  Event_7211_ChoiceDesc1 = {
    Text = "【カードを1枚選択して刻印「(EnchantConfig.Arg1)」を獲得する】テスト刻印"
  },
  Event_7211_ChoiceDesc2 = {
    Text = "【カードを1枚選択して刻印「(EnchantConfig.Arg1)」を獲得する】テストドロップパック"
  },
  Event_7211_Desc = {
    Text = "テスト指定刻印"
  },
  Event_7211_Name = {
    Text = "指定刻印テスト1"
  },
  Event_7212_ChoiceDesc1 = {
    Text = "【離れる】覚醒体を1体選択して覚醒させる"
  },
  Event_7212_Desc = {
    Text = "あなたは少年の頭を撫で、一緒に言葉を導く。\n「母への歌を——」\n\n声は夜の蛾のように、空っぽの舞台から漂い、\n暗闇の観客席にそっと降り立つ。"
  },
  Event_7212_Name = {
    Text = "終幕の儀Ⅲ"
  },
  Event_7213_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7213_Desc = {
    Text = "あなたは冷静に見守る。\n貴婦人が突然舞台に駆け上がる。\n\n彼女は狂ったように少年の口をこじ開け、\n手にした棒を強く突き込む。\n「話しなさい、ちゃんと話しなさい」\n\n少年の口から黒い血が流れる。\n彼は不明瞭に続けた。\n「母への歌を……」"
  },
  Event_7213_Name = {
    Text = "終幕の儀Ⅲ"
  },
  Event_7215_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7215_Desc = {
    Text = "それは窓ではなく、鏡だった。\n鏡にはラモンナの緊張した顔が映っている。\n\nこの部屋にはなぜ窓がなく、壁に大きな鏡が掛かっているのだろう？"
  },
  Event_7215_Name = {
    Text = "窓の中の影"
  },
  Event_7216_ChoiceDesc1 = {
    Text = "【シルバーキーを握る】ランダムな覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_7216_ChoiceDesc2 = {
    Text = "【目を閉じる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7216_Desc = {
    Text = "あなたは巨大な不条理に引き裂かれ、四肢がねじ曲がり、地面を這いずり回った。\nまるで次元外の@2に操られているかのようだ。\n\n「いや……いやだ……」\n\n正気が少しずつ崩壊していく——狂気の笑いと叫びが交錯し、巨大な網のように意識を絡め取る。\n\n口から漏れるのは支離滅裂な悲鳴だけ。"
  },
  Event_7216_Name = {
    Text = "凝視の眼"
  },
  Event_7217_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7217_Desc = {
    Text = "星河の色が変化し、足元に言葉にできない模様を描く。\nルビーのように美しく、クラゲのように膨らむ。\n鞄の中で赤い光が浮かび上がる……"
  },
  Event_7217_Name = {
    Text = "星々の分岐点"
  },
  Event_7218_ChoiceDesc1 = {
    Text = "【幻影を払う】心労値が+10増加する"
  },
  Event_7218_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7218_Desc = {
    Text = "ぼんやりとした顔が周囲に現れ、絶望的な呻き声をあげる。"
  },
  Event_7218_Name = {Text = "幻影"},
  Event_7221_ChoiceDesc1 = {
    Text = "【受け止める】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7221_ChoiceDesc2 = {
    Text = "【うつむいて確認する】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7221_Desc = {
    Text = "カラスが小道に切り取られた積み木のような空を旋回し、不安を掻き立てるかすれた鳴き声を上げる。\n\nカラス群が突然騒乱し、何か病的な本能が歪んだか目覚めたように、苛立ち凶暴に互いを追いかけ、何かが引き裂かれて落ちてきた。"
  },
  Event_7221_Name = {
    Text = "騒乱のカラスの群れ"
  },
  Event_7222_ChoiceDesc1 = {
    Text = "【指示に従う】最大ライフをArg1増加させる"
  },
  Event_7222_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7222_Desc = {
    Text = "シルバーキーの追跡力で休憩所を探そうとするが、得られた情報には微妙な異常が混じっており、何かに干渉されているようだ。"
  },
  Event_7222_Name = {
    Text = "異常な連絡"
  },
  Event_7223_ChoiceDesc1 = {
    Text = "【ドールに渡す】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7223_ChoiceDesc2 = {
    Text = "【銘板を読む】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7223_Desc = {
    Text = "彫刻家協会の実験体を倒すと、金属の銘板が落ちた。\nシルバーキーが銘板に反応し、微かに光る。"
  },
  Event_7223_Name = {Text = "銘板"},
  Event_7224_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7224_Desc = {
    Text = "刀持ちが長い叫び声を上げ、まるで山海を断ち切るような轟音の響き。\n\n声は瞬く間に消え、他の二人の海踊人も姿を消した……これは密境が映し出した幻影に過ぎなかった。"
  },
  Event_7224_Name = {Text = "追撃"},
  Event_7225_ChoiceDesc1 = {
    Text = "【蝋人形を修復する】カードを選択し、その行動力消費を1点減少させる"
  },
  Event_7225_Desc = {
    Text = "あなたは蝋燭を手に、霧の中を進み、彼女の前にたどり着いた。これは未完成の蝋人形だ。\n\n穏やかな顔立ちはふたつに裂けていて——\n一方は微笑み、一方は@1。\n\n彼女の神になれ。美を与えるか、涙を授けるか。\n彫刻し形づくるのか、破壊するのか。"
  },
  Event_7225_Name = {
    Text = "未完成の蝋人形"
  },
  Event_7226_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7226_Desc = {
    Text = "「もちろん、私は消滅を目の当たりにした」\nあなたは答えた。\n\nそう、それはただの小さな鼠の突然の死、心臓の崩壊、そして夜に沈むアイリスの葬送だった。"
  },
  Event_7226_Name = {
    Text = "失われた神の国"
  },
  Event_7227_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7227_Desc = {
    Text = "「神国……消滅……儚い議題……私は消滅が何かを知らない」\n二つの人影が静かに笑い、周囲に雪白の光の破片を撒き散らした。\n\n「では今、あなたは真の消滅を目撃することになる」"
  },
  Event_7227_Name = {
    Text = "失われた神の国"
  },
  Event_7228_ChoiceDesc1 = {
    Text = "【紙をつなぎ合わせる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7228_ChoiceDesc2 = {
    Text = "【読む】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7228_ChoiceDesc3 = {
    Text = "【それを捨てる】50黒章を獲得する"
  },
  Event_7228_Desc = {
    Text = "提灯教会のローブから黄ばんだ紙が落ちた。\n\n紙には奇妙な文字がびっしりと書かれており、象形文字のようなものや、奇妙に上向きのもの、重なり合った文字もあり、わずかに判読可能な文字もある。\n\nタイトルは《@2神子の誕生》"
  },
  Event_7228_Name = {
    Text = "密命・下"
  },
  Event_7229_ChoiceDesc1 = {
    Text = "【足掻く】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7229_ChoiceDesc2 = {
    Text = "【沈む】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7229_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7229_Desc = {
    Text = "「苦しい、苦しい……」\n「なぜ私が、なぜこんな目に？」\n「慈悲深い父なる神よ、私は何を間違えた？」\n悲しみ、苦痛、怒り、無念……\n「患者」たちの感情が重くのしかかってくる。\n胸を圧迫され、息ができない。"
  },
  Event_7229_Name = {
    Text = "溺れ沈む"
  },
  Event_7230_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7230_Desc = {
    Text = "その視線は肉を貫き、先駆者の網膜に烙印を焼き付けた。\n\n誰も逃れることはできない、まるで誰も@2できないように。"
  },
  Event_7230_Name = {Text = "覗き見"},
  Event_7231_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7231_Desc = {
    Text = "集中して歌詞を識別し、混乱した言葉が後頭部を打つ。\n\nそれは人間には理解できない言葉だった。"
  },
  Event_7231_Name = {Text = "海の歌"},
  Event_7232_ChoiceDesc1 = {
    Text = "【試練を受ける】「(Skill.Arg1)」に感染し、成功すれば高級遺物を獲得し、失敗すれば50黒章を獲得する"
  },
  Event_7232_ChoiceDesc2 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7232_Desc = {
    Text = "あなたは足元の鏡のように反射する黒い液体から、いくつかの秘密を垣間見た。\n\nその反射の縁はぼやけ、周囲には消えない黒い気が漂っている。\n見覚えがあるが、それが何なのかはっきりしない。"
  },
  Event_7232_Name = {
    Text = "鏡面の下"
  },
  Event_7233_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7233_Desc = {
    Text = "怪しげな匿体の手紙を軽蔑し、手紙を燃やして灰にする。"
  },
  Event_7233_Name = {
    Text = "また一通の救助要請"
  },
  Event_7234_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7234_Desc = {
    Text = "手紙の本体を調べると、封をしているところに粘つく液体があり、血液と黒い液体の混合物のようで、数本の髪の毛が混じっていた。"
  },
  Event_7234_Name = {
    Text = "また一通の救助要請"
  },
  Event_7235_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7235_Desc = {
    Text = "手紙が落ちた方向を探すと、曲がり角の壁のところで光るものを見つけた。"
  },
  Event_7235_Name = {
    Text = "また一通の救助要請"
  },
  Event_7236_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7236_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7236_Desc = {
    Text = "かすかな光が目の前に現れ、明るく暖かい。\n光を追おうとすると、突然消えてしまった。"
  },
  Event_7236_Name = {
    Text = "異常な連絡"
  },
  Event_7237_ChoiceDesc1 = {
    Text = "【離れる】すべての覚醒体がArg1狂気を獲得する"
  },
  Event_7237_Desc = {
    Text = "恐怖で目をぎゅっと閉じる。\n\n「君は覆いをめくった……\n秘密、君は秘密を見つけてしまった……」 \n\nその声の波が、喧騒の海となって押し寄せる。\n床が恐ろしい共振に揺れ、君の心音すらかき消しそうだった。\n\n耐えきれず、目を開けると、周りには何もない。"
  },
  Event_7237_Name = {
    Text = "終幕の儀Ⅴ"
  },
  Event_7238_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7238_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7238_Desc = {
    Text = "鼻先に懐かしい香りが漂い、家庭的で満足感を覚える。\n食堂の香りをもう一度嗅ごうとすると、その香りは跡形もなく消えてしまった。"
  },
  Event_7238_Name = {
    Text = "異常な連絡"
  },
  Event_7239_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7239_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7239_Desc = {
    Text = "耳元に聞き慣れた声が響き、親しみと安心感を与える。\n声を追おうとすると、突然止んでしまった。"
  },
  Event_7239_Name = {
    Text = "異常な連絡"
  },
  Event_7240_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7240_Desc = {
    Text = "追跡の力はしばらくの間、休憩所を見つけることができないが、少なくとも一時的な安らぎは得られた。"
  },
  Event_7240_Name = {
    Text = "異常な連絡"
  },
  Event_7241_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7241_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7241_Desc = {
    Text = "誰かの力強い手が肩に触れたような感覚があった。\nしかし振り返って探すと、その感触は幻のように消えてしまった。"
  },
  Event_7241_Name = {
    Text = "異常な連絡"
  },
  Event_7242_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7242_Desc = {
    Text = "「N」の影が拳風で散った。\n\n黒い微粒子は秘密の地の濃霧と一体化し、跡を追うのが難しい。\n\n「つれないじゃないか。まぁ、でも面白い奴だ。\n君との本当の対面を楽しみにしている……」"
  },
  Event_7242_Name = {
    Text = "ショーの始まり"
  },
  Event_7243_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7243_Desc = {
    Text = "「いい子ね。\nでも、少し罰を与えないとね」\n\nダフォダイルの軽やかな笑い声が次元の裂け目に消えていく。"
  },
  Event_7243_Name = {
    Text = "ヒントの時間"
  },
  Event_7244_ChoiceDesc1 = {
    Text = "【表】50%の確率で高級遺物「(RelicConfig.Arg2)」を獲得し、50%の確率で「(Skill.Arg3)」に感染する"
  },
  Event_7244_ChoiceDesc2 = {
    Text = "【裏】50%の確率で75黒章を獲得し、50%の確率で「(Skill.Arg3)」に感染する"
  },
  Event_7244_ChoiceDesc3 = {
    Text = "【黒いチップ】50%の確率で呪われた遺物「(RelicConfig.Arg2)」を獲得し、50%の確率で「(Skill.Arg3)」に感染する"
  },
  Event_7244_Desc = {
    Text = "いいね…いいね……\nさて、賭けたいチップを選んで。"
  },
  Event_7244_Name = {
    Text = "ショーの始まり"
  },
  Event_7245_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7245_Desc = {
    Text = "「まあまあ。\nあの人は次元を越える生き物に夢中なの。\n\n私も次元の穴を自由に行き来できるようになるまでに、大変な努力が必要だった。\n\nああ、たしか三千年前のことだったかしら？」"
  },
  Event_7245_Name = {
    Text = "ヒントの時間"
  },
  Event_7246_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7246_Desc = {
    Text = "研究主任が君の胸に爆弾を仕掛けるわけがない。"
  },
  Event_7246_Name = {
    Text = "不安のブローチ"
  },
  Event_7247_ChoiceDesc1 = {
    Text = "【離れる】指令カードを1枚削除し、25黒章を獲得する"
  },
  Event_7247_Desc = {
    Text = "「迷える者に正しい道を示す、善意の通りすがりの者ですよ」\n彼は不敵な笑みを浮かべた。\n\n「身軽に行動してください。\nケルベロスがあなたたちを待っています」\n\n手に持った指揮装置が突然震えた。"
  },
  Event_7247_Name = {
    Text = "奇妙な旅の伴Ⅲ"
  },
  Event_7248_ChoiceDesc1 = {
    Text = "【ゆっくりと移動する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7248_ChoiceDesc2 = {
    Text = "【身を伏せる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7248_Desc = {
    Text = "「沼に遭遇したら、絶対にもがくな」\nこの言葉を心に刻み、イースター島の像のように動かずにいる。\n\n五分、十分、一時間……黒い泥はついに忍耐を失い、足元から消えた。"
  },
  Event_7248_Name = {
    Text = "暗色の沼"
  },
  Event_7249_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7249_Desc = {
    Text = "あなたは一際目立つ手に気づく。\nそれは繊細で白く、終始落ち着いている。\n\nさらに重要なのは——それが自分の手だと気づいたこと。\n\nそっとそれを握った。\n\nその手もあなたを握り返す。\n刺すような冷たさと虚無を感じ、やがて沼地は消えた。"
  },
  Event_7249_Name = {
    Text = "暗色の沼"
  },
  Event_7250_ChoiceDesc1 = {
    Text = "【片手を切断する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7250_ChoiceDesc2 = {
    Text = "【それらをなだめる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7250_Desc = {
    Text = "手にした刃を振り回し、それらを次々と断ち切る。\n\nさまざまな血が体や顔、髪に飛び散るが、あなたは気にしない。\n\n無数の手が一斉に痛みの叫びを上げ、沼地は消え去った。\n\n一週間後になってようやく、悪夢でその泣き声を聞かなくなる。"
  },
  Event_7250_Name = {
    Text = "暗色の沼"
  },
  Event_7251_ChoiceDesc1 = {
    Text = "【シルバーコアを拾い上げる】1つの低級遺物を高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_7251_ChoiceDesc2 = {
    Text = "【召喚を試みる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」と「(Skill.Arg3)」に感染する"
  },
  Event_7251_ChoiceDesc3 = {
    Text = "【無視する】25黒章を獲得する"
  },
  Event_7251_Desc = {
    Text = "緩んだ甲板の木の下から、汚れた黒い液体が溢れ出している。\n\nその黒い液体の中で光るのは、あなたがよく知っている「シルバーコア」だ。"
  },
  Event_7251_Name = {
    Text = "存在の証明"
  },
  Event_7252_ChoiceDesc1 = {
    Text = "【鼠を選ぶ】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7252_ChoiceDesc2 = {
    Text = "【ロウソクを選ぶ】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7252_Desc = {
    Text = "融蝕生物が目の前で消え、黒く冷たい灰が霧に溶け込み、奇妙な天秤を空中に作り出す。\n天秤の一方には眠る鼠、もう一方には少年の形に彫られた蝋燭がある。\nあなたは直感的に、選択をしなければならないと感じた。"
  },
  Event_7252_Name = {
    Text = "理性と感情"
  },
  Event_7253_ChoiceDesc1 = {
    Text = "【声を出して探る】"
  },
  Event_7253_ChoiceDesc2 = {
    Text = "【こっそり後を追う】"
  },
  Event_7253_Desc = {
    Text = "ある角を曲がると、周囲のすべてがますますぼやけ、恐ろしい叫び声だけがはっきりと聞こえる。\n\n足音が響き、振り返ると奇妙な影が見えた。それは人のようであり、背後には対の影があり、一見すると巨大な蛾のようだった。\n\n「気をつけて」\nラモンナが低く警告する。\n\n「密境では、目に見えるものが真実とは限らない、無闇に追いかけると危険かもしれない」"
  },
  Event_7253_Name = {
    Text = "霧の中の影"
  },
  Event_7254_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7254_Desc = {
    Text = "あなたはシルバーキーを取り出し、哀切と敬虔を込めてその手に握り締める。\n\n淡い霧のような微光があなたを包む。\n\n一片の静寂の中、ただ、ため息だけが残る。"
  },
  Event_7254_Name = {
    Text = "凝視の眼"
  },
  Event_7255_ChoiceDesc1 = {
    Text = "【銀河の道を選ぶ】ランダムな指令カード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7255_ChoiceDesc2 = {
    Text = "【虹彩の道を選ぶ】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7255_Desc = {
    Text = "ドクン、ドクン。\n心臓が太鼓のように鳴り、喉が渇く。\n空からの視線が背骨を通り胸を貫く。\n目の前に分かれ道が現れ、一方は星の川が流れ、一方は虹色が輝く。"
  },
  Event_7255_Name = {
    Text = "星々の分岐点"
  },
  Event_7256_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7256_Desc = {
    Text = "いまだ残る視線があなたを注視し、皮膚の下では血肉の細胞が狂乱し、逃れようと悲鳴を上げる。\n\n血管は皮膚の下で這い回る虫のよう蠢く。\n\n得体の知れない力が流れ込むのを感じ、それは歪んだ四肢の異変と共鳴し、激しくほとばしる——"
  },
  Event_7256_Name = {
    Text = "凝視の眼"
  },
  Event_7257_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_7257_ChoiceDesc2 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_7257_ChoiceDesc3 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_7257_Desc = {
    Text = "「いや、そんなはずはない。\nゴキブリよりも、君たちは少なくともふわふわの体を持っている。\n\n誰もふわふわの体を拒めない」\n鼠たちはひそひそ話し、最終的にあなたの意見にしぶしぶ同意した。\n\n「まあまあ……実はそんなに毛は多くないけど」\n褒められるのはいつだって嬉しいものだ。\n離れる前に、鼠たちは小さな贈り物をくれた。"
  },
  Event_7257_Name = {Text = "ペスト"},
  Event_7258_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7258_Desc = {
    Text = "「賛成だ！人間と鼠は共存できない！」\n鼠たちは少し怒って、白い牙をむき出しにした。\n\n「じゃあ、ここで何してるんだ？物を持って行って、二度と戻ってくるな」"
  },
  Event_7258_Name = {Text = "ペスト"},
  Event_7259_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7259_Desc = {
    Text = "奇妙な羽音のような音が辺りに漂う。\nトランス状態の中、ビジョンが見える。\n\nロジャーズが人形のジョージを抱えて、診療台に横たわっている。その両手は血まみれだった。\n\n目を開けた時には、クレメンタインはすでに姿を消していた。"
  },
  Event_7259_Name = {
    Text = "催眠療法"
  },
  Event_7260_ChoiceDesc1 = {
    Text = "【開ける】鍵を使用する"
  },
  Event_7260_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7260_Desc = {
    Text = "扉が行く手を阻んでいる。\nあらゆる方法を試したが、びくともしない。"
  },
  Event_7260_Name = {Text = "扉"},
  Event_7260_Tips1 = {
    Text = "「扉の鍵」が必要です。"
  },
  Event_7261_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7261_Desc = {
    Text = "あなたは視線の源と思われる方向を見つめる。\n部屋の天井が突然高くなり、空間に巨大な瞳の虚像が重なり合う。\n\nたとえ一部しか見えなくても、圧倒的なプレッシャーを感じる。"
  },
  Event_7261_Name = {
    Text = "誰かの視線"
  },
  Event_7262_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7262_Desc = {
    Text = "黒猫が歩み寄り、あなたの手のひらに黒い塊を吐き出した。"
  },
  Event_7262_Name = {
    Text = "夜猫の災い"
  },
  Event_7263_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7263_Desc = {
    Text = "「うん、賢い選択ね。\n大敵を前にして、知己知彼を望むのは当然だものね？\nでも、次元の秘密を知りすぎると精神に影響が出るかもしれないわよ？」\n\n「あの人、次元を超える生物にいつも執着してるのよね。私も自由に次元の裂け目を行き来するのに苦労したわ。ああ、それは三千年前のことだったかしら？」"
  },
  Event_7263_Name = {
    Text = "ヒントの時間"
  },
  Event_7264_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7264_Desc = {
    Text = "「にゃあ、にゃあにゃあ、にゃあにゃあにゃあ……」\nあなたは声を絞って、できるだけ柔らかく無害に見せようとする。\n\n「にゃあ！にゃあにゃあ！にゃあにゃあにゃあ！」\n猫たちはあなたの善意を受け入れ、元気よく鳴き返す。\nあなたたちの鳴き声は絶え間なく続き、月も雲に隠れてしまうほどだ。"
  },
  Event_7264_Name = {Text = "猫の街"},
  Event_7265_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7265_Desc = {
    Text = "あなたはカラスが羽をちぎろうとするのを力いっぱい止めたが、カラスは執拗に頭をねじり、骨がきしむほどの力で抵抗した。\n\n顔を真っ赤にして全力でカラスの体を押さえ込み、その狂った自傷行為を止めた。\n\nほっとした瞬間、カラスの半分禿げた首が急に後ろにねじれ、体が力を失い、手の中で黒い濃い液体に変わった。"
  },
  Event_7265_Name = {
    Text = "融蝕液の涙"
  },
  Event_7266_ChoiceDesc1 = {
    Text = "【カラスを押さえつける】20黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7266_ChoiceDesc2 = {
    Text = "【放置する】離れる"
  },
  Event_7266_Desc = {
    Text = "孤独なカラスが、かすれた喉で鳴きながら、  \n自らの漆黒の羽根を一本ずつ引き抜いていく。  \n\n痛みに震え、鋭く叫ぶが、動きを止められない。\n\n「カァ——カァ——」\n\nその目からは黒い液体を伴った青い涙が流れる。  \nそれを目にしたのは、あなただけだった。"
  },
  Event_7266_Name = {
    Text = "融蝕液の涙"
  },
  Event_7267_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7267_Desc = {
    Text = "カラスが自らの羽をむしる様子は、人間が己の肉体をむさぼる姿に酷似している。  \n\nこの恐怖に満ちた世界では、よくある光景だ。\nあなたはすべての命を救えない。"
  },
  Event_7267_Name = {
    Text = "融蝕液の涙"
  },
  Event_7268_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7268_Desc = {
    Text = "「私は学生たちを連れて戻ってくる」少女は覚醒体のスカートの裾を掴み、確信を持って言った。\n「自分を大事にして…海に落ちないでね」"
  },
  Event_7268_Name = {
    Text = "航船の聖女の加護"
  },
  Event_7269_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7269_Desc = {
    Text = "はは、黒、私の大好きな黒。\n\n無秩序、混乱、苦痛……黒は良い兆しじゃないことを知っているはずだ。\n\nさて、次の選択は？"
  },
  Event_7269_Name = {
    Text = "ショーの始まり"
  },
  Event_7270_ChoiceDesc1 = {
    Text = "【カラスを押さえつける】25黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7270_ChoiceDesc2 = {
    Text = "【放置する】離れる"
  },
  Event_7270_Desc = {
    Text = "孤独なカラスが、かすれた喉で鳴きながら、  \n自らの漆黒の羽根を一本ずつ引き抜いていく。  \n\n痛みに震え、鋭く叫ぶが、動きを止められない。\n\n「カァ——カァ——」\n\nその目からは黒い液体を伴った青い涙が流れる。  \nそれを目にしたのは、あなただけだった。"
  },
  Event_7270_Name = {
    Text = "融蝕液の涙"
  },
  Event_7271_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7271_Desc = {
    Text = "それは長年修理されず、灯りも指針もない船室の奥深く。\n\n少女は航船の聖女の祝福を受けて出発する、これが彼女たちの約束。"
  },
  Event_7271_Name = {
    Text = "航船の聖女の加護"
  },
  Event_7272_ChoiceDesc1 = {
    Text = "【歌声を追う】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7272_ChoiceDesc2 = {
    Text = "【一緒に歌う】「(Skill.Arg1)」に感染し、再度ランダムに刻印する"
  },
  Event_7272_Desc = {
    Text = "遠くの歌声が星屑に砕け散る：\n「夜の路地の汚れた水たまりを呪う、崩れた壁の根元に腐った花が咲き、鎖が脳を泥沼に引きずり込む。\n濃霧が私の存在を消す前に、黄昏は最深部に沈む@3」"
  },
  Event_7272_Name = {
    Text = "白質の呪い"
  },
  Event_7273_ChoiceDesc1 = {
    Text = "【歌声を追う】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7273_Desc = {
    Text = "遠くの歌声が星屑に砕け散る：\n「夜の路地の汚れた水たまりを呪う、崩れた壁の根元に腐った花が咲き、鎖が脳を泥沼に引きずり込む。\n濃霧が私の存在を消す前に、黄昏は最深部に沈む@4」"
  },
  Event_7273_Name = {
    Text = "白質の呪い"
  },
  Event_7274_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7274_Desc = {
    Text = "シルバーコアは召喚に応じないが、温かい気配を放っている。"
  },
  Event_7274_Name = {
    Text = "孤独なシルバーコア"
  },
  Event_7275_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7275_Desc = {
    Text = "黒い霧が背骨を這い上がり、地面に倒れるまで、あなたはこの言葉を繰り返していた。"
  },
  Event_7275_Name = {
    Text = "見てはいけない"
  },
  Event_7276_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7276_Desc = {
    Text = "そう、瞳孔からゆっくりと流れ出る硝子体液……それこそが、あなたが禁忌に侵された証。\n\n今、正直であることは美徳に反する。"
  },
  Event_7276_Name = {
    Text = "見てはいけない"
  },
  Event_7277_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7277_Desc = {
    Text = "古びた硬貨の表面は粘り気を帯び、まるで穢れが吐き出した残滓のようだった。\n\nそこからは、肉眼で確認できるほどの黒い気が、ゆらゆらと立ちのぼっていた。"
  },
  Event_7277_Name = {
    Text = "古びた硬貨"
  },
  Event_7278_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7278_Desc = {
    Text = "鋭敏な末梢神経が致命的な警告を発し、あなたは身を震わせて、渋々手を引いた。\n\nまたしても、あなたは逃れたのだ……\n\nそれは呪いだったのか？\nそれとも、ひとつの再生だったのか？"
  },
  Event_7278_Name = {
    Text = "古びた硬貨"
  },
  Event_7279_ChoiceDesc1 = {
    Text = "【蝶を放す】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7279_ChoiceDesc2 = {
    Text = "【蝶になる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7279_ChoiceDesc3 = {
    Text = "【腹に収める】25黒章を獲得する"
  },
  Event_7279_Desc = {
    Text = "今夜は多くのことが起こった。\n\n埠頭での襲撃、幽霊船、海踊教団、トゥルー、マーフィー、ラモンナ……すべてが渦の中で回転し、ミサゴレストランの朝7時のオートミールのようにかき混ぜられた。\n\n覚醒体に質問したいが、どう切り出せばいいかわからず、喉に詰まった。"
  },
  Event_7279_Name = {
    Text = "バタフライ効果"
  },
  Event_7280_ChoiceDesc1 = {
    Text = "【幻影を払う】(Arg3)ライフを失う"
  },
  Event_7280_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7280_Desc = {
    Text = "ぼんやりとした顔が周囲に現れ、絶望的な呻き声をあげる。"
  },
  Event_7280_Name = {Text = "幻影"},
  Event_7281_ChoiceDesc1 = {
    Text = "【祈りに加わる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7281_ChoiceDesc2 = {
    Text = "【大海に沈む】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」「(Skill.Arg3)」に感染する"
  },
  Event_7281_ChoiceDesc3 = {
    Text = "【水面に浮かび上がる】25黒章を獲得する"
  },
  Event_7281_Desc = {
    Text = "「優しき神よ、至高の神よ。\n\nどうか凶悪な嵐を鎮め、急流を断ち切ってください。\n\n海を私たちの深い家とし、それを永遠のヴェールで覆ってください……」\n信者の囁きがついに理解できる言葉となったが、同時に逃れられない窒息感が襲う。"
  },
  Event_7281_Name = {
    Text = "夢の祈り"
  },
  Event_7282_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7282_Desc = {
    Text = "手に残った肉片を猫たちに投げる。\n\n猫たちは黒い波のように押し寄せ、狂ったように肉片を噛みちぎり、すぐに散っていく。\n\n残念ながら、それは賞味期限切れの肉だった。\n空腹は満たせても、あまり気分は良くない。"
  },
  Event_7282_Name = {Text = "猫の街"},
  Event_7283_ChoiceDesc1 = {
    Text = "【ポケットに入れる】"
  },
  Event_7283_Desc = {
    Text = "水銀に近い物質。\n\n融蝕液から抽出され、主に儀式で覚醒体を召喚するために使用される。"
  },
  Event_7283_Name = {
    Text = "シルバーコア"
  },
  Event_7284_ChoiceDesc1 = {
    Text = "【離れる】覚醒体を1体選択して覚醒させ、その霊知覚醒カードの行動力消費を2点減少させる。「(Skill.Arg1)」に感染する"
  },
  Event_7284_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7284_Desc = {
    Text = "今はまだ伝わらないかもしれないが、いずれ彼らはあなたたちの呼び声を聞くだろう。"
  },
  Event_7284_Name = {
    Text = "導きの声"
  },
  Event_7285_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7285_Desc = {
    Text = "さまよう実験体に疲れ果て、短い休息が砂漠のオアシスのように感じる。"
  },
  Event_7285_Name = {
    Text = "無限の扉"
  },
  Event_7286_ChoiceDesc1 = {
    Text = "【離れる】ランダムに覚醒体を1体覚醒させる"
  },
  Event_7286_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7286_Desc = {
    Text = "その声があなたたちを最終地点へ導き、この調査の答えを示すだろう。"
  },
  Event_7286_Name = {
    Text = "導きの声"
  },
  Event_7287_ChoiceDesc1 = {
    Text = "【注意深く観察する】"
  },
  Event_7287_Desc = {
    Text = "水晶玉を通して、遠くを観察できる"
  },
  Event_7287_Name = {Text = "水晶玉"},
  Event_7288_ChoiceDesc1 = {
    Text = "【カラスを追い払う】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7288_ChoiceDesc2 = {
    Text = "【無視する】離れる"
  },
  Event_7288_Desc = {
    Text = "カラスがクローゼットの上に留まり、鋭いくちばしで木の扉に不気味な模様を刻んでいる。"
  },
  Event_7288_Name = {
    Text = "提灯の黒いカラス"
  },
  Event_7289_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7289_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_7289_Name = {Text = "休憩所"},
  Event_7290_ChoiceDesc1 = {
    Text = "【ここに留まる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7290_ChoiceDesc2 = {
    Text = "【出口を探す】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7290_Desc = {
    Text = "あなたは青白い静寂の中に足を踏み入れた。\nそこでは重なり合った扉が際限なく回転し、渦のようにあなたの身体を巻き込む。\n\nあなたは目眩の中、逆さまの扉の中でもがいて、逃げ道を見定めようとするが、逃れられず、何度も別の扉へと落ちてしまう。\n\n今、あなたは再び一つの扉の前に立ち止まった。\n扉の向こうに湧き出る未知なるものは、致命的な魅力を放っている。\nしかし、あなたの理性の糸は張り詰めている。\n\nそうだ、それは確かに致命的だ。"
  },
  Event_7290_Name = {
    Text = "重なる扉の外"
  },
  Event_7291_ChoiceDesc1 = {
    Text = "【狂喜に陥る】指令カードを1枚削除し、Arg1ライフを回復する"
  },
  Event_7291_ChoiceDesc2 = {
    Text = "【立ち止まる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7291_Desc = {
    Text = "頭蓋骨を簡単にこじ開けられたように、脳内から吐き気を催す眩暈に襲われた。\n\n無形の手が脳をひっくり返してかき混ぜ、元々流動的になりつつあった物質は泥状に砕け散る。\n\n消化されていない粥状の胃腸内容物が、重力から解放され、あなたの空虚で貧弱な大脳皮質に逆流していくかのようだ。\n\nそれはこねられ、混ぜ合わされ、引っかかれる。\n細かく切り裂かれた歓喜が振りかけられ、落日の残滓を肉の中へと揉み込む。"
  },
  Event_7291_Name = {
    Text = "大脳撹拌"
  },
  Event_7292_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7292_Desc = {
    Text = "突然現れた地獄の番犬に比べれば、普通の雪はあなたの注意を引くに値しない。\n\nあなたはゆっくりと舞い降りる雪を無視し、暗闇へと駆け込む。"
  },
  Event_7293_ChoiceDesc1 = {
    Text = "【休憩】Arg2ライフを回復する"
  },
  Event_7293_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n通信機から誰かが呼んでいる。"
  },
  Event_7293_Name = {Text = "休憩所"},
  Event_7294_ChoiceDesc1 = {
    Text = "【恐れを感じる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7294_ChoiceDesc2 = {
    Text = "【意志を固める】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7294_Desc = {
    Text = "異様な哀号が絶え間なく響き渡るが、ロンディニウムの万物はそれに対し何の反応も示さず、まるで死んでいるか、眠っているかのようだ。\n\nあなたは無意識のうちに鉄道橋の下をさまよい、アリステアの忠告を思い出していた。\n\n彼は礼儀正しく立つと歩み寄り、何かをあなたに語りかけたが、言葉は粘ついて不明瞭だった。\n\nあなたが顔を上げると、彼の口から黒く濃い液体が溢れ、喉を塞ぎ、言葉を遮っている——"
  },
  Event_7294_Name = {
    Text = "混沌の哀号"
  },
  Event_7295_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_7295_Desc = {
    Text = "「もちろん、当然のことです。\nよろしければ、私も力になりましょう」\n\n彼は古びた手鏡を差し出した。\n\n「騎士はすでに盤上に登場しました。\n王も、後方で長く待つことはないでしょう。\n\nあなたたちはきっとすぐに彼に会えるでしょう。\n本当に楽しみですね」"
  },
  Event_7295_Name = {
    Text = "奇妙な旅の伴Ⅳ"
  },
  Event_7296_ChoiceDesc1 = {
    Text = "【手紙を破り捨てる】カードを2枚削除する"
  },
  Event_7296_ChoiceDesc2 = {
    Text = "【読書を続ける】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7296_ChoiceDesc3 = {
    Text = "【離れる】Arg1黒章を獲得する"
  },
  Event_7296_Desc = {
    Text = "目の前には噴き出す黒い蝶の群れがあり、彼らは絶えず溢れ、羽ばたき、再び机の上に落ちていく。\n\n広げられた白紙の便箋は墨で汚れ、傷ついた蝶たちは息も絶え絶えに便箋の上に横たわっている。\n\n羽に付着した黒い粘液が連なり、禁忌の文字として塗りつぶされている。\n\nあなたはタイプライターからこの便箋を引き抜いた。"
  },
  Event_7296_Name = {Text = "蝶の章"},
  Event_7297_ChoiceDesc1 = {
    Text = "【蝶に向き合う】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_7297_ChoiceDesc2 = {
    Text = "【もう引き返さない】"
  },
  Event_7297_Desc = {
    Text = "最近、ロンディニウムで流行っている言葉：「アクートの森で蝶が羽ばたけば、レオ王国で嵐が起こるかもしれない」\n\n蝶が舞い上がるのを見て、その言葉を思い出した。\n\nこれらの蝶は、惑星を飲み込む災厄を引き起こすかもしれない。"
  },
  Event_7297_Name = {
    Text = "霊知の嵐"
  },
  Event_7298_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7298_Desc = {
    Text = "唇に指を当て静止する。\n\n黒猫が幻のように通り過ぎ、足元に黒光りする贈り物を残した。"
  },
  Event_7298_Name = {
    Text = "夜猫の災い"
  },
  Event_7299_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7299_Desc = {
    Text = "それは絹のように滑らかに、あなたの鞄の中へと滑り込んだ。\n\nわずかな重さの増加と共に、かすかな感謝の声が聞こえた気がした。\n\nそれ以降、何の音も響くことはなかった。"
  },
  Event_7299_Name = {
    Text = "混沌の霊"
  },
  Event_7300_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7300_Desc = {
    Text = "混沌の霊の泣き声は次第に鋭さを増し、ついには耳をつんざく悲鳴となり、周囲に響き渡る。\n\nあなたからの供物と逃れられない悲しみを抱え、それは再び泥の深淵へと沈んでいった。"
  },
  Event_7300_Name = {
    Text = "混沌の霊"
  },
  Event_7301_ChoiceDesc1 = {
    Text = "【正直に記入する】"
  },
  Event_7301_ChoiceDesc2 = {
    Text = "【でたらめに書く】"
  },
  Event_7301_Desc = {
    Text = "東区の道は入り組んでいて、すぐに子供たちの姿を見失った。途方に暮れていると、謎の女性が話しかけてきた。\n\n「子供たちがどこに行ったか知ってるわ。でも、その前にちょっと手伝ってくれない？」\n彼女は紙を取り出し、親しげに微笑んだ。\n\n「私はクレメンタイン、精神科医よ。ロンディニウムの住民について調査しているの。もしこのアンケートに答えてくれたら、あなたと仲間を手助けするわ」"
  },
  Event_7301_Name = {
    Text = "心理評価"
  },
  Event_7302_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7302_Desc = {
    Text = "「これも私の選択だ」\nキャンディを持つ影が言う。\n「でも彼女は彼の手駒になり、あなたは選択を迫られる。完璧な結末など存在しない」\n\n深い悲しみがあなたを襲う。\n影は消え、あなたは胸を押さえる。さっきのものは、投影なのか、重圧下での幻覚なのか分からない。"
  },
  Event_7302_Name = {
    Text = "分かれ道"
  },
  Event_7303_ChoiceDesc1 = {
    Text = "【金の斧】"
  },
  Event_7303_ChoiceDesc2 = {
    Text = "【銀の斧】"
  },
  Event_7303_ChoiceDesc3 = {
    Text = "【私は何も落としていない】"
  },
  Event_7303_Desc = {
    Text = "「次元を超える先駆者よ」\n耳元に古びた声が聞こえる。\nそれは太古から来たようで、永遠を超えてきたようだ。\n\n極度の緊張の中、その声がどこかで聞いたことのある質問をしてきた。\n\n「君が落としたのは、この金の斧か、それともこの銀の斧か？」"
  },
  Event_7303_Name = {
    Text = "界外の音"
  },
  Event_7304_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7304_Desc = {
    Text = "「ああ、これは……」\n彼女はアンケートを回収し、少し困った表情を見せた。\n「まあいいわ、あなた急いでるものね。子供たちはあっちに行ったわ、そんなに遠くないはず」\n急いで離れるあなたは、背後のささやきをほとんど聞き逃した。\n「どうせ、また会うことになるわ」"
  },
  Event_7304_Name = {
    Text = "心理評価"
  },
  Event_7305_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7305_Desc = {
    Text = "「あなたは誰？」\n「私は殺されたシルバーキーの使い手の影だ。\n犯人は狡猾な白化蛇だ」\n\n「白化蛇？それは何？」\n「一つの過ち。人と蛇の交配により生まれた……冒涜的な存在」\n\nさらに追及しようとすると、影は突然消える。\nそれは金色の塵となった。"
  },
  Event_7305_Name = {
    Text = "シルバーキーの使い手"
  },
  Event_7306_ChoiceDesc1 = {
    Text = "【「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する】"
  },
  Event_7306_ChoiceDesc2 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7306_Desc = {
    Text = "事件355（開発中）、最終効果ではない"
  },
  Event_7306_Name = {
    Text = "事件355（開発中）"
  },
  Event_7307_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7307_Desc = {
    Text = "胃の中に沈み、蝶と共に舞う。\n\n思考の鱗粉と蝶が交じり合い、胃の中に白い雪が降り積もる。\n\nすべてを整理し、次の機会が来たら必ず言おう。"
  },
  Event_7307_Name = {
    Text = "バタフライ効果"
  },
  Event_7308_ChoiceDesc1 = {
    Text = "【それらに反論する】「(Skill.Arg1)」に感染し、ランダムなカード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_7308_ChoiceDesc2 = {
    Text = "【それらに同調する】「(Skill.Arg1)」に感染し、ランダムなカード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_7308_ChoiceDesc3 = {
    Text = "【新しい観点を提示する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7308_Desc = {
    Text = "「どうか私たちに近づかないでください」\n群れをなす鼠があなたを中心に囲み、少なくとも五フィートの距離を保っている。\n\n「私たちは繁殖し、成長し、食べ物を選ばない——だから人間に病気、不安、苦痛をもたらす」\n「私たちと人間は近づきすぎるべきではない、ここはあなたの来るべき場所ではない」\n鼠たちの警戒を解くため、あなたは決めた——"
  },
  Event_7308_Name = {Text = "ペスト"},
  Event_7309_ChoiceDesc1 = {
    Text = "【鉄の扉を開ける】「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7309_ChoiceDesc2 = {
    Text = "【気にしない】50黒章を獲得する"
  },
  Event_7309_Desc = {
    Text = "これは典型的な下承式アーチ橋で、鉄道の横にある階段が鉄門へと続いている。\n門の向こうから規則的で異常な音が聞こえる。\n\nあなたは門を観察し、重い掛け錠がかかっているが、閉じられていないことに気づく。"
  },
  Event_7309_Name = {
    Text = "鉄門の向こう"
  },
  Event_7310_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染し、50黒章を獲得する"
  },
  Event_7310_Desc = {
    Text = "誘惑に動じず。\n声の主は残念に思い、水面にいくつかの波紋が気だるげに広がり、再び静かになった。"
  },
  Event_7310_Name = {
    Text = "界外の音"
  },
  Event_7311_ChoiceDesc1 = {
    Text = "【「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する】"
  },
  Event_7311_ChoiceDesc2 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7311_Desc = {
    Text = "事件353（開発中）、最終効果ではない"
  },
  Event_7311_Name = {
    Text = "事件353（開発中）"
  },
  Event_7312_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染し、50黒章を獲得する"
  },
  Event_7312_Desc = {
    Text = "「お前たち人間には他に答えがないのか？」\n声の主が苛立ちの低い唸りを上げ、空間全体が震えた。\n\n「貪欲で無知……それが私がお前たちを嫌う理由だ」"
  },
  Event_7312_Name = {
    Text = "界外の音"
  },
  Event_7313_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7313_Desc = {
    Text = "密境の計らいを受け入れ、得ることで失い、呪われた抱擁を享受する。"
  },
  Event_7313_Name = {
    Text = "妄念の噴出"
  },
  Event_7314_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7314_Desc = {
    Text = "目がゆっくりと瞬く。\nあなたの質問を理解したかどうかはわからない。\n\n金と赤が混ざった涙が目尻からこぼれ、小さな星のように太陽のような暖かい光を放つ。\n\nそれは悲しみと哀れみを伴い、レンガの上で小さな塵に砕けた。\n\nあなたが我に返ると、その目はもう消えていた。"
  },
  Event_7314_Name = {
    Text = "盲目の注視"
  },
  Event_7315_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7315_Desc = {
    Text = "簡素な服装の少し汚れた子供たちが通りを走り、その後ろを警官の服を着た大人が追いかける。\n\n見覚えのある、茶色のフードの子供がいた。"
  },
  Event_7315_Name = {
    Text = "私たちの記憶"
  },
  Event_7316_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7316_Desc = {
    Text = "「もう歌わないで——」\n音痴の歌手に警告し、耳をこれ以上苦しめないで。"
  },
  Event_7316_Name = {
    Text = "狭路の悪党"
  },
  Event_7317_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7317_Desc = {
    Text = "「踊りを止めろ！！！融蝕の怪物の方がましな踊りをする！」\n観客を解放して……\n心の中でそう祈る。"
  },
  Event_7317_Name = {
    Text = "狭路の悪党"
  },
  Event_7318_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7318_Desc = {
    Text = "黒い液体が顔に滴り、かゆみを感じる。\n\n耐えられず、手を伸ばして蝶を払いのける。\n\n蝶はあなたの手をかわし、静かに消えていった。"
  },
  Event_7318_Name = {
    Text = "存在しないはずのもの"
  },
  Event_7319_ChoiceDesc1 = {
    Text = "【それを褒める】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7319_Desc = {
    Text = "ジェンキンが言う：目を覚ませ、ジョニー！詩を書いても借金は返せないし、家の床の水漏れも解決しないよ。\n\n君が言う：残念ながら、君の真理を追求する細胞は毎日10万個の速度で枯れていく。\nすぐに君は本当の脳幹になるよ。\n\n脳が言う：我思う、故に我あり。\n私のような思考の深さに達すれば、脳幹なんて気にしなくなるよ。"
  },
  Event_7319_Name = {
    Text = "哲学の脳"
  },
  Event_7320_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7320_Desc = {
    Text = "ピアノがそっとため息をつく。\nそれは慰めのようでもあり、体残惜しさのようでもあり、まるで誰かが曲の終わりに微笑むかのようだ。\n\n「子どもたちさえ……子どもたちさえ……」\n聞き取る間もなく、ピアノの幻影は風に消えた。"
  },
  Event_7320_Name = {
    Text = "幼少期のメロディ"
  },
  Event_7321_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ低級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7321_Desc = {
    Text = "あなたは厚いカルテを受け取り開くと、扉ページに「G・R」と書かれているのを見つけた。\n\n「あらあら、これはあなたのカルテじゃないわ」\n\nクレメンタインは気にする様子もない。\n\n「他人の心理を研究するのも、自分を知る手助けになるわよ」\n\n質問する間もなく、彼女の姿は完全に消えた。"
  },
  Event_7321_Name = {Text = "カルテ"},
  Event_7322_ChoiceDesc1 = {
    Text = "【離れる】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染する"
  },
  Event_7322_Desc = {
    Text = "あなたは薄いカルテを受け取る。\n中には一枚の紙があり、そこには一文だけが書かれていた。\n\n「古代の混沌の中で、蒼白の無目の眼が永遠に見つめている」\n\nクレメンタインに尋ねようとしたが、彼女はすでに姿を消していた。"
  },
  Event_7322_Name = {Text = "カルテ"},
  Event_7323_ChoiceDesc1 = {
    Text = "【休憩】全ライフを回復する"
  },
  Event_7323_ChoiceDesc2 = {
    Text = "【瞑想】覚醒体を1体選択して覚醒させる"
  },
  Event_7323_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n通信機から誰かが呼んでいる。"
  },
  Event_7323_Name = {Text = "休憩所"},
  Event_7324_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7324_Desc = {
    Text = "重要な証拠は、歴史学部に保存して解析してもらうのが良い。"
  },
  Event_7324_Name = {
    Text = "密命・上"
  },
  Event_7325_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7325_Desc = {
    Text = "太陽が高く昇り、地を照らし、迷いを突き破り、疲れた魂を召喚する。"
  },
  Event_7326_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7326_Desc = {
    Text = "あなたは満たされる感覚を覚えた。\n神々の視線が夜空に輝き、焦点をあなたに合わせている。"
  },
  Event_7326_Name = {
    Text = "穹頂の瞳"
  },
  Event_7327_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7327_Desc = {
    Text = "逃れる方法など、ありはしない視線。\n当然、神々の贈り物を拒む事などできない。"
  },
  Event_7327_Name = {
    Text = "穹頂の瞳"
  },
  Event_7328_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7328_Desc = {
    Text = "「あなたは一体何者ですか？」\nあなたは驚いて尋ねる。\n\n「そんなこと気にする必要はありませんよ。\n敵の敵は味方、そうでしょう？」\nそういって、男は微笑んだ。\n\n「贈り物を、座席に置いておきました。\n幸運を祈ります」"
  },
  Event_7328_Name = {
    Text = "奇妙な旅の伴Ⅳ"
  },
  Event_7329_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7329_Desc = {
    Text = "ラモンナは「白衣」についてもっと聞きたいと身を乗り出して言った。\n\n 「誰かが盗み聞きしてる！」\n蓄音機から鳴っていた声が急に大きくなった。\n\n 「盗み聞き、盗み聞き、盗み聞き！」"
  },
  Event_7329_Name = {Text = "噂話"},
  Event_7330_ChoiceDesc1 = {
    Text = "【離れる】すべての覚醒体がArg1狂気を獲得する"
  },
  Event_7330_Desc = {
    Text = "あなたは男の子の柔らかい手を引き、いくつもの扉を通り抜け、ついに小さな古びた舞台の前にたどり着く。\n\n男の子はあなたの手を握り、感謝の意を示す。\n「ありがとう、さようなら」"
  },
  Event_7330_Name = {
    Text = "終幕の儀Ⅱ"
  },
  Event_7331_ChoiceDesc1 = {
    Text = "【墜落を続ける】低級遺物「(RelicConfig.Arg1)」を獲得する。引き続き墜落しますか"
  },
  Event_7331_ChoiceDesc2 = {
    Text = "【手を引いて離れる】25黒章を獲得する"
  },
  Event_7331_Desc = {
    Text = "「あなた」があなたを招いている。\n\n螺旋の奥で、過去と未来の「あなた」が異なる次元からの「贈り物」を送ってきた。"
  },
  Event_7331_Name = {
    Text = "螺旋の深淵"
  },
  Event_7332_ChoiceDesc1 = {
    Text = "【口を固く閉ざす】25黒章を獲得する"
  },
  Event_7332_ChoiceDesc2 = {
    Text = "【手を伸ばし触れる】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_7332_Desc = {
    Text = "「私が言えるのは、ただひとつの格言——誰にも猫を殺すことはできない！」\n\n「あの忌まわしい黒猫は、本来ならば腹を裂かれ、荒野に晒されるべきだった。\n\nだが、奴は私の一族の墓を掘り起こし、残された人間の腐肉を貪り尽くした。\n\n骨と四肢は無惨にも散らばっていたのだ」\n\n「冷たく暗い縦長の瞳がこちらを見つめていた。\n\n黄ばんだ膿が悪臭を放ち、私は必死に転がるように逃げ出したんだ。\n\n毎夜悪夢に苛まれ、正気がすり減っていくんだ」\n\n「待て……何をするつもりだ！？\n\n私は狂ってなどいない！違う！お前たちは何かを隠そうとしている！これは真実だ——」\n\n——確かに、それは真実だった。\n\n狂気じみた影が闇へと消えゆくのを見送りながら、あなたは足元で静かに座る黒猫と目を合わせた。"
  },
  Event_7332_Name = {
    Text = "夜猫の災い"
  },
  Event_7333_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7333_Desc = {
    Text = "あなたは彼に蝋人形館の場所を尋ねる。\n奇妙なことに、今夜はこれで5回目の出会いだ。\n\nあなたは彼に5回火を貸し、5回道を尋ねた。\nけれど蝋人形館の場所は一向に思い出せない——\nまるで、あなたが彼と繰り返し出会い続けるのと同じように。"
  },
  Event_7333_Name = {
    Text = "街灯の下の影"
  },
  Event_7334_ChoiceDesc1 = {
    Text = "【カラスを追い払う】25黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7334_ChoiceDesc2 = {
    Text = "【子供を追い続ける】離れる"
  },
  Event_7334_Desc = {
    Text = "三羽目のカラスが去り、視線の届かない場所へ、永遠の闇へと飛んでいった。"
  },
  Event_7334_Name = {
    Text = "黒いカラスの視線"
  },
  Event_7335_ChoiceDesc1 = {
    Text = "【離れる】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7335_Desc = {
    Text = "触腕の毛皮は柔らかく滑らかで、クムの生命の温もりがまだ残っている。\n\nそれは日没前の夕陽のように、瞬く間に消えてしまう。"
  },
  Event_7335_Name = {Text = "余熱"},
  Event_7336_ChoiceDesc1 = {
    Text = "【追いかける】"
  },
  Event_7336_Desc = {
    Text = "壁面を注意深く探すと、草むらの後ろに隠された下水道の入口を見つける。\n\n下水道をくぐるが怪物はすでに遠く逃げている。"
  },
  Event_7336_Name = {
    Text = "行き止まり"
  },
  Event_7337_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7337_Desc = {
    Text = "鳥たちには、彼らのルールがある。\n\nあなたの意志に従って行動するわけではないし、あなたも自然の法則に干渉することもできない。"
  },
  Event_7337_Name = {
    Text = "群れから離れたカラス"
  },
  Event_7338_ChoiceDesc1 = {
    Text = "【映り込みを見下ろす】25黒章を獲得する"
  },
  Event_7338_ChoiceDesc2 = {
    Text = "【元気かい？】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7338_Desc = {
    Text = "「ねえ、知ってる？\n隣に来た新しい女主人、いつも閉じこもってるんだ……その日、彼女にビールを一杯おごったんだけど、泡が完全に消えた後、突然気づいたんだ……グラスの中の彼女、影がないんだ！」"
  },
  Event_7338_Name = {
    Text = "記憶の破片・ビール"
  },
  Event_7339_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7339_Desc = {
    Text = "「もう一度一緒に歌いたい……」\n\nサラの歪んだ悲鳴が突然止まり、変形した顔に一瞬の戸惑いが浮かぶ。"
  },
  Event_7339_Name = {
    Text = "「サラ姉さん」"
  },
  Event_7340_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7340_Desc = {
    Text = "「嬉しい！嬉しい！」\n騒がしくも純真な声が耳元で響く。\n\n「あげる、あげるよ！」"
  },
  Event_7340_Name = {
    Text = "夜の精霊"
  },
  Event_7341_ChoiceDesc1 = {
    Text = "【分厚いカルテ】"
  },
  Event_7341_ChoiceDesc2 = {
    Text = "【薄いカルテ】"
  },
  Event_7341_Desc = {
    Text = "どこかで聞いたことのある声があなたを呼び止めるが、目を細めても彼女の姿が見えない。\n\n「急いでるのはわかってるわ」\n\nクレメンタイン医師は軽快な口調で言った。\n\n「長くは引き留めないから」\n\n霧の中から両手が現れる。\nそれぞれにカルテが一冊ずつ。\n片方は厚くて擦り切れており、もう片方は薄くて新しい。\n\n「アンケートの結果に基づいて、勝手にカルテを作ったの。\nでも、どっちがあなたのか忘れちゃったから、選んでみて？」\n\nなぜか、薄いカルテからは覚醒体との精神的な繋がりを感じる。"
  },
  Event_7341_Name = {Text = "カルテ"},
  Event_7342_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7342_Desc = {
    Text = "普通の壁だが、叩くと中が空洞のように感じる。"
  },
  Event_7342_Name = {
    Text = "奇妙な壁"
  },
  Event_7343_ChoiceDesc1 = {
    Text = "【また水面にいない】ランダムな低級遺物1つを高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_7343_ChoiceDesc2 = {
    Text = "【うつむいて確認する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7343_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7343_Desc = {
    Text = "「ふふ、守秘者、ウインクルの忠告を覚えてる？聞いて、正午に自分の影を見下ろしちゃダメだよ」"
  },
  Event_7343_Name = {
    Text = "無形の影"
  },
  Event_7343_Tips1 = {
    Text = "まだ低級遺物を所持していません。"
  },
  Event_7344_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7344_Desc = {
    Text = "遥か未来からの幻影が、アイズルワースの山間に消えた。"
  },
  Event_7344_Name = {
    Text = "火山の幻影"
  },
  Event_7345_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7345_Desc = {
    Text = "蝶があなたの手のひらで砕け散る。\n\nそれはまるでガラスの天井が突然砕けたように、欠片が重力に引かれて落ちていく、落ちていく、落ちていく——"
  },
  Event_7345_Name = {
    Text = "鋼橋の幻覚"
  },
  Event_7346_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7346_Desc = {
    Text = "彼らが影から現れるのを待とう。"
  },
  Event_7346_Name = {
    Text = "提灯の黒いカラス"
  },
  Event_7347_ChoiceDesc1 = {
    Text = "【スイッチを入れる】現在の視野を広げる"
  },
  Event_7347_Desc = {
    Text = "先人が残した照明装置で、周囲の黒い霧を払うことができる。"
  },
  Event_7347_Name = {
    Text = "サーチライト"
  },
  Event_7348_ChoiceDesc1 = {
    Text = "【問題を指摘する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7348_ChoiceDesc2 = {
    Text = "【疑問を飲み込む】「(Skill.Arg1)」に感染し、再刻印を最大2回まで行う"
  },
  Event_7348_Desc = {
    Text = "今に至るまで、あなたはマーフィーが語った過去を思い返していた。\n\nその過去はあなたに共感を覚えさせ、あなたの脳を強く縛り付け、圧迫する。\n\n最後にゴリアテがマーフィーを慰めた言葉さえ、あなたには慰めにならなかった。\n\n……待てよ、彼らは言った。\n次の星辰正しき刻は25年後だと……\nしかし、目の前のマーフィーは、明らかにまだ子供ではないか……"
  },
  Event_7348_Name = {
    Text = "囚われた命"
  },
  Event_7349_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ低級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7349_Desc = {
    Text = "彼女は泣くべきだった、彼女ほど泣く資格のある者はいない。\n\nでも、なぜ彼女は泣かないのか？なぜ彼女は他人事のように振る舞うのか、まるで彼女に跪いているのではないかのように……"
  },
  Event_7349_Name = {
    Text = "航前の儀式"
  },
  Event_7350_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7350_Desc = {
    Text = "どんな場合でも、他人のプライバシーを探ることは礼儀に反する行為だ。"
  },
  Event_7350_Name = {
    Text = "お手紙拝見"
  },
  Event_7351_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7351_Desc = {
    Text = "きっと一時的な錯覚だ。"
  },
  Event_7351_Name = {
    Text = "黒いカラスの視線"
  },
  Event_7352_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_7352_Desc = {
    Text = "記憶の中で皆が彼女に祈り、哀願している。\nあなたも思わず心の中でつぶやいてしまう……"
  },
  Event_7352_Name = {
    Text = "航前の儀式"
  },
  Event_7353_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7353_Desc = {
    Text = "黒猫の下から黒い粘液が滴り、粘液の小川が路地の下水道へと続いている。\n\n近づく気配がないと見るや、黒猫は振り返って下水道に飛び込み、姿を消した。"
  },
  Event_7353_Name = {
    Text = "夜の精霊"
  },
  Event_7354_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7354_Desc = {
    Text = "あなたは恐怖で叫び声を上げる。\n\nその声に惑わされたのか、焦っていた手が一瞬ためらう。\n\nその隙をついてすぐに逃げ出した。"
  },
  Event_7354_Name = {
    Text = "暗色の沼"
  },
  Event_7355_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7355_Desc = {
    Text = "ねじれ、蠢き、這い寄る……あなたはあらゆる手段を尽くしてこれらの厄介な腕から逃れようとする。\n\n最終的に逃げ出すことはできたが、新しい制服一式、肋骨二本、そして数百本の髪を失った。"
  },
  Event_7355_Name = {
    Text = "暗色の沼"
  },
  Event_7356_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7356_Desc = {
    Text = "「普通のことよ、驚かないで、まるで新人みたいに」\nドールが近づき、ブローチの位置を直してくれる。\n「近くに特殊な次元の通路があるってことね。\nどうやら精神病院の方向にあるみたいよ」"
  },
  Event_7356_Name = {
    Text = "不安のブローチ"
  },
  Event_7357_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7357_Desc = {
    Text = "提灯教会の餌を受け入れる理由はない。\n\nカラスは不満げに汚れた恐ろしい頭を揺らし、墓場でしか聞けないような声を上げて飛び去った。"
  },
  Event_7357_Name = {
    Text = "呪われた怪鳥"
  },
  Event_7358_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7358_Desc = {
    Text = "「これも私の選択だ」クマを抱える影が言う。\n「でも彼女は彼の操り人形になり、彼らはみんな死ぬ。あなたはその罪深い共犯者になる」\n\n強烈な罪悪感があなたを襲う。\n影は消え、あなたは胸を押さえる。さっきのものは、投影なのか、重圧下での幻覚なのか分からない。"
  },
  Event_7358_Name = {
    Text = "分かれ道"
  },
  Event_7359_ChoiceDesc1 = {
    Text = "【引き続き耳を塞ぐ】狂気値が最も高い覚醒体の狂気値と同数の黒章(Arg1)を獲得する"
  },
  Event_7359_ChoiceDesc2 = {
    Text = "【引き続き耳を塞ぐ】(Arg1)ライフを回復する。所持している黒章の量で回復量が増加する"
  },
  Event_7359_Desc = {
    Text = "耳元の悪意ある囁きに従ったとたん、針のような鋭い叫びがねじれながら耳孔に刺さってきた。\n「やめて――早くやめて――言われた通りにしたじゃないか――やめ――」\n苦しみながら頭を抱えると、ぼんやりとした意識の中でカラスの群れの嘲笑が聞こえた。"
  },
  Event_7359_Name = {
    Text = "カラスの群の歌"
  },
  Event_7360_ChoiceDesc1 = {
    Text = "【カラスを1羽捕まえる】覚醒している覚醒体1人につき25黒章を獲得する"
  },
  Event_7360_ChoiceDesc2 = {
    Text = "【金切り声を上げる】覚醒体を1体選択して覚醒させ、その霊知覚醒カードに「固有」と「保留」効果を追加する"
  },
  Event_7360_Desc = {
    Text = "あなたは遊び心が湧き、一羽のカラスを掴んだ。\n\nそれはあなたの手の中で最後の抵抗をし、最終的に温かい水の塊となって弾けた。"
  },
  Event_7360_Name = {
    Text = "カラスの群の歌"
  },
  Event_7361_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7361_Desc = {
    Text = "あなたは耳を塞ぎ、目を閉じる。\n\nドンドン、ドンドン……心臓の鼓動と叫び声が交錯し、混乱の死の歌を奏でる。\n\nこの瞬間、あなたはかつてない静けさを感じる。"
  },
  Event_7361_Name = {
    Text = "カラスの群の歌"
  },
  Event_7362_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7362_Desc = {
    Text = "密境は危険がいっぱい。\nすべての光が道しるべとは限らない。\n\nそれは蛾を誘う灯火かもしれない。"
  },
  Event_7362_Name = {
    Text = "暗夜の蛍光"
  },
  Event_7363_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7363_Desc = {
    Text = "「あなたはとっくに死んでいる、家にも帰れない。」 あなたの声は、ロスの雪原を吹き抜ける風のうなりのように冷酷だった。 旅人のかおもじには何の変化もなく、まるでそれが当然のことであるかのようだった。彼は再びあなたの手を掴み、「助けて。 私はソルジャーで、命を受けて遥か東方へ向かっていた…………」"
  },
  Event_7363_Name = {
    Text = "呑み込む者"
  },
  Event_7364_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7364_Desc = {
    Text = "電報機は壊れている。\n嵐の中で電報機の持ち主が感じた絶望が想像できた……今のあなたも同じだ。"
  },
  Event_7364_Name = {
    Text = "無声の電報"
  },
  Event_7365_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7365_Desc = {
    Text = "「50ヤード進んで左に曲がり、それから右、また左……そして突き当たりまで行けば、家がある」\n旅人はとても嬉しそうだ。\n\n彼はあなたに手を振り、そのまま去っていった。\n\nあなたは大きく息をつき、突然誰かが手を掴むのを感じる。\n耳元で再びあの声が響く――\n「助けてください。\n私は兵士で、遠い東方へ異教徒を討伐する命を受け……」"
  },
  Event_7365_Name = {
    Text = "呑み込む者"
  },
  Event_7366_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7366_Desc = {
    Text = "ついにこの迷宮を抜け出した。\nその瞬間、蝋人形館が生きていることに気づく。\n\nすべての怪異、美しさ、残酷さが古の儀式で結びついている。\nそして、その儀式の目こそが、ロジャーズだ。"
  },
  Event_7366_Name = {
    Text = "眼の迷宮"
  },
  Event_7367_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7367_Desc = {
    Text = "「ロールプレイは楽しいかしら、守秘者？」\nラモンナがあなたの袖を引っ張る。\n「出口はもうすぐ。\nダフォダイル夫人の前でもこのユーモアを保てるといいわね」"
  },
  Event_7367_Name = {
    Text = "記憶の断片・昔の夢が甦る"
  },
  Event_7368_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7368_Desc = {
    Text = "「覚醒体はリンク者の意志に逆らうのが難しい」\n\nあなたは答えた。\n「でも、私たちは諦めない」"
  },
  Event_7368_Name = {
    Text = "彼女の選択"
  },
  Event_7369_ChoiceDesc1 = {
    Text = "【進む】壁を通り抜け、奥を探る"
  },
  Event_7369_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7369_Desc = {
    Text = "壁に近づくと、壁面が突然歪み、吸い込まれそうになる。"
  },
  Event_7369_Name = {
    Text = "歪んだ空間"
  },
  Event_7370_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7370_Desc = {
    Text = "「いや、そんなはずはない。\nゴキブリよりも、君たちは少なくともふわふわの体を持っている。\n\n誰もふわふわの体を拒めない」\n鼠たちはひそひそ話し、最終的にあなたの意見にしぶしぶ同意した。\n\n「まあまあ……実はそんなに毛は多くないけど」\n褒められるのはいつだって嬉しいものだ。\n離れる前に、鼠たちは小さな贈り物をくれた。"
  },
  Event_7370_Name = {Text = "ペスト"},
  Event_7371_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7371_Desc = {
    Text = "「賛成だ！人間と鼠は共存できない！」\n鼠たちは少し怒って、白い牙をむき出しにした。\n\n「じゃあ、ここで何してるんだ？物を持って行って、二度と戻ってくるな」"
  },
  Event_7371_Name = {Text = "ペスト"},
  Event_7372_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_7372_Desc = {
    Text = "深海の下へようこそ。\nここでは一歩ごとに重圧がかかる。\n\n光を通さない混沌の霧がすべてを隠している。\nこの重圧の中、光のない海を越えられるか？"
  },
  Event_7372_Name = {Text = "潮の下"},
  Event_7373_ChoiceDesc1 = {
    Text = "【適当に見る】カードを1枚削除する"
  },
  Event_7373_ChoiceDesc2 = {
    Text = "【よく見る】「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7373_Desc = {
    Text = "「カタカタ……」\nそのタイプライターは、ウイスキーを飲みすぎた酔っ払いのように、黒いインクをゆっくりと吐き出した。\n\nあなたは「メイソン」という文字を鋭く見つけ、すぐにタイプ用紙を引き抜いた。"
  },
  Event_7373_Name = {
    Text = "タイプライター"
  },
  Event_7374_ChoiceDesc1 = {
    Text = "【眼を直視する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7374_ChoiceDesc2 = {
    Text = "【眼を閉じる】ランダムな覚醒体を2体選択して覚醒させ、2枚の「(Skill.Arg1)」に感染する"
  },
  Event_7374_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7374_Desc = {
    Text = "無数の眼があなたの耳元で囁く。\n「我々は旅をし、立ち止まり、幾億年、いやそれ以上の時間を駆け抜けてきた。\n太陽がその眼差しの中で、少しずつ光を失い、旧地球の生命が洪水に飲まれるとき——\n我々はすでに宇宙の神秘に深く心奪われていた」"
  },
  Event_7375_ChoiceDesc1 = {
    Text = "【指示に従う】最大ライフをArg1増加させる"
  },
  Event_7375_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7375_Desc = {
    Text = "シルバーキーの追跡力で休憩所を探そうとしたが、得られた情報には微妙な異常が混じっており、何かに妨害されているようだ。"
  },
  Event_7375_Name = {
    Text = "異常な連絡"
  },
  Event_7376_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7376_Desc = {
    Text = "ミサゴ学生セットのハンカチでタイプライターの表面を優しく拭く。\n\nタイプライターは再び静かになった。\n汚れたハンカチは…密境に置いておこう。"
  },
  Event_7376_Name = {
    Text = "タイプライターの囁き"
  },
  Event_7377_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7377_Desc = {
    Text = "じっと見つめると、重なったインクの痕から、名前がかすかに浮かび上がった。\n\n「Fingal Johansen」\n\nこれは誰だ？"
  },
  Event_7377_Name = {
    Text = "タイプライターの囁き"
  },
  Event_7378_ChoiceDesc1 = {
    Text = "【顔を上げ直視する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_7378_ChoiceDesc2 = {
    Text = "【太陽の仰角？】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染する"
  },
  Event_7378_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7378_Desc = {
    Text = "「今すぐ、東南の空を見上げて。\n太陽の仰角がそこにある」\n通信機からドールの指示が聞こえる。"
  },
  Event_7379_ChoiceDesc1 = {
    Text = "【「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する】"
  },
  Event_7379_ChoiceDesc2 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7379_Desc = {
    Text = "事件354（開発中）、最終効果ではない"
  },
  Event_7379_Name = {
    Text = "事件354（開発中）"
  },
  Event_7380_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7380_Desc = {
    Text = "子供たちの声が鍵盤の下から流れ出る。\n「チャーリーの、大事な大事なトラ猫ちゃん……」\n子供たちの歌声の下で、若い女性の声も優しく歌っている。\n聞き間違いだろうか？"
  },
  Event_7380_Name = {
    Text = "幼少期のメロディ"
  },
  Event_7381_ChoiceDesc1 = {
    Text = "【振り向く】25黒章を獲得する"
  },
  Event_7381_ChoiceDesc2 = {
    Text = "【前進し続ける】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7381_Desc = {
    Text = "背後から足音が聞こえる。\n影のようにゆっくりと焦らずに。\n\nあなたの足音と交じり合い、広い展示室に響き渡る。"
  },
  Event_7381_Name = {Text = "革靴"},
  Event_7382_ChoiceDesc1 = {
    Text = "【手紙をしまう】カードを2枚削除する"
  },
  Event_7382_ChoiceDesc2 = {
    Text = "【手紙を残す】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7382_ChoiceDesc3 = {
    Text = "【離れる】Arg1黒章を獲得する"
  },
  Event_7382_Desc = {
    Text = "新型タイプライター。\nそれは顕微鏡のように繊細で精巧な、他とは違う独特な文字キーが備わっていた。\n\nあなたがその完璧な機械構造に夢中になっていると、黒い文字が突然現れる。\n\n「親愛なるロジャーズ様、\n我々は重い気持ちでお知らせいたします。\nあなたは学院から退学処分を受けました」\n\n「ご存知の通り、@2学院は厳格な学問態度で王国内で知られています。\nあの驚くべき@3の噂が深く我々を悩ませて……」"
  },
  Event_7382_Name = {
    Text = "お手紙拝見"
  },
  Event_7383_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7383_Desc = {
    Text = "遠くの止まった懐中時計が何かを急かすように、時空の罠に陥らないように警告している。"
  },
  Event_7383_Name = {
    Text = "彼の神の視線"
  },
  Event_7384_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7384_Desc = {
    Text = "黒い液体が顔に滴り、かゆみを感じる。\n耐えられず、手を伸ばして蝶を払いのける。\n\n蝶はあなたの手をかわし、静かに消えていった。"
  },
  Event_7384_Name = {
    Text = "黒い液体の蝶"
  },
  Event_7385_ChoiceDesc1 = {
    Text = "【注意深く観察する】"
  },
  Event_7385_ChoiceDesc2 = {
    Text = "【掘り起こす】"
  },
  Event_7385_Desc = {
    Text = "クムはあなたたち3人を背負って精神病院内の入口を探している。\n\n突然、急ブレーキをかけ、あなたたちは背から落ちそうになった。\n\n疑問の声を上げると、クムは頭を下げ、柔らかい土の上を嗅ぎ回り、何かが埋まっていることを示すように振り返った。"
  },
  Event_7385_Name = {
    Text = "埋もれた物"
  },
  Event_7386_ChoiceDesc1 = {
    Text = "【受け取る】3つの中から1つ高級遺物を獲得する"
  },
  Event_7386_Desc = {
    Text = "そこには何もなく、黒い液体が地面に広がり、何も映し出さない。\n\n錯覚だろうか？何かが指の間をすり抜ける感覚がある。"
  },
  Event_7386_Name = {
    Text = "鏡面の下"
  },
  Event_7387_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7387_Desc = {
    Text = "黒い羽が小道の湿った土に落ち、黒泥状の融蝕液に変わる。"
  },
  Event_7387_Name = {
    Text = "騒乱のカラスの群れ"
  },
  Event_7388_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7388_Desc = {
    Text = "「ダフォダイル夫人はあなたのユーモアを気に入るかもね」\nラモンナが手を振ると、薄霧のような幻影が消えていく。\n「自分自身が超次元の旅の対価にならなければ良いけど」"
  },
  Event_7388_Name = {
    Text = "記憶の断片・昔の夢が甦る"
  },
  Event_7389_ChoiceDesc1 = {
    Text = "【受け取る】3つの中から1つ高級遺物を獲得する"
  },
  Event_7389_Desc = {
    Text = "ああ、そうだ、あの忌まわしい影は君自身だよ。\n\n溢れ出る悪意が足元の黒い泥と混じり合って踊っている。\n嫌じゃなければ、それが君の肩に乗りたがっているんだ。"
  },
  Event_7389_Name = {
    Text = "鏡面の下"
  },
  Event_7390_ChoiceDesc1 = {
    Text = "【その場に留まる】25黒章を獲得する"
  },
  Event_7390_ChoiceDesc2 = {
    Text = "【自由に歩き回る】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7390_Desc = {
    Text = "あなたは自分の影を踏み砕き、夜の闇に落ちた。\n\nこの失われた世界の中で、その七つ裂きに砕けた黒い影こそが、あなたと繋がる唯一の存在だ。\n\n本当に漆黒の悪夢の中を歩くつもりか？\nあなたは、まだ方向を見失っている。"
  },
  Event_7390_Name = {
    Text = "悪夢の旅人"
  },
  Event_7391_ChoiceDesc1 = {
    Text = "【源を探す】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7391_ChoiceDesc2 = {
    Text = "【レコードを再生する】すべての覚醒体が50狂気を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7391_ChoiceDesc3 = {
    Text = "【蓄音機を分解する】3つの中から1つ刻印を獲得する"
  },
  Event_7391_Desc = {
    Text = "古い蓄音機に出会った。\n\nゼンマイを巻き、針を傷だらけのレコードに置くと、交響曲はまるでテープを引き裂くように歪んで、管楽器と弦楽器が喧嘩しているようだ。\n\n曲の終わりに、規則的なノック音が聞こえた。\n\n「ドンドン……ドンドンドン……ドン……」\n\n眉をひそめて針を外したが、ノック音は止まらない。"
  },
  Event_7391_Name = {
    Text = "迷踪の声"
  },
  Event_7392_ChoiceDesc1 = {
    Text = "【輝きを熟視する】1つの遺物を呪われた遺物「(RelicConfig.Arg1)」に変化させる"
  },
  Event_7392_ChoiceDesc2 = {
    Text = "【輝きに触れる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7392_ChoiceDesc3 = {
    Text = "【背を向けて離れる】25黒章を獲得する"
  },
  Event_7392_Desc = {
    Text = "幻の視界の下で、密境の霧が現実に黒いヴェールをかけています。\n目に入るすべてがぼんやりとして、あるようでないようだ。\n\nぼんやりとした中で、何かの光が霧を突き抜け、灯台が船を導くように、安全な方向を示している。"
  },
  Event_7392_Name = {
    Text = "暗夜の蛍光"
  },
  Event_7393_ChoiceDesc1 = {
    Text = "【音楽を止める】1つの低級遺物を高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_7393_ChoiceDesc2 = {
    Text = "【それと対話する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」と「(Skill.Arg3)」に感染する"
  },
  Event_7393_ChoiceDesc3 = {
    Text = "【静かに耳を傾ける】25黒章を獲得する"
  },
  Event_7393_Desc = {
    Text = "あなたは濁った黒い液体の中から、砕けた記憶の粒をいくつか拾い上げた。\n\n結晶は透き通り、光を含んでいる。その中で何本かの細い糸が揺れ動き、そこに残る記憶の破片が風に舞う砂のように宙に舞い上がった。\n\n混乱し、奇怪で、不可解な光景があなたのそばで立ちのぼる。\n\nあなたは——"
  },
  Event_7393_Name = {
    Text = "銀月の破片"
  },
  Event_7394_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7394_Desc = {
    Text = "あなたは手を伸ばしていくつかの雪を受け止め、じっと見つめる。\n\nその雪が溶けてできたのは、透明な水滴ではなく濃厚で暗い融蝕液だった。"
  },
  Event_7395_ChoiceDesc1 = {
    Text = "【また水面にいない】ランダムな低級遺物1つを高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_7395_ChoiceDesc2 = {
    Text = "【うつむいて確認する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7395_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7395_Desc = {
    Text = "霧が晴れ、枯れた手があなたの前に差し出された。\n\nそれは血肉が腐蝕され、凹凸のある掌には粘つく黒い液体が覆っている。\n\nその体には、金色に輝く指輪やネックレスがたくさんぶら下がっている。\n\n手はあなたを引き寄せるように動いた。"
  },
  Event_7395_Name = {
    Text = "翻覆の魔手"
  },
  Event_7395_Tips1 = {
    Text = "まだ低級遺物を所持していません。"
  },
  Event_7396_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7396_Desc = {
    Text = "幻影はあなたに手を振り、消えてしまった。\n残されたのは冷たい雪とそびえる山々だけだ。"
  },
  Event_7396_Name = {
    Text = "火山の幻影"
  },
  Event_7397_ChoiceDesc1 = {
    Text = "【銀の月の葬儀】1つの遺物を呪われた遺物「(RelicConfig.Arg1)」に変化させる"
  },
  Event_7397_ChoiceDesc2 = {
    Text = "【銀の月の祈り】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7397_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7397_Desc = {
    Text = "あなたは濁った黒い液体の中から、砕けた記憶の粒をいくつか拾い上げた。\n\n結晶は透き通り、光を含んでいる。その中で何本かの細い糸が揺れ動き、そこに残る記憶の破片が風に舞う砂のように宙に舞い上がった。\n\n混乱し、奇怪で、不可解な光景があなたのそばで立ちのぼる。\n\nあなたは——"
  },
  Event_7397_Name = {
    Text = "銀月の破片"
  },
  Event_7398_ChoiceDesc1 = {
    Text = "【燃料を追加する】3つの中から1つ刻印を獲得する"
  },
  Event_7398_ChoiceDesc2 = {
    Text = "【それを消す】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_7398_Desc = {
    Text = "「私は殺された侍女の影。\n私を殺した犯人は、あの偽りの緑炎よ」\n\n微かに赤みがかった、ほのかな炎が身を揺らし、あなたにそう訴えかける。\n\n「私はかつて、凸月が映り込む湖畔に生きていた。\n輝かしく、まばゆく光り輝いていた。」"
  },
  Event_7398_Name = {
    Text = "微かな火"
  },
  Event_7399_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7399_Desc = {
    Text = "あなたと影は街灯の下に立ち、言葉を発しない。\n今夜は月がなく、すべての家が静まり返る。\n\nあなたは影に手を振り、振り返って離れる。"
  },
  Event_7399_Name = {
    Text = "街灯の下の影"
  },
  Event_7400_ChoiceDesc1 = {
    Text = "【カラスを追い払う】Arg1黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7400_ChoiceDesc2 = {
    Text = "【無視する】離れる"
  },
  Event_7400_Desc = {
    Text = "カラスがベッドのそばに留まり、赤い目であなたを見つめている。"
  },
  Event_7400_Name = {
    Text = "提灯の黒いカラス"
  },
  Event_7401_ChoiceDesc1 = {
    Text = "【財布を持っていないと言う】3つの中から1つ刻印を獲得"
  },
  Event_7401_ChoiceDesc2 = {
    Text = "【網を破る】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7401_Desc = {
    Text = "オレンジがかった黄色の糸が静かに空中に浮かんでいる。\n思わず手を伸ばすと、脆い糸は瞬時に溶け、子供たちの笑い声が耳元で響いた。\n「金も銀も黄も赤も、すべての財布は私たちのもの！」"
  },
  Event_7401_Name = {
    Text = "迷走ネットワーク"
  },
  Event_7402_ChoiceDesc1 = {
    Text = "【電報機を修理する】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_7402_ChoiceDesc2 = {
    Text = "【電報機を埋める】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_7402_ChoiceDesc3 = {
    Text = "【無視する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7402_Desc = {
    Text = "狭い洞窟の裂け目に身を潜め、嵐を一時的に避ける。\nしかし、ここに長く留まることはできない。\n黒いローブの怪人たちがここを見つけたら逃げ場はない。\n\n裂け目の隅で、壊れた電報機を発見した。"
  },
  Event_7402_Name = {
    Text = "先人の遺物"
  },
  Event_7403_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7403_Desc = {
    Text = "あなたは王国内の多くの場所でこのような肖像画を見たことがある。\n「その女王」は画面の中央に位置し、黒いバラに囲まれて輝いている。\nただ一点を除いて——彼女の顔は無情にも削り取られ、焦げた黒い空洞が残されている。\nあなたは今もなお、女王の真の姿を見たことがない。"
  },
  Event_7403_Name = {
    Text = "肖像画の回廊"
  },
  Event_7404_ChoiceDesc1 = {
    Text = "【彼女を許す】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7404_ChoiceDesc2 = {
    Text = "【彼女を助ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_7404_ChoiceDesc3 = {
    Text = "【自分の道を行く】50黒章を獲得する"
  },
  Event_7404_Desc = {
    Text = "三人の影があなたの行く手を阻む。\n\n「彼女を見逃してあげて」\n融蝕液塗れのクマのぬいぐるみを抱く影が言う。\n「彼女は臆病なだけで、邪悪ではない。誰も傷つけたくないんだ」\n\n「彼女を助けてあげて」\nきれいに包装されたキャンディを持つ影が言う。\n「あなたには彼女ができないことができる。すべてを終わらせることができる」\n\n「私たちの言うことを聞く必要はない」\n手ぶらの影が言う。\n「あなたにはあなたの道がある」"
  },
  Event_7404_Name = {
    Text = "分かれ道"
  },
  Event_7405_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7405_Desc = {
    Text = "ダフォダイルの声が一瞬止まった。\n\n「あら、これを選んだの？いい選択ね。\n特別にプレゼントをあげるわ」\n\n「その子のことはよく知らないけど、フランシスについては思うところがあるわ。\n\n彼女を支配し、「見る」力を与えた感情は、強い後悔だと思うわ。\n彼女はこの後悔にどう向き合うのでしょう……」"
  },
  Event_7405_Name = {
    Text = "ヒントの時間"
  },
  Event_74068_ChoiceDesc1 = {
    Text = "【脳缶に収める】「予備の脳缶」を山札のランダムな位置に追加する。"
  },
  Event_74068_Desc = {
    Text = "緻密な浮彫りが施された門の内側、赤煉瓦の斜め屋根の上、壁の崩れかけた長屋の前で、長く伸びた影が揺らめき、問いへの答えを求めている。\n\n平凡であることは、すなわち死を意味するのか？\n\n現状に甘んじることは、やがて火が尽きるように消え去る運命だというのか？"
  },
  Event_74068_Name = {
    Text = "未だ消えぬ意識"
  },
  Event_74069_ChoiceDesc1 = {
    Text = "【引き続き収容する】山札から最大2枚の指令カードを削除し、それらを「予備の脳缶」に追加する"
  },
  Event_74069_Desc = {
    Text = "「私は彼らを見た。\n\n多くの人々、多くのうわ言。\n\n賢い者もいれば、浅はかな者もいる。\n理性ある者もいれば、狂気に囚われた者もいる。\n\nときには、灰の中から希望の火花が生まれることもあるのだ」"
  },
  Event_74069_Name = {
    Text = "未だ消えぬ意識"
  },
  Event_7406_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7406_Desc = {
    Text = "あなたは慎重に天秤から鼠を取り上げる。\n\nそれは穏やかに呼吸し、毛むくじゃらの体があなたの手のひらを温める。"
  },
  Event_7406_Name = {
    Text = "理性と感情"
  },
  Event_7407_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7407_Desc = {
    Text = "薄暗いシルバーコアが眩しい光を放ち、一瞬で消え去り、手には砂のような灰だけが残った。\nシルバーコアは最後の霊知を使い果たし、未知の魂は肉体を再構築できなかったが、完全に消える前に存在の痕跡を残した。"
  },
  Event_7407_Name = {
    Text = "存在の証明"
  },
  Event_7408_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7408_Desc = {
    Text = "「私はあの子をよく知らないけど、フランシスについては推測がある。\n彼女を支配し、『見る』力を与えた感情は、強烈な後悔だと思う。\n彼女はこの後悔に対してどんな選択をするのでしょうね……」"
  },
  Event_7408_Name = {
    Text = "ヒントの時間"
  },
  Event_7409_ChoiceDesc1 = {
    Text = "【紙を引き出す】カードを1枚削除する"
  },
  Event_7409_ChoiceDesc2 = {
    Text = "【今はその時ではない】「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7409_Desc = {
    Text = "手提げ鞄の中の携帯タイプライターが突然、勝手に動き、半ページ分の歪んだ文字を打ち出した。\n\n「あなたは彼の者を見た。\n彼の者はあなたのすぐ傍らにいる。\n狂気に染められた熱狂の影が、あなたを包む……\n彼の者の姿を直視してはいけない」"
  },
  Event_7409_Name = {
    Text = "不意の警告"
  },
  Event_7410_ChoiceDesc1 = {
    Text = "【左へ進む】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_7410_ChoiceDesc2 = {
    Text = "【右へ進む】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染する"
  },
  Event_7410_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7410_Desc = {
    Text = "あなたは迷宮に迷い込んだようだ。\n左へ、右へ、また左へ……\n徐々に忍耐を失い、顔を上げると目が見えた。\nその目はあなたたちを見つめる。静かで威厳があり、まるでここを支配しているかのようだ。"
  },
  Event_7410_Name = {
    Text = "眼の迷宮"
  },
  Event_7411_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7411_Desc = {
    Text = "あなたは必死に全力で手を引っこめ、骨が折れる音をはっきりと聞いた。\n\nこれは好奇心の代償だ。"
  },
  Event_7411_Name = {
    Text = "インスピレーション"
  },
  Event_7412_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7412_Desc = {
    Text = "あなたはカメラを丁寧に点検した。\n革と黒金が機体に埋め込まれ、油のような光沢を放っている。\n\nレンズはあなたを見つめ、まるで覗き込んでいるかのようだ……"
  },
  Event_7412_Name = {
    Text = "記録は無罪"
  },
  Event_7413_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7413_Desc = {
    Text = "あなたはためらうことなく、カメラの中に隠れていたもう半分のフィルムを引き出した。\nそれに映る光景に、あなたは言葉を失った。\n\n現像されていないフィルムには、あなたが黒い泥の中に倒れている姿が忠実に記録されていた。"
  },
  Event_7413_Name = {
    Text = "記録は無罪"
  },
  Event_74145_ChoiceDesc1 = {
    Text = "【読む】指令カードを1枚削除し、25黒章を獲得する"
  },
  Event_74145_ChoiceDesc2 = {
    Text = "【タイピングを続ける】山札にあるカードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_74145_Desc = {
    Text = "プリンターは猛烈にインクを噴き出している。\n\n黒色のインクは幽霊のように噴出口から噴き出し、空気中に広がり、濃密で圧迫感のある黒い霧を形成している。\n\nキーボードには何らかの暗示が隠れているようで、無邪気な指先が触れるのを待っている。"
  },
  Event_74145_Name = {
    Text = "ゴーストインク"
  },
  Event_74146_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74146_Desc = {
    Text = "あなたは脇道へと足を踏み入れ、霧が裾をかじるが、その影は背後で無数の目に分裂する。\n錆びついた鐘の音が湿った前兆を伴って響く。\n\nすべての迂回路はやがて循環の繭へと収束するとき……腐りかけた黎明の前に、あなたは自分自身の影と再会する運命にあるのだと知っている。"
  },
  Event_74146_Name = {
    Text = "時間の灰"
  },
  Event_74147_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74147_Desc = {
    Text = "あなたは胸の前に祈りの印をそっと描き、亡き者のために無言の祈りを捧げる。\n\nこの滅びゆく世界には、あなたが救えないものがあまりにも多い。\n\nそのとき、骸骨がきらめいた。\n持ち主が生前大切にしていた宝物が、その一端をのぞかせている。"
  },
  Event_74147_Name = {
    Text = "色褪せた遺骨"
  },
  Event_74148_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74148_Desc = {
    Text = "「父なる神はあなたの慈悲を想っている。\n父なる神は私たちを見守り、苦難の重荷から救ってくれるでしょう」\n\n彼女の幻影は徐々に消え去り、聖なる音楽は無情な風のように駆け抜けました。"
  },
  Event_74148_Name = {
    Text = "パイプオルガンの祈り"
  },
  Event_74149_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74149_Desc = {
    Text = "あなたがむき出しになった骸骨をそっと押す。\n\nそれはゆっくりと、自然と黒い粘液の中に沈み、跡形もなく消えていった。\n\n魂が虚無の中で安らかにありますように。"
  },
  Event_74149_Name = {
    Text = "色褪せた遺骨"
  },
  Event_7414_ChoiceDesc1 = {
    Text = "【離れる】あなたは相手に勝利した、何も起こらなかった"
  },
  Event_7414_Desc = {
    Text = "「どうやら、小さな子は少し痛い目を見ないと、女性の秘密は簡単に探れないとわからないようね」\n\nダフォダイルの言葉と共に、巨大な敵が目の前に現れる。"
  },
  Event_7414_Name = {
    Text = "ヒントの時間"
  },
  Event_74150_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74150_Desc = {
    Text = "小さな鼠の隠れ家である鐘楼にはこのような病的な玩具は存在すべきではない。\nこの音はあなたの頭の中、あなたの記憶から来ている。\n\nかつて「缶の中の脳」だったときに感じた、音波を通じて変換された電流を思い出す。\n\nその異音は次第に平穏に、滑らかな古典音楽に変わり、あなたの脳内で繰り返し再生される。"
  },
  Event_74150_Name = {
    Text = "鐘楼の異音"
  },
  Event_74151_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74151_Desc = {
    Text = "あれは猫ではなく……それは提灯教会のうごめきです。\n\n黒色のヴェール下に憎悪と敵意が垣間見え、ささやく声があなたの意識を擦り、奇怪な幻覚をもたらします。"
  },
  Event_74151_Name = {
    Text = "猫の囁き"
  },
  Event_74152_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74152_Desc = {
    Text = "彼らはあなたの靴をつかみ、あなたの足首をつかみ、彼らは貪欲で、渇望し、あなたを彼らがいる深淵に引きずり込もうとしている。\n\nあなたは辛うじて抵抗し、後退して身を離そうとした。\n\n何かが落ちる音がした。"
  },
  Event_74152_Name = {
    Text = "悪夢の反映"
  },
  Event_74153_ChoiceDesc1 = {
    Text = "【回避する】3つの中から1つ刻印を獲得する"
  },
  Event_74153_ChoiceDesc2 = {
    Text = "【阻止する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_74153_Desc = {
    Text = "見覚えのある光景が、あなたの神経を跳ねさせ、痙攣させ、恐怖を掻き立てる。\n\n「再び……」\n\n無慈悲な悪夢が降りかかり、巨大な無力感があなたを覆う。\n\n本当に彼女の運命を書き換えることはできないのか？\n\nもう間に合わない、小さなサラの裂けた頭部の中で、銀色に光る巨大な口があなたを噛み切ることを待ち望み、捕食し咀嚼している。"
  },
  Event_74153_Name = {
    Text = "悪夢の再現"
  },
  Event_74154_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74154_Desc = {
    Text = "不安を誘うささやきが聞こえる。\n\n「私たちは遠い星々の山や沼地から来た。\n我々の身体は灯台の芯と燃料であり、地球からの灯を灯し、新しい世界への道を照らし続けるのだ」"
  },
  Event_74154_Name = {
    Text = "猫の囁き"
  },
  Event_74155_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74155_Desc = {
    Text = "夕焼け、鐘楼、飛鳥……\nその少女はアイマスクを外し、彼女の灰暗い瞳孔の視線があなたを動けなくします。\n\n幻影は蜃気楼のように、目前でほどけて散っていきますが、心配の思いは拭えません。"
  },
  Event_74155_Name = {
    Text = "白い眼帯"
  },
  Event_74156_ChoiceDesc1 = {
    Text = "【拾い上げる】3つの中から1つ低級遺物を獲得する"
  },
  Event_74156_ChoiceDesc2 = {
    Text = "【思い出す】低級遺物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」を獲得し、2枚の「(Skill.Arg3)」に感染する"
  },
  Event_74156_Desc = {
    Text = "角の融蝕液の中に、小さな白いアイマスクが横たわっている。\n\n思い出があなたの心を掴む。"
  },
  Event_74156_Name = {
    Text = "白い眼帯"
  },
  Event_74157_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74157_Desc = {
    Text = "透明な手のひらが白黒の鍵盤の上で自在に舞う。\nしかし、発せられた音はバラバラで、調子外れのオルゴールのように、どの音も不協和音の哀鳴を発し、助けを求めるように叫んでいるかのようだ。\n\n最終的に、演奏は無力な和音の中で突然止まる。\n\n生前に得られなかったものは、今この時にのみ残されたものだ。"
  },
  Event_74157_Name = {
    Text = "遺憾のソナタ"
  },
  Event_74158_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74158_Desc = {
    Text = "「親愛なるサラ様：\n私はワークハウスの介護士の職を辞退したいと考えています。\n\n私はもうあなたの理念を支持できません。\nあなたの教えは間違っています。\n東区の子供たちはあなたの庇護の下で育つべきではなく、純粋な善意と無私の贈与を信じるべきではありません。\n\n彼らはいつかあなたの翼を離れ、東区で生きるための法則を学ばなければなりません。\n\n……」\n\n後続の文字は黒い液体で濡れ、ぼやけている。"
  },
  Event_74158_Name = {
    Text = "ゴーストインク"
  },
  Event_74159_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74159_Desc = {
    Text = "「私が子供たちに提供できるのは、雨をしのぐ屋根と、飢え死にしないための食事だけです。\n\nもし親切なロジャーズ氏が呼んでくれた医者がいなければ、彼女たちは病気の時に薬すら手に入れられませんでした。\n\n私はあまり多くの本を読んだことがありませんが、子供たちが街の中で凍え死なないようにすることが、私のすべてです。\n\n私は子供たちがどんな人間になるかには干渉しませんが、彼女たちには生き続けてほしいのです。\n\n……」"
  },
  Event_74159_Name = {
    Text = "ゴーストインク"
  },
  Event_7415_ChoiceDesc1 = {
    Text = "【供給源を探る】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7415_ChoiceDesc2 = {
    Text = "【手紙を捨てる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7415_ChoiceDesc3 = {
    Text = "【手紙を確認する】50黒章を獲得する"
  },
  Event_7415_Desc = {
    Text = "また一通の手紙があなたの前に落ち、破れた紙が心を重くする。\nあなたは手紙を開いた。\n\n「また来た、私の予告は妄言ではない！@4ここから始まり、ここで終わる」\n「逃げたい……木の棚に身を隠し、手が震え止まらないが、粘つく体が床に落ちる音、そして迫る足音……名前を聞いた！それだ！@5！」"
  },
  Event_7415_Name = {
    Text = "また一通の救助要請"
  },
  Event_74160_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74160_Desc = {
    Text = "「ありがとう、父なる神の創生力が最終的に我々の形を再構築し、永遠の光と火をもたらしてくれるだろう。\n\n最終到達地点についた時、父なる神の前であなたを祝福するでしょう」\n\n彼女の幻影は徐々に消え去り、聖なる音楽は無情な風のように駆け抜けました。"
  },
  Event_74160_Name = {
    Text = "パイプオルガンの祈り"
  },
  Event_74161_ChoiceDesc1 = {
    Text = "【埋葬】Arg2ライフを回復する[ExDesc1]、指令カードを1枚選択して削除する"
  },
  Event_74161_ChoiceDesc2 = {
    Text = "【祈祷】黄金造物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_74161_Desc = {
    Text = "蒼白の骸骨の一片が、漆黒の融蝕液に半ば沈んでいた。"
  },
  Event_74161_Name = {
    Text = "色褪せた遺骨"
  },
  Event_74162_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74162_Desc = {
    Text = "霧の中へと大胆に踏み入れると、幻影がクモの巣のように身体に絡みつき、冷たい感触が骨まで染み入る。\n\n彼らのささやきは記憶の断片となって胸を貫く。\n\n通り抜ける時、背後には虚無だけが残り、前方には濃い霧に隠されたより多くの影がうごめいていて、待ち受けている。"
  },
  Event_74162_Name = {
    Text = "時間の灰"
  },
  Event_74163_ChoiceDesc1 = {
    Text = "【幻影を迂回する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_74163_ChoiceDesc2 = {
    Text = "【幻影を通り抜ける】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_74163_ChoiceDesc3 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_74163_Desc = {
    Text = "塵霾のような厚重な幕が街道を覆い、毎歩が時間の灰に踏み込むようだ。\n\n遠くでは、かすかな影が霧の中に揺らめき、過去の幽霊のように囁き、すでに忘れられた物語を語っているかのようだ。\n\n制御不能な想像力がまた恐ろしい影を幻化させ、それらは歪み、広がり、未来の兆しのようにあなたを押しつぶしそうだ。\n\nあなたは知っている、前方の道はさらに薄暗くなるだろうが、その足は止めるべきではないし、止めることもできない。"
  },
  Event_74163_Name = {
    Text = "時間の灰"
  },
  Event_74164_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74164_Desc = {
    Text = "あなたはサラの初めての猛烈な攻撃をかろうじてかわした。\n\n次はそんなに幸運ではないかもしれない。"
  },
  Event_74164_Name = {
    Text = "悪夢の再現"
  },
  Event_74165_ChoiceDesc1 = {
    Text = "【方向を指示する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_74165_ChoiceDesc2 = {
    Text = "【共に祈る】3つの中から1つ刻印を獲得する"
  },
  Event_74165_Desc = {
    Text = "ピアノとオルガンの音が灰色の風の中で交錯している。\n魔法のような旋律が人のいない街並みに漂っている。\n\n名前のない修道女が音楽に合わせて祈りを捧げる。\n\n「簡単な祈りには華やかな儀式は不要で、偉大な父なる神は私たちに希望を撒き与えてくださる。\nまさしく、彼が私たちに信仰心を授けてくれたように」"
  },
  Event_74165_Name = {
    Text = "パイプオルガンの祈り"
  },
  Event_74166_ChoiceDesc1 = {
    Text = "【モンスターを受け止める】1つの遺物を高級遺物「(RelicConfig.Arg1)」に変化させる"
  },
  Event_74166_ChoiceDesc2 = {
    Text = "【星を拾い上げる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_74166_ChoiceDesc3 = {
    Text = "【無視する】25黒章を獲得する"
  },
  Event_74166_Desc = {
    Text = "流星の雨が鐘楼に降り注ぐ。\n\n一つの透き通ったクリスタルがあなたの足元に落ち、小さな穴を掘り出した。\n\nあなたはまだ包囲の中に深く閉じ込められていて、さまざまな形状の融蝕生物が曲がった影のようにうなり、うなり声が絶え間なく響く。\n\nあなたは決意た——"
  },
  Event_74166_Name = {
    Text = "墜落した星"
  },
  Event_74167_ChoiceDesc1 = {
    Text = "【目をこする】50黒章を獲得する"
  },
  Event_74167_ChoiceDesc2 = {
    Text = "【目を閉じる】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_74167_Desc = {
    Text = "忌まわしい黒い猫の群れがジュリエットの背後に群がり、知られざる調子で囁き、秘められた悪意のある脅威を発している。"
  },
  Event_74167_Name = {
    Text = "猫の囁き"
  },
  Event_74168_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74168_Desc = {
    Text = "安物の布は手触りが少し粗いが、注意深く清潔に洗われている。\n\nそれをしっかり保管し、所有者に返される日を待とう。"
  },
  Event_74168_Name = {
    Text = "白い眼帯"
  },
  Event_74169_ChoiceDesc1 = {
    Text = "【距離を保つ】25黒章を獲得する"
  },
  Event_74169_ChoiceDesc2 = {
    Text = "【憐憫を与える】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_74169_Desc = {
    Text = "彼らはあなたの足元から押し寄せてくる。\n\n彼らのぼんやりした苦痛の顔の中で、あなたは引っ張られる自分の影を見た。\n\nあなたは本当に彼らを裁く特権を享有しているのか？"
  },
  Event_74169_Name = {
    Text = "悪夢の反映"
  },
  Event_7416_ChoiceDesc1 = {
    Text = "【破片を捨てる】特別な遺物がある場合、刻印「(EnchantConfig.Arg1)」を帯びた「症状：融蝕の狂乱」に感染する"
  },
  Event_7416_ChoiceDesc2 = {
    Text = "【破片を補完する】特別な遺物がない場合、「(Skill.Arg1)」に感染し、「(Skill.Arg2)」に感染する"
  },
  Event_7416_Desc = {
    Text = "青白い肢体があなたの前でゆっくりと動き、彼女は身をかがめて、折れた腕をあなたの前に差し出す。\n痛みに目を細めた彼女の目から、白い石膏の涙が溢れ出る。\n\n「あと……あと一つで、私は……」"
  },
  Event_7416_Name = {
    Text = "残躯を補完する"
  },
  Event_74170_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74170_Desc = {
    Text = "あなたは彼らを救おうと試みる。\n\nしかし、彼らに同化されてはいけない。"
  },
  Event_74170_Name = {
    Text = "悪夢の反映"
  },
  Event_74171_ChoiceDesc1 = {
    Text = "【視線を逸らす】最大ライフをArg1増加させる"
  },
  Event_74171_ChoiceDesc2 = {
    Text = "【見つめ続ける】ランダムな1枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、1枚の「(Skill.Arg2)」に感染"
  },
  Event_74171_Desc = {
    Text = "「終焉が既に到来しています」\n心臓が強く痛み、収縮する。\n\nジュリエットの確信に満ちた声には、間違いなく催眠やテレパシー的な力が含まれている。\n\nこの次元のジュリエットの目的は、過去に知っていたジュリエットとどう違うのか？\n謎が多く、迷いの壁が厚い。\n\nあなたはジュリエットを観察しようと視線を上げたが、彼女もまたあなたをじっと見つめていた。"
  },
  Event_74171_Name = {
    Text = "終焉の視線"
  },
  Event_74172_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74172_Desc = {
    Text = "あなたは手をあげ、虚構の鍵盤をぎこちなく叩く。\n\n鍵盤がはじけて、響き渡る音が交差し、音符はまるで滴る露のように清らかで透明だ。\nしかし、熟練した演奏技術はあなたの指先からは出てこない。\n\nふと気付けば、姿のない細長い大きな手があなたの手の甲に覆いかぶさっている。\nそれは、演奏に合わせて動いたり止まったりしている。\n\n時間はまるで静止したかのようで、ピアノの音が最後の余韵を残すまで続く。\n\n満足のため息が、あなたには聞こえた。"
  },
  Event_74172_Name = {
    Text = "遺憾のソナタ"
  },
  Event_74173_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74173_Desc = {
    Text = "頻繁に移動する意識は安定しておらず、意味のない干渉を排除する必要があります。\n\nあなたは目の前のジェンキンに注意を集中すると、蓄音機の音が徐々に薄れて、霧の中に消えていきました。"
  },
  Event_74173_Name = {
    Text = "鐘楼の異音"
  },
  Event_74174_ChoiceDesc1 = {
    Text = "【音源を探す】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_74174_ChoiceDesc2 = {
    Text = "【思い出す】すべての覚醒体が50狂気を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_74174_ChoiceDesc3 = {
    Text = "【ノイズを無視する】3つの中から1つ刻印を獲得する"
  },
  Event_74174_Desc = {
    Text = "あなたはレコードプレーヤーの針が歪む音を聞いた。\n\n歪んだ針が壊れた螺旋溝を滑り、緩やかに恐ろしい震えを発生させている。"
  },
  Event_74174_Name = {
    Text = "鐘楼の異音"
  },
  Event_74175_ChoiceDesc1 = {
    Text = "【彼のために演奏する】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_74175_ChoiceDesc2 = {
    Text = "【ピアノを聴く】狂気値が50以上の覚醒体が1人いるごとに、15黒章を獲得する"
  },
  Event_74175_ChoiceDesc3 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_74175_Desc = {
    Text = "「親愛なるジョン：\n最近、唐突に思い至りました……\nあなたが僕たちのために最後にピアノを演奏してくれた時から、もう数年も経っていることに。\n\n僕は今年81歳になり、年々若い頃の思い出の大切さを感じています。\n\nもしあなたがこの手紙を受け取ったら、次にロンディニウムに寄った時は、僕のアパートの前で立ち止まり、一曲演奏してくれませんか」"
  },
  Event_74175_Name = {
    Text = "遺憾のソナタ"
  },
  Event_74176_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74176_Desc = {
    Text = "生存の欲望が胸の中で渦巻き、あなたはためらわずに命令を出した。\n\nあなたが包囲を突破し、振り返った時、その星はすでに融蝕液に呑み込まれていた。\n\nうごめく融蝕液の中で、一連の鋭い規則正しい音が響く。\n\nあなたは融蝕液の表面に触れ、腐朽した星があなたの掌に落ちた。"
  },
  Event_74176_Name = {
    Text = "墜落した星"
  },
  Event_74177_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74177_Desc = {
    Text = "君はその星を拾い上げたが、手の平の中で光を失った。\n\n圧迫感が突然に襲い、悪寒が背中を走った。\n\n生死の瞬間、君は身を傾けて避け、凶悪な攻撃をかろうじてかわしたが、腕にはなおも2インチの擦り傷が残った。"
  },
  Event_74177_Name = {
    Text = "墜落した星"
  },
  Event_74178_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74178_Desc = {
    Text = "触肢内に隠された鋭い歯があなたの袖口を切り裂き、滴り落ちる血漿は深紅の細流となって、手首の骨を沿って滑り落ちる。\n\nあなたはサラの視線を識別することができないが、裂けた頭蓋がかすかに苦痛の震えた叫びを発している。"
  },
  Event_74178_Name = {
    Text = "悪夢の再現"
  },
  Event_74179_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74179_Desc = {
    Text = "君は周りを見回し、左右に動き、声はまるで君を隠れんぼする鼠のように、時には左に、時には右に、遠くに行ったり近くに来たりした。\n\n君は迷い込んで、声はますます騒がしくなり、金属の擦れ合う音が君をより深い不安に落とし込んだ。\n\n君は突発的に思いつき、ポケットを触ってみたが、音の源は見つからなかったものの、小さな宝物を拾った。"
  },
  Event_74179_Name = {
    Text = "鐘楼の異音"
  },
  Event_7417_ChoiceDesc1 = {
    Text = "【離れる】あなたは(Arg1)ライフを失い、「(Skill.Arg2)」に感染する"
  },
  Event_7417_Desc = {
    Text = "「いい子ね。\nでも、少し罰を与えないとね」\n\nダフォダイルの軽やかな笑い声が次元の裂け目に消えていく。"
  },
  Event_7417_Name = {
    Text = "ヒントの時間"
  },
  Event_74180_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74180_Desc = {
    Text = "彼女と視線を合わせないように避ける。\n\nそれでも、ある種の力が心臓を不安で震わせる。"
  },
  Event_74180_Name = {
    Text = "終焉の視線"
  },
  Event_74181_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74181_Desc = {
    Text = "ジュリエットと目が合う。\n\n次の瞬間、彼女は完全に狂乱の微笑みを浮かべ、あなたの慢心と無知を嘲笑しているかのように見えた。\n\nしかし、その笑みは瞬く間に消え、他の人々もこれについてリアクションをとることはなかった……まるで幻覚に過ぎなかったかのようだ。"
  },
  Event_74181_Name = {
    Text = "終焉の視線"
  },
  Event_7418_ChoiceDesc1 = {
    Text = "【任務遺物1がある場合、高級遺物「(RelicConfig.Arg1)」を獲得する】"
  },
  Event_7418_ChoiceDesc2 = {
    Text = "【任務遺物2がある場合、高級遺物「(RelicConfig.Arg1)」を獲得する】"
  },
  Event_7418_ChoiceDesc3 = {
