  },
  Event_7419_Name = {
    Text = "事件255（開発中）"
  },
  Event_7420_ChoiceDesc1 = {
    Text = "【蝶を避ける】カードを2枚削除する"
  },
  Event_7420_ChoiceDesc2 = {
    Text = "【蝶を抱擁する】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7420_ChoiceDesc3 = {
    Text = "【離れる】Arg1黒章を獲得する"
  },
  Event_7420_Desc = {
    Text = "曲がり角、また曲がり角、地獄犬を追う道は果てしなく続く。\n\n痛む足首、膨れ上がる頭、混乱の中であなたには再び蝶が見える。\n\nそれは狂気の妄念、密境の呟きだ。\n蝶たちは四方八方から舞い出る。"
  },
  Event_7420_Name = {
    Text = "妄念の噴出"
  },
  Event_7421_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7421_Desc = {
    Text = "あなたはそっと風鈴を押さえた。\n\n風鈴の音は何度か鳴った後、静寂に包まれた。\n\nそれはすでに退いたが、悪夢の中で再び戻ってくるだろう。"
  },
  Event_7421_Name = {
    Text = "小さな風鈴"
  },
