  },
  Event_7422_Desc = {
    Text = "風鈴の音は何度か鳴った後、静寂に包まれた。\n\nそれはすでに退いたが、悪夢の中で再び戻ってくるだろう。"
  },
  Event_7422_Name = {
    Text = "小さな風鈴"
  },
  Event_7423_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7423_Desc = {
    Text = "「いいね、君はとても慎重だ」\n風鈴の中から、突然遠い声が聞こえてきた。\n\n「慎重さは、君にささやかな褒美をもたらすが、それだけだ」"
  },
  Event_7423_Name = {
    Text = "小さな風鈴"
  },
  Event_74245_ChoiceDesc1 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_74245_Desc = {
    Text = "ゴロゴロと、ダイスはダイス入れの中で興奮して踊り、疲れ果てるまで舞い続ける。\n\n「君が負けたな。\nしかし、私と遊んでくれた報酬として、君はまだ報酬を受け取ることができる」"
  },
  Event_74245_Name = {
    Text = "Nのメッセージ"
  },
  Event_74246_ChoiceDesc1 = {
    Text = "【水門を閉める】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_74246_ChoiceDesc2 = {
    Text = "【慌てて遠ざかる】「(Skill.Arg1)」に感染し、ランダムな指令カード1枚が刻印「(EnchantConfig.Arg2)」を獲得する"
  },
  Event_74246_ChoiceDesc3 = {
    Text = "【無視する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_74246_Desc = {
    Text = "あなたはこのスチームと歯車で作られた迷宮の深部に閉じ込められている。\n真鍮のパイプは頭上で蜘蛛の巣のように絡まり、呼吸するたびに粘っこいオイルの霧がかき乱される。\n\n制御不能な機械のダイヤルが壁でけいれんし、針が目盛りを切ると零星の火花が散り、まるでヴィクトリア時代の実験室で瀕死の蛍のように見える。\n鋲接ぎ目からは銅の錆がにじみ出ており、この鋼鉄の巨獣のただれた傷口のようだ。\nそして、あなたの懐中時計はとうに止まっている——ここでの時間はただ歯車の嚙み合わせの祈りに過ぎない。"
  },
  Event_74246_Name = {
    Text = "蒸気の迷宮都市"
  },
  Event_74247_ChoiceDesc1 = {
    Text = "【賭ける】「(Skill.Arg1)」に感染し、賭けに入る"
  },
  Event_74247_ChoiceDesc2 = {
    Text = "【やはりやめる】25黒章を獲得する"
  },
  Event_74247_Desc = {
    Text = "街角の深い黒霧の中で、息が詰まるような気配が広がり始めます。\n\n霧の中で、二つの古くて冷たいダイスが静かに現れ、その表面には解読不能な記号と妖しい模様が刻まれています。\n\nそれらは滑りやすい石板の上に静かに横たわり、何か知らない召喚を待っているようです。\n\n「あなたは私が誰か知っている。\n賭けますか？」"
  },
  Event_74247_Name = {
    Text = "Nのメッセージ"
  },
  Event_74248_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74248_Desc = {
    Text = "「破壊的な大災害の夢を見て、昔日の輝きが圧倒されました。\n\n生活に対する怒り、そして未来に対する希望のなさに無力感を感じています。\n\n心が恐怖によって引き裂かれていますが、この崩壊寸前の瞬間に、皆さんが警戒し、この恐ろしい運命が降りかかるのを防ぐことを願っています」"
  },
  Event_74248_Name = {
    Text = "遺言のうわ言"
  },
  Event_74249_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74249_Desc = {
    Text = "黒い煙は失望して震える。\n\nその後、ダイスは一瞬で消え去った。\n\nあなたの心に残る疑問はただ一つ——\nこれらのダイスは一体何からできているのか？"
  },
  Event_74249_Name = {
    Text = "Nのメッセージ"
  },
  Event_7424_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7424_Desc = {
    Text = "振り返ると、革靴とぼんやりとした人影が見える。\n若い紳士のようだ。\n「お邪魔してすみません、黒い革靴を見かけませんでしたか？」\n「目の前にあるじゃないですか」\n「いや、違うんです……これは山羊革で、牛革じゃないんです。\nこの蝋人形館に12年も閉じ込められているのは、靴が間違っているせいだ……」\n声はぶつぶつとつぶやき、次第に弱まる。"
  },
  Event_7424_Name = {Text = "足音"},
  Event_74250_ChoiceDesc1 = {
    Text = "【男の声を判別する】山札からランダムに指令カードを3枚引き、1枚選択して複製する"
  },
  Event_74250_ChoiceDesc2 = {
    Text = "【女性の声を聞き分ける】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_74250_ChoiceDesc3 = {
    Text = "【老人の声を判別する】25黒章を獲得する"
  },
  Event_74250_Desc = {
    Text = "暗闇の中の沼地に一人立つ。\n\nぼんやりと混沌とした呪文が押し寄せ、耄碌した老人から来たものや、言葉を学び始めたばかりの子供、切迫した女性、なんとも言えない恐怖に包まれた男性から来たものもある…"
  },
  Event_74250_Name = {
    Text = "遺言のうわ言"
  },
  Event_74251_ChoiceDesc1 = {
    Text = "【前進する】山札からランダムに指令カードを3枚引き、1枚選択して削除し、75黒章を獲得する"
  },
  Event_74251_ChoiceDesc2 = {
    Text = "【休憩する】山札からランダムに指令カードを3枚引き、1枚選択して未強化のコピーを山札に追加し、25黒章を獲得する"
  },
  Event_74251_ChoiceDesc3 = {
    Text = "【振り返る】50黒章を獲得する"
  },
  Event_74251_Desc = {
    Text = "無人の街を歩く、灰の上に深い凹みを残す足音。\n\n都市の道はクモの巣のようで、あなたは束縛される蛾。"
  },
  Event_74251_Name = {
    Text = "陰霾の都"
  },
  Event_74252_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74252_Desc = {
    Text = "蒸気の扉が轟音の響きと共に閉じる瞬間、あなたは自身の影が精密に嵌合する螺旋で寸刻に引き裂かれる音を聞いた。"
  },
  Event_74252_Name = {
    Text = "蒸気の迷宮都市"
  },
  Event_74253_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74253_Desc = {
    Text = "反復する風景が目の前で更新され続け、逃げ道はありません。"
  },
  Event_74253_Name = {
    Text = "蒸気の迷宮都市"
  },
  Event_74254_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74254_Desc = {
    Text = "時間は無用な座標に過ぎず、あなたが求めるのは真実のみ。"
  },
  Event_74254_Name = {
    Text = "蒸気の迷宮都市"
  },
  Event_74255_ChoiceDesc1 = {Text = "【3点】"},
  Event_74255_ChoiceDesc2 = {Text = "【6点】"},
  Event_74255_ChoiceDesc3 = {Text = "【1点】"},
  Event_74255_Desc = {
    Text = "誰が不幸と狂気を意味するこのダイスを投げるでしょう？\nあなたです、もちろんあなたです。\n\nあなたが選択するのは——"
  },
  Event_74255_Name = {
    Text = "Nのメッセージ"
  },
  Event_74256_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_74256_Desc = {
    Text = "ゴロゴロと、ダイスはダイス入れの中で興奮して踊り、疲れ果てるまで舞い続ける。\n\n「君が負けたな。\nしかし、私と遊んでくれた報酬として、君はまだ報酬を受け取ることができる」"
  },
  Event_74256_Name = {
    Text = "Nのメッセージ"
  },
  Event_74257_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74257_Desc = {
    Text = "道のりは果てしない暗闇と混沌が広がっています。\n\n自らの運命を考える時間はなく、恐怖を削ぎ落とし、審判が降臨する前に自分の終点に到達する必要があります。"
  },
  Event_74257_Name = {
    Text = "陰霾の都"
  },
  Event_74258_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74258_Desc = {
    Text = "「時の影に座しながら、死の冷たい掌が徐々に忍び寄るのを感じる。\n窓外の世界はますます暗くなり、災厄の囁きが満ちる。\n愚かさの精算を恐れて、判決の到来を恐れる。\n我々の側に不吉な気配が漂い、審判の日が近づいていることに心配している。\n我々の文明は崩壊しそうで、破滅に飲み込まれるのではないかと恐れている。\n私たち自身の愚かな傲慢さに囚われている」"
  },
  Event_74258_Name = {
    Text = "遺言のうわ言"
  },
  Event_74259_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74259_Desc = {
    Text = "死地を生き延びただけでも容易ではなく、さらに多くを求めるべきではありません。\n\n崩れた遺跡と廃墟の影が依然としてあなたを召喚しています。"
  },
  Event_74259_Name = {
    Text = "陰霾の都"
  },
  Event_7425_ChoiceDesc1 = {
    Text = "【離れる】3つの中から1つ刻印を獲得する"
  },
  Event_7425_Desc = {
    Text = "「そうなの……とても興味深いわ」\n彼女はアンケートを回収し、子供たちが去った方向を指さした。\n\n急いで離れるあなたは、背後のささやきをほとんど聞き逃した。\n「次に会うのを楽しみにしてるわ」"
  },
  Event_7425_Name = {
    Text = "心理評価"
  },
  Event_74260_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74260_Desc = {
    Text = "何らかの巨大な力、もしくは強大な運命の支配下にある。\n\n短い休息はこの状況を変えることはできないが、疲れた足に前進の力を与えてくれる少なくとも。"
  },
  Event_74260_Name = {
    Text = "陰霾の都"
  },
  Event_74261_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_74261_Desc = {
    Text = "「……都市はもはや暖かい避難所ではなく、恐怖と絶望を孕む秘密の墓穴である。\nかつての生き生きとした夢は、今では恐怖の断片のみが残存している。\nもう恐れを知らないふりはできない。\n目の前の世界は、目覚めることのできない悪夢のようだ」"
  },
  Event_74261_Name = {
    Text = "遺言のうわ言"
  },
  Event_74262_ChoiceDesc1 = {
    Text = "【離れる】高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_74262_Desc = {
    Text = "ゴロゴロと、ダイスはダイス入れの中で興奮して踊り、疲れ果てるまで舞い続ける。\n\n「君が負けたな。\nしかし、私と遊んでくれた報酬として、君はまだ報酬を受け取ることができる」"
  },
  Event_74262_Name = {
    Text = "Nのメッセージ"
  },
  Event_7426_ChoiceDesc1 = {
    Text = "【離れる】ランダムな指令カード1枚が刻印：鏡像を獲得する"
  },
  Event_7426_Desc = {
    Text = "「答えずとも大丈夫、あなたの目にその答えが映っています。\n\n私にはまだ片付ける雑用がありますので、これで失礼します。\n\nあなたも何か用事があるのでしょう？あちらをご覧なさい、誰かがあなたを探しに来ましたよ」\n\nあなたが振り返ると、提灯教会の信者の姿が道の果てに現れた。"
  },
  Event_7426_Name = {
    Text = "奇妙な旅の伴Ⅴ"
  },
  Event_7427_ChoiceDesc1 = {
    Text = "【離れる】ランダムな指令カード1枚が刻印：策謀を獲得する"
  },
  Event_7427_Desc = {
    Text = "「あなたはまだ、私に心を開く気はないようですね。残念ですが、構いません。\n\nそれでも私は親切なヒントを差し上げます。\n\nさて、提灯教会がここに現れたのは、一体何を探しているからでしょうか？」\n\n「おや、どうやら誰かが私たちの雑談を望んでいないようです。あちらをご覧なさい、誰かがあなたを探しに来ましたよ」\n\nあなたが振り返ると、提灯教会の信者の姿が道の果てに現れた。"
  },
  Event_7427_Name = {
    Text = "奇妙な旅の伴Ⅴ"
  },
  Event_7428_ChoiceDesc1 = {
    Text = "【離れる】ランダムな指令カード1枚が刻印：啓示を獲得する"
  },
  Event_7428_Desc = {
    Text = "「あなたは正直ですね、それは称賛に値します。そこで、小さなヒントを差し上げましょう。\n\nあなたがライの町に来た途端に、彼に目をつけられたのは、一体何故でしょうか？」\n\n「おや、どうやら誰かが私たちの雑談を望んでいないようです。あちらをご覧なさい、誰かがあなたを探しに来ましたよ」\n\nあなたが振り返ると、提灯教会の信者の姿が道の果てに現れた。"
  },
  Event_7428_Name = {
    Text = "奇妙な旅の伴Ⅴ"
  },
  Event_7429_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7429_Desc = {
    Text = "雑然とした音が次第に静まり、手の中は空っぽだが、一瞬の感情はシルバーキーに記録された。"
  },
  Event_7429_Name = {Text = "無の書"},
  Event_7430_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7430_Desc = {
    Text = "混乱の中で手を伸ばし、何か奇妙な感触の物が手に落ち、徐々に形を成す。"
  },
  Event_7430_Name = {Text = "無の書"},
  Event_7431_ChoiceDesc1 = {
    Text = "【立ち去る】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7431_Desc = {
    Text = "「蛇の狩り方を聞いたことがありますか？\n\n蛇は地を這い、くねくねと進むしかないので、チーターのように力強く追うことも、狼の群れのように獲物を囲むこともできません。\n\nその代わりに、蛇は静かに待ち続ける術を身につけました」\n\n「彼らは獲物が警戒を解く瞬間まで待ちつづけ、一撃で襲いかかり、丸呑みにしてしまいます」"
  },
  Event_7431_Name = {
    Text = "奇妙な旅の伴Ⅲ"
  },
  Event_7432_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7432_Desc = {
    Text = "どうやら驚かせてしまったようだ。\n\n黒猫の艶やかな毛皮が、指先にわずかな熱を残し、霧の奥深くへと消えていった。"
  },
  Event_7432_Name = {
    Text = "夜猫の災い"
  },
  Event_7433_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7433_Desc = {
    Text = "愚かな狂信者たちの荒唐無稽な夢の戯言に過ぎない。"
  },
  Event_7433_Name = {
    Text = "密命・下"
  },
  Event_7434_ChoiceDesc1 = {
    Text = "【盗み聞きする】3つの中から1つ刻印を獲得する"
  },
  Event_7434_ChoiceDesc2 = {
    Text = "【大声で咳をする】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_7434_Desc = {
    Text = "壁の隅に亀裂が入り、血管のように伸びている。\nかすかなブーンという音と共に、反対側から男の低い声が聞こえる。\n\n「クインティン第5地区、ウェリントン第10地区、ノーマン第15地区……今月の資材は積み込み済み、出発準備、貨物番号I-0234……\n……\nそれと、ミサゴの連中のせいで、ホワイトチャペル区は現在戒厳令下、最大の素材供給源を喪失」"
  },
  Event_7434_Name = {
    Text = "壁に耳あり"
  },
  Event_7435_ChoiceDesc1 = {
    Text = "【カラスを追い払う】20黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7435_ChoiceDesc2 = {
    Text = "【子供を追い続ける】離れる"
  },
  Event_7435_Desc = {
    Text = "あなたが追い払うと、カラスたちは四方八方に飛び去り、黒い羽が液体となって黒章のように滴り落ちる。"
  },
  Event_7435_Name = {
    Text = "黒いカラスの視線"
  },
  Event_7436_ChoiceDesc1 = {
    Text = "【抵抗を諦める】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_7436_ChoiceDesc2 = {
    Text = "【両手を引っ込める】"
  },
  Event_7436_Desc = {
    Text = "新型タイプライター。\nそれは顕微鏡のように繊細で精巧な、他とは違う独特な文字キーが備わっていた。\n\nあなたは好奇心に駆られ、手をそっと置く。\n\nすると手は制御を離れ、キーが跳ね回り始める。その動きは、キーボードの上で舞い踊るように、どんどん加速していく……"
  },
  Event_7436_Name = {
    Text = "インスピレーション"
  },
  Event_7437_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7437_Desc = {
    Text = "ただ生き延びようとする生き物が、休む場所を求めているだけだ……\n\nため息をつき、蝶の尾から流れる黒い液が頬に垂れるのを許す。"
  },
  Event_7437_Name = {
    Text = "黒い液体の蝶"
  },
  Event_7438_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7438_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_7438_Name = {Text = "休憩所"},
  Event_7439_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7439_Desc = {
    Text = "学校からの連絡を受け、馴染みのある声に心が安らいだ。\n\n気を引き締めて、先へ進む。"
  },
  Event_7439_Name = {Text = "休憩所"},
  Event_7440_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7440_Desc = {
    Text = "疑問が空気に溶け込み、誰も答えず、暖かい黄色の光が窓から差し込み、まるで思い出のように温かい。"
  },
  Event_7440_Name = {
    Text = "火山の追憶"
  },
  Event_7441_ChoiceDesc1 = {
    Text = "【拾い上げる】「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7441_ChoiceDesc2 = {
    Text = "【ためらう】25黒章を獲得する"
  },
  Event_7441_Desc = {
    Text = "小道の角の樽の中に、奇妙な色の物体が浮かんでいる。\n\n異常な存在がまるで「触れるな」と警告しているかのようだ。"
  },
  Event_7441_Name = {
    Text = "樽の中の浮遊物"
  },
  Event_7442_ChoiceDesc1 = {
    Text = "【彼女に渡す】3つの中から1つ低級遺物を獲得する"
  },
  Event_7442_ChoiceDesc2 = {
    Text = "【少し状況が】低級遺物「(RelicConfig.Arg1)」「(RelicConfig.Arg2)」を獲得し、2枚の「(Skill.Arg3)」に感染する"
  },
  Event_7442_Desc = {
    Text = "「こちらはミサゴからの通信です。\n私はエリカです。\n覚醒体ロータンの霊性指数に異常な変動を検知しました。\n支援が必要ですか？」"
  },
  Event_7442_Name = {
    Text = "支援通信"
  },
  Event_7443_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7443_Desc = {
    Text = "耳元の悪意ある囁きに従ったとたん、針のような鋭い叫びがねじれながら耳孔に刺さってきた。\n「やめて――早くやめて――言われた通りにしたじゃないか――やめ――」\n苦しみながら頭を抱えると、ぼんやりとした意識の中でカラスの群れの嘲笑が聞こえた。"
  },
  Event_7443_Name = {
    Text = "カラスの歌"
  },
  Event_7444_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7444_Desc = {
    Text = "ここに置かれているのは、放置されたものか、大切にされたものかのどちらかだ。\n後者なら、元の持ち主に返そう。"
  },
  Event_7444_Name = {
    Text = "孤独なシルバーコア"
  },
  Event_7445_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7445_Desc = {
    Text = "最も幸せなのは、無知であること。"
  },
  Event_7445_Name = {Text = "覗き見"},
  Event_7446_ChoiceDesc1 = {
    Text = "【怪物を生成】"
  },
  Event_7446_ChoiceDesc2 = {
    Text = "【空白の地形を生成】"
  },
  Event_7446_ChoiceDesc3 = {
    Text = "【虚空を生成】"
  },
  Event_7446_Desc = {
    Text = "何が生成できるか見てみよう"
  },
  Event_7446_Name = {
    Text = "【包装待ち】"
  },
  Event_7447_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7447_Desc = {
    Text = "「落ち着いて、」\nラモンナがあなたの頭を軽く叩く。\n「ただの過去の断片よ。\n誰かがこの次元の通路に落としたものね」\n\n確かに、懐かしい感じがする。"
  },
  Event_7447_Name = {
    Text = "記憶の断片・ウイスキー"
  },
  Event_7448_ChoiceDesc1 = {
    Text = "【集める】1つの低級遺物を高級遺物「(RelicConfig.Arg1)」にアップグレードする"
  },
  Event_7448_ChoiceDesc2 = {
    Text = "【それらを捨てる】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」と「(Skill.Arg3)」に感染する"
  },
  Event_7448_ChoiceDesc3 = {
    Text = "【注意深く観察する】25黒章を獲得する"
  },
  Event_7448_Desc = {
    Text = "ここには多くの壊れたシルバーコアがある。\n暗く、壊れて……質の良い状態ではない。\nだが、これらが蝋人形が「生き返る」理由の一つかもしれない。\n最も粗末なシルバーコアでも、奇跡を起こす可能性がある。"
  },
  Event_7448_Name = {
    Text = "縛られた魂"
  },
  Event_7449_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7449_Desc = {
    Text = "クムは彼女が捧げられるすべてを捧げた。\n\n次は、彼女の犠牲が無意味でないことを示す番だ。"
  },
  Event_7449_Name = {Text = "余熱"},
  Event_7450_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7450_Desc = {
    Text = "願わくば、風雪があなたたちに永遠の静寂を与えんことを。"
  },
  Event_7450_Name = {
    Text = "先人の遺物"
  },
  Event_7451_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7451_Desc = {
    Text = "あなたは依然として頑強であり、歌の中で自分を保っている。\n\nあなたは耳元の囁きを信じなかった。\n頼るものは人間の理性のみ。\n\nしかし……頼るべき堅固な地面が、黒い液体に覆われる日には、眼球をえぐり出して覗くことが、あなたの臨終の際の唯一の選択肢となるだろう。"
  },
  Event_7451_Name = {
    Text = "カラスの歌"
  },
  Event_7452_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7452_Desc = {
    Text = "クムはあなたに引き離され、その一撃をかろうじてかわした。\n\n彼女は、感謝の意を込めてあなたにうなずくと、再び実験体に突進した。"
  },
  Event_7452_Name = {Text = "闘技場"},
  Event_7453_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7453_Desc = {
    Text = "チリンチリン……\n硬貨が財布に落ち、澄んだ心地よい音が響いた。\n\n財布は満足げにそれを咀嚼すると、最後にひとつ満腹のげっぷをした。\n\nあなたの気前の良さに感服して、心を開いた。\n\n今や、この財布はあなたのものだ。"
  },
  Event_7453_Name = {
    Text = "貪欲な財布"
  },
  Event_7454_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7454_Desc = {
    Text = "黄銅の硬貨は、底の見えない深淵へと落ちていった――音ひとつ立てずに。\n\nあなたはじっと5分間、辛抱強く待った。\n\nやがて財布は苦しげなうめき声を漏らし、最後に漆黒の粘液を一塊吐き出した。\n\nそれは、言葉なき抗議だった。"
  },
  Event_7454_Name = {
    Text = "貪欲な財布"
  },
  Event_7455_ChoiceDesc1 = {
    Text = "【遠くを見る】"
  },
  Event_7455_ChoiceDesc2 = {
    Text = "【じっと耳を傾ける】"
  },
  Event_7455_Desc = {
    Text = "シレストが羅針盤を揺らすと、彼女は何も言わずとも歌が微かに響き始めた。\n\n船乗りの歌が時を超えて交錯し、混沌としながらも力強い船歌があなたを導き、船の反対側を見つめさせる。"
  },
  Event_7456_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7456_Desc = {
    Text = "あなたはこの小さな授業を中断した。\n\nピアノの手の動きから基礎音楽理論まで、容赦なく一つ一つ指摘する。\n\n音が止まり、少年と先生は一斉にあなたを見て、同じ不気味な微笑を浮かべている。\n\n133，355，244……\n再びピアノの音が響くが、依然としてひどく間違っている。\n\n彼らは何も聞こえていないのだ。"
  },
  Event_7456_Name = {
    Text = "ピアノレッスン"
  },
  Event_7457_ChoiceDesc1 = {
    Text = "【ポケットに入れる】"
  },
  Event_7457_Desc = {
    Text = "密境で発見される黒い印。\n\n交換所で遺物などと交換でき、エリアを離れると溶けて消滅する。"
  },
  Event_7457_Name = {Text = "黒章"},
  Event_7458_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7458_Desc = {
    Text = "まずは謎の男を見つけるのが先決だ。\nラモンナはそう思い足早に去った。"
  },
  Event_7458_Name = {Text = "噂話"},
  Event_7459_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7459_Desc = {
    Text = "意識を解放し、祈りの声を辿って深海へ沈む。\n\n海底に沈む黄金の国を見て、不朽の石像を見て、暗闇の中で輝く瞳と目が合う……\n「神の血を持たぬ者よ……去れ、去れ」"
  },
  Event_7459_Name = {
    Text = "夢の祈り"
  },
  Event_7460_ChoiceDesc1 = {
    Text = "【離れる】1つの呪われた遺物を選択し、「(Skill.Arg1)」に感染する"
  },
  Event_7460_Desc = {
    Text = "ラモンナは剣で実験体の喉を貫いた。\n\nクムは生命反応を失った実験体を振り払い、次の目標へと向かった。"
  },
  Event_7460_Name = {Text = "闘技場"},
  Event_7461_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7461_Desc = {
    Text = "カラスが自らの羽をむしる様子は、人間が己の肉体をむさぼる姿に酷似している。  \n\nこの恐怖に満ちた世界では、よくある光景だ。\nあなたはすべての命を救えない。"
  },
  Event_7461_Name = {
    Text = "融蝕液の涙"
  },
  Event_7462_ChoiceDesc1 = {
    Text = "【クムをなだめる】"
  },
  Event_7462_ChoiceDesc2 = {
    Text = "【クムの代わりに叫ぶ】"
  },
  Event_7462_Desc = {
    Text = "巨大な怪物が小さな人に向かって吠え、かつての仲間を呼び覚まそうとしている。\nしかし、傷ついた声帯からは低く奇妙な音しか出ない。"
  },
  Event_7462_Name = {
    Text = "友情の呼びかけ"
  },
  Event_7463_ChoiceDesc1 = {
    Text = "【離れる】サーチライトを探す"
  },
  Event_7463_ChoiceDesc2 = {
    Text = "【霧に突入する】Arg2ライフを失う"
  },
  Event_7463_Desc = {
    Text = "前方には濃い黒い霧が立ち込めている。\n軽率に侵入すれば、災いが降りかかるだろう。\n\n「サーチライト」を見つけて霧を払うべきかもしれない。"
  },
  Event_7464_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7464_Desc = {
    Text = "「君のようにカチカチ響く上顎の骨？\n生まれて初めて見たよ」\n\nあなたは顎骨さんの無礼な依頼を断った。顎骨さんは非常に失望したが、何とか礼儀を保った。\n\nあなたの忍耐強い聞き取りに感謝して、彼は小さな贈り物をくれた。"
  },
  Event_7464_Name = {
    Text = "カチカチ響く"
  },
  Event_7465_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7465_Desc = {
    Text = "あなたはこの奇妙な依頼を引き受け、顎骨さんを連れて行くことにした。\n\nそれはあなたのポケットの中で絶え間なくカチカチと音を立てる。\n仲間の翻訳によると、その発言には感謝、懐旧、そして後悔が含まれている。\n\n彼がなぜこのような姿になったのか？\n顎骨さんは多くを語らず、ただこう言った——\n\n「知っているだろう。@2を覗くとき、@2もまたこちらを覗いているのだ」"
  },
  Event_7465_Name = {
    Text = "カチカチ響く"
  },
  Event_7466_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7466_Desc = {
    Text = "それは絹のように滑らかに、あなたの鞄の中へと滑り込んだ。\n\nわずかな重さの増加と共に、かすかな感謝の声が聞こえた気がした。\n\nそれ以降、何の音も響くことはなかった。"
  },
  Event_7466_Name = {
    Text = "混沌の霊"
  },
  Event_7467_ChoiceDesc1 = {
    Text = "【前進】"
  },
  Event_7467_Desc = {
    Text = "カチャッ。\n\n鍵を差し込み、扉を軽く押し開けた。"
  },
  Event_7467_Name = {Text = "扉"},
  Event_7468_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7468_Desc = {
    Text = "その声は低く笑い、足元の液体が波紋を広げる。\n\n「すぐにわかるよ、死ぬ以外に絶対にやらなければならないことなんてない」"
  },
  Event_7468_Name = {
    Text = "あなたは見つけたくない"
  },
  Event_7469_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7469_Desc = {
    Text = "あなたはその記憶を手放し、  \n幻想の慰めから意識を引き剥がした。"
  },
  Event_7469_Name = {
    Text = "過去に沈む"
  },
  Event_7470_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7470_Desc = {
    Text = "ただの浅い、まどろみだっただけ。  \n\nけれど、慰めがなければ、この果てしなく長い夜を、どうやって越えるのか……"
  },
  Event_7470_Name = {
    Text = "過去に沈む"
  },
  Event_7471_ChoiceDesc1 = {
    Text = "【写真を拾い上げる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7471_Desc = {
    Text = "これは群像写真のセットだ。\n\n元気のない人々が鉄柵の後ろにしゃがみ、苦しそうな顔をしている。\n\nその中の1枚の写真があなたの注意を引く。\nそれは痩せた若い女性で、顔は無表情だ。\n\n冒涜的な異物が彼女の体の周りにぐるぐると巻きついている。"
  },
  Event_7471_Name = {
    Text = "正確な記録"
  },
  Event_7472_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7472_Desc = {
    Text = "それは鳥の残骸だ。"
  },
  Event_7472_Name = {
    Text = "騒乱のカラスの群れ"
  },
  Event_7473_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7473_Desc = {
    Text = "あなたは冷たくピアニストの頼みを拒絶した。\n\nピアニストはひどく失望し、もう片方の耳も引きちぎり、窓の外に投げ捨てた。\n\n「どうせ必要ないから」\n憂鬱なピアニストは悲しげな顔で、哀しい音符を打ち鳴らした。"
  },
  Event_7473_Name = {
    Text = "耳を傾ける"
  },
  Event_7474_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7474_Desc = {
    Text = "混沌の霊の泣き声は次第に鋭さを増し、ついには耳をつんざく悲鳴となり、周囲に響き渡る。\n\nあなたからの供物と逃れられない悲しみを抱え、それは再び泥の深淵へと沈んでいった。"
  },
  Event_7474_Name = {
    Text = "混沌の霊"
  },
  Event_7475_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7475_Desc = {
    Text = "これは一方通行で、入口に戻ることはできない。"
  },
  Event_7475_Name = {Text = "通路"},
  Event_7476_ChoiceDesc1 = {
    Text = "【離れる】遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7476_Desc = {
    Text = "「それでは、少々目を閉じて、静かにその足音が近づいてくるのを感じてみてください」\n\n言われた通りに目を閉じると、瞬時に不気味な獣の息遣いが耳元で轟いた。\n\n驚いて目を開けると、先ほどの男性はすでに姿を消していた。"
  },
  Event_7476_Name = {
    Text = "奇妙な旅の伴Ⅰ"
  },
  Event_7477_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7477_Desc = {
    Text = "「それは本当に残念です」\n男性は声を落とし、眼鏡を直した。\n\n「しかし、聞いたことがないなら、何故こんなに夜遅くにここに来たのでしょうかね？」\n\nあなたが答える前に、男性は去っていった。"
  },
  Event_7477_Name = {
    Text = "奇妙な旅の伴Ⅰ"
  },
  Event_7478_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7478_Desc = {
    Text = "しっかりとした足取りで、前へ進む。\n一歩、二歩、三歩……\n背後の足音は闇に消える。\nまた会えるだろう。"
  },
  Event_7478_Name = {Text = "革靴"},
  Event_7479_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7479_Desc = {
    Text = "あなたは半身を起こし、隣のテーブルのトレイを手に持ち、姫君の従者に変身した。\nさて、誰がその幸運な姫君になったかというと——もちろん、あなたの最も忠実なる相棒だ。\n\n「私の顔にお茶をこぼしたら、来月の授業ノートは期待しないことね」\nこれは姫君からの警告だ。"
  },
  Event_7479_Name = {
    Text = "見事な偽装"
  },
  Event_7480_ChoiceDesc1 = {
    Text = "【静かに聞く】ランダムなカード1枚の刻印をアップグレードする"
  },
  Event_7480_ChoiceDesc2 = {
    Text = "【彼女こそが】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7480_Desc = {
    Text = "サラの叫びがあなたの頭の中で響き渡る。\n\nどこからともなく聞こえる微かな声が\n「サラ姉さん、サラ姉さん」と囁いている。\n\n「サラ姉さん、どこにいるの？」"
  },
  Event_7480_Name = {
    Text = "「サラ姉さん」"
  },
  Event_7481_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7481_Desc = {
    Text = "「……あなたの言うことに一理あるかもと思ってしまったけど、渇望では融蝕生物を解決できないわ。\nもっと実働的なことをしましょう」"
  },
  Event_7481_Name = {
    Text = "ロゴス（理性）の原理"
  },
  Event_7482_ChoiceDesc1 = {
    Text = "【100黒章を獲得】"
  },
  Event_7482_ChoiceDesc2 = {
    Text = "【ランダムな2枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」】"
  },
  Event_7482_Desc = {
    Text = "遺物は安定した霊知の凝固でできており、もしかすると、それらは調和の取れたメロディをもたらすかもしれない。"
  },
  Event_7482_Name = {
    Text = "不協和音"
  },
  Event_7483_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7483_Desc = {
    Text = "「これはこの次元に入った誰かの記憶の欠片ね」\nとラモンナが答えた。\n「次元を行き来する時、こういうことに遭遇しやすい。\n自分の記憶と混同しないように気をつけて」"
  },
  Event_7483_Name = {
    Text = "記憶の断片・ウイスキー"
  },
  Event_7484_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7484_Desc = {
    Text = "心臓のリズムに従い、光を追え。\nあなたたちは分かれることはない、昼と夜を正確に区別できないように。"
  },
  Event_7485_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7485_Desc = {
    Text = "あなたは不安定な手を撫で続け、静かにさせようとする。\n\nしばらくすると、あなたの世界は完全に静寂に包まれた。\n\n愛はいつも報われる。"
  },
  Event_7485_Name = {
    Text = "暗色の沼"
  },
  Event_7486_ChoiceDesc1 = {
    Text = "【足掻く】「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7486_ChoiceDesc2 = {
    Text = "【諦める】「(Skill.Arg1)」に感染し、低級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7486_ChoiceDesc3 = {
    Text = "【警戒する】25黒章を獲得する"
  },
  Event_7486_Desc = {
    Text = "あなたの脳に濁った物が流れ込み、その汚れた異物感が非常に鮮明だ。\n\nその濁った、悪臭を放つ液体が漏れ出し、すべての思考を占領して、恐怖と痛みが這い上がり、無限の悪夢のループから抜け出せない。"
  },
  Event_7486_Name = {
    Text = "頭の中の穴"
  },
  Event_7487_ChoiceDesc1 = {
    Text = "【メンフィスの鏡】"
  },
  Event_7487_ChoiceDesc2 = {
    Text = "【それは方位磁針だ】"
  },
  Event_7487_ChoiceDesc3 = {
    Text = "【私は何も落としていない】"
  },
  Event_7487_Desc = {
    Text = "「次元を超える先駆者よ」\n\n耳元に古びた声が響く。\nそれは太古から来たようで、時を超えているようだ。\n\n極度の緊張の中で、あなたはその声が少し聞き覚えのある質問をするのを聞く。\n\n「あなたが落としたのは、この丸い、ターン開始時にドローできるものですか？」"
  },
  Event_7487_Name = {
    Text = "界外の音"
  },
  Event_7488_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7488_Desc = {
    Text = "「ここは廃品回収所じゃないんだけど」\n\nドールはぶつぶつ言いながら受け取る。\n\n「まあ、多少は役に立つかもね」"
  },
  Event_7488_Name = {Text = "銘板"},
  Event_7489_ChoiceDesc1 = {
    Text = "ランダムな下位刻印"
  },
  Event_7490_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7490_Desc = {
    Text = "あなたは斑模様の破れた紙を読む。\n「双生」、「浸潤」、「生贄」、「無効」……\n\n相変わらず断片的な概念と解読困難な文章だ。\n膨張する脳だけがこのページを読んだ証拠となった。"
  },
  Event_7490_Name = {
    Text = "密命・下"
  },
  Event_7491_ChoiceDesc1 = {
    Text = "【あなたはどのような対価を払うおつもり？】ランダムなカード1枚の刻印をアップグレードする"
  },
  Event_7491_ChoiceDesc2 = {
    Text = "【期限切れのブラッディ・マリーを一杯奢ろう】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7491_Desc = {
    Text = "「いらっしゃいませ、私の大切なお客様。\nどうぞご自由に選んでください、ここにあるものはすべてあなたを待っていました」\n\n「えっと、失礼ですが、あなたは……ダフォダイルさんの双子の姉妹ですか？」\n\n「私はダフォダイル本人です。\nお客様、今日はどのようなご用件で……？」\n\n「申し訳ありません、以前よりも魅力的になられていて、気づきませんでした。\n覚えていますか？\n二十年前、あなたが私のバーから奇妙な奴を追い出してくれたことを……昨日、その悪夢が再び現れました。\n奴は仲間を引き連れてバーを占領して……」"
  },
  Event_7491_Name = {
    Text = "記憶の断片・昔の夢が甦る"
  },
  Event_7492_ChoiceDesc1 = {
    Text = "【カラスを追い払う】30黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7492_ChoiceDesc2 = {
    Text = "【子供を追い続ける】離れる"
  },
  Event_7492_Desc = {
    Text = "二羽目のカラスが去り、その尾羽が羽ばたくたびに白が見え、まるで白骨のようだ。"
  },
  Event_7492_Name = {
    Text = "黒いカラスの視線"
  },
  Event_7493_ChoiceDesc1 = {
    Text = "【賭ける】「(Skill.Arg1)」に感染し、賭けに入る"
  },
  Event_7493_ChoiceDesc2 = {
    Text = "【やはりやめる】25黒章を獲得する"
  },
  Event_7493_Desc = {
    Text = "「一度賭けてみない？私たちの点数を当ててごらん！ほんの少しの代償で！」\n捨てられたダイスが騒がしく鳴り、まるで話しかけてくるようだ。\n\n「投げて！投げて！」\n「たった一度！最後の一度！」\nよし、一度だけ——\nあなたはチップを手に取り、決断する——"
  },
  Event_7493_Name = {
    Text = "止まらぬ賭け"
  },
  Event_7494_ChoiceDesc1 = {
    Text = "【悪意に抵抗する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7494_ChoiceDesc2 = {
    Text = "【悪意を受け入れる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7494_ChoiceDesc3 = {
    Text = "【正気に戻って離れる】25黒章を獲得する"
  },
  Event_7494_Desc = {
    Text = "悪念が刃となり、まるで鋭い牙のよう。\n\nそれらは密境で弱まる理性を噛み砕き、残る意志をも貪り尽くす。\n\nそれはまるで現実があなたに対して行う悪行と同じように……"
  },
  Event_7494_Name = {
    Text = "無妄の念"
  },
  Event_7495_ChoiceDesc1 = {
    Text = "【全力で足掻く】指令カードを1枚削除し、Arg1黒章を獲得する"
  },
  Event_7495_ChoiceDesc2 = {
    Text = "【蜘蛛の巣に火をつける】指令カードを1枚複製し、「(Skill.Arg1)」に感染する"
  },
  Event_7495_ChoiceDesc3 = {
    Text = "【静かに待つ】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7495_Desc = {
    Text = "細い糸が蜘蛛の巣のようにあなたを絡め取り、この瞬間、あなたは密境の獲物となった。"
  },
  Event_7495_Name = {
    Text = "深淵に沈む"
  },
  Event_7496_ChoiceDesc1 = {
    Text = "【宛先：∞】「(Skill.Arg1)」に感染する"
  },
  Event_7496_ChoiceDesc2 = {
    Text = "【宛先：自分】カードを1枚削除する"
  },
  Event_7496_ChoiceDesc3 = {
    Text = "【宛先：先生】25黒章を獲得する"
  },
  Event_7496_Desc = {
    Text = "彼は密境の旅人にチャンスを与えた――未知へと繋がるチャンスを。\n\n数枚の破れた紙、インクが漏れるタイプライター、そして未知の一方的な受取人。\n\n意志があれば、あなたのメッセージがどこに届くかを決められるかもしれない……"
  },
  Event_7496_Name = {
    Text = "一方的な訴え"
  },
  Event_7497_ChoiceDesc1 = {
    Text = "【快く応じる】"
  },
  Event_7497_ChoiceDesc2 = {
    Text = "【断固として拒否する】"
  },
  Event_7497_Desc = {
    Text = "空っぽの環境に囁き声が響く。\n\n「おお、あのバカか。\n死ぬか勝つかって言ってる有体なギャンブラーだ。\n役立たずだから、近づかない方がいいよ」\nやつれた影があなたに数枚のコインを投げ、金属の音が手のひらに響く。\n\n「一局やろう」"
  },
  Event_7497_Name = {
    Text = "有体なギャンブラー"
  },
  Event_7498_ChoiceDesc1 = {
    Text = "【私たちは皆無事だ】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7498_ChoiceDesc2 = {
    Text = "【あなたは誰？】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7498_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7498_Desc = {
    Text = "タイプライターが突然インクを噴き出し、驚くほど多くの感嘆符が目に刺さる。\n\n「ドール、大丈夫か？？？\nなぜ守秘者が消えたら君も消えたんだ！！！\n無事ならメッセージを返してくれ！！！\n\n待ち続けてたら、ウィリアムの髪が全部抜けちゃうぞ！！！」"
  },
  Event_7498_Name = {
    Text = "緊急通信"
  },
  Event_7499_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7499_Desc = {
    Text = "最後の石膏をはめ込むと、彼女は鋭い笑い声を上げ、黒い煙が巻き上がり、彼女の姿はあなたの視界から消えた。"
  },
  Event_7499_Name = {
    Text = "残躯を補完する"
  },
  Event_7500_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7500_Desc = {
    Text = "あなたはシルバーキーを取り出し、哀切と敬虔を込めてその手に握り締める。\n\n淡い霧のような微光があなたを包む。\n\n一片の静寂の中、ただ、ため息だけが残る。"
  },
  Event_7500_Name = {
    Text = "凝視の眼"
  },
  Event_7501_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7501_Desc = {
    Text = "いまだ残る視線があなたを注視し、皮膚の下では血肉の細胞が狂乱し、逃れようと悲鳴を上げる。\n\n血管は皮膚の下で這い回る虫のよう蠢く。\n\n得体の知れない力が流れ込むのを感じ、それは歪んだ四肢の異変と共鳴し、激しくほとばしる——"
  },
  Event_7501_Name = {
    Text = "凝視の眼"
  },
  Event_7502_ChoiceDesc1 = {
    Text = "【視線を避ける】ランダムに覚醒体を1体覚醒させる"
  },
  Event_7502_ChoiceDesc2 = {
    Text = "【視線を直視する】覚醒体を1体選択して覚醒させ、その霊知覚醒カードの行動力消費を2点減少させる。「(Skill.Arg1)」に感染する"
  },
  Event_7502_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7502_Desc = {
    Text = "次元のトンネルが無数の宇宙を繋ぎ、至高の通路で無数の目があなたたちを見つめる。"
  },
  Event_7502_Name = {
    Text = "彼の神の視線"
  },
  Event_7503_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7503_Desc = {
    Text = "混乱だ、混乱すぎる。\n\nすべての考えが一瞬で思考の流れに飲み込まれ、遠くへと流されていく。\n\n脳の中には、数え切れないほどの迷いと苦痛だけが沈んでいく。"
  },
  Event_7503_Name = {
    Text = "インスピレーション"
  },
  Event_7504_ChoiceDesc1 = {
    Text = "【ポケットに入れる】"
  },
  Event_7504_Desc = {
    Text = "飽和した融蝕液の中に何かが含まれているようだ……シルバーキーで観測してみよう。"
  },
  Event_7504_Name = {
    Text = "黒い水たまり"
  },
  Event_7505_ChoiceDesc1 = {
    Text = "【カラスを追い払う】35黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7505_ChoiceDesc2 = {
    Text = "【子供を追い続ける】離れる"
  },
  Event_7505_Desc = {
    Text = "一羽のカラスが去り、黒い羽がゆっくりと舞い落ちる。"
  },
  Event_7505_Name = {
    Text = "黒いカラスの視線"
  },
  Event_7506_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_7506_Desc = {
    Text = "ここは深淵の血戦の地、戦いには勇気だけでなく知恵も必要だ。\n\n目を凝らし、敵を観察せよ。\nすべてを倒す必要はない、リーダーを倒せばいい！"
  },
  Event_7506_Name = {
    Text = "修羅の試練"
  },
  Event_7507_ChoiceDesc1 = {
    Text = "【休憩】Arg2ライフを回復する"
  },
  Event_7507_Desc = {
    Text = "霧の中を探索していると、突然、胸の校章が微かに光を放つ。\n通信機から誰かが呼んでいる。"
  },
  Event_7507_Name = {Text = "休憩所"},
  Event_7508_ChoiceDesc1 = {
    Text = "【彼の後をつける】"
  },
  Event_7508_ChoiceDesc2 = {
    Text = "【挨拶する】"
  },
  Event_7508_Desc = {
    Text = "タッ。タッ。タッ。\n白い影が濃霧の中をゆっくりと進む。まるで帆船が静かな夜に向かうように。\n後ろ姿から見ると、少年のようだ。\nあなたは彼の疲れた足音を聞きながら、心の中で決意を固めた。"
  },
  Event_7508_Name = {
    Text = "終幕の儀Ⅰ"
  },
  Event_7509_ChoiceDesc1 = {
    Text = "【快く同意する】"
  },
  Event_7509_ChoiceDesc2 = {
    Text = "【警戒心を持つ】"
  },
  Event_7509_Desc = {
    Text = "融蝕生物がうめき声を上げて倒れる。驚いたことに、クレメンタインがその後ろに立っていた。\n「お別れを言いに来たの」\nあなたの問いかけには、彼女は答えず、言葉を重ねる。\n\n「あなたへの感謝として、いくつか手がかりを渡すことができる。でも……それにはあなたの信頼が必要。\n私に催眠をかけさせてくれるなら、私の知っているすべてを、あなたも知ることになる」\n\n彼女を信じられるか？\n\n「気をつけて」ラモンナが警告する。\n「彼女が何も企んでいないわけがない」"
  },
  Event_7509_Name = {
    Text = "催眠療法"
  },
  Event_7510_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_7510_Desc = {
    Text = "あなたが精神を集中させると、幻影は水墨画のように消えさる。\n\nあなたは前に進み続けるが、心のもやを完全に晴らすことはできない。"
  },
  Event_7510_Name = {Text = "幻影"},
  Event_7511_ChoiceDesc1 = {
    Text = "【哀れな生き物？】"
  },
  Event_7511_ChoiceDesc2 = {
    Text = "【進化した人類？】"
  },
  Event_7511_ChoiceDesc3 = {
    Text = "【あなたは一体誰だ？】"
  },
  Event_7511_Desc = {
    Text = "あなたたちが6度目に出会ったその男は、鋼の骨組みの高い場所に立ち、地上を見下ろしていた。\n\n吹き荒れる風が彼の長い髪をなびかせ、その下の蛇の姿を露わにする。\n\n彼の視線はあなたたちに集中し、しばらくしてから遠くの闇へと投げかけられた。\n\n「はぁ、なんと哀れな生き物でしょう。\n\n裏切られる感覚とは、きっと<Bold:進化>した人類のように甘美なのでしょうね」"
  },
  Event_7511_Name = {
    Text = "奇妙な旅の伴Ⅵ"
  },
  Event_7512_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7512_Desc = {
    Text = "地獄の番犬の視線の中で、誰がフィルムに注目するだろうか？"
  },
  Event_7512_Name = {
    Text = "記憶の光影"
  },
  Event_7513_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7513_Desc = {
    Text = "見ない、話さない、聞かない、考えない——賢い選択。"
  },
  Event_7513_Name = {
    Text = "ルーンの狂気"
  },
  Event_7514_ChoiceDesc1 = {
    Text = "【離れる】カードを2枚削除する"
  },
  Event_7514_Desc = {
    Text = "周囲の騒がしい音の中で、奇妙な羽ばたき音がかすかに聞こえた。\n\nシルバーキーが胸で激しく振動し、何かの力に導かれて見上げると、空に巨大な黒い穴が現れた。\n\n「残念、残念、でも問題はない。\nまた会えるでしょう、敬愛なる無目の眼」"
  },
  Event_7514_Name = {
    Text = "催眠療法"
  },
  Event_7515_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7515_Desc = {
    Text = "周囲を無視できても、心臓の鼓動は無視できない。\n鼓動は速まり、君を急かし、責める。"
  },
  Event_7516_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7516_Desc = {
    Text = "「それなら良かった！！！\nウィリアム先輩の髪は助かった！！！」\n\n文字情報だけなのに、電報の内容からその叫び声が聞こえてくるようだ。"
  },
  Event_7516_Name = {
    Text = "緊急通信"
  },
  Event_7517_ChoiceDesc1 = {
    Text = "【彼に真実を伝える】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_7517_ChoiceDesc2 = {
    Text = "【真実を隠す】3つの中から1つ刻印を獲得する"
  },
  Event_7517_Desc = {
    Text = "「助けてください」\n憂鬱な旅人があなたの手を掴む。\n彼はここで何百年も彷徨っている。\n\n「私は兵士で、遠い東方へ異教徒を討伐する命を受けた。密林を抜け、川を渡った……しかし道に迷い、何度も同じ場所に戻ってしまうのだ。\n\n何かが暗闇で私を見ている。\n見えないが、わかる。ずっと見られている。\n\n今はただ家に帰りたい……」\n\nあなたは彼の背後に漂う影を見つめる。\n\nそれは最初はぼんやりしていたが、次第に鮮明になっていく——それは大きく開いた口で、百年も漬け込まれた迷える魂を待ち望んでいる。"
  },
  Event_7517_Name = {
    Text = "呑み込む者"
  },
  Event_7518_ChoiceDesc1 = {
    Text = "【闇の奥へ進む】"
  },
  Event_7518_ChoiceDesc2 = {
    Text = "【別れを告げる】"
  },
  Event_7518_Desc = {
    Text = "「シレスト、今回は助けてくれるよね」\n少女は不安げにその場を行ったり来たりし、時折静かな覚醒体を振り返った。\n\n彼女は少女に答えず、少女の表情がますます焦る中、微風が白いヴェールを巻き上げ、少女をある方向へとそっと押した。\n\n「私はあなたを守る」\n私はあなたを守る、「加護」に関してかつて失敗したことがあっても。\n\nでも今回は、あなたを一人で暗闇に迷わせはしない。"
  },
  Event_7518_Name = {
    Text = "航船の聖女の加護"
  },
  Event_7519_ChoiceDesc1 = {
    Text = "【離れる】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7519_Desc = {
    Text = "その歌声の中には古く、洪水が広がる前に失われたものもあれば、新しく、昨年の新年に妻がロンディニウムのデパートで買った新しい手袋を歌うものもある……感情が重なり合った混乱の後、心には空虚が残る。"
  },
  Event_7520_ChoiceDesc1 = {
    Text = "【色彩を駆逐する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7520_ChoiceDesc2 = {
    Text = "【色彩を抱擁する】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7520_ChoiceDesc3 = {
    Text = "【背を向けて離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7520_Desc = {
    Text = "マーフィーは一歩も離れず後に続くが、ある角を曲がるとその場で固まった。\n\n流れる色彩が目の前で渦巻き、空気にため息を巻き起こす。\n\n「マー@1……」\nそれはソナニール号の牢獄に囚われた溺れた魂か？それとも生者を追う亡き親友か？"
  },
  Event_7520_Name = {
    Text = "懐かしい色"
  },
  Event_7521_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7521_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7521_Desc = {
    Text = "耳元に聞き慣れた声が響き、親しみと安心感を与える。\n声を追おうとすると、突然途切れてしまった。"
  },
  Event_7521_Name = {
    Text = "異常な連絡"
  },
  Event_7522_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7522_Desc = {
    Text = "「あれは冒涜的な音楽だ」\n\n耳から流れる血を押さえながら、そう確信する。"
  },
  Event_7522_Name = {
    Text = "禁忌の音色"
  },
  Event_7523_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7523_Desc = {
    Text = "その色彩はぼんやりと人間の形に歪んでいるが、彼らはその隅に立ち尽くし、最後の祝福を目で送っている。"
  },
  Event_7523_Name = {
    Text = "懐かしい色"
  },
  Event_7524_ChoiceDesc1 = {
    Text = "【聴く】3つの中から1つ高級遺物を獲得する"
  },
  Event_7524_Desc = {
    Text = "ダフォダイルの声が一瞬止まった。\n\n「あら、これを選んだの？いい選択ね。\nご褒美に特別なプレゼントをあげるわ」"
  },
  Event_7524_Name = {
    Text = "ヒントの時間"
  },
  Event_7525_ChoiceDesc1 = {
    Text = "【尋問を続ける】「(Skill.Arg1)」に感染する"
  },
  Event_7525_ChoiceDesc2 = {
    Text = "【尋問を諦める】カードを1枚選択し、削除する"
  },
  Event_7525_Desc = {
    Text = "「うん、賢い選択ね。\n強敵を前にして、自分を知りたいと思うのは当然よね？\nでも、次元の秘密を知りすぎると、精神を乱すことになるわよ？」"
  },
  Event_7525_Name = {
    Text = "ヒントの時間"
  },
  Event_7526_ChoiceDesc1 = {
    Text = "【尋問を続ける】ダフォダイルを激怒させ、戦闘に入る"
  },
  Event_7526_ChoiceDesc2 = {
    Text = "【尋問を諦める】少しの罰を受ける"
  },
  Event_7526_Desc = {
    Text = "「あら？\nこんな時にまだ私を追いかけるつもり？\n欲張りすぎは良くないのよ？」"
  },
  Event_7526_Name = {
    Text = "ヒントの時間"
  },
  Event_7527_ChoiceDesc1 = {
    Text = "【じっと見つめる】最大ライフをArg1増加させる"
  },
  Event_7527_ChoiceDesc2 = {
    Text = "【無視する】ランダムな2枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、2枚の「(Skill.Arg2)」に感染"
  },
  Event_7527_Desc = {
    Text = "地獄の番犬を追い、小さな町の道を駆ける。\n\n冷たい雪が空から舞い降り、頬や胸に優しく触れ騒がしい心を慰める。"
  },
  Event_7528_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7528_Desc = {
    Text = "あなたは両腕を振り回し、厄介なカラスを追い払おうとする。\n\n彼らはカーカーと笑い声を上げ、あなたの愚かさと弱さを嘲笑っているようだ。\n\nそれでも、あなたの勇気は彼らを感動させ、相応の報酬を得た。"
  },
  Event_7528_Name = {
    Text = "カラスの群の歌"
  },
  Event_7529_ChoiceDesc1 = {
    Text = "【リリーについて】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7529_ChoiceDesc2 = {
    Text = "【ケルベロスについて】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7529_Desc = {
    Text = "無限の扉を越えて、遥か彼方からダフォダイルの声が聞こえてきた。\n\n「こちらはダフォダイルのヒントの時間」"
  },
  Event_7529_Name = {
    Text = "ヒントの時間"
  },
  Event_7530_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7530_Desc = {
    Text = "あなたは依然として頑強であり、歌の中で自分を保っている。\n\nあなたは耳元の囁きを信じなかった。\n頼るものは人間の理性のみ。\n\nしかし……頼るべき堅固な地面が、黒い液体に覆われる日には、眼球をえぐり出して覗くことが、あなたの臨終の際の唯一の選択肢となるだろう。"
  },
  Event_7530_Name = {
    Text = "カラスの群の歌"
  },
  Event_7531_ChoiceDesc1 = {
    Text = "【地獄の番犬の根源を直視する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7531_ChoiceDesc2 = {
    Text = "【戦闘に集中する】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7531_Desc = {
    Text = "地獄の番犬の輪郭が変化している。\n\nその体は壁の隙間と繋がり、怪しい幻影を見せる。"
  },
  Event_7531_Name = {
    Text = "角度から"
  },
  Event_7532_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7532_Desc = {
    Text = "「ニャー、ニャーニャー、ニャーニャー……」\n声を絞り出し、弱々しく無害に見せようとする。\n\n「ニャー！ニャーニャー！\nニャーニャーニャー！」\n\n猫たちは善意を受け入れ、響き渡る声で応える。\n声が昼夜を問わず交互に響きわたる。"
  },
  Event_7532_Name = {Text = "猫の街"},
  Event_7533_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7533_Desc = {
    Text = "ただ生き延びようとする生き物が、休む場所を求めているだけだ……\n\nため息をつき、蝶の尾から流れる黒い液が頬に垂れるのを許す。"
  },
  Event_7533_Name = {
    Text = "黒い液体の蝶"
  },
  Event_7534_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7534_Desc = {
    Text = "全力で猫たちから遠ざかる。\n\n振り返ると、猫たちはすでにそれぞれの場所に戻っている。\n毛づくろいをしたり、昼寝をしたり、喧嘩をしたり……\n正直、人間には興味がないようだ。"
  },
  Event_7534_Name = {Text = "猫の街"},
  Event_7535_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7535_Desc = {
    Text = "手に残った肉片を猫たちに投げ込む。\n\n猫たちは黒い波のように押し寄せ、狂ったように肉を噛みちぎり、すぐに散らばる。\n\n残念ながら、それは期限切れの肉。\n空腹は満たすが、あまり気持ちよくはない。"
  },
  Event_7535_Name = {Text = "猫の街"},
  Event_7536_ChoiceDesc1 = {
    Text = "【眼を直視する】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7536_ChoiceDesc2 = {
    Text = "【抵抗を諦める】ランダムな覚醒体を2体選択して覚醒させ、2枚の「(Skill.Arg1)」に感染する"
  },
  Event_7536_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7536_Desc = {
    Text = "無数の眼があなたの耳元で囁く。\n\n「我々は旅をし、立ち止まり、幾億年、いやそれ以上の時間を駆け抜けてきた。\n\n太陽がその眼差しの中で、少しずつ光を失い、旧地球の生命が洪水に飲まれるとき——\n我々はすでに宇宙の神秘に深く心奪われていた」"
  },
  Event_7537_ChoiceDesc1 = {
    Text = "【恐れを感じる】ランダムに覚醒体を1体覚醒させる"
  },
  Event_7537_ChoiceDesc2 = {
    Text = "【満足を感じる】覚醒体を1体選択して覚醒させ、その霊知覚醒カードの行動力消費を2点減少させる。「(Skill.Arg1)」に感染する"
  },
  Event_7537_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7537_Desc = {
    Text = "月も星もない空を見たことがあるだろう。\n\n星々の代わりに、空に浮かぶのは、無数の巨大な瞳だった。\n\n手を伸ばせば、それをもぎ取って、血肉を飛び散らせることができそうだ。\n\nだが、五指を広げても、そこには何もない。\n\n運命の瞳は、瞬きせずにあなたを見つめ、混沌の宇宙から、きらめく砂粒を一つ拾い上げている。"
  },
  Event_7537_Name = {
    Text = "穹頂の瞳"
  },
  Event_7538_ChoiceDesc1 = {
    Text = "【耳を塞ぐ手を下ろす】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7538_ChoiceDesc2 = {
    Text = "【引き続き耳を塞ぐ】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7538_Desc = {
    Text = "叫び声、終わりなき叫び声——\n\nカラスの歌い手は黒光りする羽毛をまとい、鋭いくちばしは冷たい光を放つ。\n鋭い悲鳴が何度もあなたの鼓膜を突き破る。\n\n——耳を塞ぐ手を下ろせ！\n\n夜に高らかに鳴くカラスの群れは、あなたの身に潜む未熟な震えを飲み干そうとしている。"
  },
  Event_7538_Name = {
    Text = "カラスの歌"
  },
  Event_7539_ChoiceDesc1 = {
    Text = "【猫の鳴き真似をする】50黒章を獲得する"
  },
  Event_7539_ChoiceDesc2 = {
    Text = "【餌をやる】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7539_Desc = {
    Text = "黒猫の縄張りに迷い込んだ。\n\n暗闇で無数の目が突然開き、探るように、見つめるように、警戒している……善意はない。\n\nエメラルドグリーン、アンバーホワイト、ピーコックブルー……\nまるで輝く宝石の海にいるようだ。\n\n脱出するために、あなたは——"
  },
  Event_7539_Name = {Text = "猫の街"},
  Event_7540_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7540_Desc = {
    Text = "あなたは一際目立つ手に気づく。\nそれは繊細で白く、終始落ち着いている。\n\nさらに重要なのは——それが自分の手だと気づいたこと。\n\n即座に決断し、それを強くねじ切った。\n\n耳元に無数の耳障りな叫び声が響き、沼地はついに消えた。"
  },
  Event_7540_Name = {
    Text = "暗色の沼"
  },
  Event_7541_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7541_Desc = {
    Text = "「賢明な選択だ」空っぽの人影が言う。\n「既に検証された選択には既定の結末があり、未知の行動は新たな未来を導く」\n\n微かな希望があなたを優しく包む。\n影は消え、あなたは胸を押さえる。さっきのものは、投影なのか、重圧下での幻覚なのか分からない。"
  },
  Event_7541_Name = {
    Text = "分かれ道"
  },
  Event_7542_ChoiceDesc1 = {
    Text = "【それを褒める】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7542_ChoiceDesc2 = {
    Text = "【それを嘲笑する】「(Skill.Arg1)」に感染し、再刻印を最大2回まで行う"
  },
  Event_7542_Desc = {
    Text = "脳が言う：鎖が私の前脳、脳幹、大脳皮質を縛るが、100億以上の真理を追求する小さな細胞は束縛できない。\n\nあなたが言う：誰があなたをここに閉じ込めたの？体はどこに？\n脳が言う：体？冗談はやめてくれ。\n昔は「豚肉売りのジョニー」と呼ばれていた。\n\n体があった頃は、10以下の足し算引き算も分からなかった。\n\nでも見てくれ！館長が余分な肉体を取り除いてくれた後、物理学者、哲学者、そしてアマチュア詩人になったんだ。"
  },
  Event_7542_Name = {
    Text = "哲学の脳"
  },
  Event_7543_ChoiceDesc1 = {
    Text = "【ゴールドバッハ予想を証明する】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7543_ChoiceDesc2 = {
    Text = "【旅の終点】ランダムなカード1枚が刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7543_ChoiceDesc3 = {
    Text = "【質問を拒否する】50黒章を獲得する"
  },
  Event_7543_Desc = {
    Text = "霊板を拾い上げると、若い女性の声があなたの脳内に飛び込んできた。\n\n「質問してみて、私は何でも知っている」\n「私の答えから、運命の贈り物を獲得することができる」"
  },
  Event_7543_Name = {Text = "交霊板"},
  Event_7544_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7544_Desc = {
    Text = "あなたは色あせた破れた紙を読み、断片的な文が口から流れ出る。\n「先祖」、「神子」、「永遠の死」、「長い記憶」などの言葉が頭を駆け巡り、悪夢で敏感になった神経を刺激する。"
  },
  Event_7544_Name = {
    Text = "密命・上"
  },
  Event_7545_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7545_Desc = {
    Text = "黒い液体が顔に滴り、かゆみを感じる。\n耐えられず、手を伸ばして蝶を払いのける。\n\n蝶はあなたの手をかわし、静かに消えていった。"
  },
  Event_7545_Name = {
    Text = "黒い液体の蝶"
  },
  Event_7546_ChoiceDesc1 = {
    Text = "【離れる】サーチライトを探す"
  },
  Event_7546_ChoiceDesc2 = {
    Text = "【霧に突入する】Arg2ライフを失う"
  },
  Event_7546_ChoiceDesc3 = {
    Text = "【直接進む】"
  },
  Event_7546_Desc = {
    Text = "前方には濃い黒い霧が立ち込めている。\n軽率に侵入すれば、災いが降りかかるだろう。\n\n「サーチライト」を見つけて霧を払うべきかもしれない。"
  },
  Event_7547_ChoiceDesc1 = {
    Text = "【幻覚を受け入れる】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7547_ChoiceDesc2 = {
    Text = "【幻覚を否定する】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7547_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7547_Desc = {
    Text = "重厚で暗い鉄橋の下、葦が生い茂る静かな河原に、突然光る蝶が飛び出した。\n\n蝶は軽やかにあなたの手のひらに舞い降り、騒がしい叫び声が止み、代わりに鉄筋を運ぶ作業員の掛け声、ハンマーの攻撃音、リベットの金属音が響く……"
  },
  Event_7547_Name = {
    Text = "鋼橋の幻覚"
  },
  Event_7548_ChoiceDesc1 = {
    Text = "【カラスを追い払う】40黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_7548_ChoiceDesc2 = {
    Text = "【子供を追い続ける】25黒章を獲得し、離れる"
  },
  Event_7548_Desc = {
    Text = "一羽のカラスがシャンデリアに止まっている。\n\n二羽のカラスがシャンデリアに止まっている。\n\n三羽のカラスがシャンデリアに止まっている。\n\n……\nそれらの漆黒の生物は首をねじり、路地のシャンデリアに立ち、悪意を含んだ目であなたを見下ろしている。\nその重なった頭は、まるで融蝕液に浸かった同じ体を共有しているかのようだ。"
  },
  Event_7548_Name = {
    Text = "黒いカラスの視線"
  },
  Event_7549_ChoiceDesc1 = {
    Text = "【離れる】覚醒体の数が3体未満の場合、低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7549_ChoiceDesc2 = {
    Text = "【離れる】覚醒している覚醒体の数が少なくとも3体の場合、高級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7549_Desc = {
    Text = "あなたはその裂け目を無視して、歩みを進めた。\n\n<Italic:覚醒した霊知とは何と重いことか——>\n\n\n\n裂け目はあなたの一歩ごとに広がり、ねじれ、うねり始める。\n\n今にも裂け目から腕が伸びてきて、あなたを深淵へと引きずり込もうとしているかのようだった。"
  },
  Event_7549_Name = {
    Text = "這う裂け目"
  },
  Event_7550_ChoiceDesc1 = {
    Text = "【視線に応える】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7550_ChoiceDesc2 = {
    Text = "【視線を避ける】ランダムな覚醒体を2体選択して覚醒させ、2枚の「(Skill.Arg1)」に感染する"
  },
  Event_7550_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7550_Desc = {
    Text = "あなたは視線を感じる。\nそれは次元を超え、密境を超えた視線で、あなたと目の前の少女を見つめている。\n呼吸が速くなり、理性の奥底で原始的な恐怖が叫び始める。"
  },
  Event_7550_Name = {
    Text = "誰かの視線"
  },
  Event_7551_ChoiceDesc1 = {
    Text = "【探し続ける】最大ライフをArg1増加させ、「(Skill.Arg2)」に感染する"
  },
  Event_7551_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7551_Desc = {
    Text = "ぼんやりとした光が目の前に現れ、明るく暖かい。\n光を追おうとすると、突然消えてしまった。"
  },
  Event_7551_Name = {
    Text = "異常な連絡"
  },
  Event_7552_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7552_Desc = {
    Text = "彼らの歌にそっと合わせ、暖かな水流が帰郷の祝福を運んでくれる。"
  },
  Event_7552_Name = {Text = "海の歌"},
  Event_7553_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_7553_Desc = {
    Text = "前方にかすかな光を発見し、ついに息苦しい霧を抜けた"
  },
  Event_7553_Name = {
    Text = "混沌の霧"
  },
  Event_7554_ChoiceDesc1 = {
    Text = "【下部の枝節を解く】"
  },
  Event_7554_Desc = {
    Text = "残留する密境の知識が絡み合い、不安定な力場を作り出している。\n\nもしかしたら、絡まった霊知を解きほぐし、自分の進むべき道を見つけられるかもしれない。"
  },
  Event_7554_Name = {
    Text = "絡み合う道"
  },
  Event_7555_ChoiceDesc1 = {
    Text = "【上部の枝節を解く】"
  },
  Event_7555_Desc = {
    Text = "残留する密境の知識が絡み合い、不安定な力場を作り出している。\n\nもしかしたら、絡まった霊知を解きほぐし、自分の進むべき道を見つけられるかもしれない。"
  },
  Event_7555_Name = {
    Text = "絡み合う道"
  },
  Event_7556_ChoiceDesc1 = {
    Text = "【左側の枝節を解く】"
  },
  Event_7556_Desc = {
    Text = "残留する密境の知識が絡み合い、不安定な力場を作り出している。\n\nもしかしたら、絡まった霊知を解きほぐし、自分の進むべき道を見つけられるかもしれない。"
  },
  Event_7556_Name = {
    Text = "絡み合う道"
  },
  Event_7557_ChoiceDesc1 = {
    Text = "【左側の枝節を解く】"
  },
  Event_7557_Desc = {
    Text = "残留する密境の知識が絡み合い、不安定な力場を作り出している。\n\nもしかしたら、絡まった霊知を解きほぐし、自分の進むべき道を見つけられるかもしれない。"
  },
  Event_7557_Name = {
    Text = "絡み合う道"
  },
  Event_7558_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7558_Desc = {
    Text = "あなたたちはまだ数回の激戦を控えている。\n\n今はのんびり調査している場合ではない。"
  },
  Event_7558_Name = {
    Text = "臓器登録"
  },
  Event_7559_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7559_Desc = {
    Text = "紙に書かれた文字が急に生き生きとし始め、その恐ろしい言葉が苦しむ者の信念と基盤を揺るがす。\n読むほどに混乱し、恐怖が増し、指先で頭皮を掻くのを止められない。\n\n突然、呪いの符号が消えた。\nラモンナが読書を中断し、強引にページを手提げ鞄に押し込んだ。"
  },
  Event_7559_Name = {
    Text = "密命・下"
  },
  Event_7560_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7560_Desc = {
    Text = "喜び、憂い、悲しみ、苦悩……\nこれらはすべてあなたの感情。\n\n無数の別世界にいるさまざまなあなたの感情だ。"
  },
  Event_7560_Name = {
    Text = "溺れ沈む"
  },
  Event_7561_ChoiceDesc1 = {
    Text = "【静かに聞く】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7561_ChoiceDesc2 = {
    Text = "【彼女はここにいる】3枚の指令カードから1枚を選んで刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7561_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7561_Desc = {
    Text = "怪物の悲鳴があなたの頭の中で響き渡る。\n形を成さない黒い粘液の中で、かすかな声が\n「サラ姉さん」「サラ姉さん」と囁いている。\n\n「サラ姉さん、どこにいるの？」"
  },
  Event_7561_Name = {
    Text = "「サラ姉さん」"
  },
  Event_7562_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7562_Desc = {
    Text = "「彼に加わり、彼らに加わり、私たちに加わる。\n\n彼の守護者となり、彼の代行者となる。\n\n彼の夢を進むべき道とする……」\n混乱した祈りが意識をかき乱し、声が消えた後に汗だくになっていることに気づく。"
  },
  Event_7562_Name = {
    Text = "夢の祈り"
  },
  Event_7563_ChoiceDesc1 = {
    Text = "【聞いたことがない】"
  },
  Event_7563_ChoiceDesc2 = {
    Text = "【聞いたことがある】"
  },
  Event_7563_Desc = {
    Text = "「そちらの学生さん、少しお時間良いですか？\n\nこの地の伝説について調べていまして、数分だけで良いので、少しお話しできませんか？\n\n『ケルベロス』という生物についてなのですが、ご存じありませんか？」"
  },
  Event_7563_Name = {
    Text = "奇妙な旅の伴Ⅰ"
  },
  Event_7564_ChoiceDesc1 = {
    Text = "【思考を放棄する】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7564_ChoiceDesc2 = {
    Text = "【啓示を追いかける】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」"
  },
  Event_7564_Desc = {
    Text = "襲撃された港、帰らぬ謎の貨物船、そしてヒレを生やした“新たな仲間”…これは周到に用意された罠なのか？それともまた事故が多発する予兆なのでしょうか？\n現実と理性が絡み合い、数え切れないほどの直感や提案が湧き出てきます。"
  },
  Event_7564_Name = {
    Text = "インスピレーション"
  },
  Event_7565_ChoiceDesc1 = {
    Text = "【アイズルワースの火山？】最大ライフをArg1増加させる"
  },
  Event_7565_ChoiceDesc2 = {
    Text = "【懸命に思い出す】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7565_Desc = {
    Text = "リリーの頬に黒い涙が流れる。\n「見たの、ママ」\n彼女はそっと囁く。\n「アイズルワースの火山で……」"
  },
  Event_7565_Name = {
    Text = "火山の追憶"
  },
  Event_7566_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7566_Desc = {
    Text = "「踏み@1…海……」\nルーンが目の前にちらつき、思わず手を伸ばしてしまう——\n「何してるの！追いつかれるよ！」\n謎の少女があなたを引っ張り、甲板の反対側へ走り出す。\n\nしかし、確かに何かの力が指先に痕跡を残した。"
  },
  Event_7566_Name = {
    Text = "ルーンの狂気"
  },
  Event_7567_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7567_Desc = {
    Text = "あなたは神秘的な呟きに興味がなく、リスクを冒して暗闇に入るつもりもない。"
  },
  Event_7567_Name = {
    Text = "救助要請の手紙"
  },
  Event_7568_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7568_Desc = {
    Text = "どうしても、守秘者の責務が胸に膨らみ、送り主を見つける希望を捨てられない。\nたとえそれが曖昧で不明瞭でも。"
  },
  Event_7568_Name = {
    Text = "救助要請の手紙"
  },
  Event_7569_ChoiceDesc1 = {
    Text = "【観察する】25黒章を獲得する"
  },
  Event_7569_ChoiceDesc2 = {
    Text = "【撫でる】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_7569_Desc = {
    Text = "小路に突然黒猫が飛び出してきて、異常に親しげに足元に絡みついてきた。\n\nその瞳は、まるで「追いかけるのをやめて、しばらく私と遊んで」と言わんばかりに、ぞっとするような光で輝いていた。"
  },
  Event_7569_Name = {
    Text = "夜の精霊"
  },
  Event_7570_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7570_Desc = {
    Text = "「ありえない、絶対信じない！」\n声が叫ぶ。\n\n「私を悪魔に渡したこの女は、私のサラ姉さんじゃない！」"
  },
  Event_7570_Name = {
    Text = "「サラ姉さん」"
  },
  Event_7571_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7571_Desc = {
    Text = "「了解しました。\n物資を輸送しますので、ご確認ください」"
  },
  Event_7571_Name = {
    Text = "支援通信"
  },
  Event_7572_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7572_Desc = {
    Text = "無用の物。"
  },
  Event_7572_Name = {
    Text = "先人の遺物"
  },
  Event_7573_ChoiceDesc1 = {
    Text = "【よく見る】3つの中から1つ刻印を獲得する"
  },
  Event_7573_ChoiceDesc2 = {
    Text = "【ポスターを剥がす】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7573_Desc = {
    Text = "蝋人形館内の随所に見られる燭台。\n\n病的な橙色の光で、壁に手描きのポスターが貼られているのを発見する。"
  },
  Event_7573_Name = {
    Text = "暗闇の中の笑い声"
  },
  Event_7574_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7574_Desc = {
    Text = "「リリーには彼女自身の心があり、誰にも従う必要はない」\nあなたは毅然と答える。\n\nフランシスは冷たく鼻で笑い、返事をしない。"
  },
  Event_7574_Name = {
    Text = "彼女の選択"
  },
  Event_7575_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7575_Desc = {
    Text = "これは集合写真の一組です。\n\n疲れ果てた人々が鉄柵の後ろでしゃがみ、苦しそうな顔をしている。\n\nその中の1枚があなたの注意を引いた。\nそれは痩せた若い女性で、顔は無表情。\n\n冒涜的な異物が彼女の体に巻き付いている。\n\n彼女の顔は見えないが、想像の中では無表情だろう。"
  },
  Event_7575_Name = {
    Text = "正確な記録"
  },
  Event_7576_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7576_Desc = {
    Text = "あなたは輝く装飾品に夢中になって見つめていたが、気づかぬうちに、干からびた黒い粘液の手を握っていた。\nそれはただわずかに手を握り締め、その後放した。\n何も起こらなかった、ただ一筋の黒い気が、あなたの指先から袖の中へと滑り込んだだけだった。"
  },
  Event_7576_Name = {
    Text = "翻覆の魔手"
  },
  Event_7577_ChoiceDesc1 = {
    Text = "【数音弾く】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7577_ChoiceDesc2 = {
    Text = "【蓋を閉める】3つの中から1つ刻印を獲得する"
  },
  Event_7577_Desc = {
    Text = "壁際のピアノは蓋が開いたままになっている。\n鍵盤は黄ばんでおり、端には木の色が見えるひび割れがあったが、どの鍵盤もきれいに拭き取られていた。"
  },
  Event_7577_Name = {
    Text = "幼少期のメロディ"
  },
  Event_7578_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7578_Desc = {
    Text = "槍を持つ者がうめき声を上げ、いじめられた子供のようにすすり泣く。\n\n声は瞬く間に消え、他の二人の海踊人も姿を消した……これは密境が映し出した幻影に過ぎなかった。"
  },
  Event_7578_Name = {Text = "追撃"},
  Event_7579_ChoiceDesc1 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7579_Desc = {
    Text = "「正しい答えだ」\n声の主はこの答えに非常に満足し、輝く物体が水面から投げ出された。\n「覚えておけ、すべてには代償がある」"
  },
  Event_7579_Name = {
    Text = "界外の音"
  },
  Event_7580_ChoiceDesc1 = {
    Text = "【幻影を払う】症状に感染する"
  },
  Event_7580_ChoiceDesc2 = {
    Text = "【離れる】"
  },
  Event_7580_Desc = {
    Text = "ぼんやりとした顔が周囲に現れ、絶望的な呻き声をあげる。"
  },
  Event_7580_Name = {Text = "幻影"},
  Event_7581_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7581_Desc = {
    Text = "あなたはその裂け目を無視して、歩みを進めた。\n\nしかし、まるで怒ったかのように、裂け目はあなたの一歩ごとに広がり、ねじれ、うねり始める。\n\n今にも裂け目から腕が伸びてきて、あなたを深淵へと引きずり込もうとしているかのようだった。"
  },
  Event_7581_Name = {
    Text = "這う裂け目"
  },
  Event_7582_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7582_Desc = {
    Text = "あなたは、そう簡単には騙されない。  \n\n迷いも未練もなく、きっぱりと背を向けて、その場を後にした。"
  },
  Event_7582_Name = {
    Text = "這う裂け目"
  },
  Event_7583_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7583_Desc = {
    Text = "あなたは裂け目の異様さに気づき、身をかがめて観察した。\n\n奇妙なことに、つい先ほどまで広がり続けていたその裂け目は、まるで突然死を迎えたかのように永遠の静寂へと沈み込んでいた。"
  },
  Event_7583_Name = {
    Text = "這う裂け目"
  },
  Event_7584_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7584_Desc = {
    Text = "「いいえ、冷静な頭よ。\n決意じゃ融蝕生物は解決できないわよ、守秘者。\nしっかり対策を考えましょう」"
  },
  Event_7584_Name = {
    Text = "ロゴス（理性）の原理"
  },
  Event_7585_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7585_Desc = {
    Text = "あなたは内なる衝動に抗えない。\n\n指先は森で迷子になった子供のように、キーボードの上をさまよい、遊び……\n\nやがて、タイプライターから蝶が飛び出した。\n\n一匹、二匹、三匹……\n顔や指先に、群れをなす蝶が空に咲く花火のように、暗闇で宝石のように輝く。\n\nこのタイプライターは実用性はないが、美を創造することに長けている。"
  },
  Event_7586_ChoiceDesc1 = {
    Text = "【めんどりを縛っておく】"
  },
  Event_7586_Desc = {
    Text = "ライ特産、元気な雌鶏、美食の誘惑。"
  },
  Event_7586_Name = {
    Text = "罠を作る"
  },
  Event_7587_ChoiceDesc1 = {
    Text = "【大成功】"
  },
  Event_7587_Desc = {
    Text = "安価で使いやすい罠！"
  },
  Event_7587_Name = {
    Text = "罠を作る"
  },
  Event_7588_ChoiceDesc1 = {
    Text = "【罠を仕掛ける】"
  },
  Event_7588_Desc = {
    Text = "金属製のトラップ、怠け者のハンターの頼れる味方。"
  },
  Event_7588_Name = {
    Text = "罠を作る"
  },
  Event_7589_ChoiceDesc1 = {
    Text = "【電報機を調べる】「(Skill.Arg1)」に感染し、高級遺物「(RelicConfig.Arg2)」を獲得する"
  },
  Event_7589_ChoiceDesc2 = {
    Text = "【無視する】50黒章を獲得する"
  },
  Event_7589_Desc = {
    Text = "あなたは狭い山洞の裂け目に身を潜め、吹雪を避けている。\nしかし、ここに長く留まれないことは分かっている。\n黒いローブの怪人たちがここを見つけたら逃げ場はない。\n\n裂け目の隅で、電報機を発見した。"
  },
  Event_7589_Name = {
    Text = "無声の電報"
  },
  Event_7590_ChoiceDesc1 = {
    Text = "【フィルムを検査する】2枚のカードの刻印効果をランダムにアップグレードする"
  },
  Event_7590_ChoiceDesc2 = {
    Text = "【カメラをチェックする】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7590_Desc = {
    Text = "内臓を引き出すように、カメラの中のフィルムが引き裂かれ、無造作に捨てられています。\n\n眩しい白い光が一瞬走り、捨てられたカメラが傾き、シャッターが勝手に切られます。\n\n「カシャッ——」\nあなたの驚いた表情がカメラのフィルムに記録されました。"
  },
  Event_7590_Name = {
    Text = "記録は無罪"
  },
  Event_7591_ChoiceDesc1 = {
    Text = "【歌い手の喉を絞める】呪われた遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7591_ChoiceDesc2 = {
    Text = "【ダンサーの歩みを躓かせる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_7591_ChoiceDesc3 = {
    Text = "【詩人の原稿を奪う】50黒章を獲得する"
  },
  Event_7591_Desc = {
    Text = "あなたは3つの粘つく人影に道を塞がれる。\n\n1つは歌を歌い、声はかすれて、歌詞は奇妙。\n\n1つは踊り、動きはぎこちなく、足取りが不安定。\n\n1つは詩を吟じ、リズムは崩れ、言葉は通じない。\n耐えきれず、そして——"
  },
  Event_7591_Name = {
    Text = "狭路の悪党"
  },
  Event_7592_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7592_Desc = {
    Text = "「いや！人類の進歩は歴史でも技術でもなく、鼠のおかげだ」\n「鼠があの暗黒時代を開き、その後に人類が復興の夜明けを迎えた」\n「人類は君たちを必要としている——理解していない人もいるけど」\n鼠たちは君の長い話に少し混乱したが、結局君を解放した。"
  },
  Event_7592_Name = {Text = "ペスト"},
  Event_7593_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7593_Desc = {
    Text = "あなたは視神経の痙攣をこらえ、何とか見分けようとする……\nそこには裂けた正円形の魔法陣が描かれているようだ。\n\n魔法陣の内部は無数の弧線で構成され、静止しているようで流動しているようにも見え、目がくらむ。"
  },
  Event_7593_Name = {
    Text = "角度から"
  },
  Event_7594_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7594_Desc = {
    Text = "<Bold>【ロジャーズ蝋人形館】\nサザーク・ストリート44番地、\nロンディニウム市@2区\n\n観覧時間：21:00-6:00　3:00入場停止（週末休館）\n\n<Bold>【現在の展示】\nウラジミール・@2：微笑の哲学"
  },
  Event_7594_Name = {
    Text = "暗闇の中の笑い声"
  },
  Event_7595_ChoiceDesc1 = {
    Text = "【向かい合う】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染"
  },
  Event_7595_ChoiceDesc2 = {
    Text = "【目を閉じる】覚醒体を1体選択して覚醒させ「(Skill.Arg1)」に感染する"
  },
  Event_7595_ChoiceDesc3 = {
    Text = "【背を向ける】25黒章を獲得する"
  },
  Event_7595_Desc = {
    Text = "本来なら、星空は見えないはずだ。\n\nソナニール号の密境では、天幕の光が流れ、星と月の姿は隠れている。\n\n薄暗い船室の中では、星空が見えるはずがない。\n\nここにあるのは、まばらな白熱灯と古いランタンだけのはずだ——\n\nそれなのに、何故かあなたは、空高くから見つめられていることを感じた。"
  },
  Event_7595_Name = {Text = "覗き見"},
  Event_7596_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7596_Desc = {
    Text = "あなたは勇敢に眼を見つめることを選んだ。\n\nそれらは暗闇の中で輝く星々のようだ。\nそして笑い、無数の三日月に変わった。\n\n「あなたは視線を恐れない。\n恐れるべきではない……久しぶりだな、@2」\n\n消える前に、彼らは「再会の記念」として小さな贈り物をくれた。"
  },
  Event_7597_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7597_Desc = {
    Text = "鉄道橋、ロンディニウムの血管と神経、都市の心臓と四肢を繋ぐ。太陽がここから沈まない限り、ロンディニウムの心臓は永遠に鼓動し続ける。"
  },
  Event_7597_Name = {
    Text = "鋼橋の幻覚"
  },
  Event_7598_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7598_Desc = {
    Text = "非常に華麗なフーガ曲、作曲者不詳。\n無数の声部が似たテーマを持って交錯し溢れる。\n\n各音符は外科医のメスのように正確で冷酷。\n精密で華麗——それこそがロジャーズの美学。\nFuga、飛翔せよ！"
  },
  Event_7598_Name = {Text = "悪趣味"},
  Event_7599_ChoiceDesc1 = {
    Text = "【声を出して挨拶する】"
  },
  Event_7599_ChoiceDesc2 = {
    Text = "【助けを求める】"
  },
  Event_7599_Desc = {
    Text = "手が船の縁に触れた瞬間、白いドレスの少女が見えた。\n\n高貴で、聖なる、虚構のような……どこか見覚えがある。\n\nどこで彼女を見たのだろう？混乱した記憶を掘り起こしていると、彼女が突然こちらに気づき、虚空を越えて目が合った。\n\n彼女の目は初春の海のように静かで、何かを読み取った気がした……\n彼女はあなたが挨拶するのを待っているようだ。"
  },
  Event_7599_Name = {
    Text = "白いドレスの少女"
  },
  Event_7600_ChoiceDesc1 = {
    Text = "【それを褒める】指令カード3枚から1枚選択し、刻印「(EnchantConfig.Arg1)」を獲得する"
  },
  Event_7600_ChoiceDesc2 = {
    Text = "【それを嘲笑する】「(Skill.Arg1)」に感染し、再度ランダムに刻印する"
  },
  Event_7600_Desc = {
    Text = "ジェンキンが言う：ジョニー！君は昔と本当に……全然違うね、どこから見ても。\n\n君が言う：君は本当に勤勉で追求心のある脳だね。\n\n脳は少し蠢いて、明らかに嬉しそうだ。\n\n脳が言う：さあ！君たちが私の今の成果を認めてくれるなら、私の生涯の学びを授けよう……"
  },
  Event_7600_Name = {
    Text = "哲学の脳"
  },
  Event_7601_ChoiceDesc1 = {
    Text = "【華麗なフーガ】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7601_ChoiceDesc2 = {
    Text = "【簡単なセレナーデ】すべての覚醒体が50狂気を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7601_ChoiceDesc3 = {
    Text = "【無意味なノイズ】3つの中から1つ刻印を獲得する"
  },
  Event_7601_Desc = {
    Text = "「個人的には館長の音楽の趣味には賛同できないんだがね。わかるだろう……派手すぎるんだよ。\n僕はもっと地に足のついた人間だからね」\nギシギシと回る蓄音機から、くたびれた男の声が孤独に訴えている。\n\n「でもこれが僕の仕事だからね……さあ、一枚選んでくれたまえ」"
  },
  Event_7601_Name = {Text = "悪趣味"},
  Event_7602_ChoiceDesc1 = {
    Text = "【特別な遺物がある場合、高級遺物「(RelicConfig.Arg1)」を獲得する】"
  },
  Event_7602_ChoiceDesc2 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7602_Desc = {
    Text = "事件253（開発中）、最終版ではありません"
  },
  Event_7602_Name = {
    Text = "事件253（開発中）"
  },
  Event_7603_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7603_Desc = {
    Text = "あなたは最速でその場を離れた。\n\n今、あなたたちは、今までで最も厄介で、気持ち悪い敵——密集した蝋人形たちに直面している。\n\nそれらと比べると、このいくつかの粗末な土の塊は本当に大したことはない。\n\n物事の優先順位を見極める——\nこれは守秘者が守るべき原則の一つだ。"
  },
  Event_7603_Name = {Text = "習作"},
  Event_7604_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7604_Desc = {
    Text = "シルバーキーが輝き、白銀の光が空間を満たし、濃厚な流れる色彩を純粋な銀に染める。\n\n光は瞬く間に消え、風だけが哀しい嘆きを残した。"
  },
  Event_7604_Name = {
    Text = "懐かしい色"
  },
  Event_7605_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7605_Desc = {
    Text = "その虹彩に目を奪われ、知らぬ間に陶酔してしまう……"
  },
  Event_7605_Name = {
    Text = "星々の分岐点"
  },
  Event_7606_ChoiceDesc1 = {
    Text = "【墜落を続ける】「(Skill.Arg1)」に感染する。引き続き墜落しますか"
  },
  Event_7606_ChoiceDesc2 = {
    Text = "【手を引いて離れる】25黒章を獲得する"
  },
  Event_7606_Desc = {
    Text = "「あなた」があなたを招いている。\n\n螺旋の奥で、過去と未来の「あなた」が異なる次元からの「贈り物」を送ってきた。"
  },
  Event_7606_Name = {
    Text = "螺旋の深淵"
  },
  Event_7607_ChoiceDesc1 = {
    Text = "【心得ている】高級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7607_ChoiceDesc2 = {
    Text = "【何も知らない】3つの中から1つ高級遺物を獲得し、「(Skill.Arg1)」に感染する"
  },
  Event_7607_ChoiceDesc3 = {
    Text = "【離れる】低級遺物「(RelicConfig.Arg1)」を獲得する"
  },
  Event_7607_Desc = {
    Text = "二つの銀白の光る人影が目の前に現れ、濃い液体のように空中に浮かんでいる。\n\n「ここが私が消滅した場所だ」\n一人の人影がしゃがみ込んだ。\n\n「病も災いもない神国では、渇望や喪失というものはない。あなたは本当の消滅を知らないだろう」\nもう一人の人影がため息をつき、あなたに視線を向けた。"
  },
  Event_7607_Name = {
    Text = "失われた神の国"
  },
  Event_7608_ChoiceDesc1 = {
    Text = "【離れる】サーチライトを探す"
  },
  Event_7608_ChoiceDesc2 = {
    Text = "【霧に突入する】「(Skill.Arg2)」に感染する"
  },
  Event_7608_ChoiceDesc3 = {
    Text = "【直接進む】"
  },
  Event_7608_Desc = {
    Text = "前方には濃い黒い霧が立ち込めている。\n軽率に侵入すれば、災いが降りかかるだろう。\n\n「サーチライト」を見つけて霧を払うべきかもしれない。"
  },
  Event_7609_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7609_Desc = {
    Text = "「これは記憶の投影ね」とラモンナがあなたに説明する。\n\n「ある個人のものかもしれないし、複数の人の共通の思い出かもしれないわ」\n\n大切な思い出、それは、大事に守るべきものだ。"
  },
  Event_7609_Name = {
    Text = "私たちの記憶"
  },
  Event_7610_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7610_Desc = {
    Text = "今は解読できなくても、帰校後に別の方法で情報を読み取ることを考えた。\n\nただ、手紙が不気味に縮むにつれ、胸に鈍い痛みが走り始めた。"
  },
  Event_7610_Name = {
    Text = "塗りつぶされた手紙"
  },
  Event_7611_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7611_Desc = {
    Text = "蝋燭が天秤から離れると同時にひとりでに火が付き、乳白色の涙が指の間から素早く滴り落ちて消えた。"
  },
  Event_7611_Name = {
    Text = "理性と感情"
  },
  Event_7612_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7612_Desc = {
    Text = "あなたは紙を一気に引き抜いたが、タイプライターはまだ動いていた。一枚のカードを巻き込み、インクでべったりと塗りつぶした。\nよく見ると、そこには「直視するな直視するな直視するな直視するな直視するな」と繰り返し書かれているようだった。"
  },
  Event_7612_Name = {
    Text = "不意の警告"
  },
  Event_7613_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7613_Desc = {
    Text = "指が冷たい杯の縁に触れたとき、突然身震いして正気に戻った。\n\nどう考えても、道端に置いておくべきではない。\n鞄にしまっておこう。"
  },
  Event_7613_Name = {Text = "蜂蜜酒"},
  Event_7614_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7614_Desc = {
    Text = "あなたは激しく咳をする。\n声は驚いたようで、その後は静まり返った。\n重要な手がかりを逃したような気がする……\nでも人生はいつもすれ違いと後悔で満ちている、そうだろう？"
  },
  Event_7614_Name = {
    Text = "壁に耳あり"
  },
  Event_7615_ChoiceDesc1 = {
    Text = "【口を固く閉ざす】25黒章を獲得する"
  },
  Event_7615_ChoiceDesc2 = {
    Text = "【手を伸ばし触れる】50%の確率で50黒章を獲得し、50%の確率で何も得られない"
  },
  Event_7615_Desc = {
    Text = "「私が言えるのは、ただひとつの格言——誰にも猫を殺すことはできない！」\n\n「あの忌まわしい黒猫は、本来ならば腹を裂かれ、荒野に晒されるべきだった。\n\nだが、奴は私の一族の墓を掘り起こし、残された人間の腐肉を貪り尽くした。\n\n骨と四肢は無惨にも散らばっていたのだ」\n\n「冷たく暗い縦長の瞳がこちらを見つめていた。\n\n黄ばんだ膿が悪臭を放ち、私は必死に転がるように逃げ出したんだ。\n\n毎夜悪夢に苛まれ、正気がすり減っていくんだ」\n\n「待て……何をするつもりだ！？\n\n私は狂ってなどいない！違う！お前たちは何かを隠そうとしている！これは真実だ——」\n\n——確かに、それは真実だった。\n\n狂気じみた影が闇へと消えゆくのを見送りながら、あなたは足元で静かに座る黒猫と目を合わせた。"
  },
  Event_7615_Name = {
    Text = "夜猫の災い"
  },
  Event_7616_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7616_Desc = {
    Text = "ためらっている間に、それは沈んで融蝕痕に溶け込み、すぐに消えてしまった。"
  },
  Event_7616_Name = {
    Text = "樽の中の浮遊物"
  },
  Event_7617_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7617_Desc = {
    Text = "手紙を丸めて足元に投げ捨てた。"
  },
  Event_7617_Name = {
    Text = "塗りつぶされた手紙"
  },
  Event_7618_ChoiceDesc1 = {
    Text = "【確定】"
  },
  Event_7618_Desc = {
    Text = "あなたが精神を集中させると、幻影は水墨画のように消えさる。\n\nあなたは前に進み続けるが、心のもやを完全に晴らすことはできない。"
  },
  Event_7618_Name = {Text = "幻影"},
  Event_7619_ChoiceDesc1 = {
    Text = "【慎重に調べる】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7619_ChoiceDesc2 = {
    Text = "【人影を避ける】低級遺物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7619_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_7619_Desc = {
    Text = "ラモンナは神経を尖らせ、精神病院で人混みを避けながら慎重に移動する。\n\n彼女は狭い部屋に身を潜めた。\n\n窓の外に突然人影が映る。"
  },
  Event_7619_Name = {
    Text = "窓の中の影"
  },
  Event_7620_ChoiceDesc1 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_7620_Desc = {
    Text = "今はこの混乱を引き起こした元凶を捕らえることが最も重要だ。\n\nしかし、怒りの種はあなたの心に根を張り始めている。\n\n返事を待たずに、男は横を向いて去っていった。"
  },
  Event_7620_Name = {
    Text = "巨獣の足跡"
  },
  Event_7621_ChoiceDesc1 = {
    Text = "【離れる】75黒章を獲得し、「(Skill.Arg2)」に感染する"
  },
  Event_7621_Desc = {
    Text = "幼い頃からミサゴで受けた教育により、この拓印を見過ごすことはできない。\n\nあなたは手を伸ばして灰を払うと、その瞬間、遠い次元からの「ありがとう」という声が聞こえた気がした。"
  },
  Event_7621_Name = {
    Text = "巨獣の足跡"
  },
  Event_7622_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7622_Desc = {
    Text = "あなたはシルバーキーを握りしめる。\n柔らかな銀の光と微かな振動が安心感を与える。\n\n視線は消えたような、消えていないような……\nいずれにせよ、それはあなたの身に確かに、目には見えない痕跡を残していった。"
  },
  Event_7622_Name = {
    Text = "誰かの視線"
  },
  Event_7623_ChoiceDesc1 = {
    Text = "【秘密の通路を探す】"
  },
  Event_7623_Desc = {
    Text = "あなた、ラモンナ、ロータンはそれぞれ三手に分かれ、地獄の番犬を追い始める。\n\nいくつかの小道を駆け抜けると、大きな姿が目の前に現れる。\n\n追ってくるあなたに気づき、次の角を曲がった。\n\n追いかけたが、目の前には行き止まりが現れる。\n三方を高い壁に囲まれた狭い空が広がっていた。"
  },
  Event_7623_Name = {
    Text = "行き止まり"
  },
  Event_7624_ChoiceDesc1 = {
    Text = "【通り過ぎる】"
  },
  Event_7624_ChoiceDesc2 = {
    Text = "【撫でる】"
  },
  Event_7624_Desc = {
    Text = "手術台の横には、クムの力尽きた体が横たわっている。\n\n彼女は依然として大きく、小山のようで、初めて会った時と同じだ。\n\nただ、高空にある本物の「地獄の番犬」と比べると、彼女はとても小さく、まるで子供のようだ。"
  },
  Event_7624_Name = {Text = "余熱"},
  Event_7625_ChoiceDesc1 = {
    Text = "【シルバーコアを獲得】"
  },
  Event_7625_Desc = {
    Text = "前にたくさんキラキラしたものがあるみたい！\n\n匂いを嗅いでみる……いい香り。\n舐めてみる……冷たくて気持ちいい！\n\nどうやら貴重なものみたい。\n早くジェンキンに渡そう。\n\nたくさんのチーズと交換してくれるかも！"
  },
  Event_7625_Name = {
    Text = "キラキラ"
  },
  Event_7626_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7626_Desc = {
    Text = "あなたのものではない失望が心に広がり、虚構の網がゆっくりと消え、道を開けた。"
  },
  Event_7626_Name = {
    Text = "迷走ネットワーク"
  },
  Event_7627_ChoiceDesc1 = {
    Text = "【それを理解する】ランダムに覚醒体を1体覚醒させ、「(Skill.Arg1)」に感染する"
  },
  Event_7627_ChoiceDesc2 = {
    Text = "【それを無視する】3つの中から1つ刻印を獲得する"
  },
  Event_7627_Desc = {
    Text = "流れるルーンが魚の形をしたライフの咆哮から溢れ出し、あなたの耳、鼻、喉を満たす。\nそれらはあなたの体を焼き、10秒で咆哮の真意を理解できる……"
  },
  Event_7627_Name = {
    Text = "ルーンの狂気"
  },
  Event_7628_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7628_Desc = {
    Text = "あなたは歯を食いしばりながら混乱する幻覚に抵抗しようとする。\nラモンナが冷たい物をあなたの手のひらに置く。\n\n「さっき見つけた遺物、役に立つかもしれない」"
  },
  Event_7628_Name = {
    Text = "次元の幻象"
  },
  Event_7629_ChoiceDesc1 = {
    Text = "上位刻印を選択"
  },
  Event_7630_ChoiceDesc1 = {
    Text = "【カラスを押さえる】3枚の指令カードから1枚を選んで刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_7630_ChoiceDesc2 = {
    Text = "【カラスを殺す】3つの中から1つ刻印を獲得する"
  },
  Event_7630_ChoiceDesc3 = {
    Text = "【離れる】"
  },
  Event_7630_Desc = {
    Text = "孤独なカラスが、かすれた喉で鳴きながら、  \n自らの漆黒の羽根を一本ずつ引き抜いていく。  \n\n痛みに震え、鋭く叫ぶが、動きを止められない。\n\n「カァ——カァ——」\n\nその目からは黒い液体を伴った青い涙が流れる。  \nそれを目にしたのは、あなただけだった。"
  },
  Event_7630_Name = {
    Text = "融蝕液の涙"
  },
  Event_7631_ChoiceDesc1 = {
    Text = "【離れる】最大ライフをArg1増加させる"
  },
  Event_7631_Desc = {
    Text = "「任せて」\nあなたは怪物の背骨を撫で、怒った子猫をなだめるように言った。\n\n「彼女はきっと目を覚ますよ、私たちは彼女を傷つけない」"
  },
  Event_7631_Name = {
    Text = "友情の呼びかけ"
  },
  Event_7632_ChoiceDesc1 = {
    Text = "【離れる】最大ライフをArg1増加させ、さらに「(Skill.Arg2)」「(Skill.Arg3)」に感染する"
  },
  Event_7632_Desc = {
    Text = "「起きて、リリー、クムも君が早く目覚めることを望んでいるよ——」"
  },
  Event_7632_Name = {
    Text = "友情の呼びかけ"
  },
  Event_7633_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_7633_Desc = {
    Text = "無用の物。"
  },
  Event_7633_Name = {
    Text = "無声の電報"
  },
  Event_79429_ChoiceDesc1 = {
    Text = "覚醒体を1体選択し、命の儀式を通じて「虫族」に変化させる。「虫族」の指令カードの行動力消費-1、ただし使用後に除外する。"
  },
  Event_79429_Desc = {
    Text = "「自己を認知する過程には、常に苦痛が伴います。変容や新生もまた、同じことです」\n彼女は優しく微笑み、慈しむようにあなたの顔を撫でた。\n「怖がらないでください。私はここにいます。ですから、あなたの心をすべて解き放ち、それらを受け入れてください」\n「いい子ですね。私はあなたが生まれ変わる時を待っています。あなたが……私たちの一員になる、その時を」"
  },
  Event_79429_Name = {
    Text = "生命の変容"
  },
  Event_80463_ChoiceDesc1 = {
    Text = "【離れる】しろがねのつくりもの3選1を獲得、感染「(Skill.Arg1)」"
  },
  Event_80463_Desc = {
    Text = "あなたは道を選び、小ウィリアムを引きずって必死に走った。\n幸いなことに、あなたの選択は正しかった。\nあの精神汚染、あの同じようなクレメンタインたちを、ついに振り切った。\nもちろん、あなたはいくつかの代償を払った。"
  },
  Event_80463_Name = {
    Text = "「クレメンタイン」たち"
  },
  Event_80464_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80464_Desc = {
    Text = "あなたの脳に認知を超えた記憶が注入され、あなたの理性を直接打ち砕いた。\nその超高速で進む映像の中で、あなたが覚えているのは一つのシーンだけ：三角形の神殿\nそれは@2虫族が偉大で愚かな@4のために建てた偉業である。"
  },
  Event_80464_Name = {
    Text = "ディープメモリ"
  },
  Event_80465_ChoiceDesc1 = {
    Text = "【離れる】選択覚醒1名の覚醒体に「(Skill.Arg1)」を感染させる"
  },
  Event_80465_Desc = {
    Text = "あなたは道を選び、小ウィリアムを引きずって必死に走った。\n幸運なことに、あなたの選択は正しかった。\nあの精神的汚染、あの同じようなクレメンタインを、ついに振り切った。\nもちろん、あなたはいくつかの代償を払った。"
  },
  Event_80465_Name = {
    Text = "「クレメンタイン」たち"
  },
  Event_80466_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80466_Desc = {
    Text = "「カチッ。カチッ。カチッ」\n「作業」がついに完成したが、「作業」そのものを除いて、あなたは何を得ることができたのか？"
  },
  Event_80466_Name = {
    Text = "永遠の拷問"
  },
  Event_80467_ChoiceDesc1 = {
    Text = "【離れる】3つの刻印の中から1つを獲得"
  },
  Event_80467_Desc = {
    Text = "「あなたの心からの返答を聞けて嬉しい。」\n「次回の会合を楽しみにしている。」"
  },
  Event_80467_Name = {
    Text = "夢の中の呼び出し"
  },
  Event_80468_ChoiceDesc1 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_80468_Desc = {
    Text = "「ああ、なんて不正直な子供なの。」\n「しかし大丈夫、次回、あなたに心の真実を言わせるわ。」\n「すべて、内面と魂からあふれ出る真実を。」"
  },
  Event_80468_Name = {
    Text = "夢の中の呼び出し"
  },
  Event_80469_ChoiceDesc1 = {
    Text = "【「仕事」を始める】1枚の指令カードを削除し、Arg1ブラックシールを獲得"
  },
  Event_80469_ChoiceDesc2 = {
    Text = "【遠くに後退】"
  },
  Event_80469_Desc = {
    Text = "「カチッ。」\nタイプライターの音が響く、「作業」が完了するまで、あなたは永遠にその奴隷でいる。"
  },
  Event_80469_Name = {
    Text = "永遠の拷問"
  },
  Event_80470_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80470_Desc = {
    Text = "「本当に残念ですね、あなたの慎重さが真実を知る唯一のチャンスを逃してしまいました。」\nそれはため息をつき、無言で消えていった。"
  },
  Event_80470_Name = {
    Text = "ディープメモリ"
  },
  Event_80471_ChoiceDesc1 = {
    Text = "【全力で攻撃】"
  },
  Event_80471_ChoiceDesc2 = {
    Text = "【戦って退く】"
  },
  Event_80471_Desc = {
    Text = "予期しない影があなたの前に現れた、それはクレメンタインだった。\n「驚かなくていい、私はただ特別なテストをしたいだけ。」\n「テストが何かについては、秘密です。」クレメンタインは微笑みながら言った、「あなたにとって、テストの唯一の内容——」\n「それは生き残ることです。」"
  },
  Event_80471_Name = {
    Text = "特別なテスト"
  },
  Event_80472_ChoiceDesc1 = {
    Text = "【過去を思い出す】"
  },
  Event_80472_ChoiceDesc2 = {
    Text = "【虫の鱗を引き抜く】"
  },
  Event_80472_Desc = {
    Text = "「どうか信じてください、私は悪意はありません、ただあなたを助けたいだけです。」\nクレメンタインはあなたを追いかけ、大声で叫びます。\n彼女の声は非常に誠実に聞こえますが、あなたはもう何も信じられません。\nあなたの道徳は「具身認知理論」によって打ち破られ、理性も崩壊しようとしています。\nあなたは何かをしなければならない、血肉の中で成長する虫の鱗に抵抗し、徐々に魂に浸透する発狂と絶望に抵抗しなければなりません。"
  },
  Event_80472_Name = {
    Text = "苦闘する魂"
  },
  Event_80473_ChoiceDesc1 = {
    Text = "【離れる】2枚のカードを除去"
  },
  Event_80473_Desc = {
    Text = "「最後の決戦に対抗する力を保持したいのか？」\n「賢い選択だ。しかし人は得ると同時に、実際には失っている。」\n「この燃え盛る残酷な世界では、生きること自体が代償を必要とする。」"
  },
  Event_80473_Name = {
    Text = "特別なテスト"
  },
  Event_80474_ChoiceDesc1 = {
    Text = "【無視する】3つの刻印から1つを獲得"
  },
  Event_80474_ChoiceDesc2 = {
    Text = "【触れる】ランダムな指令カード1枚に刻印を付与：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_80474_Desc = {
    Text = "胞子のような奇妙な物があなたの注意を引いた。\nそれは血肉でできた細いクラゲのようであり、また脳の奥深くに信号を保存している神経繊維のようでもある。\n「私に触れてみて。」それは無言であなたを誘惑し、「私はあなたに残酷な記憶を見せるだろう。」"
  },
  Event_80474_Name = {
    Text = "ディープメモリ"
  },
  Event_80475_ChoiceDesc1 = {
    Text = "【離れる】3つの刻印の中から1つを獲得"
  },
  Event_80475_Desc = {
    Text = "「ラモンナ、ドール、ロータン、オジール……」\nあなたは神経質にこれらの名前を繰り返して呟いています。\n崩壊した理性は彼らの姿を思い出すことができませんが、この名前が象徴する存在は、依然としてあなたの心の扉と魂を温めてくれます。\n彼らは存在していた、彼らは笑っていた、彼らは……あなたが今この瞬間に人間性の底線とアンカーを維持するための存在です。"
  },
  Event_80475_Name = {
    Text = "苦闘する魂"
  },
  Event_80476_ChoiceDesc1 = {
    Text = "【離れる】3つの選択肢から1つのシルバーのつくりものを獲得し、「(Skill.Arg1)」に感染される"
  },
  Event_80476_Desc = {
    Text = "「あああああ——」\nあなたは口を開き、大声を上げ、その声は叫びというよりもむしろ鳴き声のようだ。\nその抜かれた虫の鱗は再び生え、崩壊した理性は二度と戻らない。"
  },
  Event_80476_Name = {
    Text = "苦闘する魂"
  },
  Event_80477_ChoiceDesc1 = {
    Text = "【離れる】獲得造物「(RelicConfig.Arg1)」、感染「(Skill.Arg2)」"
  },
  Event_80477_Desc = {
    Text = "あなたは何も隠さず、全力を尽くした。この姿勢は明らかにクレメンタインを喜ばせた。\n「本当に良い子だ。」\n「そういうことなら、少しご褒美をあげよう。ただし、代償が必要だ。」\n「この燃え盛る残酷な世界では、生きること自体が代償を必要とする。」"
  },
  Event_80477_Name = {
    Text = "特別なテスト"
  },
  Event_80478_ChoiceDesc1 = {
    Text = "【「仕事」を始める】1枚の指令カードを削除し、Arg1ブラックシールを獲得"
  },
  Event_80478_ChoiceDesc2 = {
    Text = "【遠くに後退】"
  },
  Event_80478_Desc = {
    Text = "「カチッ。カチッ。」\nタイプライターの音が響く、「作業」が行われる時、あなたはただ「作業」の道具に過ぎない。"
  },
  Event_80478_Name = {
    Text = "永遠の拷問"
  },
  Event_80479_ChoiceDesc1 = {
    Text = "【左に走る】"
  },
  Event_80479_ChoiceDesc2 = {
    Text = "【右に走る】"
  },
  Event_80479_Desc = {
    Text = "なじみの影があなたの後ろにぴったりとついてきている。それは一人や二人ではなく、数十人、数百人だ。\n狭い廊下はこれほど多くの「クレメンタイン」を支えることができず、地面に押し倒される「クレメンタイン」もいれば、踏みつけられて泥になっている「クレメンタイン」もいる。\nしかし、彼女たちは一斉にあなたを呼びかけ、あなたを精神汚染に陥らせるその言葉を繰り返している。\n「なぜ逃げるの？ただあなたにカウンセリングをしたいだけです。」\nそしてあなたは、サナトリウムの廊下を全力で走り、分岐点の選択に直面している。"
  },
  Event_80479_Name = {
    Text = "「クレメンタイン」たち"
  },
  Event_80480_ChoiceDesc1 = {
    Text = "【「仕事」を始める】1枚の指令カードを削除し、Arg1ブラックシールを獲得"
  },
  Event_80480_ChoiceDesc2 = {
    Text = "【遠くに後退】"
  },
  Event_80480_Desc = {
    Text = "「修正！作業！止まらないで！」\n無数のブンブンが耳元で反響し、あなたは突然現れたタイプライターに引き寄せられる。\n「どうしよう、どうしよう、朝から晩まで叩いているのに、作業が全く終わらない。」\n「修正！修正！修正案、要求を提出、作業を完了！」\n「作業！作業！！作業！！！」\nブンブンと鳴る魂が絶え間なく叩くタイプライターにぶつかり、ついにそのタイプライターは止まった。\nしかし、しばらくすると、そのタイプライターは再び動き出した。\n「修正！作業！止まらないで！」\n作業は、決して終わることがない。"
  },
  Event_80480_Name = {
    Text = "永遠の拷問"
  },
  Event_80481_ChoiceDesc1 = {
    Text = "【事実を答える】"
  },
  Event_80481_ChoiceDesc2 = {
    Text = "【回答を拒否する】"
  },
  Event_80481_Desc = {
    Text = "刹那のうちに、目の前の光景がぼんやりと虚幻に変わった。\nあなたは部屋がねじれ変わっていると思ったが、後になって、あなたの視神経が侵入されたことに気づいた。\n「また会いましたね。」\nぼんやりとした視線の中で、クレメンタインは優しく微笑んだ。\n「想像よりも早く会うことになったけれど、私はとても嬉しいです。%player%さんも同じ気持ちでしょうか？」"
  },
  Event_80481_Name = {
    Text = "夢の中の呼び出し"
  },
  Event_80595_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80595_Desc = {
    Text = "\nあなたの追い払いに、蝶は無関心です。\nそれはあなたの手のひらを追い続け、あなたの掌の中で息を失いました。\n「うあぁ、暖かい……」\nこれはそれの最後の心の声です。"
  },
  Event_80595_Name = {Text = "蝶の夢"},
  Event_80596_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80596_Desc = {
    Text = "「私は花がいつも咲いていてほしい、笑顔が永遠に存在してほしい。」\n「私はすべての融蝕にかかった人々が癒されて平安であることを望み、この世界が昔に戻り、もう燃やされないことを願っています。」\n「私は…………」\n小さな蝶が翼を動かし、あなたの手のひらの中で息を失いました。\n少なくとも、誰かがその声を聞いてくれました。"
  },
  Event_80596_Name = {Text = "蝶の夢"},
  Event_80597_ChoiceDesc1 = {
    Text = "【蝶を追い払う】ランダムな1枚の指令カードが刻印を獲得：「(EnchantConfig.Arg1)」、「(Skill.Arg2)」に感染"
  },
  Event_80597_ChoiceDesc2 = {
    Text = "【心願を聴く】3枚の指令カードから1枚選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_80597_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_80597_Desc = {
    Text = "小さな蝶は、たくさんの夢を抱えています。\nこれらの夢は花畑や病室、そして多くの血肉で満たされた@2の祭壇に散らばっています。\n今、ようやく絆のある人を待ち望んでいますが、あなたはその小さな、小さな願いを聞いてくれるのでしょうか。"
  },
  Event_80597_Name = {Text = "蝶の夢"},
  Event_80610_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80610_Desc = {
    Text = "「理性ですか？面白い回答ですね。」\n「自分の選択を後悔しないことを願います。」"
  },
  Event_80610_Name = {
    Text = "人間性の代償"
  },
  Event_80612_ChoiceDesc1 = {
    Text = "【彼らに餌を与える】白銀造物「(RelicConfig.Arg1)」を獲得し、1回症状を感染することを選択"
  },
  Event_80612_ChoiceDesc2 = {
    Text = "【何もしない】3枚の指令カードから1枚を選択して刻印を獲得：「(EnchantConfig.Arg1)」，感染「(Skill.Arg2)」"
  },
  Event_80612_ChoiceDesc3 = {
    Text = "【離れる】25黒章を獲得する"
  },
  Event_80612_Desc = {
    Text = "住民が出入りする中、鼠の群れは長く続いている。\n人間と比べて、彼らこそがこの古城の「先住民」だ。\nしかし、彼らは人間の進入に異議を唱えない。\nなぜなら、その香ばしく柔らかく、白くて醜いものたちが、同じように香ばしく柔らかく、白くて醜いものを与えてくれるからだ。\n「そしてお前は、醜いもの、どちらの種類に属するのか？」"
  },
  Event_80612_Name = {
    Text = "古城の秘密"
  },
  Event_80613_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80613_Desc = {
    Text = "\n暗闇の中から優しい笑い声が聞こえます。\n「私はあなたを待っています、私に会いに来て。」\n「勇敢な小さな虫よ。」"
  },
  Event_80613_Name = {
    Text = "「彼女」の覗き見"
  },
  Event_80614_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80614_Desc = {
    Text = "「黙れ黙れ、耳障りだ。」\n黒猫は人間のように耳を覆った。\n「人間、お前の猫語は本当に下手だ。何を言っているんだ、めちゃくちゃだ！」\nそう言いながらも、黒猫の表情は穏やかになった。\n「お前がニャーニャー言って私を喜ばせているから、贈り物をあげよう。」\n「贈り物の内容は、お前の運次第だ。」"
  },
  Event_80614_Name = {
    Text = "ニゲルマン"
  },
  Event_80615_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80615_Desc = {
    Text = "\n「母親、友人、夫、息子を失った後、私はまた永遠にダイアナを失ってしまった、私の小さな娘。」\n「彼女が私の目の前で灰になったとき、私の脳は真っ白だった……」その後の文字はもう読み取れない。\nあなたは次の行を読むしかなかった。\n私は決心した。もし再び会うことがあったら、私を責めないでください、私はただ……あなたたちがとても恋しいのです。"
  },
  Event_80615_Name = {
    Text = "消えゆく思い"
  },
  Event_80616_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80616_Desc = {
    Text = "あなたの追い払いは効果を発揮しました。姿がはっきりしない少数の体がねじれながら逃げ去り、大部分はその場に留まっています。\n彼らはもはや笑い声を上げず、詩を吟じることもなく、むしろ大声で泣いています。\n子供の泣き声があなたの耳元で響き渡り、一言だけを繰り返します。\n「化け物を殺せ！」"
  },
  Event_80616_Name = {
    Text = "「彼」のこども時代"
  },
  Event_80617_ChoiceDesc1 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_80617_ChoiceDesc2 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_80617_ChoiceDesc3 = {
    Text = "【離れる】「(Skill.Arg1)」に感染する"
  },
  Event_80617_Desc = {
    Text = "あなたの投与は鼠群を喜ばせました。\nその巨大な鼠群がサージし、粗末な包装の贈り物をあなたに贈りました。\nあなたはその贈り物の姿を見分けることができず、包装に染み込んだ大量の鮮血だけを見ました。"
  },
  Event_80617_Name = {
    Text = "古城の秘密"
  },
  Event_80618_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80618_Desc = {
    Text = "「……」\n「…………」\n「………………」\nブラックシャドウは沈黙し、泣きたいのに、すでに涙を流す能力を失っていた。\n結局、彼はただ深くため息をついた。\n「友よ、どうか君が最も大切なものを守れますように。」"
  },
  Event_80618_Name = {
    Text = "ホロウマン"
  },
  Event_80619_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80619_Desc = {
    Text = "あなたの叱責は全く効果がなく、むしろ彼らをさらに狂熱にさせた。\n笑い声と歌声はますます高まっていき、別の童謡を歌っている。\n「小ウィリアム、古城に住み、人を食べる鼠が、壁の中を走る。\n人の犠牲が捧げられる時、すべての人が噛み倒される。」"
  },
  Event_80619_Name = {
    Text = "「彼」のこども時代"
  },
  Event_80620_ChoiceDesc1 = {
    Text = "【視線を逸らす】ランダムに1体の覚醒体を覚醒させる"
  },
  Event_80620_ChoiceDesc2 = {
    Text = "【直視目線】1体の覚醒体を覚醒させ、その覚醒カードの計算力消費を2ポイント減らす。感染「(Skill.Arg1)」"
  },
  Event_80620_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_80620_Desc = {
    Text = "療養院のすべては、彼女の掌握と監視の下にある。当然、あなたも。\nしかし彼女はあなたのために一つの目を開け、一つの目を閉じてくれる。\n結局、ゲームは往復があってこそ面白いのだから。"
  },
  Event_80620_Name = {
    Text = "「彼女」の覗き見"
  },
  Event_80621_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80621_Desc = {
    Text = "あなたは封筒を元の場所に戻し、立ち去る準備をしていたが、突然、ぼんやりとした囁きが聞こえた。\n「私の頼みで、クレメンタインドクターがついに口を割った。\n彼女が私に語ったその広大な宇宙、神秘的な宇宙には、あなたたちを救う方法が必ずあるはずだ。\n私は「新生」の準備ができている。どれだけの光年を漂流しようとも、再びあなたたちに会いたいと願っている。」"
  },
  Event_80621_Name = {
    Text = "消えゆく思い"
  },
  Event_80622_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80622_Desc = {
    Text = "クレメンタイン先生が私を救ってくれました。\n彼女は本当にとても、とても良い人で、私の声に耳を傾けてくれます。\n私は本当に楽しいこと、嬉しいことを話したいのですが、今の私には苦しみと絶望しかありません。\n恐らく、私は先生の気持ちを裏切ることになるでしょう。\nあなたたちを失った後、私にとっての生活はただの荒涼です。"
  },
  Event_80622_Name = {
    Text = "消えゆく思い"
  },
  Event_80623_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80623_Desc = {
    Text = "「あなた、あなた……」\n「ふん、なかなかの手法だ。この調子なら次回は合格だ。次はそんなに簡単にはいかないぞ！」\n黒猫が飛び跳ねて、器用に逃げていった。"
  },
  Event_80623_Name = {
    Text = "ニゲルマン"
  },
  Event_80624_ChoiceDesc1 = {
    Text = "【黒猫を攻撃する】50%の確率で125ブラックシールを獲得、50%の確率で感染「(Skill.Arg2)」"
  },
  Event_80624_ChoiceDesc2 = {
    Text = "【猫の鳴き声を真似る】75%の確率で100ブラックシールを獲得、25%の確率で感染「(Skill.Arg2)」"
  },
  Event_80624_ChoiceDesc3 = {
    Text = "【猫を撫でる】50ブラックシールを獲得"
  },
  Event_80624_Desc = {
    Text = "「おい！君、前に進むのは禁止だ。」\n黒猫たちが突然飛び出し、君の前進を阻止する。\n彼らは優雅に爪を舐め、傲慢で誇らしげな表情を見せている。\n「前方には危険が満ちている。そんな弱い人間には探検できない場所だ。」\n君は前に進む決意を示した。その時、先頭の黒猫の縦瞳がくるりと回り、獲物を弄ぶ残酷な本性を見せた。「それなら、君の決意を見せてみろ。」"
  },
  Event_80624_Name = {
    Text = "ニゲルマン"
  },
  Event_80625_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80625_Desc = {
    Text = "\nあなたの無視に鼠群は怒り、彼らは鳴きながらあなたに向かって押し寄せました。しかし、あなたは鼠群が動く前に、すでに遠くに逃げていました。"
  },
  Event_80625_Name = {
    Text = "古城の秘密"
  },
  Event_80626_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80626_Desc = {
    Text = "「そう、私の翼を折ってくれ。」\n「時間、健康、尊厳、命、彼らは私からあまりにも多くを奪っていった。」\n「この最後の夢も、もちろん私のものではない。」\n「なぜなら、私はただ閉じ込められ自由を失った鳥だからだ。」"
  },
  Event_80626_Name = {
    Text = "ホロウマン"
  },
  Event_80627_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80627_Desc = {
    Text = "「感情的？面白い返答。」\n「あなたが自分の選択を後悔しないことを願っている。」"
  },
  Event_80627_Name = {
    Text = "人間性の代償"
  },
  Event_80628_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80628_Desc = {
    Text = "「あなたの願いを受け入れます。」\nうなり声が近づき、耳道を通じてゆっくりとあなたの脳に浸透していく。\nあなたの脳は震え、その震えの中で、あなたは宇宙の「声」を聞いた。\n「私と、リンク。」"
  },
  Event_80628_Name = {
    Text = "ダーク救済"
  },
  Event_80629_ChoiceDesc1 = {
    Text = "【祈る】ランダムに1名の覚醒体を覚醒させ、感染「(Skill.Arg1)」"
  },
  Event_80629_ChoiceDesc2 = {
    Text = "【拒否する】3つの中から1つの刻印を獲得"
  },
  Event_80629_Desc = {
    Text = "「そうあるべきではない、そうあるべきではない。」\n「私は明らかに、明らかに人間という低級な生命から脱却し、より上位の存在に進化するべきだ……」\n暗闇の中、苦痛の泣き声が聞こえてくる。\nその泣き声が集まり、サージとなり、巨大なブーンという音を形成する。\n「この燃える世界は、決して満腹しないブラックホールのように、すべての人を捕食している。だから——」\n「私に祈りなさい、無限の宇宙があなたに救済を与えるだろう。」"
  },
  Event_80629_Name = {
    Text = "ダーク救済"
  },
  Event_80630_ChoiceDesc1 = {
    Text = "【封筒を開ける】黄金造物「(RelicConfig.Arg1)」を獲得し、感染「(Skill.Arg2)」"
  },
  Event_80630_ChoiceDesc2 = {
    Text = "【読む】3枚の指令カードの中から1枚を選び刻印を得る：「(EnchantConfig.Arg1)」"
  },
  Event_80630_ChoiceDesc3 = {
    Text = "【元の場所に戻す】50黒章を獲得する"
  },
  Event_80630_Desc = {
    Text = "誰も気に留めない隅に、手紙が残されていた。\n手紙の多くの文字は判読できなくなっているが、ただ一つの言葉だけは透き通っている。\nその言葉は「母」だ。"
  },
  Event_80630_Name = {
    Text = "消えゆく思い"
  },
  Event_80631_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80631_Desc = {
    Text = "「ああ、ちっぽけな人間よ、あなたは間違った選択をした。」\n黒猫たちが冷酷にあなたを見つめ、突然襲ってきた。\n「代償を支払わなければならない——もちろん、私たちは強者を敬う。」"
  },
  Event_80631_Name = {
    Text = "ニゲルマン"
  },
  Event_80632_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80632_Desc = {
    Text = "\n暗闇の中から優しい笑い声が聞こえます。\n「私はあなたを待っています、私に会いに来て。」\n「可愛い小さな虫よ。」"
  },
  Event_80632_Name = {
    Text = "「彼女」の覗き見"
  },
  Event_80633_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80633_Desc = {
    Text = "あなたの攻撃の下で、この歪んだ奇怪な影たちはついに逃れました。\n周りは静寂、ただあなたの心臓の鼓動が無言で泣いている。\nこれが、「彼」の子供時代だったとは。"
  },
  Event_80633_Name = {
    Text = "「彼」のこども時代"
  },
  Event_80635_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80635_Desc = {
    Text = "「ああ、小さな文字の罠が覗かれた。」\n「これは報酬です。なぜなら……」\n「選択のすべてが、選ばなければならないわけではない。」"
  },
  Event_80635_Name = {
    Text = "人間性の代償"
  },
  Event_80636_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80636_Desc = {
    Text = "「@3忤逆者」\nうなり声は徐々に弱まり、ついには消えます。最後の言葉だけが残ります。\n「人間性を維持することは、この残酷な世界では生き残れないです。」"
  },
  Event_80636_Name = {
    Text = "ダーク救済"
  },
  Event_80637_ChoiceDesc1 = {
    Text = "【拒否を選択する】1枚の指令カードを削除し、Arg1ブラックシールを獲得"
  },
  Event_80637_ChoiceDesc2 = {
    Text = "【従うを選択する】1枚の指令カードをコピーし、感染「(Skill.Arg1)」"
  },
  Event_80637_ChoiceDesc3 = {
    Text = "【抱擁を選択する】3枚の指令カードから1枚選んで刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_80637_Desc = {
    Text = "「私は檻の中の鳥で、たくさんの部屋がある庭に閉じ込められています。」\n暗闇の中を彷徨うぼんやりとした人影、それは過去の者たちが残した執念です。\n「彼らはそれを精神病院だと言いますが、私は知っています。それは人間の特別な囚籠で、社会のルールに従うことを望まない自由な鳥を閉じ込めています。」\n「しかし、鳥が飛べないなら、鳥と呼べるのでしょうか？」\n執念たちがあなたに寄り添い、救済を求めています。\n「私の翼を折ってください、私は飛ぶことに疲れました。」"
  },
  Event_80637_Name = {
    Text = "ホロウマン"
  },
  Event_80638_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_80638_Desc = {
    Text = "「……」\n「…………」\n「………………」\nブラックシャドウが突然震え、あなたの身体に融解していく。\n「友よ、前に進もう、自分が最も大切にしているものを守るために。」\n「私たちはすでに逝去しましたが、あなたの夢のために、最後のブレスを捧げます。」"
  },
  Event_80638_Name = {
    Text = "ホロウマン"
  },
  Event_80639_ChoiceDesc1 = {
    Text = "【感情を選択する】Arg1ポイントの生命を回復"
  },
  Event_80639_ChoiceDesc2 = {
    Text = "【理性を保つ】ランダムに1枚の指令カードを引き、刻印を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_80639_ChoiceDesc3 = {
    Text = "【選択を拒否する】25ブラックシールを獲得"
  },
  Event_80639_Desc = {
    Text = "「選択せよ、選択せよ。」\n狂奔するダークの中から、無数の呟きが聞こえてきた。\nこの声は優しく催眠的で、無限の魔力を帯びているようで、あなたに何らかの狂気の幻覚を引き起こさせる。\nあなたの脳は狂悖に陥り、身体から脱け出そうと蠕動し、心臓は何らかの意識を持ち始め、あなたに叫びかけて呼びかけている。\n「選択せよ、選択せよ。」\n「理性を維持するか、感性を選ぶか、あなたは選択しなければならない。」"
  },
  Event_80639_Name = {
    Text = "人間性の代償"
  },
  Event_80641_ChoiceDesc1 = {
    Text = "【叱責「彼ら」】感染「(Skill.Arg1)」、呪われた造物「(RelicConfig.Arg2)」"
  },
  Event_80641_ChoiceDesc2 = {
    Text = "【「彼ら」を追い払う】感染「(Skill.Arg1)」を2回行い、白銀造物「(RelicConfig.Arg2)」および「(RelicConfig.Arg3)」を獲得"
  },
  Event_80641_ChoiceDesc3 = {
    Text = "【「彼ら」を攻撃する】白銀造物「(RelicConfig.Arg1)」を獲得"
  },
  Event_80641_Desc = {
    Text = "「小ウィリアム、奇形、墓場で眠っていて、誰にも愛されない。彼と関わらないで、彼にこっそり害されるのに気をつけて。」\n姿が見えない体がねじれているが、声は幼い子供のようだ。\n彼らは笑いながら、詠唱し、軽蔑と熱意を持った目であなたを見つめている。\n悪意を持って。"
  },
  Event_80641_Name = {
    Text = "「彼」のこども時代"
  },
  Event_90571_ChoiceDesc1 = {
    Text = "【味わう】「祭霊夜の特製ブレンド」を1枚デッキに加える。"
  },
  Event_90571_Desc = {
    Text = "華やかな食卓、熱気あふれるダンスフロア、精巧な食器、芳醇な死体……\nああ、親愛なるお客様。待ちきれないお気持ちはよく存じておりますが、どうかもう少しお待ちください。\nこの一杯は、宴の主催者が特別にブレンドした飲み物であり、尊いお客様への贈り物でございます。\nどうぞお手に取り、口に含んでください。その余韻に浸りながら、この歓びを存分にお楽しみください！"
  },
  Event_90571_Name = {
    Text = "宴前の儀礼"
  },
  Event_91460_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91460_Desc = {
    Text = "あなたは抵抗できず、その声に身を任せるしかありませんでした。\n鋭い叫びがあなたの脳を裂き、いくつかの忘れられた恐れが流れ出し、あなたはその飢えを感じました。\n恐ろしい食人の生物……"
  },
  Event_91460_Name = {
    Text = "沈黙の告白"
  },
  Event_91461_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91461_Desc = {
    Text = "あなたはもはや抑制されず、その熱情を完全に解放し、全ての未発言の言葉があなたの頭から次々と噴き出します。\nあなたは奇妙なインスピレーションを感じ、ピクマンの才能に酔いしれています。"
  },
  Event_91462_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91462_Desc = {
    Text = "炎の舌が墨の染みを巻きつけ、血痕を残した。\nその瞬間、あなたは夢と現実の境界で落ちていった。自分が小さな女の子になり、ドレセインの手を取り彼と共に踊っているのが見えた。\n再び目を覚ましドレセインを見たとき、重い悲しみがあなたの脳を覆った。"
  },
  Event_91462_Name = {
    Text = "夢の啓示"
  },
  Event_91463_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91463_Desc = {
    Text = "あなたは突進し、炎はあなたの皮膚に飲み込まれる。あの絵については、誰が見てもただの平凡な肖像画に過ぎない。\nその後の夢の中で、あなたはいつも燃えている自分を見て、ちょうど良い具合に焼かれ、そしてある日、自分の食卓に出される。"
  },
  Event_91463_Name = {
