  },
  Event_91464_ChoiceDesc2 = {
    Text = "【無視】離れる"
  },
  Event_91464_Desc = {
    Text = "無音の雑音の中で、あなたは徐々にカラスの言葉を理解し始めた……"
  },
  Event_91464_Name = {
    Text = "沈黙の告白"
  },
  Event_91465_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91465_Desc = {
    Text = "あなたは石を拾い上げ、専念している鼠の影を驚かせました。\n彼らは貪欲にあなたと目を合わせました。\nあなたは彼らの体から湿った汚れた臭いを嗅ぎ取り、それが何かの兆しであるかのようでした。"
  },
  Event_91465_Name = {
