  Event_91466_ChoiceDesc1 = {
    Text = "【聴く】25のブラックシールを獲得し、「(Skill.Arg2)」に感染し、さらに選択します"
  },
  Event_91466_ChoiceDesc2 = {
    Text = "【無視】離れる"
  },
  Event_91466_Desc = {
    Text = "それは歓迎している。誰を？\n もちろん、あなただ！\n もしかしたらそれはあなたを明日の美食と見なしているのかもしれない。"
