  },
  Event_91468_Desc = {
    Text = "あなたはピックマンの贈り物の前に立っています。\nそれは血で描かれた肖像画で、真っ黒な炎が静かに燃えています。\n絵の中の人の空洞の目を通して、あなたは見ることができます——\nあなたの記憶がうねり燃え上がり、引き延ばされ、ねじれ、光り輝いており、まるで何か無形の火があなたの脳の回廊を舐めているかのようです。ぼんやりとした中で、あなたは一つの声を聞きます。\n「鍋に入れる時間だ、ちょうどいい火加減だ。」\nそれはあなた自身が描いた記憶の景色で、あなたは炎の中でもがき変形しています。"
  },
  Event_91468_Name = {
    Text = "燃える肖像"
  },
  Event_91469_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91469_Desc = {
    Text = "あなたは応答を拒否し、静かにその震えが収まるのを見ていました。\n長年にわたり、あなたはすでに狂気と対抗することを学んでいました。"
  },
  Event_91470_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91470_Desc = {
    Text = "あなたは一歩後退し、キャンバスが炎の中で燃えるのをそのまま見守る。\nあなたは自分が火で焼かれ、魅力的な焦げ色になっているのを見て、脂がパチパチと音を立てているのが聞こえ、まるでキャンバスを通して肉の香りが感じられるかのようだ。\nドレセインが感じているのは、こういう誘惑なのだろうか？"
  },
  Event_91470_Name = {
    Text = "燃える肖像"
  },
  Event_91471_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91471_Desc = {
    Text = "冒涜に近い好奇心、あるいは未知への対抗する絶望の勇気を抱き、往昔の幻影の中に啓示を求める。\n君は少女と傍らの顔がぼやけた高大な男と共に踊るのを見、心臓は不思議なほどの楽しさで満たされる。"
  },
  Event_91471_Name = {
    Text = "過去の影"
  },
  Event_91472_ChoiceDesc1 = {
    Text = "【記録を終了する】カードを2枚削除します"
  },
  Event_91472_ChoiceDesc2 = {
    Text = "【書き続ける】呪われた造物「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染します"
  },
  Event_91472_ChoiceDesc3 = {
    Text = "【離れる】獲得 Arg1 ブラックスタンプ"
  },
  Event_91472_Desc = {
    Text = "あなたはようやく死体食い人の市場から一時的に解放され、いつものように静かな隅で記録を始めた。\nタイプライターが突然狂暴に震え、キーが自動的に上下し、黒い粘液が隙間から噴き出して、あなたの指先の理性を濡らした。\n紙の上に呼び起こされる蝶の影が徐々に浮かび上がるのを見た……"
  },
  Event_91472_Name = {
    Text = "蝶の影が重なる"
  },
  Event_91473_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91473_Desc = {
    Text = "不思議なことに、学んだことのない言語であるはずなのに、その意味が分かるような気がする。\n詩には、親への思いが満ちており、その思いは生と死を越えて、あなたの夢の中で伝わる。\n詩の最後にかすかに字が認識できる——\nそれは「セリネ」。"
  },
  Event_91473_Name = {
    Text = "夢の啓示"
  },
  Event_91474_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91474_Desc = {
    Text = "あなたは手のひらの皮膚を痛みをこらえて切り裂き、その新生の肉の翼を炎で焼く。\n黒い液体が蒸発し、蝶が砕ける。\nすべてがきれいに痕跡もなくなるが、あなたはいつも手のひらから微かな羽ばたきの音が聞こえるように感じる。それは完全に孵化できなかった思想のようで、あなたの血管の中でゆっくりと呼吸している。\nドレセインはそれについて何も言わず、ただあなたが残した鮮血を持ち去ろうとしている。"
  },
  Event_91475_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91475_Desc = {
    Text = "あなたは熱狂的なインスピレーションが常に災厄をもたらすことを知り、それであなたはすべてを理性で封じ込めた。"
  },
  Event_91476_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91476_Desc = {
    Text = "あなたはその目をじっと見つめ、その情報を理解しようと試みる。\nあなたはすでに数多くの戦闘を経験しているが、今回はゴリアテに直面して……恐怖があなたの心臓を掴んでいる。\n「ほぼ正常とは、災厄が起こる前の最も静かな形状だ。」"
  },
  Event_91476_Name = {
    Text = "ほぼ正常"
  },
  Event_91477_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91477_Desc = {
    Text = "あなたは目を閉じ、振り向いて荒野へと歩き出す。\n潜んでいる渇望と予兆を感じることができるが、永遠に自ら止めることはできない。\n無言の墓碑を見渡すと、これがあなたの結末かもしれないと思う。"
  },
  Event_91477_Name = {
    Text = "カラスの宴"
  },
  Event_91478_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91478_Desc = {
    Text = "あなたはゆっくりと頭を上げ、その瞬間、光が瞳孔を貫き、熱が脳内に空白の花を開かせた。\n埋葬の街の星々は他の場所と何も変わらず、永遠の死体食い人もまた星の下で存在するしかなく、自由はない。"
  },
  Event_91478_Name = {Text = "星の夜"},
  Event_91479_ChoiceDesc1 = {
    Text = "【炉の火に投げ込む】カードを1枚削除します"
  },
  Event_91479_ChoiceDesc2 = {
    Text = "【尝试解读】「(RelicConfig.Arg1)」を獲得し、感染「(Skill.Arg2)」"
  },
  Event_91479_Desc = {
    Text = "あなたの意識は無辺の黒雲の中で浮沈し、生者と亡者の無数の精神図景を行き交う。\n夢の中で、神秘的なタイプライターが見知らぬ詩を吐き出す。それは誰の物語なのか？\nそれは不明な出所の紙に刻まれ、ねじれた文字はまるで目覚めた酔っ払いが手書きしたかのようだ。\nあなたは夢の中で言葉にできない衝動に駆り立てられ、その紙を手に取り、インクが炉火の光影の間で跳ねる。"
  },
  Event_91479_Name = {
    Text = "夢の啓示"
  },
  Event_91480_ChoiceDesc1 = {
    Text = "【加入】感染「(Skill.Arg1)」、ランダムで1枚のカードが刻印を得る：「(EnchantConfig.Arg2)」"
  },
  Event_91480_ChoiceDesc2 = {
    Text = "【駆除】「(Skill.Arg1)」に感染し、ランダムに1枚のカードを選び、彫刻を獲得：「(EnchantConfig.Arg2)」"
  },
  Event_91480_ChoiceDesc3 = {
    Text = "【無視】3枚の指令カードから1枚を選び、彫刻を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_91480_Desc = {
    Text = "あなたは遠くからかすかに響く骨のホラ貝の音を聞いた。\n鼠の群れがその音に導かれ、黒い泥の中から湧き出て、干からびた河床に横たわる無名の死体を貪り食っている。\n彼らは円を作り、その中心にはすでに空洞となった遺体があり、円周は忘却を法とする新王国である。\nそしてあなたは、その王国の入口に立っている。"
  },
  Event_91480_Name = {
    Text = "追放された王国"
  },
  Event_91481_ChoiceDesc1 = {
    Text = "【見上げる】シルバークリエイション「(RelicConfig.Arg1)」を獲得します"
  },
  Event_91481_ChoiceDesc2 = {
    Text = "【低头离开】75ブラックシールを獲得し、感染「(Skill.Arg2)」"
  },
  Event_91481_Desc = {
    Text = "群れを成したカラスが空を旋回し、ためらう鋸のように空の脊髄を何度も切り刻んでいる。\n彼らは君の周囲を低空飛行し、君の死を予見しているかのように、宴の始まりを辛抱強く待っている。"
  },
  Event_91481_Name = {
    Text = "カラスの宴"
  },
  Event_91482_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91482_Desc = {
    Text = "あなたはそれを続けて書かせる。あなたの脈拍、痛覚、過去や想像で。\n蝶が紙の束縛を破り、あなたの心も解き放たれる。\nあなたは自分が遊園地で楽しんでいる姿を想像し始める。ドゥルセインには言っていないが、実はあなたは遊園地がとても好きだ、たとえそれが死体の遊園地であっても……\nそんなに奇妙ではないはず……。"
  },
  Event_91482_Name = {
    Text = "蝶の影が重なる"
  },
  Event_91483_ChoiceDesc1 = {
    Text = "【再観察】3枚の指令カードから1枚を選び、彫刻を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_91483_Desc = {
    Text = "かつて鮮やかだった夕食が血肉模糊とした盛宴に変わり、あなたは灶台の上の食材を思い出し、腐った匂いが鼻腔を刺激した。\n恐怖があなたの心臓を締め付け、選択を迫られた。"
  },
  Event_91483_Name = {
    Text = "過去の影"
  },
  Event_91484_ChoiceDesc1 = {
    Text = "【鈴の音を無視する】3枚の選択肢から1つの高度な彫刻を獲得します"
  },
  Event_91484_ChoiceDesc2 = {
    Text = "【受話器を取る】ゴールドクリエイション「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染します"
  },
  Event_91484_ChoiceDesc3 = {
    Text = "【離れる】50のブラックスタンプを獲得"
  },
  Event_91484_Desc = {
    Text = "それは鳴るべきではなかった——その電話は、キャンバスの裏に縮こまっている。\n受話器のコードは大きな本体に絡まりつき、錆びたへその緒のように、あなたの脳から伸びているかのようだ。\nあなたは震動の周波数を注意深く識別し、奇妙な音はピックマンの超現実的なアートのようだ。"
  },
  Event_91485_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91485_Desc = {
    Text = "あなたはその冷たい脳を抱え上げた瞬間、それは流水のように指の隙間から静かに滑り落ちた。\n天秤は即座に不均衡になり、心臓は腐った果実のように急速に崩れ、融解し、静かな黒い水たまりとなった。\nすべての飢えは消え去り、あなたは冷静さ、悔いのなさ、そして短い明晰さを手に入れた。"
  },
  Event_91485_Name = {
    Text = "ハンガー・ゲーム"
  },
  Event_91486_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91486_Desc = {
    Text = "音もなく、誰も応じない。もしかしたらただの悪戯？\n君が受話器を置いた時、何か重い感情が再び君の中に流れ込んできた。"
  },
  Event_91487_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91487_Desc = {
    Text = "カラスは消えた。\nしかし、あなたは別の夜の鏡の中に自分が立っているのを見て、このカラスを見つめている。\nそれはまだ無言で鳴き叫び、まるであなたの応答を待っているかのようだ。"
  },
  Event_91487_Name = {
    Text = "沈黙の告白"
  },
  Event_91488_ChoiceDesc1 = {
    Text = "【再観察】3枚の指令カードから1枚を選び、彫刻を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_91488_ChoiceDesc2 = {
    Text = "【抵抗を放棄する】「(Skill.Arg1)」に感染し、選択肢1で得た彫刻を交換できます。さらに1回使用可能です"
  },
  Event_91488_Desc = {
    Text = "あなたは決然と視線を移しましたが、その映像はまるで幽霊の影のようにあなたの目の前に浮かびました……\nそれは悲しい二人の舞踏でした。"
  },
  Event_91488_Name = {
    Text = "過去の影"
  },
  Event_91489_ChoiceDesc1 = {
    Text = "【享用】3枚の指令カードから1枚を選んで刻印を得る：「(EnchantConfig.Arg1)」"
  },
  Event_91489_ChoiceDesc2 = {
    Text = "【婉拒】感染「(Skill.Arg1)」、再刻印を行い、最大2回まで"
  },
  Event_91489_Desc = {
    Text = "それはドレセインがあなたたちのために苦労して調査した結果、丁寧に用意したものです。\n香辛料を加えず、腐った味はなく、ドレセインが言ったように、これは最高の食材です。\n宴はあなたのために設けられ、大脳は皿の中で静かに無言です。\n「試してみますか？」"
  },
  Event_91489_Name = {
    Text = "美食を堪能する"
  },
  Event_91490_ChoiceDesc1 = {
    Text = "【聴く】40黒章を獲得し、「(Skill.Arg2)」に感染する。選択を続ける"
  },
  Event_91490_ChoiceDesc2 = {
    Text = "【無視】25黒章を獲得し、離れる"
  },
  Event_91490_Desc = {
    Text = "それは一羽のカラス。\n骸骨のランプの上に立ち、口を開けても、何の音も発しなかった。"
  },
  Event_91490_Name = {
    Text = "沈黙の告白"
  },
  Event_91491_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91491_Desc = {
    Text = "あなたはゆっくりとそのまだ熱い心臓に手を伸ばす。それは躍動し、収縮し、やがて芳しい熱気となって消散する。\n天秤が激しく揺れ、大脳は果てしない闇に落ちる。\n満ち足りた感覚が飢えに取って代わり、あなたは熱烈さ、苦痛、そして真の記憶を悟った。"
  },
  Event_91491_Name = {
    Text = "ハンガー・ゲーム"
  },
  Event_91492_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91492_Desc = {
    Text = "あなたは頭を仰ぎ、無音の回転を迎え入れ、古代の祭祀の巡礼者のようです。\n彼らは楽しげにあなたの血肉を味わい、あなたは痛みを感じますが、同時に清明さも感じます。\n失われた自分を見つけました、死ななかった部分がついに奪われました。\n意識が戻ると、あなたは無事であることに気づきます。"
  },
  Event_91492_Name = {
    Text = "カラスの宴"
  },
  Event_91493_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91493_Desc = {
    Text = "あなたは記憶と感情のセメントで鍵穴を塞ぎ、真実はもはやあなたを誘惑できない。\nあなたが大敵に直面しているかのような様子を見て、ドレセインは口元を舐めた。\n「まだ試してみたいですか？これは守秘者様のために特別に作られた脳葉モッツァレラです。」"
  },
  Event_91493_Name = {Text = "啓示録"},
  Event_91494_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91494_Desc = {
    Text = "実はあなたはずっと、死体食らいの体験に興味があった。\n「つまり、あなたはネズミの群れに入り、その一員となる――」\nあなたは認めざるを得ない、海行者の到来があなたの頭を少し混乱させていることを。"
  },
  Event_91494_Name = {
    Text = "追放された王国"
  },
  Event_91495_ChoiceDesc1 = {
    Text = "【離れる】"
  },
  Event_91495_Desc = {
    Text = "あなたは腐敗と混乱には触れたくない。\nあなたはすでに、全ての腐朽が常態であることに慣れています。"
  },
  Event_91495_Name = {
    Text = "追放された王国"
  },
  Event_91496_ChoiceDesc1 = {
    Text = "【享用】3枚の指令カードから1枚を選んで刻印を得る：「(EnchantConfig.Arg1)」"
  },
  Event_91496_ChoiceDesc2 = {
    Text = "【婉拒】感染「(Skill.Arg1)」、再度ランダムで刻印を得る"
  },
  Event_91496_Desc = {
    Text = "デュラサインは優雅にあなたに「脳」を切り分けた。\nその甘美な味……\nその柔らかくてしっとりとした食感……\nもう一口食べたくてたまらない。"
  },
  Event_91496_Name = {
    Text = "美食を堪能する"
  },
  Event_91497_ChoiceDesc1 = {
    Text = "【私は夢を見ている】シルバークリエイション「(RelicConfig.Arg1)」を獲得します"
  },
  Event_91497_ChoiceDesc2 = {
    Text = "【これは異常だ】ゴールドクリエイション「(RelicConfig.Arg1)」を獲得し、「(Skill.Arg2)」に感染します"
  },
  Event_91497_Desc = {
    Text = "滑らかな墓碑に、ゆっくりとねじれ始める目が映し出される。\nまるで肉眼では描写できない何かのイメージを抱えているかのように、一段の記憶はあなたに属さないが、すでにあなたの目の奥のしわに深く植え付けられている。\nあなたはまばたきをしようとし、指先で拭おうとするが、その目はもはやあなたのものではなく、万華鏡のような景色を反射し始める。"
  },
  Event_91497_Name = {
    Text = "ほぼ正常"
  },
  Event_91498_ChoiceDesc1 = {
    Text = "【観察を続ける】3枚の指令カードから1枚を選び、彫刻を獲得：「(EnchantConfig.Arg1)」"
  },
  Event_91498_ChoiceDesc2 = {
    Text = "【視線を外す】「(Skill.Arg1)」に感染し、選択肢1で得た彫刻を交換できます。2回使用可能です"
  },
  Event_91498_Desc = {
    Text = "古城の湿った隅で、あなたはそのフィルムを発見した。\n映像はまるで時間の河に溺れた幻影のように、ゆっくりと固定され、時折名状しがたい巨物に膨れ上がり、時折ちらちらと光る星点に崩れ落ちる。\nあなたはその中に没入し、ひとしきりの眩暈が時間の流れを思い出させた。"
  },
  Event_91498_Name = {
    Text = "過去の影"
  },
  Event_91499_ChoiceDesc1 = {
    Text = "【凝视群星】黄金クリエイション「(RelicConfig.Arg1)」を獲得し、感染「(Skill.Arg2)」"
  },
  Event_91499_ChoiceDesc2 = {
    Text = "【目を閉じる】ランダムに2体の覚醒体を覚醒させ、「(Skill.Arg1)」に2回感染します"
  },
  Event_91499_ChoiceDesc3 = {
    Text = "【離れる】50黒章を獲得する"
  },
  Event_91499_Desc = {
    Text = "あなたは誰もいない墓地に立ち、星の存在が夜を明るい昼のように照らしています。\n時間の深海に漂う光球は言葉を発することなく、夢話のように長い回転の中で徐々に焦点を合わせています。\nそれらは忘れられた孤星を見つめています。\n彼はあなたを見つめ、すべての死と永遠を見つめています。"
  },
  Event_91499_Name = {Text = "星の夜"},
  Event_91500_ChoiceDesc1 = {
    Text = "【聴く】20のブラックシールを獲得し、「(Skill.Arg2)」に感染します"
  },
  Event_91500_ChoiceDesc2 = {
    Text = "【無視】離れる"
